function canonicalDurableStockOrderUnitPayload(value) {
    if (
        !exactKeys(value, [
            'commonLots',
            'contractKey',
            'contractUnit',
            'quantityShares',
            'schemaVersion',
        ]) ||
        value.schemaVersion !== DURABLE_STOCK_ORDER_UNIT_INTENT_SCHEMA_VERSION
    ) {
        throw new TypeError('durable stock order unit payload schema is invalid');
    }
    const contractUnit = safeInteger(
        value.contractUnit,
        'durableStockOrderUnit.contractUnit',
        { minimum: 1 },
    );
    const quantityShares = safeInteger(
        value.quantityShares,
        'durableStockOrderUnit.quantityShares',
        { minimum: 1 },
    );
    const commonLots = safeInteger(
        value.commonLots,
        'durableStockOrderUnit.commonLots',
        { minimum: 1 },
    );
    if (commonLots * contractUnit !== quantityShares) {
        throw new Error('durable stock order unit projection is not exact');
    }
    return Object.freeze({
        commonLots,
        contractKey: boundedToken(
            value.contractKey,
            'durableStockOrderUnit.contractKey',
        ),
        contractUnit,
        quantityShares,
        schemaVersion: DURABLE_STOCK_ORDER_UNIT_INTENT_SCHEMA_VERSION,
    });
}

function canonicalGoodTillIntentPayload(value) {
    if (
        !exactKeys(value, [
            'activationTradeDate',
            'conditionEvidenceHash',
            'confirmationSnapshotHash',
            'order',
            'progress',
            'schemaVersion',
            'strategyId',
        ]) ||
        value.schemaVersion !== GOOD_TILL_INTENT_SCHEMA_VERSION ||
        !exactKeys(value.order, [
            'baseShares',
            'commonLots',
            'contractKey',
            'contractUnit',
            'limitPrice',
            'orderCond',
            'orderLot',
            'policyRevision',
            'priceType',
            'side',
            'timeInForce',
        ]) ||
        !exactKeys(value.progress, [
            'confirmedFilledSharesBefore',
            'remainingTargetSharesAfter',
            'targetShares',
        ])
    ) {
        throw new TypeError('good-till intent payload schema is invalid');
    }
    const order = value.order;
    const baseShares = safeInteger(order.baseShares, 'goodTill.order.baseShares', {
        minimum: 1,
    });
    const commonLots = safeInteger(order.commonLots, 'goodTill.order.commonLots', {
        minimum: 1,
    });
    const contractUnit = safeInteger(
        order.contractUnit,
        'goodTill.order.contractUnit',
        { minimum: 1 },
    );
    if (
        order.side !== 'Buy' ||
        order.orderCond !== 'Cash' ||
        order.orderLot !== 'Common' ||
        order.priceType !== 'LMT' ||
        !['ROD', 'IOC'].includes(order.timeInForce) ||
        baseShares !== commonLots * contractUnit
    ) {
        throw new Error('good-till order policy or unit projection is invalid');
    }
    brokerPriceMinorUnits(order.limitPrice, 'goodTill.order.limitPrice');
    const targetShares = safeInteger(
        value.progress.targetShares,
        'goodTill.progress.targetShares',
        { minimum: 1 },
    );
    const confirmedFilledSharesBefore = safeInteger(
        value.progress.confirmedFilledSharesBefore,
        'goodTill.progress.confirmedFilledSharesBefore',
    );
    const remainingTargetSharesAfter = safeInteger(
        value.progress.remainingTargetSharesAfter,
        'goodTill.progress.remainingTargetSharesAfter',
    );
    if (
        confirmedFilledSharesBefore + baseShares +
            remainingTargetSharesAfter !==
            targetShares ||
        baseShares > targetShares
    ) {
        throw new Error('good-till intent target/remainder projection is invalid');
    }
    return Object.freeze({
        ...value,
        activationTradeDate: taipeiTradeDate(value.activationTradeDate),
        conditionEvidenceHash: sha256Digest(
            value.conditionEvidenceHash,
            'goodTill.conditionEvidenceHash',
        ),
        confirmationSnapshotHash: sha256Digest(
            value.confirmationSnapshotHash,
            'goodTill.confirmationSnapshotHash',
        ),
        strategyId: boundedToken(value.strategyId, 'goodTill.strategyId'),
        order: Object.freeze({
            ...order,
            baseShares,
            commonLots,
            contractUnit,
            contractKey: boundedToken(order.contractKey, 'goodTill.order.contractKey'),
            policyRevision: boundedToken(
                order.policyRevision,
                'goodTill.order.policyRevision',
            ),
        }),
        progress: Object.freeze({
            targetShares,
            confirmedFilledSharesBefore,
            remainingTargetSharesAfter,
        }),
    });
}

function canonicalParentChildIntentPayload(value) {
    if (
        !exactKeys(value, [
            'activationTradeDate',
            'childPositionLineageId',
            'conditionEvidenceHash',
            'confirmationSnapshotHash',
            'leg',
            'order',
            'parentSettlementHash',
            'schemaVersion',
            'strategyId',
        ]) ||
        value.schemaVersion !== PARENT_CHILD_INTENT_SCHEMA_VERSION ||
        !['parent', 'child'].includes(value.leg) ||
        !exactKeys(value.order, [
            'baseShares',
            'commonLots',
            'contractKey',
            'contractUnit',
            'limitPrice',
            'orderCond',
            'orderLot',
            'policyRevision',
            'priceType',
            'side',
            'timeInForce',
        ])
    ) {
        throw new TypeError('parent-child intent payload schema is invalid');
    }
    const order = value.order;
    const contractUnit = safeInteger(
        order.contractUnit,
        'parentChild.order.contractUnit',
        { minimum: 1 },
    );
    const baseShares = safeInteger(order.baseShares, 'parentChild.order.baseShares', {
        minimum: 1,
    });
    const commonLots = safeInteger(
        order.commonLots,
        'parentChild.order.commonLots',
        { minimum: 1 },
    );
    if (
        order.orderCond !== 'Cash' ||
        order.orderLot !== 'Common' ||
        order.priceType !== 'LMT' ||
        !['ROD', 'IOC'].includes(order.timeInForce) ||
        baseShares !== commonLots * contractUnit ||
        (value.leg === 'parent' && order.side !== 'Buy') ||
        (value.leg === 'child' && order.side !== 'Sell') ||
        (value.leg === 'parent' &&
            (value.parentSettlementHash !== null ||
                value.childPositionLineageId !== null)) ||
        (value.leg === 'child' &&
            (typeof value.parentSettlementHash !== 'string' ||
                typeof value.childPositionLineageId !== 'string'))
    ) {
        throw new Error('parent-child intent order or lineage is invalid');
    }
    brokerPriceMinorUnits(order.limitPrice, 'parentChild.order.limitPrice');
    return Object.freeze({
        ...value,
        activationTradeDate: taipeiTradeDate(value.activationTradeDate),
        childPositionLineageId:
            value.childPositionLineageId === null
                ? null
                : boundedToken(
                      value.childPositionLineageId,
                      'parentChild.childPositionLineageId',
                  ),
        conditionEvidenceHash: sha256Digest(
            value.conditionEvidenceHash,
            'parentChild.conditionEvidenceHash',
        ),
        confirmationSnapshotHash: sha256Digest(
            value.confirmationSnapshotHash,
            'parentChild.confirmationSnapshotHash',
        ),
        order: Object.freeze({
            ...order,
            baseShares,
            commonLots,
            contractKey: boundedToken(
                order.contractKey,
                'parentChild.order.contractKey',
            ),
            contractUnit,
            policyRevision: boundedToken(
                order.policyRevision,
                'parentChild.order.policyRevision',
            ),
        }),
        parentSettlementHash:
            value.parentSettlementHash === null
                ? null
                : sha256Digest(
                      value.parentSettlementHash,
                      'parentChild.parentSettlementHash',
                  ),
        strategyId: boundedToken(value.strategyId, 'parentChild.strategyId'),
    });
}
