function verifyRepository(database) {
    const integrity = database.prepare('PRAGMA integrity_check').get()?.integrity_check;
    if (integrity !== 'ok') throw new Error(`repository integrity failed: ${integrity}`);
    const tables = new Set(
        database
            .prepare("SELECT name FROM sqlite_master WHERE type='table'")
            .all()
            .map((row) => row.name),
    );
    for (const required of REQUIRED_SMART_ORDER_TABLES) {
        if (!tables.has(required)) throw new Error(`repository table missing: ${required}`);
    }
    const foreignKeys = database.prepare('PRAGMA foreign_keys').get()?.foreign_keys;
    const synchronous = database.prepare('PRAGMA synchronous').get()?.synchronous;
    const busyTimeout = database.prepare('PRAGMA busy_timeout').get()?.timeout;
    const trustedSchema = database.prepare('PRAGMA trusted_schema').get()?.trusted_schema;
    const journalMode = database.prepare('PRAGMA journal_mode').get()?.journal_mode;
    if (
        foreignKeys !== 1 ||
        synchronous !== 2 ||
        busyTimeout !== BUSY_TIMEOUT_MS ||
        trustedSchema !== 0 ||
        journalMode !== 'wal'
    ) {
        throw new Error('repository safety PRAGMA mismatch');
    }
    if (database.prepare('PRAGMA foreign_key_check').get()) {
        throw new Error('repository foreign-key integrity failed');
    }
    const exposureHeadMismatch = database.prepare(`
        SELECT account.account_broker_ref, account.account_id_ref
          FROM exposure_account_arbiter_heads AS account
          LEFT JOIN exposure_identity_arbiter_heads AS identity
            ON identity.identity_group_id=account.identity_group_id
         WHERE identity.identity_group_id IS NULL
            OR account.policy_revision<>identity.policy_revision
            OR account.policy_hash<>identity.policy_hash
            OR account.reserved_dimensions_json<>identity.reserved_dimensions_json
         LIMIT 1
    `).get();
    if (exposureHeadMismatch) {
        throw new Error('account and identity exposure head integrity failed');
    }
    for (const table of [
        'exposure_identity_arbiter_heads',
        'exposure_account_arbiter_heads',
    ]) {
        for (const row of database.prepare(
            `SELECT reserved_dimensions_json FROM ${table}`,
        ).all()) {
            parseExposureHeadDimensions(row, table);
        }
    }
    const visibilityBindingMismatch = database.prepare(`
        SELECT bindings.exit_claim_id
          FROM exit_claim_visibility_bindings AS bindings
          JOIN exit_claims AS claims
            ON claims.exit_claim_id=bindings.exit_claim_id
         WHERE bindings.account_broker_ref<>claims.account_broker_ref
            OR bindings.account_id_ref<>claims.account_id_ref
            OR bindings.contract_key<>claims.contract_key
            OR (bindings.binding_kind='external_projection'
                AND (claims.external_lineage<>1 OR claims.intent_id IS NOT NULL))
            OR (bindings.binding_kind='internal_prepared'
                AND (claims.external_lineage<>0 OR claims.intent_id IS NULL))
         LIMIT 1
    `).get();
    if (visibilityBindingMismatch) {
        throw new Error('ExitClaim visibility binding integrity failed');
    }
    const correlationScopeMismatch = database
        .prepare(`
            SELECT correlation_id
              FROM broker_correlations AS correlation
              JOIN order_intents AS intent
                ON intent.intent_id=correlation.intent_id
             WHERE correlation.account_broker_ref<>intent.account_broker_ref
                OR correlation.account_id_ref<>intent.account_id_ref
                OR correlation.trade_date<>intent.trade_date
                OR correlation.contract_key<>intent.contract_key
                OR correlation.side<>intent.side
                OR (
                    correlation.broker_order_id IS NOT NULL AND NOT EXISTS (
                        SELECT 1 FROM broker_orders AS broker_order
                         WHERE broker_order.broker_order_id=correlation.broker_order_id
                           AND broker_order.intent_id=correlation.intent_id
                    )
                )
             LIMIT 1
        `)
        .get();
    if (correlationScopeMismatch) {
        throw new Error('broker correlation fixed scope integrity failed');
    }
    const correlationIdentifierMismatch = database
        .prepare(`
            WITH expected AS (
                SELECT account_broker_ref, account_id_ref, trade_date,
                       contract_key, side, 'tradeId' AS identifier_kind,
                       trade_id AS identifier_value, intent_id, correlation_id
                  FROM broker_correlations WHERE trade_id IS NOT NULL
                UNION ALL
                SELECT account_broker_ref, account_id_ref, trade_date,
                       contract_key, side, 'orderId', order_id, intent_id,
                       correlation_id
                  FROM broker_correlations WHERE order_id IS NOT NULL
                UNION ALL
                SELECT account_broker_ref, account_id_ref, trade_date,
                       contract_key, side, 'dealId', deal_id, intent_id,
                       correlation_id
                  FROM broker_correlations WHERE deal_id IS NOT NULL
                UNION ALL
                SELECT account_broker_ref, account_id_ref, trade_date,
                       contract_key, side, 'seqno', seqno, intent_id,
                       correlation_id
                  FROM broker_correlations WHERE seqno IS NOT NULL
                UNION ALL
                SELECT account_broker_ref, account_id_ref, trade_date,
                       contract_key, side, 'ordno', ordno, intent_id,
                       correlation_id
                  FROM broker_correlations WHERE ordno IS NOT NULL
                UNION ALL
                SELECT account_broker_ref, account_id_ref, trade_date,
                       contract_key, side, 'exchangeSequence',
                       exchange_sequence, intent_id, correlation_id
                  FROM broker_correlations WHERE exchange_sequence IS NOT NULL
            )
            SELECT expected.correlation_id
              FROM expected
              LEFT JOIN broker_correlation_identifiers AS identifier
                ON identifier.account_broker_ref=expected.account_broker_ref
               AND identifier.account_id_ref=expected.account_id_ref
               AND identifier.trade_date=expected.trade_date
               AND identifier.contract_key=expected.contract_key
               AND identifier.side=expected.side
               AND identifier.identifier_kind=expected.identifier_kind
               AND identifier.identifier_value=expected.identifier_value
               AND identifier.intent_id=expected.intent_id
               AND identifier.correlation_id=expected.correlation_id
             WHERE identifier.correlation_id IS NULL
            UNION ALL
            SELECT identifier.correlation_id
              FROM broker_correlation_identifiers AS identifier
              JOIN broker_correlations AS correlation
                ON correlation.correlation_id=identifier.correlation_id
             WHERE identifier.account_broker_ref<>correlation.account_broker_ref
                OR identifier.account_id_ref<>correlation.account_id_ref
                OR identifier.trade_date<>correlation.trade_date
                OR identifier.contract_key<>correlation.contract_key
                OR identifier.side<>correlation.side
                OR identifier.intent_id<>correlation.intent_id
                OR CASE identifier.identifier_kind
                    WHEN 'tradeId' THEN correlation.trade_id
                    WHEN 'orderId' THEN correlation.order_id
                    WHEN 'dealId' THEN correlation.deal_id
                    WHEN 'seqno' THEN correlation.seqno
                    WHEN 'ordno' THEN correlation.ordno
                    WHEN 'exchangeSequence' THEN correlation.exchange_sequence
                END IS NULL
                OR identifier.identifier_value<>CASE identifier.identifier_kind
                    WHEN 'tradeId' THEN correlation.trade_id
                    WHEN 'orderId' THEN correlation.order_id
                    WHEN 'dealId' THEN correlation.deal_id
                    WHEN 'seqno' THEN correlation.seqno
                    WHEN 'ordno' THEN correlation.ordno
                    WHEN 'exchangeSequence' THEN correlation.exchange_sequence
                END
             LIMIT 1
        `)
        .get();
    if (correlationIdentifierMismatch) {
        throw new Error('broker correlation identifier projection integrity failed');
    }
    for (const correlation of database
        .prepare(`
            SELECT correlation_id, canonical_key_hash,
                   account_broker_ref, account_id_ref, trade_date,
                   contract_key, side, trade_id, order_id, deal_id,
                   seqno, ordno, exchange_sequence, custom_field
              FROM broker_correlations
        `)
        .all()) {
        try {
            const canonical = {
                accountBrokerRef: boundedToken(
                    correlation.account_broker_ref,
                    'broker correlation accountBrokerRef',
                ),
                accountIdRef: boundedToken(
                    correlation.account_id_ref,
                    'broker correlation accountIdRef',
                ),
                tradeDate: taipeiTradeDate(correlation.trade_date),
                contractKey: boundedToken(
                    correlation.contract_key,
                    'broker correlation contractKey',
                ),
                side: boundedToken(correlation.side, 'broker correlation side'),
                tradeId:
                    correlation.trade_id === null
                        ? undefined
                        : boundedToken(
                              correlation.trade_id,
                              'broker correlation tradeId',
                          ),
                orderId:
                    correlation.order_id === null
                        ? undefined
                        : boundedToken(
                              correlation.order_id,
                              'broker correlation orderId',
                          ),
                dealId:
                    correlation.deal_id === null
                        ? undefined
                        : boundedToken(
                              correlation.deal_id,
                              'broker correlation dealId',
                          ),
                seqno:
                    correlation.seqno === null
                        ? undefined
                        : boundedToken(
                              correlation.seqno,
                              'broker correlation seqno',
                          ),
                ordno:
                    correlation.ordno === null
                        ? undefined
                        : boundedToken(
                              correlation.ordno,
                              'broker correlation ordno',
                          ),
                exchangeSequence:
                    correlation.exchange_sequence === null
                        ? undefined
                        : boundedToken(
                              correlation.exchange_sequence,
                              'broker correlation exchangeSequence',
                          ),
            };
            if (!['Buy', 'Sell'].includes(canonical.side)) {
                throw new TypeError('broker correlation side is invalid');
            }
            if (
                BROKER_CORRELATION_IDENTIFIER_KINDS.every(
                    (kind) => canonical[kind] === undefined,
                )
            ) {
                throw new TypeError(
                    'broker correlation needs at least one identifier',
                );
            }
            if (
                correlation.custom_field !== null &&
                (typeof correlation.custom_field !== 'string' ||
                    !/^[A-Za-z0-9]{1,6}$/.test(correlation.custom_field))
            ) {
                throw new TypeError('broker correlation customField is invalid');
            }
            if (
                correlation.canonical_key_hash !==
                hashCanonicalCorrelation(canonical)
            ) {
                throw new Error('broker correlation canonical key changed');
            }
        } catch {
            throw new Error('broker correlation canonical integrity failed');
        }
    }
    const invalidJournalKind = database
        .prepare(`
            SELECT entity_kind FROM event_journal
             WHERE entity_kind NOT IN (${SMART_ORDER_JOURNAL_ENTITY_KINDS.map(
                 () => '?',
             ).join(',')})
             LIMIT 1
        `)
        .get(...SMART_ORDER_JOURNAL_ENTITY_KINDS);
    if (invalidJournalKind) {
        throw new Error('repository journal entity kind is not canonical');
    }
    const journalRows = Number(
        database.prepare('SELECT COUNT(*) AS count FROM event_journal').get()?.count,
    );
    if (
        !Number.isSafeInteger(journalRows) ||
        journalRows < 0 ||
        journalRows > configuredEventJournalMaxRows
    ) {
        throw new Error('repository journal exceeds its bounded capacity');
    }
}

function nextJournalSequence(database) {
    const row = database
        .prepare("SELECT value FROM repository_meta WHERE key='journal_local_sequence'")
        .get();
    const current = Number(row?.value);
    if (!Number.isSafeInteger(current) || current < 0 || current >= Number.MAX_SAFE_INTEGER) {
        throw new Error('journal local sequence is invalid');
    }
    const next = current + 1;
    database
        .prepare("UPDATE repository_meta SET value=? WHERE key='journal_local_sequence'")
        .run(String(next));
    return next;
}

function insertJournalEvent(database, event, entityRevision) {
    const entityKind = boundedToken(event.entityKind, 'event.entityKind');
    if (!SMART_ORDER_JOURNAL_ENTITY_KINDS.includes(entityKind)) {
        throw new TypeError('event.entityKind must use the canonical allowlist');
    }
    const journalRows = Number(
        database.prepare('SELECT COUNT(*) AS count FROM event_journal').get()?.count,
    );
    if (
        !Number.isSafeInteger(journalRows) ||
        journalRows < 0 ||
        journalRows >= configuredEventJournalMaxRows
    ) {
        throw new Error('event journal capacity exceeded');
    }
    const exchangeEpochMs =
        event.exchangeEpochMs === undefined
            ? null
            : safeInteger(event.exchangeEpochMs, 'event.exchangeEpochMs');
    const brokerEpochMs =
        event.brokerEpochMs === undefined
            ? null
            : safeInteger(event.brokerEpochMs, 'event.brokerEpochMs');
    const receiveEpochMs = safeInteger(
        event.receiveEpochMs,
        'event.receiveEpochMs',
    );
    if (
        (exchangeEpochMs !== null && exchangeEpochMs > receiveEpochMs) ||
        (brokerEpochMs !== null && brokerEpochMs > receiveEpochMs) ||
        (exchangeEpochMs !== null &&
            brokerEpochMs !== null &&
            exchangeEpochMs > brokerEpochMs)
    ) {
        throw new TypeError(
            'event exchange/broker/receive timestamps are not monotonic',
        );
    }
    const localSequence = nextJournalSequence(database);
    database
        .prepare(`
            INSERT INTO event_journal(
                event_id, entity_kind, entity_id, reason_code,
                exchange_epoch_ms, broker_epoch_ms, receive_epoch_ms,
                local_monotonic_sequence, entity_revision, payload_hash,
                summary_code, created_at_epoch_ms
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `)
        .run(
            boundedToken(event.eventId, 'event.eventId'),
            entityKind,
            boundedToken(event.entityId, 'event.entityId'),
            boundedToken(event.reasonCode, 'event.reasonCode'),
            exchangeEpochMs,
            brokerEpochMs,
            receiveEpochMs,
            localSequence,
            safeInteger(entityRevision, 'event.entityRevision'),
            sha256Digest(event.payloadHash, 'event.payloadHash'),
            boundedToken(event.summaryCode, 'event.summaryCode'),
            safeInteger(event.createdAtEpochMs, 'event.createdAtEpochMs'),
        );
    return localSequence;
}

function rejectCallerSuppliedJournalEvent(input) {
    if (input.event !== undefined) {
        throw new TypeError(
            'caller-supplied journal events are not accepted; repository transitions journal internally',
        );
    }
}

function insertTransitionJournalEvent(
    database,
    {
        entityKind,
        entityId,
        revision,
        reasonCode,
        summaryCode,
        nowEpochMs,
        payloadHash,
        eventSuffix,
        exchangeEpochMs,
        brokerEpochMs,
    },
) {
    insertJournalEvent(
        database,
        {
            eventId: `${entityKind}:${entityId}:${eventSuffix}:${revision}`,
            entityKind,
            entityId,
            reasonCode,
            exchangeEpochMs,
            brokerEpochMs,
            receiveEpochMs: nowEpochMs,
            payloadHash,
            summaryCode,
            createdAtEpochMs: nowEpochMs,
        },
        revision,
    );
}

function setRepositoryMeta(database, key, value) {
    database
        .prepare(`
            INSERT INTO repository_meta(key, value) VALUES (?, ?)
            ON CONFLICT(key) DO UPDATE SET value=excluded.value
        `)
        .run(key, value);
}

function deleteRepositoryMeta(database, key) {
    database.prepare('DELETE FROM repository_meta WHERE key=?').run(key);
}

function repositoryMetaValue(database, key) {
    return database
        .prepare('SELECT value FROM repository_meta WHERE key=?')
        .get(key)?.value;
}

function loadAuthenticatedIdentityKey() {
    if (typeof identityKeyPath !== 'string' || !path.isAbsolute(identityKeyPath)) {
        throw new Error('identity key path is invalid');
    }
    const metadata = exactPrivateRegularFile(
        identityKeyPath,
        'authenticated identity key',
    );
    if (metadata.size !== 32) {
        throw new Error('authenticated identity key must contain exactly 32 bytes');
    }
    identityKeyBytes = readFileSync(identityKeyPath);
    identityKeyFingerprintSha256 = `sha256:${createHash('sha256')
        .update(identityKeyBytes)
        .digest('hex')}`;
}

function initializeAuthenticatedIdentityKeyBinding(database) {
    const stored = repositoryMetaValue(
        database,
        IDENTITY_KEY_FINGERPRINT_META_KEY,
    );
    if (stored === undefined) {
        const legacyActive = database
            .prepare(`
                SELECT 1 FROM strategies
                 WHERE state!='draft'
                 LIMIT 1
            `)
            .get();
        if (legacyActive && !testOnlyAllowUnverifiedIdentitySeed) {
            throw new Error(
                'authenticated identity key binding is missing for an existing strategy repository',
            );
        }
        transaction(database, () => {
            if (
                repositoryMetaValue(
                    database,
                    IDENTITY_KEY_FINGERPRINT_META_KEY,
                ) !== undefined
            ) {
                throw new Error('authenticated identity key binding changed concurrently');
            }
            setRepositoryMeta(
                database,
                IDENTITY_KEY_FINGERPRINT_META_KEY,
                identityKeyFingerprintSha256,
            );
        });
        return;
    }
    if (stored !== identityKeyFingerprintSha256) {
        throw new Error(
            'authenticated identity key was replaced or rotated without reconciliation',
        );
    }
}

function identityAccountBindingKey(accountBrokerRef, accountIdRef) {
    return `${IDENTITY_ACCOUNT_BINDING_META_PREFIX}${createHash('sha256')
        .update(`${accountBrokerRef}\u001f${accountIdRef}`)
        .digest('hex')}`;
}

function persistIdentityAccountBinding(database, admission) {
    const conflictingStrategy = database
        .prepare(`
            SELECT identity_group_id
              FROM strategies
             WHERE account_broker_ref=? AND account_id_ref=?
               AND state!='draft' AND identity_group_id<>?
             LIMIT 1
        `)
        .get(
            admission.accountBrokerRef,
            admission.accountIdRef,
            admission.identityGroupId,
        );
    if (conflictingStrategy) {
        throw new Error(
            'fixed account maps to a conflicting authenticated identity group',
        );
    }
    const key = identityAccountBindingKey(
        admission.accountBrokerRef,
        admission.accountIdRef,
    );
    const binding = {
        accountScopeSha256: `sha256:${createHash('sha256')
            .update(
                `${admission.accountBrokerRef}\u001f${admission.accountIdRef}`,
            )
            .digest('hex')}`,
        identityGroupId: admission.identityGroupId,
        mappingRevision: admission.mappingRevision,
        principalEvidenceHash: admission.principalEvidenceHash,
    };
    const next = canonicalJson(
        binding,
        'authenticated identity account binding',
    );
    const current = repositoryMetaValue(database, key);
    if (current !== undefined) {
        let parsed;
        try {
            parsed = JSON.parse(current);
        } catch {
            throw new Error('authenticated identity account binding is invalid');
        }
        if (parsed.identityGroupId !== binding.identityGroupId) {
            throw new Error(
                'fixed account maps to a conflicting authenticated identity group',
            );
        }
        if (
            parsed.accountScopeSha256 !== binding.accountScopeSha256 ||
            parsed.mappingRevision !== binding.mappingRevision ||
            parsed.principalEvidenceHash !== binding.principalEvidenceHash
        ) {
            throw new Error(
                'authenticated identity mapping evidence changed; reconciliation required',
            );
        }
        if (current !== next) {
            throw new Error(
                'authenticated identity account binding is not canonical',
            );
        }
        return;
    }
    setRepositoryMeta(database, key, next);
}

function verifyAuthenticatedIdentityAdmission(database, value, expected) {
    if (
        !exactKeys(value, [
            'accountBrokerRef',
            'accountIdRef',
            'admissionHmacSha256',
            'identityGroupId',
            'identityKeyFingerprintSha256',
            'issuedAtEpochMs',
            'mappingRevision',
            'principalEvidenceHash',
            'schemaVersion',
        ]) ||
        value.schemaVersion !==
            SMART_ORDER_AUTHENTICATED_IDENTITY_ADMISSION_SCHEMA_VERSION
    ) {
        throw new TypeError('authenticated identity admission schema is invalid');
    }
    const admission = Object.freeze({
        schemaVersion: value.schemaVersion,
        accountBrokerRef: boundedToken(
            value.accountBrokerRef,
            'identityAdmission.accountBrokerRef',
        ),
        accountIdRef: boundedToken(
            value.accountIdRef,
            'identityAdmission.accountIdRef',
        ),
        identityGroupId: boundedToken(
            value.identityGroupId,
            'identityAdmission.identityGroupId',
        ),
        identityKeyFingerprintSha256: sha256Digest(
            value.identityKeyFingerprintSha256,
            'identityAdmission.identityKeyFingerprintSha256',
        ),
        principalEvidenceHash: sha256Digest(
            value.principalEvidenceHash,
            'identityAdmission.principalEvidenceHash',
        ),
        mappingRevision: boundedToken(
            value.mappingRevision,
            'identityAdmission.mappingRevision',
        ),
        issuedAtEpochMs: safeInteger(
            value.issuedAtEpochMs,
            'identityAdmission.issuedAtEpochMs',
        ),
    });
    if (
        admission.accountBrokerRef !== expected.accountBrokerRef ||
        admission.accountIdRef !== expected.accountIdRef ||
        admission.identityGroupId !== expected.identityGroupId ||
        admission.identityKeyFingerprintSha256 !==
            identityKeyFingerprintSha256
    ) {
        throw new Error(
            'authenticated identity admission does not match its durable scope',
        );
    }
    const signature = boundedToken(
        value.admissionHmacSha256,
        'identityAdmission.admissionHmacSha256',
    );
    if (!/^hmac-sha256:[0-9a-f]{64}$/.test(signature)) {
        throw new TypeError('authenticated identity admission HMAC is invalid');
    }
    const expectedSignature = createHmac('sha256', identityKeyBytes)
        .update(canonicalJson(admission, 'authenticated identity admission'))
        .digest();
    const providedSignature = Buffer.from(
        signature.slice('hmac-sha256:'.length),
        'hex',
    );
    if (
        providedSignature.length !== expectedSignature.length ||
        !timingSafeEqual(providedSignature, expectedSignature)
    ) {
        throw new Error('authenticated identity admission HMAC mismatch');
    }
    persistIdentityAccountBinding(database, admission);
    return admission;
}

function seedUnverifiedIdentityForTest(database, expected) {
    if (
        !testOnlyAllowUnverifiedIdentitySeed ||
        process.env.VITEST !== 'true'
    ) {
        throw new Error(
            'broker-authenticated identity admission is required',
        );
    }
    const admission = Object.freeze({
        accountBrokerRef: expected.accountBrokerRef,
        accountIdRef: expected.accountIdRef,
        identityGroupId: expected.identityGroupId,
        mappingRevision: 'test-only-unverified-seed/1',
        principalEvidenceHash: `sha256:${'0'.repeat(64)}`,
    });
    persistIdentityAccountBinding(database, admission);
    return admission;
}

function authenticatedIdentityAdmission(database, value, expected) {
    return value === undefined
        ? seedUnverifiedIdentityForTest(database, expected)
        : verifyAuthenticatedIdentityAdmission(database, value, expected);
}

function identityStrategyCount(database, identityGroupId) {
    const row = database
        .prepare(`
            SELECT COUNT(DISTINCT strategies.strategy_id) AS count
              FROM strategies
             WHERE strategies.identity_group_id=?
               AND (
                    strategies.state NOT IN ('completed','cancelled','expired')
                    OR EXISTS (
                        SELECT 1 FROM activations
                         WHERE activations.strategy_id=strategies.strategy_id
                           AND activations.state NOT IN (
                               'filled','cancelled','failed','missed'
                           )
                    )
                    OR EXISTS (
                        SELECT 1 FROM order_intents
                         WHERE order_intents.strategy_id=strategies.strategy_id
                           AND order_intents.state NOT IN (
                               'terminal','cancelled_proven_unsent'
                           )
                    )
                    OR EXISTS (
                        SELECT 1 FROM broker_orders
                        JOIN order_intents AS broker_intents
                          ON broker_intents.intent_id=broker_orders.intent_id
                         WHERE broker_intents.strategy_id=strategies.strategy_id
                           AND broker_orders.state NOT IN (
                               'filled','cancelled','failed','inactive'
                           )
                    )
                    OR EXISTS (
                        SELECT 1 FROM pending_protection_commitments
                         WHERE pending_protection_commitments.strategy_id=
                                   strategies.strategy_id
                           AND pending_protection_commitments.state NOT IN (
                               'materialized','zero_fill_terminal',
                               'released_pre_dispatch','released_manual'
                           )
                    )
                    OR EXISTS (
                        SELECT 1 FROM protection_obligations
                         WHERE protection_obligations.strategy_id=
                                   strategies.strategy_id
                           AND protection_obligations.state NOT IN (
                               'fulfilled','zero_fill_terminal','released_manual'
                           )
                    )
                    OR EXISTS (
                        SELECT 1 FROM entry_exposure_reservations
                         WHERE entry_exposure_reservations.strategy_id=
                                   strategies.strategy_id
                           AND entry_exposure_reservations.state NOT IN (
                               'consumed','released'
                           )
                    )
                    OR EXISTS (
                        SELECT 1 FROM exit_claims
                        JOIN protection_obligations AS claim_obligations
                          ON claim_obligations.obligation_id=exit_claims.obligation_id
                         WHERE claim_obligations.strategy_id=strategies.strategy_id
                           AND exit_claims.state NOT IN ('consumed','released')
                    )
               )
        `)
        .get(identityGroupId);
    return safeInteger(Number(row?.count ?? 0), 'identity strategy count');
}

function assertAuthenticatedIdentityStrategyCapacity(
    database,
    identityGroupId,
    { prospectiveStrategyId } = {},
) {
    const count = identityStrategyCount(database, identityGroupId);
    const alreadyCounted = prospectiveStrategyId
        ? database
              .prepare(`
                  SELECT 1 FROM strategies
                   WHERE strategy_id=? AND identity_group_id=?
                     AND state NOT IN ('completed','cancelled','expired')
              `)
              .get(prospectiveStrategyId, identityGroupId)
        : undefined;
    const projected = count + (prospectiveStrategyId && !alreadyCounted ? 1 : 0);
    if (projected > SMART_ORDER_IDENTITY_LOCAL_STRATEGY_LIMIT) {
        throw new Error(
            'authenticated identity local strategy limit of 20 is exhausted',
        );
    }
    return Object.freeze({ count, projected });
}

function lifecycleMetaRevision(database, key, { missing = 0 } = {}) {
    const value = repositoryMetaValue(database, key);
    if (value === undefined) return missing;
    if (!/^(?:0|[1-9]\d*)$/.test(value)) {
        throw new Error('lifecycle side-effect revision metadata is invalid');
    }
    return safeInteger(Number(value), 'lifecycle side-effect revision');
}

function currentLifecycleSideEffectRevision(database) {
    return lifecycleMetaRevision(
        database,
        LIFECYCLE_SIDE_EFFECT_REVISION_META_KEY,
    );
}

function advanceLifecycleSideEffectRevision(database) {
    const current = currentLifecycleSideEffectRevision(database);
    if (current === Number.MAX_SAFE_INTEGER) {
        throw new Error('lifecycle side-effect revision is exhausted');
    }
    const next = current + 1;
    setRepositoryMeta(
        database,
        LIFECYCLE_SIDE_EFFECT_REVISION_META_KEY,
        String(next),
    );
    return next;
}

function bindLifecycleReconciliationToCurrentSideEffects(database) {
    const revision = currentLifecycleSideEffectRevision(database);
    setRepositoryMeta(
        database,
        LIFECYCLE_RECONCILED_SIDE_EFFECT_REVISION_META_KEY,
        String(revision),
    );
    return revision;
}

function lifecycleReconciliationCoversCurrentSideEffects(database) {
    const reconciled = lifecycleMetaRevision(
        database,
        LIFECYCLE_RECONCILED_SIDE_EFFECT_REVISION_META_KEY,
        { missing: -1 },
    );
    return reconciled === currentLifecycleSideEffectRevision(database);
}

function lifecycleMutationFenceOperation(database) {
    const value = repositoryMetaValue(
        database,
        LIFECYCLE_MUTATION_FENCE_META_KEY,
    );
    if (value === undefined) return undefined;
    return runtimeLifecycleOperation(value);
}

const LIFECYCLE_FENCED_REPOSITORY_METHODS = new Set([
    'insertStrategy',
    'createDraftStrategy',
    'replaceDraftStrategy',
    'resumeStrategy',
    'requestBrokerOrderCancellation',
    'requestBrokerOrderQuantityReduction',
    'copyStrategyToDraft',
    'prepareIntent',
    'rearmPreparedIntent',
    'markIntentDispatching',
    'prepareGateProbeSafetyEnvelope',
    'consumeAuthority',
]);

const LIFECYCLE_FENCED_REPLAY_MUTATION_KINDS = new Set([
    'create',
    'update',
    'resume',
    'cancel_broker_order',
    'update_broker_order',
    'copy',
]);

function repositoryMethodCreatesLifecycleBlocker(method, payload) {
    if (LIFECYCLE_FENCED_REPOSITORY_METHODS.has(method)) return true;
    return Boolean(
        method === 'executeReplayProtectedStrategyMutation' &&
            LIFECYCLE_FENCED_REPLAY_MUTATION_KINDS.has(
                payload?.mutation?.kind,
            ),
    );
}

function assertLifecycleMutationFenceAllows(database, method, payload) {
    const operation = lifecycleMutationFenceOperation(database);
    if (
        operation === undefined ||
        !repositoryMethodCreatesLifecycleBlocker(method, payload)
    ) {
        return;
    }
    const error = new Error(
        `repository mutation is fenced by lifecycle operation ${operation}`,
    );
    error.name = 'RuntimeLifecycleMutationFencedError';
    throw error;
}

function initialKillSwitchArbiterState() {
    return Object.freeze({
        schemaVersion: KILL_SWITCH_ARBITER_SCHEMA_VERSION,
        arbiterRevision: 0,
        switches: Object.freeze(
            Object.fromEntries(
                KILL_SWITCH_NAMES.map((name) => [
                    name,
                    Object.freeze({
                        enabled: false,
                        revision: 0,
                        updatedAtEpochMs: 0,
                        reasonCode: 'initial_disabled',
                    }),
                ]),
            ),
        ),
    });
}

function validateKillSwitchArbiterState(value) {
    if (
        !exactKeys(value, ['schemaVersion', 'arbiterRevision', 'switches']) ||
        value.schemaVersion !== KILL_SWITCH_ARBITER_SCHEMA_VERSION ||
        !exactKeys(value.switches, KILL_SWITCH_NAMES)
    ) {
        throw new Error('kill switch arbiter metadata schema is invalid');
    }
    const arbiterRevision = safeInteger(
        value.arbiterRevision,
        'kill switch arbiterRevision',
    );
    const switches = {};
    for (const name of KILL_SWITCH_NAMES) {
        const current = value.switches[name];
        if (
            !exactKeys(current, [
                'enabled',
                'revision',
                'updatedAtEpochMs',
                'reasonCode',
            ]) ||
            typeof current.enabled !== 'boolean'
        ) {
            throw new Error(`kill switch ${name} metadata is invalid`);
        }
        const revision = safeInteger(
            current.revision,
            `kill switch ${name}.revision`,
        );
        if (revision > arbiterRevision) {
            throw new Error(`kill switch ${name} revision exceeds its arbiter`);
        }
        const reasonCode = boundedToken(
            current.reasonCode,
            `kill switch ${name}.reasonCode`,
            80,
        );
        if (!KILL_SWITCH_STORED_REASON_CODE_SET.has(reasonCode)) {
            throw new Error(
                `kill switch ${name} reason code is not allowlisted`,
            );
        }
        switches[name] = Object.freeze({
            enabled: current.enabled,
            revision,
            updatedAtEpochMs: safeInteger(
                current.updatedAtEpochMs,
                `kill switch ${name}.updatedAtEpochMs`,
            ),
            reasonCode,
        });
    }
    return Object.freeze({
        schemaVersion: KILL_SWITCH_ARBITER_SCHEMA_VERSION,
        arbiterRevision,
        switches: Object.freeze(switches),
    });
}

function initializeKillSwitchArbiter(database, { allowInitialize }) {
    const expected = repositoryMetaValue(
        database,
        KILL_SWITCH_ARBITER_EXPECTED_META_KEY,
    );
    const serialized = repositoryMetaValue(database, KILL_SWITCH_ARBITER_META_KEY);
    if (expected === undefined && serialized === undefined) {
        if (!allowInitialize) {
            throw new Error(
                'durable kill switch arbiter metadata is missing or inconsistent',
            );
        }
        const initial = initialKillSwitchArbiterState();
        setRepositoryMeta(
            database,
            KILL_SWITCH_ARBITER_META_KEY,
            canonicalJson(initial, 'initial kill switch arbiter'),
        );
        setRepositoryMeta(
            database,
            KILL_SWITCH_ARBITER_EXPECTED_META_KEY,
            KILL_SWITCH_ARBITER_SCHEMA_VERSION,
        );
        return initial;
    }
    if (
        expected !== KILL_SWITCH_ARBITER_SCHEMA_VERSION ||
        serialized === undefined
    ) {
        throw new Error('durable kill switch arbiter metadata is missing or inconsistent');
    }
    return validateKillSwitchArbiterState(
        parseStoredCanonicalObject(serialized, 'kill switch arbiter metadata'),
    );
}

function currentKillSwitchArbiter(database) {
    const expected = repositoryMetaValue(
        database,
        KILL_SWITCH_ARBITER_EXPECTED_META_KEY,
    );
    const serialized = repositoryMetaValue(database, KILL_SWITCH_ARBITER_META_KEY);
    if (
        expected !== KILL_SWITCH_ARBITER_SCHEMA_VERSION ||
        serialized === undefined
    ) {
        throw new Error('durable kill switch arbiter metadata is missing or inconsistent');
    }
    return validateKillSwitchArbiterState(
        parseStoredCanonicalObject(serialized, 'kill switch arbiter metadata'),
    );
}

function killSwitchProjection(state) {
    const enabled = KILL_SWITCH_NAMES.filter(
        (name) => state.switches[name].enabled,
    );
    return Object.freeze({
        schemaVersion: state.schemaVersion,
        arbiterRevision: state.arbiterRevision,
        switches: Object.freeze(
            Object.fromEntries(
                KILL_SWITCH_NAMES.map((name) => [name, state.switches[name]]),
            ),
        ),
        enabled: Object.freeze(enabled),
        denyUnionActive: enabled.length > 0,
        brokerWriteAuthority: false,
        accountIdentifiersExposed: false,
        identityIdentifiersExposed: false,
    });
}

function dispatchArbiterGrantMetaKey(intentId) {
    return `${DISPATCH_ARBITER_GRANT_META_PREFIX}${boundedToken(
        intentId,
        'dispatch arbiter intentId',
    )}`;
}

function validateDispatchArbiterGrant(value, intentId) {
    if (
        !exactKeys(value, [
            'schemaVersion',
            'intentId',
            'intentRevision',
            'arbiterRevision',
            'operationClass',
            'operationEvidenceHash',
            'decisionHash',
            'exposureDecisionHash',
            'rearmAuthorizationId',
            'rearmConfirmationSnapshotHash',
            'rearmUserEvidenceHash',
            'grantedAtEpochMs',
        ]) ||
        value.schemaVersion !== DISPATCH_ARBITER_GRANT_SCHEMA_VERSION ||
        value.intentId !== intentId
    ) {
        throw new Error('dispatch arbiter grant metadata is invalid');
    }
    return Object.freeze({
        schemaVersion: value.schemaVersion,
        intentId,
        intentRevision: safeInteger(
            value.intentRevision,
            'dispatch arbiter intentRevision',
        ),
        arbiterRevision: safeInteger(
            value.arbiterRevision,
            'dispatch arbiter revision',
        ),
        operationClass: boundedToken(
            value.operationClass,
            'dispatch arbiter operationClass',
            80,
        ),
        operationEvidenceHash: sha256Digest(
            value.operationEvidenceHash,
            'dispatch arbiter operationEvidenceHash',
        ),
        decisionHash: sha256Digest(
            value.decisionHash,
            'dispatch arbiter decisionHash',
        ),
        exposureDecisionHash: sha256Digest(
            value.exposureDecisionHash,
            'dispatch arbiter exposureDecisionHash',
        ),
        rearmAuthorizationId: boundedToken(
            value.rearmAuthorizationId,
            'dispatch arbiter rearmAuthorizationId',
        ),
        rearmConfirmationSnapshotHash: sha256Digest(
            value.rearmConfirmationSnapshotHash,
            'dispatch arbiter rearmConfirmationSnapshotHash',
        ),
        rearmUserEvidenceHash: sha256Digest(
            value.rearmUserEvidenceHash,
            'dispatch arbiter rearmUserEvidenceHash',
        ),
        grantedAtEpochMs: safeInteger(
            value.grantedAtEpochMs,
            'dispatch arbiter grantedAtEpochMs',
        ),
    });
}

function currentDispatchArbiterGrant(database, intentId) {
    const serialized = repositoryMetaValue(
        database,
        dispatchArbiterGrantMetaKey(intentId),
    );
    if (serialized === undefined) return undefined;
    return validateDispatchArbiterGrant(
        parseStoredCanonicalObject(serialized, 'dispatch arbiter grant metadata'),
        intentId,
    );
}

function canonicalIntentPayload(payloadJson, label) {
    const payload = parseStoredCanonicalObject(payloadJson, label);
    if (canonicalJson(payload, label) !== payloadJson) {
        throw new Error(`${label} is not canonical`);
    }
    return payload;
}

function classifyBrokerWriteForKillSwitch({
    intent,
    reservation,
    exitClaims,
    targetBrokerOrder,
    targetIntent,
    targetCorrelations,
    rearm,
}) {
    const payload = canonicalIntentPayload(
        intent.payload_json,
        'broker intent payload',
    );
    const parentChildPayload =
        intent.operation_kind === 'place' &&
        intent.side === 'Sell' &&
        payload.schemaVersion === PARENT_CHILD_INTENT_SCHEMA_VERSION
            ? canonicalParentChildIntentPayload(payload)
            : undefined;
    const protectivePayload =
        intent.operation_kind === 'place' &&
        intent.side === 'Sell' &&
        parentChildPayload === undefined
            ? canonicalSmartOrderProtectiveBrokerIntentPayload(payload).payload
            : undefined;
    const currentProtectiveProjection =
        protectivePayload !== undefined && exitClaims.length === 1
            ? buildSmartOrderProtectiveBrokerIntentPayload({
                  legId: exitClaims[0].winner_leg_id,
                  protectionPlan:
                      exitClaims[0].existing_plan_json !== null
                          ? canonicalExistingPositionProtectionPlan(
                                parseStoredCanonicalObject(
                                    exitClaims[0].existing_plan_json,
                                    'protective broker intent existing-position lineage payload',
                                ),
                            ).plan
                          : canonicalProtectedEntryIntentPayload(
                                parseStoredCanonicalObject(
                                    exitClaims[0].entry_payload_json,
                                    'protective broker intent entry lineage payload',
                                ),
                            ).payload.protectionPlan,
                  quantityShares: exitClaims[0].quantity_shares,
                  triggerPolicyHash: exitClaims[0].winner_evidence_hash,
              })
            : undefined;
    const exactProtectiveClaim =
        protectivePayload !== undefined &&
        currentProtectiveProjection?.payloadJson === intent.payload_json &&
        currentProtectiveProjection?.payloadSha256 === intent.payload_hash &&
        protectivePayload.schemaVersion ===
            SMART_ORDER_PROTECTIVE_BROKER_INTENT_SCHEMA_VERSION &&
        protectivePayload.quantityShares % protectivePayload.contractUnit === 0 &&
        reservation === undefined &&
        exitClaims.length === 1 &&
        exitClaims[0].external_lineage === 0 &&
        exitClaims[0].state === 'intent_reserved' &&
        exitClaims[0].quantity_shares === protectivePayload.quantityShares &&
        exitClaims[0].account_broker_ref === intent.account_broker_ref &&
        exitClaims[0].account_id_ref === intent.account_id_ref &&
        exitClaims[0].contract_key === intent.contract_key &&
        exitClaims[0].obligation_strategy_id === intent.strategy_id &&
        exitClaims[0].obligation_position_lineage_id ===
            exitClaims[0].position_lineage_id &&
        typeof exitClaims[0].protection_group_id === 'string' &&
        exitClaims[0].protection_group_state === 'winner_selected' &&
        exitClaims[0].protection_group_generation ===
            exitClaims[0].remainder_generation &&
        exitClaims[0].protection_generation_state === 'winner_selected' &&
        exitClaims[0].winner_intent_id === intent.intent_id &&
        exitClaims[0].winner_activation_id === intent.activation_id &&
        exitClaims[0].winner_leg_id === protectivePayload.legId &&
        exitClaims[0].winner_evidence_hash ===
            protectivePayload.triggerPolicyHash &&
        exitClaims[0].winner_evaluation_count === 1 &&
        exitClaims[0].candidate_evaluation_count >= 1 &&
        exitClaims[0].zero_authority_evaluation_count ===
            exitClaims[0].candidate_evaluation_count;
    if (exactProtectiveClaim) {
        return Object.freeze({
            operationClass: 'protective_reduce_only',
            operationEvidenceHash: sha256Canonical(
                {
                    intentPayloadHash: intent.payload_hash,
                    quantityShares: protectivePayload.quantityShares,
                    executionPolicy: {
                        legId: protectivePayload.legId,
                        contractUnit: protectivePayload.contractUnit,
                        executionPolicyRevision:
                            protectivePayload.executionPolicyRevision,
                        executionPolicyHash:
                            protectivePayload.executionPolicyHash,
                        triggerPolicyHash:
                            protectivePayload.triggerPolicyHash,
                        execution: protectivePayload.execution,
                        automaticRetryAllowed: false,
                        iocRemainderDisposition:
                            protectivePayload.iocRemainderDisposition,
                    },
                    exitClaim: {
                        exitClaimId: exitClaims[0].exit_claim_id,
                        obligationId: exitClaims[0].obligation_id,
                        positionLineageId: exitClaims[0].position_lineage_id,
                        remainderGeneration:
                            exitClaims[0].remainder_generation,
                        allocationStartShare:
                            exitClaims[0].allocation_start_share,
                        quantityShares: exitClaims[0].quantity_shares,
                        revision: exitClaims[0].revision,
                        evidenceHash: exitClaims[0].evidence_hash,
                    },
                    protectionGroup: {
                        protectionGroupId:
                            exitClaims[0].protection_group_id,
                        groupRevision:
                            exitClaims[0].protection_group_revision,
                        generationRevision:
                            exitClaims[0].protection_generation_revision,
                        winnerLegId: exitClaims[0].winner_leg_id,
                        candidateCount:
                            exitClaims[0].candidate_evaluation_count,
                    },
                },
                'protective kill switch classification evidence',
            ),
        });
    }
    const exactParentChildClaim =
        parentChildPayload?.leg === 'child' &&
        parentChildPayload.order.baseShares %
            parentChildPayload.order.contractUnit ===
            0 &&
        reservation === undefined &&
        exitClaims.length === 1 &&
        exitClaims[0].external_lineage === 0 &&
        exitClaims[0].state === 'intent_reserved' &&
        exitClaims[0].quantity_shares ===
            parentChildPayload.order.baseShares &&
        exitClaims[0].account_broker_ref === intent.account_broker_ref &&
        exitClaims[0].account_id_ref === intent.account_id_ref &&
        exitClaims[0].contract_key === intent.contract_key &&
        exitClaims[0].obligation_strategy_id === intent.strategy_id &&
        exitClaims[0].obligation_position_lineage_id ===
            parentChildPayload.childPositionLineageId &&
        exitClaims[0].position_lineage_id ===
            parentChildPayload.childPositionLineageId &&
        exitClaims[0].protection_group_state === 'winner_selected' &&
        exitClaims[0].protection_generation_state === 'winner_selected' &&
        exitClaims[0].winner_intent_id === intent.intent_id &&
        exitClaims[0].winner_activation_id === intent.activation_id &&
        exitClaims[0].winner_leg_id === 'child' &&
        exitClaims[0].winner_evidence_hash ===
            parentChildPayload.conditionEvidenceHash &&
        exitClaims[0].winner_evaluation_count === 1 &&
        exitClaims[0].candidate_evaluation_count === 1 &&
        exitClaims[0].zero_authority_evaluation_count === 1;
    if (exactParentChildClaim) {
        return Object.freeze({
            operationClass: 'protective_reduce_only',
            operationEvidenceHash: sha256Canonical(
                {
                    schemaVersion:
                        'smart-order-parent-child-reduce-only-decision/2026-08-21.1',
                    intentPayloadHash: intent.payload_hash,
                    parentSettlementHash:
                        parentChildPayload.parentSettlementHash,
                    childPositionLineageId:
                        parentChildPayload.childPositionLineageId,
                    exitClaimId: exitClaims[0].exit_claim_id,
                    exitClaimRevision: exitClaims[0].revision,
                    protectionGroupId:
                        exitClaims[0].protection_group_id,
                    protectionGenerationRevision:
                        exitClaims[0].protection_generation_revision,
                    quantityShares: parentChildPayload.order.baseShares,
                    automaticRetryAllowed: false,
                },
                'parent-child reduce-only classification evidence',
            ),
        });
    }
    if (protectivePayload !== undefined) {
        throw new Error(
            'protective broker intent lost its exact CommonLot claim/execution binding',
        );
    }
    if (parentChildPayload !== undefined) {
        throw new Error(
            'parent-child child intent lost its exact reduce-only claim binding',
        );
    }
    const explicitManualCancel =
        intent.operation_kind === 'cancel' &&
        intent.owner_kind === 'manual_request' &&
        exactKeys(payload, [
            'brokerOrderId',
            'controlRevision',
            'schemaVersion',
        ]) &&
        payload.schemaVersion === MANUAL_CANCEL_BROKER_INTENT_SCHEMA_VERSION &&
        payload.brokerOrderId === intent.target_broker_order_id &&
        payload.controlRevision === intent.target_control_revision &&
        typeof intent.target_broker_order_id === 'string' &&
        intent.target_broker_order_id.length > 0 &&
        Number.isSafeInteger(intent.target_control_revision) &&
        intent.target_control_revision >= 0 &&
        targetBrokerOrder !== undefined &&
        ['pre_submitted', 'submitted', 'part_filled'].includes(
            targetBrokerOrder.state,
        ) &&
        targetBrokerOrder.broker_order_id === intent.target_broker_order_id &&
        targetBrokerOrder.control_revision === intent.target_control_revision &&
        targetBrokerOrder.quantity_shares > 0 &&
        targetBrokerOrder.remaining_shares > 0 &&
        targetBrokerOrder.filled_shares + targetBrokerOrder.remaining_shares ===
            targetBrokerOrder.quantity_shares &&
        targetIntent !== undefined &&
        targetBrokerOrder.intent_id === targetIntent.intent_id &&
        targetIntent.account_broker_ref === intent.account_broker_ref &&
        targetIntent.account_id_ref === intent.account_id_ref &&
        targetIntent.trade_date === intent.trade_date &&
        targetIntent.contract_key === intent.contract_key &&
        targetIntent.side === intent.side &&
        targetCorrelations.length === 1 &&
        targetCorrelations.every(
            (correlation) =>
                correlation.intent_id === targetIntent.intent_id &&
                correlation.broker_order_id ===
                    targetBrokerOrder.broker_order_id &&
                correlation.account_broker_ref === intent.account_broker_ref &&
                correlation.account_id_ref === intent.account_id_ref &&
                correlation.trade_date === intent.trade_date &&
                correlation.contract_key === intent.contract_key &&
                correlation.side === intent.side,
        ) &&
        rearm !== undefined &&
        rearm.state === 'active' &&
        reservation === undefined &&
        exitClaims.length === 0;
    if (explicitManualCancel) {
        return Object.freeze({
            operationClass: 'explicit_manual_cancel',
            operationEvidenceHash: sha256Canonical(
                {
                    intentPayloadHash: intent.payload_hash,
                    targetBrokerOrder: {
                        brokerOrderId: targetBrokerOrder.broker_order_id,
                        state: targetBrokerOrder.state,
                        controlRevision: targetBrokerOrder.control_revision,
                        quantityShares: targetBrokerOrder.quantity_shares,
                        filledShares: targetBrokerOrder.filled_shares,
                        remainingShares: targetBrokerOrder.remaining_shares,
                        revision: targetBrokerOrder.revision,
                        evidenceHash: targetBrokerOrder.evidence_hash,
                    },
                    targetIntent: {
                        intentId: targetIntent.intent_id,
                        accountBrokerRef: targetIntent.account_broker_ref,
                        accountIdRef: targetIntent.account_id_ref,
                        tradeDate: targetIntent.trade_date,
                        contractKey: targetIntent.contract_key,
                        side: targetIntent.side,
                    },
                    targetCorrelations: targetCorrelations.map(
                        (correlation) => ({
                            correlationId: correlation.correlation_id,
                            canonicalKeyHash: correlation.canonical_key_hash,
                            evidenceHash: correlation.evidence_hash,
                            revision: correlation.revision,
                        }),
                    ),
                    rearmAuthorizationId: rearm.rearm_authorization_id,
                    rearmConfirmationSnapshotHash:
                        rearm.confirmation_snapshot_hash,
                    rearmUserEvidenceHash: rearm.user_rearm_evidence_hash,
                },
                'manual cancel kill switch classification evidence',
            ),
        });
    }
    const protectiveEntryCancel =
        intent.operation_kind === 'cancel' &&
        intent.owner_kind === 'activation' &&
        exactKeys(payload, [
            'brokerOrderId',
            'controlRevision',
            'protectionGroupId',
            'remainderGeneration',
            'schemaVersion',
            'triggerSelectionHash',
        ]) &&
        payload.schemaVersion ===
            PROTECTIVE_ENTRY_CANCEL_INTENT_SCHEMA_VERSION &&
        payload.brokerOrderId === intent.target_broker_order_id &&
        payload.controlRevision === intent.target_control_revision &&
        typeof payload.protectionGroupId === 'string' &&
        payload.protectionGroupId.length > 0 &&
        Number.isSafeInteger(payload.remainderGeneration) &&
        payload.remainderGeneration >= 0 &&
        /^sha256:[0-9a-f]{64}$/.test(payload.triggerSelectionHash ?? '') &&
        targetBrokerOrder !== undefined &&
        ['pre_submitted', 'submitted', 'part_filled'].includes(
            targetBrokerOrder.state,
        ) &&
        targetBrokerOrder.broker_order_id === intent.target_broker_order_id &&
        targetBrokerOrder.control_revision === intent.target_control_revision &&
        targetBrokerOrder.quantity_shares > 0 &&
        targetBrokerOrder.remaining_shares > 0 &&
        targetBrokerOrder.filled_shares + targetBrokerOrder.remaining_shares ===
            targetBrokerOrder.quantity_shares &&
        targetIntent !== undefined &&
        targetBrokerOrder.intent_id === targetIntent.intent_id &&
        targetIntent.account_broker_ref === intent.account_broker_ref &&
        targetIntent.account_id_ref === intent.account_id_ref &&
        targetIntent.trade_date === intent.trade_date &&
        targetIntent.contract_key === intent.contract_key &&
        targetIntent.side === intent.side &&
        targetCorrelations.length === 1 &&
        targetCorrelations.every(
            (correlation) =>
                correlation.intent_id === targetIntent.intent_id &&
                correlation.broker_order_id ===
                    targetBrokerOrder.broker_order_id &&
                correlation.account_broker_ref === intent.account_broker_ref &&
                correlation.account_id_ref === intent.account_id_ref &&
                correlation.trade_date === intent.trade_date &&
                correlation.contract_key === intent.contract_key &&
                correlation.side === intent.side,
        ) &&
        rearm !== undefined &&
        rearm.state === 'active' &&
        reservation === undefined &&
        exitClaims.length === 0;
    if (protectiveEntryCancel) {
        return Object.freeze({
            operationClass: 'protective_entry_cancel',
            operationEvidenceHash: sha256Canonical(
                {
                    intentPayloadHash: intent.payload_hash,
                    protectionGroupId: payload.protectionGroupId,
                    remainderGeneration: payload.remainderGeneration,
                    triggerSelectionHash: payload.triggerSelectionHash,
                    targetBrokerOrder: {
                        brokerOrderId: targetBrokerOrder.broker_order_id,
                        state: targetBrokerOrder.state,
                        controlRevision: targetBrokerOrder.control_revision,
                        quantityShares: targetBrokerOrder.quantity_shares,
                        filledShares: targetBrokerOrder.filled_shares,
                        remainingShares: targetBrokerOrder.remaining_shares,
                        revision: targetBrokerOrder.revision,
                        evidenceHash: targetBrokerOrder.evidence_hash,
                    },
                    targetCorrelations: targetCorrelations.map(
                        (correlation) => ({
                            correlationId: correlation.correlation_id,
                            canonicalKeyHash: correlation.canonical_key_hash,
                            evidenceHash: correlation.evidence_hash,
                            revision: correlation.revision,
                        }),
                    ),
                    rearmAuthorizationId: rearm.rearm_authorization_id,
                    rearmConfirmationSnapshotHash:
                        rearm.confirmation_snapshot_hash,
                    rearmUserEvidenceHash: rearm.user_rearm_evidence_hash,
                },
                'protective entry cancel kill switch classification evidence',
            ),
        });
    }
    if (
        reservation !== undefined ||
        (intent.operation_kind === 'place' && intent.side === 'Buy')
    ) {
        return Object.freeze({
            operationClass: 'new_exposure',
            operationEvidenceHash: intent.payload_hash,
        });
    }
    if (intent.owner_kind !== 'manual_request') {
        return Object.freeze({
            operationClass: 'automation_write',
            operationEvidenceHash: intent.payload_hash,
        });
    }
    return Object.freeze({
        operationClass: 'unclassified_write',
        operationEvidenceHash: intent.payload_hash,
    });
}

function evaluateKillSwitchDenyUnion(state, operationClass) {
    const deniedBy = [];
    if (state.switches.emergency_block_all_writes.enabled) {
        deniedBy.push('emergency_block_all_writes');
    }
    if (
        state.switches.pause_automation.enabled &&
        operationClass !== 'explicit_manual_cancel'
    ) {
        deniedBy.push('pause_automation');
    }
    if (
        state.switches.pause_new_exposure.enabled &&
        ![
            'protective_reduce_only',
            'protective_entry_cancel',
            'explicit_manual_cancel',
        ].includes(
            operationClass,
        )
    ) {
        deniedBy.push('pause_new_exposure');
    }
    return Object.freeze(deniedBy.sort());
}

function killSwitchStatus(database, input) {
    if (
        input === undefined ||
        input === null ||
        typeof input !== 'object' ||
        Array.isArray(input) ||
        Object.keys(input).length !== 0
    ) {
        throw new TypeError('kill switch status input must be an empty object');
    }
    return killSwitchProjection(currentKillSwitchArbiter(database));
}

function mutateKillSwitchInTransaction(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'runtimeEpochId',
            'senderFence',
            'apiGeneration',
            'expectedArbiterRevision',
            'switchName',
            'enabled',
            'reasonCode',
            'nowEpochMs',
        ])
    ) {
        throw new TypeError('kill switch mutation input schema is invalid');
    }
    const nowEpochMs = safeInteger(
        input.nowEpochMs,
        'kill switch mutation.nowEpochMs',
    );
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
        const senderFence = boundedToken(input.senderFence, 'senderFence');
        const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
        if (
            !currentReadySenderMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error('kill switch mutation requires the current ready sender');
        }
        const switchName = boundedToken(
            input.switchName,
            'kill switch name',
            80,
        );
        if (!KILL_SWITCH_NAME_SET.has(switchName)) {
            throw new TypeError('kill switch name is not allowlisted');
        }
        if (typeof input.enabled !== 'boolean') {
            throw new TypeError('kill switch enabled must be boolean');
        }
        const reasonCode = boundedToken(
            input.reasonCode,
            'kill switch reasonCode',
            80,
        );
        if (!KILL_SWITCH_REASON_CODE_SET.has(reasonCode)) {
            throw new TypeError('kill switch reasonCode is not allowlisted');
        }
        const current = currentKillSwitchArbiter(database);
        const expectedArbiterRevision = safeInteger(
            input.expectedArbiterRevision,
            'kill switch expectedArbiterRevision',
        );
        if (current.arbiterRevision !== expectedArbiterRevision) {
            const error = new Error('kill switch mutation lost its arbiter revision CAS');
            error.name = 'KillSwitchArbiterRevisionError';
            throw error;
        }
        if (current.switches[switchName].enabled === input.enabled) {
            return Object.freeze({
                ...killSwitchProjection(current),
                changed: false,
                replayed: true,
            });
        }
        if (current.arbiterRevision >= Number.MAX_SAFE_INTEGER) {
            throw new Error('kill switch arbiter revision is exhausted');
        }
        const nextRevision = current.arbiterRevision + 1;
        const switches = Object.fromEntries(
            KILL_SWITCH_NAMES.map((name) => [
                name,
                name === switchName
                    ? Object.freeze({
                          enabled: input.enabled,
                          revision: nextRevision,
                          updatedAtEpochMs: nowEpochMs,
                          reasonCode,
                      })
                    : current.switches[name],
            ]),
        );
        const next = validateKillSwitchArbiterState({
            schemaVersion: KILL_SWITCH_ARBITER_SCHEMA_VERSION,
            arbiterRevision: nextRevision,
            switches,
        });
        setRepositoryMeta(
            database,
            KILL_SWITCH_ARBITER_META_KEY,
            canonicalJson(next, 'kill switch arbiter mutation'),
        );
    return Object.freeze({
        ...killSwitchProjection(next),
        changed: true,
        replayed: false,
    });
}

function mutateKillSwitch(database, input) {
    return transaction(database, () =>
        mutateKillSwitchInTransaction(database, input),
    );
}

function runtimeTradingSenderAuthority(runtimeEpochId) {
    return `runtime:${boundedToken(runtimeEpochId, 'runtimeEpochId')}`;
}

function currentApiGenerationIsInvalidated(database) {
    return (
        repositoryMetaValue(database, API_GENERATION_INVALIDATED_SHA256_META_KEY) !==
        undefined
    );
}

function canonicalRuntimeContinuityReasonCodes(value, label) {
    if (
        !Array.isArray(value) ||
        value.length === 0 ||
        value.length > RUNTIME_CONTINUITY_GAP_REASON_CODE_SET.size
    ) {
        throw new TypeError(`${label} must be a non-empty bounded array`);
    }
    const reasonCodes = value.map((reasonCode, index) =>
        boundedToken(reasonCode, `${label}[${index}]`, 80),
    );
    if (
        reasonCodes.some(
            (reasonCode) => !RUNTIME_CONTINUITY_GAP_REASON_CODE_SET.has(reasonCode),
        ) ||
        new Set(reasonCodes).size !== reasonCodes.length ||
        JSON.stringify(reasonCodes) !== JSON.stringify([...reasonCodes].sort())
    ) {
        throw new TypeError(`${label} must contain sorted unique allowlisted codes`);
    }
    return Object.freeze(reasonCodes);
}

const RUNTIME_CONTINUITY_INVALIDATION_RESULT_KEYS = Object.freeze([
    'automaticRedispatchAllowed',
    'continuitySignalSha256',
    'invalidatedGateManifestCount',
    'manualInterventionStrategyCount',
    'previousState',
    'reason',
    'reasonCodes',
    'recoveredIntentCount',
    'recoveryStrategyCount',
    'requiresProcessRestart',
    'revision',
    'state',
    'supersededRearmCount',
    'userRearmRequiredAfterReconciliation',
]);

function currentRuntimeContinuityInvalidation(database) {
    const serialized = repositoryMetaValue(
        database,
        RUNTIME_CONTINUITY_INVALIDATION_META_KEY,
    );
    if (serialized === undefined) return undefined;
    const record = parseStoredCanonicalObject(
        serialized,
        'runtime continuity invalidation metadata',
    );
    if (
        !exactKeys(record, [
            'schemaVersion',
            'signalSha256',
            'reasonCodes',
            'invalidatedAtEpochMs',
            'result',
        ]) ||
        record.schemaVersion !== RUNTIME_CONTINUITY_INVALIDATION_SCHEMA_VERSION
    ) {
        throw new Error('runtime continuity invalidation metadata schema is invalid');
    }
    const signalSha256 = sha256Digest(
        record.signalSha256,
        'runtime continuity signal',
    );
    const reasonCodes = canonicalRuntimeContinuityReasonCodes(
        record.reasonCodes,
        'runtime continuity reasonCodes',
    );
    safeInteger(
        record.invalidatedAtEpochMs,
        'runtime continuity invalidatedAtEpochMs',
    );
    const result = record.result;
    if (
        !exactKeys(result, RUNTIME_CONTINUITY_INVALIDATION_RESULT_KEYS) ||
        result.state !== 'reconciling' ||
        ![
            'starting',
            'observe_only',
            'reconciling',
            'ready',
            'quiescing',
        ].includes(result.previousState) ||
        result.reason !== 'continuity_gap_invalidated' ||
        result.continuitySignalSha256 !== signalSha256 ||
        JSON.stringify(result.reasonCodes) !== JSON.stringify(reasonCodes) ||
        result.automaticRedispatchAllowed !== false ||
        result.requiresProcessRestart !== false ||
        result.userRearmRequiredAfterReconciliation !== true
    ) {
        throw new Error('runtime continuity invalidation result is invalid');
    }
    for (const key of [
        'revision',
        'recoveryStrategyCount',
        'supersededRearmCount',
        'recoveredIntentCount',
        'invalidatedGateManifestCount',
        'manualInterventionStrategyCount',
    ]) {
        safeInteger(result[key], `runtime continuity result.${key}`);
    }
    return Object.freeze({
        schemaVersion: record.schemaVersion,
        signalSha256,
        reasonCodes,
        invalidatedAtEpochMs: record.invalidatedAtEpochMs,
        result: Object.freeze({
            ...result,
            reasonCodes,
        }),
    });
}

function currentRuntimeContinuityIsInvalidated(database) {
    return currentRuntimeContinuityInvalidation(database) !== undefined;
}

function validatePriorTradingSenderAuthority(database) {
    const authority = repositoryMetaValue(
        database,
        TRADING_SENDER_AUTHORITY_META_KEY,
    );
    const currentRuntimeEpochId = repositoryMetaValue(
        database,
        'current_runtime_epoch_id',
    );
    if (authority === undefined || authority === NO_TRADING_SENDER_AUTHORITY) {
        if (currentRuntimeEpochId !== undefined) {
            throw new Error(
                'trading sender authority is missing for the current runtime epoch',
            );
        }
        return;
    }
    if (
        currentRuntimeEpochId === undefined ||
        authority !== runtimeTradingSenderAuthority(currentRuntimeEpochId)
    ) {
        throw new Error('trading sender authority metadata is inconsistent');
    }
    const current = database
        .prepare(`SELECT state FROM runtime_epochs WHERE runtime_epoch_id=?`)
        .get(currentRuntimeEpochId);
    if (!current || ['stopped', 'forced_stopped'].includes(current.state)) {
        throw new Error('trading sender authority targets a terminal runtime epoch');
    }
}

function openTrailingGapResolutionCompanions(
    database,
    { strategy, gapEvidenceHash, nowEpochMs, eventSuffix },
) {
    const scopeHash = sha256Canonical(
        {
            schemaVersion: 'smart-order-trailing-gap-scope/2026-08-13.1',
            strategyId: strategy.strategy_id,
            definitionHash: strategy.definition_hash,
            confirmationSnapshotHash: strategy.confirmation_snapshot_hash,
            strategyRevision: strategy.revision + 1,
        },
        'trailing gap resolution scope',
    );
    const evidenceSnapshotHash = sha256Canonical(
        {
            schemaVersion:
                'smart-order-trailing-gap-evidence-snapshot/2026-08-13.1',
            reasonCode: 'TRAILING_GAP_EXTREME_UNKNOWN',
            gapEvidenceHash,
            previousState: strategy.state,
            previousRevision: strategy.revision,
        },
        'trailing gap resolution evidence',
    );
    const identity = sha256Canonical(
        {
            strategyId: strategy.strategy_id,
            strategyRevision: strategy.revision + 1,
            reasonCode: 'TRAILING_GAP_EXTREME_UNKNOWN',
            scopeHash,
            evidenceSnapshotHash,
        },
        'trailing gap resolution identity',
    ).slice('sha256:'.length);
    const resolutionCaseId = `resolution-${identity}`;
    const blockerId = `blocker-${identity}`;
    database.prepare(`
        INSERT INTO resolution_cases(
            resolution_case_id, strategy_id, reason_code, scope_hash,
            evidence_snapshot_hash, state, created_at_epoch_ms,
            updated_at_epoch_ms, terminal_at_epoch_ms, revision
        ) VALUES (?, ?, 'TRAILING_GAP_EXTREME_UNKNOWN', ?, ?, 'open',
                  ?, ?, NULL, 0)
    `).run(
        resolutionCaseId,
        strategy.strategy_id,
        scopeHash,
        evidenceSnapshotHash,
        nowEpochMs,
        nowEpochMs,
    );
    database.prepare(`
        INSERT INTO safety_blockers(
            blocker_id, resolution_case_id, scope_hash, reason_code,
            state, created_at_epoch_ms, resolved_at_epoch_ms, revision
        ) VALUES (?, ?, ?, 'TRAILING_GAP_EXTREME_UNKNOWN', 'open',
                  ?, NULL, 0)
    `).run(
        blockerId,
        resolutionCaseId,
        scopeHash,
        nowEpochMs,
    );
    advanceLifecycleSideEffectRevision(database);
    insertTransitionJournalEvent(database, {
        entityKind: 'resolution_case',
        entityId: resolutionCaseId,
        revision: 0,
        reasonCode: 'TRAILING_GAP_EXTREME_UNKNOWN',
        summaryCode: 'trailing_gap_resolution_opened',
        nowEpochMs,
        payloadHash: evidenceSnapshotHash,
        eventSuffix: `${eventSuffix}-resolution`,
    });
    insertTransitionJournalEvent(database, {
        entityKind: 'safety_blocker',
        entityId: blockerId,
        revision: 0,
        reasonCode: 'TRAILING_GAP_EXTREME_UNKNOWN',
        summaryCode: 'trailing_gap_safety_blocker_opened',
        nowEpochMs,
        payloadHash: scopeHash,
        eventSuffix: `${eventSuffix}-blocker`,
    });
    return Object.freeze({
        resolutionCaseId,
        blockerId,
        scopeHash,
        evidenceSnapshotHash,
    });
}

function startRuntimeEpoch(database, input) {
    const now = safeInteger(input.nowEpochMs, 'runtime.nowEpochMs');
    return transaction(database, () => {
        const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
        const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
        const senderFence = boundedToken(input.senderFence, 'senderFence');
        const leaseEvidenceHash = sha256Digest(
            input.leaseEvidenceHash,
            'leaseEvidenceHash',
        );
        const existing = database
            .prepare(`SELECT state FROM runtime_epochs WHERE runtime_epoch_id=?`)
            .get(runtimeEpochId);
        if (existing) throw new Error('runtime epoch already exists');
        validatePriorTradingSenderAuthority(database);

        // A newly acquired epoch can be recovering from a process crash,
        // relogin, upgrade, or a missed generation watcher. Never inherit a
        // previously active monitoring state across that process boundary.
        const activeStrategies = database
            .prepare(`
                SELECT strategy_id, strategy_kind, state, revision,
                       definition_hash, confirmation_snapshot_hash
                  FROM strategies
                 WHERE state IN ('observing','monitoring')
                 ORDER BY strategy_id
            `)
            .all();
        // A process boundary cannot prove that a monitoring trailing strategy
        // observed every eligible last trade. Until a production verifier can
        // prove a gap-free current lineage, preserve its extreme only for audit
        // and require manual resolution. A trailing strategy that had not yet
        // entered monitoring remains ordinary recovery.
        const manualInterventionStrategies = activeStrategies.filter(
            (strategy) =>
                strategy.strategy_kind === 'trailing_exit' &&
                strategy.state === 'monitoring',
        );
        const recoveringStrategies = activeStrategies.filter(
            (strategy) =>
                !(
                    strategy.strategy_kind === 'trailing_exit' &&
                    strategy.state === 'monitoring'
                ),
        );
        const enterTrailingManualIntervention = database.prepare(`
            UPDATE strategies
               SET state='manual_intervention', updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE strategy_id=? AND strategy_kind='trailing_exit'
               AND state='monitoring' AND revision=?
        `);
        for (const strategy of manualInterventionStrategies) {
            if (
                Number(
                    enterTrailingManualIntervention.run(
                        now,
                        strategy.strategy_id,
                        strategy.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'trailing restart manual-intervention transition lost its CAS',
                );
            }
            const trailingGapLineageHash = sha256Canonical(
                {
                    schemaVersion:
                        'smart-order-trailing-gap-transition/2026-08-13.1',
                    strategyId: strategy.strategy_id,
                    strategyKind: strategy.strategy_kind,
                    previousState: strategy.state,
                    previousRevision: strategy.revision,
                    definitionHash: strategy.definition_hash,
                    confirmationSnapshotHash:
                        strategy.confirmation_snapshot_hash,
                    newRuntimeEpochIdSha256: sha256Text(runtimeEpochId),
                    gapKind: 'runtime_restart',
                },
                'trailing restart gap durable lineage',
            );
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: strategy.strategy_id,
                revision: strategy.revision + 1,
                reasonCode: 'TRAILING_GAP_EXTREME_UNKNOWN',
                summaryCode:
                    'trailing_strategy_manual_after_runtime_restart_gap',
                nowEpochMs: now,
                payloadHash: trailingGapLineageHash,
                eventSuffix: `runtime-${runtimeEpochId}-trailing-manual`,
            });
            openTrailingGapResolutionCompanions(database, {
                strategy,
                gapEvidenceHash: trailingGapLineageHash,
                nowEpochMs: now,
                eventSuffix: `runtime-${runtimeEpochId}-trailing-manual`,
            });
        }
        const recoverStrategy = database.prepare(`
            UPDATE strategies
               SET state='recovery', updated_at_epoch_ms=?, revision=revision+1
             WHERE strategy_id=? AND state=? AND revision=?
        `);
        for (const strategy of recoveringStrategies) {
            if (
                Number(
                    recoverStrategy.run(
                        now,
                        strategy.strategy_id,
                        strategy.state,
                        strategy.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error('runtime start strategy recovery lost its CAS');
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: strategy.strategy_id,
                revision: strategy.revision + 1,
                reasonCode: 'RUNTIME_EPOCH_STARTED_RECOVERY_REQUIRED',
                summaryCode: 'strategy_recovery_after_runtime_epoch_start',
                nowEpochMs: now,
                payloadHash: strategy.definition_hash,
                eventSuffix: `runtime-${runtimeEpochId}-recovery`,
            });
        }

        const staleRearms = database
            .prepare(`
                SELECT rearms.rearm_authorization_id, rearms.intent_id,
                       rearms.revision, intents.revision AS intent_revision,
                       rearms.user_rearm_evidence_hash
                  FROM intent_rearm_authorizations AS rearms
                  JOIN order_intents AS intents
                    ON intents.intent_id=rearms.intent_id
                 WHERE rearms.state='active'
            `)
            .all();
        const supersedeRearm = database.prepare(`
            UPDATE intent_rearm_authorizations
               SET state='superseded', revision=revision+1
             WHERE rearm_authorization_id=? AND state='active' AND revision=?
        `);
        for (const rearm of staleRearms) {
            if (
                Number(
                    supersedeRearm.run(
                        rearm.rearm_authorization_id,
                        rearm.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error('prepared intent re-arm supersession lost its CAS');
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: rearm.intent_id,
                revision: rearm.intent_revision,
                reasonCode: 'PREPARED_INTENT_REARM_SUPERSEDED_BY_RUNTIME_RESTART',
                summaryCode: 'prepared_intent_rearm_superseded',
                nowEpochMs: now,
                payloadHash: rearm.user_rearm_evidence_hash,
                eventSuffix: `rearm-${rearm.rearm_authorization_id}-superseded`,
            });
        }

        const priorEpochs = database
            .prepare(`
                SELECT runtime_epoch_id, state, revision
                  FROM runtime_epochs
                 WHERE state IN ('starting','ready','quiescing')
                 ORDER BY started_at_epoch_ms, runtime_epoch_id
            `)
            .all();
        const demotePrior = database.prepare(`
            UPDATE runtime_epochs
               SET state='reconciling', revision=revision+1
             WHERE runtime_epoch_id=? AND state=? AND revision=?
        `);
        for (const prior of priorEpochs) {
            const result = demotePrior.run(
                prior.runtime_epoch_id,
                prior.state,
                prior.revision,
            );
            if (Number(result.changes) !== 1) {
                throw new Error('prior runtime epoch fence transition lost its CAS');
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'runtime_epoch',
                entityId: prior.runtime_epoch_id,
                revision: prior.revision + 1,
                reasonCode: 'RUNTIME_EPOCH_SUPERSEDED_RECONCILING',
                summaryCode: 'runtime_epoch_reconciling',
                nowEpochMs: now,
                payloadHash: sha256Canonical(
                    { previousState: prior.state, state: 'reconciling' },
                    'runtime epoch transition',
                ),
                eventSuffix: 'superseded-reconciling',
            });
        }

        const dispatched = database
            .prepare(`
                SELECT intent_id, activation_id, revision
                  FROM order_intents WHERE state='dispatching'
            `)
            .all();
        const recoverIntent = database.prepare(`
            UPDATE order_intents
               SET state='reconciling', terminal_outcome='restart_after_dispatch_fence',
                   updated_at_epoch_ms=?, revision=revision+1
             WHERE intent_id=? AND state='dispatching' AND revision=?
        `);
        const recoverActivation = database.prepare(`
            UPDATE activations
               SET state='unknown', updated_at_epoch_ms=?, revision=revision+1
             WHERE activation_id=? AND state='dispatching'
        `);
        const recoverReservation = database.prepare(`
            UPDATE entry_exposure_reservations
               SET state='unknown', updated_at_epoch_ms=?, revision=revision+1
             WHERE intent_id=? AND state='reserved'
        `);
        for (const row of dispatched) {
            if (Number(recoverIntent.run(now, row.intent_id, row.revision).changes) !== 1) {
                throw new Error('runtime start intent recovery lost its CAS');
            }
            if (Number(recoverActivation.run(now, row.activation_id).changes) !== 1) {
                throw new Error('runtime start activation recovery lost its CAS');
            }
            recoverReservation.run(now, row.intent_id);
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: row.intent_id,
                revision: row.revision + 1,
                reasonCode: 'INTENT_RECOVERING_AFTER_RUNTIME_RESTART',
                summaryCode: 'intent_reconciling_after_restart',
                nowEpochMs: now,
                payloadHash: sha256Canonical(
                    { state: 'reconciling', activationId: row.activation_id },
                    'restart intent recovery',
                ),
                eventSuffix: 'restart-reconciling',
            });
            const activation = database
                .prepare('SELECT revision FROM activations WHERE activation_id=?')
                .get(row.activation_id);
            insertTransitionJournalEvent(database, {
                entityKind: 'activation',
                entityId: row.activation_id,
                revision: activation.revision,
                reasonCode: 'ACTIVATION_UNKNOWN_AFTER_RUNTIME_RESTART',
                summaryCode: 'activation_unknown_after_restart',
                nowEpochMs: now,
                payloadHash: sha256Canonical(
                    { state: 'unknown', intentId: row.intent_id },
                    'restart activation recovery',
                ),
                eventSuffix: 'restart-unknown',
            });
            const reservation = database
                .prepare(`
                    SELECT reservation_id, revision
                      FROM entry_exposure_reservations WHERE intent_id=?
                `)
                .get(row.intent_id);
            if (reservation) {
                insertTransitionJournalEvent(database, {
                    entityKind: 'entry_exposure_reservation',
                    entityId: reservation.reservation_id,
                    revision: reservation.revision,
                    reasonCode: 'RESERVATION_UNKNOWN_AFTER_RUNTIME_RESTART',
                    summaryCode: 'reservation_unknown_after_restart',
                    nowEpochMs: now,
                    payloadHash: sha256Canonical(
                        { state: 'unknown', intentId: row.intent_id },
                        'restart reservation recovery',
                    ),
                    eventSuffix: 'restart-unknown',
                });
            }
        }

        database
            .prepare(`
                INSERT INTO runtime_epochs(
                    runtime_epoch_id, api_generation, sender_fence,
                    lease_evidence_hash, reconciliation_evidence_hash,
                    state, started_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, NULL, 'reconciling', ?, 0)
            `)
            .run(
                runtimeEpochId,
                apiGeneration,
                senderFence,
                leaseEvidenceHash,
                now,
            );
        setRepositoryMeta(database, 'current_runtime_epoch_id', runtimeEpochId);
        setRepositoryMeta(database, 'current_sender_fence', senderFence);
        setRepositoryMeta(database, 'current_api_generation', apiGeneration);
        deleteRepositoryMeta(database, API_GENERATION_INVALIDATED_SHA256_META_KEY);
        deleteRepositoryMeta(database, RUNTIME_CONTINUITY_INVALIDATION_META_KEY);
        deleteRepositoryMeta(database, 'current_lifecycle_operation');
        deleteRepositoryMeta(database, 'current_lifecycle_operation_id');
        deleteRepositoryMeta(database, LIFECYCLE_MUTATION_FENCE_META_KEY);
        setRepositoryMeta(
            database,
            TRADING_SENDER_AUTHORITY_META_KEY,
            runtimeTradingSenderAuthority(runtimeEpochId),
        );
        insertTransitionJournalEvent(database, {
            entityKind: 'runtime_epoch',
            entityId: runtimeEpochId,
            revision: 0,
            reasonCode: 'RUNTIME_EPOCH_STARTED_RECONCILING',
            summaryCode: 'runtime_epoch_started_reconciling',
            nowEpochMs: now,
            payloadHash: leaseEvidenceHash,
            eventSuffix: 'started-reconciling',
        });
        return Object.freeze({
            runtimeEpochId,
            state: 'reconciling',
            revision: 0,
            priorEpochIds: Object.freeze(
                priorEpochs.map((row) => row.runtime_epoch_id),
            ),
            recoveredIntentIds: Object.freeze(
                dispatched.map((row) => row.intent_id),
            ),
            supersededRearmIntentIds: Object.freeze(
                staleRearms.map((row) => row.intent_id),
            ),
            recoveryStrategyIds: Object.freeze(
                recoveringStrategies.map((strategy) => strategy.strategy_id),
            ),
            manualInterventionStrategyIds: Object.freeze(
                manualInterventionStrategies.map(
                    (strategy) => strategy.strategy_id,
                ),
            ),
            automaticRedispatchAllowed: false,
            tradingSenderAuthority: 'runtime_only',
            legacyTradingTriggerAuthority: 'permanently_retired',
            killSwitch: killSwitchProjection(currentKillSwitchArbiter(database)),
        });
    });
}

function rearmPreparedIntent(database, input, withinExistingTransaction = false) {
    rejectCallerSuppliedJournalEvent(input);
    const now = safeInteger(input.nowEpochMs, 'rearm.nowEpochMs');
    const mutate = () => {
        const intentId = boundedToken(input.intentId, 'rearm.intentId');
        const runtimeEpochId = boundedToken(
            input.runtimeEpochId,
            'rearm.runtimeEpochId',
        );
        const senderFence = boundedToken(input.senderFence, 'rearm.senderFence');
        const apiGeneration = boundedToken(
            input.apiGeneration,
            'rearm.apiGeneration',
        );
        const rearmAuthorizationId = boundedToken(
            input.rearmAuthorizationId,
            'rearm.rearmAuthorizationId',
        );
        const rearmRequestId = boundedToken(
            input.rearmRequestId,
            'rearm.rearmRequestId',
        );
        const confirmationSnapshotHash = sha256Digest(
            input.confirmationSnapshotHash,
            'rearm.confirmationSnapshotHash',
        );
        const reconciliationEvidenceHash = sha256Digest(
            input.reconciliationEvidenceHash,
            'rearm.reconciliationEvidenceHash',
        );
        const userRearmEvidenceHash = sha256Digest(
            input.userRearmEvidenceHash,
            'rearm.userRearmEvidenceHash',
        );
        const riskRevision = boundedToken(
            input.riskRevision,
            'rearm.riskRevision',
        );
        const expectedIntentRevision = safeInteger(
            input.expectedIntentRevision,
            'rearm.expectedIntentRevision',
        );
        if (
            repositoryMetaValue(database, 'current_runtime_epoch_id') !==
                runtimeEpochId ||
            repositoryMetaValue(database, 'current_sender_fence') !== senderFence ||
            repositoryMetaValue(database, 'current_api_generation') !== apiGeneration
        ) {
            throw new Error('prepared intent re-arm does not target current runtime epoch');
        }
        if (currentApiGenerationIsInvalidated(database)) {
            throw new Error(
                'prepared intent re-arm is blocked because the API generation was invalidated',
            );
        }
        if (currentRuntimeContinuityIsInvalidated(database)) {
            throw new Error(
                'prepared intent re-arm is blocked because runtime continuity was invalidated',
            );
        }
        const runtime = database
            .prepare(`
                SELECT state, reconciliation_evidence_hash
                  FROM runtime_epochs
                 WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
            `)
            .get(runtimeEpochId, senderFence, apiGeneration);
        if (!runtime || !['reconciling', 'ready'].includes(runtime.state)) {
            throw new Error('prepared intent re-arm requires current reconciling or ready epoch');
        }
        if (
            runtime.state === 'ready' &&
            runtime.reconciliation_evidence_hash !== reconciliationEvidenceHash
        ) {
            throw new Error('prepared intent re-arm reconciliation evidence is stale');
        }
        const confirmationTarget = database.prepare(`
            SELECT intents.strategy_id, strategies.confirmation_snapshot_hash
              FROM order_intents AS intents
              JOIN strategies ON strategies.strategy_id=intents.strategy_id
             WHERE intents.intent_id=?
        `).get(intentId);
        if (!confirmationTarget) {
            throw new Error('prepared intent re-arm target does not exist');
        }
        if (
            confirmationTarget.confirmation_snapshot_hash !==
            confirmationSnapshotHash
        ) {
            throw new Error('prepared intent re-arm confirmation is stale');
        }
        assertCanonicalConfirmationCurrent(database, {
            strategyId: confirmationTarget.strategy_id,
            snapshotHash: confirmationSnapshotHash,
            runtimeEpochId,
            senderFence,
            apiGeneration,
            nowEpochMs: canonicalConfirmationClockNowEpochMs(now),
        });
        const replay = database
            .prepare(`
                SELECT rearm_authorization_id, intent_id, runtime_epoch_id,
                       sender_fence, api_generation, authorized_intent_revision,
                       confirmation_snapshot_hash, risk_revision,
                       reconciliation_evidence_hash, user_rearm_evidence_hash,
                       state, revision
                  FROM intent_rearm_authorizations
                 WHERE rearm_request_id=?
            `)
            .get(rearmRequestId);
        if (replay) {
            if (
                replay.rearm_authorization_id !== rearmAuthorizationId ||
                replay.intent_id !== intentId ||
                replay.runtime_epoch_id !== runtimeEpochId ||
                replay.sender_fence !== senderFence ||
                replay.api_generation !== apiGeneration ||
                replay.confirmation_snapshot_hash !== confirmationSnapshotHash ||
                replay.risk_revision !== riskRevision ||
                replay.reconciliation_evidence_hash !==
                    reconciliationEvidenceHash ||
                replay.user_rearm_evidence_hash !== userRearmEvidenceHash
            ) {
                throw new Error('prepared intent re-arm request replay mismatch');
            }
            return Object.freeze({
                rearmAuthorizationId,
                intentId,
                runtimeEpochId,
                state: replay.state,
                intentRevision: replay.authorized_intent_revision,
                rearmRevision: replay.revision,
                replayed: true,
            });
        }
        const intent = database
            .prepare(`
                SELECT intents.state, intents.revision,
                       intents.adapter_authority_granted,
                       strategies.confirmation_snapshot_hash,
                       strategies.state AS strategy_state
                  FROM order_intents AS intents
                  JOIN strategies ON strategies.strategy_id=intents.strategy_id
                 WHERE intents.intent_id=?
            `)
            .get(intentId);
        if (!intent) throw new Error('prepared intent re-arm target does not exist');
        if (intent.confirmation_snapshot_hash !== confirmationSnapshotHash) {
            throw new Error('prepared intent re-arm confirmation is stale');
        }
        if (
            !['observing', 'monitoring', 'recovery'].includes(
                intent.strategy_state,
            )
        ) {
            throw new Error(
                'prepared intent re-arm requires an observing, monitoring, or recovery strategy',
            );
        }
        if (
            intent.state !== 'prepared' ||
            intent.adapter_authority_granted !== 0 ||
            intent.revision !== expectedIntentRevision
        ) {
            throw new Error('prepared intent re-arm lost its intent CAS');
        }
        const existingForEpoch = database
            .prepare(`
                SELECT rearm_authorization_id
                  FROM intent_rearm_authorizations
                 WHERE intent_id=? AND runtime_epoch_id=?
            `)
            .get(intentId, runtimeEpochId);
        if (existingForEpoch) {
            throw new Error('prepared intent already has a re-arm decision for this epoch');
        }
        const intentResult = database
            .prepare(`
                UPDATE order_intents
                   SET updated_at_epoch_ms=?, revision=revision+1
                 WHERE intent_id=? AND state='prepared'
                   AND adapter_authority_granted=0 AND revision=?
            `)
            .run(now, intentId, expectedIntentRevision);
        if (Number(intentResult.changes) !== 1) {
            throw new Error('prepared intent re-arm lost its intent CAS');
        }
        const authorizedIntentRevision = expectedIntentRevision + 1;
        database
            .prepare(`
                INSERT INTO intent_rearm_authorizations(
                    rearm_authorization_id, intent_id, runtime_epoch_id,
                    sender_fence, api_generation, rearm_request_id,
                    authorized_intent_revision, confirmation_snapshot_hash,
                    risk_revision, reconciliation_evidence_hash,
                    user_rearm_evidence_hash, state, authorized_at_epoch_ms,
                    revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, 0)
            `)
            .run(
                rearmAuthorizationId,
                intentId,
                runtimeEpochId,
                senderFence,
                apiGeneration,
                rearmRequestId,
                authorizedIntentRevision,
                confirmationSnapshotHash,
                riskRevision,
                reconciliationEvidenceHash,
                userRearmEvidenceHash,
                now,
            );
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: intentId,
            revision: authorizedIntentRevision,
            reasonCode: 'PREPARED_INTENT_USER_REARM_AUTHORIZED',
            summaryCode: 'prepared_intent_user_rearmed',
            nowEpochMs: now,
            payloadHash: userRearmEvidenceHash,
            eventSuffix: `rearm-${rearmAuthorizationId}-authorized`,
        });
        return Object.freeze({
            rearmAuthorizationId,
            intentId,
            runtimeEpochId,
            state: 'active',
            intentRevision: authorizedIntentRevision,
            rearmRevision: 0,
            replayed: false,
        });
    };
    return withinExistingTransaction ? mutate() : transaction(database, mutate);
}

function markRuntimeEpochReady(database, input) {
    const now = safeInteger(
        input.nowEpochMs ?? Date.now(),
        'runtimeReady.nowEpochMs',
    );
    return transaction(database, () => {
        const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
        const senderFence = boundedToken(input.senderFence, 'senderFence');
        const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
        if (
            repositoryMetaValue(database, 'current_runtime_epoch_id') !==
                runtimeEpochId ||
            repositoryMetaValue(database, 'current_sender_fence') !== senderFence ||
            repositoryMetaValue(database, 'current_api_generation') !== apiGeneration
        ) {
            throw new Error('runtime ready transition does not target the current epoch');
        }
        if (currentApiGenerationIsInvalidated(database)) {
            throw new Error(
                'runtime ready transition is blocked because the API generation was invalidated',
            );
        }
        if (currentRuntimeContinuityIsInvalidated(database)) {
            throw new Error(
                'runtime ready transition is blocked because runtime continuity was invalidated',
            );
        }
        const reconciliationEvidenceHash = sha256Digest(
            input.reconciliationEvidenceHash,
            'reconciliationEvidenceHash',
        );
        if (
            canonicalPnlRequired &&
            configuredTestExposureArbiterHeads.length === 0
        ) {
            assertRuntimeRiskReadinessCurrent(database, {
                apiGeneration,
                now,
                reconciliationEvidenceHash,
                runtimeEpochId,
            });
        }
        const unresolved = database
            .prepare(`
                SELECT
                    (SELECT COUNT(*) FROM order_intents
                      WHERE state IN ('dispatching','reconciling','unknown')) AS intents,
                    (SELECT COUNT(*) FROM activations
                      WHERE state IN ('dispatching','unknown')) AS activations,
                    (SELECT COUNT(*) FROM entry_exposure_reservations
                      WHERE state='unknown') AS reservations,
                    (SELECT COUNT(*) FROM exit_claims
                      WHERE state='unknown') AS exit_claims,
                    (SELECT COUNT(*) FROM safety_blockers
                      WHERE state='open') AS safety_blockers,
                    (SELECT COUNT(*) FROM order_intents AS intents
                      WHERE intents.state='prepared'
                        AND intents.adapter_authority_granted=0
                        AND NOT EXISTS (
                            SELECT 1
                              FROM intent_rearm_authorizations AS rearms
                             WHERE rearms.intent_id=intents.intent_id
                               AND rearms.runtime_epoch_id=?
                               AND rearms.sender_fence=?
                               AND rearms.api_generation=?
                               AND rearms.state='active'
                               AND rearms.authorized_intent_revision=intents.revision
                               AND rearms.reconciliation_evidence_hash=?
                        )) AS prepared_without_current_rearm
            `)
            .get(
                runtimeEpochId,
                senderFence,
                apiGeneration,
                reconciliationEvidenceHash,
            );
        if (Object.values(unresolved ?? {}).some((count) => Number(count) !== 0)) {
            throw new Error('runtime epoch cannot become ready with unresolved blockers');
        }
        const recoveryStrategies = database
            .prepare(`
                SELECT strategy_id, revision, definition_hash
                  FROM strategies
                 WHERE state='recovery'
                   AND NOT EXISTS (
                       SELECT 1
                         FROM order_intents AS intents
                        WHERE intents.strategy_id=strategies.strategy_id
                          AND intents.state NOT IN (
                              'terminal',
                              'cancelled_proven_unsent'
                          )
                   )
                 ORDER BY strategy_id
            `)
            .all();
        const pauseRecoveredStrategy = database.prepare(`
            UPDATE strategies
               SET state='paused', updated_at_epoch_ms=?, revision=revision+1
             WHERE strategy_id=? AND state='recovery' AND revision=?
        `);
        for (const strategy of recoveryStrategies) {
            if (
                Number(
                    pauseRecoveredStrategy.run(
                        now,
                        strategy.strategy_id,
                        strategy.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'strategy recovery reconciliation lost its optimistic revision',
                );
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: strategy.strategy_id,
                revision: strategy.revision + 1,
                reasonCode: 'RECOVERY_RECONCILED_REARM_REQUIRED',
                summaryCode: 'strategy_recovery_reconciled_paused',
                nowEpochMs: now,
                payloadHash: strategy.definition_hash,
                eventSuffix: 'recovery-reconciled-paused',
            });
        }
        const result = database
            .prepare(`
                UPDATE runtime_epochs
                   SET state='ready', reconciliation_evidence_hash=?, revision=revision+1
                 WHERE runtime_epoch_id=? AND state='reconciling' AND revision=?
                   AND sender_fence=? AND api_generation=?
            `)
            .run(
                reconciliationEvidenceHash,
                runtimeEpochId,
                safeInteger(input.expectedRevision, 'expectedRevision'),
                senderFence,
                apiGeneration,
            );
        if (Number(result.changes) !== 1) {
            throw new Error('runtime ready transition lost its fenced CAS');
        }
        bindLifecycleReconciliationToCurrentSideEffects(database);
        insertTransitionJournalEvent(database, {
            entityKind: 'runtime_epoch',
            entityId: runtimeEpochId,
            revision: input.expectedRevision + 1,
            reasonCode: 'RUNTIME_EPOCH_RECONCILIATION_READY',
            summaryCode: 'runtime_epoch_ready',
            nowEpochMs: now,
            payloadHash: reconciliationEvidenceHash,
            eventSuffix: 'ready',
        });
        return Object.freeze({
            runtimeEpochId,
            state: 'ready',
            revision: input.expectedRevision + 1,
            pausedRecoveryStrategyIds: Object.freeze(
                recoveryStrategies.map((strategy) => strategy.strategy_id),
            ),
        });
    });
}

function invalidateRuntimeApiGeneration(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    const now = safeInteger(
        input.nowEpochMs,
        'invalidateRuntimeApiGeneration.nowEpochMs',
    );
    return transaction(database, () => {
        const runtimeEpochId = boundedToken(
            input.runtimeEpochId,
            'runtimeEpochId',
        );
        const senderFence = boundedToken(input.senderFence, 'senderFence');
        const apiGeneration = boundedToken(
            input.apiGeneration,
            'apiGeneration',
        );
        const observedApiGeneration = boundedToken(
            input.observedApiGeneration,
            'observedApiGeneration',
        );
        if (observedApiGeneration === apiGeneration) {
            throw new Error(
                'API generation invalidation requires a changed observation',
            );
        }
        if (
            repositoryMetaValue(database, 'current_runtime_epoch_id') !==
                runtimeEpochId ||
            repositoryMetaValue(database, 'current_sender_fence') !== senderFence ||
            repositoryMetaValue(database, 'current_api_generation') !== apiGeneration
        ) {
            throw new Error(
                'API generation invalidation does not target the current runtime fence',
            );
        }
        if (currentApiGenerationIsInvalidated(database)) {
            throw new Error('current API generation was already invalidated');
        }
        const current = database
            .prepare(`
                SELECT state, revision
                  FROM runtime_epochs
                 WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
            `)
            .get(runtimeEpochId, senderFence, apiGeneration);
        if (
            !current ||
            ![
                'starting',
                'observe_only',
                'reconciling',
                'ready',
                'quiescing',
            ].includes(current.state)
        ) {
            throw new Error(
                'API generation invalidation requires a current non-terminal runtime epoch',
            );
        }

        const observedApiGenerationSha256 = sha256Text(observedApiGeneration);
        const invalidationEvidenceHash = sha256Canonical(
            {
                apiGenerationSha256: sha256Text(apiGeneration),
                observedApiGenerationSha256,
                runtimeEpochIdSha256: sha256Text(runtimeEpochId),
                senderFenceSha256: sha256Text(senderFence),
            },
            'API generation invalidation evidence',
        );

        const activeStrategies = database
            .prepare(`
                SELECT strategy_id, strategy_kind, state, revision,
                       definition_hash, confirmation_snapshot_hash
                  FROM strategies
                 WHERE state IN ('observing','monitoring')
                 ORDER BY strategy_id
            `)
            .all();
        const manualInterventionStrategies = activeStrategies.filter(
            (strategy) =>
                strategy.strategy_kind === 'trailing_exit' &&
                strategy.state === 'monitoring',
        );
        const recoveringStrategies = activeStrategies.filter(
            (strategy) =>
                !(
                    strategy.strategy_kind === 'trailing_exit' &&
                    strategy.state === 'monitoring'
                ),
        );
        const enterTrailingManualIntervention = database.prepare(`
            UPDATE strategies
               SET state='manual_intervention', updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE strategy_id=? AND strategy_kind='trailing_exit'
               AND state='monitoring' AND revision=?
        `);
        for (const strategy of manualInterventionStrategies) {
            if (
                Number(
                    enterTrailingManualIntervention.run(
                        now,
                        strategy.strategy_id,
                        strategy.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'trailing generation manual-intervention transition lost its CAS',
                );
            }
            const trailingGapLineageHash = sha256Canonical(
                {
                    schemaVersion:
                        'smart-order-trailing-gap-transition/2026-08-13.1',
                    strategyId: strategy.strategy_id,
                    strategyKind: strategy.strategy_kind,
                    previousState: strategy.state,
                    previousRevision: strategy.revision,
                    definitionHash: strategy.definition_hash,
                    confirmationSnapshotHash:
                        strategy.confirmation_snapshot_hash,
                    observedApiGenerationSha256,
                    gapKind: 'api_generation_change',
                },
                'trailing generation gap durable lineage',
            );
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: strategy.strategy_id,
                revision: strategy.revision + 1,
                reasonCode: 'TRAILING_GAP_EXTREME_UNKNOWN',
                summaryCode:
                    'trailing_strategy_manual_after_api_generation_gap',
                nowEpochMs: now,
                payloadHash: trailingGapLineageHash,
                eventSuffix: 'api-generation-trailing-manual',
            });
            openTrailingGapResolutionCompanions(database, {
                strategy,
                gapEvidenceHash: trailingGapLineageHash,
                nowEpochMs: now,
                eventSuffix: 'api-generation-trailing-manual',
            });
        }
        const recoverStrategy = database.prepare(`
            UPDATE strategies
               SET state='recovery', updated_at_epoch_ms=?, revision=revision+1
             WHERE strategy_id=? AND state=? AND revision=?
        `);
        for (const strategy of recoveringStrategies) {
            if (
                Number(
                    recoverStrategy.run(
                        now,
                        strategy.strategy_id,
                        strategy.state,
                        strategy.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'strategy generation recovery transition lost its CAS',
                );
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: strategy.strategy_id,
                revision: strategy.revision + 1,
                reasonCode: 'RUNTIME_API_GENERATION_CHANGED',
                summaryCode: 'strategy_recovery_after_api_generation_change',
                nowEpochMs: now,
                payloadHash: strategy.definition_hash,
                eventSuffix: 'api-generation-recovery',
            });
        }

        const activeRearms = database
            .prepare(`
                SELECT rearm_authorization_id, intent_id, revision,
                       user_rearm_evidence_hash
                  FROM intent_rearm_authorizations
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state='active'
                 ORDER BY intent_id
            `)
            .all(runtimeEpochId, senderFence, apiGeneration);
        const supersedeRearm = database.prepare(`
            UPDATE intent_rearm_authorizations
               SET state='superseded', revision=revision+1
             WHERE rearm_authorization_id=? AND state='active' AND revision=?
        `);
        for (const rearm of activeRearms) {
            if (
                Number(
                    supersedeRearm.run(
                        rearm.rearm_authorization_id,
                        rearm.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'API generation re-arm supersession lost its CAS',
                );
            }
            const intentRevision = database
                .prepare('SELECT revision FROM order_intents WHERE intent_id=?')
                .get(rearm.intent_id)?.revision;
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: rearm.intent_id,
                revision: safeInteger(intentRevision, 'intentRevision'),
                reasonCode:
                    'PREPARED_INTENT_REARM_SUPERSEDED_BY_API_GENERATION_CHANGE',
                summaryCode: 'prepared_intent_rearm_superseded',
                nowEpochMs: now,
                payloadHash: rearm.user_rearm_evidence_hash,
                eventSuffix: `api-generation-${rearm.rearm_authorization_id}`,
            });
        }

        const dispatchingIntents = database
            .prepare(`
                SELECT intents.intent_id, intents.activation_id,
                       intents.payload_hash, intents.revision,
                       activations.evidence_hash AS activation_evidence_hash,
                       activations.revision AS activation_revision,
                       reservations.reservation_id,
                       reservations.policy_hash AS reservation_policy_hash,
                       reservations.revision AS reservation_revision
                  FROM order_intents AS intents
                  JOIN activations
                    ON activations.activation_id=intents.activation_id
                  LEFT JOIN entry_exposure_reservations AS reservations
                    ON reservations.intent_id=intents.intent_id
                 WHERE intents.state='dispatching'
                   AND intents.runtime_epoch_id=?
                   AND intents.sender_fence=?
                   AND intents.api_generation=?
                 ORDER BY intents.intent_id
            `)
            .all(runtimeEpochId, senderFence, apiGeneration);
        const recoverIntent = database.prepare(`
            UPDATE order_intents
               SET state='reconciling',
                   terminal_outcome='api_generation_changed_after_dispatch_fence',
                   updated_at_epoch_ms=?, revision=revision+1
             WHERE intent_id=? AND state='dispatching' AND revision=?
               AND runtime_epoch_id=? AND sender_fence=? AND api_generation=?
        `);
        const recoverActivation = database.prepare(`
            UPDATE activations
               SET state='unknown', updated_at_epoch_ms=?, revision=revision+1
             WHERE activation_id=? AND state='dispatching' AND revision=?
        `);
        const recoverReservation = database.prepare(`
            UPDATE entry_exposure_reservations
               SET state='unknown', updated_at_epoch_ms=?, revision=revision+1
             WHERE reservation_id=? AND state='reserved' AND revision=?
        `);
        for (const intent of dispatchingIntents) {
            if (
                Number(
                    recoverIntent.run(
                        now,
                        intent.intent_id,
                        intent.revision,
                        runtimeEpochId,
                        senderFence,
                        apiGeneration,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'API generation intent recovery transition lost its CAS',
                );
            }
            if (
                Number(
                    recoverActivation.run(
                        now,
                        intent.activation_id,
                        intent.activation_revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'API generation activation recovery transition lost its CAS',
                );
            }
            if (
                intent.reservation_id !== null &&
                Number(
                    recoverReservation.run(
                        now,
                        intent.reservation_id,
                        intent.reservation_revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'API generation reservation recovery transition lost its CAS',
                );
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: intent.intent_id,
                revision: intent.revision + 1,
                reasonCode: 'INTENT_RECONCILING_AFTER_API_GENERATION_CHANGE',
                summaryCode: 'intent_reconciling_after_api_generation_change',
                nowEpochMs: now,
                payloadHash: intent.payload_hash,
                eventSuffix: 'api-generation-reconciling',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'activation',
                entityId: intent.activation_id,
                revision: intent.activation_revision + 1,
                reasonCode: 'ACTIVATION_UNKNOWN_AFTER_API_GENERATION_CHANGE',
                summaryCode: 'activation_unknown_after_api_generation_change',
                nowEpochMs: now,
                payloadHash: intent.activation_evidence_hash,
                eventSuffix: 'api-generation-unknown',
            });
            if (intent.reservation_id !== null) {
                insertTransitionJournalEvent(database, {
                    entityKind: 'entry_exposure_reservation',
                    entityId: intent.reservation_id,
                    revision: intent.reservation_revision + 1,
                    reasonCode:
                        'RESERVATION_UNKNOWN_AFTER_API_GENERATION_CHANGE',
                    summaryCode:
                        'reservation_unknown_after_api_generation_change',
                    nowEpochMs: now,
                    payloadHash: intent.reservation_policy_hash,
                    eventSuffix: 'api-generation-unknown',
                });
            }
        }

        const gateManifests = database
            .prepare(`
                SELECT manifest_id, manifest_sha256, revision
                  FROM gate_manifests
                 WHERE state IN ('observe_only','eligible')
                 ORDER BY manifest_id
            `)
            .all();
        const invalidateGateManifestsResult = database
            .prepare(`
                UPDATE gate_manifests
                   SET state='invalidated', invalidated_at_epoch_ms=?,
                       invalidation_reason='api_generation_changed',
                       revision=revision+1
                 WHERE state IN ('observe_only','eligible')
            `)
            .run(now);
        if (
            Number(invalidateGateManifestsResult.changes) !== gateManifests.length
        ) {
            throw new Error('API generation gate invalidation lost its CAS');
        }
        for (const manifest of gateManifests) {
            insertTransitionJournalEvent(database, {
                entityKind: 'gate_manifest',
                entityId: manifest.manifest_id,
                revision: manifest.revision + 1,
                reasonCode: 'GATE_MANIFEST_API_GENERATION_INVALIDATED',
                summaryCode: 'gate_manifest_invalidated',
                nowEpochMs: now,
                payloadHash: manifest.manifest_sha256,
                eventSuffix: 'api-generation-invalidated',
            });
        }

        const runtimeResult = database
            .prepare(`
                UPDATE runtime_epochs
                   SET state='reconciling', reconciliation_evidence_hash=NULL,
                       revision=revision+1
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state=? AND revision=?
            `)
            .run(
                runtimeEpochId,
                senderFence,
                apiGeneration,
                current.state,
                current.revision,
            );
        if (Number(runtimeResult.changes) !== 1) {
            throw new Error(
                'API generation runtime invalidation lost its fenced CAS',
            );
        }
        setRepositoryMeta(
            database,
            API_GENERATION_INVALIDATED_SHA256_META_KEY,
            observedApiGenerationSha256,
        );
        deleteRepositoryMeta(database, 'current_lifecycle_operation');
        deleteRepositoryMeta(database, 'current_lifecycle_operation_id');
        insertTransitionJournalEvent(database, {
            entityKind: 'runtime_epoch',
            entityId: runtimeEpochId,
            revision: current.revision + 1,
            reasonCode: 'RUNTIME_API_GENERATION_SUPERSEDED',
            summaryCode: 'runtime_reconciling_after_api_generation_change',
            nowEpochMs: now,
            payloadHash: invalidationEvidenceHash,
            eventSuffix: 'api-generation-invalidated',
        });
        return Object.freeze({
            runtimeEpochId,
            state: 'reconciling',
            previousState: current.state,
            revision: current.revision + 1,
            reason: 'generation_invalidated',
            observedApiGenerationSha256,
            recoveryStrategyIds: Object.freeze(
                recoveringStrategies.map((strategy) => strategy.strategy_id),
            ),
            manualInterventionStrategyIds: Object.freeze(
                manualInterventionStrategies.map(
                    (strategy) => strategy.strategy_id,
                ),
            ),
            supersededRearmIntentIds: Object.freeze(
                activeRearms.map((rearm) => rearm.intent_id),
            ),
            recoveredIntentIds: Object.freeze(
                dispatchingIntents.map((intent) => intent.intent_id),
            ),
            invalidatedGateManifestCount: gateManifests.length,
            automaticRedispatchAllowed: false,
            requiresProcessRestart: true,
        });
    });
}

function invalidateRuntimeContinuityGap(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'runtimeEpochId',
            'senderFence',
            'apiGeneration',
            'signalSha256',
            'reasonCodes',
            'nowEpochMs',
        ])
    ) {
        throw new TypeError(
            'runtime continuity invalidation input must contain only canonical digests and reason codes',
        );
    }
    const now = safeInteger(
        input.nowEpochMs,
        'invalidateRuntimeContinuityGap.nowEpochMs',
    );
    return transaction(database, () => {
        const runtimeEpochId = boundedToken(
            input.runtimeEpochId,
            'runtimeEpochId',
        );
        const senderFence = boundedToken(input.senderFence, 'senderFence');
        const apiGeneration = boundedToken(
            input.apiGeneration,
            'apiGeneration',
        );
        const signalSha256 = sha256Digest(
            input.signalSha256,
            'runtime continuity signalSha256',
        );
        const reasonCodes = canonicalRuntimeContinuityReasonCodes(
            input.reasonCodes,
            'runtime continuity reasonCodes',
        );
        if (
            repositoryMetaValue(database, 'current_runtime_epoch_id') !==
                runtimeEpochId ||
            repositoryMetaValue(database, 'current_sender_fence') !== senderFence ||
            repositoryMetaValue(database, 'current_api_generation') !== apiGeneration
        ) {
            throw new Error(
                'runtime continuity invalidation does not target the current runtime fence',
            );
        }
        if (currentApiGenerationIsInvalidated(database)) {
            throw new Error(
                'runtime continuity invalidation is blocked because the API generation was invalidated',
            );
        }
        const priorInvalidation = currentRuntimeContinuityInvalidation(database);
        if (priorInvalidation) {
            if (
                priorInvalidation.signalSha256 !== signalSha256 ||
                JSON.stringify(priorInvalidation.reasonCodes) !==
                    JSON.stringify(reasonCodes)
            ) {
                throw new Error(
                    'runtime continuity was already invalidated by a different signal',
                );
            }
            return priorInvalidation.result;
        }
        const current = database
            .prepare(`
                SELECT state, revision
                  FROM runtime_epochs
                 WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
            `)
            .get(runtimeEpochId, senderFence, apiGeneration);
        if (
            !current ||
            ![
                'starting',
                'observe_only',
                'reconciling',
                'ready',
                'quiescing',
            ].includes(current.state)
        ) {
            throw new Error(
                'runtime continuity invalidation requires a current non-terminal runtime epoch',
            );
        }

        const invalidationEvidenceHash = sha256Canonical(
            {
                schemaVersion: RUNTIME_CONTINUITY_INVALIDATION_SCHEMA_VERSION,
                signalSha256,
                reasonCodes,
                apiGenerationSha256: sha256Text(apiGeneration),
                runtimeEpochIdSha256: sha256Text(runtimeEpochId),
                senderFenceSha256: sha256Text(senderFence),
            },
            'runtime continuity invalidation evidence',
        );

        const activeStrategies = database
            .prepare(`
                SELECT strategy_id, strategy_kind, state, revision,
                       definition_hash, confirmation_snapshot_hash
                  FROM strategies
                 WHERE state IN ('observing','monitoring')
                 ORDER BY strategy_id
            `)
            .all();
        // A monitoring trailing strategy is the durable indication that the
        // Runtime is actively maintaining its favorable extreme. Any Runtime
        // observation gap makes that extreme unknowable and therefore enters
        // manual intervention. Observing (not-yet-monitoring) trailing
        // strategies still use ordinary recovery, and a browser-only/UI
        // disconnect never reaches this Runtime continuity transaction.
        const manualInterventionStrategies = activeStrategies.filter(
            (strategy) =>
                strategy.strategy_kind === 'trailing_exit' &&
                strategy.state === 'monitoring',
        );
        const recoveringStrategies = activeStrategies.filter(
            (strategy) =>
                !(
                    strategy.strategy_kind === 'trailing_exit' &&
                    strategy.state === 'monitoring'
                ),
        );
        const enterTrailingManualIntervention = database.prepare(`
            UPDATE strategies
               SET state='manual_intervention', updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE strategy_id=? AND strategy_kind='trailing_exit'
               AND state='monitoring' AND revision=?
        `);
        for (const strategy of manualInterventionStrategies) {
            if (
                Number(
                    enterTrailingManualIntervention.run(
                        now,
                        strategy.strategy_id,
                        strategy.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'trailing continuity manual-intervention transition lost its CAS',
                );
            }
            const trailingGapLineageHash = sha256Canonical(
                {
                    schemaVersion:
                        'smart-order-trailing-gap-transition/2026-08-13.1',
                    strategyId: strategy.strategy_id,
                    strategyKind: strategy.strategy_kind,
                    previousState: strategy.state,
                    previousRevision: strategy.revision,
                    definitionHash: strategy.definition_hash,
                    confirmationSnapshotHash:
                        strategy.confirmation_snapshot_hash,
                    signalSha256,
                    reasonCodes,
                },
                'trailing gap durable lineage',
            );
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: strategy.strategy_id,
                revision: strategy.revision + 1,
                reasonCode: 'TRAILING_GAP_EXTREME_UNKNOWN',
                summaryCode:
                    'trailing_strategy_manual_after_runtime_observation_gap',
                nowEpochMs: now,
                payloadHash: trailingGapLineageHash,
                eventSuffix: 'runtime-continuity-trailing-manual',
            });
            openTrailingGapResolutionCompanions(database, {
                strategy,
                gapEvidenceHash: trailingGapLineageHash,
                nowEpochMs: now,
                eventSuffix: 'runtime-continuity-trailing-manual',
            });
        }
        const recoverStrategy = database.prepare(`
            UPDATE strategies
               SET state='recovery', updated_at_epoch_ms=?, revision=revision+1
             WHERE strategy_id=? AND state=? AND revision=?
        `);
        for (const strategy of recoveringStrategies) {
            if (
                Number(
                    recoverStrategy.run(
                        now,
                        strategy.strategy_id,
                        strategy.state,
                        strategy.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'strategy continuity recovery transition lost its CAS',
                );
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: strategy.strategy_id,
                revision: strategy.revision + 1,
                reasonCode: 'READINESS_LOST_RECONCILIATION_REQUIRED',
                summaryCode: 'strategy_recovery_after_runtime_continuity_gap',
                nowEpochMs: now,
                payloadHash: strategy.definition_hash,
                eventSuffix: 'runtime-continuity-recovery',
            });
        }

        const activeRearms = database
            .prepare(`
                SELECT rearm_authorization_id, intent_id, revision,
                       user_rearm_evidence_hash
                  FROM intent_rearm_authorizations
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state='active'
                 ORDER BY intent_id
            `)
            .all(runtimeEpochId, senderFence, apiGeneration);
        const supersedeRearm = database.prepare(`
            UPDATE intent_rearm_authorizations
               SET state='superseded', revision=revision+1
             WHERE rearm_authorization_id=? AND state='active' AND revision=?
        `);
        for (const rearm of activeRearms) {
            if (
                Number(
                    supersedeRearm.run(
                        rearm.rearm_authorization_id,
                        rearm.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'runtime continuity re-arm supersession lost its CAS',
                );
            }
            const intentRevision = database
                .prepare('SELECT revision FROM order_intents WHERE intent_id=?')
                .get(rearm.intent_id)?.revision;
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: rearm.intent_id,
                revision: safeInteger(intentRevision, 'intentRevision'),
                reasonCode:
                    'PREPARED_INTENT_REARM_SUPERSEDED_BY_RUNTIME_CONTINUITY_GAP',
                summaryCode: 'prepared_intent_rearm_superseded',
                nowEpochMs: now,
                payloadHash: rearm.user_rearm_evidence_hash,
                eventSuffix: `runtime-continuity-${rearm.rearm_authorization_id}`,
            });
        }

        const dispatchingIntents = database
            .prepare(`
                SELECT intents.intent_id, intents.activation_id,
                       intents.payload_hash, intents.revision,
                       activations.evidence_hash AS activation_evidence_hash,
                       activations.revision AS activation_revision,
                       reservations.reservation_id,
                       reservations.policy_hash AS reservation_policy_hash,
                       reservations.revision AS reservation_revision
                  FROM order_intents AS intents
                  JOIN activations
                    ON activations.activation_id=intents.activation_id
                  LEFT JOIN entry_exposure_reservations AS reservations
                    ON reservations.intent_id=intents.intent_id
                 WHERE intents.state='dispatching'
                   AND intents.runtime_epoch_id=?
                   AND intents.sender_fence=?
                   AND intents.api_generation=?
                 ORDER BY intents.intent_id
            `)
            .all(runtimeEpochId, senderFence, apiGeneration);
        const recoverIntent = database.prepare(`
            UPDATE order_intents
               SET state='reconciling',
                   terminal_outcome='runtime_continuity_gap_after_dispatch_fence',
                   updated_at_epoch_ms=?, revision=revision+1
             WHERE intent_id=? AND state='dispatching' AND revision=?
               AND runtime_epoch_id=? AND sender_fence=? AND api_generation=?
        `);
        const recoverActivation = database.prepare(`
            UPDATE activations
               SET state='unknown', updated_at_epoch_ms=?, revision=revision+1
             WHERE activation_id=? AND state='dispatching' AND revision=?
        `);
        const recoverReservation = database.prepare(`
            UPDATE entry_exposure_reservations
               SET state='unknown', updated_at_epoch_ms=?, revision=revision+1
             WHERE reservation_id=? AND state='reserved' AND revision=?
        `);
        for (const intent of dispatchingIntents) {
            if (
                Number(
                    recoverIntent.run(
                        now,
                        intent.intent_id,
                        intent.revision,
                        runtimeEpochId,
                        senderFence,
                        apiGeneration,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'runtime continuity intent recovery transition lost its CAS',
                );
            }
            if (
                Number(
                    recoverActivation.run(
                        now,
                        intent.activation_id,
                        intent.activation_revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'runtime continuity activation recovery transition lost its CAS',
                );
            }
            if (
                intent.reservation_id !== null &&
                Number(
                    recoverReservation.run(
                        now,
                        intent.reservation_id,
                        intent.reservation_revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error(
                    'runtime continuity reservation recovery transition lost its CAS',
                );
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: intent.intent_id,
                revision: intent.revision + 1,
                reasonCode: 'INTENT_RECONCILING_AFTER_RUNTIME_CONTINUITY_GAP',
                summaryCode: 'intent_reconciling_after_runtime_continuity_gap',
                nowEpochMs: now,
                payloadHash: intent.payload_hash,
                eventSuffix: 'runtime-continuity-reconciling',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'activation',
                entityId: intent.activation_id,
                revision: intent.activation_revision + 1,
                reasonCode: 'ACTIVATION_UNKNOWN_AFTER_RUNTIME_CONTINUITY_GAP',
                summaryCode: 'activation_unknown_after_runtime_continuity_gap',
                nowEpochMs: now,
                payloadHash: intent.activation_evidence_hash,
                eventSuffix: 'runtime-continuity-unknown',
            });
            if (intent.reservation_id !== null) {
                insertTransitionJournalEvent(database, {
                    entityKind: 'entry_exposure_reservation',
                    entityId: intent.reservation_id,
                    revision: intent.reservation_revision + 1,
                    reasonCode:
                        'RESERVATION_UNKNOWN_AFTER_RUNTIME_CONTINUITY_GAP',
                    summaryCode:
                        'reservation_unknown_after_runtime_continuity_gap',
                    nowEpochMs: now,
                    payloadHash: intent.reservation_policy_hash,
                    eventSuffix: 'runtime-continuity-unknown',
                });
            }
        }

        const gateManifests = database
            .prepare(`
                SELECT manifest_id, manifest_sha256, revision
                  FROM gate_manifests
                 WHERE state IN ('observe_only','eligible')
                 ORDER BY manifest_id
            `)
            .all();
        const invalidateGateManifestsResult = database
            .prepare(`
                UPDATE gate_manifests
                   SET state='invalidated', invalidated_at_epoch_ms=?,
                       invalidation_reason='runtime_continuity_gap',
                       revision=revision+1
                 WHERE state IN ('observe_only','eligible')
            `)
            .run(now);
        if (
            Number(invalidateGateManifestsResult.changes) !== gateManifests.length
        ) {
            throw new Error('runtime continuity gate invalidation lost its CAS');
        }
        for (const manifest of gateManifests) {
            insertTransitionJournalEvent(database, {
                entityKind: 'gate_manifest',
                entityId: manifest.manifest_id,
                revision: manifest.revision + 1,
                reasonCode: 'GATE_MANIFEST_RUNTIME_CONTINUITY_INVALIDATED',
                summaryCode: 'gate_manifest_invalidated',
                nowEpochMs: now,
                payloadHash: manifest.manifest_sha256,
                eventSuffix: 'runtime-continuity-invalidated',
            });
        }

        const runtimeResult = database
            .prepare(`
                UPDATE runtime_epochs
                   SET state='reconciling', reconciliation_evidence_hash=NULL,
                       revision=revision+1
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state=? AND revision=?
            `)
            .run(
                runtimeEpochId,
                senderFence,
                apiGeneration,
                current.state,
                current.revision,
            );
        if (Number(runtimeResult.changes) !== 1) {
            throw new Error(
                'runtime continuity invalidation lost its fenced CAS',
            );
        }
        deleteRepositoryMeta(database, 'current_lifecycle_operation');
        deleteRepositoryMeta(database, 'current_lifecycle_operation_id');
        const result = Object.freeze({
            state: 'reconciling',
            previousState: current.state,
            revision: current.revision + 1,
            reason: 'continuity_gap_invalidated',
            continuitySignalSha256: signalSha256,
            reasonCodes,
            recoveryStrategyCount: recoveringStrategies.length,
            manualInterventionStrategyCount:
                manualInterventionStrategies.length,
            supersededRearmCount: activeRearms.length,
            recoveredIntentCount: dispatchingIntents.length,
            invalidatedGateManifestCount: gateManifests.length,
            automaticRedispatchAllowed: false,
            userRearmRequiredAfterReconciliation: true,
            requiresProcessRestart: false,
        });
        setRepositoryMeta(
            database,
            RUNTIME_CONTINUITY_INVALIDATION_META_KEY,
            canonicalJson(
                {
                    schemaVersion:
                        RUNTIME_CONTINUITY_INVALIDATION_SCHEMA_VERSION,
                    signalSha256,
                    reasonCodes,
                    invalidatedAtEpochMs: now,
                    result,
                },
                'runtime continuity invalidation metadata',
            ),
        );
        insertTransitionJournalEvent(database, {
            entityKind: 'runtime_epoch',
            entityId: runtimeEpochId,
            revision: current.revision + 1,
            reasonCode: 'RUNTIME_RECONCILIATION_REQUIRED',
            summaryCode: 'runtime_reconciling_after_continuity_gap',
            nowEpochMs: now,
            payloadHash: invalidationEvidenceHash,
            eventSuffix: 'runtime-continuity-invalidated',
        });
        return result;
    });
}

const RUNTIME_LIFECYCLE_OPERATIONS = new Set(
    SMART_ORDER_LIFECYCLE_OPERATIONS,
);

function runtimeLifecycleOperation(value) {
    const operation = boundedToken(value, 'lifecycle.operation');
    if (!RUNTIME_LIFECYCLE_OPERATIONS.has(operation)) {
        throw new TypeError('runtime lifecycle operation is not supported');
    }
    return operation;
}

function quiesceRuntimeEpoch(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    verifyRepository(database);
    const now = safeInteger(input.nowEpochMs, 'runtimeQuiesce.nowEpochMs');
    return transaction(database, () => {
        const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
        const senderFence = boundedToken(input.senderFence, 'senderFence');
        const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
        const operation = runtimeLifecycleOperation(input.operation);
        safeInteger(input.expectedRevision, 'expectedRevision');
        if (
            repositoryMetaValue(database, 'current_runtime_epoch_id') !==
                runtimeEpochId ||
            repositoryMetaValue(database, 'current_sender_fence') !== senderFence ||
            repositoryMetaValue(database, 'current_api_generation') !== apiGeneration
        ) {
            throw new Error('runtime quiesce does not target the current epoch');
        }
        const current = database
            .prepare(`
                SELECT state, revision
                  FROM runtime_epochs
                 WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
            `)
            .get(runtimeEpochId, senderFence, apiGeneration);
        if (!current) throw new Error('runtime quiesce lost its fenced epoch');
        const sourceRevision = current.revision;
        setRepositoryMeta(
            database,
            LIFECYCLE_MUTATION_FENCE_META_KEY,
            operation,
        );
        if (current.state === 'quiescing') {
            const currentOperation = repositoryMetaValue(
                database,
                'current_lifecycle_operation',
            );
            const lifecycleOperationId = repositoryMetaValue(
                database,
                'current_lifecycle_operation_id',
            );
            if (currentOperation !== operation) {
                throw new Error(
                    'runtime quiesce operation conflicts with the durable request',
                );
            }
            sha256Digest(
                lifecycleOperationId,
                'current lifecycle operation identity',
            );
            const lifecycle = lifecycleProjection(database, { verify: false });
            const selectedDrain = selectSmartOrderLifecycleDrainProjection(
                lifecycle,
                operation,
            );
            const drainAllowed = selectedDrain.allowed;
            const selectedBlockerCount = selectedDrain.blockerCount;
            return Object.freeze({
                runtimeEpochId,
                operation,
                state: 'quiescing',
                revision: current.revision,
                replayed: true,
                pausedStrategyCount: 0,
                supersededRearmCount: 0,
                drainAllowed,
                selectedBlockerCount,
                lifecycle,
            });
        }
        if (!['reconciling', 'observe_only', 'ready'].includes(current.state)) {
            throw new Error('runtime epoch cannot enter quiescing from its current state');
        }

        const strategies = database
            .prepare(`
                SELECT strategy_id, revision, definition_hash
                  FROM strategies
                 WHERE state IN ('observing','monitoring')
                 ORDER BY strategy_id
            `)
            .all();
        const pauseStrategyForQuiesce = database.prepare(`
            UPDATE strategies
               SET state='paused', updated_at_epoch_ms=?, revision=revision+1
             WHERE strategy_id=? AND state IN ('observing','monitoring')
               AND revision=?
        `);
        for (const strategy of strategies) {
            if (
                Number(
                    pauseStrategyForQuiesce.run(
                        now,
                        strategy.strategy_id,
                        strategy.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error('strategy quiesce pause lost its CAS');
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: strategy.strategy_id,
                revision: strategy.revision + 1,
                reasonCode: 'POLICY_PAUSE_AUTOMATION',
                summaryCode: 'strategy_paused_for_runtime_quiesce',
                nowEpochMs: now,
                payloadHash: strategy.definition_hash,
                eventSuffix: `quiesce-${operation}`,
            });
        }

        const activeRearms = database
            .prepare(`
                SELECT rearm_authorization_id, intent_id, revision,
                       user_rearm_evidence_hash
                  FROM intent_rearm_authorizations
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state='active'
                 ORDER BY rearm_authorization_id
            `)
            .all(runtimeEpochId, senderFence, apiGeneration);
        const supersedeRearm = database.prepare(`
            UPDATE intent_rearm_authorizations
               SET state='superseded', revision=revision+1
             WHERE rearm_authorization_id=? AND state='active' AND revision=?
        `);
        for (const rearm of activeRearms) {
            if (
                Number(
                    supersedeRearm.run(
                        rearm.rearm_authorization_id,
                        rearm.revision,
                    ).changes,
                ) !== 1
            ) {
                throw new Error('runtime quiesce re-arm supersession lost its CAS');
            }
            const intentRevision = database
                .prepare('SELECT revision FROM order_intents WHERE intent_id=?')
                .get(rearm.intent_id)?.revision;
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: rearm.intent_id,
                revision: safeInteger(intentRevision, 'intentRevision'),
                reasonCode: 'PREPARED_INTENT_REARM_SUPERSEDED_BY_RUNTIME_QUIESCE',
                summaryCode: 'prepared_intent_rearm_superseded',
                nowEpochMs: now,
                payloadHash: rearm.user_rearm_evidence_hash,
                eventSuffix: `quiesce-${rearm.rearm_authorization_id}`,
            });
        }

        const result = database
            .prepare(`
                UPDATE runtime_epochs
                   SET state='quiescing', revision=revision+1
                 WHERE runtime_epoch_id=? AND state=? AND revision=?
                   AND sender_fence=? AND api_generation=?
            `)
            .run(
                runtimeEpochId,
                current.state,
                sourceRevision,
                senderFence,
                apiGeneration,
            );
        if (Number(result.changes) !== 1) {
            throw new Error('runtime quiesce transition lost its fenced CAS');
        }
        const lifecycleOperationId = sha256Canonical(
            {
                runtimeEpochId,
                operation,
                sourceRevision,
            },
            'runtime lifecycle operation identity',
        );
        setRepositoryMeta(database, 'current_lifecycle_operation', operation);
        setRepositoryMeta(
            database,
            'current_lifecycle_operation_id',
            lifecycleOperationId,
        );
        const revision = sourceRevision + 1;
        const lifecycleSnapshotHash = sha256Canonical(
            {
                lifecycleOperationId,
                operation,
                previousState: current.state,
                pausedStrategyCount: strategies.length,
                supersededRearmCount: activeRearms.length,
            },
            'runtime quiesce transition',
        );
        insertTransitionJournalEvent(database, {
            entityKind: 'runtime_epoch',
            entityId: runtimeEpochId,
            revision,
            reasonCode: 'RUNTIME_QUIESCE_REQUESTED',
            summaryCode: 'runtime_quiescing',
            nowEpochMs: now,
            payloadHash: lifecycleSnapshotHash,
            eventSuffix: `quiesce-${operation}`,
        });
        const lifecycle = lifecycleProjection(database, { verify: false });
        const selectedDrain = selectSmartOrderLifecycleDrainProjection(
            lifecycle,
            operation,
        );
        const drainAllowed = selectedDrain.allowed;
        const selectedBlockerCount = selectedDrain.blockerCount;
        if (!drainAllowed) {
            const reconciliationEvidenceHash = database
                .prepare(`
                    SELECT reconciliation_evidence_hash
                      FROM runtime_epochs
                     WHERE runtime_epoch_id=?
                `)
                .get(runtimeEpochId)?.reconciliation_evidence_hash;
            const reconciliationCompleted =
                typeof reconciliationEvidenceHash === 'string' &&
                /^sha256:[0-9a-f]{64}$/.test(reconciliationEvidenceHash) &&
                lifecycleReconciliationCoversCurrentSideEffects(database);
            const blockedState = reconciliationCompleted
                ? 'observe_only'
                : 'reconciling';
            const blockedRevision = revision + 1;
            const blockedResult = database
                .prepare(`
                    UPDATE runtime_epochs
                       SET state=?, revision=revision+1
                     WHERE runtime_epoch_id=? AND state='quiescing'
                       AND revision=? AND sender_fence=? AND api_generation=?
                `)
                .run(
                    blockedState,
                    runtimeEpochId,
                    revision,
                    senderFence,
                    apiGeneration,
                );
            if (Number(blockedResult.changes) !== 1) {
                throw new Error(
                    'blocked runtime quiesce fallback lost its fenced CAS',
                );
            }
            deleteRepositoryMeta(database, 'current_lifecycle_operation');
            deleteRepositoryMeta(database, 'current_lifecycle_operation_id');
            insertTransitionJournalEvent(database, {
                entityKind: 'runtime_epoch',
                entityId: runtimeEpochId,
                revision: blockedRevision,
                reasonCode: reconciliationCompleted
                    ? 'RUNTIME_QUIESCE_BLOCKED_OBLIGATION'
                    : 'RUNTIME_RECONCILIATION_REQUIRED',
                summaryCode: reconciliationCompleted
                    ? 'runtime_observe_only_after_blocked_quiesce'
                    : 'runtime_reconciling_after_blocked_quiesce',
                nowEpochMs: now,
                payloadHash: sha256Canonical(
                    {
                        lifecycleOperationId,
                        operation,
                        selectedBlockerCount,
                        state: blockedState,
                    },
                    'blocked runtime quiesce transition',
                ),
                eventSuffix: `quiesce-blocked-${operation}`,
            });
            return Object.freeze({
                runtimeEpochId,
                operation,
                state: blockedState,
                revision: blockedRevision,
                replayed: false,
                pausedStrategyCount: strategies.length,
                supersededRearmCount: activeRearms.length,
                lifecycleSnapshotHash,
                drainAllowed: false,
                selectedBlockerCount,
                lifecycle: lifecycleProjection(database, { verify: false }),
            });
        }
        return Object.freeze({
            runtimeEpochId,
            operation,
            state: 'quiescing',
            revision,
            replayed: false,
            pausedStrategyCount: strategies.length,
            supersededRearmCount: activeRearms.length,
            lifecycleSnapshotHash,
            drainAllowed: true,
            selectedBlockerCount,
            lifecycle,
        });
    });
}

function currentReadySenderMatches(database, input) {
    if (
        currentApiGenerationIsInvalidated(database) ||
        currentRuntimeContinuityIsInvalidated(database)
    ) {
        return false;
    }
    const row = database
        .prepare(`
            SELECT runtime_epoch_id, sender_fence, api_generation
              FROM runtime_epochs WHERE state='ready'
        `)
        .get();
    return Boolean(
        row &&
            repositoryMetaValue(database, 'current_runtime_epoch_id') ===
                input.runtimeEpochId &&
            repositoryMetaValue(database, 'current_sender_fence') ===
                input.senderFence &&
            repositoryMetaValue(database, 'current_api_generation') ===
                input.apiGeneration &&
            repositoryMetaValue(
                database,
                TRADING_SENDER_AUTHORITY_META_KEY,
            ) === runtimeTradingSenderAuthority(input.runtimeEpochId) &&
            row.runtime_epoch_id === input.runtimeEpochId &&
            row.sender_fence === input.senderFence &&
            row.api_generation === input.apiGeneration,
    );
}

function currentRuntimeObserverMatches(database, input) {
    if (currentApiGenerationIsInvalidated(database)) {
        return false;
    }
    const row = database
        .prepare(`
            SELECT runtime_epoch_id, sender_fence, api_generation, state
              FROM runtime_epochs
             WHERE runtime_epoch_id=? AND state IN ('reconciling','ready')
        `)
        .get(input.runtimeEpochId);
    return Boolean(
        row &&
            repositoryMetaValue(database, 'current_runtime_epoch_id') ===
                input.runtimeEpochId &&
            repositoryMetaValue(database, 'current_sender_fence') ===
                input.senderFence &&
            repositoryMetaValue(database, 'current_api_generation') ===
                input.apiGeneration &&
            row.sender_fence === input.senderFence &&
            row.api_generation === input.apiGeneration
    );
}

function stopRuntimeEpoch(database, input) {
    const now = safeInteger(input.nowEpochMs, 'runtimeStop.nowEpochMs');
    return transaction(database, () => {
        const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
        const senderFence = boundedToken(input.senderFence, 'senderFence');
        const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
        const operation = runtimeLifecycleOperation(
            input.operation ?? 'graceful_stop',
        );
        if (
            repositoryMetaValue(database, 'current_runtime_epoch_id') !==
                runtimeEpochId ||
            repositoryMetaValue(database, 'current_sender_fence') !== senderFence ||
            repositoryMetaValue(database, 'current_api_generation') !== apiGeneration
        ) {
            throw new Error('runtime stop does not target the current epoch');
        }
        if (
            repositoryMetaValue(database, 'current_lifecycle_operation') !==
            operation
        ) {
            throw new Error('runtime stop operation does not match durable quiesce');
        }
        const lifecycle = lifecycleProjection(database, { verify: false });
        const drainAllowed = selectSmartOrderLifecycleDrainProjection(
            lifecycle,
            operation,
        ).allowed;
        if (!drainAllowed) {
            const error = new Error('runtime stop blocked by non-terminal side effects');
            error.name = 'RuntimeStopBlockedError';
            throw error;
        }
        const result = database
            .prepare(`
                UPDATE runtime_epochs
                   SET state='stopped', stopped_at_epoch_ms=?, revision=revision+1
                 WHERE runtime_epoch_id=?
                   AND state='quiescing'
                   AND revision=? AND sender_fence=? AND api_generation=?
            `)
            .run(
                now,
                runtimeEpochId,
                safeInteger(input.expectedRevision, 'expectedRevision'),
                senderFence,
                apiGeneration,
            );
        if (Number(result.changes) !== 1) {
            throw new Error('runtime stop transition lost its fenced CAS');
        }
        insertTransitionJournalEvent(database, {
            entityKind: 'runtime_epoch',
            entityId: runtimeEpochId,
            revision: input.expectedRevision + 1,
            reasonCode: 'RUNTIME_EPOCH_STOPPED_WITHOUT_BLOCKERS',
            summaryCode: 'runtime_epoch_stopped',
            nowEpochMs: now,
            payloadHash: sha256Canonical(
                {
                    state: 'stopped',
                    senderFence,
                    apiGeneration,
                    operation,
                    lifecycle,
                },
                'runtime stop transition',
            ),
            eventSuffix: 'stopped',
        });
        deleteRepositoryMeta(database, 'current_runtime_epoch_id');
        deleteRepositoryMeta(database, 'current_sender_fence');
        deleteRepositoryMeta(database, 'current_api_generation');
        deleteRepositoryMeta(database, 'current_lifecycle_operation');
        deleteRepositoryMeta(database, 'current_lifecycle_operation_id');
        setRepositoryMeta(
            database,
            TRADING_SENDER_AUTHORITY_META_KEY,
            NO_TRADING_SENDER_AUTHORITY,
        );
        return Object.freeze({
            runtimeEpochId,
            state: 'stopped',
            revision: input.expectedRevision + 1,
            stoppedAtEpochMs: now,
            operation,
            activeBlockers: Object.freeze([]),
            lifecycle,
        });
    });
}

function assertStrategyCapacity(database, { draft }) {
    const counts = database
        .prepare(`
            SELECT COUNT(*) AS total,
                   SUM(CASE WHEN state='draft' THEN 1 ELSE 0 END) AS drafts
              FROM strategies
        `)
        .get();
    if (Number(counts?.total) >= configuredStrategyMaxRows) {
        throw new Error('strategy repository capacity exhausted');
    }
    if (
        draft === true &&
        Number(counts?.drafts ?? 0) >= configuredDraftStrategyMaxRows
    ) {
        throw new Error('draft strategy repository capacity exhausted');
    }
}

function insertStrategy(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    const now = safeInteger(input.nowEpochMs, 'strategy.nowEpochMs');
    return transaction(database, () => {
        const state = boundedToken(input.state, 'strategy.state');
        assertStrategyCapacity(database, { draft: state === 'draft' });
        const strategyId = boundedToken(input.strategyId, 'strategyId');
        const accountBrokerRef = boundedToken(
            input.accountBrokerRef,
            'accountBrokerRef',
        );
        const accountIdRef = boundedToken(input.accountIdRef, 'accountIdRef');
        const identityGroupId = boundedToken(
            input.identityGroupId,
            'identityGroupId',
        );
        if (state === 'draft') {
            if (
                (accountBrokerRef !== 'draft-unbound' ||
                    accountIdRef !== 'draft-unbound' ||
                    identityGroupId !== 'draft-unbound') &&
                !testOnlyAllowUnverifiedIdentitySeed
            ) {
                throw new Error('draft strategy identity scope must remain unbound');
            }
        } else {
            authenticatedIdentityAdmission(database, input.identityAdmission, {
                accountBrokerRef,
                accountIdRef,
                identityGroupId,
            });
            assertAuthenticatedIdentityStrategyCapacity(
                database,
                identityGroupId,
                { prospectiveStrategyId: strategyId },
            );
        }
        const terminal = ['cancelled', 'completed', 'expired', 'failed'].includes(
            state,
        );
        const terminalAtEpochMs = terminal
            ? safeInteger(input.terminalAtEpochMs, 'strategy.terminalAtEpochMs')
            : null;
        if (!terminal && input.terminalAtEpochMs !== undefined) {
            throw new Error('non-terminal strategy cannot have terminalAtEpochMs');
        }
        database
            .prepare(`
                INSERT INTO strategies(
                    strategy_id, strategy_kind, state, definition_hash,
                    definition_json, account_broker_ref, account_id_ref,
                    identity_group_id, confirmation_snapshot_hash,
                    created_at_epoch_ms, updated_at_epoch_ms,
                    terminal_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            `)
            .run(
                strategyId,
                boundedToken(input.strategyKind, 'strategyKind'),
                state,
                sha256Digest(input.definitionHash, 'definitionHash'),
                canonicalJson(input.definition, 'strategy.definition'),
                accountBrokerRef,
                accountIdRef,
                identityGroupId,
                sha256Digest(input.confirmationSnapshotHash, 'confirmationSnapshotHash'),
                now,
                now,
                terminalAtEpochMs,
                safeInteger(input.revision ?? 0, 'strategy.revision'),
            );
        insertTransitionJournalEvent(database, {
            entityKind: 'strategy',
            entityId: input.strategyId,
            revision: input.revision ?? 0,
            reasonCode: terminal
                ? 'STRATEGY_TERMINAL_IMPORTED'
                : 'STRATEGY_PERSISTED',
            summaryCode: terminal
                ? 'strategy_terminal_persisted'
                : 'strategy_persisted',
            nowEpochMs: now,
            payloadHash: input.definitionHash,
            eventSuffix: terminal ? 'terminal-persisted' : 'persisted',
        });
        return { strategyId: input.strategyId, revision: input.revision ?? 0 };
    });
}

const SMART_ORDER_STRATEGY_KINDS = new Set([
    'quick',
    'good_till',
    'multi_condition',
    'parent_child',
    'stop_take',
    'trailing_exit',
    'scheduled_quantity',
]);
const STRATEGY_TERMINAL_STATES = new Set([
    'cancelled',
    'completed',
    'expired',
    'failed',
]);
const STRATEGY_TERMINAL_HISTORY_REASON_STATES = new Map([
    [
        'STRATEGY_TERMINAL_IMPORTED',
        new Set(['cancelled', 'completed', 'expired', 'failed']),
    ],
    ['STRATEGY_CANCELLED_WITHOUT_SIDE_EFFECTS', new Set(['cancelled'])],
]);
const SMART_ORDER_HISTORY_MAX_ITEMS = 100;

const SMART_ORDER_ACTIVE_ACTIVITY_SCHEMA_VERSION =
    'smart-order-active-activity/2026-08-13.3';
const SMART_ORDER_FORMAL_PROTECTION_VIEW_SCHEMA_VERSION =
    'smart-order-formal-protection-view/2026-08-13.1';
const ACTIVE_ACTIVITY_COMPONENTS = Object.freeze([
    'activations',
    'intents',
    'brokerOrders',
    'protectionCommitments',
    'protectionObligations',
    'entryExposureReservations',
    'exitClaims',
    'resolutionCases',
    'safetyBlockers',
]);
const ACTIVE_ACTIVITY_DISPLAY_PRIORITY = new Map(
    [
        'unknown',
        'unprotected',
        'manual_intervention',
        'reconciling',
        'recovery',
        'cancel_pending',
        'expired_with_obligation',
        'dispatching',
        'part_filled',
        'filled',
        'unfilled',
        'working',
        'submitted',
        'pre_submitted',
        'pending_submit',
        'acknowledged',
        'pending_entry_fill',
        'prepared',
        'triggered',
        'paused',
        'monitoring',
        'observing',
        'draft',
        'completed',
        'cancelled',
        'expired',
    ].map((state, index, states) => [state, states.length - index]),
);

function maskedAccountLabel(row) {
    if (
        row.account_broker_ref === 'draft-unbound' ||
        row.account_id_ref === 'draft-unbound'
    ) {
        return null;
    }
    const compact = String(row.account_id_ref).replace(/[^A-Za-z0-9]/g, '');
    if (compact.length <= 4) return '固定帳號（識別已遮罩）';
    return `固定帳號 ····${compact.slice(-4)}`;
}

function activeActivityDisplayState(component, state) {
    if (component === 'activations') {
        return state === 'candidate' ? 'observing' : state;
    }
    if (component === 'intents') return state;
    if (component === 'brokerOrders') {
        return state;
    }
    if (component === 'protectionCommitments') {
        if (['unknown'].includes(state)) return 'unknown';
        if (['entry_dispatching'].includes(state)) return 'dispatching';
        if (state === 'pending_entry_fill') return 'pending_entry_fill';
        if (['waiting_entry_result', 'materializing'].includes(state)) {
            return 'working';
        }
        return 'prepared';
    }
    if (component === 'protectionObligations') {
        if (state === 'reconciling') return 'reconciling';
        if (state === 'pending_entry' || state === 'pending_entry_fill') {
            return 'pending_entry_fill';
        }
        if (state === 'safety_blocked') return 'unprotected';
        if (state === 'exit_dispatching') return 'dispatching';
        if (state === 'exit_working') return 'working';
        if (state === 'partially_exited') return 'part_filled';
        if (state === 'monitoring') return 'monitoring';
        return 'prepared';
    }
    if (component === 'entryExposureReservations') {
        if (state === 'unknown') return 'unknown';
        if (state === 'dispatching') return 'dispatching';
        if (state === 'working') return 'working';
        return 'prepared';
    }
    if (component === 'exitClaims') {
        if (state === 'unknown') return 'unknown';
        if (state === 'broker_working') return 'working';
        if (state === 'intent_reserved') return 'prepared';
        return 'monitoring';
    }
    if (component === 'resolutionCases' || component === 'safetyBlockers') {
        return 'manual_intervention';
    }
    return state;
}

function activeFormalProtectionView(database, strategyId) {
    const existingPosition = database.prepare(`
        SELECT heads.protection_plan_json, heads.protection_plan_hash,
               heads.formal_protection_json, heads.formal_protection_hash,
               heads.reconciliation_as_of_epoch_ms,
               claims.quantity_shares
          FROM existing_position_protection_heads AS heads
          JOIN exit_claims AS claims
            ON claims.exit_claim_id=heads.exit_claim_id
         WHERE heads.strategy_id=?
         LIMIT 1
    `).get(strategyId);
    if (existingPosition) {
        const plan = canonicalExistingPositionProtectionPlan(
            parseStoredCanonicalObject(
                existingPosition.protection_plan_json,
                'existing-position formal protection plan',
            ),
        );
        const formal = deriveExistingPositionFormalProtection(
            plan.plan,
            existingPosition.quantity_shares,
        );
        if (
            plan.planSha256 !== existingPosition.protection_plan_hash ||
            stableCanonicalJson(formal) !==
                existingPosition.formal_protection_json ||
            sha256Canonical(
                formal,
                'existing-position formal protection',
            ) !== existingPosition.formal_protection_hash
        ) {
            throw new Error(
                'stored existing-position formal protection is not canonical',
            );
        }
        return Object.freeze({
            schemaVersion: SMART_ORDER_FORMAL_PROTECTION_VIEW_SCHEMA_VERSION,
            state: 'formal',
            cumulativeFilledShares: existingPosition.quantity_shares,
            asOfEpochMs: existingPosition.reconciliation_as_of_epoch_ms,
            estimatedBasis: formal.weightedAverageBasis,
            formalBasis: formal.weightedAverageBasis,
            legs: Object.freeze(
                formal.legs.map((leg) => Object.freeze({
                    type: leg.type,
                    comparator: leg.comparator,
                    triggerState: leg.triggerState,
                    triggerBasis: leg.triggerBasis,
                    estimatedTriggerPrice: leg.triggerPrice,
                    formalTriggerPrice: leg.triggerPrice,
                    differsFromEstimate: false,
                })),
            ),
            accountIdentifiersExposed: false,
            entityIdentifiersExposed: false,
        });
    }
    const row = database
        .prepare(`
            SELECT fills.cumulative_filled_shares,
                   fills.fill_notional_minor_units,
                   fills.formal_protection_json,
                   fills.formal_protection_hash,
                   fills.reconciliation_as_of_epoch_ms,
                   intents.payload_json
              FROM protected_entry_fill_heads AS fills
              JOIN order_intents AS intents ON intents.intent_id=fills.intent_id
             WHERE intents.strategy_id=?
               AND fills.cumulative_filled_shares > 0
             ORDER BY fills.updated_at_epoch_ms DESC, fills.intent_id DESC
             LIMIT 1
        `)
        .get(strategyId);
    if (!row) return null;
    if (
        row.formal_protection_json === null ||
        row.formal_protection_hash === null
    ) {
        throw new Error('positive protected entry fill lacks formal protection');
    }
    const intent = canonicalProtectedEntryIntentPayload(
        JSON.parse(row.payload_json),
    );
    const plan = canonicalProtectedEntryPlan(intent.payload.protectionPlan);
    const formal = deriveProtectedEntryFormalProtection(
        plan.plan,
        row.fill_notional_minor_units,
        row.cumulative_filled_shares,
    );
    if (
        stableCanonicalJson(formal) !== row.formal_protection_json ||
        sha256Canonical(formal, 'formal protected entry projection') !==
            row.formal_protection_hash
    ) {
        throw new Error('stored formal protection projection is not canonical');
    }
    const previewPriceMinorUnits = brokerPriceMinorUnits(
        plan.plan.basis.previewPrice,
        'protected entry preview basis',
    );
    const previewNotional =
        BigInt(previewPriceMinorUnits) * BigInt(plan.baseShares);
    if (previewNotional > BigInt(Number.MAX_SAFE_INTEGER)) {
        throw new Error('protected entry preview basis exceeds safe bounds');
    }
    const estimated = deriveProtectedEntryFormalProtection(
        plan.plan,
        Number(previewNotional),
        plan.baseShares,
    );
    const estimatedByType = new Map(
        estimated.legs.map((leg) => [leg.type, leg]),
    );
    const legs = formal.legs.map((leg) => {
        const estimate = estimatedByType.get(leg.type);
        if (!estimate) {
            throw new Error('formal protection leg has no estimate projection');
        }
        const pending = leg.triggerState === 'pending_saved_high';
        return Object.freeze({
            type: leg.type,
            comparator: leg.comparator,
            triggerState: leg.triggerState,
            triggerBasis: leg.triggerBasis,
            estimatedTriggerPrice: estimate.triggerPrice,
            formalTriggerPrice: leg.triggerPrice,
            differsFromEstimate: pending
                ? null
                : stableCanonicalJson(estimate.triggerPrice) !==
                  stableCanonicalJson(leg.triggerPrice),
        });
    });
    return Object.freeze({
        schemaVersion: SMART_ORDER_FORMAL_PROTECTION_VIEW_SCHEMA_VERSION,
        state: legs.some((leg) => leg.triggerState === 'pending_saved_high')
            ? 'pending_saved_high'
            : 'formal',
        cumulativeFilledShares: row.cumulative_filled_shares,
        asOfEpochMs: row.reconciliation_as_of_epoch_ms,
        estimatedBasis: estimated.weightedAverageBasis,
        formalBasis: formal.weightedAverageBasis,
        legs: Object.freeze(legs),
        accountIdentifiersExposed: false,
        entityIdentifiersExposed: false,
    });
}

function activeActivitySummary(database, strategyId, strategyState) {
    const rows = database
        .prepare(`
            SELECT 'activations' AS component, state, COUNT(*) AS count
              FROM activations
             WHERE strategy_id=?
               AND state NOT IN ('filled','cancelled','failed','missed')
             GROUP BY state
            UNION ALL
            SELECT 'intents', state, COUNT(*)
              FROM order_intents
             WHERE strategy_id=?
               AND state NOT IN ('terminal','cancelled_proven_unsent')
             GROUP BY state
            UNION ALL
            SELECT 'brokerOrders', orders.state, COUNT(*)
              FROM broker_orders AS orders
              JOIN order_intents AS intents ON intents.intent_id=orders.intent_id
             WHERE intents.strategy_id=?
               AND orders.state NOT IN ('filled','cancelled','failed','inactive')
             GROUP BY orders.state
            UNION ALL
            SELECT 'brokerOrders', latest.projected_state, 1
              FROM (
                    SELECT CASE
                               WHEN orders.state='filled' THEN 'filled'
                               WHEN orders.filled_shares=0 THEN 'unfilled'
                               ELSE 'part_filled'
                           END AS projected_state
                      FROM broker_orders AS orders
                      JOIN order_intents AS intents
                        ON intents.intent_id=orders.intent_id
                     WHERE intents.strategy_id=?
                       AND orders.state IN (
                           'filled','cancelled','failed','inactive'
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM broker_orders AS active_orders
                             JOIN order_intents AS active_intents
                               ON active_intents.intent_id=active_orders.intent_id
                            WHERE active_intents.strategy_id=?
                              AND active_orders.state NOT IN (
                                  'filled','cancelled','failed','inactive'
                              )
                       )
                     ORDER BY orders.updated_at_epoch_ms DESC,
                              orders.broker_order_id DESC
                     LIMIT 1
              ) AS latest
            UNION ALL
            SELECT 'protectionCommitments', state, COUNT(*)
              FROM pending_protection_commitments
             WHERE strategy_id=?
               AND state NOT IN ('materialized','zero_fill_terminal',
                                 'released_pre_dispatch','released_manual')
             GROUP BY state
            UNION ALL
            SELECT 'protectionObligations', state, COUNT(*)
              FROM protection_obligations
             WHERE strategy_id=? AND terminal_at_epoch_ms IS NULL
             GROUP BY state
            UNION ALL
            SELECT 'entryExposureReservations', state, COUNT(*)
              FROM entry_exposure_reservations
             WHERE strategy_id=? AND state NOT IN ('consumed','released')
             GROUP BY state
            UNION ALL
            SELECT 'exitClaims', claims.state, COUNT(*)
              FROM exit_claims AS claims
              JOIN protection_obligations AS obligations
                ON obligations.obligation_id=claims.obligation_id
             WHERE obligations.strategy_id=?
               AND claims.state NOT IN ('consumed','released')
             GROUP BY claims.state
            UNION ALL
            SELECT 'resolutionCases', cases.state, COUNT(*)
              FROM resolution_cases AS cases
             WHERE cases.strategy_id=? AND cases.state!='resolved'
             GROUP BY cases.state
            UNION ALL
            SELECT 'safetyBlockers', blockers.state, COUNT(*)
              FROM safety_blockers AS blockers
              JOIN resolution_cases AS cases
                ON cases.resolution_case_id=blockers.resolution_case_id
             WHERE cases.strategy_id=? AND blockers.state!='resolved'
             GROUP BY blockers.state
        `)
        .all(
            strategyId,
            strategyId,
            strategyId,
            strategyId,
            strategyId,
            strategyId,
            strategyId,
            strategyId,
            strategyId,
            strategyId,
            strategyId,
        );
    const grouped = new Map(
        ACTIVE_ACTIVITY_COMPONENTS.map((component) => [component, []]),
    );
    for (const row of rows) {
        if (!grouped.has(row.component)) {
            throw new Error('active strategy projection has an unknown component');
        }
        const count = Number(row.count);
        if (!Number.isSafeInteger(count) || count <= 0) {
            throw new Error('active strategy projection count is invalid');
        }
        grouped.get(row.component).push({
            state: boundedToken(row.state, 'activity.state', 80),
            count,
        });
    }
    const summaries = {};
    const displayCandidates = [strategyState];
    for (const component of ACTIVE_ACTIVITY_COMPONENTS) {
        const states = grouped.get(component);
        states.sort((left, right) => {
            const leftPriority =
                ACTIVE_ACTIVITY_DISPLAY_PRIORITY.get(
                    activeActivityDisplayState(component, left.state),
                ) ?? 0;
            const rightPriority =
                ACTIVE_ACTIVITY_DISPLAY_PRIORITY.get(
                    activeActivityDisplayState(component, right.state),
                ) ?? 0;
            return (
                rightPriority - leftPriority ||
                left.state.localeCompare(right.state)
            );
        });
        const count = states.reduce((sum, entry) => sum + entry.count, 0);
        if (!Number.isSafeInteger(count)) {
            throw new Error('active strategy projection count overflowed');
        }
        const state = states[0]?.state ?? null;
        summaries[component] = Object.freeze({ state, count });
        if (state !== null) {
            displayCandidates.push(
                activeActivityDisplayState(component, state),
            );
        }
    }
    const protection = database
        .prepare(`
            SELECT
              (SELECT COUNT(*)
                  FROM protection_obligations AS obligations
                 WHERE obligations.strategy_id=?
                   AND obligations.terminal_at_epoch_ms IS NULL
              ) AS active_obligation_count,
              (SELECT COALESCE(SUM(MAX(
                          0,
                          obligations.filled_shares -
                          obligations.confirmed_exited_shares -
                          COALESCE((
                              SELECT SUM(claims.quantity_shares)
                                FROM exit_claims AS claims
                               WHERE claims.obligation_id=obligations.obligation_id
                                 AND claims.state IN (
                                     'monitoring_reserved',
                                     'intent_reserved',
                                     'broker_working'
                                 )
                          ), 0)
                      )), 0)
                 FROM protection_obligations AS obligations
                WHERE obligations.strategy_id=?
                  AND obligations.terminal_at_epoch_ms IS NULL
              ) AS last_known_unprotected_shares,
              (SELECT MAX(projection_time)
                 FROM (
                     SELECT obligations.updated_at_epoch_ms AS projection_time
                       FROM protection_obligations AS obligations
                      WHERE obligations.strategy_id=?
                        AND obligations.terminal_at_epoch_ms IS NULL
                     UNION ALL
                     SELECT claims.updated_at_epoch_ms
                       FROM exit_claims AS claims
                       JOIN protection_obligations AS obligations
                         ON obligations.obligation_id=claims.obligation_id
                      WHERE obligations.strategy_id=?
                        AND obligations.terminal_at_epoch_ms IS NULL
                 )
              ) AS unprotected_as_of_epoch_ms,
              EXISTS(
                SELECT 1
                  FROM exit_claims AS claims
                  JOIN protection_obligations AS obligations
                    ON obligations.obligation_id=claims.obligation_id
                 WHERE obligations.strategy_id=? AND claims.state='unknown'
              ) AS has_unknown_claim
        `)
        .get(strategyId, strategyId, strategyId, strategyId, strategyId);
    const activeObligationCount = safeInteger(
        protection?.active_obligation_count ?? 0,
        'activity.activeObligationCount',
    );
    const lastKnownUnprotectedShares = safeInteger(
        protection?.last_known_unprotected_shares ?? 0,
        'activity.lastKnownUnprotectedShares',
    );
    const unprotectedAsOfEpochMs =
        lastKnownUnprotectedShares === 0
            ? null
            : safeInteger(
                  protection?.unprotected_as_of_epoch_ms,
                  'activity.unprotectedAsOfEpochMs',
              );
    const hasRuntimeTrackedUnprotectedRemainder =
        lastKnownUnprotectedShares > 0;
    const hasUnknownExitClaim = protection?.has_unknown_claim === 1;
    if (hasRuntimeTrackedUnprotectedRemainder) {
        displayCandidates.push('unprotected');
    }
    if (hasUnknownExitClaim) displayCandidates.push('unknown');
    displayCandidates.sort(
        (left, right) =>
            (ACTIVE_ACTIVITY_DISPLAY_PRIORITY.get(right) ?? 0) -
                (ACTIVE_ACTIVITY_DISPLAY_PRIORITY.get(left) ?? 0) ||
            left.localeCompare(right),
    );
    return Object.freeze({
        schemaVersion: SMART_ORDER_ACTIVE_ACTIVITY_SCHEMA_VERSION,
        displayState: displayCandidates[0],
        ...summaries,
        formalProtection: activeFormalProtectionView(database, strategyId),
        hasRuntimeTrackedUnprotectedRemainder,
        runtimeTrackedUnprotectedRemainder: Object.freeze({
            state:
                lastKnownUnprotectedShares === 0 ? 'none' : 'last_known',
            lastKnownShares: lastKnownUnprotectedShares,
            asOfEpochMs: unprotectedAsOfEpochMs,
            current: false,
        }),
        hasUnknownExitClaim,
        accountIdentifiersExposed: false,
        entityIdentifiersExposed: false,
    });
}

function parseStrategyRow(
    row,
    { includeDefinition = false, database } = {},
) {
    if (!row) return undefined;
    const result = {
        strategyId: row.strategy_id,
        strategyKind: row.strategy_kind,
        state: row.state,
        definitionHash: row.definition_hash,
        accountBound:
            row.account_broker_ref !== 'draft-unbound' &&
            row.account_id_ref !== 'draft-unbound',
        maskedAccountLabel: maskedAccountLabel(row),
        createdAtEpochMs: row.created_at_epoch_ms,
        updatedAtEpochMs: row.updated_at_epoch_ms,
        revision: row.revision,
    };
    if (row.terminal_at_epoch_ms !== null) {
        result.terminalAtEpochMs = row.terminal_at_epoch_ms;
    }
    if (includeDefinition) {
        try {
            result.definition = JSON.parse(row.definition_json);
        } catch {
            throw new Error('stored strategy definition is not valid JSON');
        }
    }
    if (database) {
        result.activity = activeActivitySummary(
            database,
            row.strategy_id,
            row.state,
        );
    }
    return Object.freeze(result);
}

const STRATEGY_CONFIRMATION_SCHEMA_VERSION =
    'smart-order-canonical-confirmation/2026-08-20.1';
const CONTRACT_EVIDENCE_SCHEMA_VERSION =
    'smart-order-canonical-contract-evidence/2026-08-21.2';

function strategyConfirmationEvidenceContext(database, input) {
    if (
        !exactKeys(input, [
            'accountBrokerRef',
            'accountIdRef',
            'apiGeneration',
            'expectedRevision',
            'runtimeEpochId',
            'senderFence',
            'strategyId',
        ])
    ) {
        throw new TypeError(
            'strategy confirmation evidence context input is invalid',
        );
    }
    const sender = {
        apiGeneration: boundedToken(input.apiGeneration, 'apiGeneration'),
        runtimeEpochId: boundedToken(input.runtimeEpochId, 'runtimeEpochId'),
        senderFence: boundedToken(input.senderFence, 'senderFence'),
    };
    if (!currentReadySenderMatches(database, sender)) {
        throw new Error(
            'strategy confirmation evidence context requires the current ready Runtime',
        );
    }
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'expectedRevision',
    );
    const accountBrokerRef = boundedToken(
        input.accountBrokerRef,
        'accountBrokerRef',
    );
    const accountIdRef = boundedToken(input.accountIdRef, 'accountIdRef');
    const strategy = database
        .prepare(
            `SELECT strategy_kind, state, definition_hash, definition_json,
                    revision
               FROM strategies WHERE strategy_id=?`,
        )
        .get(strategyId);
    if (
        !strategy ||
        strategy.state !== 'draft' ||
        strategy.revision !== expectedRevision ||
        !['quick', 'good_till', 'multi_condition', 'parent_child', 'stop_take', 'trailing_exit'].includes(
            strategy.strategy_kind,
        )
    ) {
        throw new Error(
            'strategy confirmation evidence context requires the exact current supported draft',
        );
    }
    const definition = parseStoredCanonicalObject(
        strategy.definition_json,
        'strategy confirmation evidence draft',
    );
    assertCanonicalSmartOrderDraft(definition, {
        expectedKind: strategy.strategy_kind,
    });
    const contractKey =
        definition.kind === 'parent_child'
            ? definition.parameters.parent.order.contractKey
            : definition.parameters.order.contractKey;
    const runtimeContract = /^(TSE|OTC):STK:([A-Za-z0-9][A-Za-z0-9._-]{0,31})$/.exec(
        contractKey,
    );
    if (!runtimeContract) {
        throw new Error('strategy confirmation evidence contract is unsupported');
    }
    const requiresPosition = ['stop_take', 'trailing_exit'].includes(
        strategy.strategy_kind,
    );
    const position = requiresPosition
        ? database
              .prepare(
                  `SELECT positions.trade_date
                     FROM account_reconciliation_positions AS positions
                     JOIN account_reconciliation_heads AS heads
                       ON heads.account_broker_ref=positions.account_broker_ref
                      AND heads.account_id_ref=positions.account_id_ref
                      AND heads.trade_date=positions.trade_date
                    WHERE positions.account_broker_ref=?
                      AND positions.account_id_ref=?
                      AND positions.contract_key=?
                      AND positions.account_head_revision=heads.revision
                      AND positions.source_revision=heads.source_revision
                      AND positions.source_snapshot_hash=heads.source_snapshot_hash
                      AND positions.evidence_hash=heads.evidence_hash
                    ORDER BY positions.as_of_epoch_ms DESC
                    LIMIT 1`,
              )
              .get(
                  accountBrokerRef,
                  accountIdRef,
                  `${runtimeContract[1]}:${runtimeContract[2]}:STK:Common`,
              )
        : null;
    if (requiresPosition && !position) {
        throw new Error(
            'strategy confirmation evidence context requires the reconciled position',
        );
    }
    const distances =
        definition.kind === 'stop_take'
            ? definition.parameters.legs.map((leg) => leg.distance)
            : definition.kind === 'trailing_exit'
              ? [definition.parameters.retracement]
              : [];
    return Object.freeze({
        schemaVersion:
            'smart-order-strategy-confirmation-evidence-context/2026-08-21.1',
        strategyId,
        strategyRevision: strategy.revision,
        strategyDefinitionHash: strategy.definition_hash,
        contractKey,
        monitorContractKey:
            definition.kind === 'good_till'
                ? definition.parameters.monitorContractKey
                : definition.parameters.monitorContractKey ?? contractKey,
        monitorContractKeys:
            definition.kind === 'multi_condition'
                ? Object.freeze(
                      definition.parameters.conditions.map(
                          (entry) => entry.monitorContractKey,
                      ),
                  )
                : definition.kind === 'parent_child'
                  ? Object.freeze([
                        definition.parameters.child.order.contractKey,
                    ])
                  : Object.freeze([]),
        decisionTradingDate:
            position?.trade_date ??
            (definition.kind === 'parent_child'
                ? definition.parameters.parentValidity.startDate
                : definition.parameters.validity.startDate),
        fixedAtrRequired: distances.some(
            (distance) => distance.kind === 'fixed_atr',
        ),
        brokerWriteAuthority: false,
    });
}

function strategyProtectionRearmEvidenceContext(database, input) {
    if (
        !exactKeys(input, [
            'apiGeneration',
            'expectedRevision',
            'runtimeEpochId',
            'senderFence',
            'strategyId',
        ])
    ) {
        throw new TypeError(
            'strategy protection re-arm evidence context input is invalid',
        );
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    if (
        !currentReadySenderMatches(database, {
            runtimeEpochId,
            senderFence,
            apiGeneration,
        })
    ) {
        throw new Error(
            'strategy protection re-arm evidence requires the current ready Runtime',
        );
    }
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'expectedRevision',
    );
    const row = database.prepare(`
        SELECT strategies.state, strategies.strategy_kind,
               strategies.definition_hash, strategies.revision,
               claims.account_broker_ref, claims.account_id_ref,
               claims.contract_key, heads.trade_date,
               heads.protection_plan_json
          FROM existing_position_protection_heads AS heads
          JOIN strategies ON strategies.strategy_id=heads.strategy_id
          JOIN protection_groups AS groups
            ON groups.exit_claim_id=heads.exit_claim_id
          JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
          JOIN exit_claims AS claims ON claims.exit_claim_id=heads.exit_claim_id
         WHERE heads.strategy_id=? AND strategies.state='paused'
           AND strategies.revision=?
           AND groups.state='rearm_required'
           AND generations.state='rearm_required'
           AND claims.remainder_generation=groups.current_generation
           AND claims.state='monitoring_reserved' AND claims.intent_id IS NULL
    `).get(strategyId, expectedRevision);
    if (!row) return null;
    const plan = canonicalExistingPositionProtectionPlan(
        parseStoredCanonicalObject(
            row.protection_plan_json,
            'strategy protection re-arm evidence plan',
        ),
    );
    if (
        plan.plan.accountBrokerRef !== row.account_broker_ref ||
        plan.plan.accountIdRef !== row.account_id_ref ||
        plan.plan.contractKey !== row.contract_key ||
        !['stop_take', 'trailing_exit'].includes(row.strategy_kind)
    ) {
        throw new Error(
            'strategy protection re-arm evidence lineage is invalid',
        );
    }
    const contract = /^(TSE|OTC):([A-Za-z0-9][A-Za-z0-9._-]{0,31}):STK:Common$/.exec(
        plan.plan.contractKey,
    );
    if (!contract) {
        throw new Error(
            'strategy protection re-arm contract lineage is invalid',
        );
    }
    return Object.freeze({
        schemaVersion:
            'smart-order-strategy-protection-rearm-evidence-context/2026-08-21.1',
        accountBrokerRef: row.account_broker_ref,
        accountIdRef: row.account_id_ref,
        contractKey: `${contract[1]}:STK:${contract[2]}`,
        decisionTradingDate: row.trade_date,
        expectedRevision,
        fixedAtrRequired: false,
        strategyDefinitionHash: row.definition_hash,
        strategyId,
        brokerWriteAuthority: false,
    });
}

function canonicalRuntimeFixedAtrSnapshot(value) {
    if (value === null) return null;
    if (
        !exactKeys(value, [
            'algorithmVersion',
            'asOfTradingDate',
            'contractKey',
            'contractRevision',
            'corporateActionRevision',
            'period',
            'schemaVersion',
            'snapshotSha256',
            'source',
            'strategyDefinitionHash',
            'timeframe',
            'value',
        ]) ||
        value.schemaVersion !== SMART_ORDER_RUNTIME_FIXED_ATR_SCHEMA_VERSION ||
        value.algorithmVersion !==
            SMART_ORDER_RUNTIME_FIXED_ATR_ALGORITHM_VERSION ||
        value.timeframe !== '1D' ||
        value.period !== 14 ||
        typeof value.value !== 'string' ||
        !/^(?:0|[1-9]\d*)(?:\.\d+)?$/.test(value.value) ||
        value.value === '0' ||
        !/^\d{4}-\d{2}-\d{2}$/.test(value.asOfTradingDate) ||
        !exactKeys(value.source, [
            'canonicalCandlesSha256',
            'completedCandleCount',
            'completeness',
            'coverageEndTradingDate',
            'coverageStartTradingDate',
            'requestedEndDate',
            'requestedStartDate',
            'sourceId',
        ]) ||
        value.source.sourceId !== 'shioaji:/api/v1/data/kbars' ||
        value.source.completeness !== 'bounded_native_kbars_response' ||
        !Number.isSafeInteger(value.source.completedCandleCount) ||
        value.source.completedCandleCount < 15
    ) {
        throw new TypeError('Runtime fixed ATR snapshot schema is invalid');
    }
    const { snapshotSha256, ...payload } = value;
    if (
        sha256Digest(snapshotSha256, 'fixedAtrSnapshot.snapshotSha256') !==
            sha256Canonical(payload, 'Runtime fixed ATR snapshot') ||
        value.source.coverageEndTradingDate !== value.asOfTradingDate
    ) {
        throw new Error('Runtime fixed ATR snapshot integrity is invalid');
    }
    sha256Digest(value.contractRevision, 'fixedAtrSnapshot.contractRevision');
    sha256Digest(
        value.corporateActionRevision,
        'fixedAtrSnapshot.corporateActionRevision',
    );
    sha256Digest(
        value.strategyDefinitionHash,
        'fixedAtrSnapshot.strategyDefinitionHash',
    );
    sha256Digest(
        value.source.canonicalCandlesSha256,
        'fixedAtrSnapshot.source.canonicalCandlesSha256',
    );
    return Object.freeze({
        ...value,
        source: Object.freeze({ ...value.source }),
    });
}

function canonicalConfirmationContractEvidence(value) {
    if (
        !exactKeys(value, [
            'accountScopeSha256',
            'apiGeneration',
            'contract',
            'contractRevision',
            'corporateActionRevision',
            'evidenceSha256',
            'fixedAtrSnapshot',
            'gateManifestHash',
            'gateManifestRevision',
            'mappingRevision',
            'observedAtEpochMs',
            'runtimeEpochId',
            'schemaVersion',
            'validUntilEpochMs',
        ]) ||
        value.schemaVersion !== CONTRACT_EVIDENCE_SCHEMA_VERSION ||
        !exactKeys(value.contract, [
            'categoryCode',
            'code',
            'contractUnit',
            'draftContractKey',
            'exchange',
            'limitDownMinorUnits',
            'limitUpMinorUnits',
            'referenceMinorUnits',
            'runtimeContractKey',
            'securityType',
            'updateDate',
        ])
    ) {
        throw new TypeError('canonical contract evidence schema is invalid');
    }
    const { evidenceSha256, ...content } = value;
    if (
        sha256Digest(evidenceSha256, 'contractEvidence.evidenceSha256') !==
            sha256Canonical(content, 'contract evidence content') ||
        value.contractRevision !==
            `sha256:${createHash('sha256')
                .update(
                    `smart-order-contract-revision\u001f${stableCanonicalJson(
                        value.contract,
                    )}`,
                )
                .digest('hex')}`
    ) {
        throw new Error('canonical contract evidence hash is invalid');
    }
    const contract = value.contract;
    const fixedAtrSnapshot = canonicalRuntimeFixedAtrSnapshot(
        value.fixedAtrSnapshot,
    );
    const contractUnit = safeInteger(
        contract.contractUnit,
        'contractEvidence.contractUnit',
        { minimum: 1 },
    );
    const referenceMinorUnits = safeInteger(
        contract.referenceMinorUnits,
        'contractEvidence.referenceMinorUnits',
        { minimum: 1 },
    );
    const limitDownMinorUnits = safeInteger(
        contract.limitDownMinorUnits,
        'contractEvidence.limitDownMinorUnits',
        { minimum: 1 },
    );
    const limitUpMinorUnits = safeInteger(
        contract.limitUpMinorUnits,
        'contractEvidence.limitUpMinorUnits',
        { minimum: referenceMinorUnits },
    );
    if (
        limitDownMinorUnits > referenceMinorUnits ||
        !/^(?:00|0[1-9]|[1-9]\d)$/.test(contract.categoryCode) ||
        !/^(TSE|OTC):STK:[A-Za-z0-9][A-Za-z0-9._-]{0,31}$/.test(
            contract.draftContractKey,
        ) ||
        contract.runtimeContractKey !==
            `${contract.exchange}:${contract.code}:STK:Common` ||
        contract.draftContractKey !==
            `${contract.exchange}:STK:${contract.code}` ||
        !['TSE', 'OTC'].includes(contract.exchange) ||
        contract.securityType !== 'STK'
    ) {
        throw new Error('canonical contract evidence projection is inconsistent');
    }
    return Object.freeze({
        ...value,
        accountScopeSha256: sha256Digest(
            value.accountScopeSha256,
            'contractEvidence.accountScopeSha256',
        ),
        apiGeneration: boundedToken(
            value.apiGeneration,
            'contractEvidence.apiGeneration',
        ),
        contract: Object.freeze({
            ...contract,
            categoryCode: boundedToken(
                contract.categoryCode,
                'contractEvidence.categoryCode',
            ),
            code: boundedToken(contract.code, 'contractEvidence.code'),
            contractUnit,
            draftContractKey: boundedToken(
                contract.draftContractKey,
                'contractEvidence.draftContractKey',
            ),
            exchange: boundedToken(
                contract.exchange,
                'contractEvidence.exchange',
            ),
            limitDownMinorUnits,
            limitUpMinorUnits,
            referenceMinorUnits,
            runtimeContractKey: boundedToken(
                contract.runtimeContractKey,
                'contractEvidence.runtimeContractKey',
            ),
            securityType: 'STK',
            updateDate: boundedToken(
                contract.updateDate,
                'contractEvidence.updateDate',
            ),
        }),
        contractRevision: sha256Digest(
            value.contractRevision,
            'contractEvidence.contractRevision',
        ),
        corporateActionRevision: sha256Digest(
            value.corporateActionRevision,
            'contractEvidence.corporateActionRevision',
        ),
        fixedAtrSnapshot,
        gateManifestHash: sha256Digest(
            value.gateManifestHash,
            'contractEvidence.gateManifestHash',
        ),
        gateManifestRevision: boundedToken(
            value.gateManifestRevision,
            'contractEvidence.gateManifestRevision',
        ),
        mappingRevision: boundedToken(
            value.mappingRevision,
            'contractEvidence.mappingRevision',
        ),
        observedAtEpochMs: safeInteger(
            value.observedAtEpochMs,
            'contractEvidence.observedAtEpochMs',
        ),
        runtimeEpochId: boundedToken(
            value.runtimeEpochId,
            'contractEvidence.runtimeEpochId',
        ),
        validUntilEpochMs: safeInteger(
            value.validUntilEpochMs,
            'contractEvidence.validUntilEpochMs',
        ),
    });
}

const CANONICAL_CONTRACT_HEAD_META_PREFIX =
    'canonical_contract_evidence_head:';
const CANONICAL_CONTRACT_HEAD_SCHEMA_VERSION =
    'smart-order-canonical-contract-evidence-head/2026-08-20.1';

function canonicalContractHeadMetaKey(contractEvidence) {
    return `${CANONICAL_CONTRACT_HEAD_META_PREFIX}${createHash('sha256')
        .update(
            `${contractEvidence.accountScopeSha256}\u001f${contractEvidence.contract.runtimeContractKey}`,
        )
        .digest('hex')}`;
}

function canonicalContractHeadProjection(contractEvidence) {
    return Object.freeze({
        schemaVersion: CANONICAL_CONTRACT_HEAD_SCHEMA_VERSION,
        accountScopeSha256: contractEvidence.accountScopeSha256,
        runtimeContractKey: contractEvidence.contract.runtimeContractKey,
        evidenceSha256: contractEvidence.evidenceSha256,
        contractRevision: contractEvidence.contractRevision,
        corporateActionRevision: contractEvidence.corporateActionRevision,
        gateManifestRevision: contractEvidence.gateManifestRevision,
        gateManifestHash: contractEvidence.gateManifestHash,
        mappingRevision: contractEvidence.mappingRevision,
        runtimeEpochId: contractEvidence.runtimeEpochId,
        apiGeneration: contractEvidence.apiGeneration,
        observedAtEpochMs: contractEvidence.observedAtEpochMs,
        validUntilEpochMs: contractEvidence.validUntilEpochMs,
    });
}

function parseCanonicalContractHead(value) {
    let parsed;
    try {
        parsed = JSON.parse(value);
    } catch {
        throw new Error('canonical contract evidence head JSON is invalid');
    }
    if (
        !exactKeys(parsed, [
            'accountScopeSha256',
            'apiGeneration',
            'contractRevision',
            'corporateActionRevision',
            'evidenceSha256',
            'gateManifestHash',
            'gateManifestRevision',
            'mappingRevision',
            'observedAtEpochMs',
            'runtimeContractKey',
            'runtimeEpochId',
            'schemaVersion',
            'validUntilEpochMs',
        ]) ||
        parsed.schemaVersion !== CANONICAL_CONTRACT_HEAD_SCHEMA_VERSION ||
        stableCanonicalJson(parsed) !== value
    ) {
        throw new Error('canonical contract evidence head is not canonical');
    }
    return parsed;
}

function supersedeCanonicalConfirmations(database, rows, now, reasonCode) {
    for (const row of rows) {
        database.prepare(`
            UPDATE intent_rearm_authorizations
               SET state='superseded', revision=revision+1
             WHERE state='active' AND intent_id IN (
                SELECT intent_id FROM order_intents WHERE strategy_id=?
             )
        `).run(row.strategy_id);
        const result = database.prepare(`
            UPDATE canonical_confirmation_snapshots
               SET state='superseded', updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE confirmation_id=? AND state='accepted' AND revision=?
        `).run(now, row.confirmation_id, row.revision);
        if (Number(result.changes) !== 1) {
            throw new Error('canonical confirmation invalidation lost its CAS');
        }
        insertTransitionJournalEvent(database, {
            entityKind: 'canonical_confirmation',
            entityId: row.confirmation_id,
            revision: row.revision + 1,
            reasonCode,
            summaryCode: 'canonical_confirmation_superseded_current_head_changed',
            nowEpochMs: now,
            payloadHash: row.snapshot_hash,
            eventSuffix: 'current-head-superseded',
        });
    }
}

function observeCanonicalContractHead(
    database,
    { accountBrokerRef, accountIdRef, contractEvidence, nowEpochMs },
) {
    const now = safeInteger(nowEpochMs, 'canonicalContractHead.nowEpochMs');
    const key = canonicalContractHeadMetaKey(contractEvidence);
    const next = canonicalContractHeadProjection(contractEvidence);
    const serialized = stableCanonicalJson(next);
    const storedValue = repositoryMetaValue(database, key);
    if (storedValue !== undefined) {
        const stored = parseCanonicalContractHead(storedValue);
        if (
            stored.accountScopeSha256 !== next.accountScopeSha256 ||
            stored.runtimeContractKey !== next.runtimeContractKey
        ) {
            throw new Error('canonical contract evidence head scope conflicted');
        }
        if (next.observedAtEpochMs < stored.observedAtEpochMs) {
            throw new Error('canonical contract evidence head cannot roll back');
        }
        const semanticHeadChanged =
            stored.contractRevision !== next.contractRevision ||
            stored.corporateActionRevision !==
                next.corporateActionRevision ||
            stored.gateManifestRevision !== next.gateManifestRevision ||
            stored.gateManifestHash !== next.gateManifestHash ||
            stored.mappingRevision !== next.mappingRevision ||
            stored.runtimeEpochId !== next.runtimeEpochId ||
            stored.apiGeneration !== next.apiGeneration;
        if (
            next.observedAtEpochMs === stored.observedAtEpochMs &&
            semanticHeadChanged
        ) {
            throw new Error('canonical contract evidence head has a same-time conflict');
        }
        if (storedValue === serialized) return next;
        if (semanticHeadChanged) {
            const stale = database.prepare(`
                SELECT confirmation_id, strategy_id, snapshot_hash, revision
                  FROM canonical_confirmation_snapshots
                 WHERE state='accepted' AND account_broker_ref=?
                   AND account_id_ref=? AND contract_key=?
                   AND (
                       contract_revision<>?
                       OR corporate_action_revision<>?
                       OR gate_manifest_revision<>?
                       OR gate_manifest_hash<>?
                   )
                 ORDER BY confirmation_id
            `).all(
                accountBrokerRef,
                accountIdRef,
                contractEvidence.contract.runtimeContractKey,
                contractEvidence.contractRevision,
                contractEvidence.corporateActionRevision,
                contractEvidence.gateManifestRevision,
                contractEvidence.gateManifestHash,
            );
            supersedeCanonicalConfirmations(
                database,
                stale,
                now,
                'CANONICAL_CONFIRMATION_CONTRACT_HEAD_CHANGED',
            );
        }
    }
    setRepositoryMeta(database, key, serialized);
    return next;
}

function invalidateCanonicalConfirmationsForAccountHead(
    database,
    { projection, accountHeadRevision, nowEpochMs },
) {
    const stale = database.prepare(`
        SELECT confirmation_id, strategy_id, snapshot_hash, revision
          FROM canonical_confirmation_snapshots
         WHERE state='accepted' AND account_broker_ref=? AND account_id_ref=?
           AND trade_date=?
           AND strategy_id NOT IN (
               SELECT strategy_id FROM strategies
                WHERE strategy_kind='parent_child'
           )
           AND (
               account_head_revision<>? OR position_evidence_hash<>?
           )
         ORDER BY confirmation_id
    `).all(
        projection.account.brokerId,
        projection.account.accountId,
        projection.tradeDate,
        accountHeadRevision,
        projection.evidenceSha256,
    );
    supersedeCanonicalConfirmations(
        database,
        stale,
        safeInteger(nowEpochMs, 'confirmationInvalidation.nowEpochMs'),
        'CANONICAL_CONFIRMATION_ACCOUNT_HEAD_CHANGED',
    );
}

function assertCanonicalConfirmationCurrent(
    database,
    { strategyId, snapshotHash, runtimeEpochId, senderFence, apiGeneration, nowEpochMs },
) {
    const strategy = database.prepare(`
        SELECT strategy_kind, definition_json
          FROM strategies WHERE strategy_id=?
    `).get(strategyId);
    if (strategy?.strategy_kind === 'scheduled_quantity') {
        let definition;
        try {
            definition = JSON.parse(strategy.definition_json);
            assertCanonicalSmartOrderDraft(definition, {
                expectedKind: 'scheduled_quantity',
            });
        } catch {
            throw new Error(
                'scheduled quantity strategy definition is not canonical',
            );
        }
        const decision = scheduledQuantityModeDecision(
            definition.parameters.mode,
        );
        throw new Error(
            `scheduled quantity ${decision.mode} mode is disabled: ${decision.blocker}`,
        );
    }
    const rows = database.prepare(`
        SELECT * FROM canonical_confirmation_snapshots
         WHERE strategy_id=?
         ORDER BY updated_at_epoch_ms DESC, confirmation_id
    `).all(strategyId);
    if (rows.length === 0) {
        let currentQuickDefinition = false;
        if (strategy?.strategy_kind === 'quick') {
            try {
                const definition = JSON.parse(strategy.definition_json);
                assertCanonicalSmartOrderDraft(definition, {
                    expectedKind: 'quick',
                });
                currentQuickDefinition = true;
            } catch {
                currentQuickDefinition = false;
            }
        }
        if (
            ['stop_take', 'trailing_exit'].includes(
                strategy?.strategy_kind,
            ) ||
            ['good_till', 'multi_condition', 'parent_child'].includes(strategy?.strategy_kind) ||
            currentQuickDefinition
        ) {
            throw new Error(
                'protected strategy requires one durable accepted canonical confirmation',
            );
        }
        return true;
    }
    const acceptedRows = rows.filter(
        (candidate) =>
            candidate.state === 'accepted' &&
            candidate.snapshot_hash === snapshotHash,
    );
    if (acceptedRows.length !== 1) {
        throw new Error('canonical confirmation is no longer accepted/current');
    }
    const row = acceptedRows[0];
    const now = safeInteger(nowEpochMs, 'canonicalConfirmationCurrent.nowEpochMs');
    let content;
    try {
        content = JSON.parse(row.snapshot_json);
    } catch {
        throw new Error('canonical confirmation snapshot JSON is invalid');
    }
    if (stableCanonicalJson(content) !== row.snapshot_json) {
        throw new Error('canonical confirmation snapshot is not canonical');
    }
    const runtime = database.prepare(`
        SELECT revision FROM runtime_epochs
         WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
    `).get(runtimeEpochId, senderFence, apiGeneration);
    const renewableMappingStrategy =
        content.schemaVersion === STRATEGY_CONFIRMATION_SCHEMA_VERSION &&
        ['good_till', 'multi_condition', 'parent_child'].includes(content.strategyKind);
    if (
        (!renewableMappingStrategy && row.valid_until_epoch_ms <= now) ||
        row.runtime_epoch_id !== runtimeEpochId ||
        row.sender_fence !== senderFence ||
        row.api_generation !== apiGeneration ||
        !runtime ||
        (!renewableMappingStrategy && row.runtime_revision !== runtime.revision)
    ) {
        throw new Error('canonical confirmation Runtime/expiry head changed');
    }
    if (content.schemaVersion === STRATEGY_CONFIRMATION_SCHEMA_VERSION) {
        if (['quick', 'good_till', 'multi_condition'].includes(content.strategyKind)) {
            if (
                content.position !== null ||
                (content.strategyKind !== 'multi_condition' &&
                    (content.quickFieldMapping?.revision !==
                        SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
                        content.quickFieldMapping?.definitionSha256 !==
                            SMART_ORDER_QUICK_FIELD_MAPPING_DEFINITION_SHA256)) ||
                (content.strategyKind === 'multi_condition' &&
                    (!Array.isArray(content.monitorConditions) ||
                        content.monitorConditions.length < 1 ||
                        content.monitorConditions.length > 7 ||
                        content.monitorConditions.some(
                            (entry, index) =>
                                entry.conditionIndex !== index ||
                                entry.quickFieldMapping?.revision !==
                                    SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
                                entry.quickFieldMapping?.definitionSha256 !==
                                    SMART_ORDER_QUICK_FIELD_MAPPING_DEFINITION_SHA256,
                        ))) ||
                sha256Canonical(content, 'canonical confirmation snapshot') !==
                    row.snapshot_hash
            ) {
                throw new Error('quick confirmation mapping integrity failed');
            }
        } else if (content.strategyKind === 'parent_child') {
            const childPosition = database.prepare(`
                SELECT positions.position_lineage_id, positions.available_shares,
                       positions.valid_until_epoch_ms,
                       heads.as_of_epoch_ms AS head_as_of_epoch_ms
                  FROM account_reconciliation_positions AS positions
                  JOIN account_reconciliation_heads AS heads
                    ON heads.account_broker_ref=positions.account_broker_ref
                   AND heads.account_id_ref=positions.account_id_ref
                   AND heads.trade_date=positions.trade_date
                 WHERE positions.account_broker_ref=?
                   AND positions.account_id_ref=?
                   AND positions.contract_key=?
                   AND positions.account_head_revision=heads.revision
                   AND positions.source_revision=heads.source_revision
                   AND positions.source_snapshot_hash=heads.source_snapshot_hash
                   AND positions.evidence_hash=heads.evidence_hash
                 ORDER BY positions.as_of_epoch_ms DESC
                 LIMIT 1
            `).get(
                row.account_broker_ref,
                row.account_id_ref,
                content.childContract.runtimeContractKey,
            );
            const requiredChildShares = safeInteger(
                Number(content.resolvedDefinition.parameters.child.order.baseShares),
                'parentChild.currentChildShares',
                { minimum: 1 },
            );
            if (
                content.position === null ||
                content.position.positionLineageId !== row.position_lineage_id ||
                content.parentLeg.quickFieldMapping.revision !==
                    SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
                content.parentLeg.quickFieldMapping.definitionSha256 !==
                    SMART_ORDER_QUICK_FIELD_MAPPING_DEFINITION_SHA256 ||
                content.childLeg.quickFieldMapping.revision !==
                    SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
                content.childLeg.quickFieldMapping.definitionSha256 !==
                    SMART_ORDER_QUICK_FIELD_MAPPING_DEFINITION_SHA256 ||
                !childPosition ||
                childPosition.position_lineage_id !== row.position_lineage_id ||
                childPosition.available_shares < requiredChildShares ||
                childPosition.valid_until_epoch_ms <= now ||
                childPosition.head_as_of_epoch_ms > now ||
                sha256Canonical(content, 'canonical confirmation snapshot') !==
                    row.snapshot_hash
            ) {
                throw new Error('parent-child child position or mapping changed');
            }
        } else {
            const accountHead = database.prepare(`
                SELECT revision, evidence_hash FROM account_reconciliation_heads
                 WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
            `).get(row.account_broker_ref, row.account_id_ref, row.trade_date);
            const position = database.prepare(`
                SELECT position_lineage_id, evidence_hash, valid_until_epoch_ms
                  FROM account_reconciliation_positions
                 WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
                   AND contract_key=?
            `).get(
                row.account_broker_ref,
                row.account_id_ref,
                row.trade_date,
                row.contract_key,
            );
            if (
                !accountHead ||
                accountHead.revision !== row.account_head_revision ||
                accountHead.evidence_hash !== row.position_evidence_hash ||
                !position ||
                position.position_lineage_id !== row.position_lineage_id ||
                position.evidence_hash !== row.position_evidence_hash ||
                position.valid_until_epoch_ms <= now ||
                sha256Canonical(content, 'canonical confirmation snapshot') !==
                    row.snapshot_hash
            ) {
                throw new Error('canonical confirmation position evidence changed');
            }
        }
    } else if (
        content.schemaVersion === PROTECTED_ENTRY_CONFIRMATION_SCHEMA_VERSION
    ) {
        if (
            content.confirmationSnapshotHash !== row.snapshot_hash ||
            content.protectionPlan?.confirmationSnapshotHash !== row.snapshot_hash ||
            content.definitionHash !== row.definition_hash
        ) {
            throw new Error('protected entry confirmation snapshot integrity failed');
        }
    } else {
        throw new Error('canonical confirmation snapshot schema is unsupported');
    }
    const contractHeadValue = repositoryMetaValue(
        database,
        `${CANONICAL_CONTRACT_HEAD_META_PREFIX}${createHash('sha256')
            .update(
                `${content.fixedAccount.accountScopeSha256}\u001f${row.contract_key}`,
            )
            .digest('hex')}`,
    );
    if (contractHeadValue === undefined) {
        throw new Error('canonical confirmation contract head is missing');
    }
    const contractHead = parseCanonicalContractHead(contractHeadValue);
    if (
        contractHead.contractRevision !== row.contract_revision ||
        contractHead.corporateActionRevision !== row.corporate_action_revision ||
        contractHead.runtimeEpochId !== runtimeEpochId ||
        contractHead.apiGeneration !== apiGeneration ||
        contractHead.validUntilEpochMs <= now
    ) {
        throw new Error('canonical confirmation contract head changed');
    }
    if (content.strategyKind === 'good_till') {
        const monitorHeadValue = repositoryMetaValue(
            database,
            `${CANONICAL_CONTRACT_HEAD_META_PREFIX}${createHash('sha256')
                .update(
                    `${content.fixedAccount.accountScopeSha256}\u001f${content.monitorContract.runtimeContractKey}`,
                )
                .digest('hex')}`,
        );
        if (monitorHeadValue === undefined) {
            throw new Error('good-till monitor contract head is missing');
        }
        const monitorHead = parseCanonicalContractHead(monitorHeadValue);
        if (
            monitorHead.contractRevision !== content.monitorContractRevision ||
            monitorHead.corporateActionRevision !==
                content.monitorCorporateActionRevision ||
            monitorHead.runtimeEpochId !== runtimeEpochId ||
            monitorHead.apiGeneration !== apiGeneration ||
            monitorHead.validUntilEpochMs <= now
        ) {
            throw new Error('good-till monitor contract head changed');
        }
    }
    if (content.strategyKind === 'multi_condition') {
        for (const entry of content.monitorConditions) {
            const monitorHeadValue = repositoryMetaValue(
                database,
                `${CANONICAL_CONTRACT_HEAD_META_PREFIX}${createHash('sha256')
                    .update(
                        `${content.fixedAccount.accountScopeSha256}\u001f${entry.monitorContract.runtimeContractKey}`,
                    )
                    .digest('hex')}`,
            );
            if (monitorHeadValue === undefined) {
                throw new Error('multi-condition monitor contract head is missing');
            }
            const monitorHead = parseCanonicalContractHead(monitorHeadValue);
            if (
                monitorHead.contractRevision !== entry.monitorContractRevision ||
                monitorHead.corporateActionRevision !==
                    entry.monitorCorporateActionRevision ||
                monitorHead.runtimeEpochId !== runtimeEpochId ||
                monitorHead.apiGeneration !== apiGeneration ||
                monitorHead.validUntilEpochMs <= now
            ) {
                throw new Error('multi-condition monitor contract head changed');
            }
        }
    }
    if (content.strategyKind === 'parent_child') {
        const childHeadValue = repositoryMetaValue(
            database,
            `${CANONICAL_CONTRACT_HEAD_META_PREFIX}${createHash('sha256')
                .update(
                    `${content.fixedAccount.accountScopeSha256}\u001f${content.childContract.runtimeContractKey}`,
                )
                .digest('hex')}`,
        );
        if (childHeadValue === undefined) {
            throw new Error('parent-child child contract head is missing');
        }
        const childHead = parseCanonicalContractHead(childHeadValue);
        if (
            childHead.contractRevision !== content.childContractRevision ||
            childHead.corporateActionRevision !==
                content.childCorporateActionRevision ||
            childHead.runtimeEpochId !== runtimeEpochId ||
            childHead.apiGeneration !== apiGeneration ||
            childHead.validUntilEpochMs <= now
        ) {
            throw new Error('parent-child child contract head changed');
        }
    }
    const gate = gateManifestStatus(database, {
        provenance: 'automation',
        nowEpochMs: now,
    });
    const gateHeadDrift = [
        gate.state !== 'eligible' ? 'state' : null,
        gate.manifestRevision !== row.gate_manifest_revision
            ? 'revision'
            : null,
        gate.manifestSha256 !== row.gate_manifest_hash ? 'hash' : null,
        gate.mappingRevision !== content.gate.mappingRevision
            ? 'mapping'
            : null,
    ].filter(Boolean);
    if (gateHeadDrift.length > 0) {
        throw new Error(
            `canonical confirmation Gate head changed (${content.strategyKind}): ${gateHeadDrift.join(',')}; blocker=${gate.blocker ?? 'none'}`,
        );
    }
    const risk = runtimeRiskPolicyView(database);
    const expectedRiskRevision =
        content.schemaVersion === STRATEGY_CONFIRMATION_SCHEMA_VERSION
            ? String(risk.revision)
            : risk.policy?.policyRevision;
    if (
        risk.state !== 'current' ||
        risk.policyHash !== row.risk_hash ||
        expectedRiskRevision !== row.risk_revision
    ) {
        throw new Error('canonical confirmation risk head changed');
    }
    return true;
}

function canonicalConfirmationClockNowEpochMs(requestNowEpochMs) {
    const clockNow =
        testOnlyExposureClockNowEpochMs === undefined
            ? Date.now()
            : safeInteger(
                  testOnlyExposureClockNowEpochMs,
                  'testOnlyExposureClockNowEpochMs',
              );
    if (requestNowEpochMs === undefined) return clockNow;
    return Math.max(
        clockNow,
        safeInteger(
            requestNowEpochMs,
            'canonicalConfirmation.requestNowEpochMs',
        ),
    );
}

function canonicalConfirmationBasis(value) {
    if (exactKeys(value, ['source']) && value.source === 'broker_average_cost') {
        return Object.freeze({ source: 'broker_average_cost' });
    }
    if (
        exactKeys(value, ['priceDecimal', 'source']) &&
        value.source === 'user_specified'
    ) {
        return Object.freeze({
            source: 'user_specified',
            priceDecimal: boundedToken(
                value.priceDecimal,
                'confirmation.basis.priceDecimal',
            ),
        });
    }
    throw new TypeError('canonical confirmation basis selection is invalid');
}

function canonicalStockTickMinorUnits(categoryCode, priceMinorUnits) {
    if (categoryCode === '00') {
        return priceMinorUnits < 5_000 ? 1 : 5;
    }
    if (!/^(?:0[1-9]|[1-9]\d)$/.test(categoryCode)) {
        throw new Error('canonical contract category is unsupported');
    }
    if (priceMinorUnits < 1_000) return 1;
    if (priceMinorUnits < 5_000) return 5;
    if (priceMinorUnits < 10_000) return 10;
    if (priceMinorUnits < 50_000) return 50;
    if (priceMinorUnits < 100_000) return 100;
    return 500;
}

function assertCanonicalContractPrice(priceDecimal, evidence, label) {
    const priceMinorUnits = brokerPriceMinorUnits(priceDecimal, label);
    const tickMinorUnits = canonicalStockTickMinorUnits(
        evidence.contract.categoryCode,
        priceMinorUnits,
    );
    if (
        priceMinorUnits % tickMinorUnits !== 0 ||
        priceMinorUnits < evidence.contract.limitDownMinorUnits ||
        priceMinorUnits > evidence.contract.limitUpMinorUnits
    ) {
        throw new Error(`${label} is outside the current legal tick/price limits`);
    }
    return priceMinorUnits;
}

function confirmationAccountScopeSha256(accountBrokerRef, accountIdRef) {
    return `sha256:${createHash('sha256')
        .update(
            `smart-order-confirmation-account\u001f${stableCanonicalJson([
                accountBrokerRef,
                accountIdRef,
                'S',
            ])}`,
        )
        .digest('hex')}`;
}

function authenticatedIdentityGroupForAccount(
    database,
    accountBrokerRef,
    accountIdRef,
) {
    const raw = repositoryMetaValue(
        database,
        identityAccountBindingKey(accountBrokerRef, accountIdRef),
    );
    if (!raw) {
        throw new Error('canonical confirmation account identity is unavailable');
    }
    let binding;
    try {
        binding = JSON.parse(raw);
    } catch {
        throw new Error('canonical confirmation account identity is invalid');
    }
    return boundedToken(
        binding.identityGroupId,
        'canonicalConfirmation.identityGroupId',
    );
}

function buildQuickStrategyConfirmationSnapshot(
    database,
    input,
    { snapshotCreatedAtEpochMs = input.nowEpochMs } = {},
) {
    const now = safeInteger(input.nowEpochMs, 'confirmation.nowEpochMs');
    const createdAtEpochMs = safeInteger(
        snapshotCreatedAtEpochMs,
        'confirmation.snapshotCreatedAtEpochMs',
    );
    if (
        createdAtEpochMs > now ||
        input.basisSelection !== null ||
        input.monitorContractEvidence !== null
    ) {
        throw new TypeError('quick confirmation does not accept a position basis');
    }
    const strategyId = boundedToken(input.strategyId, 'confirmation.strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'confirmation.expectedRevision',
    );
    const accountBrokerRef = boundedToken(
        input.accountBrokerRef,
        'confirmation.accountBrokerRef',
    );
    const accountIdRef = boundedToken(
        input.accountIdRef,
        'confirmation.accountIdRef',
    );
    const runtimeEpochId = boundedToken(
        input.runtimeEpochId,
        'confirmation.runtimeEpochId',
    );
    const senderFence = boundedToken(input.senderFence, 'confirmation.senderFence');
    const apiGeneration = boundedToken(
        input.apiGeneration,
        'confirmation.apiGeneration',
    );
    const contractEvidence = canonicalConfirmationContractEvidence(
        input.contractEvidence,
    );
    const runtime = database.prepare(`
        SELECT state, revision FROM runtime_epochs
         WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
    `).get(runtimeEpochId, senderFence, apiGeneration);
    const strategy = database
        .prepare('SELECT * FROM strategies WHERE strategy_id=?')
        .get(strategyId);
    if (
        !runtime ||
        runtime.state !== 'ready' ||
        !strategy ||
        strategy.state !== 'draft' ||
        strategy.revision !== expectedRevision ||
        strategy.strategy_kind !== 'quick'
    ) {
        throw new Error('quick confirmation requires the current ready draft');
    }
    let definition;
    try {
        definition = JSON.parse(strategy.definition_json);
    } catch {
        throw new Error('quick confirmation draft JSON is invalid');
    }
    assertCanonicalSmartOrderDraft(definition, { expectedKind: 'quick' });
    const order = definition.parameters.order;
    const condition = canonicalSmartOrderQuickCondition(
        definition.parameters.condition,
    );
    const expectedRuntimeContractKey =
        `${order.contractKey.split(':')[0]}:${order.contractKey.split(':')[2]}:STK:Common`;
    if (
        definition.parameters.monitorContractKey !== order.contractKey ||
        contractEvidence.contract.draftContractKey !== order.contractKey ||
        contractEvidence.contract.runtimeContractKey !== expectedRuntimeContractKey ||
        contractEvidence.accountScopeSha256 !==
            confirmationAccountScopeSha256(accountBrokerRef, accountIdRef) ||
        contractEvidence.runtimeEpochId !== runtimeEpochId ||
        contractEvidence.apiGeneration !== apiGeneration ||
        contractEvidence.mappingRevision !==
            SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
        contractEvidence.observedAtEpochMs > now ||
        contractEvidence.validUntilEpochMs <= now
    ) {
        throw new Error('quick confirmation contract or mapping evidence changed');
    }
    const gate = gateManifestStatus(database, {
        provenance: 'automation',
        nowEpochMs: now,
    });
    if (
        gate.state !== 'eligible' ||
        gate.featureGates.quick !== true ||
        gate.manifestRevision !== contractEvidence.gateManifestRevision ||
        gate.manifestSha256 !== contractEvidence.gateManifestHash ||
        gate.mappingRevision !== SMART_ORDER_QUICK_FIELD_MAPPING_REVISION
    ) {
        throw new Error('quick confirmation Gate or mapping head changed');
    }
    observeCanonicalContractHead(database, {
        accountBrokerRef,
        accountIdRef,
        contractEvidence,
        nowEpochMs: now,
    });
    const risk = runtimeRiskPolicyView(database);
    if (
        risk.state !== 'current' ||
        risk.policy === null ||
        risk.policyHash === null ||
        risk.revision === null
    ) {
        throw new Error('quick confirmation requires the current risk policy');
    }
    const resolvedDefinition = JSON.parse(strategy.definition_json);
    const contractUnit = BigInt(contractEvidence.contract.contractUnit);
    const commonLots = BigInt(order.commonLots);
    const baseShares = commonLots * contractUnit;
    if (baseShares < 1n || baseShares > BigInt(Number.MAX_SAFE_INTEGER)) {
        throw new Error('quick confirmation quantity is outside safe bounds');
    }
    resolvedDefinition.parameters.condition = {
        comparator: condition.comparator,
        field: condition.field,
        mappingRevision: condition.mappingRevision,
        threshold: condition.threshold,
    };
    resolvedDefinition.parameters.order.contractUnit = String(contractUnit);
    resolvedDefinition.parameters.order.baseShares = String(baseShares);
    resolvedDefinition.parameters.order.policyRevision =
        risk.policy.policyRevision;
    if (resolvedDefinition.parameters.order.limitPrice !== null) {
        assertCanonicalContractPrice(
            resolvedDefinition.parameters.order.limitPrice,
            contractEvidence,
            'quick broker limit price',
        );
    }
    assertCanonicalSmartOrderDraft(resolvedDefinition, { expectedKind: 'quick' });
    const resolvedDefinitionJson = canonicalJson(
        resolvedDefinition,
        'quick confirmation resolved definition',
    );
    const resolvedDefinitionHash = `sha256:${createHash('sha256')
        .update(resolvedDefinitionJson)
        .digest('hex')}`;
    const content = Object.freeze({
        schemaVersion: STRATEGY_CONFIRMATION_SCHEMA_VERSION,
        strategyId,
        strategyKind: 'quick',
        strategyRevision: strategy.revision,
        sourceDefinitionHash: strategy.definition_hash,
        resolvedDefinitionHash,
        resolvedDefinition,
        fixedAccount: Object.freeze({
            accountBrokerRef,
            accountIdRef,
            accountScopeSha256: contractEvidence.accountScopeSha256,
        }),
        tradeDate: resolvedDefinition.parameters.validity.startDate,
        position: null,
        quickFieldMapping: Object.freeze({
            field: condition.field,
            localUnit: condition.localUnit,
            sourceKind: condition.sourceKind,
            revision: condition.mappingRevision,
            definitionSha256: condition.mappingDefinitionSha256,
        }),
        contract: contractEvidence.contract,
        contractEvidenceHash: contractEvidence.evidenceSha256,
        contractRevision: contractEvidence.contractRevision,
        corporateActionRevision: contractEvidence.corporateActionRevision,
        gate: Object.freeze({
            manifestRevision: gate.manifestRevision,
            manifestHash: gate.manifestSha256,
            mappingRevision: gate.mappingRevision,
        }),
        risk: Object.freeze({
            revision: risk.revision,
            policyRevision: risk.policy.policyRevision,
            policyHash: risk.policyHash,
        }),
        runtime: Object.freeze({
            runtimeEpochId,
            senderFence,
            apiGeneration,
            revision: runtime.revision,
        }),
        disclosureVersion: 'smart-order-local-runtime-disclosure/2026-08-20.1',
        warnings: Object.freeze([
            'local_runtime_not_broker_cloud',
            'restart_requires_reconciliation_and_user_rearm',
            'broker_write_not_authorized',
        ]),
        createdAtEpochMs,
        validUntilEpochMs: Math.min(
            contractEvidence.validUntilEpochMs,
            gate.validUntilEpochMs,
        ),
    });
    if (content.validUntilEpochMs <= now) {
        throw new Error('quick confirmation expired during construction');
    }
    return Object.freeze({
        content,
        snapshotHash: sha256Canonical(content, 'canonical confirmation snapshot'),
        resolvedDefinitionJson,
        identityGroupId: authenticatedIdentityGroupForAccount(
            database,
            accountBrokerRef,
            accountIdRef,
        ),
        storagePosition: Object.freeze({
            accountHeadRevision: 0,
            positionLineageId: 'not_applicable',
            positionEvidenceHash: contractEvidence.evidenceSha256,
        }),
    });
}

function inclusiveCalendarDateSpan(startDate, endDate) {
    const start = taipeiTradeDate(startDate);
    const end = taipeiTradeDate(endDate);
    const toDay = (value) => {
        const [year, month, day] = value.split('-').map(Number);
        const epoch = Date.UTC(year, month - 1, day);
        if (new Date(epoch).toISOString().slice(0, 10) !== value) {
            throw new Error('good-till validity contains an invalid calendar date');
        }
        return epoch / 86_400_000;
    };
    const span = toDay(end) - toDay(start) + 1;
    if (!Number.isSafeInteger(span) || span < 1 || span > 30) {
        throw new Error('good-till validity must be an inclusive 1-30 day range');
    }
    return span;
}

function buildGoodTillStrategyConfirmationSnapshot(
    database,
    input,
    { snapshotCreatedAtEpochMs = input.nowEpochMs } = {},
) {
    const now = safeInteger(input.nowEpochMs, 'confirmation.nowEpochMs');
    const createdAtEpochMs = safeInteger(
        snapshotCreatedAtEpochMs,
        'confirmation.snapshotCreatedAtEpochMs',
    );
    if (createdAtEpochMs > now || input.basisSelection !== null) {
        throw new TypeError('good-till confirmation does not accept a position basis');
    }
    const strategyId = boundedToken(input.strategyId, 'confirmation.strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'confirmation.expectedRevision',
    );
    const accountBrokerRef = boundedToken(
        input.accountBrokerRef,
        'confirmation.accountBrokerRef',
    );
    const accountIdRef = boundedToken(
        input.accountIdRef,
        'confirmation.accountIdRef',
    );
    const runtimeEpochId = boundedToken(
        input.runtimeEpochId,
        'confirmation.runtimeEpochId',
    );
    const senderFence = boundedToken(input.senderFence, 'confirmation.senderFence');
    const apiGeneration = boundedToken(
        input.apiGeneration,
        'confirmation.apiGeneration',
    );
    const orderEvidence = canonicalConfirmationContractEvidence(
        input.contractEvidence,
    );
    const monitorEvidence = canonicalConfirmationContractEvidence(
        input.monitorContractEvidence,
    );
    const runtime = database.prepare(`
        SELECT state, revision FROM runtime_epochs
         WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
    `).get(runtimeEpochId, senderFence, apiGeneration);
    const strategy = database
        .prepare('SELECT * FROM strategies WHERE strategy_id=?')
        .get(strategyId);
    if (
        !runtime ||
        runtime.state !== 'ready' ||
        !strategy ||
        strategy.state !== 'draft' ||
        strategy.revision !== expectedRevision ||
        strategy.strategy_kind !== 'good_till'
    ) {
        throw new Error('good-till confirmation requires the current ready draft');
    }
    const definition = parseStoredCanonicalObject(
        strategy.definition_json,
        'good-till confirmation draft',
    );
    assertCanonicalSmartOrderDraft(definition, { expectedKind: 'good_till' });
    const order = definition.parameters.order;
    const condition = canonicalSmartOrderQuickCondition(
        definition.parameters.condition,
    );
    const accountScopeSha256 = confirmationAccountScopeSha256(
        accountBrokerRef,
        accountIdRef,
    );
    const expectedRuntimeKey = (draftKey) => {
        const match = /^(TSE|OTC):STK:([A-Za-z0-9][A-Za-z0-9._-]{0,31})$/.exec(
            draftKey,
        );
        if (!match) throw new Error('good-till contract is unsupported');
        return `${match[1]}:${match[2]}:STK:Common`;
    };
    if (
        orderEvidence.contract.draftContractKey !== order.contractKey ||
        orderEvidence.contract.runtimeContractKey !==
            expectedRuntimeKey(order.contractKey) ||
        monitorEvidence.contract.draftContractKey !==
            definition.parameters.monitorContractKey ||
        monitorEvidence.contract.runtimeContractKey !==
            expectedRuntimeKey(definition.parameters.monitorContractKey) ||
        orderEvidence.accountScopeSha256 !== accountScopeSha256 ||
        monitorEvidence.accountScopeSha256 !== accountScopeSha256 ||
        [orderEvidence, monitorEvidence].some(
            (evidence) =>
                evidence.runtimeEpochId !== runtimeEpochId ||
                evidence.apiGeneration !== apiGeneration ||
                evidence.mappingRevision !==
                    SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
                evidence.observedAtEpochMs > now ||
                evidence.validUntilEpochMs <= now,
        )
    ) {
        throw new Error('good-till order/monitor contract evidence changed');
    }
    inclusiveCalendarDateSpan(
        definition.parameters.validity.startDate,
        definition.parameters.validity.endDate,
    );
    const gate = gateManifestStatus(database, {
        provenance: 'automation',
        nowEpochMs: now,
    });
    if (
        gate.state !== 'eligible' ||
        gate.featureGates.good_till !== true ||
        gate.manifestRevision !== orderEvidence.gateManifestRevision ||
        gate.manifestRevision !== monitorEvidence.gateManifestRevision ||
        gate.manifestSha256 !== orderEvidence.gateManifestHash ||
        gate.manifestSha256 !== monitorEvidence.gateManifestHash ||
        gate.mappingRevision !== SMART_ORDER_QUICK_FIELD_MAPPING_REVISION
    ) {
        throw new Error('good-till Gate/calendar/mapping head changed');
    }
    observeCanonicalContractHead(database, {
        accountBrokerRef,
        accountIdRef,
        contractEvidence: orderEvidence,
        nowEpochMs: now,
    });
    observeCanonicalContractHead(database, {
        accountBrokerRef,
        accountIdRef,
        contractEvidence: monitorEvidence,
        nowEpochMs: now,
    });
    const risk = runtimeRiskPolicyView(database);
    if (
        risk.state !== 'current' ||
        risk.policy === null ||
        risk.policyHash === null ||
        risk.revision === null
    ) {
        throw new Error('good-till confirmation requires the current risk policy');
    }
    if (order.priceType !== 'LMT' || !['ROD', 'IOC'].includes(order.timeInForce)) {
        throw new Error('good-till currently supports only verified LMT/ROD or LMT/IOC');
    }
    const contractUnit = BigInt(orderEvidence.contract.contractUnit);
    const targetShares = BigInt(definition.parameters.targetBaseShares);
    const perOrderShares = BigInt(definition.parameters.perOrderMaxBaseShares);
    if (
        contractUnit < 1n ||
        targetShares < 1n ||
        perOrderShares < 1n ||
        targetShares > BigInt(Number.MAX_SAFE_INTEGER) ||
        perOrderShares > targetShares ||
        targetShares % contractUnit !== 0n ||
        perOrderShares % contractUnit !== 0n ||
        BigInt(order.commonLots) * contractUnit !== perOrderShares
    ) {
        throw new Error('good-till target/per-order quantities are not exact Common lots');
    }
    assertCanonicalContractPrice(
        order.limitPrice,
        orderEvidence,
        'good-till broker limit price',
    );
    const resolvedDefinition = JSON.parse(strategy.definition_json);
    resolvedDefinition.parameters.condition = {
        comparator: condition.comparator,
        field: condition.field,
        mappingRevision: condition.mappingRevision,
        threshold: condition.threshold,
    };
    resolvedDefinition.parameters.order.contractUnit = String(contractUnit);
    resolvedDefinition.parameters.order.baseShares = String(perOrderShares);
    resolvedDefinition.parameters.order.policyRevision =
        risk.policy.policyRevision;
    assertCanonicalSmartOrderDraft(resolvedDefinition, {
        expectedKind: 'good_till',
    });
    const resolvedDefinitionJson = canonicalJson(
        resolvedDefinition,
        'good-till confirmation resolved definition',
    );
    const resolvedDefinitionHash = `sha256:${createHash('sha256')
        .update(resolvedDefinitionJson)
        .digest('hex')}`;
    const content = Object.freeze({
        schemaVersion: STRATEGY_CONFIRMATION_SCHEMA_VERSION,
        strategyId,
        strategyKind: 'good_till',
        strategyRevision: strategy.revision,
        sourceDefinitionHash: strategy.definition_hash,
        resolvedDefinitionHash,
        resolvedDefinition,
        fixedAccount: Object.freeze({
            accountBrokerRef,
            accountIdRef,
            accountScopeSha256,
        }),
        tradeDate: resolvedDefinition.parameters.validity.startDate,
        position: null,
        quickFieldMapping: Object.freeze({
            field: condition.field,
            localUnit: condition.localUnit,
            sourceKind: condition.sourceKind,
            revision: condition.mappingRevision,
            definitionSha256: condition.mappingDefinitionSha256,
        }),
        contract: orderEvidence.contract,
        contractEvidenceHash: orderEvidence.evidenceSha256,
        contractRevision: orderEvidence.contractRevision,
        corporateActionRevision: orderEvidence.corporateActionRevision,
        monitorContract: monitorEvidence.contract,
        monitorContractEvidenceHash: monitorEvidence.evidenceSha256,
        monitorContractRevision: monitorEvidence.contractRevision,
        monitorCorporateActionRevision:
            monitorEvidence.corporateActionRevision,
        gate: Object.freeze({
            manifestRevision: gate.manifestRevision,
            manifestHash: gate.manifestSha256,
            mappingRevision: gate.mappingRevision,
        }),
        risk: Object.freeze({
            revision: risk.revision,
            policyRevision: risk.policy.policyRevision,
            policyHash: risk.policyHash,
        }),
        runtime: Object.freeze({
            runtimeEpochId,
            senderFence,
            apiGeneration,
            revision: runtime.revision,
        }),
        disclosureVersion: 'smart-order-local-runtime-disclosure/2026-08-20.1',
        warnings: Object.freeze([
            'local_runtime_not_broker_cloud',
            'one_activation_per_verified_trade_date',
            'broker_write_not_authorized',
        ]),
        createdAtEpochMs,
        validUntilEpochMs: Math.min(
            orderEvidence.validUntilEpochMs,
            monitorEvidence.validUntilEpochMs,
            gate.validUntilEpochMs,
        ),
    });
    if (content.validUntilEpochMs <= now) {
        throw new Error('good-till confirmation expired during construction');
    }
    return Object.freeze({
        content,
        snapshotHash: sha256Canonical(content, 'canonical confirmation snapshot'),
        resolvedDefinitionJson,
        identityGroupId: authenticatedIdentityGroupForAccount(
            database,
            accountBrokerRef,
            accountIdRef,
        ),
        storagePosition: Object.freeze({
            accountHeadRevision: 0,
            positionLineageId: 'not_applicable',
            positionEvidenceHash: orderEvidence.evidenceSha256,
        }),
    });
}

function buildMultiConditionStrategyConfirmationSnapshot(
    database,
    input,
    { snapshotCreatedAtEpochMs = input.nowEpochMs } = {},
) {
    const now = safeInteger(input.nowEpochMs, 'confirmation.nowEpochMs');
    const createdAtEpochMs = safeInteger(
        snapshotCreatedAtEpochMs,
        'confirmation.snapshotCreatedAtEpochMs',
    );
    if (
        createdAtEpochMs > now ||
        input.basisSelection !== null ||
        !Array.isArray(input.monitorContractEvidence) ||
        input.monitorContractEvidence.length < 1 ||
        input.monitorContractEvidence.length > 7
    ) {
        throw new TypeError('multi-condition confirmation evidence is invalid');
    }
    const strategyId = boundedToken(input.strategyId, 'confirmation.strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'confirmation.expectedRevision',
    );
    const accountBrokerRef = boundedToken(
        input.accountBrokerRef,
        'confirmation.accountBrokerRef',
    );
    const accountIdRef = boundedToken(
        input.accountIdRef,
        'confirmation.accountIdRef',
    );
    const runtimeEpochId = boundedToken(
        input.runtimeEpochId,
        'confirmation.runtimeEpochId',
    );
    const senderFence = boundedToken(input.senderFence, 'confirmation.senderFence');
    const apiGeneration = boundedToken(
        input.apiGeneration,
        'confirmation.apiGeneration',
    );
    const orderEvidence = canonicalConfirmationContractEvidence(
        input.contractEvidence,
    );
    const monitorEvidence = input.monitorContractEvidence.map((candidate) =>
        canonicalConfirmationContractEvidence(candidate),
    );
    const runtime = database.prepare(`
        SELECT state, revision FROM runtime_epochs
         WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
    `).get(runtimeEpochId, senderFence, apiGeneration);
    const strategy = database
        .prepare('SELECT * FROM strategies WHERE strategy_id=?')
        .get(strategyId);
    if (
        !runtime ||
        runtime.state !== 'ready' ||
        !strategy ||
        strategy.state !== 'draft' ||
        strategy.revision !== expectedRevision ||
        strategy.strategy_kind !== 'multi_condition'
    ) {
        throw new Error('multi-condition confirmation requires the current ready draft');
    }
    const definition = parseStoredCanonicalObject(
        strategy.definition_json,
        'multi-condition confirmation draft',
    );
    assertCanonicalSmartOrderDraft(definition, { expectedKind: 'multi_condition' });
    if (definition.parameters.conditions.length !== monitorEvidence.length) {
        throw new Error('multi-condition evidence count changed');
    }
    inclusiveCalendarDateSpan(
        definition.parameters.validity.startDate,
        definition.parameters.validity.endDate,
    );
    const expectedRuntimeKey = (draftKey) => {
        const match = /^(TSE|OTC):STK:([A-Za-z0-9][A-Za-z0-9._-]{0,31})$/.exec(
            draftKey,
        );
        if (!match) throw new Error('multi-condition contract is unsupported');
        return `${match[1]}:${match[2]}:STK:Common`;
    };
    const accountScopeSha256 = confirmationAccountScopeSha256(
        accountBrokerRef,
        accountIdRef,
    );
    const allEvidence = [orderEvidence, ...monitorEvidence];
    if (
        orderEvidence.contract.draftContractKey !==
            definition.parameters.order.contractKey ||
        orderEvidence.contract.runtimeContractKey !==
            expectedRuntimeKey(definition.parameters.order.contractKey) ||
        allEvidence.some(
            (evidence) =>
                evidence.accountScopeSha256 !== accountScopeSha256 ||
                evidence.runtimeEpochId !== runtimeEpochId ||
                evidence.apiGeneration !== apiGeneration ||
                evidence.mappingRevision !==
                    SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
                evidence.observedAtEpochMs > now ||
                evidence.validUntilEpochMs <= now,
        ) ||
        monitorEvidence.some(
            (evidence, index) =>
                evidence.contract.draftContractKey !==
                    definition.parameters.conditions[index].monitorContractKey ||
                evidence.contract.runtimeContractKey !==
                    expectedRuntimeKey(
                        definition.parameters.conditions[index].monitorContractKey,
                    ),
        )
    ) {
        throw new Error('multi-condition order/monitor evidence changed');
    }
    const gate = gateManifestStatus(database, {
        provenance: 'automation',
        nowEpochMs: now,
    });
    if (
        gate.state !== 'eligible' ||
        gate.featureGates.multi_condition !== true ||
        allEvidence.some(
            (evidence) =>
                evidence.gateManifestRevision !== gate.manifestRevision ||
                evidence.gateManifestHash !== gate.manifestSha256,
        ) ||
        gate.mappingRevision !== SMART_ORDER_QUICK_FIELD_MAPPING_REVISION
    ) {
        throw new Error('multi-condition Gate or mapping head changed');
    }
    for (const evidence of allEvidence) {
        observeCanonicalContractHead(database, {
            accountBrokerRef,
            accountIdRef,
            contractEvidence: evidence,
            nowEpochMs: now,
        });
    }
    const risk = runtimeRiskPolicyView(database);
    if (
        risk.state !== 'current' ||
        risk.policy === null ||
        risk.policyHash === null ||
        risk.revision === null
    ) {
        throw new Error('multi-condition confirmation requires current risk policy');
    }
    const resolvedDefinition = JSON.parse(strategy.definition_json);
    const order = resolvedDefinition.parameters.order;
    const contractUnit = BigInt(orderEvidence.contract.contractUnit);
    const baseShares = BigInt(order.commonLots) * contractUnit;
    if (baseShares < 1n || baseShares > BigInt(Number.MAX_SAFE_INTEGER)) {
        throw new Error('multi-condition order quantity is outside safe bounds');
    }
    if (order.priceType !== 'LMT' || !['ROD', 'IOC'].includes(order.timeInForce)) {
        throw new Error('multi-condition currently supports verified LMT/ROD or LMT/IOC');
    }
    assertCanonicalContractPrice(
        order.limitPrice,
        orderEvidence,
        'multi-condition broker limit price',
    );
    const monitorConditions = resolvedDefinition.parameters.conditions.map(
        (leg, index) => {
            const condition = canonicalSmartOrderQuickCondition(leg.condition);
            leg.condition = {
                comparator: condition.comparator,
                field: condition.field,
                mappingRevision: condition.mappingRevision,
                threshold: condition.threshold,
            };
            const evidence = monitorEvidence[index];
            return Object.freeze({
                conditionIndex: index,
                monitorContract: evidence.contract,
                monitorContractEvidenceHash: evidence.evidenceSha256,
                monitorContractRevision: evidence.contractRevision,
                monitorCorporateActionRevision:
                    evidence.corporateActionRevision,
                quickFieldMapping: Object.freeze({
                    field: condition.field,
                    localUnit: condition.localUnit,
                    sourceKind: condition.sourceKind,
                    revision: condition.mappingRevision,
                    definitionSha256: condition.mappingDefinitionSha256,
                }),
            });
        },
    );
    order.contractUnit = String(contractUnit);
    order.baseShares = String(baseShares);
    order.policyRevision = risk.policy.policyRevision;
    assertCanonicalSmartOrderDraft(resolvedDefinition, {
        expectedKind: 'multi_condition',
    });
    const resolvedDefinitionJson = canonicalJson(
        resolvedDefinition,
        'multi-condition confirmation resolved definition',
    );
    const resolvedDefinitionHash = `sha256:${createHash('sha256')
        .update(resolvedDefinitionJson)
        .digest('hex')}`;
    const content = Object.freeze({
        schemaVersion: STRATEGY_CONFIRMATION_SCHEMA_VERSION,
        strategyId,
        strategyKind: 'multi_condition',
        strategyRevision: strategy.revision,
        sourceDefinitionHash: strategy.definition_hash,
        resolvedDefinitionHash,
        resolvedDefinition,
        fixedAccount: Object.freeze({
            accountBrokerRef,
            accountIdRef,
            accountScopeSha256,
        }),
        tradeDate: resolvedDefinition.parameters.validity.startDate,
        position: null,
        quickFieldMapping: null,
        monitorConditions: Object.freeze(monitorConditions),
        contract: orderEvidence.contract,
        contractEvidenceHash: orderEvidence.evidenceSha256,
        contractRevision: orderEvidence.contractRevision,
        corporateActionRevision: orderEvidence.corporateActionRevision,
        gate: Object.freeze({
            manifestRevision: gate.manifestRevision,
            manifestHash: gate.manifestSha256,
            mappingRevision: gate.mappingRevision,
        }),
        risk: Object.freeze({
            revision: risk.revision,
            policyRevision: risk.policy.policyRevision,
            policyHash: risk.policyHash,
        }),
        runtime: Object.freeze({
            runtimeEpochId,
            senderFence,
            apiGeneration,
            revision: runtime.revision,
        }),
        disclosureVersion: 'smart-order-local-runtime-disclosure/2026-08-20.1',
        warnings: Object.freeze([
            'all_monitor_contracts_must_remain_current',
            'and_requires_same_date_epoch_and_three_second_coherence',
            'broker_write_not_authorized',
        ]),
        createdAtEpochMs,
        validUntilEpochMs: Math.min(
            gate.validUntilEpochMs,
            ...allEvidence.map((evidence) => evidence.validUntilEpochMs),
        ),
    });
    if (content.validUntilEpochMs <= now) {
        throw new Error('multi-condition confirmation expired during construction');
    }
    return Object.freeze({
        content,
        snapshotHash: sha256Canonical(content, 'canonical confirmation snapshot'),
        resolvedDefinitionJson,
        identityGroupId: authenticatedIdentityGroupForAccount(
            database,
            accountBrokerRef,
            accountIdRef,
        ),
        storagePosition: Object.freeze({
            accountHeadRevision: 0,
            positionLineageId: 'not_applicable',
            positionEvidenceHash: orderEvidence.evidenceSha256,
        }),
    });
}

function buildParentChildStrategyConfirmationSnapshot(
    database,
    input,
    { snapshotCreatedAtEpochMs = input.nowEpochMs } = {},
) {
    const now = safeInteger(input.nowEpochMs, 'confirmation.nowEpochMs');
    const createdAtEpochMs = safeInteger(
        snapshotCreatedAtEpochMs,
        'confirmation.snapshotCreatedAtEpochMs',
    );
    if (
        createdAtEpochMs > now ||
        input.basisSelection !== null ||
        !Array.isArray(input.monitorContractEvidence) ||
        input.monitorContractEvidence.length !== 1
    ) {
        throw new TypeError('parent-child confirmation evidence is invalid');
    }
    const strategyId = boundedToken(input.strategyId, 'confirmation.strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'confirmation.expectedRevision',
    );
    const accountBrokerRef = boundedToken(
        input.accountBrokerRef,
        'confirmation.accountBrokerRef',
    );
    const accountIdRef = boundedToken(
        input.accountIdRef,
        'confirmation.accountIdRef',
    );
    const runtimeEpochId = boundedToken(
        input.runtimeEpochId,
        'confirmation.runtimeEpochId',
    );
    const senderFence = boundedToken(input.senderFence, 'confirmation.senderFence');
    const apiGeneration = boundedToken(
        input.apiGeneration,
        'confirmation.apiGeneration',
    );
    const parentEvidence = canonicalConfirmationContractEvidence(
        input.contractEvidence,
    );
    const childEvidence = canonicalConfirmationContractEvidence(
        input.monitorContractEvidence[0],
    );
    const runtime = database.prepare(`
        SELECT state, revision FROM runtime_epochs
         WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
    `).get(runtimeEpochId, senderFence, apiGeneration);
    const strategy = database
        .prepare('SELECT * FROM strategies WHERE strategy_id=?')
        .get(strategyId);
    if (
        !runtime ||
        runtime.state !== 'ready' ||
        !strategy ||
        strategy.state !== 'draft' ||
        strategy.revision !== expectedRevision ||
        strategy.strategy_kind !== 'parent_child'
    ) {
        throw new Error('parent-child confirmation requires the current ready draft');
    }
    const definition = parseStoredCanonicalObject(
        strategy.definition_json,
        'parent-child confirmation draft',
    );
    assertCanonicalSmartOrderDraft(definition, { expectedKind: 'parent_child' });
    inclusiveCalendarDateSpan(
        definition.parameters.parentValidity.startDate,
        definition.parameters.parentValidity.endDate,
    );
    const expectedRuntimeKey = (draftKey) => {
        const match = /^(TSE|OTC):STK:([A-Za-z0-9][A-Za-z0-9._-]{0,31})$/.exec(
            draftKey,
        );
        if (!match) throw new Error('parent-child contract is unsupported');
        return `${match[1]}:${match[2]}:STK:Common`;
    };
    const accountScopeSha256 = confirmationAccountScopeSha256(
        accountBrokerRef,
        accountIdRef,
    );
    const parent = definition.parameters.parent;
    const child = definition.parameters.child;
    const allEvidence = [parentEvidence, childEvidence];
    if (
        parent.monitorContractKey !== parent.order.contractKey ||
        child.monitorContractKey !== child.order.contractKey ||
        parentEvidence.contract.draftContractKey !== parent.order.contractKey ||
        childEvidence.contract.draftContractKey !== child.order.contractKey ||
        parentEvidence.contract.runtimeContractKey !==
            expectedRuntimeKey(parent.order.contractKey) ||
        childEvidence.contract.runtimeContractKey !==
            expectedRuntimeKey(child.order.contractKey) ||
        allEvidence.some(
            (evidence) =>
                evidence.accountScopeSha256 !== accountScopeSha256 ||
                evidence.runtimeEpochId !== runtimeEpochId ||
                evidence.apiGeneration !== apiGeneration ||
                evidence.mappingRevision !==
                    SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
                evidence.observedAtEpochMs > now ||
                evidence.validUntilEpochMs <= now,
        )
    ) {
        throw new Error('parent-child contract evidence changed');
    }
    const gate = gateManifestStatus(database, {
        provenance: 'automation',
        nowEpochMs: now,
    });
    if (
        gate.state !== 'eligible' ||
        gate.featureGates.parent_child !== true ||
        allEvidence.some(
            (evidence) =>
                evidence.gateManifestRevision !== gate.manifestRevision ||
                evidence.gateManifestHash !== gate.manifestSha256,
        ) ||
        gate.mappingRevision !== SMART_ORDER_QUICK_FIELD_MAPPING_REVISION
    ) {
        throw new Error('parent-child Gate or mapping head changed');
    }
    for (const evidence of allEvidence) {
        observeCanonicalContractHead(database, {
            accountBrokerRef,
            accountIdRef,
            contractEvidence: evidence,
            nowEpochMs: now,
        });
    }
    const risk = runtimeRiskPolicyView(database);
    if (
        risk.state !== 'current' ||
        risk.policy === null ||
        risk.policyHash === null ||
        risk.revision === null
    ) {
        throw new Error('parent-child confirmation requires current risk policy');
    }
    const childPosition = database.prepare(`
        SELECT positions.*, heads.revision AS current_head_revision,
               heads.source_revision AS current_source_revision,
               heads.source_snapshot_hash AS current_snapshot_hash,
               heads.evidence_hash AS current_evidence_hash,
               heads.as_of_epoch_ms AS current_as_of_epoch_ms
          FROM account_reconciliation_positions AS positions
          JOIN account_reconciliation_heads AS heads
            ON heads.account_broker_ref=positions.account_broker_ref
           AND heads.account_id_ref=positions.account_id_ref
           AND heads.trade_date=positions.trade_date
         WHERE positions.account_broker_ref=? AND positions.account_id_ref=?
           AND positions.contract_key=?
         ORDER BY positions.as_of_epoch_ms DESC, positions.trade_date DESC
         LIMIT 1
    `).get(
        accountBrokerRef,
        accountIdRef,
        childEvidence.contract.runtimeContractKey,
    );
    const childShares =
        BigInt(child.order.commonLots) *
        BigInt(childEvidence.contract.contractUnit);
    if (
        !childPosition ||
        childPosition.valid_until_epoch_ms <= now ||
        childPosition.as_of_epoch_ms > now ||
        childPosition.current_as_of_epoch_ms !== childPosition.as_of_epoch_ms ||
        childPosition.current_head_revision !== childPosition.account_head_revision ||
        childPosition.current_source_revision !== childPosition.source_revision ||
        childPosition.current_snapshot_hash !== childPosition.source_snapshot_hash ||
        childPosition.current_evidence_hash !== childPosition.evidence_hash ||
        childShares < 1n ||
        childShares > BigInt(Number.MAX_SAFE_INTEGER) ||
        childShares > BigInt(childPosition.available_shares)
    ) {
        throw new Error('parent-child child position is missing, stale, or insufficient');
    }
    const resolvedDefinition = JSON.parse(strategy.definition_json);
    const resolveLeg = (leg, evidence, label) => {
        const condition = canonicalSmartOrderQuickCondition(leg.condition);
        const contractUnit = BigInt(evidence.contract.contractUnit);
        const baseShares = BigInt(leg.order.commonLots) * contractUnit;
        if (
            baseShares < 1n ||
            baseShares > BigInt(Number.MAX_SAFE_INTEGER) ||
            leg.order.priceType !== 'LMT' ||
            !['ROD', 'IOC'].includes(leg.order.timeInForce)
        ) {
            throw new Error(`${label} order policy or quantity is unsupported`);
        }
        assertCanonicalContractPrice(
            leg.order.limitPrice,
            evidence,
            `${label} broker limit price`,
        );
        leg.condition = {
            comparator: condition.comparator,
            field: condition.field,
            mappingRevision: condition.mappingRevision,
            threshold: condition.threshold,
        };
        leg.order.contractUnit = String(contractUnit);
        leg.order.baseShares = String(baseShares);
        leg.order.policyRevision = risk.policy.policyRevision;
        return Object.freeze({
            condition: Object.freeze({
                comparator: condition.comparator,
                field: condition.field,
                threshold: condition.threshold,
            }),
            quickFieldMapping: Object.freeze({
                field: condition.field,
                localUnit: condition.localUnit,
                sourceKind: condition.sourceKind,
                revision: condition.mappingRevision,
                definitionSha256: condition.mappingDefinitionSha256,
            }),
        });
    };
    const parentLeg = resolveLeg(
        resolvedDefinition.parameters.parent,
        parentEvidence,
        'parent-child parent',
    );
    const childLeg = resolveLeg(
        resolvedDefinition.parameters.child,
        childEvidence,
        'parent-child child',
    );
    assertCanonicalSmartOrderDraft(resolvedDefinition, {
        expectedKind: 'parent_child',
    });
    const resolvedDefinitionJson = canonicalJson(
        resolvedDefinition,
        'parent-child confirmation resolved definition',
    );
    const resolvedDefinitionHash = `sha256:${createHash('sha256')
        .update(resolvedDefinitionJson)
        .digest('hex')}`;
    const content = Object.freeze({
        schemaVersion: STRATEGY_CONFIRMATION_SCHEMA_VERSION,
        strategyId,
        strategyKind: 'parent_child',
        strategyRevision: strategy.revision,
        sourceDefinitionHash: strategy.definition_hash,
        resolvedDefinitionHash,
        resolvedDefinition,
        fixedAccount: Object.freeze({
            accountBrokerRef,
            accountIdRef,
            accountScopeSha256,
        }),
        tradeDate: childPosition.trade_date,
        position: Object.freeze({
            contractKey: childEvidence.contract.runtimeContractKey,
            positionLineageId: childPosition.position_lineage_id,
            quantityShares: childPosition.quantity_shares,
            availableShares: childPosition.available_shares,
            evidenceHash: childPosition.evidence_hash,
            asOfEpochMs: childPosition.as_of_epoch_ms,
        }),
        quickFieldMapping: null,
        parentLeg,
        childLeg,
        contract: parentEvidence.contract,
        contractEvidenceHash: parentEvidence.evidenceSha256,
        contractRevision: parentEvidence.contractRevision,
        corporateActionRevision: parentEvidence.corporateActionRevision,
        childContract: childEvidence.contract,
        childContractEvidenceHash: childEvidence.evidenceSha256,
        childContractRevision: childEvidence.contractRevision,
        childCorporateActionRevision: childEvidence.corporateActionRevision,
        gate: Object.freeze({
            manifestRevision: gate.manifestRevision,
            manifestHash: gate.manifestSha256,
            mappingRevision: gate.mappingRevision,
        }),
        risk: Object.freeze({
            revision: risk.revision,
            policyRevision: risk.policy.policyRevision,
            policyHash: risk.policyHash,
        }),
        runtime: Object.freeze({
            runtimeEpochId,
            senderFence,
            apiGeneration,
            revision: runtime.revision,
        }),
        disclosureVersion: 'smart-order-local-runtime-disclosure/2026-08-20.1',
        warnings: Object.freeze([
            'parent_and_child_contracts_are_distinct',
            'child_requires_parent_broker_confirmed_full_fill',
            'child_is_same_trade_date_only',
            'broker_write_not_authorized',
        ]),
        createdAtEpochMs,
        validUntilEpochMs: Math.min(
            gate.validUntilEpochMs,
            parentEvidence.validUntilEpochMs,
            childEvidence.validUntilEpochMs,
            childPosition.valid_until_epoch_ms,
        ),
    });
    if (content.validUntilEpochMs <= now) {
        throw new Error('parent-child confirmation expired during construction');
    }
    return Object.freeze({
        content,
        snapshotHash: sha256Canonical(content, 'canonical confirmation snapshot'),
        resolvedDefinitionJson,
        identityGroupId: authenticatedIdentityGroupForAccount(
            database,
            accountBrokerRef,
            accountIdRef,
        ),
        storagePosition: Object.freeze({
            accountHeadRevision: childPosition.account_head_revision,
            positionLineageId: childPosition.position_lineage_id,
            positionEvidenceHash: childPosition.evidence_hash,
        }),
    });
}

function buildStrategyConfirmationSnapshot(
    database,
    input,
    { snapshotCreatedAtEpochMs = input.nowEpochMs } = {},
) {
    const candidateKind = database
        .prepare('SELECT strategy_kind FROM strategies WHERE strategy_id=?')
        .get(input.strategyId)?.strategy_kind;
    if (candidateKind === 'scheduled_quantity') {
        const strategy = database
            .prepare('SELECT definition_json FROM strategies WHERE strategy_id=?')
            .get(input.strategyId);
        let definition;
        try {
            definition = JSON.parse(strategy.definition_json);
            assertCanonicalSmartOrderDraft(definition, {
                expectedKind: 'scheduled_quantity',
            });
        } catch {
            throw new Error(
                'scheduled quantity strategy definition is not canonical',
            );
        }
        const decision = scheduledQuantityModeDecision(
            definition.parameters.mode,
        );
        throw new Error(
            `scheduled quantity ${decision.mode} mode is disabled: ${decision.blocker}`,
        );
    }
    if (candidateKind === 'quick') {
        return buildQuickStrategyConfirmationSnapshot(database, input, {
            snapshotCreatedAtEpochMs,
        });
    }
    if (candidateKind === 'good_till') {
        return buildGoodTillStrategyConfirmationSnapshot(database, input, {
            snapshotCreatedAtEpochMs,
        });
    }
    if (candidateKind === 'multi_condition') {
        return buildMultiConditionStrategyConfirmationSnapshot(database, input, {
            snapshotCreatedAtEpochMs,
        });
    }
    if (candidateKind === 'parent_child') {
        return buildParentChildStrategyConfirmationSnapshot(database, input, {
            snapshotCreatedAtEpochMs,
        });
    }
    if (input.monitorContractEvidence !== null) {
        throw new TypeError(
            'only good-till, multi-condition, or parent-child confirmation accepts distinct monitor evidence',
        );
    }
    const now = safeInteger(input.nowEpochMs, 'confirmation.nowEpochMs');
    const createdAtEpochMs = safeInteger(
        snapshotCreatedAtEpochMs,
        'confirmation.snapshotCreatedAtEpochMs',
    );
    if (createdAtEpochMs > now) {
        throw new Error('canonical confirmation snapshot is future-dated');
    }
    const strategyId = boundedToken(input.strategyId, 'confirmation.strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'confirmation.expectedRevision',
    );
    const accountBrokerRef = boundedToken(
        input.accountBrokerRef,
        'confirmation.accountBrokerRef',
    );
    const accountIdRef = boundedToken(
        input.accountIdRef,
        'confirmation.accountIdRef',
    );
    const runtimeEpochId = boundedToken(
        input.runtimeEpochId,
        'confirmation.runtimeEpochId',
    );
    const senderFence = boundedToken(
        input.senderFence,
        'confirmation.senderFence',
    );
    const apiGeneration = boundedToken(
        input.apiGeneration,
        'confirmation.apiGeneration',
    );
    const basisSelection = canonicalConfirmationBasis(input.basisSelection);
    const contractEvidence = canonicalConfirmationContractEvidence(
        input.contractEvidence,
    );
    const runtime = database.prepare(`
        SELECT state, revision FROM runtime_epochs
         WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
    `).get(runtimeEpochId, senderFence, apiGeneration);
    if (!runtime || runtime.state !== 'ready') {
        throw new Error('canonical confirmation requires the current ready Runtime');
    }
    const strategy = database
        .prepare('SELECT * FROM strategies WHERE strategy_id=?')
        .get(strategyId);
    if (
        !strategy ||
        strategy.state !== 'draft' ||
        strategy.revision !== expectedRevision ||
        !['stop_take', 'trailing_exit'].includes(strategy.strategy_kind)
    ) {
        throw new Error('canonical confirmation requires the current protection draft');
    }
    let definition;
    try {
        definition = JSON.parse(strategy.definition_json);
    } catch {
        throw new Error('canonical confirmation draft JSON is invalid');
    }
    assertCanonicalSmartOrderDraft(definition, {
        expectedKind: strategy.strategy_kind,
    });
    const parameters = definition.parameters;
    const order = parameters.order;
    const expectedRuntimeContractKey =
        `${order.contractKey.split(':')[0]}:${order.contractKey.split(':')[2]}:STK:Common`;
    if (
        parameters.positionContractKey !== order.contractKey ||
        parameters.monitorContractKey !== order.contractKey ||
        contractEvidence.contract.draftContractKey !== order.contractKey ||
        contractEvidence.contract.runtimeContractKey !== expectedRuntimeContractKey ||
        contractEvidence.accountScopeSha256 !==
            confirmationAccountScopeSha256(accountBrokerRef, accountIdRef) ||
        contractEvidence.runtimeEpochId !== runtimeEpochId ||
        contractEvidence.apiGeneration !== apiGeneration ||
        contractEvidence.observedAtEpochMs > now ||
        contractEvidence.validUntilEpochMs <= now
    ) {
        throw new Error('canonical confirmation contract evidence is not current/scope-bound');
    }
    const gate = gateManifestStatus(database, {
        provenance: 'automation',
        nowEpochMs: now,
    });
    if (
        gate.state !== 'eligible' ||
        gate.featureGates[strategy.strategy_kind] !== true ||
        gate.manifestRevision !== contractEvidence.gateManifestRevision ||
        gate.manifestSha256 !== contractEvidence.gateManifestHash ||
        gate.mappingRevision !== contractEvidence.mappingRevision
    ) {
        throw new Error('canonical confirmation Gate/contract evidence changed');
    }
    observeCanonicalContractHead(database, {
        accountBrokerRef,
        accountIdRef,
        contractEvidence,
        nowEpochMs: now,
    });
    const risk = runtimeRiskPolicyView(database);
    if (
        risk.state !== 'current' ||
        risk.policy === null ||
        risk.policyHash === null ||
        risk.revision === null
    ) {
        throw new Error('canonical confirmation requires the current risk policy');
    }
    const position = database.prepare(`
        SELECT positions.*,
               heads.revision AS current_account_head_revision,
               heads.source_revision AS current_account_source_revision,
               heads.source_snapshot_hash AS current_account_source_snapshot_hash,
               heads.evidence_hash AS current_account_evidence_hash,
               heads.as_of_epoch_ms AS current_account_as_of_epoch_ms
          FROM account_reconciliation_positions AS positions
          JOIN account_reconciliation_heads AS heads
            ON heads.account_broker_ref=positions.account_broker_ref
           AND heads.account_id_ref=positions.account_id_ref
           AND heads.trade_date=positions.trade_date
         WHERE positions.account_broker_ref=? AND positions.account_id_ref=?
           AND positions.contract_key=?
         ORDER BY positions.as_of_epoch_ms DESC, positions.trade_date DESC
         LIMIT 1
    `).get(accountBrokerRef, accountIdRef, expectedRuntimeContractKey);
    if (
        !position ||
        position.valid_until_epoch_ms <= now ||
        position.as_of_epoch_ms > now ||
        position.current_account_as_of_epoch_ms !== position.as_of_epoch_ms ||
        position.current_account_head_revision !==
            position.account_head_revision ||
        position.current_account_source_revision !== position.source_revision ||
        position.current_account_source_snapshot_hash !==
            position.source_snapshot_hash ||
        position.current_account_evidence_hash !== position.evidence_hash
    ) {
        throw new Error('canonical confirmation position is missing or stale');
    }
    const commonLots = BigInt(order.commonLots);
    const contractUnit = BigInt(contractEvidence.contract.contractUnit);
    const baseShares = commonLots * contractUnit;
    if (
        baseShares < 1n ||
        baseShares > BigInt(Number.MAX_SAFE_INTEGER) ||
        baseShares > BigInt(position.available_shares)
    ) {
        throw new Error('canonical confirmation quantity exceeds current available shares');
    }
    let basisPriceMinorUnits;
    let basisPriceDecimal;
    if (basisSelection.source === 'broker_average_cost') {
        if (
            position.average_cost_state !== 'available' ||
            !Number.isSafeInteger(position.average_price_minor_units) ||
            position.average_price_minor_units < 1
        ) {
            throw new Error('broker-confirmed average cost is unavailable');
        }
        basisPriceMinorUnits = position.average_price_minor_units;
        basisPriceDecimal = `${Math.floor(basisPriceMinorUnits / 100)}.${String(
            basisPriceMinorUnits % 100,
        ).padStart(2, '0')}`.replace(/\.00$/, '');
    } else {
        basisPriceDecimal = basisSelection.priceDecimal;
        basisPriceMinorUnits = assertCanonicalContractPrice(
            basisPriceDecimal,
            contractEvidence,
            'user-specified basis',
        );
    }
    const resolvedDefinition = JSON.parse(strategy.definition_json);
    resolvedDefinition.parameters.positionEvidenceRevision =
        `${position.source_revision}:${position.revision}`;
    resolvedDefinition.parameters.order.contractUnit = String(contractUnit);
    resolvedDefinition.parameters.order.baseShares = String(baseShares);
    const draftDistances =
        resolvedDefinition.kind === 'stop_take'
            ? resolvedDefinition.parameters.legs.map((leg) => leg.distance)
            : [
                  resolvedDefinition.parameters.retracement,
              ];
    const fixedAtrRequired = draftDistances.some(
        (distance) => distance.kind === 'fixed_atr',
    );
    const fixedAtrSnapshot = contractEvidence.fixedAtrSnapshot;
    if (
        fixedAtrRequired !== (fixedAtrSnapshot !== null) ||
        (fixedAtrSnapshot !== null &&
            (fixedAtrSnapshot.strategyDefinitionHash !==
                strategy.definition_hash ||
                fixedAtrSnapshot.contractKey !==
                    contractEvidence.contract.runtimeContractKey ||
                fixedAtrSnapshot.contractRevision !==
                    contractEvidence.contractRevision ||
                fixedAtrSnapshot.corporateActionRevision !==
                    contractEvidence.corporateActionRevision ||
                fixedAtrSnapshot.asOfTradingDate >= position.trade_date))
    ) {
        throw new Error(
            'canonical confirmation fixed ATR snapshot is missing, stale or bound to another context',
        );
    }
    if (fixedAtrSnapshot !== null) {
        for (const distance of draftDistances) {
            if (distance.kind !== 'fixed_atr') continue;
            distance.atr = fixedAtrSnapshot.value;
            distance.atrSnapshotRevision = fixedAtrSnapshot.snapshotSha256;
        }
    }
    if (resolvedDefinition.kind === 'stop_take') {
        resolvedDefinition.parameters.basisPrice = basisPriceDecimal;
        resolvedDefinition.parameters.basisSource = basisSelection.source;
        for (const [index, leg] of resolvedDefinition.parameters.legs.entries()) {
            const comparator = leg.type === 'stop' ? 'lte' : 'gte';
            const legalTrigger = canonicalSmartOrderLegalProtectiveTrigger({
                comparator,
                contractPricePolicy: {
                    categoryCode: contractEvidence.contract.categoryCode,
                    limitDownMinorUnits:
                        contractEvidence.contract.limitDownMinorUnits,
                    limitUpMinorUnits:
                        contractEvidence.contract.limitUpMinorUnits,
                },
                theoreticalTrigger:
                    deriveExistingPositionProtectionLegTrigger({
                        basisPriceDecimal,
                        comparator,
                        distance: leg.distance,
                        legId: leg.legId,
                    }),
            });
            leg.triggerPrice = legalTrigger.decimal;
            leg.triggerTicks = String(
                legalTrigger.minorUnits / legalTrigger.tickMinorUnits,
            );
            assertCanonicalContractPrice(
                leg.triggerPrice,
                contractEvidence,
                `protection leg ${index} trigger`,
            );
        }
    } else {
        resolvedDefinition.parameters.positionCost = basisPriceDecimal;
        assertCanonicalContractPrice(
            resolvedDefinition.parameters.activationPrice,
            contractEvidence,
            'trailing activation price',
        );
        if (resolvedDefinition.parameters.fixedStopPrice !== null) {
            assertCanonicalContractPrice(
                resolvedDefinition.parameters.fixedStopPrice,
                contractEvidence,
                'trailing fixed stop price',
            );
        }
    }
    if (resolvedDefinition.parameters.order.limitPrice !== null) {
        assertCanonicalContractPrice(
            resolvedDefinition.parameters.order.limitPrice,
            contractEvidence,
            'broker limit price',
        );
    }
    assertCanonicalSmartOrderDraft(resolvedDefinition, {
        expectedKind: strategy.strategy_kind,
    });
    const resolvedDefinitionJson = canonicalJson(
        resolvedDefinition,
        'canonical confirmation resolved definition',
    );
    const resolvedDefinitionHash = `sha256:${createHash('sha256')
        .update(resolvedDefinitionJson)
        .digest('hex')}`;
    const content = Object.freeze({
        schemaVersion: STRATEGY_CONFIRMATION_SCHEMA_VERSION,
        strategyId,
        strategyKind: strategy.strategy_kind,
        strategyRevision: strategy.revision,
        sourceDefinitionHash: strategy.definition_hash,
        resolvedDefinitionHash,
        resolvedDefinition,
        fixedAccount: Object.freeze({
            accountBrokerRef,
            accountIdRef,
            accountScopeSha256: contractEvidence.accountScopeSha256,
        }),
        tradeDate: position.trade_date,
        position: Object.freeze({
            accountHeadRevision: position.account_head_revision,
            positionLineageId: position.position_lineage_id,
            positionEvidenceHash: position.evidence_hash,
            quantityShares: position.quantity_shares,
            availableShares: position.available_shares,
            asOfEpochMs: position.as_of_epoch_ms,
            averageCostState: position.average_cost_state,
            basisSource: basisSelection.source,
            basisPriceMinorUnits,
        }),
        contract: contractEvidence.contract,
        contractEvidenceHash: contractEvidence.evidenceSha256,
        contractRevision: contractEvidence.contractRevision,
        corporateActionRevision: contractEvidence.corporateActionRevision,
        fixedAtrSnapshot,
        gate: Object.freeze({
            manifestRevision: gate.manifestRevision,
            manifestHash: gate.manifestSha256,
            mappingRevision: gate.mappingRevision,
        }),
        risk: Object.freeze({
            revision: risk.revision,
            policyRevision: risk.policy.policyRevision,
            policyHash: risk.policyHash,
        }),
        runtime: Object.freeze({
            runtimeEpochId,
            senderFence,
            apiGeneration,
            revision: runtime.revision,
        }),
        disclosureVersion:
            'smart-order-local-runtime-disclosure/2026-08-20.1',
        warnings: Object.freeze([
            'local_runtime_not_broker_cloud',
            'restart_requires_reconciliation_and_user_rearm',
            'broker_write_not_authorized',
        ]),
        createdAtEpochMs,
        validUntilEpochMs: Math.min(
            position.valid_until_epoch_ms,
            contractEvidence.validUntilEpochMs,
            gate.validUntilEpochMs,
        ),
    });
    if (content.validUntilEpochMs <= now) {
        throw new Error('canonical confirmation expired during construction');
    }
    return Object.freeze({
        content,
        snapshotHash: sha256Canonical(content, 'canonical confirmation snapshot'),
        resolvedDefinitionJson,
        identityGroupId: authenticatedIdentityGroupForAccount(
            database,
            accountBrokerRef,
            accountIdRef,
        ),
        storagePosition: Object.freeze({
            accountHeadRevision: content.position.accountHeadRevision,
            positionLineageId: content.position.positionLineageId,
            positionEvidenceHash: content.position.positionEvidenceHash,
        }),
    });
}

function publicStrategyConfirmationView(snapshot, state) {
    const publicContract = (contract, contractRevision, corporateActionRevision) =>
        Object.freeze({
            contractKey: contract.draftContractKey,
            category: contract.categoryCode === '00' ? 'ETF' : '股票',
            contractUnit: contract.contractUnit,
            referenceMinorUnits: contract.referenceMinorUnits,
            limitUpMinorUnits: contract.limitUpMinorUnits,
            limitDownMinorUnits: contract.limitDownMinorUnits,
            updateDate: contract.updateDate,
            contractRevision,
            corporateActionRevision,
        });
    return Object.freeze({
        schemaVersion: STRATEGY_CONFIRMATION_SCHEMA_VERSION,
        state,
        snapshotHash: snapshot.snapshotHash,
        strategyId: snapshot.content.strategyId,
        strategyKind: snapshot.content.strategyKind,
        strategyRevision: snapshot.content.strategyRevision,
        resolvedDefinitionHash: snapshot.content.resolvedDefinitionHash,
        fixedAccountLabel: '固定股票帳號（Runtime 已驗證）',
        contract: publicContract(
            snapshot.content.contract,
            snapshot.content.contractRevision,
            snapshot.content.corporateActionRevision,
        ),
        ...(snapshot.content.strategyKind === 'parent_child'
            ? {
                  childContract: publicContract(
                      snapshot.content.childContract,
                      snapshot.content.childContractRevision,
                      snapshot.content.childCorporateActionRevision,
                  ),
              }
            : {}),
        position:
            snapshot.content.position === null
                ? null
                : snapshot.content.strategyKind === 'parent_child'
                  ? Object.freeze({
                        quantityShares:
                            snapshot.content.position.quantityShares,
                        availableShares:
                            snapshot.content.position.availableShares,
                        asOfEpochMs: snapshot.content.position.asOfEpochMs,
                    })
                  : Object.freeze({
                        quantityShares:
                            snapshot.content.position.quantityShares,
                        availableShares:
                            snapshot.content.position.availableShares,
                        averageCostState:
                            snapshot.content.position.averageCostState,
                        basisSource: snapshot.content.position.basisSource,
                        basisPriceMinorUnits:
                            snapshot.content.position.basisPriceMinorUnits,
                        asOfEpochMs: snapshot.content.position.asOfEpochMs,
                    }),
        fixedAtrSnapshot:
            snapshot.content.fixedAtrSnapshot == null
                ? null
                : Object.freeze({
                      timeframe:
                          snapshot.content.fixedAtrSnapshot.timeframe,
                      period: snapshot.content.fixedAtrSnapshot.period,
                      algorithmVersion:
                          snapshot.content.fixedAtrSnapshot.algorithmVersion,
                      value: snapshot.content.fixedAtrSnapshot.value,
                      asOfTradingDate:
                          snapshot.content.fixedAtrSnapshot.asOfTradingDate,
                      snapshotSha256:
                          snapshot.content.fixedAtrSnapshot.snapshotSha256,
                  }),
        riskRevision: snapshot.content.risk.revision,
        modeGeneration: snapshot.content.runtime.apiGeneration,
        runtimeRevision: snapshot.content.runtime.revision,
        validUntilEpochMs: snapshot.content.validUntilEpochMs,
        warnings: snapshot.content.warnings,
        brokerWriteAttempted: false,
        brokerWriteAuthority: false,
        accountIdentifiersExposed: false,
    });
}

function previewStrategyConfirmation(database, input) {
    if (
        !exactKeys(input, [
            'accountBrokerRef',
            'accountIdRef',
            'apiGeneration',
            'basisSelection',
            'confirmationId',
            'contractEvidence',
            'expectedRevision',
            'kind',
            'monitorContractEvidence',
            'nowEpochMs',
            'runtimeEpochId',
            'senderFence',
            'strategyId',
        ])
    ) {
        throw new TypeError('canonical confirmation preview input is invalid');
    }
    const built = buildStrategyConfirmationSnapshot(database, input);
    const confirmationId = boundedToken(
        input.confirmationId,
        'confirmation.confirmationId',
    );
    const now = safeInteger(input.nowEpochMs, 'confirmation.nowEpochMs');
    const prior = database
        .prepare('SELECT * FROM canonical_confirmation_snapshots WHERE confirmation_id=?')
        .get(confirmationId);
    if (prior) {
        if (
            prior.snapshot_hash !== built.snapshotHash ||
            prior.state !== 'previewed'
        ) {
            throw new Error('canonical confirmation preview replay conflicted');
        }
        return publicStrategyConfirmationView(built, 'previewed');
    }
    database.prepare(`
        UPDATE canonical_confirmation_snapshots
           SET state='superseded', updated_at_epoch_ms=?, revision=revision+1
         WHERE strategy_id=? AND state='previewed'
    `).run(now, built.content.strategyId);
    database.prepare(`
        INSERT INTO canonical_confirmation_snapshots(
            confirmation_id, strategy_id, state, snapshot_hash, snapshot_json,
            strategy_revision, definition_hash, account_broker_ref,
            account_id_ref, trade_date, contract_key,
            account_head_revision, position_lineage_id, position_evidence_hash,
            contract_evidence_hash, contract_revision,
            corporate_action_revision, gate_manifest_revision,
            gate_manifest_hash, risk_revision, risk_hash,
            runtime_epoch_id, sender_fence, api_generation, runtime_revision,
            created_at_epoch_ms, valid_until_epoch_ms, accepted_at_epoch_ms,
            updated_at_epoch_ms, revision
        ) VALUES (?, ?, 'previewed', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, 0)
    `).run(
        confirmationId,
        built.content.strategyId,
        built.snapshotHash,
        canonicalJson(built.content, 'canonical confirmation snapshot'),
        built.content.strategyRevision,
        built.content.sourceDefinitionHash,
        built.content.fixedAccount.accountBrokerRef,
        built.content.fixedAccount.accountIdRef,
        built.content.tradeDate,
        built.content.contract.runtimeContractKey,
        built.storagePosition.accountHeadRevision,
        built.storagePosition.positionLineageId,
        built.storagePosition.positionEvidenceHash,
        built.content.contractEvidenceHash,
        built.content.contractRevision,
        built.content.corporateActionRevision,
        built.content.gate.manifestRevision,
        built.content.gate.manifestHash,
        String(built.content.risk.revision),
        built.content.risk.policyHash,
        built.content.runtime.runtimeEpochId,
        built.content.runtime.senderFence,
        built.content.runtime.apiGeneration,
        built.content.runtime.revision,
        now,
        built.content.validUntilEpochMs,
        now,
    );
    insertTransitionJournalEvent(database, {
        entityKind: 'canonical_confirmation',
        entityId: confirmationId,
        revision: 0,
        reasonCode: 'CANONICAL_CONFIRMATION_PREVIEWED',
        summaryCode: 'canonical_confirmation_previewed',
        nowEpochMs: now,
        payloadHash: built.snapshotHash,
        eventSuffix: 'previewed',
    });
    return publicStrategyConfirmationView(built, 'previewed');
}

function positiveDecimalDifference(upper, lower, label) {
    const parse = (value) => {
        if (
            typeof value !== 'string' ||
            !/^(?:0|[1-9]\d*)(?:\.\d+)?$/.test(value) ||
            value === '0'
        ) {
            throw new TypeError(`${label} requires canonical positive decimals`);
        }
        const [whole, fraction = ''] = value.split('.');
        return { whole, fraction };
    };
    const left = parse(upper);
    const right = parse(lower);
    const scale = Math.max(left.fraction.length, right.fraction.length);
    const scaled = ({ whole, fraction }) =>
        BigInt(`${whole}${fraction.padEnd(scale, '0')}`);
    const difference = scaled(left) - scaled(right);
    if (difference <= 0n) {
        throw new Error(`${label} must be greater than zero`);
    }
    const digits = difference.toString().padStart(scale + 1, '0');
    if (scale === 0) return digits;
    const whole = digits.slice(0, -scale);
    const fraction = digits.slice(-scale).replace(/0+$/, '');
    return fraction.length === 0 ? whole : `${whole}.${fraction}`;
}

function materializeExistingPositionProtection(database, built, now) {
    const definition = built.content.resolvedDefinition;
    if (!['stop_take', 'trailing_exit'].includes(definition.kind)) {
        throw new Error('existing-position materialization requires a protection strategy');
    }
    const parameters = definition.parameters;
    const quantityShares = safeInteger(
        Number(parameters.order.baseShares),
        'existing-position protection quantityShares',
        { minimum: 1 },
    );
    if (
        built.content.position === null ||
        quantityShares > built.content.position.availableShares
    ) {
        throw new Error(
            'existing-position protection exceeds the confirmed available position',
        );
    }
    const execution = {
        limitPrice: parameters.order.limitPrice,
        priceType: parameters.order.priceType,
        timeInForce: parameters.order.timeInForce,
    };
    const protection = definition.kind === 'stop_take'
        ? {
              family: 'fixed',
              legs: parameters.legs.map((leg) => ({
                  comparator: leg.type === 'stop' ? 'lte' : 'gte',
                  distance: leg.distance,
                  execution,
                  legId: leg.legId,
                  type: leg.type,
              })),
          }
        : {
              family: 'trailing',
              legs: [
                  {
                      comparator: 'gte',
                      distance: {
                          kind: 'absolute',
                          value: positiveDecimalDifference(
                              parameters.activationPrice,
                              parameters.positionCost,
                              'trailing activation distance',
                          ),
                      },
                      execution,
                      legId: 'trailing-activation',
                      type: 'trailing_activation',
                  },
                  {
                      comparator: 'lte',
                      distance: parameters.retracement,
                      execution,
                      legId: 'trailing-retracement',
                      type: 'trailing_retracement',
                  },
                  ...(parameters.fixedStopPrice === null
                      ? []
                      : [{
                            comparator: 'lte',
                            distance: {
                                kind: 'absolute',
                                value: positiveDecimalDifference(
                                    parameters.positionCost,
                                    parameters.fixedStopPrice,
                                    'trailing fixed stop distance',
                                ),
                            },
                            execution,
                            legId: 'trailing-fixed-stop',
                            type: 'fixed_stop',
                        }]),
              ],
          };
    const plan = canonicalExistingPositionProtectionPlan({
        schemaVersion:
            SMART_ORDER_EXISTING_POSITION_PROTECTION_PLAN_SCHEMA_VERSION,
        accountBrokerRef: built.content.fixedAccount.accountBrokerRef,
        accountIdRef: built.content.fixedAccount.accountIdRef,
        basis: {
            source: built.content.position.basisSource,
            priceDecimal:
                definition.kind === 'stop_take'
                    ? parameters.basisPrice
                    : parameters.positionCost,
        },
        confirmationSnapshotHash: built.snapshotHash,
        contractKey: built.content.contract.runtimeContractKey,
        contractPricePolicy: {
            categoryCode: built.content.contract.categoryCode,
            limitDownMinorUnits: built.content.contract.limitDownMinorUnits,
            limitUpMinorUnits: built.content.contract.limitUpMinorUnits,
        },
        contractUnit: safeInteger(
            built.content.contract.contractUnit,
            'existing-position protection contractUnit',
            { minimum: 1 },
        ),
        position: {
            accountHeadRevision: built.content.position.accountHeadRevision,
            availableShares: built.content.position.availableShares,
            evidenceHash: built.content.position.positionEvidenceHash,
            lineageId: built.content.position.positionLineageId,
            quantityShares: built.content.position.quantityShares,
        },
        protection,
        riskRevision: built.content.risk.policyRevision,
        tradeDate: built.content.tradeDate,
    });
    const formal = deriveExistingPositionFormalProtection(
        plan.plan,
        quantityShares,
    );
    const formalJson = stableCanonicalJson(formal);
    const formalHash = sha256Canonical(
        formal,
        'existing-position formal protection',
    );
    const lineage = sha256Canonical(
        {
            confirmationSnapshotHash: built.snapshotHash,
            planSha256: plan.planSha256,
            positionEvidenceHash:
                built.content.position.positionEvidenceHash,
            positionLineageId: built.content.position.positionLineageId,
            strategyId: built.content.strategyId,
        },
        'existing-position protection lineage',
    ).slice(7);
    const obligationId = `obligation:existing-position:${lineage}`;
    const exitClaimId = `claim:existing-position:${lineage}`;
    const protectionGroupId = `protection-group:existing-position:${lineage}`;
    const allocation = allocateProtectedEntryExitClaim(database, {
        accountBrokerRef: built.content.fixedAccount.accountBrokerRef,
        accountIdRef: built.content.fixedAccount.accountIdRef,
        contractKey: built.content.contract.runtimeContractKey,
        exitClaimId,
        positionLineageId: built.content.position.positionLineageId,
        positionQuantityShares: Math.min(
            built.content.position.quantityShares,
            built.content.position.availableShares,
        ),
        quantityShares,
    });
    if (!allocation || allocation.existingClaim) {
        throw new Error(
            'existing-position protection quantity is already reserved or unavailable',
        );
    }
    const evidenceHash = sha256Canonical(
        {
            activeClaimSetHash: allocation.activeClaimSetHash,
            confirmationSnapshotHash: built.snapshotHash,
            formalProtectionHash: formalHash,
            planSha256: plan.planSha256,
            quantityShares,
        },
        'existing-position protection claim evidence',
    );
    database.prepare(`
        INSERT INTO protection_obligations(
            obligation_id, strategy_id, commitment_id, state,
            position_lineage_id, filled_shares, confirmed_exited_shares,
            created_at_epoch_ms, updated_at_epoch_ms, terminal_at_epoch_ms,
            revision
        ) VALUES (?, ?, NULL, 'monitoring', ?, ?, 0, ?, ?, NULL, 0)
    `).run(
        obligationId,
        built.content.strategyId,
        built.content.position.positionLineageId,
        quantityShares,
        now,
        now,
    );
    database.prepare(`
        INSERT INTO exit_claims(
            exit_claim_id, obligation_id, intent_id, external_lineage,
            account_broker_ref, account_id_ref, contract_key,
            position_lineage_id, remainder_generation,
            allocation_start_share, quantity_shares, state, evidence_hash,
            created_at_epoch_ms, updated_at_epoch_ms, terminal_at_epoch_ms,
            revision
        ) VALUES (?, ?, NULL, 0, ?, ?, ?, ?, 0, ?, ?,
                  'monitoring_reserved', ?, ?, ?, NULL, 0)
    `).run(
        exitClaimId,
        obligationId,
        built.content.fixedAccount.accountBrokerRef,
        built.content.fixedAccount.accountIdRef,
        built.content.contract.runtimeContractKey,
        built.content.position.positionLineageId,
        allocation.allocationStartShare,
        quantityShares,
        evidenceHash,
        now,
        now,
    );
    database.prepare(`
        INSERT INTO protection_groups(
            protection_group_id, obligation_id, exit_claim_id, state,
            current_generation, plan_hash, created_at_epoch_ms,
            updated_at_epoch_ms, terminal_at_epoch_ms, revision
        ) VALUES (?, ?, ?, 'monitoring', 0, ?, ?, ?, NULL, 0)
    `).run(
        protectionGroupId,
        obligationId,
        exitClaimId,
        plan.planSha256,
        now,
        now,
    );
    database.prepare(`
        INSERT INTO protection_remainder_generations(
            protection_group_id, remainder_generation, exit_claim_id,
            state, quantity_shares, winner_leg_id, winner_activation_id,
            winner_intent_id, evidence_hash, created_at_epoch_ms,
            updated_at_epoch_ms, terminal_at_epoch_ms, revision
        ) VALUES (?, 0, ?, 'monitoring', ?, NULL, NULL, NULL, ?, ?, ?, NULL, 0)
    `).run(
        protectionGroupId,
        exitClaimId,
        quantityShares,
        evidenceHash,
        now,
        now,
    );
    database.prepare(`
        INSERT INTO existing_position_protection_heads(
            strategy_id, obligation_id, exit_claim_id, trade_date,
            protection_plan_json, protection_plan_hash,
            formal_protection_json, formal_protection_hash,
            reconciliation_evidence_hash, reconciliation_as_of_epoch_ms,
            created_at_epoch_ms, updated_at_epoch_ms, revision
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
    `).run(
        built.content.strategyId,
        obligationId,
        exitClaimId,
        built.content.tradeDate,
        plan.planJson,
        plan.planSha256,
        formalJson,
        formalHash,
        built.content.position.positionEvidenceHash,
        built.content.position.asOfEpochMs,
        now,
        now,
    );
    for (const [entityKind, entityId, reasonCode, summaryCode] of [
        [
            'protection_obligation',
            obligationId,
            'EXISTING_POSITION_PROTECTION_OBLIGATION_CREATED',
            'existing_position_protection_obligation_created',
        ],
        [
            'exit_claim',
            exitClaimId,
            'EXIT_CLAIM_MONITORING_RESERVED',
            'existing_position_exit_claim_reserved',
        ],
        [
            'protection_group',
            protectionGroupId,
            'PROTECTION_GROUP_MONITORING',
            'existing_position_protection_group_monitoring',
        ],
    ]) {
        insertTransitionJournalEvent(database, {
            entityKind,
            entityId,
            revision: 0,
            reasonCode,
            summaryCode,
            nowEpochMs: now,
            payloadHash: evidenceHash,
            eventSuffix: 'created',
        });
    }
    return Object.freeze({
        exitClaimId,
        obligationId,
        protectionGroupId,
        planHash: plan.planSha256,
    });
}

function acceptStrategyConfirmation(database, input) {
    if (
        !exactKeys(input, [
            'accountBrokerRef',
            'accountIdRef',
            'apiGeneration',
            'basisSelection',
            'confirmationId',
            'contractEvidence',
            'expectedRevision',
            'kind',
            'monitorContractEvidence',
            'nowEpochMs',
            'runtimeEpochId',
            'senderFence',
            'snapshotHash',
            'strategyId',
            'userAcknowledged',
        ])
    ) {
        throw new TypeError('canonical confirmation accept input is invalid');
    }
    const now = safeInteger(input.nowEpochMs, 'confirmation.nowEpochMs');
    const confirmationId = boundedToken(
        input.confirmationId,
        'confirmation.confirmationId',
    );
    const expectedSnapshotHash = sha256Digest(
        input.snapshotHash,
        'confirmation.snapshotHash',
    );
    if (input.userAcknowledged !== true) {
        throw new TypeError('canonical confirmation requires explicit acknowledgement');
    }
    const preview = database
        .prepare('SELECT * FROM canonical_confirmation_snapshots WHERE confirmation_id=?')
        .get(confirmationId);
    if (
        !preview ||
        preview.state !== 'previewed' ||
        preview.snapshot_hash !== expectedSnapshotHash ||
        preview.valid_until_epoch_ms <= now
    ) {
        throw new Error('canonical confirmation preview is missing, changed, or expired');
    }
    const built = buildStrategyConfirmationSnapshot(database, input, {
        snapshotCreatedAtEpochMs: preview.created_at_epoch_ms,
    });
    if (built.snapshotHash !== expectedSnapshotHash) {
        throw new Error('canonical confirmation inputs changed after preview');
    }
    const acceptedStrategyState =
        ['quick', 'good_till', 'multi_condition', 'parent_child'].includes(built.content.strategyKind) ||
        ['stop_take', 'trailing_exit'].includes(built.content.strategyKind)
            ? 'paused'
            : 'draft';
    const strategyUpdate = database.prepare(`
        UPDATE strategies
           SET definition_hash=?, definition_json=?, state=?,
               account_broker_ref=?, account_id_ref=?, identity_group_id=?,
               confirmation_snapshot_hash=?, updated_at_epoch_ms=?,
               revision=revision+1
         WHERE strategy_id=? AND state='draft' AND revision=?
           AND definition_hash=?
    `).run(
        built.content.resolvedDefinitionHash,
        built.resolvedDefinitionJson,
        acceptedStrategyState,
        built.content.fixedAccount.accountBrokerRef,
        built.content.fixedAccount.accountIdRef,
        built.identityGroupId,
        built.snapshotHash,
        now,
        built.content.strategyId,
        built.content.strategyRevision,
        built.content.sourceDefinitionHash,
    );
    if (Number(strategyUpdate.changes) !== 1) {
        throw new Error('canonical confirmation strategy CAS failed');
    }
    const existingPositionProtection =
        ['stop_take', 'trailing_exit'].includes(built.content.strategyKind)
            ? materializeExistingPositionProtection(database, built, now)
            : null;
    if (built.content.strategyKind === 'good_till') {
        const targetShares = safeInteger(
            Number(built.content.resolvedDefinition.parameters.targetBaseShares),
            'goodTill.targetShares',
            { minimum: 1 },
        );
        database.prepare(`
            INSERT INTO good_till_progress_heads(
                strategy_id, target_shares, confirmed_filled_shares,
                remaining_target_shares, daily_state, active_trade_date,
                active_activation_id, active_intent_id,
                active_accounted_filled_shares, last_reconciliation_hash,
                created_at_epoch_ms, updated_at_epoch_ms, revision
            ) VALUES (?, ?, 0, ?, 'waiting', NULL, NULL, NULL, 0, NULL, ?, ?, 0)
        `).run(
            built.content.strategyId,
            targetShares,
            targetShares,
            now,
            now,
        );
    }
    if (built.content.strategyKind === 'parent_child') {
        database.prepare(`
            INSERT INTO parent_child_progress_heads(
                strategy_id, state, parent_activation_trade_date,
                parent_activation_id, parent_intent_id,
                parent_settlement_hash, child_activation_trade_date,
                child_quantity_shares, child_position_lineage_id,
                child_obligation_id, child_exit_claim_id,
                child_protection_group_id, child_activation_id,
                child_intent_id, child_settlement_hash,
                created_at_epoch_ms, updated_at_epoch_ms, revision
            ) VALUES (?, 'waiting_parent', NULL, NULL, NULL, NULL,
                      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                      ?, ?, 0)
        `).run(built.content.strategyId, now, now);
    }
    database.prepare(`
        UPDATE canonical_confirmation_snapshots
           SET state='superseded', updated_at_epoch_ms=?, revision=revision+1
         WHERE strategy_id=? AND state='accepted'
    `).run(now, built.content.strategyId);
    const accepted = database.prepare(`
        UPDATE canonical_confirmation_snapshots
           SET state='accepted', accepted_at_epoch_ms=?,
               updated_at_epoch_ms=?, revision=revision+1
         WHERE confirmation_id=? AND state='previewed' AND snapshot_hash=?
           AND revision=0
    `).run(now, now, confirmationId, expectedSnapshotHash);
    if (Number(accepted.changes) !== 1) {
        throw new Error('canonical confirmation accept CAS failed');
    }
    insertTransitionJournalEvent(database, {
        entityKind: 'canonical_confirmation',
        entityId: confirmationId,
        revision: 1,
        reasonCode: 'CANONICAL_CONFIRMATION_ACCEPTED',
        summaryCode: 'canonical_confirmation_accepted',
        nowEpochMs: now,
        payloadHash: built.snapshotHash,
        eventSuffix: 'accepted',
    });
    return Object.freeze({
        ...publicStrategyConfirmationView(built, 'accepted'),
        existingPositionProtection,
        strategy: parseStrategyRow(
            database
                .prepare('SELECT * FROM strategies WHERE strategy_id=?')
                .get(built.content.strategyId),
            { includeDefinition: true, database },
        ),
    });
}

const PROTECTED_ENTRY_CONFIRMATION_REQUEST_SCHEMA_VERSION =
    'smart-order-protected-entry-confirmation-request/2026-08-20.1';
const PROTECTED_ENTRY_CONFIRMATION_SCHEMA_VERSION =
    'smart-order-protected-entry-confirmation/2026-08-20.1';
const PROTECTED_ENTRY_STRATEGY_SCHEMA_VERSION =
    'smart-order-protected-entry-strategy/2026-08-20.1';

function canonicalProtectedEntryConfirmationDecimal(value, label) {
    const fractionalDigits =
        typeof value === 'string' ? (value.split('.')[1] ?? '') : '';
    if (
        typeof value !== 'string' ||
        value.length > 80 ||
        !/^(?:0|[1-9]\d*)(?:\.\d+)?$/.test(value) ||
        value === '0' ||
        (fractionalDigits.length > 0 && fractionalDigits.endsWith('0')) ||
        value.split('.')[0].length > 18 ||
        fractionalDigits.length > 18
    ) {
        throw new TypeError(`${label} must be a positive canonical decimal`);
    }
    return value;
}

function canonicalProtectedEntryConfirmationDistance(value, label) {
    if (exactKeys(value, ['kind', 'value']) && value.kind === 'absolute') {
        return Object.freeze({
            kind: 'absolute',
            value: canonicalProtectedEntryConfirmationDecimal(
                value.value,
                `${label}.value`,
            ),
        });
    }
    if (exactKeys(value, ['kind', 'pctBps']) && value.kind === 'pct_bps') {
        const pctBps = safeInteger(value.pctBps, `${label}.pctBps`, {
            minimum: 1,
        });
        if (pctBps > 9_999) {
            throw new TypeError(`${label}.pctBps must be 1-9999`);
        }
        return Object.freeze({ kind: 'pct_bps', pctBps });
    }
    if (
        exactKeys(value, ['kind', 'multiplier']) &&
        value.kind === 'fixed_atr'
    ) {
        canonicalProtectedEntryConfirmationDecimal(
            value.multiplier,
            `${label}.multiplier`,
        );
        throw new Error(
            'protected entry ATR confirmation requires a trusted Runtime fixed-ATR snapshot',
        );
    }
    throw new TypeError(`${label} is outside the protected-entry schema`);
}

function canonicalProtectedEntryConfirmationExecution(value, evidence, label) {
    if (!exactKeys(value, ['limitPrice', 'priceType', 'timeInForce'])) {
        throw new TypeError(`${label} execution schema is invalid`);
    }
    if (
        !(
            (value.priceType === 'LMT' &&
                ['ROD', 'IOC'].includes(value.timeInForce)) ||
            (value.priceType === 'MKT' && value.timeInForce === 'IOC')
        )
    ) {
        throw new TypeError(`${label} execution policy is unsupported`);
    }
    if (value.priceType === 'LMT') {
        assertCanonicalContractPrice(value.limitPrice, evidence, `${label}.limitPrice`);
    } else if (value.limitPrice !== null) {
        throw new TypeError(`${label}.limitPrice must be null for MKT`);
    }
    return Object.freeze({
        limitPrice: value.limitPrice,
        priceType: value.priceType,
        timeInForce: value.timeInForce,
    });
}

function canonicalProtectedEntryConfirmationRequest(value, evidence) {
    if (
        !exactKeys(value, [
            'accountBrokerRef',
            'accountIdRef',
            'commonLots',
            'contractKey',
            'entryOrder',
            'protection',
            'schemaVersion',
        ]) ||
        value.schemaVersion !==
            PROTECTED_ENTRY_CONFIRMATION_REQUEST_SCHEMA_VERSION ||
        !exactKeys(value.entryOrder, [
            'limitPrice',
            'priceType',
            'timeInForce',
        ]) ||
        !exactKeys(value.protection, ['family', 'legs']) ||
        !['fixed', 'trailing'].includes(value.protection.family) ||
        !Array.isArray(value.protection.legs) ||
        value.protection.legs.length < 1 ||
        value.protection.legs.length > 3
    ) {
        throw new TypeError('protected entry confirmation request is invalid');
    }
    const accountBrokerRef = boundedToken(
        value.accountBrokerRef,
        'protectedEntryConfirmation.accountBrokerRef',
    );
    const accountIdRef = boundedToken(
        value.accountIdRef,
        'protectedEntryConfirmation.accountIdRef',
    );
    const contractKey = boundedToken(
        value.contractKey,
        'protectedEntryConfirmation.contractKey',
    );
    if (
        contractKey !== evidence.contract.draftContractKey ||
        evidence.accountScopeSha256 !==
            confirmationAccountScopeSha256(accountBrokerRef, accountIdRef)
    ) {
        throw new Error('protected entry confirmation scope is inconsistent');
    }
    const commonLots = safeInteger(
        value.commonLots,
        'protectedEntryConfirmation.commonLots',
        { minimum: 1 },
    );
    const baseSharesBigInt =
        BigInt(commonLots) * BigInt(evidence.contract.contractUnit);
    if (baseSharesBigInt > BigInt(Number.MAX_SAFE_INTEGER)) {
        throw new TypeError('protected entry quantity exceeds safe bounds');
    }
    const entryOrder = canonicalProtectedEntryConfirmationExecution(
        value.entryOrder,
        evidence,
        'protectedEntryConfirmation.entryOrder',
    );
    if (entryOrder.priceType !== 'LMT') {
        throw new Error(
            'protected entry MKT confirmation requires a trusted worst-price authority',
        );
    }
    const legs = value.protection.legs.map((candidate, index) => {
        const label = `protectedEntryConfirmation.protection.legs[${index}]`;
        if (
            !exactKeys(candidate, [
                'comparator',
                'distance',
                'execution',
                'legId',
                'type',
            ])
        ) {
            throw new TypeError(`${label} schema is invalid`);
        }
        return Object.freeze({
            comparator: boundedToken(candidate.comparator, `${label}.comparator`),
            distance: canonicalProtectedEntryConfirmationDistance(
                candidate.distance,
                `${label}.distance`,
            ),
            execution: canonicalProtectedEntryConfirmationExecution(
                candidate.execution,
                evidence,
                `${label}.execution`,
            ),
            legId: boundedToken(candidate.legId, `${label}.legId`),
            type: boundedToken(candidate.type, `${label}.type`),
        });
    });
    return Object.freeze({
        schemaVersion: PROTECTED_ENTRY_CONFIRMATION_REQUEST_SCHEMA_VERSION,
        accountBrokerRef,
        accountIdRef,
        commonLots,
        baseShares: Number(baseSharesBigInt),
        contractKey,
        entryOrder,
        protection: Object.freeze({
            family: value.protection.family,
            legs: Object.freeze(legs),
        }),
    });
}

function protectedEntryConfirmationEntityId(kind, confirmationId) {
    return `${kind}:${createHash('sha256')
        .update(`smart-order-protected-entry-confirmation\u001f${confirmationId}\u001f${kind}`)
        .digest('hex')}`;
}

function buildProtectedEntryConfirmationSnapshot(database, input) {
    const now = safeInteger(
        input.nowEpochMs,
        'protectedEntryConfirmation.nowEpochMs',
    );
    const snapshotCreatedAtEpochMs =
        input.snapshotCreatedAtEpochMs === undefined
            ? now
            : safeInteger(
                  input.snapshotCreatedAtEpochMs,
                  'protectedEntryConfirmation.snapshotCreatedAtEpochMs',
              );
    if (snapshotCreatedAtEpochMs > now) {
        throw new Error('protected entry confirmation snapshot is future-dated');
    }
    const confirmationId = boundedToken(
        input.confirmationId,
        'protectedEntryConfirmation.confirmationId',
    );
    const runtimeEpochId = boundedToken(
        input.runtimeEpochId,
        'protectedEntryConfirmation.runtimeEpochId',
    );
    const senderFence = boundedToken(
        input.senderFence,
        'protectedEntryConfirmation.senderFence',
    );
    const apiGeneration = boundedToken(
        input.apiGeneration,
        'protectedEntryConfirmation.apiGeneration',
    );
    const runtimeSender = database.prepare(`
        SELECT state, revision
          FROM runtime_epochs
         WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
    `).get(runtimeEpochId, senderFence, apiGeneration);
    if (
        !runtimeSender ||
        runtimeSender.state !== 'ready' ||
        !currentReadySenderMatches(database, {
            runtimeEpochId,
            senderFence,
            apiGeneration,
        })
    ) {
        throw new Error(
            'protected entry confirmation requires the current ready Runtime sender',
        );
    }
    const contractEvidence = canonicalConfirmationContractEvidence(
        input.contractEvidence,
    );
    const request = canonicalProtectedEntryConfirmationRequest(
        input.confirmationRequest,
        contractEvidence,
    );
    if (
        contractEvidence.runtimeEpochId !== runtimeEpochId ||
        contractEvidence.apiGeneration !== apiGeneration ||
        contractEvidence.observedAtEpochMs > now ||
        contractEvidence.validUntilEpochMs <= now
    ) {
        throw new Error('protected entry contract evidence is not current');
    }
    const strategyKind =
        request.protection.family === 'fixed' ? 'stop_take' : 'trailing_exit';
    const gate = gateManifestStatus(database, {
        provenance: 'automation',
        nowEpochMs: now,
    });
    if (
        gate.state !== 'eligible' ||
        gate.featureGates[strategyKind] !== true ||
        gate.manifestRevision !== contractEvidence.gateManifestRevision ||
        gate.manifestSha256 !== contractEvidence.gateManifestHash ||
        gate.mappingRevision !== contractEvidence.mappingRevision
    ) {
        throw new Error('protected entry confirmation Gate evidence is not current');
    }
    observeCanonicalContractHead(database, {
        accountBrokerRef: request.accountBrokerRef,
        accountIdRef: request.accountIdRef,
        contractEvidence,
        nowEpochMs: now,
    });
    const risk = runtimeRiskPolicyView(database);
    if (
        risk.state !== 'current' ||
        risk.policy === null ||
        risk.policyHash === null ||
        risk.revision === null
    ) {
        throw new Error('protected entry confirmation requires current risk evidence');
    }
    const accountHead = database.prepare(`
        SELECT * FROM account_reconciliation_heads
         WHERE account_broker_ref=? AND account_id_ref=?
         ORDER BY as_of_epoch_ms DESC, trade_date DESC
         LIMIT 1
    `).get(request.accountBrokerRef, request.accountIdRef);
    if (!accountHead || accountHead.as_of_epoch_ms > now) {
        throw new Error(
            'protected entry confirmation requires current account reconciliation',
        );
    }
    const identityGroupId = authenticatedIdentityGroupForAccount(
        database,
        request.accountBrokerRef,
        request.accountIdRef,
    );
    const strategyId = protectedEntryConfirmationEntityId(
        'strategy',
        confirmationId,
    );
    const core = Object.freeze({
        schemaVersion: PROTECTED_ENTRY_CONFIRMATION_SCHEMA_VERSION,
        confirmationKind: 'protected_entry',
        confirmationId,
        strategyId,
        strategyKind,
        request,
        fixedAccount: Object.freeze({
            accountBrokerRef: request.accountBrokerRef,
            accountIdRef: request.accountIdRef,
            accountScopeSha256: contractEvidence.accountScopeSha256,
            identityGroupId,
        }),
        tradeDate: accountHead.trade_date,
        accountReconciliation: Object.freeze({
            revision: accountHead.revision,
            sourceRevision: accountHead.source_revision,
            sourceSnapshotHash: accountHead.source_snapshot_hash,
            evidenceHash: accountHead.evidence_hash,
            asOfEpochMs: accountHead.as_of_epoch_ms,
        }),
        contract: contractEvidence.contract,
        contractEvidenceHash: contractEvidence.evidenceSha256,
        contractRevision: contractEvidence.contractRevision,
        corporateActionRevision: contractEvidence.corporateActionRevision,
        gate: Object.freeze({
            manifestRevision: gate.manifestRevision,
            manifestHash: gate.manifestSha256,
            mappingRevision: gate.mappingRevision,
        }),
        risk: Object.freeze({
            revision: risk.revision,
            policyRevision: risk.policy.policyRevision,
            policyHash: risk.policyHash,
            executionPolicy: risk.policy.executionPolicy,
        }),
        runtime: Object.freeze({
            runtimeEpochId,
            senderFence,
            apiGeneration,
            revision: runtimeSender.revision,
        }),
        disclosureVersion: 'smart-order-local-runtime-disclosure/2026-08-20.1',
        warnings: Object.freeze([
            'local_runtime_not_broker_cloud',
            'entry_not_sent_until_durable_dispatch_gates',
            'restart_requires_reconciliation_and_user_rearm',
            'broker_write_not_authorized',
        ]),
        createdAtEpochMs: snapshotCreatedAtEpochMs,
        validUntilEpochMs: Math.min(
            contractEvidence.validUntilEpochMs,
            gate.validUntilEpochMs,
            snapshotCreatedAtEpochMs + 5_000,
        ),
    });
    if (core.validUntilEpochMs <= now) {
        throw new Error('protected entry confirmation expired during construction');
    }
    const snapshotHash = sha256Canonical(
        core,
        'protected entry confirmation core',
    );
    const protectionPlan = Object.freeze({
        schemaVersion: SMART_ORDER_PROTECTED_ENTRY_PLAN_SCHEMA_VERSION,
        accountBrokerRef: request.accountBrokerRef,
        accountIdRef: request.accountIdRef,
        basis: Object.freeze({
            source: 'entry_weighted_average_fill',
            previewPrice: request.entryOrder.limitPrice,
        }),
        confirmationSnapshotHash: snapshotHash,
        contractKey: contractEvidence.contract.runtimeContractKey,
        contractPricePolicy: Object.freeze({
            categoryCode: contractEvidence.contract.categoryCode,
            limitDownMinorUnits:
                contractEvidence.contract.limitDownMinorUnits,
            limitUpMinorUnits:
                contractEvidence.contract.limitUpMinorUnits,
        }),
        entryOrder: Object.freeze({
            baseShares: request.baseShares,
            commonLots: request.commonLots,
            contractUnit: contractEvidence.contract.contractUnit,
            limitPrice: request.entryOrder.limitPrice,
            orderCond: 'Cash',
            orderLot: 'Common',
            priceType: request.entryOrder.priceType,
            side: 'Buy',
            timeInForce: request.entryOrder.timeInForce,
        }),
        fixedAtrSnapshot: null,
        modeRevision: apiGeneration,
        protection: request.protection,
        riskPolicy: Object.freeze({
            schemaVersion:
                SMART_ORDER_PROTECTED_ENTRY_RISK_POLICY_SCHEMA_VERSION,
            ...risk.policy.executionPolicy,
        }),
        riskRevision: risk.policy.policyRevision,
    });
    const canonicalPlan = canonicalProtectedEntryPlan(protectionPlan);
    const definition = Object.freeze({
        schemaVersion: PROTECTED_ENTRY_STRATEGY_SCHEMA_VERSION,
        confirmationSnapshotHash: snapshotHash,
        protectionPlan: canonicalPlan.plan,
        protectionPlanSha256: canonicalPlan.planSha256,
    });
    const definitionJson = canonicalJson(
        definition,
        'protected entry strategy definition',
    );
    const definitionHash = `sha256:${createHash('sha256')
        .update(definitionJson)
        .digest('hex')}`;
    return Object.freeze({
        content: Object.freeze({
            ...core,
            confirmationSnapshotHash: snapshotHash,
            protectionPlan: canonicalPlan.plan,
            protectionPlanSha256: canonicalPlan.planSha256,
            definitionHash,
        }),
        snapshotHash,
        canonicalPlan,
        definition,
        definitionJson,
        definitionHash,
    });
}

function publicProtectedEntryConfirmationView(built, state, preparationState) {
    const content = built.content;
    return Object.freeze({
        schemaVersion: PROTECTED_ENTRY_CONFIRMATION_SCHEMA_VERSION,
        state,
        snapshotHash: built.snapshotHash,
        confirmationId: content.confirmationId,
        strategyKind: content.strategyKind,
        fixedAccountLabel: '固定股票帳號（Runtime 已驗證）',
        simulation: true,
        contract: Object.freeze({
            contractKey: content.contract.draftContractKey,
            category: content.contract.categoryCode === '00' ? 'ETF' : '股票',
            contractUnit: content.contract.contractUnit,
            updateDate: content.contract.updateDate,
            contractRevision: content.contractRevision,
            corporateActionRevision: content.corporateActionRevision,
        }),
        entryOrder: Object.freeze({
            side: 'Buy',
            orderCond: 'Cash',
            orderLot: 'Common',
            baseShares: content.request.baseShares,
            commonLots: content.request.commonLots,
            priceType: content.request.entryOrder.priceType,
            limitPrice: content.request.entryOrder.limitPrice,
            timeInForce: content.request.entryOrder.timeInForce,
        }),
        protection: content.request.protection,
        fixedAtrSnapshot: null,
        previewBasis: Object.freeze({
            source: 'entry_limit_estimate',
            priceDecimal: content.request.entryOrder.limitPrice,
            formalSource: 'entry_weighted_average_fill',
        }),
        riskRevision: content.risk.revision,
        riskPolicyRevision: content.risk.policyRevision,
        modeGeneration: content.runtime.apiGeneration,
        runtimeRevision: content.runtime.revision,
        accountReconciliationAsOfEpochMs:
            content.accountReconciliation.asOfEpochMs,
        validUntilEpochMs: content.validUntilEpochMs,
        warnings: content.warnings,
        durablePreparationState: preparationState,
        brokerWriteAttempted: false,
        brokerWriteAuthority: false,
        accountIdentifiersExposed: false,
        entityIdentifiersExposed: false,
    });
}

function insertProtectedEntryConfirmation(database, built, now) {
    const content = built.content;
    database.prepare(`
        INSERT INTO strategies(
            strategy_id, strategy_kind, state, definition_hash,
            definition_json, account_broker_ref, account_id_ref,
            identity_group_id, confirmation_snapshot_hash,
            created_at_epoch_ms, updated_at_epoch_ms, revision
        ) VALUES (?, ?, 'draft', ?, ?, 'draft-unbound', 'draft-unbound',
                  'draft-unbound', ?, ?, ?, 0)
    `).run(
        content.strategyId,
        content.strategyKind,
        built.definitionHash,
        built.definitionJson,
        built.snapshotHash,
        now,
        now,
    );
    database.prepare(`
        INSERT INTO canonical_confirmation_snapshots(
            confirmation_id, strategy_id, state, snapshot_hash, snapshot_json,
            strategy_revision, definition_hash, account_broker_ref,
            account_id_ref, trade_date, contract_key,
            account_head_revision, position_lineage_id, position_evidence_hash,
            contract_evidence_hash, contract_revision,
            corporate_action_revision, gate_manifest_revision,
            gate_manifest_hash, risk_revision, risk_hash,
            runtime_epoch_id, sender_fence, api_generation, runtime_revision,
            created_at_epoch_ms, valid_until_epoch_ms, accepted_at_epoch_ms,
            updated_at_epoch_ms, revision
        ) VALUES (?, ?, 'previewed', ?, ?, 0, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, 0)
    `).run(
        content.confirmationId,
        content.strategyId,
        built.snapshotHash,
        canonicalJson(content, 'protected entry confirmation snapshot'),
        built.definitionHash,
        content.fixedAccount.accountBrokerRef,
        content.fixedAccount.accountIdRef,
        content.tradeDate,
        content.contract.runtimeContractKey,
        content.accountReconciliation.revision,
        protectedEntryConfirmationEntityId(
            'pending-position-lineage',
            content.confirmationId,
        ),
        content.accountReconciliation.evidenceHash,
        content.contractEvidenceHash,
        content.contractRevision,
        content.corporateActionRevision,
        content.gate.manifestRevision,
        content.gate.manifestHash,
        content.risk.policyRevision,
        content.risk.policyHash,
        content.runtime.runtimeEpochId,
        content.runtime.senderFence,
        content.runtime.apiGeneration,
        content.runtime.revision,
        content.createdAtEpochMs,
        content.validUntilEpochMs,
        now,
    );
    insertTransitionJournalEvent(database, {
        entityKind: 'strategy',
        entityId: content.strategyId,
        revision: 0,
        reasonCode: 'STRATEGY_DRAFT_CREATED',
        summaryCode: 'protected_entry_confirmation_draft_created',
        nowEpochMs: now,
        payloadHash: built.definitionHash,
        eventSuffix: 'protected-entry-confirmation-draft',
    });
    insertTransitionJournalEvent(database, {
        entityKind: 'canonical_confirmation',
        entityId: content.confirmationId,
        revision: 0,
        reasonCode: 'CANONICAL_CONFIRMATION_PREVIEWED',
        summaryCode: 'protected_entry_confirmation_previewed',
        nowEpochMs: now,
        payloadHash: built.snapshotHash,
        eventSuffix: 'protected-entry-previewed',
    });
}

function previewProtectedEntryConfirmation(database, input) {
    if (
        !exactKeys(input, [
            'apiGeneration',
            'confirmationId',
            'confirmationRequest',
            'contractEvidence',
            'kind',
            'nowEpochMs',
            'runtimeEpochId',
            'senderFence',
        ])
    ) {
        throw new TypeError('protected entry confirmation preview input is invalid');
    }
    const built = buildProtectedEntryConfirmationSnapshot(database, input);
    const prior = database.prepare(`
        SELECT confirmation_id, strategy_id, state, snapshot_hash
          FROM canonical_confirmation_snapshots WHERE confirmation_id=?
    `).get(built.content.confirmationId);
    if (prior) {
        if (
            prior.strategy_id !== built.content.strategyId ||
            prior.state !== 'previewed' ||
            prior.snapshot_hash !== built.snapshotHash
        ) {
            throw new Error('protected entry confirmation preview replay conflicted');
        }
        return publicProtectedEntryConfirmationView(built, 'previewed', 'none');
    }
    assertStrategyCapacity(database, { draft: true });
    insertProtectedEntryConfirmation(database, built, input.nowEpochMs);
    return publicProtectedEntryConfirmationView(built, 'previewed', 'none');
}

function acceptProtectedEntryConfirmation(database, input) {
    if (
        !exactKeys(input, [
            'apiGeneration',
            'confirmationId',
            'confirmationRequest',
            'contractEvidence',
            'identityAdmission',
            'kind',
            'nowEpochMs',
            'runtimeEpochId',
            'senderFence',
            'snapshotHash',
            'userAcknowledged',
        ]) ||
        input.userAcknowledged !== true
    ) {
        throw new TypeError('protected entry confirmation accept input is invalid');
    }
    const now = safeInteger(
        input.nowEpochMs,
        'protectedEntryConfirmation.nowEpochMs',
    );
    const expectedSnapshotHash = sha256Digest(
        input.snapshotHash,
        'protectedEntryConfirmation.snapshotHash',
    );
    const preview = database.prepare(`
        SELECT * FROM canonical_confirmation_snapshots WHERE confirmation_id=?
    `).get(input.confirmationId);
    if (
        !preview ||
        preview.state !== 'previewed' ||
        preview.snapshot_hash !== expectedSnapshotHash ||
        preview.valid_until_epoch_ms <= now
    ) {
        throw new Error('protected entry confirmation preview is missing or stale');
    }
    const built = buildProtectedEntryConfirmationSnapshot(database, {
        ...input,
        snapshotCreatedAtEpochMs: preview.created_at_epoch_ms,
    });
    if (
        built.snapshotHash !== expectedSnapshotHash ||
        preview.strategy_id !== built.content.strategyId ||
        preview.snapshot_json !==
            canonicalJson(built.content, 'protected entry confirmation snapshot')
    ) {
        throw new Error('protected entry confirmation inputs changed after preview');
    }
    authenticatedIdentityAdmission(database, input.identityAdmission, {
        accountBrokerRef: built.content.fixedAccount.accountBrokerRef,
        accountIdRef: built.content.fixedAccount.accountIdRef,
        identityGroupId: built.content.fixedAccount.identityGroupId,
    });
    assertAuthenticatedIdentityStrategyCapacity(
        database,
        built.content.fixedAccount.identityGroupId,
        { prospectiveStrategyId: built.content.strategyId },
    );
    const strategyUpdate = database.prepare(`
        UPDATE strategies
           SET state='observing', account_broker_ref=?, account_id_ref=?,
               identity_group_id=?, confirmation_snapshot_hash=?,
               updated_at_epoch_ms=?, revision=revision+1
         WHERE strategy_id=? AND state='draft' AND revision=0
           AND definition_hash=? AND definition_json=?
    `).run(
        built.content.fixedAccount.accountBrokerRef,
        built.content.fixedAccount.accountIdRef,
        built.content.fixedAccount.identityGroupId,
        built.snapshotHash,
        now,
        built.content.strategyId,
        built.definitionHash,
        built.definitionJson,
    );
    if (Number(strategyUpdate.changes) !== 1) {
        throw new Error('protected entry strategy confirmation CAS failed');
    }
    const canonicalIntent = canonicalProtectedEntryIntentPayload({
        schemaVersion: SMART_ORDER_PROTECTED_ENTRY_INTENT_SCHEMA_VERSION,
        confirmationSnapshotHash: built.snapshotHash,
        entryOrder: built.canonicalPlan.plan.entryOrder,
        protectionPlan: built.canonicalPlan.plan,
        protectionPlanSha256: built.canonicalPlan.planSha256,
    });
    const confirmationId = built.content.confirmationId;
    const intentId = protectedEntryConfirmationEntityId('intent', confirmationId);
    const preparation = prepareIntent(
        database,
        {
            strategyId: built.content.strategyId,
            activation: {
                activationId: protectedEntryConfirmationEntityId(
                    'activation',
                    confirmationId,
                ),
                logicalKey: protectedEntryConfirmationEntityId(
                    'activation-logical-key',
                    confirmationId,
                ),
                generation: 0,
                evidenceHash: built.snapshotHash,
            },
            intent: {
                intentId,
                ownerKind: 'activation',
                clientRequestId: protectedEntryConfirmationEntityId(
                    'client-request',
                    confirmationId,
                ),
                accountBrokerRef: built.content.fixedAccount.accountBrokerRef,
                accountIdRef: built.content.fixedAccount.accountIdRef,
                tradeDate: built.content.tradeDate,
                contractKey: built.content.contract.runtimeContractKey,
                side: 'Buy',
                operationKind: 'place',
                payload: canonicalIntent.payload,
                payloadHash: canonicalIntent.payloadSha256,
            },
            reservation: {
                reservationId: protectedEntryConfirmationEntityId(
                    'reservation',
                    confirmationId,
                ),
                accountBrokerRef: built.content.fixedAccount.accountBrokerRef,
                accountIdRef: built.content.fixedAccount.accountIdRef,
                identityGroupId: built.content.fixedAccount.identityGroupId,
                policyRevision: built.content.risk.policyRevision,
                policyHash: built.canonicalPlan.riskPolicyHash,
                ...built.canonicalPlan.worstCaseExposure,
            },
            protectionCommitment: {
                commitmentId: protectedEntryConfirmationEntityId(
                    'commitment',
                    confirmationId,
                ),
                committedShares: built.canonicalPlan.baseShares,
            },
            protectionObligation: {
                obligationId: protectedEntryConfirmationEntityId(
                    'obligation',
                    confirmationId,
                ),
                positionLineageId: protectedEntryConfirmationEntityId(
                    'position-lineage',
                    confirmationId,
                ),
            },
            identityAdmission: input.identityAdmission,
            runtimeEpochId: built.content.runtime.runtimeEpochId,
            senderFence: built.content.runtime.senderFence,
            apiGeneration: built.content.runtime.apiGeneration,
            nowEpochMs: now,
        },
        true,
    );
    if (
        preparation.state !== 'prepared' ||
        preparation.adapterAuthorityGranted !== false
    ) {
        throw new Error('protected entry durable preparation did not fail closed');
    }
    const accepted = database.prepare(`
        UPDATE canonical_confirmation_snapshots
           SET state='accepted', accepted_at_epoch_ms=?,
               updated_at_epoch_ms=?, revision=revision+1
         WHERE confirmation_id=? AND state='previewed' AND snapshot_hash=?
           AND revision=0
    `).run(now, now, confirmationId, expectedSnapshotHash);
    if (Number(accepted.changes) !== 1) {
        throw new Error('protected entry confirmation accept CAS failed');
    }
    insertTransitionJournalEvent(database, {
        entityKind: 'canonical_confirmation',
        entityId: confirmationId,
        revision: 1,
        reasonCode: 'CANONICAL_CONFIRMATION_ACCEPTED',
        summaryCode: 'protected_entry_confirmation_accepted_and_prepared',
        nowEpochMs: now,
        payloadHash: built.snapshotHash,
        eventSuffix: 'protected-entry-accepted',
    });
    return publicProtectedEntryConfirmationView(
        built,
        'accepted',
        'prepared',
    );
}

function createDraftStrategy(database, input, withinExistingTransaction = false) {
    const now = safeInteger(input.nowEpochMs, 'draft.nowEpochMs');
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const strategyKind = boundedToken(input.strategyKind, 'strategyKind');
    if (!SMART_ORDER_STRATEGY_KINDS.has(strategyKind)) {
        throw new TypeError('draft strategy kind is unsupported');
    }
    const definition = createEditableCanonicalSmartOrderDraft({
        kind: strategyKind,
        workspaceContractKey: input.workspaceContractKey,
        nowEpochMs: now,
    });
    const definitionJson = canonicalJson(definition, 'draft.definition');
    const definitionHash = `sha256:${createHash('sha256')
        .update(definitionJson)
        .digest('hex')}`;
    const mutate = () => {
        assertStrategyCapacity(database, { draft: true });
        database
            .prepare(`
                INSERT INTO strategies(
                    strategy_id, strategy_kind, state, definition_hash,
                    definition_json, account_broker_ref, account_id_ref,
                    identity_group_id, confirmation_snapshot_hash,
                    created_at_epoch_ms, updated_at_epoch_ms, revision
                ) VALUES (?, ?, 'draft', ?, ?, 'draft-unbound',
                          'draft-unbound', 'draft-unbound', ?, ?, ?, 0)
            `)
            .run(
                strategyId,
                strategyKind,
                definitionHash,
                definitionJson,
                definitionHash,
                now,
                now,
            );
        insertJournalEvent(
            database,
            {
                eventId: `strategy:${strategyId}:created:0`,
                entityKind: 'strategy',
                entityId: strategyId,
                reasonCode: 'STRATEGY_DRAFT_CREATED',
                receiveEpochMs: now,
                payloadHash: definitionHash,
                summaryCode: 'strategy_draft_created',
                createdAtEpochMs: now,
            },
            0,
        );
        return parseStrategyRow(
            database
                .prepare('SELECT * FROM strategies WHERE strategy_id=?')
                .get(strategyId),
            { includeDefinition: true, database },
        );
    };
    return withinExistingTransaction ? mutate() : transaction(database, mutate);
}

function replaceDraftStrategy(database, input, withinExistingTransaction = false) {
    const now = safeInteger(input.nowEpochMs, 'draft.nowEpochMs');
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'expectedRevision',
    );
    const mutate = () => {
        const row = database
            .prepare('SELECT strategy_kind, state FROM strategies WHERE strategy_id=?')
            .get(strategyId);
        if (!row) throw new Error('strategy draft does not exist');
        if (row.state !== 'draft') throw new Error('only a draft may be edited');
        const draft = assertCanonicalSmartOrderDraft(input.draft, {
            expectedKind: row.strategy_kind,
        });
        const definitionJson = canonicalJson(draft, 'draft.definition');
        const definitionHash = `sha256:${createHash('sha256')
            .update(definitionJson)
            .digest('hex')}`;
        const result = database
            .prepare(`
                UPDATE strategies
                   SET definition_hash=?, definition_json=?,
                       confirmation_snapshot_hash=?, updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE strategy_id=? AND state='draft' AND revision=?
            `)
            .run(
                definitionHash,
                definitionJson,
                definitionHash,
                now,
                strategyId,
                expectedRevision,
            );
        if (Number(result.changes) !== 1) {
            throw new Error('draft update lost its optimistic revision');
        }
        insertJournalEvent(
            database,
            {
                eventId: `strategy:${strategyId}:draft-updated:${expectedRevision + 1}`,
                entityKind: 'strategy',
                entityId: strategyId,
                reasonCode: 'STRATEGY_DRAFT_UPDATED',
                receiveEpochMs: now,
                payloadHash: definitionHash,
                summaryCode: 'strategy_draft_updated',
                createdAtEpochMs: now,
            },
            expectedRevision + 1,
        );
        return parseStrategyRow(
            database
                .prepare('SELECT * FROM strategies WHERE strategy_id=?')
                .get(strategyId),
            { includeDefinition: true, database },
        );
    };
    return withinExistingTransaction ? mutate() : transaction(database, mutate);
}

function listStrategies(database, input) {
    const limit = safeInteger(input.limit ?? 100, 'strategyList.limit', {
        minimum: 1,
    });
    if (limit > 200) throw new TypeError('strategy list limit exceeds 200');
    const states = input.states;
    let rows;
    if (states === undefined) {
        rows = database
            .prepare(`
                SELECT * FROM strategies
                 ORDER BY updated_at_epoch_ms DESC, strategy_id
                 LIMIT ?
            `)
            .all(limit);
    } else {
        if (
            !Array.isArray(states) ||
            states.length === 0 ||
            states.length > 16
        ) {
            throw new TypeError('strategy states filter is invalid');
        }
        const canonicalStates = [...new Set(states.map((state) =>
            boundedToken(state, 'strategy.state'),
        ))];
        rows = database
            .prepare(`
                SELECT * FROM strategies
                 WHERE state IN (${canonicalStates.map(() => '?').join(',')})
                 ORDER BY updated_at_epoch_ms DESC, strategy_id
                 LIMIT ?
            `)
            .all(...canonicalStates, limit);
    }
    return Object.freeze(
        rows.map((row) => parseStrategyRow(row, { database })),
    );
}

function listProtectiveQuoteDemands(database, input) {
    if (
        !exactKeys(input, [
            'apiGeneration',
            'runtimeEpochId',
            'senderFence',
        ])
    ) {
        throw new TypeError('protective quote demand input schema is invalid');
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    if (
        !currentReadySenderMatches(database, {
            runtimeEpochId,
            senderFence,
            apiGeneration,
        })
    ) {
        return Object.freeze([]);
    }
    const rows = database.prepare(`
        SELECT groups.protection_group_id, claims.contract_key
          FROM protection_groups AS groups
          JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
          JOIN exit_claims AS claims
            ON claims.exit_claim_id=groups.exit_claim_id
          JOIN protection_obligations AS obligations
            ON obligations.obligation_id=groups.obligation_id
          JOIN strategies
            ON strategies.strategy_id=obligations.strategy_id
         WHERE strategies.state='monitoring'
           AND groups.state='monitoring'
           AND generations.state='monitoring'
           AND claims.state='monitoring_reserved'
           AND claims.intent_id IS NULL
           AND claims.external_lineage=0
         ORDER BY groups.protection_group_id
    `).all();
    return Object.freeze(
        rows.map((row) => {
            const match = /^(TSE|OTC):([A-Za-z0-9][A-Za-z0-9._-]{0,31}):STK:Common$/.exec(
                row.contract_key,
            );
            if (!match) {
                throw new Error('durable protection contract is not quote eligible');
            }
            return Object.freeze({
                consumerId: `protection:${sha256Canonical(
                    row.protection_group_id,
                    'protective quote demand consumer',
                ).slice(7)}`,
                contract: Object.freeze({
                    code: match[2],
                    exchange: match[1],
                    securityType: 'STK',
                }),
                quoteType: 'tick',
            });
        }),
    );
}

function listSmartOrderQuoteDemands(database, input) {
    if (
        !exactKeys(input, [
            'apiGeneration',
            'runtimeEpochId',
            'senderFence',
        ])
    ) {
        throw new TypeError('smart-order quote demand input schema is invalid');
    }
    const sender = {
        apiGeneration: boundedToken(input.apiGeneration, 'apiGeneration'),
        runtimeEpochId: boundedToken(input.runtimeEpochId, 'runtimeEpochId'),
        senderFence: boundedToken(input.senderFence, 'senderFence'),
    };
    if (!currentReadySenderMatches(database, sender)) {
        return Object.freeze([]);
    }
    const protection = listProtectiveQuoteDemands(database, sender);
    const quickRows = database.prepare(`
        SELECT strategy_id, strategy_kind, revision, definition_json,
               confirmation_snapshot_hash
          FROM strategies
         WHERE strategy_kind IN ('quick','good_till','multi_condition','parent_child') AND state='monitoring'
           AND confirmation_snapshot_hash IS NOT NULL
         ORDER BY strategy_id
    `).all();
    const quick = quickRows.flatMap((row) => {
        try {
            assertCanonicalConfirmationCurrent(database, {
                strategyId: row.strategy_id,
                snapshotHash: row.confirmation_snapshot_hash,
                ...sender,
                nowEpochMs: canonicalConfirmationClockNowEpochMs(),
            });
        } catch {
            return [];
        }
        const definition = parseStoredCanonicalObject(
            row.definition_json,
            'quick quote demand definition',
        );
        assertCanonicalSmartOrderDraft(definition, {
            expectedKind: row.strategy_kind,
        });
        let legs = row.strategy_kind === 'multi_condition'
            ? definition.parameters.conditions
            : [{
                  monitorContractKey: definition.parameters.monitorContractKey,
                  condition: definition.parameters.condition,
              }];
        if (row.strategy_kind === 'parent_child') {
            const progress = database.prepare(`
                SELECT state FROM parent_child_progress_heads WHERE strategy_id=?
            `).get(row.strategy_id);
            if (!progress) {
                throw new Error('parent-child quote demand progress is missing');
            }
            if (progress.state === 'waiting_parent') {
                legs = [definition.parameters.parent];
            } else if (progress.state === 'child_monitoring') {
                legs = [definition.parameters.child];
            } else {
                legs = [];
            }
        }
        return legs.map((leg, index) => {
            const condition = canonicalSmartOrderQuickCondition(leg.condition);
            const match = /^(TSE|OTC):STK:([A-Za-z0-9][A-Za-z0-9._-]{0,31})$/.exec(
                leg.monitorContractKey,
            );
            if (!match) {
                throw new Error('smart-order quote demand contract is unsupported');
            }
            return Object.freeze({
                consumerId: `${row.strategy_kind}:${sha256Canonical(
                    [
                        row.strategy_id,
                        row.revision,
                        row.confirmation_snapshot_hash,
                        index,
                        leg.monitorContractKey,
                        condition.field,
                    ],
                    `${row.strategy_kind} quote demand consumer`,
                ).slice(7)}`,
                contract: Object.freeze({
                    code: match[2],
                    exchange: match[1],
                    securityType: 'STK',
                }),
                quoteType: condition.sourceKind,
            });
        });
    });
    return Object.freeze([...protection, ...quick]);
}

function listGoodTillConfirmationRenewalContexts(database, input) {
    if (
        !exactKeys(input, ['apiGeneration', 'runtimeEpochId', 'senderFence'])
    ) {
        throw new TypeError('good-till renewal context input schema is invalid');
    }
    const sender = {
        apiGeneration: boundedToken(input.apiGeneration, 'apiGeneration'),
        runtimeEpochId: boundedToken(input.runtimeEpochId, 'runtimeEpochId'),
        senderFence: boundedToken(input.senderFence, 'senderFence'),
    };
    if (!currentReadySenderMatches(database, sender)) return Object.freeze([]);
    const rows = database.prepare(`
        SELECT strategies.strategy_id, strategies.revision AS strategy_revision,
               strategies.confirmation_snapshot_hash,
               strategies.account_broker_ref, strategies.account_id_ref,
               confirmations.snapshot_json
          FROM strategies
          JOIN canonical_confirmation_snapshots AS confirmations
            ON confirmations.strategy_id=strategies.strategy_id
           AND confirmations.snapshot_hash=strategies.confirmation_snapshot_hash
           AND confirmations.state='accepted'
         WHERE strategies.strategy_kind='good_till'
           AND strategies.state='monitoring'
         ORDER BY strategies.strategy_id
         LIMIT 129
    `).all();
    if (rows.length > 128) {
        throw new Error('good-till renewal context set exceeds its bound');
    }
    return Object.freeze(
        rows.map((row) => {
            const content = parseStoredCanonicalObject(
                row.snapshot_json,
                'good-till renewal confirmation snapshot',
            );
            if (
                content.schemaVersion !== STRATEGY_CONFIRMATION_SCHEMA_VERSION ||
                content.strategyKind !== 'good_till' ||
                sha256Canonical(content, 'canonical confirmation snapshot') !==
                    row.confirmation_snapshot_hash
            ) {
                throw new Error('good-till renewal confirmation is not canonical');
            }
            return Object.freeze({
                accountBrokerRef: row.account_broker_ref,
                accountIdRef: row.account_id_ref,
                monitorContractKey: content.monitorContract.draftContractKey,
                orderContractKey: content.contract.draftContractKey,
                snapshotHash: row.confirmation_snapshot_hash,
                strategyId: row.strategy_id,
                strategyRevision: row.strategy_revision,
            });
        }),
    );
}

function refreshGoodTillConfirmationEvidence(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'apiGeneration',
            'monitorContractEvidence',
            'nowEpochMs',
            'orderContractEvidence',
            'runtimeEpochId',
            'senderFence',
            'snapshotHash',
            'strategyId',
        ])
    ) {
        throw new TypeError('good-till confirmation renewal input schema is invalid');
    }
    const sender = {
        apiGeneration: boundedToken(input.apiGeneration, 'apiGeneration'),
        runtimeEpochId: boundedToken(input.runtimeEpochId, 'runtimeEpochId'),
        senderFence: boundedToken(input.senderFence, 'senderFence'),
    };
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const snapshotHash = sha256Digest(input.snapshotHash, 'snapshotHash');
    const now = safeInteger(input.nowEpochMs, 'goodTillRenewal.nowEpochMs');
    const orderEvidence = canonicalConfirmationContractEvidence(
        input.orderContractEvidence,
    );
    const monitorEvidence = canonicalConfirmationContractEvidence(
        input.monitorContractEvidence,
    );
    return transaction(database, () => {
        if (!currentReadySenderMatches(database, sender)) {
            throw new Error('good-till confirmation renewal requires current ready Runtime');
        }
        const row = database.prepare(`
            SELECT strategies.account_broker_ref, strategies.account_id_ref,
                   strategies.state AS strategy_state,
                   confirmations.snapshot_json
              FROM strategies
              JOIN canonical_confirmation_snapshots AS confirmations
                ON confirmations.strategy_id=strategies.strategy_id
               AND confirmations.snapshot_hash=strategies.confirmation_snapshot_hash
               AND confirmations.state='accepted'
             WHERE strategies.strategy_id=?
               AND strategies.strategy_kind='good_till'
               AND strategies.confirmation_snapshot_hash=?
        `).get(strategyId, snapshotHash);
        if (!row || row.strategy_state !== 'monitoring') {
            throw new Error('good-till confirmation renewal scope is stale');
        }
        const content = parseStoredCanonicalObject(
            row.snapshot_json,
            'good-till renewal confirmation snapshot',
        );
        const gate = gateManifestStatus(database, {
            provenance: 'automation',
            nowEpochMs: now,
        });
        if (
            content.schemaVersion !== STRATEGY_CONFIRMATION_SCHEMA_VERSION ||
            content.strategyKind !== 'good_till' ||
            sha256Canonical(content, 'canonical confirmation snapshot') !==
                snapshotHash ||
            [orderEvidence, monitorEvidence].some(
                (evidence) =>
                    evidence.runtimeEpochId !== sender.runtimeEpochId ||
                    evidence.apiGeneration !== sender.apiGeneration ||
                    evidence.observedAtEpochMs > now ||
                    evidence.validUntilEpochMs <= now ||
                    evidence.accountScopeSha256 !==
                        content.fixedAccount.accountScopeSha256 ||
                    evidence.gateManifestRevision !==
                        content.gate.manifestRevision ||
                    evidence.gateManifestHash !== content.gate.manifestHash ||
                    evidence.mappingRevision !== content.gate.mappingRevision,
            ) ||
            orderEvidence.contract.runtimeContractKey !==
                content.contract.runtimeContractKey ||
            orderEvidence.contractRevision !== content.contractRevision ||
            orderEvidence.corporateActionRevision !==
                content.corporateActionRevision ||
            monitorEvidence.contract.runtimeContractKey !==
                content.monitorContract.runtimeContractKey ||
            monitorEvidence.contractRevision !==
                content.monitorContractRevision ||
            monitorEvidence.corporateActionRevision !==
                content.monitorCorporateActionRevision ||
            gate.state !== 'eligible' ||
            gate.featureGates.good_till !== true ||
            gate.manifestRevision !== content.gate.manifestRevision ||
            gate.manifestSha256 !== content.gate.manifestHash
        ) {
            throw new Error('good-till confirmation renewal head changed');
        }
        observeCanonicalContractHead(database, {
            accountBrokerRef: row.account_broker_ref,
            accountIdRef: row.account_id_ref,
            contractEvidence: orderEvidence,
            nowEpochMs: now,
        });
        observeCanonicalContractHead(database, {
            accountBrokerRef: row.account_broker_ref,
            accountIdRef: row.account_id_ref,
            contractEvidence: monitorEvidence,
            nowEpochMs: now,
        });
        return Object.freeze({
            state: 'refreshed',
            strategyId,
            validUntilEpochMs: Math.min(
                orderEvidence.validUntilEpochMs,
                monitorEvidence.validUntilEpochMs,
                gate.validUntilEpochMs,
            ),
            brokerWriteAuthority: false,
            automaticDispatchAllowed: false,
        });
    });
}

function listMultiConditionConfirmationRenewalContexts(database, input) {
    if (!exactKeys(input, ['apiGeneration', 'runtimeEpochId', 'senderFence'])) {
        throw new TypeError('multi-condition renewal context input schema is invalid');
    }
    const sender = {
        apiGeneration: boundedToken(input.apiGeneration, 'apiGeneration'),
        runtimeEpochId: boundedToken(input.runtimeEpochId, 'runtimeEpochId'),
        senderFence: boundedToken(input.senderFence, 'senderFence'),
    };
    if (!currentReadySenderMatches(database, sender)) return Object.freeze([]);
    const rows = database.prepare(`
        SELECT strategies.strategy_id, strategies.revision AS strategy_revision,
               strategies.confirmation_snapshot_hash,
               strategies.account_broker_ref, strategies.account_id_ref,
               confirmations.snapshot_json
          FROM strategies
          JOIN canonical_confirmation_snapshots AS confirmations
            ON confirmations.strategy_id=strategies.strategy_id
           AND confirmations.snapshot_hash=strategies.confirmation_snapshot_hash
           AND confirmations.state='accepted'
         WHERE strategies.strategy_kind IN ('multi_condition','parent_child')
           AND strategies.state='monitoring'
         ORDER BY strategies.strategy_id
         LIMIT 129
    `).all();
    if (rows.length > 128) {
        throw new Error('multi-condition renewal context set exceeds its bound');
    }
    return Object.freeze(
        rows.map((row) => {
            const content = parseStoredCanonicalObject(
                row.snapshot_json,
                'multi-condition renewal confirmation snapshot',
            );
            if (
                content.schemaVersion !== STRATEGY_CONFIRMATION_SCHEMA_VERSION ||
                !['multi_condition', 'parent_child'].includes(
                    content.strategyKind,
                ) ||
                (content.strategyKind === 'multi_condition' &&
                    (!Array.isArray(content.monitorConditions) ||
                        content.monitorConditions.length < 1 ||
                        content.monitorConditions.length > 7)) ||
                sha256Canonical(content, 'canonical confirmation snapshot') !==
                    row.confirmation_snapshot_hash
            ) {
                throw new Error('multi-condition renewal confirmation is not canonical');
            }
            return Object.freeze({
                accountBrokerRef: row.account_broker_ref,
                accountIdRef: row.account_id_ref,
                monitorContractKeys: Object.freeze(
                    content.strategyKind === 'parent_child'
                        ? [content.childContract.draftContractKey]
                        : content.monitorConditions.map(
                              (entry) =>
                                  entry.monitorContract.draftContractKey,
                          ),
                ),
                orderContractKey: content.contract.draftContractKey,
                snapshotHash: row.confirmation_snapshot_hash,
                strategyId: row.strategy_id,
                strategyRevision: row.strategy_revision,
            });
        }),
    );
}

function refreshMultiConditionConfirmationEvidence(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'apiGeneration',
            'monitorContractEvidence',
            'nowEpochMs',
            'orderContractEvidence',
            'runtimeEpochId',
            'senderFence',
            'snapshotHash',
            'strategyId',
        ]) ||
        !Array.isArray(input.monitorContractEvidence) ||
        input.monitorContractEvidence.length < 1 ||
        input.monitorContractEvidence.length > 7
    ) {
        throw new TypeError('multi-condition confirmation renewal input is invalid');
    }
    const sender = {
        apiGeneration: boundedToken(input.apiGeneration, 'apiGeneration'),
        runtimeEpochId: boundedToken(input.runtimeEpochId, 'runtimeEpochId'),
        senderFence: boundedToken(input.senderFence, 'senderFence'),
    };
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const snapshotHash = sha256Digest(input.snapshotHash, 'snapshotHash');
    const now = safeInteger(input.nowEpochMs, 'multiConditionRenewal.nowEpochMs');
    const orderEvidence = canonicalConfirmationContractEvidence(
        input.orderContractEvidence,
    );
    const monitorEvidence = input.monitorContractEvidence.map((candidate) =>
        canonicalConfirmationContractEvidence(candidate),
    );
    return transaction(database, () => {
        if (!currentReadySenderMatches(database, sender)) {
            throw new Error('multi-condition renewal requires current ready Runtime');
        }
        const row = database.prepare(`
            SELECT strategies.account_broker_ref, strategies.account_id_ref,
                   strategies.state AS strategy_state,
                   confirmations.snapshot_json
              FROM strategies
              JOIN canonical_confirmation_snapshots AS confirmations
                ON confirmations.strategy_id=strategies.strategy_id
               AND confirmations.snapshot_hash=strategies.confirmation_snapshot_hash
               AND confirmations.state='accepted'
             WHERE strategies.strategy_id=?
               AND strategies.strategy_kind IN ('multi_condition','parent_child')
               AND strategies.confirmation_snapshot_hash=?
        `).get(strategyId, snapshotHash);
        if (!row || row.strategy_state !== 'monitoring') {
            throw new Error('multi-condition renewal scope is stale');
        }
        const content = parseStoredCanonicalObject(
            row.snapshot_json,
            'multi-condition renewal confirmation snapshot',
        );
        const gate = gateManifestStatus(database, {
            provenance: 'automation',
            nowEpochMs: now,
        });
        const allEvidence = [orderEvidence, ...monitorEvidence];
        if (
            content.schemaVersion !== STRATEGY_CONFIRMATION_SCHEMA_VERSION ||
            !['multi_condition', 'parent_child'].includes(
                content.strategyKind,
            ) ||
            (content.strategyKind === 'multi_condition' &&
                (!Array.isArray(content.monitorConditions) ||
                    content.monitorConditions.length !==
                        monitorEvidence.length)) ||
            (content.strategyKind === 'parent_child' &&
                monitorEvidence.length !== 1) ||
            sha256Canonical(content, 'canonical confirmation snapshot') !==
                snapshotHash ||
            allEvidence.some(
                (evidence) =>
                    evidence.runtimeEpochId !== sender.runtimeEpochId ||
                    evidence.apiGeneration !== sender.apiGeneration ||
                    evidence.observedAtEpochMs > now ||
                    evidence.validUntilEpochMs <= now ||
                    evidence.accountScopeSha256 !==
                        content.fixedAccount.accountScopeSha256 ||
                    evidence.gateManifestRevision !==
                        content.gate.manifestRevision ||
                    evidence.gateManifestHash !== content.gate.manifestHash ||
                    evidence.mappingRevision !== content.gate.mappingRevision,
            ) ||
            orderEvidence.contract.runtimeContractKey !==
                content.contract.runtimeContractKey ||
            orderEvidence.contractRevision !== content.contractRevision ||
            orderEvidence.corporateActionRevision !==
                content.corporateActionRevision ||
            monitorEvidence.some((evidence, index) => {
                const expected =
                    content.strategyKind === 'parent_child'
                        ? {
                              monitorContract: content.childContract,
                              monitorContractRevision:
                                  content.childContractRevision,
                              monitorCorporateActionRevision:
                                  content.childCorporateActionRevision,
                          }
                        : content.monitorConditions[index];
                return (
                    evidence.contract.runtimeContractKey !==
                        expected.monitorContract.runtimeContractKey ||
                    evidence.contractRevision !==
                        expected.monitorContractRevision ||
                    evidence.corporateActionRevision !==
                        expected.monitorCorporateActionRevision
                );
            }) ||
            gate.state !== 'eligible' ||
            gate.featureGates[content.strategyKind] !== true ||
            gate.manifestRevision !== content.gate.manifestRevision ||
            gate.manifestSha256 !== content.gate.manifestHash
        ) {
            throw new Error('multi-condition renewal head changed');
        }
        for (const evidence of allEvidence) {
            observeCanonicalContractHead(database, {
                accountBrokerRef: row.account_broker_ref,
                accountIdRef: row.account_id_ref,
                contractEvidence: evidence,
                nowEpochMs: now,
            });
        }
        return Object.freeze({
            state: 'refreshed',
            strategyId,
            validUntilEpochMs: Math.min(
                gate.validUntilEpochMs,
                ...allEvidence.map((evidence) => evidence.validUntilEpochMs),
            ),
            brokerWriteAuthority: false,
            automaticDispatchAllowed: false,
        });
    });
}

const MANUAL_RESOLUTION_TERMINAL_BROKER_STATES = new Map([
    ['filled', 'Filled'],
    ['cancelled', 'Cancelled'],
    ['failed', 'Failed'],
    ['inactive', 'Inactive'],
]);

const MANUAL_RESOLUTION_RECONCILIATION_TTL_MS = 5_000;

function manualResolutionKey(resolutionCase) {
    return sha256Canonical(
        {
            resolutionCaseId: resolutionCase.resolution_case_id,
            reasonCode: resolutionCase.reason_code,
            scopeHash: resolutionCase.scope_hash,
            evidenceSnapshotHash: resolutionCase.evidence_snapshot_hash,
            revision: resolutionCase.revision,
        },
        'manual resolution public key',
    );
}

function manualResolutionBrokerQuantityShares(database, intent, order, head) {
    if (head.quantity_unit === 'Share') {
        return Object.freeze({
            orderShares: safeInteger(
                head.order_quantity,
                'manualResolution.brokerOrderQuantityShares',
            ),
            filledShares: safeInteger(
                head.cumulative_deal_quantity,
                'manualResolution.brokerFilledQuantityShares',
            ),
            cancelledShares: safeInteger(
                head.cumulative_cancel_quantity,
                'manualResolution.brokerCancelledQuantityShares',
            ),
            remainingShares: safeInteger(
                head.remaining_quantity,
                'manualResolution.brokerRemainingQuantityShares',
            ),
        });
    }
    if (head.quantity_unit !== 'CommonLot') {
        throw new Error(
            'manual resolution broker quantity unit is unsupported',
        );
    }
    const originatingIntent = database
        .prepare('SELECT payload_json FROM order_intents WHERE intent_id=?')
        .get(order.intent_id);
    if (!originatingIntent) {
        throw new Error(
            'manual resolution broker quantity lacks its originating intent',
        );
    }
    let plan;
    try {
        const protectedIntent = canonicalProtectedEntryIntentPayload(
            parseStoredCanonicalObject(
                originatingIntent.payload_json,
                'manual resolution originating protected entry intent',
            ),
        );
        plan = canonicalProtectedEntryPlan(
            protectedIntent.payload.protectionPlan,
        );
    } catch {
        throw new Error(
            'manual resolution CommonLot quantity lacks a canonical contract unit',
        );
    }
    if (plan.baseShares !== order.quantity_shares) {
        throw new Error(
            'manual resolution protected entry quantity does not match its broker order',
        );
    }
    const contractUnit = plan.plan.entryOrder.contractUnit;
    return Object.freeze({
        orderShares: brokerEventQuantityShares(
            head.order_quantity,
            head.quantity_unit,
            contractUnit,
            'manual resolution broker order quantity',
        ),
        filledShares: brokerEventQuantityShares(
            head.cumulative_deal_quantity,
            head.quantity_unit,
            contractUnit,
            'manual resolution broker filled quantity',
        ),
        cancelledShares: brokerEventQuantityShares(
            head.cumulative_cancel_quantity,
            head.quantity_unit,
            contractUnit,
            'manual resolution broker cancelled quantity',
        ),
        remainingShares: brokerEventQuantityShares(
            head.remaining_quantity,
            head.quantity_unit,
            contractUnit,
            'manual resolution broker remaining quantity',
        ),
    });
}

function proveManualResolutionUniqueFinal(
    database,
    { strategy, resolutionCase, nowEpochMs },
) {
    const policy = smartOrderManualResolutionPolicyRow(
        resolutionCase.reason_code,
    );
    if (!policy?.allowedOperations.includes('apply_unique_final_evidence')) {
        throw new Error(
            'manual resolution reason does not allow unique final evidence',
        );
    }
    const runtimeEpochId = repositoryMetaValue(
        database,
        'current_runtime_epoch_id',
    );
    const runtime = runtimeEpochId
        ? database
              .prepare(`
                  SELECT state, reconciliation_evidence_hash, api_generation,
                         sender_fence, revision
                    FROM runtime_epochs WHERE runtime_epoch_id=?
              `)
              .get(runtimeEpochId)
        : undefined;
    if (
        !runtime ||
        !['ready', 'reconciling'].includes(runtime.state) ||
        runtime.reconciliation_evidence_hash === null
    ) {
        throw new Error(
            'manual resolution requires current full account reconciliation',
        );
    }
    sha256Digest(
        runtime.reconciliation_evidence_hash,
        'manualResolution.runtimeReconciliationEvidenceHash',
    );
    const unresolvedIntents = database
        .prepare(`
            SELECT * FROM order_intents
             WHERE strategy_id=? AND operation_kind IN ('place','update','cancel')
               AND state IN ('reconciling','unknown')
             ORDER BY intent_id
        `)
        .all(strategy.strategy_id);
    if (unresolvedIntents.length !== 1) {
        throw new Error(
            'manual resolution requires exactly one unresolved broker intent',
        );
    }
    const [intent] = unresolvedIntents;
    if (
        intent.adapter_authority_granted !== 1 ||
        intent.runtime_epoch_id !== runtimeEpochId ||
        intent.api_generation !== runtime.api_generation ||
        intent.sender_fence !== runtime.sender_fence
    ) {
        throw new Error(
            'manual resolution intent lost its current Runtime sender lineage',
        );
    }
    const sibling = database
        .prepare(`
            SELECT COUNT(*) AS count FROM order_intents
             WHERE strategy_id=? AND operation_kind IN ('place','update','cancel')
               AND intent_id<>?
               AND state NOT IN ('terminal','cancelled_proven_unsent')
        `)
        .get(strategy.strategy_id, intent.intent_id);
    if (Number(sibling?.count) !== 0) {
        throw new Error(
            'manual resolution found another nonterminal broker intent',
        );
    }
    const orders = intent.target_broker_order_id
        ? database
              .prepare(
                  'SELECT * FROM broker_orders WHERE broker_order_id=? ORDER BY broker_order_id',
              )
              .all(intent.target_broker_order_id)
        : database
              .prepare(
                  'SELECT * FROM broker_orders WHERE intent_id=? ORDER BY broker_order_id',
              )
              .all(intent.intent_id);
    if (orders.length !== 1) {
        throw new Error(
            'manual resolution requires one durable broker order outcome',
        );
    }
    const [order] = orders;
    const expectedBrokerStatus =
        MANUAL_RESOLUTION_TERMINAL_BROKER_STATES.get(order.state);
    if (
        !expectedBrokerStatus ||
        order.terminal_at_epoch_ms === null ||
        order.quantity_shares < 1 ||
        order.filled_shares < 0 ||
        order.filled_shares > order.quantity_shares ||
        order.remaining_shares !== 0 ||
        (order.state === 'filled' &&
            order.filled_shares !== order.quantity_shares)
    ) {
        throw new Error(
            'manual resolution broker order is not a canonical terminal outcome',
        );
    }
    const correlations = database
        .prepare(`
            SELECT * FROM broker_correlations
             WHERE intent_id=? AND broker_order_id=?
             ORDER BY correlation_id
        `)
        .all(order.intent_id, order.broker_order_id);
    if (
        correlations.length !== 1 ||
        correlations[0].account_broker_ref !== intent.account_broker_ref ||
        correlations[0].account_id_ref !== intent.account_id_ref ||
        correlations[0].trade_date !== intent.trade_date ||
        correlations[0].contract_key !== intent.contract_key ||
        correlations[0].side !== intent.side
    ) {
        throw new Error(
            'manual resolution broker correlation is not unique and exact',
        );
    }
    const heads = database
        .prepare(`
            SELECT * FROM broker_event_heads
             WHERE intent_id=? AND broker_order_correlation_key_hash=?
             ORDER BY broker_order_correlation_key_hash
        `)
        .all(order.intent_id, correlations[0].canonical_key_hash);
    if (heads.length !== 1) {
        throw new Error(
            'manual resolution requires one canonical broker event head',
        );
    }
    const [head] = heads;
    if (
        head.status !== expectedBrokerStatus ||
        head.remaining_quantity !== 0 ||
        head.order_quantity !==
            head.cumulative_deal_quantity + head.cumulative_cancel_quantity ||
        head.order_quantity < 1
    ) {
        throw new Error(
            'manual resolution broker terminal quantities are inconsistent',
        );
    }
    const brokerQuantities = manualResolutionBrokerQuantityShares(
        database,
        intent,
        order,
        head,
    );
    if (
        brokerQuantities.orderShares !== order.quantity_shares ||
        brokerQuantities.filledShares !== order.filled_shares ||
        brokerQuantities.remainingShares !== order.remaining_shares ||
        brokerQuantities.filledShares + brokerQuantities.cancelledShares !==
            brokerQuantities.orderShares
    ) {
        throw new Error(
            'manual resolution broker quantity conversion is inconsistent',
        );
    }
    const reconciliation = database
        .prepare(`
            SELECT * FROM account_reconciliation_heads
             WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
        `)
        .get(
            intent.account_broker_ref,
            intent.account_id_ref,
            intent.trade_date,
        );
    if (
        !reconciliation ||
        reconciliation.as_of_epoch_ms < head.exchange_epoch_ms ||
        reconciliation.as_of_epoch_ms > nowEpochMs ||
        nowEpochMs - reconciliation.as_of_epoch_ms >
            MANUAL_RESOLUTION_RECONCILIATION_TTL_MS
    ) {
        throw new Error(
            'manual resolution account reconciliation is stale or missing',
        );
    }
    for (const [table, states] of [
        ['entry_exposure_reservations', ['unknown']],
        ['exit_claims', ['unknown']],
        ['protection_obligations', ['safety_blocked', 'reconciling']],
        ['pending_protection_commitments', ['unknown']],
    ]) {
        const count =
            table === 'exit_claims'
                ? database
                      .prepare(`
                          SELECT COUNT(*) AS count
                            FROM exit_claims AS claims
                            JOIN protection_obligations AS obligations
                              ON obligations.obligation_id=claims.obligation_id
                           WHERE obligations.strategy_id=?
                             AND claims.state IN (${states.map(() => '?').join(',')})
                      `)
                      .get(strategy.strategy_id, ...states)
                : database
                      .prepare(`
                          SELECT COUNT(*) AS count FROM ${table}
                           WHERE strategy_id=?
                             AND state IN (${states.map(() => '?').join(',')})
                      `)
                      .get(strategy.strategy_id, ...states);
        if (Number(count?.count) !== 0) {
            throw new Error(
                'manual resolution protection quantities remain unresolved',
            );
        }
    }
    const evidenceHash = sha256Canonical(
        {
            schemaVersion:
                'smart-order-manual-resolution-unique-final-evidence/2026-08-20.1',
            resolutionCaseEvidenceHash:
                resolutionCase.evidence_snapshot_hash,
            runtimeReconciliationEvidenceHash:
                runtime.reconciliation_evidence_hash,
            accountReconciliationEvidenceHash: reconciliation.evidence_hash,
            brokerCorrelationEvidenceHash: correlations[0].evidence_hash,
            brokerOrderEvidenceHash: order.evidence_hash,
            brokerEventEvidenceHash: head.evidence_hash,
            brokerOrderState: order.state,
            quantityShares: order.quantity_shares,
            filledShares: order.filled_shares,
            remainingShares: order.remaining_shares,
        },
        'manual resolution unique final evidence',
    );
    return Object.freeze({
        evidenceHash,
        intent,
        order,
        runtime,
        runtimeEpochId,
    });
}

function listManualResolutionCases(database, input) {
    if (!exactKeys(input, ['strategyId'])) {
        throw new TypeError('manual resolution list input schema is invalid');
    }
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const strategy = database
        .prepare('SELECT * FROM strategies WHERE strategy_id=?')
        .get(strategyId);
    if (!strategy) throw new Error('strategy does not exist');
    const nowEpochMs = Date.now();
    const openCases = database
        .prepare(`
            SELECT * FROM resolution_cases
             WHERE strategy_id=? AND state!='resolved'
             ORDER BY updated_at_epoch_ms DESC, resolution_case_id
             LIMIT 32
        `)
        .all(strategyId);
    const cases = openCases.map((resolutionCase) => {
            const policy = smartOrderManualResolutionPolicyRow(
                resolutionCase.reason_code,
            );
            if (!policy) {
                throw new Error(
                    'manual resolution case has no versioned policy row',
                );
            }
            let uniqueFinalReady = false;
            let uniqueFinalEvidenceHash;
            if (
                openCases.length === 1 &&
                policy.allowedOperations.includes(
                    'apply_unique_final_evidence',
                )
            ) {
                try {
                    uniqueFinalEvidenceHash = proveManualResolutionUniqueFinal(
                        database,
                        { strategy, resolutionCase, nowEpochMs },
                    ).evidenceHash;
                    uniqueFinalReady = true;
                } catch {
                    // Projection stays fail closed and exposes no raw evidence.
                }
            }
            const activeObligationCount = Number(
                database
                    .prepare(`
                        SELECT COUNT(*) AS count
                          FROM protection_obligations
                         WHERE strategy_id=? AND terminal_at_epoch_ms IS NULL
                    `)
                    .get(strategyId)?.count ?? 0,
            );
            return Object.freeze({
                resolutionKey: manualResolutionKey(resolutionCase),
                reasonCode: policy.reasonCode,
                caseRevision: resolutionCase.revision,
                state: boundedToken(
                    resolutionCase.state,
                    'manualResolution.state',
                ),
                requiredEvidence: policy.requiredEvidence,
                allowedOperations: policy.allowedOperations,
                executableOperations: Object.freeze(
                    policy.allowedOperations.filter((operation) =>
                        operation === 'apply_unique_final_evidence'
                            ? uniqueFinalReady
                            : operation === 'break_glass_relinquish'
                              ? activeObligationCount > 0
                              : [
                                    'cancel_strategy',
                                    'copy_to_new_draft',
                                    'remain_open',
                                ].includes(operation),
                    ),
                ),
                uniqueFinalReady,
                ...(uniqueFinalEvidenceHash
                    ? { uniqueFinalEvidenceHash }
                    : {}),
                breakGlassAllowed: policy.breakGlassAllowed,
                oldIntentDisposition: 'never_resend',
                updatedAtEpochMs: resolutionCase.updated_at_epoch_ms,
                accountIdentifiersExposed: false,
                entityIdentifiersExposed: false,
                brokerWriteAuthority: false,
            });
        });
    return Object.freeze({
        schemaVersion:
            'smart-order-manual-resolution-list/2026-08-20.1',
        policySchemaVersion:
            SMART_ORDER_MANUAL_RESOLUTION_POLICY_SCHEMA_VERSION,
        strategyId,
        strategyRevision: strategy.revision,
        strategyState: strategy.state,
        cases: Object.freeze(cases),
        genericResumeAllowed: false,
        brokerWriteAuthority: false,
    });
}

function applyManualResolutionUniqueFinalInTransaction(database, input) {
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'manualResolution.expectedRevision',
    );
    const resolutionKey = sha256Digest(
        input.resolutionKey,
        'manualResolution.resolutionKey',
    );
    const now = safeInteger(input.nowEpochMs, 'manualResolution.nowEpochMs');
    const strategy = database
        .prepare('SELECT * FROM strategies WHERE strategy_id=?')
        .get(strategyId);
    if (
        !strategy ||
        strategy.state !== 'manual_intervention' ||
        strategy.revision !== expectedRevision
    ) {
        throw new Error(
            'manual resolution lost its strategy state or revision',
        );
    }
    const allOpenCases = database
        .prepare(`
            SELECT * FROM resolution_cases
             WHERE strategy_id=? AND state!='resolved'
             ORDER BY resolution_case_id
        `)
        .all(strategyId);
    if (allOpenCases.length !== 1) {
        throw new Error(
            'manual resolution requires one open reason-specific case',
        );
    }
    const cases = allOpenCases.filter(
        (candidate) => manualResolutionKey(candidate) === resolutionKey,
    );
    if (cases.length !== 1) {
        throw new Error('manual resolution target is stale or ambiguous');
    }
    const [resolutionCase] = cases;
    const proof = proveManualResolutionUniqueFinal(database, {
        strategy,
        resolutionCase,
        nowEpochMs: now,
    });
    const intentUpdate = database
        .prepare(`
            UPDATE order_intents
               SET state='terminal', terminal_outcome=?,
                   updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                   revision=revision+1
             WHERE intent_id=? AND state IN ('reconciling','unknown')
               AND revision=?
        `)
        .run(
            `${proof.intent.operation_kind}_${proof.order.state}_unique_final`,
            now,
            now,
            proof.intent.intent_id,
            proof.intent.revision,
        );
    if (Number(intentUpdate.changes) !== 1) {
        throw new Error('manual resolution intent transition lost its CAS');
    }
    const activation = database
        .prepare(`
            SELECT activation_id, state, revision FROM activations
             WHERE activation_id=?
        `)
        .get(proof.intent.activation_id);
    let activationState;
    if (activation?.state === 'unknown') {
        activationState =
            proof.order.state === 'filled'
                ? 'filled'
                : proof.order.state === 'failed'
                  ? 'failed'
                  : 'cancelled';
        const activationUpdate = database
            .prepare(`
                UPDATE activations
                   SET state=?, updated_at_epoch_ms=?, revision=revision+1
                 WHERE activation_id=? AND state='unknown' AND revision=?
            `)
            .run(
                activationState,
                now,
                activation.activation_id,
                activation.revision,
            );
        if (Number(activationUpdate.changes) !== 1) {
            throw new Error(
                'manual resolution activation transition lost its CAS',
            );
        }
    }
    const caseUpdate = database
        .prepare(`
            UPDATE resolution_cases
               SET state='resolved', evidence_snapshot_hash=?,
                   updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                   revision=revision+1
             WHERE resolution_case_id=? AND revision=? AND state!='resolved'
        `)
        .run(
            proof.evidenceHash,
            now,
            now,
            resolutionCase.resolution_case_id,
            resolutionCase.revision,
        );
    if (Number(caseUpdate.changes) !== 1) {
        throw new Error('manual resolution case transition lost its CAS');
    }
    const blockerRows = database
        .prepare(`
            SELECT blocker_id, revision FROM safety_blockers
             WHERE resolution_case_id=? AND state='open'
             ORDER BY blocker_id
        `)
        .all(resolutionCase.resolution_case_id);
    for (const blocker of blockerRows) {
        const blockerUpdate = database
            .prepare(`
                UPDATE safety_blockers
                   SET state='resolved', resolved_at_epoch_ms=?,
                       revision=revision+1
                 WHERE blocker_id=? AND state='open' AND revision=?
            `)
            .run(now, blocker.blocker_id, blocker.revision);
        if (Number(blockerUpdate.changes) !== 1) {
            throw new Error(
                'manual resolution safety blocker transition lost its CAS',
            );
        }
    }
    const rearmRows = database
        .prepare(`
            SELECT rearms.rearm_authorization_id, rearms.revision
              FROM intent_rearm_authorizations AS rearms
              JOIN order_intents AS intents USING(intent_id)
             WHERE intents.strategy_id=? AND rearms.state='active'
        `)
        .all(strategyId);
    for (const rearm of rearmRows) {
        const rearmUpdate = database
            .prepare(`
                UPDATE intent_rearm_authorizations
                   SET state='superseded', revision=revision+1
                 WHERE rearm_authorization_id=? AND state='active'
                   AND revision=?
            `)
            .run(rearm.rearm_authorization_id, rearm.revision);
        if (Number(rearmUpdate.changes) !== 1) {
            throw new Error('manual resolution re-arm transition lost its CAS');
        }
    }
    const strategyUpdate = database
        .prepare(`
            UPDATE strategies
               SET state='paused', updated_at_epoch_ms=?, revision=revision+1
             WHERE strategy_id=? AND state='manual_intervention' AND revision=?
        `)
        .run(now, strategyId, expectedRevision);
    if (Number(strategyUpdate.changes) !== 1) {
        throw new Error('manual resolution strategy transition lost its CAS');
    }
    advanceLifecycleSideEffectRevision(database);
    insertTransitionJournalEvent(database, {
        entityKind: 'order_intent',
        entityId: proof.intent.intent_id,
        revision: proof.intent.revision + 1,
        reasonCode: 'MANUAL_FINAL_EVIDENCE_APPLIED',
        summaryCode: 'manual_unique_final_intent_terminal',
        nowEpochMs: now,
        payloadHash: proof.evidenceHash,
        eventSuffix: 'manual-resolution-final',
    });
    insertTransitionJournalEvent(database, {
        entityKind: 'resolution_case',
        entityId: resolutionCase.resolution_case_id,
        revision: resolutionCase.revision + 1,
        reasonCode: 'RESOLUTION_CASE_RESOLVED_FINAL_EVIDENCE',
        summaryCode: 'manual_resolution_unique_final_applied',
        nowEpochMs: now,
        payloadHash: proof.evidenceHash,
        eventSuffix: 'unique-final',
    });
    insertTransitionJournalEvent(database, {
        entityKind: 'strategy',
        entityId: strategyId,
        revision: expectedRevision + 1,
        reasonCode: 'MANUAL_RESOLUTION_RECONFIRMED',
        summaryCode: 'manual_resolution_paused_after_unique_final',
        nowEpochMs: now,
        payloadHash: proof.evidenceHash,
        eventSuffix: 'unique-final',
    });
    return Object.freeze({
        schemaVersion:
            'smart-order-manual-resolution-result/2026-08-20.1',
        strategyId,
        strategyState: 'paused',
        strategyRevision: expectedRevision + 1,
        resolutionState: 'resolved',
        resolutionRevision: resolutionCase.revision + 1,
        uniqueFinalEvidenceHash: proof.evidenceHash,
        originalIntentState: 'terminal',
        originalIntentRedispatchAllowed: false,
        safetyBlockerCount: blockerRows.length,
        rearmSupersededCount: rearmRows.length,
        brokerWriteAttempted: false,
        brokerAuthorityGranted: false,
    });
}

function resolveManualIntervention(database, input) {
    if (
        !exactKeys(input, [
            'apiGeneration',
            'expectedRevision',
            'nowEpochMs',
            'operation',
            'payloadHash',
            'requestId',
            'resolutionKey',
            'runtimeEpochId',
            'senderFence',
            'strategyId',
        ]) ||
        input.operation !== 'apply_unique_final_evidence'
    ) {
        throw new TypeError('manual resolution mutation schema is invalid');
    }
    const request = {
        requestId: input.requestId,
        operationKind: 'manual_resolution_apply_unique_final',
        payloadHash: input.payloadHash,
        nowEpochMs: input.nowEpochMs,
    };
    return transaction(database, () => {
        if (
            !currentRuntimeObserverMatches(database, {
                runtimeEpochId: input.runtimeEpochId,
                senderFence: input.senderFence,
                apiGeneration: input.apiGeneration,
            })
        ) {
            throw new Error(
                'manual resolution requires the current Runtime observer',
            );
        }
        const replay = reserveRequestReplayInTransaction(database, request);
        if (replay.replayed) return replay;
        database.exec('SAVEPOINT manual_resolution_effect');
        let result;
        try {
            result = applyManualResolutionUniqueFinalInTransaction(
                database,
                input,
            );
            database.exec('RELEASE manual_resolution_effect');
        } catch (error) {
            database.exec('ROLLBACK TO manual_resolution_effect');
            database.exec('RELEASE manual_resolution_effect');
            const publicError = publicStrategyOperationError(error);
            const publicResult = {
                code: publicError.code,
                status: publicError.status,
            };
            const failed = failRequestReplayInTransaction(database, {
                ...request,
                resultStatus: publicError.status,
                result: publicResult,
            });
            return Object.freeze({
                ...failed,
                result: publicResult,
                replayed: false,
                mayExecute: false,
            });
        }
        const completed = completeRequestReplayInTransaction(database, {
            ...request,
            resultStatus: 200,
            result,
        });
        return Object.freeze({
            ...completed,
            result,
            replayed: false,
            mayExecute: false,
        });
    });
}

function historyTerminalBlockers(database, strategyId) {
    const blockers = strategySideEffectBlockers(database, strategyId);
    const lifecycleCounts = database
        .prepare(`
            SELECT
              (SELECT COUNT(*) FROM activations
                WHERE strategy_id=?
                  AND state NOT IN ('filled','cancelled','failed','missed'))
                  AS activations,
              (SELECT COUNT(*) FROM pending_protection_commitments
                WHERE strategy_id=?
                  AND state NOT IN ('materialized','zero_fill_terminal',
                                    'released_pre_dispatch','released_manual'))
                  AS commitments,
              (SELECT COUNT(*) FROM protection_obligations
                WHERE strategy_id=?
                  AND state NOT IN ('fulfilled','zero_fill_terminal',
                                    'released_manual'))
                  AS obligation_states,
              (SELECT COUNT(*) FROM resolution_cases
                WHERE strategy_id=? AND state!='resolved') AS resolution_cases,
              (SELECT COUNT(*) FROM safety_blockers AS blockers
                JOIN resolution_cases AS cases
                  ON cases.resolution_case_id=blockers.resolution_case_id
               WHERE cases.strategy_id=? AND blockers.state!='resolved')
                  AS safety_blockers
        `)
        .get(strategyId, strategyId, strategyId, strategyId, strategyId);
    for (const [kind, rawCount] of Object.entries(lifecycleCounts ?? {})) {
        const count = Number(rawCount);
        if (!Number.isSafeInteger(count) || count < 0) {
            throw new Error('strategy lifecycle history projection is invalid');
        }
        if (count > 0) blockers.push(`${kind}:${count}`);
    }
    return blockers;
}

function listHistory(database, input) {
    if (
        !input ||
        typeof input !== 'object' ||
        Array.isArray(input) ||
        Object.keys(input).some((key) => key !== 'limit')
    ) {
        throw new TypeError('history read input is invalid');
    }
    const limit = safeInteger(input.limit ?? SMART_ORDER_HISTORY_MAX_ITEMS, 'history.limit', {
        minimum: 1,
    });
    if (limit > SMART_ORDER_HISTORY_MAX_ITEMS) {
        throw new TypeError('history limit exceeds 100');
    }
    const rows = database
        .prepare(`
            SELECT strategies.strategy_id,
                   strategies.strategy_kind,
                   strategies.state,
                   strategies.account_broker_ref,
                   strategies.account_id_ref,
                   strategies.created_at_epoch_ms,
                   strategies.updated_at_epoch_ms,
                   strategies.terminal_at_epoch_ms,
                   strategies.revision,
                   journal.entity_kind,
                   journal.reason_code,
                   journal.exchange_epoch_ms,
                   journal.broker_epoch_ms,
                   journal.receive_epoch_ms,
                   journal.entity_revision
              FROM strategies
              LEFT JOIN event_journal AS journal
                ON journal.journal_sequence = (
                    SELECT candidate.journal_sequence
                      FROM event_journal AS candidate
                     WHERE candidate.entity_kind='strategy'
                       AND candidate.entity_id=strategies.strategy_id
                       AND candidate.entity_revision=strategies.revision
                     ORDER BY candidate.journal_sequence DESC
                     LIMIT 1
                )
             WHERE strategies.state IN ('cancelled','completed','expired','failed')
               AND strategies.terminal_at_epoch_ms IS NOT NULL
             ORDER BY strategies.terminal_at_epoch_ms DESC,
                      strategies.strategy_id
             LIMIT ?
        `)
        .all(limit);
    return Object.freeze(
        rows.map((row) => {
            const reasonStates = STRATEGY_TERMINAL_HISTORY_REASON_STATES.get(
                row.reason_code,
            );
            if (
                !SMART_ORDER_STRATEGY_KINDS.has(row.strategy_kind) ||
                !STRATEGY_TERMINAL_STATES.has(row.state) ||
                !reasonStates?.has(row.state) ||
                row.entity_kind !== 'strategy' ||
                row.entity_revision !== row.revision ||
                row.receive_epoch_ms !== row.updated_at_epoch_ms ||
                row.created_at_epoch_ms > row.updated_at_epoch_ms ||
                row.terminal_at_epoch_ms > row.updated_at_epoch_ms ||
                (row.exchange_epoch_ms !== null &&
                    row.exchange_epoch_ms > row.receive_epoch_ms) ||
                (row.broker_epoch_ms !== null &&
                    row.broker_epoch_ms > row.receive_epoch_ms) ||
                (row.exchange_epoch_ms !== null &&
                    row.broker_epoch_ms !== null &&
                    row.exchange_epoch_ms > row.broker_epoch_ms) ||
                historyTerminalBlockers(database, row.strategy_id).length !== 0
            ) {
                throw new Error('terminal strategy history projection is invalid');
            }
            return Object.freeze({
                type: 'strategy',
                strategyId: boundedToken(row.strategy_id, 'history.strategyId'),
                strategyKind: row.strategy_kind,
                state: row.state,
                maskedAccountLabel: maskedAccountLabel(row),
                reasonCode: boundedToken(row.reason_code, 'history.reasonCode'),
                revision: safeInteger(row.revision, 'history.revision'),
                createdAtEpochMs: safeInteger(
                    row.created_at_epoch_ms,
                    'history.createdAtEpochMs',
                ),
                updatedAtEpochMs: safeInteger(
                    row.updated_at_epoch_ms,
                    'history.updatedAtEpochMs',
                ),
                terminalAtEpochMs: safeInteger(
                    row.terminal_at_epoch_ms,
                    'history.terminalAtEpochMs',
                ),
                exchangeEpochMs:
                    row.exchange_epoch_ms === null
                        ? null
                        : safeInteger(
                              row.exchange_epoch_ms,
                              'history.exchangeEpochMs',
                          ),
                brokerEpochMs:
                    row.broker_epoch_ms === null
                        ? null
                        : safeInteger(
                              row.broker_epoch_ms,
                              'history.brokerEpochMs',
                          ),
                receiveEpochMs: safeInteger(
                    row.receive_epoch_ms,
                    'history.receiveEpochMs',
                ),
            });
        }),
    );
}

function listEvents(database, input) {
    if (
        !input ||
        typeof input !== 'object' ||
        Array.isArray(input) ||
        Object.keys(input).some(
            (key) => !['afterSequence', 'limit'].includes(key),
        )
    ) {
        throw new TypeError('event read input is invalid');
    }
    const afterSequence =
        input.afterSequence === null
            ? null
            : safeInteger(input.afterSequence, 'events.afterSequence');
    const limit = safeInteger(
        input.limit ?? SMART_ORDER_EVENT_READ_MAX_ITEMS,
        'events.limit',
        { minimum: 1 },
    );
    if (limit > SMART_ORDER_EVENT_READ_MAX_ITEMS) {
        throw new TypeError('event read limit exceeds 100');
    }
    const highWaterSequence = Number(
        repositoryMetaValue(database, 'journal_local_sequence'),
    );
    if (!Number.isSafeInteger(highWaterSequence) || highWaterSequence < 0) {
        throw new Error('event journal high-water cursor is invalid');
    }
    if (afterSequence !== null && afterSequence > highWaterSequence) {
        throw new Error('event cursor is ahead of the durable journal');
    }
    if (afterSequence === null) {
        return Object.freeze({
            schemaVersion: SMART_ORDER_EVENT_PROJECTION_SCHEMA_VERSION,
            cursorStatus: 'initialized',
            fromSequence: null,
            nextSequence: highWaterSequence,
            highWaterSequence,
            events: Object.freeze([]),
            accountIdentifiersExposed: false,
            entityIdentifiersExposed: false,
            journalPayloadExposed: false,
        });
    }

    const rows = database
        .prepare(`
            SELECT entity_kind, reason_code, exchange_epoch_ms,
                   broker_epoch_ms, receive_epoch_ms,
                   local_monotonic_sequence, entity_revision, summary_code,
                   created_at_epoch_ms
              FROM event_journal
             WHERE local_monotonic_sequence > ?
             ORDER BY local_monotonic_sequence
             LIMIT ?
        `)
        .all(afterSequence, limit);
    const earliestSequence = database
        .prepare(
            'SELECT MIN(local_monotonic_sequence) AS sequence FROM event_journal',
        )
        .get()?.sequence;
    const firstSequence = rows[0]?.local_monotonic_sequence;
    const cursorHasGap =
        afterSequence < highWaterSequence &&
        ((rows.length === 0 && earliestSequence === null) ||
            firstSequence !== afterSequence + 1 ||
            rows.some(
                (row, index) =>
                    index > 0 &&
                    row.local_monotonic_sequence !==
                        rows[index - 1].local_monotonic_sequence + 1,
            ));
    if (cursorHasGap) {
        return Object.freeze({
            schemaVersion: SMART_ORDER_EVENT_PROJECTION_SCHEMA_VERSION,
            cursorStatus: 'gap',
            fromSequence: afterSequence,
            nextSequence: highWaterSequence,
            highWaterSequence,
            events: Object.freeze([]),
            accountIdentifiersExposed: false,
            entityIdentifiersExposed: false,
            journalPayloadExposed: false,
        });
    }

    const events = rows.map((row) => {
        if (
            !SMART_ORDER_JOURNAL_ENTITY_KINDS.includes(row.entity_kind) ||
            !Number.isSafeInteger(row.local_monotonic_sequence) ||
            row.local_monotonic_sequence <= afterSequence ||
            !Number.isSafeInteger(row.entity_revision) ||
            row.entity_revision < 0 ||
            !Number.isSafeInteger(row.receive_epoch_ms) ||
            row.receive_epoch_ms < 0 ||
            row.created_at_epoch_ms !== row.receive_epoch_ms ||
            (row.exchange_epoch_ms !== null &&
                (!Number.isSafeInteger(row.exchange_epoch_ms) ||
                    row.exchange_epoch_ms < 0 ||
                    row.exchange_epoch_ms > row.receive_epoch_ms)) ||
            (row.broker_epoch_ms !== null &&
                (!Number.isSafeInteger(row.broker_epoch_ms) ||
                    row.broker_epoch_ms < 0 ||
                    row.broker_epoch_ms > row.receive_epoch_ms)) ||
            (row.exchange_epoch_ms !== null &&
                row.broker_epoch_ms !== null &&
                row.exchange_epoch_ms > row.broker_epoch_ms)
        ) {
            throw new Error('event journal projection is invalid');
        }
        return Object.freeze({
            sequence: row.local_monotonic_sequence,
            entityKind: boundedToken(row.entity_kind, 'events.entityKind'),
            reasonCode: boundedToken(row.reason_code, 'events.reasonCode'),
            revision: row.entity_revision,
            summaryCode: boundedToken(row.summary_code, 'events.summaryCode'),
            exchangeEpochMs: row.exchange_epoch_ms,
            brokerEpochMs: row.broker_epoch_ms,
            receiveEpochMs: row.receive_epoch_ms,
        });
    });
    return Object.freeze({
        schemaVersion: SMART_ORDER_EVENT_PROJECTION_SCHEMA_VERSION,
        cursorStatus: 'current',
        fromSequence: afterSequence,
        nextSequence:
            events.length === 0
                ? afterSequence
                : events[events.length - 1].sequence,
        highWaterSequence,
        events: Object.freeze(events),
        accountIdentifiersExposed: false,
        entityIdentifiersExposed: false,
        journalPayloadExposed: false,
    });
}

function getStrategy(database, input) {
    const row = database
        .prepare('SELECT * FROM strategies WHERE strategy_id=?')
        .get(boundedToken(input.strategyId, 'strategyId'));
    return row
        ? parseStrategyRow(row, { includeDefinition: true, database })
        : null;
}

function pauseStrategy(database, input, withinExistingTransaction = false) {
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const expectedRevision = safeInteger(input.expectedRevision, 'expectedRevision');
    const now = safeInteger(input.nowEpochMs, 'pause.nowEpochMs');
    const mutate = () => {
        const result = database
            .prepare(`
                UPDATE strategies
                   SET state='paused', updated_at_epoch_ms=?, revision=revision+1
                 WHERE strategy_id=? AND state IN ('observing','monitoring')
                   AND revision=?
            `)
            .run(now, strategyId, expectedRevision);
        if (Number(result.changes) !== 1) {
            throw new Error('strategy pause is not allowed or lost its revision');
        }
        const row = database
            .prepare('SELECT * FROM strategies WHERE strategy_id=?')
            .get(strategyId);
        insertJournalEvent(
            database,
            {
                eventId: `strategy:${strategyId}:paused:${expectedRevision + 1}`,
                entityKind: 'strategy',
                entityId: strategyId,
                reasonCode: 'STRATEGY_PAUSED_BY_USER',
                receiveEpochMs: now,
                payloadHash: row.definition_hash,
                summaryCode: 'strategy_paused',
                createdAtEpochMs: now,
            },
            expectedRevision + 1,
        );
        return parseStrategyRow(row, { database });
    };
    return withinExistingTransaction ? mutate() : transaction(database, mutate);
}

function strategySideEffectBlockers(database, strategyId) {
    const counts = database
        .prepare(`
            SELECT
              (SELECT COUNT(*) FROM order_intents
                WHERE strategy_id=? AND state NOT IN ('terminal','cancelled_proven_unsent')) AS intents,
              (SELECT COUNT(*) FROM broker_orders AS orders
                JOIN order_intents AS intents ON intents.intent_id=orders.intent_id
               WHERE intents.strategy_id=? AND orders.state NOT IN
                     ('filled','cancelled','failed','inactive')) AS broker_orders,
              (SELECT COUNT(*) FROM protection_obligations
                WHERE strategy_id=? AND terminal_at_epoch_ms IS NULL) AS obligations,
              (SELECT COUNT(*) FROM entry_exposure_reservations
                WHERE strategy_id=? AND state NOT IN ('consumed','released')) AS reservations,
              (SELECT COUNT(*) FROM exit_claims AS claims
                JOIN protection_obligations AS obligations
                  ON obligations.obligation_id=claims.obligation_id
               WHERE obligations.strategy_id=? AND claims.state NOT IN
                     ('consumed','released')) AS claims
        `)
        .get(strategyId, strategyId, strategyId, strategyId, strategyId);
    return Object.entries(counts)
        .filter(([, count]) => Number(count) > 0)
        .map(([kind, count]) => `${kind}:${count}`);
}

function assertManualResolutionOperationAllowed(
    database,
    { strategyId, strategyState, operation },
) {
    if (strategyState !== 'manual_intervention') return;
    const cases = database
        .prepare(`
            SELECT reason_code FROM resolution_cases
             WHERE strategy_id=? AND state!='resolved'
             ORDER BY resolution_case_id
        `)
        .all(strategyId);
    if (
        cases.length === 0 ||
        cases.some(
            (resolutionCase) =>
                !smartOrderManualResolutionPolicyRow(
                    resolutionCase.reason_code,
                )?.allowedOperations.includes(operation),
        )
    ) {
        throw new Error(
            'manual intervention operation is forbidden by its reason matrix',
        );
    }
}

function resolveManualCasesForBreakGlass(
    database,
    { strategyId, strategyState, evidenceHash, nowEpochMs },
) {
    if (strategyState !== 'manual_intervention') return 0;
    const cases = database
        .prepare(`
            SELECT resolution_case_id, revision FROM resolution_cases
             WHERE strategy_id=? AND state!='resolved'
             ORDER BY resolution_case_id
        `)
        .all(strategyId);
    for (const resolutionCase of cases) {
        const blockers = database
            .prepare(`
                SELECT blocker_id, revision FROM safety_blockers
                 WHERE resolution_case_id=? AND state='open'
            `)
            .all(resolutionCase.resolution_case_id);
        for (const blocker of blockers) {
            const update = database
                .prepare(`
                    UPDATE safety_blockers
                       SET state='resolved', resolved_at_epoch_ms=?,
                           revision=revision+1
                     WHERE blocker_id=? AND state='open' AND revision=?
                `)
                .run(nowEpochMs, blocker.blocker_id, blocker.revision);
            if (Number(update.changes) !== 1) {
                throw new Error(
                    'break-glass predecessor blocker transition lost its CAS',
                );
            }
        }
        const update = database
            .prepare(`
                UPDATE resolution_cases
                   SET state='resolved', evidence_snapshot_hash=?,
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE resolution_case_id=? AND state!='resolved'
                   AND revision=?
            `)
            .run(
                evidenceHash,
                nowEpochMs,
                nowEpochMs,
                resolutionCase.resolution_case_id,
                resolutionCase.revision,
            );
        if (Number(update.changes) !== 1) {
            throw new Error(
                'break-glass predecessor resolution transition lost its CAS',
            );
        }
    }
    return cases.length;
}

function requestStrategyCancellation(
    database,
    input,
    withinExistingTransaction = false,
) {
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const expectedRevision = safeInteger(input.expectedRevision, 'expectedRevision');
    const now = safeInteger(input.nowEpochMs, 'cancel.nowEpochMs');
    const mutate = () => {
        const row = database
            .prepare('SELECT * FROM strategies WHERE strategy_id=?')
            .get(strategyId);
        if (!row) throw new Error('strategy does not exist');
        if (row.revision !== expectedRevision) {
            throw new Error('strategy cancellation lost its optimistic revision');
        }
        if (STRATEGY_TERMINAL_STATES.has(row.state)) {
            throw new Error('terminal strategy cannot be cancelled again');
        }
        assertManualResolutionOperationAllowed(database, {
            strategyId,
            strategyState: row.state,
            operation: 'cancel_strategy',
        });
        if (row.state === 'cancel_pending') {
            return {
                ...parseStrategyRow(row, { database }),
                blockers: Object.freeze(strategySideEffectBlockers(database, strategyId)),
                replayed: true,
            };
        }
        const blockers = strategySideEffectBlockers(database, strategyId);
        const nextState = blockers.length === 0 ? 'cancelled' : 'cancel_pending';
        const result = database
            .prepare(`
                UPDATE strategies
                   SET state=?, updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE strategy_id=? AND revision=?
            `)
            .run(
                nextState,
                now,
                nextState === 'cancelled' ? now : null,
                strategyId,
                expectedRevision,
            );
        if (Number(result.changes) !== 1) {
            throw new Error('strategy cancellation lost its optimistic revision');
        }
        const updated = database
            .prepare('SELECT * FROM strategies WHERE strategy_id=?')
            .get(strategyId);
        insertJournalEvent(
            database,
            {
                eventId: `strategy:${strategyId}:cancel:${expectedRevision + 1}`,
                entityKind: 'strategy',
                entityId: strategyId,
                reasonCode:
                    nextState === 'cancelled'
                        ? 'STRATEGY_CANCELLED_WITHOUT_SIDE_EFFECTS'
                        : 'STRATEGY_CANCELLATION_PENDING_SIDE_EFFECT_DRAIN',
                receiveEpochMs: now,
                payloadHash: row.definition_hash,
                summaryCode:
                    nextState === 'cancelled'
                        ? 'strategy_cancelled'
                        : 'strategy_cancel_pending',
                createdAtEpochMs: now,
            },
            expectedRevision + 1,
        );
        return {
            ...parseStrategyRow(updated, { database }),
            blockers: Object.freeze(blockers),
            replayed: false,
        };
    };
    return withinExistingTransaction ? mutate() : transaction(database, mutate);
}

function copyStrategyToDraft(database, input, withinExistingTransaction = false) {
    const sourceId = boundedToken(input.sourceStrategyId, 'sourceStrategyId');
    const draftId = boundedToken(input.draftStrategyId, 'draftStrategyId');
    const now = safeInteger(input.nowEpochMs, 'copy.nowEpochMs');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'expectedRevision',
    );
    const mutate = () => {
        assertStrategyCapacity(database, { draft: true });
        const source = database
            .prepare('SELECT * FROM strategies WHERE strategy_id=?')
            .get(sourceId);
        if (!source) throw new Error('source strategy does not exist');
        if (source.revision !== expectedRevision) {
            throw new Error('strategy copy lost its optimistic revision');
        }
        assertManualResolutionOperationAllowed(database, {
            strategyId: sourceId,
            strategyState: source.state,
            operation: 'copy_to_new_draft',
        });
        const draft = assertCanonicalSmartOrderDraft(
            JSON.parse(source.definition_json),
            { expectedKind: source.strategy_kind },
        );
        const definitionJson = canonicalJson(draft, 'copiedDraft.definition');
        const definitionHash = `sha256:${createHash('sha256')
            .update(definitionJson)
            .digest('hex')}`;
        database
            .prepare(`
                INSERT INTO strategies(
                    strategy_id, strategy_kind, state, definition_hash,
                    definition_json, account_broker_ref, account_id_ref,
                    identity_group_id, confirmation_snapshot_hash,
                    created_at_epoch_ms, updated_at_epoch_ms, revision
                ) VALUES (?, ?, 'draft', ?, ?, 'draft-unbound',
                          'draft-unbound', 'draft-unbound', ?, ?, ?, 0)
            `)
            .run(
                draftId,
                source.strategy_kind,
                definitionHash,
                definitionJson,
                definitionHash,
                now,
                now,
            );
        insertJournalEvent(
            database,
            {
                eventId: `strategy:${draftId}:copied:0`,
                entityKind: 'strategy',
                entityId: draftId,
                reasonCode: 'STRATEGY_COPIED_TO_DRAFT',
                receiveEpochMs: now,
                payloadHash: definitionHash,
                summaryCode: 'strategy_copied_to_draft',
                createdAtEpochMs: now,
            },
            0,
        );
        return parseStrategyRow(
            database
                .prepare('SELECT * FROM strategies WHERE strategy_id=?')
                .get(draftId),
            { includeDefinition: true, database },
        );
    };
    return withinExistingTransaction ? mutate() : transaction(database, mutate);
}

function currentEligibleManualGate(
    database,
    strategyKind,
    nowEpochMs,
    operation = 'strategy resume',
    requireFeatureGate = true,
) {
    const status = gateManifestStatus(database, {
        provenance: 'manual_user_confirmed',
        nowEpochMs,
    });
    if (
        status.state !== 'eligible' ||
        (requireFeatureGate && status.featureGates[strategyKind] !== true)
    ) {
        throw new Error(
            `${operation} requires current gate, readiness, confirmation and arm verification`,
        );
    }
    return status;
}

function insertAuthorityConsumptionInTransaction(database, input) {
    const existing = database
        .prepare(`
            SELECT 1 FROM authority_consumptions
             WHERE authority_kind=? AND authority_id=?
        `)
        .get(input.authorityKind, input.authorityId);
    if (existing) throw new Error('authority was already durably consumed');
    database
        .prepare(`
            INSERT INTO authority_consumptions(
                authority_kind, authority_id, authority_payload_hash,
                scope_hash, consumed_by, runtime_epoch_id,
                consumed_at_epoch_ms
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
        `)
        .run(
            input.authorityKind,
            input.authorityId,
            input.authorityPayloadHash,
            input.scopeHash,
            input.consumedBy,
            input.runtimeEpochId,
            input.consumedAtEpochMs,
        );
    insertTransitionJournalEvent(database, {
        entityKind: 'authority_consumption',
        entityId: sha256Canonical(
            {
                authorityKind: input.authorityKind,
                authorityId: input.authorityId,
            },
            'strategy control authority identity',
        ),
        revision: 0,
        reasonCode: 'ONE_TIME_AUTHORITY_DURABLY_CONSUMED',
        summaryCode: 'authority_consumed',
        nowEpochMs: input.consumedAtEpochMs,
        payloadHash: input.authorityPayloadHash,
        eventSuffix: 'consumed',
    });
}

function currentExistingPositionProtectionArm(
    database,
    {
        apiGeneration,
        expectedGroupState,
        nowEpochMs,
        runtimeEpochId,
        senderFence,
        strategyId,
    },
) {
    const rows = database.prepare(`
        SELECT strategies.strategy_id, strategies.state AS strategy_state,
               strategies.strategy_kind, strategies.confirmation_snapshot_hash,
               groups.protection_group_id, groups.current_generation,
               groups.plan_hash, groups.state AS group_state,
               groups.revision AS group_revision,
               generations.state AS generation_state,
               generations.quantity_shares,
               generations.revision AS generation_revision,
               claims.exit_claim_id, claims.account_broker_ref,
               claims.account_id_ref, claims.contract_key,
               claims.position_lineage_id, claims.quantity_shares AS claim_quantity_shares,
               claims.state AS claim_state, claims.revision AS claim_revision,
               heads.trade_date, heads.protection_plan_json,
               heads.protection_plan_hash, heads.formal_protection_json,
               heads.formal_protection_hash,
               heads.reconciliation_evidence_hash,
               heads.reconciliation_as_of_epoch_ms,
               heads.revision AS head_revision,
               positions.account_head_revision,
               positions.position_lineage_id AS current_position_lineage_id,
               positions.quantity_shares AS current_position_quantity_shares,
               positions.available_shares AS current_position_available_shares,
               positions.evidence_hash AS current_position_evidence_hash,
               positions.as_of_epoch_ms AS current_position_as_of_epoch_ms,
               positions.valid_until_epoch_ms AS current_position_valid_until_epoch_ms,
               account_heads.revision AS current_account_head_revision,
               account_heads.evidence_hash AS current_account_evidence_hash,
               account_heads.snapshot_hash AS current_account_snapshot_hash,
               account_heads.event_stream_watermark_hash AS current_event_stream_watermark_hash,
               runtime.reconciliation_evidence_hash AS runtime_reconciliation_evidence_hash
          FROM existing_position_protection_heads AS heads
          JOIN strategies ON strategies.strategy_id=heads.strategy_id
          JOIN protection_groups AS groups
            ON groups.exit_claim_id=heads.exit_claim_id
          JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
          JOIN exit_claims AS claims ON claims.exit_claim_id=heads.exit_claim_id
          JOIN account_reconciliation_positions AS positions
            ON positions.account_broker_ref=claims.account_broker_ref
           AND positions.account_id_ref=claims.account_id_ref
           AND positions.trade_date=heads.trade_date
           AND positions.contract_key=claims.contract_key
          JOIN account_reconciliation_heads AS account_heads
            ON account_heads.account_broker_ref=positions.account_broker_ref
           AND account_heads.account_id_ref=positions.account_id_ref
           AND account_heads.trade_date=positions.trade_date
          JOIN runtime_epochs AS runtime
            ON runtime.runtime_epoch_id=? AND runtime.sender_fence=?
           AND runtime.api_generation=? AND runtime.state='ready'
         WHERE heads.strategy_id=?
           AND groups.state=? AND generations.state=?
           AND claims.remainder_generation=groups.current_generation
           AND claims.state='monitoring_reserved' AND claims.intent_id IS NULL
           AND claims.external_lineage=0
         ORDER BY groups.protection_group_id
    `).all(
        runtimeEpochId,
        senderFence,
        apiGeneration,
        strategyId,
        expectedGroupState,
        expectedGroupState,
    );
    if (rows.length === 0) return null;
    if (rows.length !== 1) {
        throw new Error(
            'existing-position protection arm requires one exact remainder lineage',
        );
    }
    const row = rows[0];
    const confirmations = database.prepare(`
        SELECT * FROM canonical_confirmation_snapshots
         WHERE strategy_id=? AND snapshot_hash=?
           AND accepted_at_epoch_ms IS NOT NULL
         ORDER BY confirmation_id
    `).all(strategyId, row.confirmation_snapshot_hash);
    if (confirmations.length !== 1) {
        throw new Error(
            'existing-position protection arm requires its unique accepted confirmation',
        );
    }
    const confirmation = confirmations[0];
    let content;
    try {
        content = JSON.parse(confirmation.snapshot_json);
    } catch {
        throw new Error(
            'existing-position protection confirmation JSON is invalid',
        );
    }
    const now = safeInteger(
        nowEpochMs,
        'existingPositionProtectionArm.nowEpochMs',
    );
    const plan = canonicalExistingPositionProtectionPlan(
        parseStoredCanonicalObject(
            row.protection_plan_json,
            'existing-position protection arm plan',
        ),
    );
    const formal = deriveExistingPositionFormalProtection(
        plan.plan,
        row.claim_quantity_shares,
    );
    const contractHeadValue = repositoryMetaValue(
        database,
        `${CANONICAL_CONTRACT_HEAD_META_PREFIX}${createHash('sha256')
            .update(
                `${content?.fixedAccount?.accountScopeSha256}\u001f${row.contract_key}`,
            )
            .digest('hex')}`,
    );
    if (contractHeadValue === undefined) {
        throw new Error(
            'existing-position protection arm contract head is missing',
        );
    }
    const contractHead = parseCanonicalContractHead(contractHeadValue);
    const gate = gateManifestStatus(database, {
        provenance: 'automation',
        nowEpochMs: now,
    });
    const risk = runtimeRiskPolicyView(database);
    const roundHeads = database.prepare(`
        SELECT snapshot_hash
          FROM account_reconciliation_heads
         WHERE trade_date=? AND event_stream_watermark_hash=?
         ORDER BY account_broker_ref, account_id_ref
    `).all(row.trade_date, row.current_event_stream_watermark_hash);
    const currentReconciliationEvidenceHash = sha256Canonical(
        {
            eventStreamWatermarkSha256:
                row.current_event_stream_watermark_hash,
            snapshotHashes: roundHeads.map((head) => head.snapshot_hash),
            tradeDate: row.trade_date,
        },
        'durable account reconciliation evidence',
    );
    const invalidReasons = [
        [
            'confirmation_integrity',
            stableCanonicalJson(content) !== confirmation.snapshot_json ||
                sha256Canonical(content, 'canonical confirmation snapshot') !==
                    confirmation.snapshot_hash ||
                content.schemaVersion !== STRATEGY_CONFIRMATION_SCHEMA_VERSION ||
                !['accepted', 'superseded'].includes(confirmation.state) ||
                (row.current_generation === 0 &&
                    confirmation.valid_until_epoch_ms <= now),
        ],
        [
            'strategy_plan_lineage',
            row.strategy_kind !== content.strategyKind ||
                row.confirmation_snapshot_hash !==
                    plan.plan.confirmationSnapshotHash ||
                plan.planSha256 !== row.protection_plan_hash ||
                plan.planSha256 !== row.plan_hash ||
                row.claim_quantity_shares !== row.quantity_shares,
        ],
        [
            'position_currentness',
            row.current_position_lineage_id !== row.position_lineage_id ||
                row.current_position_quantity_shares <
                    row.claim_quantity_shares ||
                row.current_position_available_shares <
                    row.claim_quantity_shares ||
                row.current_position_valid_until_epoch_ms <= now ||
                row.current_position_as_of_epoch_ms > now ||
                row.account_head_revision !==
                    row.current_account_head_revision ||
                row.current_position_evidence_hash !==
                    row.current_account_evidence_hash ||
                row.current_position_evidence_hash !==
                    row.reconciliation_evidence_hash,
        ],
        [
            'runtime_reconciliation',
            roundHeads.length === 0 ||
                ![
                    row.reconciliation_evidence_hash,
                    currentReconciliationEvidenceHash,
                ].includes(row.runtime_reconciliation_evidence_hash),
        ],
        [
            'formal_projection',
            stableCanonicalJson(formal) !== row.formal_protection_json ||
                sha256Canonical(formal, 'existing-position formal protection') !==
                    row.formal_protection_hash,
        ],
        [
            'confirmation_scope',
            content.fixedAccount.accountBrokerRef !== row.account_broker_ref ||
                content.fixedAccount.accountIdRef !== row.account_id_ref ||
                content.contract.runtimeContractKey !== row.contract_key ||
                content.position.positionLineageId !== row.position_lineage_id,
        ],
        [
            'contract_currentness',
            contractHead.contractRevision !== content.contractRevision ||
                contractHead.corporateActionRevision !==
                    content.corporateActionRevision ||
                contractHead.runtimeEpochId !== runtimeEpochId ||
                contractHead.apiGeneration !== apiGeneration ||
                contractHead.validUntilEpochMs <= now,
        ],
        [
            'gate_currentness',
            gate.state !== 'eligible' ||
                gate.manifestRevision !== content.gate.manifestRevision ||
                gate.manifestSha256 !== content.gate.manifestHash ||
                gate.mappingRevision !== content.gate.mappingRevision,
        ],
        [
            'risk_currentness',
            risk.state !== 'current' ||
                risk.policyHash !== content.risk.policyHash ||
                String(risk.revision) !== String(content.risk.revision) ||
                plan.plan.riskRevision !== risk.policy?.policyRevision,
        ],
    ].filter(([, invalid]) => invalid).map(([reason]) => reason);
    if (invalidReasons.length > 0) {
        throw new Error(
            `existing-position protection remainder is not current for user re-arm: ${invalidReasons.join(',')}`,
        );
    }
    return Object.freeze({
        ...row,
        confirmationState: confirmation.state,
        formalProtectionHash: row.formal_protection_hash,
    });
}

function resumeStrategy(database, input, withinExistingTransaction = false) {
    if (
        !exactKeys(input, [
            'activationPolicyAcknowledged',
            'apiGeneration',
            'authorityId',
            'contractEvidence',
            'expectedRevision',
            'nowEpochMs',
            'runtimeEpochId',
            'senderFence',
            'strategyId',
            'userArmEvidenceHash',
        ]) ||
        input.activationPolicyAcknowledged !== true
    ) {
        throw new TypeError('strategy resume input is invalid');
    }
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const expectedRevision = safeInteger(input.expectedRevision, 'expectedRevision');
    const now = safeInteger(input.nowEpochMs, 'resume.nowEpochMs');
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const authorityId = boundedToken(input.authorityId, 'authorityId');
    const userArmEvidenceHash = sha256Digest(
        input.userArmEvidenceHash,
        'userArmEvidenceHash',
    );
    const contractEvidence =
        input.contractEvidence === null
            ? null
            : canonicalConfirmationContractEvidence(
                  input.contractEvidence,
              );
    const mutate = () => {
        if (
            !currentReadySenderMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error(
                'strategy resume requires current gate, readiness, confirmation and arm verification',
            );
        }
        const deniedBy = evaluateKillSwitchDenyUnion(
            currentKillSwitchArbiter(database),
            'automation_write',
        );
        if (deniedBy.length > 0) {
            throw new Error(
                'strategy resume requires current gate, readiness, confirmation and arm verification',
            );
        }
        const runtime = database
            .prepare(`
                SELECT reconciliation_evidence_hash
                  FROM runtime_epochs
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state='ready'
            `)
            .get(runtimeEpochId, senderFence, apiGeneration);
        if (!runtime?.reconciliation_evidence_hash) {
            throw new Error(
                'strategy resume requires current gate, readiness, confirmation and arm verification',
            );
        }
        const strategy = database
            .prepare('SELECT * FROM strategies WHERE strategy_id=?')
            .get(strategyId);
        if (!strategy || strategy.state !== 'paused') {
            throw new Error('strategy resume is not allowed');
        }
        if (strategy.revision !== expectedRevision) {
            throw new Error('strategy resume lost its optimistic revision');
        }
        const canonicalNow = canonicalConfirmationClockNowEpochMs(now);
        if (contractEvidence !== null) {
            const existingScope = database.prepare(`
                SELECT claims.account_broker_ref, claims.account_id_ref,
                       claims.contract_key
                  FROM existing_position_protection_heads AS heads
                  JOIN exit_claims AS claims
                    ON claims.exit_claim_id=heads.exit_claim_id
                  JOIN protection_groups AS groups
                    ON groups.exit_claim_id=heads.exit_claim_id
                  JOIN protection_remainder_generations AS generations
                    ON generations.protection_group_id=groups.protection_group_id
                   AND generations.remainder_generation=groups.current_generation
                 WHERE heads.strategy_id=? AND groups.state='rearm_required'
                   AND generations.state='rearm_required'
            `).get(strategyId);
            if (
                !existingScope ||
                contractEvidence.accountScopeSha256 !==
                    confirmationAccountScopeSha256(
                        existingScope.account_broker_ref,
                        existingScope.account_id_ref,
                    ) ||
                contractEvidence.contract.runtimeContractKey !==
                    existingScope.contract_key ||
                contractEvidence.runtimeEpochId !== runtimeEpochId ||
                contractEvidence.apiGeneration !== apiGeneration ||
                contractEvidence.observedAtEpochMs > canonicalNow ||
                contractEvidence.validUntilEpochMs <= canonicalNow
            ) {
                throw new Error(
                    'strategy protection re-arm contract evidence is not current or scope-bound',
                );
            }
            observeCanonicalContractHead(database, {
                accountBrokerRef: existingScope.account_broker_ref,
                accountIdRef: existingScope.account_id_ref,
                contractEvidence,
                nowEpochMs: canonicalNow,
            });
        }
        const existingPositionRemainder =
            currentExistingPositionProtectionArm(database, {
                apiGeneration,
                expectedGroupState: 'rearm_required',
                nowEpochMs: canonicalNow,
                runtimeEpochId,
                senderFence,
                strategyId,
            });
        if (
            existingPositionRemainder !== null &&
            contractEvidence === null
        ) {
            throw new Error(
                'existing-position protection remainder re-arm requires fresh contract evidence',
            );
        }
        if (existingPositionRemainder === null) {
            assertCanonicalConfirmationCurrent(database, {
                strategyId,
                snapshotHash: strategy.confirmation_snapshot_hash,
                runtimeEpochId,
                senderFence,
                apiGeneration,
                nowEpochMs: canonicalNow,
            });
        }
        let definition;
        try {
            definition = JSON.parse(strategy.definition_json);
        } catch {
            throw new Error('stored strategy definition is invalid');
        }
        const activationPolicy =
            definition?.activationPolicy ??
            definition?.parameters?.activationPolicy;
        if (
            !['require_rearm', 'immediate_if_true'].includes(
                activationPolicy,
            )
        ) {
            throw new Error('stored strategy activation policy is invalid');
        }
        const gate = currentEligibleManualGate(
            database,
            strategy.strategy_kind,
            now,
            'strategy resume',
        );
        const scopeHash = sha256Canonical(
            {
                activationPolicy,
                apiGeneration,
                confirmationSnapshotHash: strategy.confirmation_snapshot_hash,
                definitionHash: strategy.definition_hash,
                gateManifestSha256: gate.manifestSha256,
                reconciliationEvidenceHash: runtime.reconciliation_evidence_hash,
                protectionRemainder:
                    existingPositionRemainder === null
                        ? null
                        : {
                              exitClaimId:
                                  existingPositionRemainder.exit_claim_id,
                              formalProtectionHash:
                                  existingPositionRemainder.formalProtectionHash,
                              protectionGroupId:
                                  existingPositionRemainder.protection_group_id,
                              remainderGeneration:
                                  existingPositionRemainder.current_generation,
                              quantityShares:
                                  existingPositionRemainder.claim_quantity_shares,
                          },
                runtimeEpochId,
                senderFence,
                strategyId,
                strategyRevision: expectedRevision,
            },
            'strategy resume arm scope',
        );
        insertAuthorityConsumptionInTransaction(database, {
            authorityKind: 'strategy_resume_arm',
            authorityId,
            authorityPayloadHash: userArmEvidenceHash,
            scopeHash,
            consumedBy: strategyId,
            runtimeEpochId,
            consumedAtEpochMs: now,
        });
        if (existingPositionRemainder !== null) {
            const groupUpdate = database.prepare(`
                UPDATE protection_groups
                   SET state='monitoring', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE protection_group_id=? AND state='rearm_required'
                   AND current_generation=? AND revision=?
            `).run(
                now,
                existingPositionRemainder.protection_group_id,
                existingPositionRemainder.current_generation,
                existingPositionRemainder.group_revision,
            );
            const generationUpdate = database.prepare(`
                UPDATE protection_remainder_generations
                   SET state='monitoring', evidence_hash=?,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE protection_group_id=? AND remainder_generation=?
                   AND state='rearm_required' AND revision=?
            `).run(
                scopeHash,
                now,
                existingPositionRemainder.protection_group_id,
                existingPositionRemainder.current_generation,
                existingPositionRemainder.generation_revision,
            );
            if (
                Number(groupUpdate.changes) !== 1 ||
                Number(generationUpdate.changes) !== 1
            ) {
                throw new Error(
                    'existing-position protection remainder re-arm lost its CAS',
                );
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'protection_group',
                entityId: existingPositionRemainder.protection_group_id,
                revision: existingPositionRemainder.group_revision + 1,
                reasonCode: 'PROTECTION_OCO_REMAINDER_USER_REARMED',
                summaryCode: 'protection_oco_remainder_monitoring',
                nowEpochMs: now,
                payloadHash: scopeHash,
                eventSuffix:
                    `generation-${existingPositionRemainder.current_generation}-user-rearmed`,
            });
        }
        if (strategy.strategy_kind === 'quick') {
            database.prepare(`
                DELETE FROM quick_condition_heads WHERE strategy_id=?
            `).run(strategyId);
        }
        if (strategy.strategy_kind === 'multi_condition') {
            database.prepare(`
                DELETE FROM multi_condition_leg_heads WHERE strategy_id=?
            `).run(strategyId);
            database.prepare(`
                DELETE FROM multi_condition_group_heads WHERE strategy_id=?
            `).run(strategyId);
        }
        if (strategy.strategy_kind === 'parent_child') {
            database.prepare(`
                DELETE FROM parent_child_condition_heads WHERE strategy_id=?
            `).run(strategyId);
        }
        const result = database
            .prepare(`
                UPDATE strategies
                   SET state='monitoring', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE strategy_id=? AND state='paused' AND revision=?
            `)
            .run(now, strategyId, expectedRevision);
        if (Number(result.changes) !== 1) {
            throw new Error('strategy resume lost its optimistic revision');
        }
        const updated = database
            .prepare('SELECT * FROM strategies WHERE strategy_id=?')
            .get(strategyId);
        insertJournalEvent(
            database,
            {
                eventId: `strategy:${strategyId}:resumed:${expectedRevision + 1}`,
                entityKind: 'strategy',
                entityId: strategyId,
                reasonCode: 'STRATEGY_RESUMED_WITH_CURRENT_USER_ARM',
                receiveEpochMs: now,
                payloadHash: scopeHash,
                summaryCode: 'strategy_resumed_monitoring',
                createdAtEpochMs: now,
            },
            expectedRevision + 1,
        );
        return parseStrategyRow(updated, { database });
    };
    return withinExistingTransaction ? mutate() : transaction(database, mutate);
}

function requestBrokerOrderCancellation(
    database,
    input,
    withinExistingTransaction = false,
) {
    if (
        !exactKeys(input, [
            'apiGeneration',
            'authorityId',
            'expectedRevision',
            'nowEpochMs',
            'runtimeEpochId',
            'senderFence',
            'strategyId',
            'userConfirmationEvidenceHash',
        ])
    ) {
        throw new TypeError('broker order cancellation request is invalid');
    }
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const expectedRevision = safeInteger(input.expectedRevision, 'expectedRevision');
    const now = safeInteger(input.nowEpochMs, 'brokerCancel.nowEpochMs');
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const authorityId = boundedToken(input.authorityId, 'authorityId');
    const userEvidenceHash = sha256Digest(
        input.userConfirmationEvidenceHash,
        'userConfirmationEvidenceHash',
    );
    const mutate = () => {
        if (
            !currentReadySenderMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error(
                'broker order cancellation requires current gate, readiness and user confirmation',
            );
        }
        const deniedBy = evaluateKillSwitchDenyUnion(
            currentKillSwitchArbiter(database),
            'explicit_manual_cancel',
        );
        if (deniedBy.length > 0) {
            throw new Error(
                'broker order cancellation requires current gate, readiness and user confirmation',
            );
        }
        const runtime = database
            .prepare(`
                SELECT reconciliation_evidence_hash
                  FROM runtime_epochs
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state='ready'
            `)
            .get(runtimeEpochId, senderFence, apiGeneration);
        const strategy = database
            .prepare('SELECT * FROM strategies WHERE strategy_id=?')
            .get(strategyId);
        if (
            !runtime?.reconciliation_evidence_hash ||
            !strategy ||
            STRATEGY_TERMINAL_STATES.has(strategy.state) ||
            strategy.state === 'draft'
        ) {
            throw new Error(
                'broker order cancellation requires current gate, readiness and user confirmation',
            );
        }
        if (strategy.revision !== expectedRevision) {
            throw new Error(
                'broker order cancellation lost its optimistic revision',
            );
        }
        const gate = currentEligibleManualGate(
            database,
            strategy.strategy_kind,
            now,
            'broker order cancellation',
            false,
        );
        const targets = database
            .prepare(`
                SELECT orders.broker_order_id, orders.state,
                       orders.control_revision, orders.quantity_shares,
                       orders.filled_shares, orders.remaining_shares,
                       orders.evidence_hash AS broker_order_evidence_hash,
                       orders.revision AS broker_order_revision,
                       intents.intent_id AS target_intent_id,
                       intents.account_broker_ref, intents.account_id_ref,
                       intents.trade_date, intents.contract_key, intents.side,
                       intents.risk_revision
                  FROM broker_orders AS orders
                  JOIN order_intents AS intents
                    ON intents.intent_id=orders.intent_id
                 WHERE intents.strategy_id=?
                   AND orders.state IN ('pre_submitted','submitted','part_filled')
                   AND orders.remaining_shares > 0
                 ORDER BY orders.broker_order_id
            `)
            .all(strategyId);
        if (targets.length !== 1) {
            throw new Error(
                'broker order cancellation requires one exact working order',
            );
        }
        const target = targets[0];
        if (
            !target.risk_revision ||
            target.filled_shares + target.remaining_shares !==
                target.quantity_shares
        ) {
            throw new Error(
                'broker order cancellation target is not current and canonical',
            );
        }
        const correlations = database
            .prepare(`
                SELECT correlation_id, canonical_key_hash, evidence_hash,
                       revision, intent_id, broker_order_id,
                       account_broker_ref, account_id_ref, trade_date,
                       contract_key, side
                  FROM broker_correlations
                 WHERE intent_id=? AND broker_order_id=?
                 ORDER BY correlation_id
            `)
            .all(target.target_intent_id, target.broker_order_id);
        if (
            correlations.length !== 1 ||
            correlations.some(
                (correlation) =>
                    correlation.intent_id !== target.target_intent_id ||
                    correlation.broker_order_id !== target.broker_order_id ||
                    correlation.account_broker_ref !==
                        target.account_broker_ref ||
                    correlation.account_id_ref !== target.account_id_ref ||
                    correlation.trade_date !== target.trade_date ||
                    correlation.contract_key !== target.contract_key ||
                    correlation.side !== target.side,
            )
        ) {
            throw new Error(
                'broker order cancellation requires exact durable correlation',
            );
        }
        const existingControl = database
            .prepare(`
                SELECT intent_id
                  FROM order_intents
                 WHERE operation_kind IN ('update','cancel')
                   AND owner_kind='manual_request'
                   AND target_broker_order_id=?
                   AND target_control_revision=?
                   AND state NOT IN ('terminal','cancelled_proven_unsent')
                 LIMIT 1
            `)
            .get(target.broker_order_id, target.control_revision);
        if (existingControl) {
            throw new Error(
                'broker order control already has a live intent',
            );
        }
        const payload = Object.freeze({
            brokerOrderId: target.broker_order_id,
            controlRevision: target.control_revision,
            schemaVersion: MANUAL_CANCEL_BROKER_INTENT_SCHEMA_VERSION,
        });
        const payloadJson = canonicalJson(payload, 'manual broker cancel payload');
        const payloadHash = `sha256:${createHash('sha256')
            .update(payloadJson)
            .digest('hex')}`;
        const activationId = `manual-cancel-activation:${authorityId}`;
        const intentId = `manual-cancel-intent:${authorityId}`;
        const rearmAuthorizationId = `manual-cancel-rearm:${authorityId}`;
        const scopeHash = sha256Canonical(
            {
                apiGeneration,
                brokerOrder: {
                    brokerOrderId: target.broker_order_id,
                    controlRevision: target.control_revision,
                    evidenceHash: target.broker_order_evidence_hash,
                    revision: target.broker_order_revision,
                    state: target.state,
                },
                correlations: correlations.map((correlation) => ({
                    canonicalKeyHash: correlation.canonical_key_hash,
                    correlationId: correlation.correlation_id,
                    evidenceHash: correlation.evidence_hash,
                    revision: correlation.revision,
                })),
                confirmationSnapshotHash: strategy.confirmation_snapshot_hash,
                gateManifestSha256: gate.manifestSha256,
                reconciliationEvidenceHash: runtime.reconciliation_evidence_hash,
                runtimeEpochId,
                senderFence,
                strategyId,
                strategyRevision: expectedRevision,
            },
            'manual broker cancel request scope',
        );
        insertAuthorityConsumptionInTransaction(database, {
            authorityKind: 'broker_order_cancel_request',
            authorityId,
            authorityPayloadHash: userEvidenceHash,
            scopeHash,
            consumedBy: strategyId,
            runtimeEpochId,
            consumedAtEpochMs: now,
        });
        database
            .prepare(`
                INSERT INTO activations(
                    activation_id, strategy_id, logical_key, state, generation,
                    evidence_hash, created_at_epoch_ms, updated_at_epoch_ms,
                    revision
                ) VALUES (?, ?, ?, 'prepared', 0, ?, ?, ?, 0)
            `)
            .run(
                activationId,
                strategyId,
                `manual-cancel:${target.broker_order_id}:${target.control_revision}`,
                userEvidenceHash,
                now,
                now,
            );
        database
            .prepare(`
                INSERT INTO order_intents(
                    intent_id, activation_id, strategy_id, operation_kind,
                    owner_kind, state, payload_hash, payload_json,
                    client_request_id, account_broker_ref, account_id_ref,
                    trade_date, contract_key, side, target_broker_order_id,
                    target_control_revision, created_at_epoch_ms,
                    updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, 'cancel', 'manual_request', 'prepared',
                          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
            `)
            .run(
                intentId,
                activationId,
                strategyId,
                payloadHash,
                payloadJson,
                authorityId,
                target.account_broker_ref,
                target.account_id_ref,
                target.trade_date,
                target.contract_key,
                target.side,
                target.broker_order_id,
                target.control_revision,
                now,
                now,
            );
        database
            .prepare(`
                INSERT INTO intent_rearm_authorizations(
                    rearm_authorization_id, intent_id, runtime_epoch_id,
                    sender_fence, api_generation, rearm_request_id,
                    authorized_intent_revision, confirmation_snapshot_hash,
                    risk_revision, reconciliation_evidence_hash,
                    user_rearm_evidence_hash, state, authorized_at_epoch_ms,
                    revision
                ) VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, 'active', ?, 0)
            `)
            .run(
                rearmAuthorizationId,
                intentId,
                runtimeEpochId,
                senderFence,
                apiGeneration,
                authorityId,
                strategy.confirmation_snapshot_hash,
                target.risk_revision,
                runtime.reconciliation_evidence_hash,
                userEvidenceHash,
                now,
            );
        insertTransitionJournalEvent(database, {
            entityKind: 'activation',
            entityId: activationId,
            revision: 0,
            reasonCode: 'ACTIVATION_PREPARED_WITH_INTENT',
            summaryCode: 'manual_cancel_activation_prepared',
            nowEpochMs: now,
            payloadHash: userEvidenceHash,
            eventSuffix: 'manual-cancel-prepared',
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: intentId,
            revision: 0,
            reasonCode: 'ORDER_INTENT_PREPARED_DURABLY',
            summaryCode: 'manual_cancel_intent_prepared',
            nowEpochMs: now,
            payloadHash,
            eventSuffix: 'manual-cancel-prepared',
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: intentId,
            revision: 1,
            reasonCode: 'PREPARED_INTENT_USER_REARM_AUTHORIZED',
            summaryCode: 'manual_cancel_intent_user_confirmed',
            nowEpochMs: now,
            payloadHash: userEvidenceHash,
            eventSuffix: 'manual-cancel-rearmed',
        });
        return Object.freeze({
            brokerAuthorityGranted: false,
            brokerWriteAttempted: false,
            cancelIntentState: 'prepared',
            dispatchAllowed: false,
            replayed: false,
            strategyId,
            strategyRevision: expectedRevision,
            targetState: target.state,
            userConfirmationConsumed: true,
        });
    };
    return withinExistingTransaction ? mutate() : transaction(database, mutate);
}

function requestBrokerOrderQuantityReduction(
    database,
    input,
    withinExistingTransaction = false,
) {
    if (
        !exactKeys(input, [
            'apiGeneration',
            'authorityId',
            'expectedRevision',
            'nowEpochMs',
            'quantityShares',
            'runtimeEpochId',
            'senderFence',
            'strategyId',
            'userConfirmationEvidenceHash',
        ])
    ) {
        throw new TypeError('broker order quantity reduction request is invalid');
    }
    const strategyId = boundedToken(input.strategyId, 'strategyId');
    const expectedRevision = safeInteger(input.expectedRevision, 'expectedRevision');
    const quantityShares = safeInteger(
        input.quantityShares,
        'brokerUpdate.quantityShares',
    );
    if (quantityShares < 1) {
        throw new TypeError('broker update quantityShares must be positive');
    }
    const now = safeInteger(input.nowEpochMs, 'brokerUpdate.nowEpochMs');
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const authorityId = boundedToken(input.authorityId, 'authorityId');
    const userEvidenceHash = sha256Digest(
        input.userConfirmationEvidenceHash,
        'userConfirmationEvidenceHash',
    );
    const mutate = () => {
        if (
            !currentReadySenderMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error(
                'broker order quantity reduction requires current gate, readiness and user confirmation',
            );
        }
        const deniedBy = evaluateKillSwitchDenyUnion(
            currentKillSwitchArbiter(database),
            'unclassified_write',
        );
        if (deniedBy.length > 0) {
            throw new Error(
                'broker order quantity reduction requires current gate, readiness and user confirmation',
            );
        }
        const runtime = database
            .prepare(`
                SELECT reconciliation_evidence_hash
                  FROM runtime_epochs
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state='ready'
            `)
            .get(runtimeEpochId, senderFence, apiGeneration);
        const strategy = database
            .prepare('SELECT * FROM strategies WHERE strategy_id=?')
            .get(strategyId);
        if (
            !runtime?.reconciliation_evidence_hash ||
            !strategy ||
            !['observing', 'monitoring', 'recovery'].includes(strategy.state)
        ) {
            throw new Error(
                'broker order quantity reduction requires an active current strategy',
            );
        }
        if (strategy.revision !== expectedRevision) {
            throw new Error(
                'broker order quantity reduction lost its optimistic revision',
            );
        }
        const gate = currentEligibleManualGate(
            database,
            strategy.strategy_kind,
            now,
            'broker order quantity reduction',
            false,
        );
        const targets = database
            .prepare(`
                SELECT orders.broker_order_id, orders.state,
                       orders.control_revision, orders.quantity_shares,
                       orders.filled_shares, orders.remaining_shares,
                       orders.evidence_hash AS broker_order_evidence_hash,
                       orders.revision AS broker_order_revision,
                       intents.intent_id AS target_intent_id,
                       intents.account_broker_ref, intents.account_id_ref,
                       intents.trade_date, intents.contract_key, intents.side,
                       intents.risk_revision
                  FROM broker_orders AS orders
                  JOIN order_intents AS intents
                    ON intents.intent_id=orders.intent_id
                 WHERE intents.strategy_id=?
                   AND orders.state IN ('pre_submitted','submitted','part_filled')
                   AND orders.remaining_shares > 0
                 ORDER BY orders.broker_order_id
            `)
            .all(strategyId);
        if (targets.length !== 1) {
            throw new Error(
                'broker order quantity reduction requires one exact working order',
            );
        }
        const target = targets[0];
        if (
            !target.risk_revision ||
            target.filled_shares + target.remaining_shares !==
                target.quantity_shares
        ) {
            throw new Error(
                'broker order quantity reduction target is not current and canonical',
            );
        }
        const correlations = database
            .prepare(`
                SELECT correlation_id, canonical_key_hash, evidence_hash,
                       revision, intent_id, broker_order_id,
                       account_broker_ref, account_id_ref, trade_date,
                       contract_key, side
                  FROM broker_correlations
                 WHERE intent_id=? AND broker_order_id=?
                 ORDER BY correlation_id
            `)
            .all(target.target_intent_id, target.broker_order_id);
        if (
            correlations.length !== 1 ||
            correlations.some(
                (correlation) =>
                    correlation.intent_id !== target.target_intent_id ||
                    correlation.broker_order_id !== target.broker_order_id ||
                    correlation.account_broker_ref !== target.account_broker_ref ||
                    correlation.account_id_ref !== target.account_id_ref ||
                    correlation.trade_date !== target.trade_date ||
                    correlation.contract_key !== target.contract_key ||
                    correlation.side !== target.side,
            )
        ) {
            throw new Error(
                'broker order quantity reduction requires exact durable correlation',
            );
        }
        const adapterTarget = currentDispatchAdapterTarget(database, {
            operation_kind: 'update',
            target_broker_order_id: target.broker_order_id,
            target_control_revision: target.control_revision,
            account_broker_ref: target.account_broker_ref,
            account_id_ref: target.account_id_ref,
            trade_date: target.trade_date,
            contract_key: target.contract_key,
            side: target.side,
        });
        if (
            !adapterTarget ||
            quantityShares >= target.quantity_shares ||
            quantityShares <= target.filled_shares ||
            quantityShares % adapterTarget.contractUnit !== 0
        ) {
            throw new Error(
                'broker order quantity reduction must be an exact safe reduction above the filled quantity',
            );
        }
        const existingControl = database
            .prepare(`
                SELECT intent_id
                  FROM order_intents
                 WHERE operation_kind IN ('update','cancel')
                   AND owner_kind='manual_request'
                   AND target_broker_order_id=?
                   AND target_control_revision=?
                   AND state NOT IN ('terminal','cancelled_proven_unsent')
                 LIMIT 1
            `)
            .get(target.broker_order_id, target.control_revision);
        if (existingControl) {
            throw new Error('broker order control already has a live intent');
        }
        const payload = Object.freeze({
            quantityShares,
            schemaVersion: MANUAL_UPDATE_BROKER_QUANTITY_INTENT_SCHEMA_VERSION,
        });
        const payloadJson = canonicalJson(
            payload,
            'manual broker quantity update payload',
        );
        const payloadHash = `sha256:${createHash('sha256')
            .update(payloadJson)
            .digest('hex')}`;
        const activationId = `manual-update-activation:${authorityId}`;
        const intentId = `manual-update-intent:${authorityId}`;
        const rearmAuthorizationId = `manual-update-rearm:${authorityId}`;
        const scopeHash = sha256Canonical(
            {
                apiGeneration,
                brokerOrder: {
                    brokerOrderId: target.broker_order_id,
                    controlRevision: target.control_revision,
                    evidenceHash: target.broker_order_evidence_hash,
                    revision: target.broker_order_revision,
                    state: target.state,
                },
                correlations: correlations.map((correlation) => ({
                    canonicalKeyHash: correlation.canonical_key_hash,
                    correlationId: correlation.correlation_id,
                    evidenceHash: correlation.evidence_hash,
                    revision: correlation.revision,
                })),
                confirmationSnapshotHash: strategy.confirmation_snapshot_hash,
                gateManifestSha256: gate.manifestSha256,
                quantityShares,
                reconciliationEvidenceHash: runtime.reconciliation_evidence_hash,
                runtimeEpochId,
                senderFence,
                strategyId,
                strategyRevision: expectedRevision,
                targetRevision: adapterTarget.targetRevision,
            },
            'manual broker quantity update request scope',
        );
        insertAuthorityConsumptionInTransaction(database, {
            authorityKind: 'broker_order_quantity_update_request',
            authorityId,
            authorityPayloadHash: userEvidenceHash,
            scopeHash,
            consumedBy: strategyId,
            runtimeEpochId,
            consumedAtEpochMs: now,
        });
        database
            .prepare(`
                INSERT INTO activations(
                    activation_id, strategy_id, logical_key, state, generation,
                    evidence_hash, created_at_epoch_ms, updated_at_epoch_ms,
                    revision
                ) VALUES (?, ?, ?, 'prepared', 0, ?, ?, ?, 0)
            `)
            .run(
                activationId,
                strategyId,
                `manual-update:${target.broker_order_id}:${target.control_revision}`,
                userEvidenceHash,
                now,
                now,
            );
        database
            .prepare(`
                INSERT INTO order_intents(
                    intent_id, activation_id, strategy_id, operation_kind,
                    owner_kind, state, payload_hash, payload_json,
                    client_request_id, account_broker_ref, account_id_ref,
                    trade_date, contract_key, side, target_broker_order_id,
                    target_control_revision, created_at_epoch_ms,
                    updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, 'update', 'manual_request', 'prepared',
                          ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
            `)
            .run(
                intentId,
                activationId,
                strategyId,
                payloadHash,
                payloadJson,
                authorityId,
                target.account_broker_ref,
                target.account_id_ref,
                target.trade_date,
                target.contract_key,
                target.side,
                target.broker_order_id,
                target.control_revision,
                now,
                now,
            );
        database
            .prepare(`
                INSERT INTO intent_rearm_authorizations(
                    rearm_authorization_id, intent_id, runtime_epoch_id,
                    sender_fence, api_generation, rearm_request_id,
                    authorized_intent_revision, confirmation_snapshot_hash,
                    risk_revision, reconciliation_evidence_hash,
                    user_rearm_evidence_hash, state, authorized_at_epoch_ms,
                    revision
                ) VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, 'active', ?, 0)
            `)
            .run(
                rearmAuthorizationId,
                intentId,
                runtimeEpochId,
                senderFence,
                apiGeneration,
                authorityId,
                strategy.confirmation_snapshot_hash,
                target.risk_revision,
                runtime.reconciliation_evidence_hash,
                userEvidenceHash,
                now,
            );
        insertTransitionJournalEvent(database, {
            entityKind: 'activation',
            entityId: activationId,
            revision: 0,
            reasonCode: 'ACTIVATION_PREPARED_WITH_INTENT',
            summaryCode: 'manual_update_activation_prepared',
            nowEpochMs: now,
            payloadHash: userEvidenceHash,
            eventSuffix: 'manual-update-prepared',
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: intentId,
            revision: 0,
            reasonCode: 'ORDER_INTENT_PREPARED_DURABLY',
            summaryCode: 'manual_update_intent_prepared',
            nowEpochMs: now,
            payloadHash,
            eventSuffix: 'manual-update-prepared',
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: intentId,
            revision: 1,
            reasonCode: 'PREPARED_INTENT_USER_REARM_AUTHORIZED',
            summaryCode: 'manual_update_intent_user_confirmed',
            nowEpochMs: now,
            payloadHash: userEvidenceHash,
            eventSuffix: 'manual-update-rearmed',
        });
        return Object.freeze({
            brokerAuthorityGranted: false,
            brokerWriteAttempted: false,
            dispatchAllowed: false,
            quantityShares,
            replayed: false,
            strategyId,
            strategyRevision: expectedRevision,
            targetState: target.state,
            updateIntentState: 'prepared',
            userConfirmationConsumed: true,
        });
    };
    return withinExistingTransaction ? mutate() : transaction(database, mutate);
}

function addExposureInteger(left, right, label) {
    const result = left + right;
    if (!Number.isSafeInteger(result) || result < 0) {
        throw new Error(`${label} exceeds the safe integer range`);
    }
    return result;
}

function parseExposureHeadDimensions(head, label) {
    let parsed;
    try {
        parsed = JSON.parse(head.reserved_dimensions_json);
    } catch {
        throw new Error(`${label} reserved dimensions are invalid`);
    }
    const dimensions = canonicalExposureDimensions(parsed, `${label}.reservedDimensions`);
    if (JSON.stringify(dimensions) !== head.reserved_dimensions_json) {
        throw new Error(`${label} reserved dimensions are not canonical`);
    }
    return dimensions;
}

function assertExposureHeadPair(accountHead, identityHead, strategy) {
    if (!accountHead || !identityHead) {
        throw new Error('current account and identity exposure heads are required');
    }
    if (
        accountHead.identity_group_id !== strategy.identity_group_id ||
        identityHead.identity_group_id !== strategy.identity_group_id
    ) {
        throw new Error('exposure heads do not match the strategy identity group');
    }
    // Account and identity heads are projections at different aggregation
    // layers. Their source revisions/evidence are therefore intentionally
    // distinct; the canonical PnL decision above binds both layers to the
    // same current Runtime watermark. Only policy/dimension identity must be
    // byte-identical here, while each head is checked independently for
    // freshness.
    for (const column of [
        'policy_revision',
        'policy_hash',
        'reserved_dimensions_json',
    ]) {
        if (accountHead[column] !== identityHead[column]) {
            throw new Error(`account and identity exposure heads disagree on ${column}`);
        }
    }
    const trustedNowEpochMs = exposureClockNowEpochMs();
    if (
        accountHead.observed_at_epoch_ms > trustedNowEpochMs ||
        accountHead.valid_until_epoch_ms <= trustedNowEpochMs ||
        identityHead.observed_at_epoch_ms > trustedNowEpochMs ||
        identityHead.valid_until_epoch_ms <= trustedNowEpochMs
    ) {
        throw new Error('current exposure head is future-dated or expired');
    }
}

function aggregateActiveExposure(database, whereSql, parameters) {
    return database.prepare(`
        SELECT COALESCE(SUM(quantity_shares), 0) AS quantity_shares,
               COALESCE(SUM(notional_minor_units), 0) AS notional_minor_units,
               COALESCE(SUM(cash_minor_units), 0) AS cash_minor_units,
               COALESCE(SUM(position_shares), 0) AS position_shares,
               COALESCE(SUM(order_count), 0) AS order_count
          FROM entry_exposure_reservations
         WHERE state NOT IN ('consumed', 'released') AND ${whereSql}
    `).get(...parameters);
}

function assertExposureLimit(head, aggregate, reservation, dimensions, scopeLabel) {
    for (const dimension of dimensions) {
        const columns = EXPOSURE_DIMENSION_COLUMNS[dimension];
        const projected = addExposureInteger(
            addExposureInteger(
                safeInteger(head[columns.baseline], `${scopeLabel}.${columns.baseline}`),
                safeInteger(aggregate[columns.reservation], `${scopeLabel}.${columns.reservation}`),
                `${scopeLabel}.${dimension}`,
            ),
            safeInteger(reservation[dimension], `reservation.${dimension}`),
            `${scopeLabel}.${dimension}`,
        );
        const limit = safeInteger(head[columns.limit], `${scopeLabel}.${columns.limit}`);
        if (projected > limit) {
            throw new Error(`${scopeLabel} exposure limit exceeded: ${dimension}`);
        }
    }
}

function currentExternalSellVisibility(database, scope, requiredIntentId = null) {
    const head = database.prepare(`
        SELECT * FROM external_sell_visibility_heads
         WHERE account_broker_ref=? AND account_id_ref=?
           AND trade_date=? AND contract_key=?
    `).get(
        scope.account_broker_ref,
        scope.account_id_ref,
        scope.trade_date,
        scope.contract_key,
    );
    if (!head || head.collection_complete !== 1) {
        throw externalSellVisibilityError(
            'complete current external working-sell visibility is required',
        );
    }
    const trustedNowEpochMs = exposureClockNowEpochMs();
    if (
        head.observed_at_epoch_ms > trustedNowEpochMs ||
        head.valid_until_epoch_ms <= trustedNowEpochMs ||
        head.valid_until_epoch_ms - head.observed_at_epoch_ms > 5_000
    ) {
        throw externalSellVisibilityError(
            'external working-sell visibility is future-dated or expired',
        );
    }
    const externalRows = database.prepare(`
        SELECT claims.exit_claim_id, claims.position_lineage_id,
               claims.remainder_generation, claims.allocation_start_share,
               claims.quantity_shares, claims.state, claims.evidence_hash,
               bindings.source_revision, bindings.source_sequence,
               bindings.source_evidence_hash,
               bindings.position_revision, bindings.position_shares,
               bindings.working_set_hash, bindings.binding_kind,
               bindings.visibility_head_revision
          FROM exit_claims AS claims
     LEFT JOIN exit_claim_visibility_bindings AS bindings
            ON bindings.exit_claim_id=claims.exit_claim_id
         WHERE claims.external_lineage=1
           AND claims.account_broker_ref=? AND claims.account_id_ref=?
           AND claims.contract_key=?
           AND claims.state IN ('broker_working','unknown')
         ORDER BY claims.exit_claim_id
    `).all(scope.account_broker_ref, scope.account_id_ref, scope.contract_key);
    for (const row of externalRows) {
        if (
            row.binding_kind !== 'external_projection' ||
            row.source_revision !== head.source_revision ||
            row.source_sequence !== head.source_sequence ||
            row.source_evidence_hash !== head.source_evidence_hash ||
            row.position_revision !== head.position_revision ||
            row.position_shares !== head.position_shares ||
            row.working_set_hash !== head.working_set_hash ||
            row.visibility_head_revision !== head.revision
        ) {
            throw externalSellVisibilityError(
                'external working sell lacks the exact current complete-set binding',
            );
        }
        if (row.state === 'unknown') {
            throw externalSellVisibilityError(
                'unknown external working sell cannot prove reduce-only capacity',
            );
        }
    }
    const projected = canonicalExternalWorkingSet(
        externalRows.map((row) => ({
            allocationStartShare: row.allocation_start_share,
            evidenceHash: row.evidence_hash,
            exitClaimId: row.exit_claim_id,
            positionLineageId: row.position_lineage_id,
            quantityShares: row.quantity_shares,
            remainderGeneration: row.remainder_generation,
            state: row.state,
        })),
        'durable external working sell projection',
    );
    if (projected.workingSetHash !== head.working_set_hash) {
        throw externalSellVisibilityError(
            'external working-sell set hash integrity failed',
        );
    }
    const activeClaims = database.prepare(`
        SELECT exit_claim_id, position_lineage_id, remainder_generation,
               allocation_start_share, state, quantity_shares
          FROM exit_claims
         WHERE account_broker_ref=? AND account_id_ref=? AND contract_key=?
           AND state IN ('monitoring_reserved','intent_reserved',
                         'broker_working','unknown')
         ORDER BY exit_claim_id
    `).all(scope.account_broker_ref, scope.account_id_ref, scope.contract_key);
    if (activeClaims.some((claim) => claim.state === 'unknown')) {
        throw externalSellVisibilityError(
            'unknown ExitClaim blocks reduce-only classification',
        );
    }
    const intervalsByLineage = new Map();
    for (const claim of activeClaims) {
        const key = `${claim.position_lineage_id}\u0000${claim.remainder_generation}`;
        const interval = {
            exitClaimId: claim.exit_claim_id,
            start: safeInteger(
                claim.allocation_start_share,
                'active ExitClaim allocationStartShare',
            ),
            end: addExposureInteger(
                safeInteger(
                    claim.allocation_start_share,
                    'active ExitClaim allocationStartShare',
                ),
                safeInteger(
                    claim.quantity_shares,
                    'active ExitClaim quantityShares',
                ),
                'active ExitClaim allocation interval',
            ),
        };
        const intervals = intervalsByLineage.get(key) ?? [];
        intervals.push(interval);
        intervalsByLineage.set(key, intervals);
    }
    for (const intervals of intervalsByLineage.values()) {
        intervals.sort((left, right) =>
            left.start - right.start ||
            left.exitClaimId.localeCompare(right.exitClaimId),
        );
        for (let index = 1; index < intervals.length; index += 1) {
            if (intervals[index].start < intervals[index - 1].end) {
                throw externalSellVisibilityError(
                    'active ExitClaim allocation intervals overlap',
                );
            }
        }
    }
    const claimedShares = activeClaims.reduce(
        (total, claim) =>
            addExposureInteger(
                total,
                safeInteger(claim.quantity_shares, 'active ExitClaim quantityShares'),
                'active ExitClaim aggregate',
            ),
        0,
    );
    if (claimedShares > head.position_shares) {
        throw externalSellVisibilityError(
            'distinct active ExitClaims exceed the confirmed long position',
        );
    }
    let internalBinding = null;
    if (requiredIntentId !== null) {
        internalBinding = database.prepare(`
            SELECT bindings.*, claims.exit_claim_id, claims.revision AS claim_revision
              FROM exit_claims AS claims
              JOIN exit_claim_visibility_bindings AS bindings
                ON bindings.exit_claim_id=claims.exit_claim_id
             WHERE claims.intent_id=? AND claims.external_lineage=0
               AND claims.state='intent_reserved'
        `).get(requiredIntentId);
        if (
            !internalBinding ||
            internalBinding.binding_kind !== 'internal_prepared' ||
            internalBinding.account_broker_ref !== scope.account_broker_ref ||
            internalBinding.account_id_ref !== scope.account_id_ref ||
            internalBinding.trade_date !== scope.trade_date ||
            internalBinding.contract_key !== scope.contract_key ||
            internalBinding.source_revision !== head.source_revision ||
            internalBinding.source_sequence !== head.source_sequence ||
            internalBinding.source_evidence_hash !== head.source_evidence_hash ||
            internalBinding.position_revision !== head.position_revision ||
            internalBinding.position_shares !== head.position_shares ||
            internalBinding.working_set_hash !== head.working_set_hash ||
            internalBinding.visibility_head_revision !== head.revision
        ) {
            throw externalSellVisibilityError(
                'Sell intent external visibility binding is stale or missing',
            );
        }
    }
    return Object.freeze({
        claimedShares,
        head,
        internalBinding,
    });
}

function externalSellVisibilityError(message) {
    const error = new Error(message);
    error.name = 'ExternalSellVisibilityError';
    return error;
}

function isExternalSellVisibilityError(error) {
    return error?.name === 'ExternalSellVisibilityError';
}

function authorizeEntryExposureReservation(
    database,
    input,
    strategy,
    now,
    protectedEntryPlan,
) {
    const isExposureIncreasing =
        input.intent.operationKind === 'place' && input.intent.side === 'Buy';
    if (!isExposureIncreasing) {
        if (input.reservation) {
            throw new Error('entry exposure reservation requires a Buy place intent');
        }
        if (
            input.intent.operationKind === 'place' &&
            input.intent.side === 'Sell' &&
            !input.exitClaim
        ) {
            throw new Error(
                'Sell place intent requires an exact current ExitClaim reservation',
            );
        }
        if (input.intent.operationKind === 'place' && input.intent.side === 'Sell') {
            return currentExternalSellVisibility(database, {
                account_broker_ref: input.intent.accountBrokerRef,
                account_id_ref: input.intent.accountIdRef,
                trade_date: taipeiTradeDate(input.intent.tradeDate),
                contract_key: boundedToken(
                    input.intent.contractKey,
                    'intent.contractKey',
                ),
            });
        }
        return undefined;
    }
    canonicalPnlDecisionForExposure(database, {
        accountBrokerRef: input.intent.accountBrokerRef,
        accountIdRef: input.intent.accountIdRef,
        identityGroupId: strategy.identity_group_id,
        tradeDate: taipeiTradeDate(input.intent.tradeDate),
        runtimeEpochId: input.runtimeEpochId,
        apiGeneration: input.apiGeneration,
    });
    const accountHead = database.prepare(`
        SELECT * FROM exposure_account_arbiter_heads
         WHERE account_broker_ref=? AND account_id_ref=?
    `).get(input.intent.accountBrokerRef, input.intent.accountIdRef);
    const identityHead = database.prepare(`
        SELECT * FROM exposure_identity_arbiter_heads WHERE identity_group_id=?
    `).get(strategy.identity_group_id);
    assertExposureHeadPair(accountHead, identityHead, strategy);
    const accountDimensions = parseExposureHeadDimensions(accountHead, 'account exposure head');
    const identityDimensions = parseExposureHeadDimensions(identityHead, 'identity exposure head');
    if (JSON.stringify(accountDimensions) !== JSON.stringify(identityDimensions)) {
        throw new Error('account and identity exposure dimensions disagree');
    }
    if (accountDimensions.length === 0) {
        if (input.reservation) {
            throw new Error('current exposure policy does not reserve any dimension');
        }
        return undefined;
    }
    if (!input.reservation) {
        throw new Error('exposure-increasing intent requires an atomic reservation');
    }
    const reservation = input.reservation;
    if (protectedEntryPlan) {
        if (
            protectedEntryPlan.riskPolicyHash !== accountHead.policy_hash ||
            protectedEntryPlan.riskPolicyHash !== identityHead.policy_hash
        ) {
            throw new Error(
                'protected entry worst-case projection is not bound to the current risk policy',
            );
        }
        for (const dimension of EXPOSURE_DIMENSIONS) {
            if (
                reservation[dimension] !==
                protectedEntryPlan.worstCaseExposure[dimension]
            ) {
                throw new Error(
                    `protected entry ${dimension} is below or differs from its canonical worst case`,
                );
            }
        }
    }
    if (
        reservation.accountBrokerRef !== input.intent.accountBrokerRef ||
        reservation.accountIdRef !== input.intent.accountIdRef ||
        reservation.accountBrokerRef !== strategy.account_broker_ref ||
        reservation.accountIdRef !== strategy.account_id_ref ||
        reservation.identityGroupId !== strategy.identity_group_id
    ) {
        throw new Error('reservation scope must match strategy and intent');
    }
    if (
        reservation.policyRevision !== accountHead.policy_revision ||
        reservation.policyHash !== accountHead.policy_hash
    ) {
        throw new Error('reservation policy is not the current exposure policy');
    }
    const accountAggregate = aggregateActiveExposure(
        database,
        'account_broker_ref=? AND account_id_ref=?',
        [input.intent.accountBrokerRef, input.intent.accountIdRef],
    );
    const identityAggregate = aggregateActiveExposure(
        database,
        'identity_group_id=?',
        [strategy.identity_group_id],
    );
    assertExposureLimit(
        accountHead,
        accountAggregate,
        reservation,
        accountDimensions,
        'account',
    );
    assertExposureLimit(
        identityHead,
        identityAggregate,
        reservation,
        identityDimensions,
        'identity',
    );
    const accountUpdated = database.prepare(`
        UPDATE exposure_account_arbiter_heads
           SET revision=revision+1, updated_at_epoch_ms=?
         WHERE account_broker_ref=? AND account_id_ref=? AND revision=?
    `).run(
        now,
        input.intent.accountBrokerRef,
        input.intent.accountIdRef,
        accountHead.revision,
    );
    const identityUpdated = database.prepare(`
        UPDATE exposure_identity_arbiter_heads
           SET revision=revision+1, updated_at_epoch_ms=?
         WHERE identity_group_id=? AND revision=?
    `).run(now, strategy.identity_group_id, identityHead.revision);
    if (accountUpdated.changes !== 1 || identityUpdated.changes !== 1) {
        throw new Error('exposure arbiter revision changed concurrently');
    }
    return undefined;
}

function currentDispatchExposureDecision(database, companion, reservation) {
    if (companion.operation_kind === 'place' && companion.side === 'Sell') {
        const visibility = currentExternalSellVisibility(
            database,
            companion,
            companion.intent_id,
        );
        return sha256Canonical(
            {
                claimId: visibility.internalBinding.exit_claim_id,
                claimRevision: visibility.internalBinding.claim_revision,
                claimedShares: visibility.claimedShares,
                positionRevision: visibility.head.position_revision,
                positionShares: visibility.head.position_shares,
                sourceEvidenceHash: visibility.head.source_evidence_hash,
                sourceSequence: visibility.head.source_sequence,
                visibilityRevision: visibility.head.revision,
                workingSetHash: visibility.head.working_set_hash,
            },
            'dispatch reduce-only decision',
        );
    }
    if (companion.operation_kind !== 'place' || companion.side !== 'Buy') {
        return sha256Canonical(
            { classification: 'no_new_exposure' },
            'dispatch exposure decision',
        );
    }
    if (!reservation) {
        throw new Error('Buy dispatch requires its durable exposure reservation');
    }
    const strategy = database.prepare(`
        SELECT account_broker_ref, account_id_ref, identity_group_id
          FROM strategies WHERE strategy_id=?
    `).get(companion.strategy_id);
    const canonicalPnlDecisionHash = canonicalPnlDecisionForExposure(
        database,
        {
            accountBrokerRef: companion.account_broker_ref,
            accountIdRef: companion.account_id_ref,
            identityGroupId: strategy?.identity_group_id,
            tradeDate: taipeiTradeDate(companion.trade_date),
            runtimeEpochId: companion.runtime_epoch_id,
            apiGeneration: companion.api_generation,
        },
    );
    const accountHead = database.prepare(`
        SELECT * FROM exposure_account_arbiter_heads
         WHERE account_broker_ref=? AND account_id_ref=?
    `).get(companion.account_broker_ref, companion.account_id_ref);
    const identityHead = database.prepare(`
        SELECT * FROM exposure_identity_arbiter_heads WHERE identity_group_id=?
    `).get(strategy?.identity_group_id);
    assertExposureHeadPair(accountHead, identityHead, strategy);
    const dimensions = parseExposureHeadDimensions(accountHead, 'account exposure head');
    parseExposureHeadDimensions(identityHead, 'identity exposure head');
    if (
        reservation.policy_revision !== accountHead.policy_revision ||
        reservation.policy_hash !== accountHead.policy_hash ||
        reservation.account_broker_ref !== companion.account_broker_ref ||
        reservation.account_id_ref !== companion.account_id_ref ||
        reservation.identity_group_id !== strategy.identity_group_id
    ) {
        throw new Error('dispatch reservation no longer matches current exposure heads');
    }
    const accountAggregate = aggregateActiveExposure(
        database,
        'account_broker_ref=? AND account_id_ref=?',
        [companion.account_broker_ref, companion.account_id_ref],
    );
    const identityAggregate = aggregateActiveExposure(
        database,
        'identity_group_id=?',
        [strategy.identity_group_id],
    );
    const zeroCandidate = Object.fromEntries(
        EXPOSURE_DIMENSIONS.map((dimension) => [dimension, 0]),
    );
    assertExposureLimit(accountHead, accountAggregate, zeroCandidate, dimensions, 'account');
    assertExposureLimit(identityHead, identityAggregate, zeroCandidate, dimensions, 'identity');
    return sha256Canonical(
        {
            account: {
                revision: accountHead.revision,
                sourceSequence: accountHead.source_sequence,
            },
            identity: {
                revision: identityHead.revision,
                sourceSequence: identityHead.source_sequence,
            },
            policyHash: accountHead.policy_hash,
            policyRevision: accountHead.policy_revision,
            canonicalPnlDecisionHash,
            reservationId: reservation.reservation_id,
            reservationRevision: reservation.revision,
            sourceEvidenceHash: accountHead.source_evidence_hash,
        },
        'dispatch exposure decision',
    );
}

function canonicalProtectionOcoSelection(exitClaim) {
    if (
        !exactKeys(exitClaim, [
            'accountBrokerRef',
            'accountIdRef',
            'allocationStartShare',
            'candidateEvaluations',
            'contractKey',
            'evidenceHash',
            'exitClaimId',
            'expectedGenerationRevision',
            'expectedGroupRevision',
            'expectedRevision',
            'obligationId',
            'positionLineageId',
            'protectionGroupId',
            'quantityShares',
            'remainderGeneration',
        ]) ||
        !Array.isArray(exitClaim.candidateEvaluations) ||
        exitClaim.candidateEvaluations.length < 1 ||
        exitClaim.candidateEvaluations.length > 3
    ) {
        throw new TypeError('protection OCO selection schema is invalid');
    }
    const protectionGroupId = boundedToken(
        exitClaim.protectionGroupId,
        'exitClaim.protectionGroupId',
    );
    const exitClaimId = boundedToken(
        exitClaim.exitClaimId,
        'exitClaim.exitClaimId',
    );
    const remainderGeneration = safeInteger(
        exitClaim.remainderGeneration,
        'exitClaim.remainderGeneration',
    );
    const seen = new Set();
    const candidates = exitClaim.candidateEvaluations.map((candidate, index) => {
        if (!exactKeys(candidate, ['evidenceHash', 'legId', 'observedAtEpochMs'])) {
            throw new TypeError(
                `exitClaim.candidateEvaluations[${index}] schema is invalid`,
            );
        }
        const legId = boundedToken(
            candidate.legId,
            `exitClaim.candidateEvaluations[${index}].legId`,
        );
        if (seen.has(legId)) {
            throw new TypeError('protection OCO candidate leg IDs must be unique');
        }
        seen.add(legId);
        return Object.freeze({
            legId,
            evidenceHash: sha256Digest(
                candidate.evidenceHash,
                `exitClaim.candidateEvaluations[${index}].evidenceHash`,
            ),
            observedAtEpochMs: safeInteger(
                candidate.observedAtEpochMs,
                `exitClaim.candidateEvaluations[${index}].observedAtEpochMs`,
            ),
        });
    });
    candidates.sort(
        (left, right) =>
            left.observedAtEpochMs - right.observedAtEpochMs ||
            left.legId.localeCompare(right.legId),
    );
    const winner = candidates[0];
    const selectionHash = sha256Canonical(
        {
            schemaVersion: 'smart-order-protection-oco-selection/2026-08-15.1',
            protectionGroupId,
            exitClaimId,
            remainderGeneration,
            candidates,
            winnerLegId: winner.legId,
        },
        'protection OCO selection',
    );
    return Object.freeze({
        protectionGroupId,
        exitClaimId,
        remainderGeneration,
        candidates: Object.freeze(candidates),
        winner,
        selectionHash,
    });
}

function transitionProtectedEntryTriggerToManual(
    database,
    {
        blockerId,
        deniedBy,
        entry,
        manualReason,
        now,
        orders,
        resolutionCaseId,
        triggerSelectionHash,
    },
) {
    if (
        !['observing', 'monitoring', 'recovery'].includes(
            entry.strategy_state,
        ) ||
        entry.claim_state !== 'monitoring_reserved' ||
        entry.obligation_state !== 'monitoring' ||
        entry.group_state !== 'monitoring' ||
        entry.generation_state !== 'monitoring'
    ) {
        throw new Error(
            'protected entry manual intervention lost its durable lineage',
        );
    }
    const evidenceHash = sha256Canonical(
        {
            deniedBy,
            entryIntentId: entry.entry_intent_id,
            entryIntentState: entry.entry_intent_state,
            manualReason,
            orderStates: orders.map((order) => ({
                brokerOrderId: order.broker_order_id,
                controlRevision: order.control_revision,
                filledShares: order.filled_shares,
                remainingShares: order.remaining_shares,
                revision: order.revision,
                state: order.state,
            })),
            triggerSelectionHash,
        },
        'protected entry manual-intervention evidence',
    );
    const scopeHash = sha256Canonical(
        {
            accountBrokerRef: entry.account_broker_ref,
            accountIdRef: entry.account_id_ref,
            contractKey: entry.contract_key,
            protectionGroupId: entry.protection_group_id,
            strategyId: entry.strategy_id,
            tradeDate: entry.trade_date,
        },
        'protected entry manual-intervention scope',
    );
    const strategyResult = database.prepare(`
        UPDATE strategies
           SET state='manual_intervention', updated_at_epoch_ms=?,
               revision=revision+1
         WHERE strategy_id=? AND state=? AND revision=?
    `).run(
        now,
        entry.strategy_id,
        entry.strategy_state,
        entry.strategy_revision,
    );
    const claimResult = database.prepare(`
        UPDATE exit_claims
           SET state='unknown', evidence_hash=?, updated_at_epoch_ms=?,
               terminal_at_epoch_ms=NULL, revision=revision+1
         WHERE exit_claim_id=? AND state='monitoring_reserved'
           AND revision=?
    `).run(
        evidenceHash,
        now,
        entry.exit_claim_id,
        entry.claim_revision,
    );
    const obligationResult = database.prepare(`
        UPDATE protection_obligations
           SET state='safety_blocked', updated_at_epoch_ms=?,
               revision=revision+1
         WHERE obligation_id=? AND state='monitoring' AND revision=?
    `).run(
        now,
        entry.obligation_id,
        entry.obligation_revision,
    );
    const generationResult = database.prepare(`
        UPDATE protection_remainder_generations
           SET state='unknown', evidence_hash=?, updated_at_epoch_ms=?,
               revision=revision+1
         WHERE protection_group_id=? AND remainder_generation=?
           AND state='monitoring' AND revision=?
    `).run(
        evidenceHash,
        now,
        entry.protection_group_id,
        entry.current_generation,
        entry.generation_revision,
    );
    const groupResult = database.prepare(`
        UPDATE protection_groups
           SET state='unknown', updated_at_epoch_ms=?, revision=revision+1
         WHERE protection_group_id=? AND state='monitoring' AND revision=?
    `).run(
        now,
        entry.protection_group_id,
        entry.group_revision,
    );
    if (
        [
            strategyResult,
            claimResult,
            obligationResult,
            generationResult,
            groupResult,
        ].some((result) => Number(result.changes) !== 1)
    ) {
        throw new Error(
            'protected entry manual intervention lost its atomic CAS',
        );
    }
    const activeRearms = database.prepare(`
        SELECT rearms.rearm_authorization_id, rearms.intent_id,
               rearms.user_rearm_evidence_hash, rearms.revision
          FROM intent_rearm_authorizations AS rearms
          JOIN order_intents AS intents ON intents.intent_id=rearms.intent_id
         WHERE intents.strategy_id=? AND rearms.state='active'
         ORDER BY rearms.rearm_authorization_id
    `).all(entry.strategy_id);
    for (const rearm of activeRearms) {
        const result = database.prepare(`
            UPDATE intent_rearm_authorizations
               SET state='superseded', revision=revision+1
             WHERE rearm_authorization_id=? AND state='active'
               AND revision=?
        `).run(rearm.rearm_authorization_id, rearm.revision);
        if (Number(result.changes) !== 1) {
            throw new Error(
                'protected entry manual intervention lost its re-arm CAS',
            );
        }
    }
    database.prepare(`
        INSERT INTO resolution_cases(
            resolution_case_id, strategy_id, reason_code, scope_hash,
            evidence_snapshot_hash, state, created_at_epoch_ms,
            updated_at_epoch_ms, terminal_at_epoch_ms, revision
        ) VALUES (?, ?, 'ENTRY_RESULT_UNKNOWN', ?, ?, 'open', ?, ?, NULL, 0)
    `).run(
        resolutionCaseId,
        entry.strategy_id,
        scopeHash,
        evidenceHash,
        now,
        now,
    );
    database.prepare(`
        INSERT INTO safety_blockers(
            blocker_id, resolution_case_id, scope_hash, reason_code,
            state, created_at_epoch_ms, resolved_at_epoch_ms, revision
        ) VALUES (?, ?, ?, 'ENTRY_RESULT_UNKNOWN', 'open', ?, NULL, 0)
    `).run(blockerId, resolutionCaseId, scopeHash, now);
    advanceLifecycleSideEffectRevision(database);
    insertTransitionJournalEvent(database, {
        entityKind: 'strategy',
        entityId: entry.strategy_id,
        revision: entry.strategy_revision + 1,
        reasonCode: 'ENTRY_RESULT_UNKNOWN',
        summaryCode: 'protected_entry_trigger_manual_intervention',
        nowEpochMs: now,
        payloadHash: evidenceHash,
        eventSuffix: 'protected-entry-trigger-manual',
    });
    insertTransitionJournalEvent(database, {
        entityKind: 'resolution_case',
        entityId: resolutionCaseId,
        revision: 0,
        reasonCode: 'RESOLUTION_CASE_OPENED',
        summaryCode: 'protected_entry_resolution_opened',
        nowEpochMs: now,
        payloadHash: evidenceHash,
        eventSuffix: 'protected-entry-trigger-manual',
    });
    insertTransitionJournalEvent(database, {
        entityKind: 'safety_blocker',
        entityId: blockerId,
        revision: 0,
        reasonCode: 'ENTRY_RESULT_UNKNOWN',
        summaryCode: 'protected_entry_safety_blocker_opened',
        nowEpochMs: now,
        payloadHash: scopeHash,
        eventSuffix: 'protected-entry-trigger-manual',
    });
    return Object.freeze({
        adapterAuthorityGranted: false,
        automaticExitAllowed: false,
        brokerWriteAttempted: false,
        cancelIntentId: null,
        entryDisposition: 'manual_intervention',
        replayed: false,
    });
}

function prepareProtectionEntryBeforeExit(
    database,
    input,
    protectionOcoSelection,
    now,
) {
    const entry = database.prepare(`
        SELECT groups.protection_group_id, groups.state AS group_state,
               groups.current_generation, groups.revision AS group_revision,
               generations.state AS generation_state,
               generations.revision AS generation_revision,
               claims.exit_claim_id, claims.state AS claim_state,
               claims.revision AS claim_revision,
               claims.evidence_hash AS claim_evidence_hash,
               claims.account_broker_ref AS claim_account_broker_ref,
               claims.account_id_ref AS claim_account_id_ref,
               claims.contract_key AS claim_contract_key,
               claims.position_lineage_id AS claim_position_lineage_id,
               claims.allocation_start_share,
               claims.quantity_shares,
               obligations.obligation_id, obligations.state AS obligation_state,
               obligations.revision AS obligation_revision,
               commitments.entry_intent_id,
               entry_intents.state AS entry_intent_state,
               entry_intents.risk_revision AS entry_risk_revision,
               entry_intents.account_broker_ref,
               entry_intents.account_id_ref,
               COALESCE(
                   entry_intents.trade_date,
                   existing.trade_date,
                   parent_child.child_activation_trade_date
               ) AS trade_date,
               COALESCE(entry_intents.contract_key, claims.contract_key) AS contract_key,
               COALESCE(entry_intents.side, 'Sell') AS side,
               existing.strategy_id AS existing_strategy_id,
               existing.protection_plan_json AS existing_plan_json,
               existing.protection_plan_hash AS existing_plan_hash,
               strategies.strategy_id, strategies.strategy_kind,
               strategies.state AS strategy_state,
               strategies.revision AS strategy_revision,
               strategies.definition_hash AS strategy_definition_hash,
               strategies.confirmation_snapshot_hash
          FROM protection_groups AS groups
          JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
          JOIN exit_claims AS claims
            ON claims.exit_claim_id=groups.exit_claim_id
          JOIN protection_obligations AS obligations
            ON obligations.obligation_id=groups.obligation_id
     LEFT JOIN pending_protection_commitments AS commitments
            ON commitments.commitment_id=obligations.commitment_id
     LEFT JOIN order_intents AS entry_intents
            ON entry_intents.intent_id=commitments.entry_intent_id
     LEFT JOIN existing_position_protection_heads AS existing
            ON existing.strategy_id=obligations.strategy_id
           AND existing.obligation_id=obligations.obligation_id
           AND existing.exit_claim_id=claims.exit_claim_id
     LEFT JOIN parent_child_progress_heads AS parent_child
            ON parent_child.strategy_id=obligations.strategy_id
          JOIN strategies ON strategies.strategy_id=obligations.strategy_id
         WHERE groups.protection_group_id=?
           AND generations.remainder_generation=?
    `).get(
        protectionOcoSelection.protectionGroupId,
        protectionOcoSelection.remainderGeneration,
    );
    if (
        !entry ||
        entry.strategy_id !== input.strategyId ||
        (entry.strategy_kind === 'parent_child'
            ? entry.entry_intent_id !== null ||
              entry.existing_strategy_id !== null
            : (entry.entry_intent_id === null) ===
              (entry.existing_strategy_id === null))
    ) {
        throw new Error(
            'protection trigger does not resolve one durable protected entry lineage',
        );
    }
    const lineageMismatches = [
        ['exit_claim', entry.exit_claim_id !== input.exitClaim.exitClaimId],
        ['obligation', entry.obligation_id !== input.exitClaim.obligationId],
        [
            'claim_account_broker',
            entry.claim_account_broker_ref !==
                input.exitClaim.accountBrokerRef,
        ],
        [
            'claim_account_id',
            entry.claim_account_id_ref !== input.exitClaim.accountIdRef,
        ],
        [
            'claim_contract',
            entry.claim_contract_key !== input.exitClaim.contractKey,
        ],
        [
            'position_lineage',
            entry.claim_position_lineage_id !==
                input.exitClaim.positionLineageId,
        ],
        [
            'allocation',
            entry.allocation_start_share !==
                input.exitClaim.allocationStartShare,
        ],
        ['quantity', entry.quantity_shares !== input.exitClaim.quantityShares],
        ['claim_revision', entry.claim_revision !== input.exitClaim.expectedRevision],
        [
            'group_revision',
            entry.group_revision !== input.exitClaim.expectedGroupRevision,
        ],
        [
            'generation_revision',
            entry.generation_revision !==
                input.exitClaim.expectedGenerationRevision,
        ],
        [
            'intent_account_broker',
            (entry.account_broker_ref ?? entry.claim_account_broker_ref) !==
                input.intent.accountBrokerRef,
        ],
        [
            'intent_account_id',
            (entry.account_id_ref ?? entry.claim_account_id_ref) !==
                input.intent.accountIdRef,
        ],
        ['trade_date', entry.trade_date !== input.intent.tradeDate],
        ['intent_contract', entry.contract_key !== input.intent.contractKey],
        ['intent_side', input.intent.side !== 'Sell'],
    ].filter(([, mismatched]) => mismatched);
    if (lineageMismatches.length > 0) {
        throw new Error(
            `protection OCO group, claim lineage, or optimistic revision does not exactly match: ${lineageMismatches
                .map(([field]) => field)
                .join(',')} (claim ${entry.claim_revision}/${input.exitClaim.expectedRevision}, group ${entry.group_revision}/${input.exitClaim.expectedGroupRevision}, generation ${entry.generation_revision}/${input.exitClaim.expectedGenerationRevision})`,
        );
    }
    if (entry.strategy_kind === 'parent_child') {
        if (
            entry.strategy_state !== 'monitoring' ||
            entry.group_state !== 'monitoring' ||
            entry.generation_state !== 'monitoring' ||
            entry.claim_state !== 'monitoring_reserved' ||
            entry.obligation_state !== 'monitoring'
        ) {
            throw new Error(
                'parent-child protection trigger lineage is not current',
            );
        }
        return null;
    }
    if (entry.existing_strategy_id !== null) {
        const plan = canonicalExistingPositionProtectionPlan(
            parseStoredCanonicalObject(
                entry.existing_plan_json,
                'existing-position OCO preparation plan',
            ),
        );
        if (
            plan.planSha256 !== entry.existing_plan_hash ||
            plan.plan.confirmationSnapshotHash !==
                entry.confirmation_snapshot_hash ||
            plan.plan.accountBrokerRef !== entry.claim_account_broker_ref ||
            plan.plan.accountIdRef !== entry.claim_account_id_ref ||
            plan.plan.contractKey !== entry.claim_contract_key ||
            !['monitoring'].includes(entry.strategy_state) ||
            entry.group_state !== 'monitoring' ||
            entry.generation_state !== 'monitoring' ||
            entry.claim_state !== 'monitoring_reserved' ||
            !['monitoring', 'partially_exited'].includes(
                entry.obligation_state,
            )
        ) {
            throw new Error(
                'existing-position protection trigger lineage is not current',
            );
        }
        return null;
    }
    const orders = database.prepare(`
        SELECT broker_order_id, intent_id, state, control_revision,
               quantity_shares, filled_shares, remaining_shares,
               evidence_hash, revision
          FROM broker_orders
         WHERE intent_id=?
         ORDER BY broker_order_id
    `).all(entry.entry_intent_id);
    const workingOrders = orders.filter(
        (order) =>
            ['pre_submitted', 'submitted', 'part_filled'].includes(
                order.state,
            ) && order.remaining_shares > 0,
    );
    const uncertainOrders = orders.filter(
        (order) =>
            ['pending_submit', 'unknown'].includes(order.state) ||
            (!BROKER_ORDER_TERMINAL_STATES.has(order.state) &&
                !workingOrders.includes(order)),
    );
    const resolutionIdentity = sha256Canonical(
        {
            entryIntentId: entry.entry_intent_id,
            protectionGroupId: protectionOcoSelection.protectionGroupId,
            remainderGeneration: protectionOcoSelection.remainderGeneration,
            triggerSelectionHash: protectionOcoSelection.selectionHash,
        },
        'protected entry trigger disposition identity',
    ).slice('sha256:'.length);
    const cancelActivationId =
        `protective-entry-cancel-activation:${resolutionIdentity}`;
    const cancelIntentId = `protective-entry-cancel-intent:${resolutionIdentity}`;
    const cancelRequestId = `protective-entry-cancel:${resolutionIdentity}`;
    const resolutionCaseId = `resolution-${resolutionIdentity}`;
    const blockerId = `blocker-${resolutionIdentity}`;

    const existingCancel = database.prepare(`
        SELECT intent_id, activation_id, state, payload_hash, payload_json,
               target_broker_order_id, target_control_revision, revision
          FROM order_intents
         WHERE owner_kind='activation' AND client_request_id=?
    `).get(cancelRequestId);
    const existingResolution = database.prepare(`
        SELECT state FROM resolution_cases WHERE resolution_case_id=?
    `).get(resolutionCaseId);
    const deniedBy = evaluateKillSwitchDenyUnion(
        currentKillSwitchArbiter(database),
        'protective_entry_cancel',
    );
    if (existingResolution) {
        if (
            existingResolution.state !== 'open' ||
            entry.strategy_state !== 'manual_intervention'
        ) {
            throw new Error(
                'protected entry manual-intervention replay is inconsistent',
            );
        }
        return Object.freeze({
            adapterAuthorityGranted: false,
            automaticExitAllowed: false,
            brokerWriteAttempted: false,
            cancelIntentId: null,
            entryDisposition: 'manual_intervention',
            replayed: true,
        });
    }
    if (
        existingCancel &&
        deniedBy.length === 0 &&
        !['terminal', 'cancelled_proven_unsent', 'unknown'].includes(
            existingCancel.state,
        )
    ) {
        const storedPayload = canonicalIntentPayload(
            existingCancel.payload_json,
            'protected entry cancel replay payload',
        );
        const targetOrder = orders.find(
            (order) =>
                order.broker_order_id ===
                existingCancel.target_broker_order_id,
        );
        if (
            existingCancel.intent_id !== cancelIntentId ||
            existingCancel.activation_id !== cancelActivationId ||
            !targetOrder ||
            !exactKeys(storedPayload, [
                'brokerOrderId',
                'controlRevision',
                'protectionGroupId',
                'remainderGeneration',
                'schemaVersion',
                'triggerSelectionHash',
            ]) ||
            storedPayload.schemaVersion !==
                PROTECTIVE_ENTRY_CANCEL_INTENT_SCHEMA_VERSION ||
            storedPayload.brokerOrderId !== targetOrder.broker_order_id ||
            storedPayload.controlRevision !== targetOrder.control_revision ||
            storedPayload.protectionGroupId !==
                protectionOcoSelection.protectionGroupId ||
            storedPayload.remainderGeneration !==
                protectionOcoSelection.remainderGeneration ||
            storedPayload.triggerSelectionHash !==
                protectionOcoSelection.selectionHash
        ) {
            throw new Error(
                'protected entry cancel replay does not match its durable intent',
            );
        }
        return Object.freeze({
            adapterAuthorityGranted: false,
            automaticExitAllowed: false,
            brokerWriteAttempted: false,
            cancelIntentId,
            cancelTargetBrokerOrderId: targetOrder.broker_order_id,
            entryDisposition:
                existingCancel.state === 'prepared'
                    ? 'entry_cancel_prepared'
                    : 'entry_cancel_pending',
            replayed: true,
        });
    }
    if (
        workingOrders.length === 0 &&
        uncertainOrders.length === 0 &&
        ['terminal', 'cancelled_proven_unsent'].includes(
            entry.entry_intent_state,
        )
    ) {
        return null;
    }

    let manualReason = null;
    let target;
    let correlations = [];
    if (workingOrders.length !== 1 || uncertainOrders.length > 0) {
        manualReason = 'entry_order_state_not_unique_or_final';
    } else if (existingCancel) {
        manualReason =
            existingCancel.state === 'unknown'
                ? 'entry_cancel_result_unknown'
                : 'entry_cancel_terminal_but_entry_still_working';
    } else {
        target = workingOrders[0];
        if (
            target.filled_shares + target.remaining_shares !==
                target.quantity_shares ||
            !entry.entry_risk_revision
        ) {
            manualReason = 'entry_order_quantity_or_risk_unknown';
        } else {
            correlations = database.prepare(`
                SELECT correlation_id, intent_id, broker_order_id,
                       canonical_key_hash, account_broker_ref, account_id_ref,
                       trade_date, contract_key, side, evidence_hash, revision
                  FROM broker_correlations
                 WHERE intent_id=? AND broker_order_id=?
                 ORDER BY correlation_id
            `).all(entry.entry_intent_id, target.broker_order_id);
            if (
                correlations.length !== 1 ||
                correlations.some(
                    (correlation) =>
                        correlation.intent_id !== entry.entry_intent_id ||
                        correlation.broker_order_id !== target.broker_order_id ||
                        correlation.account_broker_ref !==
                            entry.account_broker_ref ||
                        correlation.account_id_ref !== entry.account_id_ref ||
                        correlation.trade_date !== entry.trade_date ||
                        correlation.contract_key !== entry.contract_key ||
                        correlation.side !== entry.side,
                )
            ) {
                manualReason = 'entry_order_correlation_not_unique';
            }
        }
    }
    if (deniedBy.length > 0) {
        manualReason = 'entry_cancel_denied_by_kill_switch';
    }

    if (manualReason !== null) {
        if (
            !['observing', 'monitoring', 'recovery'].includes(
                entry.strategy_state,
            ) ||
            entry.claim_state !== 'monitoring_reserved' ||
            entry.obligation_state !== 'monitoring' ||
            entry.group_state !== 'monitoring' ||
            entry.generation_state !== 'monitoring'
        ) {
            throw new Error(
                'protected entry manual intervention lost its durable lineage',
            );
        }
        const evidenceHash = sha256Canonical(
            {
                deniedBy,
                entryIntentId: entry.entry_intent_id,
                entryIntentState: entry.entry_intent_state,
                manualReason,
                orderStates: orders.map((order) => ({
                    brokerOrderId: order.broker_order_id,
                    controlRevision: order.control_revision,
                    filledShares: order.filled_shares,
                    remainingShares: order.remaining_shares,
                    revision: order.revision,
                    state: order.state,
                })),
                triggerSelectionHash: protectionOcoSelection.selectionHash,
            },
            'protected entry manual-intervention evidence',
        );
        const scopeHash = sha256Canonical(
            {
                accountBrokerRef: entry.account_broker_ref,
                accountIdRef: entry.account_id_ref,
                contractKey: entry.contract_key,
                protectionGroupId: entry.protection_group_id,
                strategyId: entry.strategy_id,
                tradeDate: entry.trade_date,
            },
            'protected entry manual-intervention scope',
        );
        const strategyResult = database.prepare(`
            UPDATE strategies
               SET state='manual_intervention', updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE strategy_id=? AND state=? AND revision=?
        `).run(
            now,
            entry.strategy_id,
            entry.strategy_state,
            entry.strategy_revision,
        );
        const claimResult = database.prepare(`
            UPDATE exit_claims
               SET state='unknown', evidence_hash=?, updated_at_epoch_ms=?,
                   terminal_at_epoch_ms=NULL, revision=revision+1
             WHERE exit_claim_id=? AND state='monitoring_reserved'
               AND revision=?
        `).run(
            evidenceHash,
            now,
            entry.exit_claim_id,
            entry.claim_revision,
        );
        const obligationResult = database.prepare(`
            UPDATE protection_obligations
               SET state='safety_blocked', updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE obligation_id=? AND state='monitoring' AND revision=?
        `).run(
            now,
            entry.obligation_id,
            entry.obligation_revision,
        );
        const generationResult = database.prepare(`
            UPDATE protection_remainder_generations
               SET state='unknown', evidence_hash=?, updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE protection_group_id=? AND remainder_generation=?
               AND state='monitoring' AND revision=?
        `).run(
            evidenceHash,
            now,
            entry.protection_group_id,
            entry.current_generation,
            entry.generation_revision,
        );
        const groupResult = database.prepare(`
            UPDATE protection_groups
               SET state='unknown', updated_at_epoch_ms=?, revision=revision+1
             WHERE protection_group_id=? AND state='monitoring' AND revision=?
        `).run(
            now,
            entry.protection_group_id,
            entry.group_revision,
        );
        if (
            [
                strategyResult,
                claimResult,
                obligationResult,
                generationResult,
                groupResult,
            ].some((result) => Number(result.changes) !== 1)
        ) {
            throw new Error(
                'protected entry manual intervention lost its atomic CAS',
            );
        }
        const activeRearms = database.prepare(`
            SELECT rearms.rearm_authorization_id, rearms.intent_id,
                   rearms.user_rearm_evidence_hash, rearms.revision
              FROM intent_rearm_authorizations AS rearms
              JOIN order_intents AS intents ON intents.intent_id=rearms.intent_id
             WHERE intents.strategy_id=? AND rearms.state='active'
             ORDER BY rearms.rearm_authorization_id
        `).all(entry.strategy_id);
        for (const rearm of activeRearms) {
            const result = database.prepare(`
                UPDATE intent_rearm_authorizations
                   SET state='superseded', revision=revision+1
                 WHERE rearm_authorization_id=? AND state='active'
                   AND revision=?
            `).run(rearm.rearm_authorization_id, rearm.revision);
            if (Number(result.changes) !== 1) {
                throw new Error(
                    'protected entry manual intervention lost its re-arm CAS',
                );
            }
        }
        database.prepare(`
            INSERT INTO resolution_cases(
                resolution_case_id, strategy_id, reason_code, scope_hash,
                evidence_snapshot_hash, state, created_at_epoch_ms,
                updated_at_epoch_ms, terminal_at_epoch_ms, revision
            ) VALUES (?, ?, 'ENTRY_RESULT_UNKNOWN', ?, ?, 'open', ?, ?, NULL, 0)
        `).run(
            resolutionCaseId,
            entry.strategy_id,
            scopeHash,
            evidenceHash,
            now,
            now,
        );
        database.prepare(`
            INSERT INTO safety_blockers(
                blocker_id, resolution_case_id, scope_hash, reason_code,
                state, created_at_epoch_ms, resolved_at_epoch_ms, revision
            ) VALUES (?, ?, ?, 'ENTRY_RESULT_UNKNOWN', 'open', ?, NULL, 0)
        `).run(blockerId, resolutionCaseId, scopeHash, now);
        advanceLifecycleSideEffectRevision(database);
        insertTransitionJournalEvent(database, {
            entityKind: 'strategy',
            entityId: entry.strategy_id,
            revision: entry.strategy_revision + 1,
            reasonCode: 'ENTRY_RESULT_UNKNOWN',
            summaryCode: 'protected_entry_trigger_manual_intervention',
            nowEpochMs: now,
            payloadHash: evidenceHash,
            eventSuffix: 'protected-entry-trigger-manual',
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'resolution_case',
            entityId: resolutionCaseId,
            revision: 0,
            reasonCode: 'RESOLUTION_CASE_OPENED',
            summaryCode: 'protected_entry_resolution_opened',
            nowEpochMs: now,
            payloadHash: evidenceHash,
            eventSuffix: 'protected-entry-trigger-manual',
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'safety_blocker',
            entityId: blockerId,
            revision: 0,
            reasonCode: 'ENTRY_RESULT_UNKNOWN',
            summaryCode: 'protected_entry_safety_blocker_opened',
            nowEpochMs: now,
            payloadHash: scopeHash,
            eventSuffix: 'protected-entry-trigger-manual',
        });
        return Object.freeze({
            adapterAuthorityGranted: false,
            automaticExitAllowed: false,
            brokerWriteAttempted: false,
            cancelIntentId: null,
            entryDisposition: 'manual_intervention',
            replayed: false,
        });
    }

    const payload = Object.freeze({
        brokerOrderId: target.broker_order_id,
        controlRevision: target.control_revision,
        protectionGroupId: protectionOcoSelection.protectionGroupId,
        remainderGeneration: protectionOcoSelection.remainderGeneration,
        schemaVersion: PROTECTIVE_ENTRY_CANCEL_INTENT_SCHEMA_VERSION,
        triggerSelectionHash: protectionOcoSelection.selectionHash,
    });
    const payloadJson = canonicalJson(
        payload,
        'protective entry cancel payload',
    );
    const payloadHash = `sha256:${createHash('sha256')
        .update(payloadJson)
        .digest('hex')}`;
    const existingControl = database.prepare(`
        SELECT intent_id FROM order_intents
         WHERE operation_kind IN ('update','cancel')
           AND target_broker_order_id=? AND target_control_revision=?
           AND state NOT IN ('terminal','cancelled_proven_unsent')
         LIMIT 1
    `).get(target.broker_order_id, target.control_revision);
    if (existingControl) {
        throw new Error('protected entry already has a live control intent');
    }
    database.prepare(`
        INSERT INTO activations(
            activation_id, strategy_id, logical_key, state, generation,
            evidence_hash, created_at_epoch_ms, updated_at_epoch_ms, revision
        ) VALUES (?, ?, ?, 'prepared', ?, ?, ?, ?, 0)
    `).run(
        cancelActivationId,
        entry.strategy_id,
        `protected-entry-cancel:${target.broker_order_id}:${target.control_revision}`,
        protectionOcoSelection.remainderGeneration,
        protectionOcoSelection.selectionHash,
        now,
        now,
    );
    database.prepare(`
        INSERT INTO order_intents(
            intent_id, activation_id, strategy_id, operation_kind,
            owner_kind, state, payload_hash, payload_json,
            client_request_id, account_broker_ref, account_id_ref,
            trade_date, contract_key, side, target_broker_order_id,
            target_control_revision, created_at_epoch_ms,
            updated_at_epoch_ms, revision
        ) VALUES (?, ?, ?, 'cancel', 'activation', 'prepared', ?, ?, ?,
                  ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
    `).run(
        cancelIntentId,
        cancelActivationId,
        entry.strategy_id,
        payloadHash,
        payloadJson,
        cancelRequestId,
        entry.account_broker_ref,
        entry.account_id_ref,
        entry.trade_date,
        entry.contract_key,
        entry.side,
        target.broker_order_id,
        target.control_revision,
        now,
        now,
    );
    advanceLifecycleSideEffectRevision(database);
    insertTransitionJournalEvent(database, {
        entityKind: 'activation',
        entityId: cancelActivationId,
        revision: 0,
        reasonCode: 'ACTIVATION_PREPARED_WITH_INTENT',
        summaryCode: 'protected_entry_cancel_activation_prepared',
        nowEpochMs: now,
        payloadHash: protectionOcoSelection.selectionHash,
        eventSuffix: 'protected-entry-cancel-prepared',
    });
    insertTransitionJournalEvent(database, {
        entityKind: 'order_intent',
        entityId: cancelIntentId,
        revision: 0,
        reasonCode: 'ORDER_INTENT_PREPARED_DURABLY',
        summaryCode: 'protected_entry_cancel_intent_prepared',
        nowEpochMs: now,
        payloadHash,
        eventSuffix: 'protected-entry-cancel-prepared',
    });
    return Object.freeze({
        adapterAuthorityGranted: false,
        automaticExitAllowed: false,
        brokerWriteAttempted: false,
        cancelIntentId,
        cancelTargetBrokerOrderId: target.broker_order_id,
        entryDisposition: 'entry_cancel_prepared',
        replayed: false,
    });
}

function prepareIntent(database, input, withinExistingTransaction = false) {
    rejectCallerSuppliedJournalEvent(input);
    const now = safeInteger(input.nowEpochMs, 'intent.nowEpochMs');
    const mutate = () => {
        const ownerKind = boundedToken(input.intent.ownerKind, 'intent.ownerKind');
        const clientRequestId = boundedToken(
            input.intent.clientRequestId,
            'intent.clientRequestId',
        );
        const payloadHash = sha256Digest(input.intent.payloadHash, 'intent.payloadHash');
        const payloadJson = canonicalJson(input.intent.payload, 'intent.payload');
        const computedPayloadHash = `sha256:${createHash('sha256')
            .update(payloadJson)
            .digest('hex')}`;
        if (computedPayloadHash !== payloadHash) {
            throw new Error('intent payload hash does not match canonical payload');
        }
        const intentStrategyKind = database
            .prepare('SELECT strategy_kind FROM strategies WHERE strategy_id=?')
            .get(boundedToken(input.strategyId, 'strategyId'))?.strategy_kind;
        if (intentStrategyKind === 'scheduled_quantity') {
            throw new Error(
                'scheduled quantity intent is disabled: mode_algorithm_unverified',
            );
        }
        const protectionOcoSelection = input.exitClaim
            ? canonicalProtectionOcoSelection(input.exitClaim)
            : null;
        if (protectionOcoSelection) {
            const runtimeEpochId = boundedToken(
                input.runtimeEpochId,
                'protectionOco.runtimeEpochId',
            );
            const senderFence = boundedToken(
                input.senderFence,
                'protectionOco.senderFence',
            );
            const apiGeneration = boundedToken(
                input.apiGeneration,
                'protectionOco.apiGeneration',
            );
            if (
                !currentReadySenderMatches(database, {
                    runtimeEpochId,
                    senderFence,
                    apiGeneration,
                })
            ) {
                throw new Error(
                    'protection OCO winner requires the current ready runtime sender',
                );
            }
        }
        if (
            protectionOcoSelection &&
            input.activation.generation !==
                protectionOcoSelection.remainderGeneration
        ) {
            throw new Error(
                'protection OCO activation generation is not canonical',
            );
        }
        const protectedEntryPayload =
            input.intent.payload?.schemaVersion ===
            SMART_ORDER_PROTECTED_ENTRY_INTENT_SCHEMA_VERSION
            ? canonicalProtectedEntryIntentPayload(input.intent.payload)
            : null;
        const goodTillPayload =
            input.intent.payload?.schemaVersion ===
            GOOD_TILL_INTENT_SCHEMA_VERSION
                ? canonicalGoodTillIntentPayload(input.intent.payload)
                : null;
        const parentChildPayload =
            input.intent.payload?.schemaVersion ===
            PARENT_CHILD_INTENT_SCHEMA_VERSION
                ? canonicalParentChildIntentPayload(input.intent.payload)
                : null;
        const protectedEntryPlan = protectedEntryPayload
            ? canonicalProtectedEntryPlan(
                  protectedEntryPayload.payload.protectionPlan,
              )
            : null;
        if (protectedEntryPlan) {
            const runtimeEpochId = boundedToken(
                input.runtimeEpochId,
                'protectedEntry.runtimeEpochId',
            );
            const senderFence = boundedToken(
                input.senderFence,
                'protectedEntry.senderFence',
            );
            const apiGeneration = boundedToken(
                input.apiGeneration,
                'protectedEntry.apiGeneration',
            );
            if (
                protectedEntryPlan.plan.modeRevision !== apiGeneration ||
                !currentReadySenderMatches(database, {
                    runtimeEpochId,
                    senderFence,
                    apiGeneration,
                })
            ) {
                throw new Error(
                    'protected entry requires the current ready runtime sender',
                );
            }
            const deniedBy = evaluateKillSwitchDenyUnion(
                currentKillSwitchArbiter(database),
                'new_exposure',
            );
            if (deniedBy.length > 0) {
                throw new Error(
                    `protected entry is denied by kill switch: ${deniedBy.join(',')}`,
                );
            }
        }
        if (
            protectedEntryPayload !== null &&
            (protectedEntryPayload.payloadSha256 !== payloadHash ||
                protectedEntryPayload.payloadJson !== payloadJson)
        ) {
            throw new Error(
                'protected entry intent payload is not the exact canonical projection',
            );
        }
        if (goodTillPayload !== null) {
            const risk = runtimeRiskPolicyView(database);
            const order = goodTillPayload.order;
            const executionPolicy = risk.policy?.executionPolicy;
            const priceMinorUnits = brokerPriceMinorUnits(
                order.limitPrice,
                'goodTill.order.limitPrice',
            );
            const notional = BigInt(order.baseShares) * BigInt(priceMinorUnits);
            if (notional > BigInt(Number.MAX_SAFE_INTEGER)) {
                throw new Error('good-till notional exceeds the safe integer range');
            }
            const fee =
                (notional * BigInt(executionPolicy?.buyFeeBps ?? -1) + 9_999n) /
                10_000n;
            const feeMinorUnits = BigInt(
                Math.max(
                    Number(fee),
                    executionPolicy?.minimumBuyFeeMinorUnits ?? -1,
                ),
            );
            const cash =
                notional +
                feeMinorUnits +
                BigInt(executionPolicy?.cashBufferMinorUnits ?? -1);
            const expectedReservation = {
                quantityShares: order.baseShares,
                notionalMinorUnits: Number(notional),
                cashMinorUnits: Number(cash),
                positionShares: order.baseShares,
                orderCount: 1,
            };
            if (
                intentStrategyKind !== 'good_till' ||
                goodTillPayload.strategyId !== input.strategyId ||
                goodTillPayload.confirmationSnapshotHash !==
                    database
                        .prepare(
                            'SELECT confirmation_snapshot_hash FROM strategies WHERE strategy_id=?',
                        )
                        .get(input.strategyId)?.confirmation_snapshot_hash ||
                order.contractKey !== input.intent.contractKey ||
                input.intent.side !== 'Buy' ||
                input.intent.tradeDate !==
                    goodTillPayload.activationTradeDate ||
                risk.state !== 'current' ||
                risk.policy === null ||
                executionPolicy === undefined ||
                risk.policyHash === null ||
                order.policyRevision !== risk.policy.policyRevision ||
                cash > BigInt(Number.MAX_SAFE_INTEGER) ||
                !input.reservation ||
                EXPOSURE_DIMENSIONS.some(
                    (dimension) =>
                        input.reservation[dimension] !==
                        expectedReservation[dimension],
                )
            ) {
                throw new Error(
                    'good-till intent is not bound to its current confirmation and worst-case reservation',
                );
            }
        }
        if (parentChildPayload !== null) {
            const risk = runtimeRiskPolicyView(database);
            const order = parentChildPayload.order;
            const progress = database.prepare(`
                SELECT * FROM parent_child_progress_heads WHERE strategy_id=?
            `).get(input.strategyId);
            const confirmationHash = database.prepare(`
                SELECT confirmation_snapshot_hash FROM strategies WHERE strategy_id=?
            `).get(input.strategyId)?.confirmation_snapshot_hash;
            if (
                intentStrategyKind !== 'parent_child' ||
                parentChildPayload.strategyId !== input.strategyId ||
                parentChildPayload.confirmationSnapshotHash !== confirmationHash ||
                order.contractKey !== input.intent.contractKey ||
                order.side !== input.intent.side ||
                input.intent.tradeDate !==
                    parentChildPayload.activationTradeDate ||
                risk.state !== 'current' ||
                risk.policy === null ||
                risk.policyHash === null ||
                order.policyRevision !== risk.policy.policyRevision ||
                !progress ||
                (parentChildPayload.leg === 'parent' &&
                    progress.state !== 'waiting_parent') ||
                (parentChildPayload.leg === 'child' &&
                    (progress.state !== 'child_monitoring' ||
                        progress.parent_settlement_hash !==
                            parentChildPayload.parentSettlementHash ||
                        progress.child_position_lineage_id !==
                            parentChildPayload.childPositionLineageId ||
                        progress.child_activation_trade_date !==
                            parentChildPayload.activationTradeDate ||
                        progress.child_quantity_shares !== order.baseShares))
            ) {
                throw new Error(
                    'parent-child intent is not bound to its current durable progress',
                );
            }
            if (parentChildPayload.leg === 'parent') {
                const expectedReservation = goodTillWorstCaseReservation(
                    order,
                    risk.policy,
                );
                if (
                    !input.reservation ||
                    EXPOSURE_DIMENSIONS.some(
                        (dimension) =>
                            input.reservation[dimension] !==
                            expectedReservation[dimension],
                    )
                ) {
                    throw new Error(
                        'parent-child parent requires its exact worst-case reservation',
                    );
                }
            } else if (!protectionOcoSelection || input.reservation) {
                throw new Error(
                    'parent-child child requires one exact reduce-only claim and no Buy reservation',
                );
            }
        }
        const replay = database
            .prepare(`
                SELECT intent_id, state, revision, payload_hash, payload_json,
                       strategy_id, activation_id, account_broker_ref,
                       account_id_ref, trade_date, contract_key, side,
                       adapter_authority_granted,
                       (SELECT logical_key FROM activations
                         WHERE activation_id=order_intents.activation_id) AS activation_logical_key,
                       (SELECT generation FROM activations
                         WHERE activation_id=order_intents.activation_id) AS activation_generation,
                       (SELECT evidence_hash FROM activations
                         WHERE activation_id=order_intents.activation_id) AS activation_evidence_hash,
                       (SELECT reservation_id FROM entry_exposure_reservations
                         WHERE intent_id=order_intents.intent_id) AS reservation_id,
                       (SELECT policy_revision FROM entry_exposure_reservations
                         WHERE intent_id=order_intents.intent_id) AS reservation_policy_revision,
                       (SELECT policy_hash FROM entry_exposure_reservations
                         WHERE intent_id=order_intents.intent_id) AS reservation_policy_hash,
                       (SELECT quantity_shares FROM entry_exposure_reservations
                         WHERE intent_id=order_intents.intent_id) AS reservation_quantity_shares,
                       (SELECT notional_minor_units FROM entry_exposure_reservations
                         WHERE intent_id=order_intents.intent_id) AS reservation_notional_minor_units,
                       (SELECT cash_minor_units FROM entry_exposure_reservations
                         WHERE intent_id=order_intents.intent_id) AS reservation_cash_minor_units,
                       (SELECT position_shares FROM entry_exposure_reservations
                         WHERE intent_id=order_intents.intent_id) AS reservation_position_shares,
                       (SELECT order_count FROM entry_exposure_reservations
                         WHERE intent_id=order_intents.intent_id) AS reservation_order_count,
                       (SELECT commitment_id
                          FROM pending_protection_commitments
                         WHERE entry_intent_id=order_intents.intent_id) AS commitment_id,
                       (SELECT obligations.obligation_id
                          FROM protection_obligations AS obligations
                          JOIN pending_protection_commitments AS commitments
                            ON commitments.commitment_id=obligations.commitment_id
                         WHERE commitments.entry_intent_id=order_intents.intent_id
                         LIMIT 1) AS obligation_id,
                       (SELECT commitments.committed_shares
                          FROM pending_protection_commitments AS commitments
                         WHERE commitments.entry_intent_id=order_intents.intent_id) AS committed_shares,
                       (SELECT obligations.position_lineage_id
                          FROM protection_obligations AS obligations
                          JOIN pending_protection_commitments AS commitments
                            ON commitments.commitment_id=obligations.commitment_id
                         WHERE commitments.entry_intent_id=order_intents.intent_id
                         LIMIT 1) AS position_lineage_id,
                       (SELECT exit_claim_id FROM exit_claims
                         WHERE intent_id=order_intents.intent_id
                         LIMIT 1) AS exit_claim_id
                  FROM order_intents
                 WHERE owner_kind=? AND client_request_id=?
            `)
            .get(ownerKind, clientRequestId);
        if (replay) {
            if (replay.payload_hash !== payloadHash || replay.payload_json !== payloadJson) {
                throw new Error('client request replay payload mismatch');
            }
            if (protectionOcoSelection) {
                const generation = database.prepare(`
                    SELECT groups.protection_group_id, groups.obligation_id,
                           groups.exit_claim_id, groups.current_generation,
                           generations.state, generations.winner_leg_id,
                           generations.winner_activation_id,
                           generations.winner_intent_id,
                           generations.evidence_hash
                      FROM protection_groups AS groups
                      JOIN protection_remainder_generations AS generations
                        ON generations.protection_group_id=
                           groups.protection_group_id
                       AND generations.remainder_generation=
                           groups.current_generation
                     WHERE groups.protection_group_id=?
                `).get(protectionOcoSelection.protectionGroupId);
                const evaluations = database.prepare(`
                    SELECT leg_id, state, evidence_hash, broker_authority
                      FROM protection_leg_evaluations
                     WHERE protection_group_id=? AND remainder_generation=?
                     ORDER BY leg_id
                `).all(
                    protectionOcoSelection.protectionGroupId,
                    protectionOcoSelection.remainderGeneration,
                );
                const expectedEvaluations = protectionOcoSelection.candidates
                    .map((candidate) => ({
                        leg_id: candidate.legId,
                        state:
                            candidate.legId ===
                            protectionOcoSelection.winner.legId
                                ? 'winner'
                                : 'suppressed',
                        evidence_hash: candidate.evidenceHash,
                        broker_authority: 0,
                    }))
                    .sort((left, right) =>
                        left.leg_id.localeCompare(right.leg_id),
                    );
                if (
                    replay.intent_id !== input.intent.intentId ||
                    replay.activation_id !== input.activation.activationId ||
                    replay.strategy_id !== input.strategyId ||
                    replay.account_broker_ref !==
                        input.intent.accountBrokerRef ||
                    replay.account_id_ref !== input.intent.accountIdRef ||
                    replay.trade_date !== input.intent.tradeDate ||
                    replay.contract_key !== input.intent.contractKey ||
                    replay.side !== 'Sell' ||
                    replay.exit_claim_id !==
                        protectionOcoSelection.exitClaimId ||
                    !generation ||
                    generation.obligation_id !== input.exitClaim.obligationId ||
                    generation.exit_claim_id !==
                        protectionOcoSelection.exitClaimId ||
                    generation.current_generation !==
                        protectionOcoSelection.remainderGeneration ||
                    generation.state !== 'winner_selected' ||
                    generation.winner_leg_id !==
                        protectionOcoSelection.winner.legId ||
                    generation.winner_activation_id !==
                        input.activation.activationId ||
                    generation.winner_intent_id !==
                        input.intent.intentId ||
                    generation.evidence_hash !==
                        protectionOcoSelection.selectionHash ||
                    stableCanonicalJson(evaluations) !==
                        stableCanonicalJson(expectedEvaluations)
                ) {
                    throw new Error(
                        'protection OCO replay envelope does not match its durable winner',
                    );
                }
            }
            if (
                protectedEntryPayload &&
                (replay.intent_id !== input.intent.intentId ||
                    replay.strategy_id !== input.strategyId ||
                    replay.activation_id !== input.activation?.activationId ||
                    replay.activation_logical_key !== input.activation?.logicalKey ||
                    replay.activation_generation !== input.activation?.generation ||
                    replay.activation_evidence_hash !== input.activation?.evidenceHash ||
                    replay.account_broker_ref !== input.intent.accountBrokerRef ||
                    replay.account_id_ref !== input.intent.accountIdRef ||
                    replay.trade_date !== input.intent.tradeDate ||
                    replay.contract_key !== input.intent.contractKey ||
                    replay.side !== input.intent.side ||
                    replay.reservation_id !== input.reservation?.reservationId ||
                    replay.reservation_policy_revision !==
                        input.reservation?.policyRevision ||
                    replay.reservation_policy_hash !== input.reservation?.policyHash ||
                    replay.reservation_quantity_shares !==
                        input.reservation?.quantityShares ||
                    replay.reservation_notional_minor_units !==
                        input.reservation?.notionalMinorUnits ||
                    replay.reservation_cash_minor_units !==
                        input.reservation?.cashMinorUnits ||
                    replay.reservation_position_shares !==
                        input.reservation?.positionShares ||
                    replay.reservation_order_count !==
                        input.reservation?.orderCount ||
                    replay.commitment_id !==
                        input.protectionCommitment?.commitmentId ||
                    replay.committed_shares !==
                        input.protectionCommitment?.committedShares ||
                    replay.obligation_id !==
                        input.protectionObligation?.obligationId ||
                    replay.position_lineage_id !==
                        input.protectionObligation?.positionLineageId)
            ) {
                throw new Error(
                    'protected entry replay envelope does not match its durable intent',
                );
            }
            return {
                intentId: replay.intent_id,
                state: replay.state,
                revision: replay.revision,
                adapterAuthorityGranted: replay.adapter_authority_granted === 1,
                protectionCommitmentId: replay.commitment_id ?? null,
                protectionObligationId: replay.obligation_id ?? null,
                exitClaimId: replay.exit_claim_id ?? null,
                protectionGroupId:
                    protectionOcoSelection?.protectionGroupId ?? null,
                winnerLegId:
                    protectionOcoSelection?.winner.legId ?? null,
                siblingCount:
                    protectionOcoSelection === null
                        ? 0
                        : protectionOcoSelection.candidates.length - 1,
                replayed: true,
            };
        }
        if (protectionOcoSelection) {
            const entryDisposition = prepareProtectionEntryBeforeExit(
                database,
                input,
                protectionOcoSelection,
                now,
            );
            if (entryDisposition !== null) {
                return entryDisposition;
            }
            const deniedBy = evaluateKillSwitchDenyUnion(
                currentKillSwitchArbiter(database),
                'protective_reduce_only',
            );
            if (deniedBy.length > 0) {
                throw new Error(
                    `protection OCO winner is denied by kill switch: ${deniedBy.join(',')}`,
                );
            }
        }
        const strategy = database
            .prepare(`
                SELECT state, revision, strategy_kind, account_broker_ref, account_id_ref,
                       identity_group_id, confirmation_snapshot_hash
                  FROM strategies WHERE strategy_id=?
            `)
            .get(boundedToken(input.strategyId, 'strategyId'));
        if (!strategy) throw new Error('intent strategy does not exist');
        if (['cancelled', 'completed', 'expired', 'failed'].includes(strategy.state)) {
            throw new Error('terminal strategy cannot prepare an intent');
        }
        if (
            input.intent.accountBrokerRef !== strategy.account_broker_ref ||
            input.intent.accountIdRef !== strategy.account_id_ref
        ) {
            throw new Error('intent account scope must match its fixed strategy account');
        }
        if (protectedEntryPayload) {
            authenticatedIdentityAdmission(database, input.identityAdmission, {
                accountBrokerRef: strategy.account_broker_ref,
                accountIdRef: strategy.account_id_ref,
                identityGroupId: strategy.identity_group_id,
            });
            assertAuthenticatedIdentityStrategyCapacity(
                database,
                strategy.identity_group_id,
                { prospectiveStrategyId: input.strategyId },
            );
        }
        if (
            Boolean(input.protectionCommitment) !==
            Boolean(input.protectionObligation)
        ) {
            throw new Error(
                'protected entry requires commitment and obligation in the same transaction',
            );
        }
        if (input.protectionCommitment && input.exitClaim) {
            throw new Error(
                'unfilled protected entry cannot create or reserve an exit claim',
            );
        }
        if (input.protectionCommitment) {
            const plan = protectedEntryPlan.plan;
            const order = plan.entryOrder;
            if (
                plan.confirmationSnapshotHash !==
                    strategy.confirmation_snapshot_hash ||
                protectedEntryPayload.payload.confirmationSnapshotHash !==
                    strategy.confirmation_snapshot_hash ||
                protectedEntryPayload.payload.protectionPlanSha256 !==
                    protectedEntryPlan.planSha256
            ) {
                throw new Error(
                    'protected entry confirmation or plan hash is not current',
                );
            }
            if (
                plan.accountBrokerRef !== strategy.account_broker_ref ||
                plan.accountIdRef !== strategy.account_id_ref ||
                plan.accountBrokerRef !== input.intent.accountBrokerRef ||
                plan.accountIdRef !== input.intent.accountIdRef ||
                plan.contractKey !== input.intent.contractKey ||
                order.side !== input.intent.side ||
                order.baseShares !== input.protectionCommitment.committedShares
            ) {
                throw new Error(
                    'protected entry plan scope or quantity does not match its durable strategy and intent',
                );
            }
            if (
                JSON.stringify(order) !==
                JSON.stringify(protectedEntryPayload.payload.entryOrder)
            ) {
                throw new Error(
                    'protected entry order projection diverges from its plan',
                );
            }
            if (
                input.reservation &&
                input.reservation.policyRevision !== plan.riskRevision
            ) {
                throw new Error(
                    'protected entry reservation is not bound to the confirmed risk revision',
                );
            }
        }
        const externalSellVisibility = authorizeEntryExposureReservation(
            database,
            input,
            strategy,
            now,
            protectedEntryPlan,
        );
        database
            .prepare(`
                INSERT INTO activations(
                    activation_id, strategy_id, logical_key, state, generation,
                    evidence_hash, created_at_epoch_ms, updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, 'prepared', ?, ?, ?, ?, 0)
            `)
            .run(
                boundedToken(input.activation.activationId, 'activationId'),
                input.strategyId,
                boundedToken(input.activation.logicalKey, 'activation.logicalKey'),
                safeInteger(input.activation.generation, 'activation.generation'),
                sha256Digest(input.activation.evidenceHash, 'activation.evidenceHash'),
                now,
                now,
            );
        database
            .prepare(`
                INSERT INTO order_intents(
                    intent_id, activation_id, strategy_id, operation_kind,
                    owner_kind, state, payload_hash, payload_json,
                    client_request_id, account_broker_ref, account_id_ref,
                    trade_date, contract_key, side, target_broker_order_id,
                    target_control_revision, created_at_epoch_ms,
                    updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, 'prepared', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            `)
            .run(
                boundedToken(input.intent.intentId, 'intentId'),
                input.activation.activationId,
                input.strategyId,
                boundedToken(input.intent.operationKind, 'intent.operationKind'),
                ownerKind,
                payloadHash,
                payloadJson,
                clientRequestId,
                boundedToken(input.intent.accountBrokerRef, 'intent.accountBrokerRef'),
                boundedToken(input.intent.accountIdRef, 'intent.accountIdRef'),
                taipeiTradeDate(input.intent.tradeDate),
                boundedToken(input.intent.contractKey, 'intent.contractKey'),
                boundedToken(input.intent.side, 'intent.side'),
                input.intent.targetBrokerOrderId === undefined
                    ? null
                    : boundedToken(
                          input.intent.targetBrokerOrderId,
                          'intent.targetBrokerOrderId',
                      ),
                input.intent.targetControlRevision === undefined
                    ? null
                    : safeInteger(
                          input.intent.targetControlRevision,
                          'intent.targetControlRevision',
                      ),
                now,
                now,
            );

        if (input.reservation) {
            const reservation = input.reservation;
            database
                .prepare(`
                    INSERT INTO entry_exposure_reservations(
                        reservation_id, strategy_id, intent_id,
                        account_broker_ref, account_id_ref, identity_group_id,
                        policy_revision, policy_hash, state, quantity_shares,
                        notional_minor_units, cash_minor_units, position_shares,
                        order_count, created_at_epoch_ms, updated_at_epoch_ms,
                        revision
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'reserved', ?, ?, ?, ?, ?, ?, ?, 0)
                `)
                .run(
                    boundedToken(reservation.reservationId, 'reservationId'),
                    input.strategyId,
                    input.intent.intentId,
                    boundedToken(reservation.accountBrokerRef, 'reservation.accountBrokerRef'),
                    boundedToken(reservation.accountIdRef, 'reservation.accountIdRef'),
                    boundedToken(reservation.identityGroupId, 'reservation.identityGroupId'),
                    boundedToken(reservation.policyRevision, 'reservation.policyRevision'),
                    sha256Digest(reservation.policyHash, 'reservation.policyHash'),
                    safeInteger(reservation.quantityShares, 'reservation.quantityShares'),
                    safeInteger(
                        reservation.notionalMinorUnits,
                        'reservation.notionalMinorUnits',
                    ),
                    safeInteger(reservation.cashMinorUnits, 'reservation.cashMinorUnits'),
                    safeInteger(reservation.positionShares, 'reservation.positionShares'),
                    safeInteger(reservation.orderCount, 'reservation.orderCount'),
                    now,
                    now,
                );
        }
        if (input.protectionCommitment) {
            if (
                input.intent.operationKind !== 'place' ||
                input.intent.side !== 'Buy'
            ) {
                throw new Error('protected entry commitment requires a Buy place intent');
            }
            const commitment = input.protectionCommitment;
            const obligation = input.protectionObligation;
            const committedShares = safeInteger(
                commitment.committedShares,
                'protectionCommitment.committedShares',
                { minimum: 1 },
            );
            if (
                input.reservation &&
                committedShares !== input.reservation.quantityShares
            ) {
                throw new Error(
                    'protected entry commitment shares must match its exposure reservation',
                );
            }
            database
                .prepare(`
                    INSERT INTO pending_protection_commitments(
                        commitment_id, strategy_id, entry_intent_id, state,
                        committed_shares, materialized_shares,
                        created_at_epoch_ms, updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, 'pending_entry_fill', ?, 0, ?, ?, 0)
                `)
                .run(
                    boundedToken(commitment.commitmentId, 'protectionCommitment.commitmentId'),
                    input.strategyId,
                    input.intent.intentId,
                    committedShares,
                    now,
                    now,
                );
            database
                .prepare(`
                    INSERT INTO protection_obligations(
                        obligation_id, strategy_id, commitment_id, state,
                        position_lineage_id, filled_shares,
                        confirmed_exited_shares, created_at_epoch_ms,
                        updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, 'pending_entry_fill', ?, 0, 0, ?, ?, 0)
                `)
                .run(
                    boundedToken(obligation.obligationId, 'protectionObligation.obligationId'),
                    input.strategyId,
                    commitment.commitmentId,
                    boundedToken(
                        obligation.positionLineageId,
                        'protectionObligation.positionLineageId',
                    ),
                    now,
                    now,
                );
        }
        let reservedExitClaim;
        if (input.exitClaim) {
            if (
                input.intent.operationKind !== 'place' ||
                input.intent.side !== 'Sell'
            ) {
                throw new Error('exit claim reservation requires a Sell place intent');
            }
            const claim = input.exitClaim;
            const exitClaimId = boundedToken(claim.exitClaimId, 'exitClaim.exitClaimId');
            const obligationId = boundedToken(
                claim.obligationId,
                'exitClaim.obligationId',
            );
            const accountBrokerRef = boundedToken(
                claim.accountBrokerRef,
                'exitClaim.accountBrokerRef',
            );
            const accountIdRef = boundedToken(
                claim.accountIdRef,
                'exitClaim.accountIdRef',
            );
            const contractKey = boundedToken(
                claim.contractKey,
                'exitClaim.contractKey',
            );
            const positionLineageId = boundedToken(
                claim.positionLineageId,
                'exitClaim.positionLineageId',
            );
            const remainderGeneration = safeInteger(
                claim.remainderGeneration,
                'exitClaim.remainderGeneration',
            );
            const allocationStartShare = safeInteger(
                claim.allocationStartShare,
                'exitClaim.allocationStartShare',
            );
            const quantityShares = safeInteger(
                claim.quantityShares,
                'exitClaim.quantityShares',
                { minimum: 1 },
            );
            const expectedRevision = safeInteger(
                claim.expectedRevision,
                'exitClaim.expectedRevision',
            );
            const evidenceHash = sha256Digest(
                claim.evidenceHash,
                'exitClaim.evidenceHash',
            );
            if (
                accountBrokerRef !== input.intent.accountBrokerRef ||
                accountIdRef !== input.intent.accountIdRef ||
                contractKey !== input.intent.contractKey
            ) {
                throw new Error('exit claim scope must exactly match its fixed intent');
            }
            const existingClaim = database
                .prepare(`
                    SELECT claims.obligation_id, claims.intent_id,
                           claims.external_lineage, claims.account_broker_ref,
                           claims.account_id_ref, claims.contract_key,
                           claims.position_lineage_id,
                           claims.remainder_generation,
                           claims.allocation_start_share,
                           claims.quantity_shares, claims.state, claims.revision,
                           obligations.strategy_id
                      FROM exit_claims AS claims
                      JOIN protection_obligations AS obligations
                        ON obligations.obligation_id=claims.obligation_id
                     WHERE claims.exit_claim_id=?
                `)
                .get(exitClaimId);
            const protectionGeneration = database.prepare(`
                SELECT groups.protection_group_id, groups.obligation_id,
                       groups.exit_claim_id, groups.state AS group_state,
                       groups.current_generation, groups.plan_hash,
                       groups.revision AS group_revision,
                       generations.state AS generation_state,
                       generations.quantity_shares AS generation_quantity_shares,
                       generations.evidence_hash AS generation_evidence_hash,
                       generations.revision AS generation_revision,
                       entry_intents.payload_json AS entry_payload_json,
                       existing.protection_plan_json AS existing_plan_json,
                       strategies.strategy_kind,
                       strategies.confirmation_snapshot_hash
                  FROM protection_groups AS groups
                  JOIN protection_remainder_generations AS generations
                    ON generations.protection_group_id=groups.protection_group_id
                   AND generations.remainder_generation=groups.current_generation
                  JOIN protection_obligations AS obligations
                    ON obligations.obligation_id=groups.obligation_id
                  JOIN strategies
                    ON strategies.strategy_id=obligations.strategy_id
             LEFT JOIN pending_protection_commitments AS commitments
                    ON commitments.commitment_id=obligations.commitment_id
             LEFT JOIN order_intents AS entry_intents
                    ON entry_intents.intent_id=commitments.entry_intent_id
             LEFT JOIN existing_position_protection_heads AS existing
                    ON existing.strategy_id=obligations.strategy_id
                   AND existing.obligation_id=obligations.obligation_id
                   AND existing.exit_claim_id=groups.exit_claim_id
                 WHERE groups.protection_group_id=?
            `).get(protectionOcoSelection.protectionGroupId);
            const entryPlan = !protectionGeneration
                ? undefined
                : protectionGeneration.strategy_kind === 'parent_child'
                  ? undefined
                : protectionGeneration.existing_plan_json !== null
                  ? canonicalExistingPositionProtectionPlan(
                        parseStoredCanonicalObject(
                            protectionGeneration.existing_plan_json,
                            'protection OCO existing-position plan',
                        ),
                    )
                  : canonicalProtectedEntryPlan(
                        canonicalProtectedEntryIntentPayload(
                            parseStoredCanonicalObject(
                                protectionGeneration.entry_payload_json,
                                'protection OCO entry intent payload',
                            ),
                        ).payload.protectionPlan,
                    );
            const expectedProtectiveIntent = entryPlan
                ? buildSmartOrderProtectiveBrokerIntentPayload({
                      legId: protectionOcoSelection.winner.legId,
                      protectionPlan: entryPlan.plan,
                      quantityShares,
                      triggerPolicyHash:
                          protectionOcoSelection.winner.evidenceHash,
                  })
                : protectionGeneration?.strategy_kind === 'parent_child' &&
                    parentChildPayload?.leg === 'child'
                  ? Object.freeze({
                        payloadJson,
                        payloadSha256: payloadHash,
                    })
                  : undefined;
            const planLegIds = new Set(
                protectionGeneration?.strategy_kind === 'parent_child'
                    ? ['child']
                    : entryPlan?.plan.protection.legs.map((leg) => leg.legId) ?? [],
            );
            if (
                !existingClaim ||
                existingClaim.external_lineage !== 0 ||
                existingClaim.intent_id !== null ||
                existingClaim.state !== 'monitoring_reserved' ||
                existingClaim.revision !== expectedRevision ||
                existingClaim.obligation_id !== obligationId ||
                existingClaim.strategy_id !== input.strategyId ||
                existingClaim.account_broker_ref !== accountBrokerRef ||
                existingClaim.account_id_ref !== accountIdRef ||
                existingClaim.contract_key !== contractKey ||
                existingClaim.position_lineage_id !== positionLineageId ||
                existingClaim.remainder_generation !== remainderGeneration ||
                existingClaim.allocation_start_share !== allocationStartShare ||
                existingClaim.quantity_shares !== quantityShares ||
                !protectionGeneration ||
                protectionGeneration.protection_group_id !==
                    protectionOcoSelection.protectionGroupId ||
                protectionGeneration.obligation_id !== obligationId ||
                protectionGeneration.exit_claim_id !== exitClaimId ||
                protectionGeneration.group_state !== 'monitoring' ||
                protectionGeneration.generation_state !== 'monitoring' ||
                protectionGeneration.current_generation !==
                    remainderGeneration ||
                protectionGeneration.generation_quantity_shares !==
                    quantityShares ||
                protectionGeneration.group_revision !==
                    safeInteger(
                        claim.expectedGroupRevision,
                        'exitClaim.expectedGroupRevision',
                    ) ||
                protectionGeneration.generation_revision !==
                    safeInteger(
                        claim.expectedGenerationRevision,
                        'exitClaim.expectedGenerationRevision',
                    ) ||
                protectionGeneration.plan_hash !==
                    (protectionGeneration.strategy_kind === 'parent_child'
                        ? protectionGeneration.confirmation_snapshot_hash
                        : entryPlan?.planSha256) ||
                expectedProtectiveIntent?.payloadJson !== payloadJson ||
                expectedProtectiveIntent?.payloadSha256 !== payloadHash ||
                protectionOcoSelection.candidates.some(
                    (candidate) =>
                        !planLegIds.has(candidate.legId) ||
                        candidate.observedAtEpochMs > now,
                )
            ) {
                throw new Error(
                    'protection OCO group, claim lineage, or optimistic revision does not exactly match',
                );
            }
            const claimResult = database
                .prepare(`
                    UPDATE exit_claims
                       SET intent_id=?, state='intent_reserved', evidence_hash=?,
                           updated_at_epoch_ms=?, revision=revision+1
                     WHERE exit_claim_id=? AND external_lineage=0
                       AND intent_id IS NULL AND state='monitoring_reserved'
                       AND revision=?
                `)
                .run(
                    input.intent.intentId,
                    evidenceHash,
                    now,
                    exitClaimId,
                    expectedRevision,
                );
            if (Number(claimResult.changes) !== 1) {
                throw new Error('exit claim reservation lost its lineage CAS');
            }
            const generationResult = database.prepare(`
                UPDATE protection_remainder_generations
                   SET state='winner_selected', winner_leg_id=?,
                       winner_activation_id=?, winner_intent_id=?,
                       evidence_hash=?, updated_at_epoch_ms=?, revision=revision+1
                 WHERE protection_group_id=? AND remainder_generation=?
                   AND exit_claim_id=? AND state='monitoring' AND revision=?
            `).run(
                protectionOcoSelection.winner.legId,
                input.activation.activationId,
                input.intent.intentId,
                protectionOcoSelection.selectionHash,
                now,
                protectionOcoSelection.protectionGroupId,
                remainderGeneration,
                exitClaimId,
                protectionGeneration.generation_revision,
            );
            const groupResult = database.prepare(`
                UPDATE protection_groups
                   SET state='winner_selected', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE protection_group_id=? AND exit_claim_id=?
                   AND current_generation=? AND state='monitoring'
                   AND revision=?
            `).run(
                now,
                protectionOcoSelection.protectionGroupId,
                exitClaimId,
                remainderGeneration,
                protectionGeneration.group_revision,
            );
            if (
                Number(generationResult.changes) !== 1 ||
                Number(groupResult.changes) !== 1
            ) {
                throw new Error('protection OCO winner selection lost its CAS');
            }
            const insertEvaluation = database.prepare(`
                INSERT INTO protection_leg_evaluations(
                    protection_group_id, remainder_generation, leg_id, state,
                    active_dispatch_slot, activation_id, intent_id,
                    evidence_hash, broker_authority,
                    created_at_epoch_ms, updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, 0)
            `);
            for (const candidate of protectionOcoSelection.candidates) {
                const isWinner =
                    candidate.legId === protectionOcoSelection.winner.legId;
                insertEvaluation.run(
                    protectionOcoSelection.protectionGroupId,
                    remainderGeneration,
                    candidate.legId,
                    isWinner ? 'winner' : 'suppressed',
                    isWinner ? 1 : null,
                    isWinner ? input.activation.activationId : null,
                    isWinner ? input.intent.intentId : null,
                    candidate.evidenceHash,
                    now,
                    now,
                );
            }
            if (!externalSellVisibility) {
                throw new Error(
                    'Sell claim reservation requires current external visibility',
                );
            }
            const visibilityBinding = database.prepare(`
                INSERT INTO exit_claim_visibility_bindings(
                    exit_claim_id, account_broker_ref, account_id_ref,
                    trade_date, contract_key, source_revision,
                    source_sequence,
                    source_evidence_hash, position_revision,
                    position_shares, working_set_hash, binding_kind,
                    visibility_head_revision,
                    created_at_epoch_ms, updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'internal_prepared', ?, ?, ?, 0)
                ON CONFLICT(exit_claim_id) DO UPDATE SET
                    source_revision=excluded.source_revision,
                    source_sequence=excluded.source_sequence,
                    source_evidence_hash=excluded.source_evidence_hash,
                    position_revision=excluded.position_revision,
                    position_shares=excluded.position_shares,
                    working_set_hash=excluded.working_set_hash,
                    visibility_head_revision=excluded.visibility_head_revision,
                    updated_at_epoch_ms=excluded.updated_at_epoch_ms,
                    revision=exit_claim_visibility_bindings.revision+1
                WHERE exit_claim_visibility_bindings.account_broker_ref=
                          excluded.account_broker_ref
                  AND exit_claim_visibility_bindings.account_id_ref=
                          excluded.account_id_ref
                  AND exit_claim_visibility_bindings.trade_date=
                          excluded.trade_date
                  AND exit_claim_visibility_bindings.contract_key=
                          excluded.contract_key
                  AND exit_claim_visibility_bindings.binding_kind=
                          'internal_prepared'
            `).run(
                exitClaimId,
                accountBrokerRef,
                accountIdRef,
                taipeiTradeDate(input.intent.tradeDate),
                contractKey,
                externalSellVisibility.head.source_revision,
                externalSellVisibility.head.source_sequence,
                externalSellVisibility.head.source_evidence_hash,
                externalSellVisibility.head.position_revision,
                externalSellVisibility.head.position_shares,
                externalSellVisibility.head.working_set_hash,
                externalSellVisibility.head.revision,
                now,
                now,
            );
            if (Number(visibilityBinding.changes) !== 1) {
                throw new Error(
                    'Sell claim visibility binding lost its exact lineage',
                );
            }
            reservedExitClaim = {
                exitClaimId,
                evidenceHash,
                revision: expectedRevision + 1,
                protectionGroupId: protectionOcoSelection.protectionGroupId,
                winnerLegId: protectionOcoSelection.winner.legId,
                siblingCount: protectionOcoSelection.candidates.length - 1,
            };
        }
        insertTransitionJournalEvent(database, {
            entityKind: 'activation',
            entityId: input.activation.activationId,
            revision: 0,
            reasonCode: 'ACTIVATION_PREPARED_WITH_INTENT',
            summaryCode: 'activation_prepared',
            nowEpochMs: now,
            payloadHash: input.activation.evidenceHash,
            eventSuffix: 'prepared',
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: input.intent.intentId,
            revision: 0,
            reasonCode: 'ORDER_INTENT_PREPARED_DURABLY',
            summaryCode: 'order_intent_prepared',
            nowEpochMs: now,
            payloadHash,
            eventSuffix: 'prepared',
        });
        if (input.reservation) {
            insertTransitionJournalEvent(database, {
                entityKind: 'entry_exposure_reservation',
                entityId: input.reservation.reservationId,
                revision: 0,
                reasonCode: 'ENTRY_EXPOSURE_RESERVED_WITH_INTENT',
                summaryCode: 'entry_exposure_reserved',
                nowEpochMs: now,
                payloadHash: input.reservation.policyHash,
                eventSuffix: 'reserved',
            });
        }
        if (input.protectionCommitment) {
            insertTransitionJournalEvent(database, {
                entityKind: 'pending_protection_commitment',
                entityId: input.protectionCommitment.commitmentId,
                revision: 0,
                reasonCode: 'PENDING_PROTECTION_COMMITTED_WITH_ENTRY_INTENT',
                summaryCode: 'pending_protection_committed',
                nowEpochMs: now,
                payloadHash,
                eventSuffix: 'pending-entry-fill',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'protection_obligation',
                entityId: input.protectionObligation.obligationId,
                revision: 0,
                reasonCode: 'PROTECTION_OBLIGATION_CREATED_WITH_ENTRY_INTENT',
                summaryCode: 'protection_obligation_pending_entry_fill',
                nowEpochMs: now,
                payloadHash,
                eventSuffix: 'pending-entry-fill',
            });
        }
        if (reservedExitClaim) {
            insertTransitionJournalEvent(database, {
                entityKind: 'exit_claim',
                entityId: reservedExitClaim.exitClaimId,
                revision: reservedExitClaim.revision,
                reasonCode: 'EXIT_CLAIM_RESERVED_WITH_INTENT',
                summaryCode: 'exit_claim_intent_reserved',
                nowEpochMs: now,
                payloadHash: reservedExitClaim.evidenceHash,
                eventSuffix: 'intent-reserved',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'protection_group',
                entityId: reservedExitClaim.protectionGroupId,
                revision: input.exitClaim.expectedGroupRevision + 1,
                reasonCode: 'PROTECTION_OCO_WINNER_SELECTED',
                summaryCode: 'protection_oco_winner_selected',
                nowEpochMs: now,
                payloadHash: reservedExitClaim.evidenceHash,
                eventSuffix: `generation-${input.exitClaim.remainderGeneration}-winner`,
            });
            for (const candidate of protectionOcoSelection.candidates) {
                insertTransitionJournalEvent(database, {
                    entityKind: 'protection_leg_evaluation',
                    entityId: `${reservedExitClaim.protectionGroupId}:${input.exitClaim.remainderGeneration}:${candidate.legId}`,
                    revision: 0,
                    reasonCode:
                        candidate.legId === reservedExitClaim.winnerLegId
                            ? 'PROTECTION_LEG_WINNER_SELECTED'
                            : 'PROTECTION_LEG_SUPPRESSED_PRE_BROKER',
                    summaryCode:
                        candidate.legId === reservedExitClaim.winnerLegId
                            ? 'protection_leg_winner'
                            : 'protection_leg_suppressed',
                    nowEpochMs: now,
                    payloadHash: candidate.evidenceHash,
                    eventSuffix:
                        candidate.legId === reservedExitClaim.winnerLegId
                            ? 'winner'
                            : 'suppressed',
                });
            }
        }
        return {
            intentId: input.intent.intentId,
            state: 'prepared',
            revision: 0,
            adapterAuthorityGranted: false,
            protectionCommitmentId:
                input.protectionCommitment?.commitmentId ?? null,
            protectionObligationId:
                input.protectionObligation?.obligationId ?? null,
            exitClaimId: reservedExitClaim?.exitClaimId ?? null,
            protectionGroupId:
                reservedExitClaim?.protectionGroupId ?? null,
            winnerLegId: reservedExitClaim?.winnerLegId ?? null,
            siblingCount: reservedExitClaim?.siblingCount ?? 0,
            replayed: false,
        };
    };
    return withinExistingTransaction ? mutate() : transaction(database, mutate);
}

const PREPARED_INTENT_LOCAL_CANCEL_OPERATION_KIND =
    'intent_cancel_proven_unsent';
const PREPARED_INTENT_LOCAL_CANCEL_AUTHORITY_KIND =
    'prepared_intent_local_cancel';

function exactNullableCompanion(value, keys, label) {
    if (value === null) return null;
    if (!exactKeys(value, keys)) {
        throw new TypeError(`${label} has an invalid shape`);
    }
    return value;
}

function cancelPreparedIntentProvenUnsent(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'requestId',
            'authorization',
            'intentId',
            'expectedIntentRevision',
            'activation',
            'reservation',
            'protection',
            'exitClaim',
            'rearm',
            'nowEpochMs',
        ]) ||
        !exactKeys(input.authorization, [
            'authorizationId',
            'evidenceHash',
            'actorKind',
            'lifecycleOperationId',
        ]) ||
        !exactKeys(input.activation, ['activationId', 'expectedRevision'])
    ) {
        throw new TypeError(
            'prepared intent local cancellation input has an invalid shape',
        );
    }
    const reservation = exactNullableCompanion(
        input.reservation,
        ['reservationId', 'expectedRevision'],
        'prepared intent reservation companion',
    );
    const protection = exactNullableCompanion(
        input.protection,
        [
            'commitmentId',
            'expectedCommitmentRevision',
            'obligationId',
            'expectedObligationRevision',
        ],
        'prepared intent protection companion',
    );
    const exitClaim = exactNullableCompanion(
        input.exitClaim,
        ['exitClaimId', 'expectedRevision'],
        'prepared intent exit claim companion',
    );
    const rearm = exactNullableCompanion(
        input.rearm,
        ['rearmAuthorizationId', 'expectedRevision'],
        'prepared intent re-arm companion',
    );
    const requestId = boundedToken(input.requestId, 'localCancel.requestId');
    const intentId = boundedToken(input.intentId, 'localCancel.intentId');
    const expectedIntentRevision = safeInteger(
        input.expectedIntentRevision,
        'localCancel.expectedIntentRevision',
    );
    const activationId = boundedToken(
        input.activation.activationId,
        'localCancel.activation.activationId',
    );
    const expectedActivationRevision = safeInteger(
        input.activation.expectedRevision,
        'localCancel.activation.expectedRevision',
    );
    const authorizationId = boundedToken(
        input.authorization.authorizationId,
        'localCancel.authorization.authorizationId',
    );
    const authorizationEvidenceHash = sha256Digest(
        input.authorization.evidenceHash,
        'localCancel.authorization.evidenceHash',
    );
    const actorKind = boundedToken(
        input.authorization.actorKind,
        'localCancel.authorization.actorKind',
    );
    if (actorKind !== 'interactive_user') {
        throw new TypeError(
            'prepared intent local cancellation requires interactive user authority',
        );
    }
    const lifecycleOperationId =
        input.authorization.lifecycleOperationId === null
            ? null
            : sha256Digest(
                  input.authorization.lifecycleOperationId,
                  'localCancel.authorization.lifecycleOperationId',
              );
    const now = safeInteger(input.nowEpochMs, 'localCancel.nowEpochMs');
    const canonicalAction = {
        schemaVersion:
            'smart-order-prepared-intent-local-cancel/2026-08-12.1',
        authorization: {
            authorizationId,
            evidenceHash: authorizationEvidenceHash,
            actorKind,
            lifecycleOperationId,
        },
        intentId,
        expectedIntentRevision,
        activation: {
            activationId,
            expectedRevision: expectedActivationRevision,
        },
        reservation:
            reservation === null
                ? null
                : {
                      reservationId: boundedToken(
                          reservation.reservationId,
                          'localCancel.reservation.reservationId',
                      ),
                      expectedRevision: safeInteger(
                          reservation.expectedRevision,
                          'localCancel.reservation.expectedRevision',
                      ),
                  },
        protection:
            protection === null
                ? null
                : {
                      commitmentId: boundedToken(
                          protection.commitmentId,
                          'localCancel.protection.commitmentId',
                      ),
                      expectedCommitmentRevision: safeInteger(
                          protection.expectedCommitmentRevision,
                          'localCancel.protection.expectedCommitmentRevision',
                      ),
                      obligationId: boundedToken(
                          protection.obligationId,
                          'localCancel.protection.obligationId',
                      ),
                      expectedObligationRevision: safeInteger(
                          protection.expectedObligationRevision,
                          'localCancel.protection.expectedObligationRevision',
                      ),
                  },
        exitClaim:
            exitClaim === null
                ? null
                : {
                      exitClaimId: boundedToken(
                          exitClaim.exitClaimId,
                          'localCancel.exitClaim.exitClaimId',
                      ),
                      expectedRevision: safeInteger(
                          exitClaim.expectedRevision,
                          'localCancel.exitClaim.expectedRevision',
                      ),
                  },
        rearm:
            rearm === null
                ? null
                : {
                      rearmAuthorizationId: boundedToken(
                          rearm.rearmAuthorizationId,
                          'localCancel.rearm.rearmAuthorizationId',
                      ),
                      expectedRevision: safeInteger(
                          rearm.expectedRevision,
                          'localCancel.rearm.expectedRevision',
                      ),
                  },
    };
    const actionHash = sha256Canonical(
        canonicalAction,
        'prepared intent local cancellation',
    );
    const scopeHash = sha256Canonical(
        {
            intentId,
            expectedIntentRevision,
            activation: canonicalAction.activation,
            reservation: canonicalAction.reservation,
            protection: canonicalAction.protection,
            exitClaim: canonicalAction.exitClaim,
            rearm: canonicalAction.rearm,
        },
        'prepared intent local cancellation scope',
    );
    const authorityConsumptionId = sha256Canonical(
        {
            sourceAuthorizationId: authorizationId,
            actorKind,
            intentId,
        },
        'prepared intent local cancellation authority consumption',
    );
    let trustedStrategyCancelResult = null;

    return transaction(database, () => {
        const replay = reserveRequestReplayInTransaction(database, {
            requestId,
            operationKind: PREPARED_INTENT_LOCAL_CANCEL_OPERATION_KIND,
            payloadHash: actionHash,
            nowEpochMs: now,
        });
        if (replay.replayed) {
            if (replay.state !== 'completed' || replay.resultStatus !== 200) {
                throw new Error(
                    'prepared intent local cancellation replay is not terminal',
                );
            }
            return Object.freeze({ ...replay.result, replayed: true });
        }

        const lifecycleOperation = lifecycleMutationFenceOperation(database);
        if (lifecycleOperationId !== null || lifecycleOperation !== undefined) {
            throw new Error(
                'interactive prepared intent cancellation cannot cross a lifecycle fence',
            );
        }
        const strategyCancelReplay = database
            .prepare(`
                SELECT operation_kind, payload_hash, result_status,
                       result_json, state
                  FROM request_replays WHERE request_id=?
            `)
            .get(authorizationId);
        if (
            !strategyCancelReplay ||
            strategyCancelReplay.operation_kind !== 'strategy_cancel' ||
            strategyCancelReplay.payload_hash !== authorizationEvidenceHash ||
            strategyCancelReplay.state !== 'completed' ||
            strategyCancelReplay.result_status !== 200
        ) {
            throw new Error(
                'interactive prepared intent cancellation lacks a completed strategy-cancel authority',
            );
        }
        const strategyCancelResult = parseStoredCanonicalObject(
            strategyCancelReplay.result_json,
            'strategy cancel authority result',
        );
        if (
            strategyCancelResult.strategyId !== undefined &&
            strategyCancelResult.strategyId !== null &&
            typeof strategyCancelResult.strategyId !== 'string'
        ) {
            throw new Error('strategy cancel authority result is invalid');
        }
        trustedStrategyCancelResult = strategyCancelResult;

        const intent = database
            .prepare(`
                SELECT intents.intent_id, intents.activation_id, intents.strategy_id,
                       intents.operation_kind, intents.state,
                       intents.payload_hash, intents.revision,
                       intents.adapter_authority_granted,
                       intents.dispatch_attempt_nonce, intents.sender_fence,
                       intents.api_generation, intents.runtime_epoch_id,
                       intents.terminal_outcome,
                       activations.state AS activation_state,
                       activations.revision AS activation_revision,
                       activations.evidence_hash AS activation_evidence_hash,
                       strategies.state AS strategy_state,
                       strategies.revision AS strategy_revision,
                       strategies.definition_hash AS strategy_definition_hash
                  FROM order_intents AS intents
                  JOIN activations
                    ON activations.activation_id=intents.activation_id
                  JOIN strategies
                    ON strategies.strategy_id=intents.strategy_id
                 WHERE intents.intent_id=?
            `)
            .get(intentId);
        if (!intent) {
            throw new Error('prepared intent local cancellation target does not exist');
        }
        if (
            intent.activation_id !== activationId ||
            intent.state !== 'prepared' ||
            intent.revision !== expectedIntentRevision ||
            intent.adapter_authority_granted !== 0 ||
            intent.dispatch_attempt_nonce !== null ||
            intent.sender_fence !== null ||
            intent.api_generation !== null ||
            intent.runtime_epoch_id !== null ||
            intent.terminal_outcome !== null ||
            intent.activation_state !== 'prepared' ||
            intent.activation_revision !== expectedActivationRevision ||
            repositoryMetaValue(database, dispatchArbiterGrantMetaKey(intentId)) !==
                undefined
        ) {
            throw new Error(
                'prepared intent local cancellation lost its proven-unsent CAS',
            );
        }
        if (
            intent.strategy_state !== 'cancel_pending'
        ) {
            throw new Error(
                'prepared intent local cancellation requires cancel-pending strategy',
            );
        }
        if (
            actorKind === 'interactive_user' &&
            (
                trustedStrategyCancelResult?.strategyId !==
                    intent.strategy_id ||
                trustedStrategyCancelResult?.state !==
                    'cancel_pending' ||
                trustedStrategyCancelResult?.revision !==
                    intent.strategy_revision)
        ) {
            throw new Error(
                'interactive prepared intent cancellation requires cancel-pending strategy',
            );
        }
        const brokerOrderCount = Number(
            database
                .prepare(
                    'SELECT COUNT(*) AS count FROM broker_orders WHERE intent_id=?',
                )
                .get(intentId)?.count,
        );
        const correlationCount = Number(
            database
                .prepare(
                    'SELECT COUNT(*) AS count FROM broker_correlations WHERE intent_id=?',
                )
                .get(intentId)?.count,
        );
        if (brokerOrderCount !== 0 || correlationCount !== 0) {
            throw new Error(
                'prepared intent local cancellation found broker-side evidence',
            );
        }

        const reservations = database
            .prepare(
                'SELECT * FROM entry_exposure_reservations WHERE intent_id=? ORDER BY reservation_id',
            )
            .all(intentId);
        const commitments = database
            .prepare(
                'SELECT * FROM pending_protection_commitments WHERE entry_intent_id=? ORDER BY commitment_id',
            )
            .all(intentId);
        const obligations = database
            .prepare(`
                SELECT obligations.*
                  FROM protection_obligations AS obligations
                  JOIN pending_protection_commitments AS commitments
                    ON commitments.commitment_id=obligations.commitment_id
                 WHERE commitments.entry_intent_id=?
                 ORDER BY obligations.obligation_id
            `)
            .all(intentId);
        const claims = database
            .prepare(
                'SELECT * FROM exit_claims WHERE intent_id=? ORDER BY exit_claim_id',
            )
            .all(intentId);
        const activeRearms = database
            .prepare(`
                SELECT * FROM intent_rearm_authorizations
                 WHERE intent_id=? AND state='active'
                 ORDER BY rearm_authorization_id
            `)
            .all(intentId);
        if (
            reservations.length > 1 ||
            commitments.length > 1 ||
            obligations.length > 1 ||
            claims.length > 1 ||
            activeRearms.length > 1
        ) {
            throw new Error(
                'prepared intent local cancellation companion cardinality is invalid',
            );
        }
        const reservationRow = reservations[0] ?? null;
        const commitmentRow = commitments[0] ?? null;
        const obligationRow = obligations[0] ?? null;
        const claimRow = claims[0] ?? null;
        const rearmRow = activeRearms[0] ?? null;
        const protectionGroupRow =
            claimRow === null
                ? null
                : database
                      .prepare(`
                          SELECT groups.protection_group_id,
                                 groups.current_generation,
                                 groups.state AS group_state,
                                 groups.revision AS group_revision,
                                 generations.state AS generation_state,
                                 generations.winner_activation_id,
                                 generations.winner_intent_id,
                                 generations.revision AS generation_revision
                            FROM protection_groups AS groups
                            JOIN protection_remainder_generations AS generations
                              ON generations.protection_group_id=
                                 groups.protection_group_id
                             AND generations.remainder_generation=
                                 groups.current_generation
                           WHERE groups.exit_claim_id=?
                      `)
                      .get(claimRow.exit_claim_id);
        const obligationClaimCount =
            obligationRow === null
                ? 0
                : Number(
                      database
                          .prepare(
                              'SELECT COUNT(*) AS count FROM exit_claims WHERE obligation_id=?',
                          )
                          .get(obligationRow.obligation_id)?.count,
                  );
        if (
            (canonicalAction.reservation === null) !==
                (reservationRow === null) ||
            (canonicalAction.reservation !== null &&
                (reservationRow?.reservation_id !==
                    canonicalAction.reservation.reservationId ||
                    reservationRow?.revision !==
                        canonicalAction.reservation.expectedRevision)) ||
            (canonicalAction.protection === null) !==
                (commitmentRow === null && obligationRow === null) ||
            (canonicalAction.protection !== null &&
                (commitmentRow?.commitment_id !==
                    canonicalAction.protection.commitmentId ||
                    commitmentRow?.revision !==
                        canonicalAction.protection.expectedCommitmentRevision ||
                    obligationRow?.obligation_id !==
                        canonicalAction.protection.obligationId ||
                    obligationRow?.revision !==
                        canonicalAction.protection.expectedObligationRevision)) ||
            (canonicalAction.exitClaim === null) !== (claimRow === null) ||
            (canonicalAction.exitClaim !== null &&
                (claimRow?.exit_claim_id !==
                    canonicalAction.exitClaim.exitClaimId ||
                    claimRow?.revision !==
                        canonicalAction.exitClaim.expectedRevision)) ||
            (canonicalAction.rearm === null) !== (rearmRow === null) ||
            (canonicalAction.rearm !== null &&
                (rearmRow?.rearm_authorization_id !==
                    canonicalAction.rearm.rearmAuthorizationId ||
                    rearmRow?.revision !== canonicalAction.rearm.expectedRevision))
        ) {
            throw new Error(
                'prepared intent local cancellation companion projection is stale',
            );
        }
        if (
            reservationRow !== null && reservationRow.state !== 'reserved'
        ) {
            throw new Error(
                'prepared intent local cancellation reservation is not releasable',
            );
        }
        if (
            commitmentRow !== null &&
            (commitmentRow.state !== 'pending_entry_fill' ||
                commitmentRow.materialized_shares !== 0)
        ) {
            throw new Error(
                'prepared intent local cancellation commitment is not proven unmaterialized',
            );
        }
        if (
            obligationRow !== null &&
            (obligationRow.state !== 'pending_entry_fill' ||
                obligationRow.filled_shares !== 0 ||
                obligationRow.confirmed_exited_shares !== 0 ||
                obligationClaimCount !== 0)
        ) {
            throw new Error(
                'prepared intent local cancellation obligation is not true zero-fill',
            );
        }
        if (
            claimRow !== null &&
            (claimRow.external_lineage !== 0 ||
                claimRow.state !== 'intent_reserved' ||
                !protectionGroupRow ||
                protectionGroupRow.group_state !== 'winner_selected' ||
                protectionGroupRow.generation_state !== 'winner_selected' ||
                protectionGroupRow.winner_activation_id !== activationId ||
                protectionGroupRow.winner_intent_id !== intentId)
        ) {
            throw new Error(
                'prepared intent local cancellation exit claim or protection group is not releasable',
            );
        }

        const existingAuthority = database
            .prepare(`
                SELECT authority_payload_hash, scope_hash, consumed_by
                  FROM authority_consumptions
                 WHERE authority_kind=? AND authority_id=?
            `)
            .get(
                PREPARED_INTENT_LOCAL_CANCEL_AUTHORITY_KIND,
                authorityConsumptionId,
            );
        if (existingAuthority) {
            throw new Error(
                'prepared intent local cancellation authority was already consumed',
            );
        }
        database
            .prepare(`
                INSERT INTO authority_consumptions(
                    authority_kind, authority_id, authority_payload_hash,
                    scope_hash, consumed_by, runtime_epoch_id,
                    consumed_at_epoch_ms
                ) VALUES (?, ?, ?, ?, ?, NULL, ?)
            `)
            .run(
                PREPARED_INTENT_LOCAL_CANCEL_AUTHORITY_KIND,
                authorityConsumptionId,
                authorizationEvidenceHash,
                scopeHash,
                actorKind,
                now,
            );

        const intentResult = database
            .prepare(`
                UPDATE order_intents
                   SET state='cancelled_proven_unsent', terminal_outcome=?,
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE intent_id=? AND state='prepared'
                   AND adapter_authority_granted=0 AND revision=?
                   AND dispatch_attempt_nonce IS NULL AND sender_fence IS NULL
                   AND api_generation IS NULL AND runtime_epoch_id IS NULL
            `)
            .run(
                `${intent.operation_kind}_cancelled_proven_unsent`,
                now,
                now,
                intentId,
                expectedIntentRevision,
            );
        const activationResult = database
            .prepare(`
                UPDATE activations
                   SET state='cancelled', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE activation_id=? AND state='prepared' AND revision=?
            `)
            .run(now, activationId, expectedActivationRevision);
        if (
            Number(intentResult.changes) !== 1 ||
            Number(activationResult.changes) !== 1
        ) {
            throw new Error(
                'prepared intent local cancellation lost its atomic CAS',
            );
        }
        if (reservationRow !== null) {
            const result = database
                .prepare(`
                    UPDATE entry_exposure_reservations
                       SET state='released', updated_at_epoch_ms=?,
                           terminal_at_epoch_ms=?, revision=revision+1
                     WHERE reservation_id=? AND state='reserved' AND revision=?
                `)
                .run(
                    now,
                    now,
                    reservationRow.reservation_id,
                    reservationRow.revision,
                );
            if (Number(result.changes) !== 1) {
                throw new Error(
                    'prepared intent local cancellation reservation CAS failed',
                );
            }
        }
        if (commitmentRow !== null) {
            const commitmentResult = database
                .prepare(`
                    UPDATE pending_protection_commitments
                       SET state='released_pre_dispatch', updated_at_epoch_ms=?,
                           revision=revision+1
                     WHERE commitment_id=? AND state='pending_entry_fill'
                       AND materialized_shares=0 AND revision=?
                `)
                .run(
                    now,
                    commitmentRow.commitment_id,
                    commitmentRow.revision,
                );
            const obligationResult = database
                .prepare(`
                    UPDATE protection_obligations
                       SET state='zero_fill_terminal', updated_at_epoch_ms=?,
                           terminal_at_epoch_ms=?, revision=revision+1
                     WHERE obligation_id=? AND state='pending_entry_fill'
                       AND filled_shares=0 AND confirmed_exited_shares=0
                       AND revision=?
                `)
                .run(
                    now,
                    now,
                    obligationRow.obligation_id,
                    obligationRow.revision,
                );
            if (
                Number(commitmentResult.changes) !== 1 ||
                Number(obligationResult.changes) !== 1
            ) {
                throw new Error(
                    'prepared intent local cancellation protection CAS failed',
                );
            }
        }
        if (claimRow !== null) {
            const result = database
                .prepare(`
                    UPDATE exit_claims
                       SET state='released', updated_at_epoch_ms=?,
                           terminal_at_epoch_ms=?, revision=revision+1
                     WHERE exit_claim_id=? AND external_lineage=0
                       AND state='intent_reserved' AND revision=?
                `)
                .run(now, now, claimRow.exit_claim_id, claimRow.revision);
            if (Number(result.changes) !== 1) {
                throw new Error(
                    'prepared intent local cancellation exit claim CAS failed',
                );
            }
            const generationResult = database.prepare(`
                UPDATE protection_remainder_generations
                   SET state='unknown', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE protection_group_id=? AND remainder_generation=?
                   AND state='winner_selected' AND winner_intent_id=?
                   AND revision=?
            `).run(
                now,
                protectionGroupRow.protection_group_id,
                protectionGroupRow.current_generation,
                intentId,
                protectionGroupRow.generation_revision,
            );
            const groupResult = database.prepare(`
                UPDATE protection_groups
                   SET state='unknown', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE protection_group_id=? AND state='winner_selected'
                   AND current_generation=? AND revision=?
            `).run(
                now,
                protectionGroupRow.protection_group_id,
                protectionGroupRow.current_generation,
                protectionGroupRow.group_revision,
            );
            if (
                Number(generationResult.changes) !== 1 ||
                Number(groupResult.changes) !== 1
            ) {
                throw new Error(
                    'prepared intent local cancellation protection group CAS failed',
                );
            }
        }
        if (rearmRow !== null) {
            const result = database
                .prepare(`
                    UPDATE intent_rearm_authorizations
                       SET state='superseded', revision=revision+1
                     WHERE rearm_authorization_id=? AND state='active'
                       AND revision=?
                `)
                .run(rearmRow.rearm_authorization_id, rearmRow.revision);
            if (Number(result.changes) !== 1) {
                throw new Error(
                    'prepared intent local cancellation re-arm CAS failed',
                );
            }
        }

        const intentRevision = expectedIntentRevision + 1;
        const activationRevision = expectedActivationRevision + 1;
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: intentId,
            revision: intentRevision,
            reasonCode: 'INTENT_CANCELLED_PROVEN_UNSENT',
            summaryCode: 'intent_cancelled_proven_unsent',
            nowEpochMs: now,
            payloadHash: intent.payload_hash,
            eventSuffix: `local-cancel-${requestId}`,
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'activation',
            entityId: activationId,
            revision: activationRevision,
            reasonCode: 'INTENT_CANCELLED_PROVEN_UNSENT',
            summaryCode: 'activation_cancelled_proven_unsent',
            nowEpochMs: now,
            payloadHash: intent.activation_evidence_hash,
            eventSuffix: `local-cancel-${requestId}`,
        });
        if (reservationRow !== null) {
            insertTransitionJournalEvent(database, {
                entityKind: 'entry_exposure_reservation',
                entityId: reservationRow.reservation_id,
                revision: reservationRow.revision + 1,
                reasonCode: 'ENTRY_RESERVATION_RELEASED',
                summaryCode: 'entry_reservation_released_proven_unsent',
                nowEpochMs: now,
                payloadHash: reservationRow.policy_hash,
                eventSuffix: `local-cancel-${requestId}`,
            });
        }
        if (commitmentRow !== null) {
            insertTransitionJournalEvent(database, {
                entityKind: 'pending_protection_commitment',
                entityId: commitmentRow.commitment_id,
                revision: commitmentRow.revision + 1,
                reasonCode: 'PROTECTION_PLAN_CANCELLED_PROVEN_UNSENT',
                summaryCode: 'protection_plan_released_pre_dispatch',
                nowEpochMs: now,
                payloadHash: intent.payload_hash,
                eventSuffix: `local-cancel-${requestId}`,
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'protection_obligation',
                entityId: obligationRow.obligation_id,
                revision: obligationRow.revision + 1,
                reasonCode: 'ENTRY_ZERO_FILL_TERMINAL',
                summaryCode: 'protection_obligation_zero_fill_terminal',
                nowEpochMs: now,
                payloadHash: intent.payload_hash,
                eventSuffix: `local-cancel-${requestId}`,
            });
        }
        if (claimRow !== null) {
            insertTransitionJournalEvent(database, {
                entityKind: 'exit_claim',
                entityId: claimRow.exit_claim_id,
                revision: claimRow.revision + 1,
                reasonCode: 'EXIT_INTENT_CANCELLED_PROVEN_UNSENT',
                summaryCode: 'exit_claim_released_proven_unsent',
                nowEpochMs: now,
                payloadHash: claimRow.evidence_hash,
                eventSuffix: `local-cancel-${requestId}`,
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'protection_group',
                entityId: protectionGroupRow.protection_group_id,
                revision: protectionGroupRow.group_revision + 1,
                reasonCode: 'PROTECTION_OCO_WINNER_CANCELLED_PROVEN_UNSENT',
                summaryCode: 'protection_oco_group_unknown_after_cancel',
                nowEpochMs: now,
                payloadHash: claimRow.evidence_hash,
                eventSuffix: `local-cancel-${requestId}`,
            });
        }
        if (rearmRow !== null) {
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: intentId,
                revision: intentRevision,
                reasonCode:
                    'PREPARED_INTENT_REARM_SUPERSEDED_BY_LOCAL_CANCELLATION',
                summaryCode: 'prepared_intent_rearm_superseded',
                nowEpochMs: now,
                payloadHash: rearmRow.user_rearm_evidence_hash,
                eventSuffix: `local-cancel-${requestId}-rearm`,
            });
        }
        const authorityEntityId = sha256Canonical(
            {
                authorityKind: PREPARED_INTENT_LOCAL_CANCEL_AUTHORITY_KIND,
                authorityConsumptionId,
            },
            'prepared intent local cancellation authority identity',
        );
        insertTransitionJournalEvent(database, {
            entityKind: 'authority_consumption',
            entityId: authorityEntityId,
            revision: 0,
            reasonCode: 'ONE_TIME_AUTHORITY_DURABLY_CONSUMED',
            summaryCode: 'prepared_intent_local_cancel_authority_consumed',
            nowEpochMs: now,
            payloadHash: authorizationEvidenceHash,
            eventSuffix: 'consumed',
        });

        let strategyState = intent.strategy_state;
        let strategyRevision = intent.strategy_revision;
        const blockers = strategySideEffectBlockers(
            database,
            intent.strategy_id,
        );
        if (blockers.length === 0) {
            const result = database
                .prepare(`
                    UPDATE strategies
                       SET state='cancelled', updated_at_epoch_ms=?,
                           terminal_at_epoch_ms=?, revision=revision+1
                     WHERE strategy_id=? AND state='cancel_pending'
                       AND revision=?
                `)
                .run(
                    now,
                    now,
                    intent.strategy_id,
                    intent.strategy_revision,
                );
            if (Number(result.changes) !== 1) {
                throw new Error(
                    'prepared intent local cancellation strategy CAS failed',
                );
            }
            strategyState = 'cancelled';
            strategyRevision += 1;
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: intent.strategy_id,
                revision: strategyRevision,
                reasonCode: 'STRATEGY_CANCEL_DRAIN_COMPLETE',
                summaryCode: 'strategy_cancel_drain_complete',
                nowEpochMs: now,
                payloadHash: intent.strategy_definition_hash,
                eventSuffix: `local-cancel-${requestId}`,
            });
        }

        const result = {
            schemaVersion:
                'smart-order-prepared-intent-local-cancel-result/2026-08-12.1',
            intentId,
            state: 'cancelled_proven_unsent',
            terminalOutcome: `${intent.operation_kind}_cancelled_proven_unsent`,
            revision: intentRevision,
            activationId,
            activationState: 'cancelled',
            activationRevision,
            reservationId: reservationRow?.reservation_id ?? null,
            reservationState: reservationRow === null ? null : 'released',
            reservationRevision:
                reservationRow === null ? null : reservationRow.revision + 1,
            protectionCommitmentId: commitmentRow?.commitment_id ?? null,
            protectionCommitmentState:
                commitmentRow === null ? null : 'released_pre_dispatch',
            protectionCommitmentRevision:
                commitmentRow === null ? null : commitmentRow.revision + 1,
            protectionObligationId: obligationRow?.obligation_id ?? null,
            protectionObligationState:
                obligationRow === null ? null : 'zero_fill_terminal',
            protectionObligationRevision:
                obligationRow === null ? null : obligationRow.revision + 1,
            exitClaimId: claimRow?.exit_claim_id ?? null,
            exitClaimState: claimRow === null ? null : 'released',
            exitClaimRevision:
                claimRow === null ? null : claimRow.revision + 1,
            rearmAuthorizationId:
                rearmRow?.rearm_authorization_id ?? null,
            rearmState: rearmRow === null ? null : 'superseded',
            rearmRevision: rearmRow === null ? null : rearmRow.revision + 1,
            strategyId: intent.strategy_id,
            strategyState,
            strategyRevision,
            authorizationId,
            authorizationConsumed: true,
            actorKind,
            brokerCallRequired: false,
            adapterAuthorityGranted: false,
            replayed: false,
        };
        if (testOnlyFailReplayCompletionAfterMutation === true) {
            if (process.env.VITEST !== 'true') {
                throw new Error(
                    'test-only replay fault injection is unavailable',
                );
            }
            throw new Error(
                'test replay failure after local cancellation before outcome commit',
            );
        }
        completeRequestReplayInTransaction(database, {
            requestId,
            operationKind: PREPARED_INTENT_LOCAL_CANCEL_OPERATION_KIND,
            payloadHash: actionHash,
            resultStatus: 200,
            result,
            nowEpochMs: now,
        });
        return Object.freeze(result);
    });
}

function preparedIntentDrainCandidate(database, input) {
    if (!exactKeys(input, ['strategyId', 'expectedRevision'])) {
        throw new TypeError('prepared intent drain candidate input is invalid');
    }
    const strategyId = boundedToken(input.strategyId, 'drain.strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'drain.expectedRevision',
    );
    const strategy = database
        .prepare('SELECT state, revision FROM strategies WHERE strategy_id=?')
        .get(strategyId);
    if (
        !strategy ||
        strategy.state !== 'cancel_pending' ||
        strategy.revision !== expectedRevision
    ) {
        throw new Error(
            'prepared intent drain requires the current cancel-pending strategy',
        );
    }
    const intents = database
        .prepare(`
            SELECT intents.intent_id, intents.revision,
                   intents.adapter_authority_granted,
                   intents.dispatch_attempt_nonce, intents.sender_fence,
                   intents.api_generation, intents.runtime_epoch_id,
                   intents.terminal_outcome,
                   activations.activation_id,
                   activations.state AS activation_state,
                   activations.revision AS activation_revision
              FROM order_intents AS intents
              JOIN activations
                ON activations.activation_id=intents.activation_id
             WHERE intents.strategy_id=? AND intents.state='prepared'
               AND intents.adapter_authority_granted=0
               AND intents.dispatch_attempt_nonce IS NULL
               AND intents.sender_fence IS NULL
               AND intents.api_generation IS NULL
               AND intents.runtime_epoch_id IS NULL
               AND intents.terminal_outcome IS NULL
               AND activations.state='prepared'
             ORDER BY intents.intent_id
             LIMIT 2
        `)
        .all(strategyId);
    if (intents.length !== 1) {
        throw new Error(
            'prepared intent drain requires exactly one proven-unsent candidate',
        );
    }
    const intent = intents[0];
    const brokerEvidenceCount = Number(
        database
            .prepare(`
                SELECT
                  (SELECT COUNT(*) FROM broker_orders WHERE intent_id=?) +
                  (SELECT COUNT(*) FROM broker_correlations WHERE intent_id=?)
                    AS count
            `)
            .get(intent.intent_id, intent.intent_id)?.count,
    );
    if (brokerEvidenceCount !== 0) {
        throw new Error('prepared intent drain found broker-side evidence');
    }
    const reservationRows = database
        .prepare(`
            SELECT reservation_id, revision
              FROM entry_exposure_reservations
             WHERE intent_id=? ORDER BY reservation_id
        `)
        .all(intent.intent_id);
    const protectionRows = database
        .prepare(`
            SELECT commitments.commitment_id,
                   commitments.revision AS commitment_revision,
                   obligations.obligation_id,
                   obligations.revision AS obligation_revision
              FROM pending_protection_commitments AS commitments
              JOIN protection_obligations AS obligations
                ON obligations.commitment_id=commitments.commitment_id
             WHERE commitments.entry_intent_id=?
             ORDER BY commitments.commitment_id, obligations.obligation_id
        `)
        .all(intent.intent_id);
    const claimRows = database
        .prepare(`
            SELECT exit_claim_id, revision
              FROM exit_claims WHERE intent_id=? ORDER BY exit_claim_id
        `)
        .all(intent.intent_id);
    const rearmRows = database
        .prepare(`
            SELECT rearm_authorization_id, revision
              FROM intent_rearm_authorizations
             WHERE intent_id=? AND state='active'
             ORDER BY rearm_authorization_id
        `)
        .all(intent.intent_id);
    if (
        reservationRows.length > 1 ||
        protectionRows.length > 1 ||
        claimRows.length > 1 ||
        rearmRows.length > 1
    ) {
        throw new Error('prepared intent drain companion cardinality is invalid');
    }
    const cancelAuthorities = database
        .prepare(`
            SELECT request_id, payload_hash, result_json
              FROM request_replays
             WHERE operation_kind='strategy_cancel' AND state='completed'
               AND result_status=200
             ORDER BY updated_at_epoch_ms DESC, request_id
             LIMIT 1000
        `)
        .all();
    let authority;
    for (const candidate of cancelAuthorities) {
        const result = parseStoredCanonicalObject(
            candidate.result_json,
            'strategy cancel authority result',
        );
        if (
            result.strategyId === strategyId &&
            result.state === 'cancel_pending' &&
            result.revision === expectedRevision
        ) {
            authority = candidate;
            break;
        }
    }
    if (!authority) {
        throw new Error(
            'prepared intent drain lacks current durable strategy-cancel authority',
        );
    }
    const reservation = reservationRows[0] ?? null;
    const protection = protectionRows[0] ?? null;
    const claim = claimRows[0] ?? null;
    const rearm = rearmRows[0] ?? null;
    return Object.freeze({
        authorization: Object.freeze({
            authorizationId: authority.request_id,
            evidenceHash: authority.payload_hash,
            actorKind: 'interactive_user',
            lifecycleOperationId: null,
        }),
        intentId: intent.intent_id,
        expectedIntentRevision: intent.revision,
        activation: Object.freeze({
            activationId: intent.activation_id,
            expectedRevision: intent.activation_revision,
        }),
        reservation:
            reservation === null
                ? null
                : Object.freeze({
                      reservationId: reservation.reservation_id,
                      expectedRevision: reservation.revision,
                  }),
        protection:
            protection === null
                ? null
                : Object.freeze({
                      commitmentId: protection.commitment_id,
                      expectedCommitmentRevision:
                          protection.commitment_revision,
                      obligationId: protection.obligation_id,
                      expectedObligationRevision:
                          protection.obligation_revision,
                  }),
        exitClaim:
            claim === null
                ? null
                : Object.freeze({
                      exitClaimId: claim.exit_claim_id,
                      expectedRevision: claim.revision,
                  }),
        rearm:
            rearm === null
                ? null
                : Object.freeze({
                      rearmAuthorizationId: rearm.rearm_authorization_id,
                      expectedRevision: rearm.revision,
                  }),
    });
}

function drainPreparedIntentProvenUnsentByStrategy(database, input) {
    if (
        !exactKeys(input, [
            'requestId',
            'strategyId',
            'expectedRevision',
            'nowEpochMs',
        ])
    ) {
        throw new TypeError('typed prepared intent drain input is invalid');
    }
    const requestId = boundedToken(input.requestId, 'drain.requestId');
    const strategyId = boundedToken(input.strategyId, 'drain.strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'drain.expectedRevision',
    );
    const nowEpochMs = safeInteger(input.nowEpochMs, 'drain.nowEpochMs');
    const replay = database
        .prepare(`
            SELECT operation_kind, state, result_status, result_json
              FROM request_replays WHERE request_id=?
        `)
        .get(requestId);
    if (replay) {
        if (
            replay.operation_kind !== PREPARED_INTENT_LOCAL_CANCEL_OPERATION_KIND ||
            replay.state !== 'completed' ||
            replay.result_status !== 200
        ) {
            throw new Error('typed prepared intent drain replay is unresolved');
        }
        const result = parseStoredCanonicalObject(
            replay.result_json,
            'typed prepared intent drain replay result',
        );
        if (
            result.strategyId !== strategyId ||
            result.strategyRevision < expectedRevision ||
            result.state !== 'cancelled_proven_unsent'
        ) {
            throw new Error('typed prepared intent drain replay scope changed');
        }
        return Object.freeze({ ...result, replayed: true });
    }
    const candidate = preparedIntentDrainCandidate(database, {
        strategyId,
        expectedRevision,
    });
    return cancelPreparedIntentProvenUnsent(database, {
        requestId,
        ...candidate,
        nowEpochMs,
    });
}

const PROTECTION_RELINQUISH_PREPARE_OPERATION_KIND =
    'strategy_protection_relinquish_prepare';
const PROTECTION_RELINQUISH_COMMIT_OPERATION_KIND =
    'strategy_protection_relinquish_commit';
const PROTECTION_RELINQUISH_AUTHORITY_KIND =
    'protection_break_glass_relinquish';

function protectionRelinquishmentSnapshot(database, strategyId, expectedRevision) {
    const strategy = database
        .prepare(`
            SELECT strategy_id, state, revision, definition_hash,
                   confirmation_snapshot_hash
              FROM strategies WHERE strategy_id=?
        `)
        .get(strategyId);
    if (
        !strategy ||
        strategy.revision !== expectedRevision ||
        ![
            'paused',
            'recovery',
            'manual_intervention',
            'cancel_pending',
            'expired_with_obligation',
        ].includes(strategy.state)
    ) {
        throw new Error(
            'protection relinquishment requires a current non-terminal blocked strategy',
        );
    }
    const obligations = database
        .prepare(`
            SELECT obligations.obligation_id, obligations.commitment_id,
                   obligations.state, obligations.position_lineage_id,
                   obligations.filled_shares,
                   obligations.confirmed_exited_shares,
                   obligations.revision,
                   commitments.entry_intent_id,
                   intents.operation_kind,
                   intents.state AS entry_intent_state,
                   intents.revision AS entry_intent_revision,
                   intents.account_broker_ref,
                   intents.account_id_ref, intents.trade_date,
                   intents.contract_key, intents.side,
                   strategies.identity_group_id
              FROM protection_obligations AS obligations
              JOIN pending_protection_commitments AS commitments
                ON commitments.commitment_id=obligations.commitment_id
              JOIN order_intents AS intents
                ON intents.intent_id=commitments.entry_intent_id
              JOIN strategies
                ON strategies.strategy_id=obligations.strategy_id
             WHERE obligations.strategy_id=?
               AND obligations.state NOT IN (
                   'fulfilled','zero_fill_terminal','released_manual'
               )
             ORDER BY obligations.obligation_id
        `)
        .all(strategyId);
    if (obligations.length === 0) {
        throw new Error('strategy has no active protection obligation to relinquish');
    }
    const commitments = database
        .prepare(`
            SELECT commitment_id, state, committed_shares,
                   materialized_shares, revision
             FROM pending_protection_commitments
             WHERE strategy_id=?
               AND state NOT IN ('materialized','zero_fill_terminal',
                                 'released_pre_dispatch','released_manual')
             ORDER BY commitment_id
        `)
        .all(strategyId);
    const reservations = database
        .prepare(`
            SELECT reservation_id, intent_id, state, quantity_shares,
                   notional_minor_units, cash_minor_units, position_shares,
                   order_count, policy_hash, revision
              FROM entry_exposure_reservations
             WHERE strategy_id=? AND state NOT IN ('consumed','released')
             ORDER BY reservation_id
        `)
        .all(strategyId);
    const claims = database
        .prepare(`
            SELECT claims.exit_claim_id, claims.obligation_id,
                   claims.intent_id, claims.state, claims.quantity_shares,
                   claims.evidence_hash, claims.revision
              FROM exit_claims AS claims
              JOIN protection_obligations AS obligations
                ON obligations.obligation_id=claims.obligation_id
             WHERE obligations.strategy_id=?
               AND claims.external_lineage=0
               AND claims.state NOT IN ('consumed','released')
             ORDER BY claims.exit_claim_id
        `)
        .all(strategyId);
    const sideEffectIntents = database
        .prepare(`
            SELECT intent_id, operation_kind, state, revision,
                   adapter_authority_granted, account_broker_ref,
                   account_id_ref, trade_date, contract_key, side
              FROM order_intents
             WHERE strategy_id=?
               AND state NOT IN ('terminal','cancelled_proven_unsent')
             ORDER BY intent_id
        `)
        .all(strategyId);
    const brokerOrders = database
        .prepare(`
            SELECT orders.broker_order_id, orders.intent_id, orders.state,
                   orders.remaining_shares, orders.control_revision,
                   orders.revision, intents.operation_kind,
                   intents.account_broker_ref, intents.account_id_ref,
                   intents.trade_date, intents.contract_key, intents.side
              FROM broker_orders AS orders
              JOIN order_intents AS intents
                ON intents.intent_id=orders.intent_id
             WHERE intents.strategy_id=?
               AND orders.state NOT IN ('filled','cancelled','failed','inactive')
             ORDER BY orders.broker_order_id
        `)
        .all(strategyId);
    for (const intent of sideEffectIntents) {
        if (
            intent.state === 'prepared' &&
            intent.adapter_authority_granted === 0
        ) {
            const brokerEvidence = Number(
                database
                    .prepare(`
                        SELECT
                          (SELECT COUNT(*) FROM broker_orders WHERE intent_id=?) +
                          (SELECT COUNT(*) FROM broker_correlations WHERE intent_id=?)
                            AS count
                    `)
                    .get(intent.intent_id, intent.intent_id)?.count,
            );
            if (brokerEvidence === 0) {
                throw new Error(
                    'proven-unsent prepared intent requires the local drain action',
                );
            }
        }
    }
    const exposureScopes = obligations.map((obligation) => {
        const scopeMembers = [
            `account:${sha256Canonical(
                [obligation.account_broker_ref, obligation.account_id_ref],
                'relinquished exposure account member',
            )}`,
            `contract:${sha256Canonical(
                obligation.contract_key,
                'relinquished exposure contract member',
            )}`,
            `obligation:${sha256Canonical(
                obligation.obligation_id,
                'relinquished exposure obligation member',
            )}`,
            `position:${sha256Canonical(
                obligation.position_lineage_id,
                'relinquished exposure position member',
            )}`,
        ].sort();
        const intentLineage = [
            {
                intentId: obligation.entry_intent_id,
                operationKind: obligation.operation_kind,
                state: obligation.entry_intent_state,
                revision: obligation.entry_intent_revision,
            },
            ...sideEffectIntents
                .filter(
                    (intent) =>
                        intent.intent_id !== obligation.entry_intent_id &&
                        intent.account_broker_ref ===
                            obligation.account_broker_ref &&
                        intent.account_id_ref === obligation.account_id_ref &&
                        intent.contract_key === obligation.contract_key,
                )
                .map((intent) => ({
                    intentId: intent.intent_id,
                    operationKind: intent.operation_kind,
                    state: intent.state,
                    revision: intent.revision,
                })),
        ].sort((left, right) => left.intentId.localeCompare(right.intentId));
        const uncertainClaimShares = claims
            .filter(
                (claim) => claim.obligation_id === obligation.obligation_id,
            )
            .reduce((sum, claim) => sum + claim.quantity_shares, 0);
        const possibleBrokerWorkingShares = brokerOrders
            .filter(
                (order) =>
                    order.account_broker_ref === obligation.account_broker_ref &&
                    order.account_id_ref === obligation.account_id_ref &&
                    order.contract_key === obligation.contract_key,
            )
            .reduce((sum, order) => sum + order.remaining_shares, 0);
        const worstCasePositionDeltaShares = Math.max(
            0,
            obligation.filled_shares - obligation.confirmed_exited_shares,
        );
        return Object.freeze({
            obligationId: obligation.obligation_id,
            operationKind: obligation.operation_kind,
            intentLineage: Object.freeze(intentLineage),
            intentLineageHash: sha256Canonical(
                intentLineage,
                'relinquished exposure intent lineage',
            ),
            accountBrokerRef: obligation.account_broker_ref,
            accountIdRef: obligation.account_id_ref,
            identityGroupId: obligation.identity_group_id,
            tradeDate: obligation.trade_date,
            contractKey: obligation.contract_key,
            side: obligation.side,
            positionLineageId: obligation.position_lineage_id,
            scopeMembers: Object.freeze(scopeMembers),
            scopeMembersHash: sha256Canonical(
                scopeMembers,
                'relinquished exposure scope members',
            ),
            worstCasePositionDeltaShares,
            possiblyWorkingShares: Math.max(
                worstCasePositionDeltaShares,
                uncertainClaimShares,
                possibleBrokerWorkingShares,
            ),
            claimUncertaintyCount: claims.filter(
                (claim) => claim.obligation_id === obligation.obligation_id,
            ).length,
        });
    });
    const snapshot = Object.freeze({
        schemaVersion:
            'smart-order-protection-relinquishment-snapshot/2026-08-13.1',
        strategy: Object.freeze({
            strategyId: strategy.strategy_id,
            state: strategy.state,
            revision: strategy.revision,
            definitionHash: strategy.definition_hash,
            confirmationSnapshotHash: strategy.confirmation_snapshot_hash,
        }),
        obligations: Object.freeze(obligations.map((row) => Object.freeze({ ...row }))),
        commitments: Object.freeze(commitments.map((row) => Object.freeze({ ...row }))),
        reservations: Object.freeze(reservations.map((row) => Object.freeze({ ...row }))),
        claims: Object.freeze(claims.map((row) => Object.freeze({ ...row }))),
        sideEffectIntents: Object.freeze(
            sideEffectIntents.map((row) => Object.freeze({ ...row })),
        ),
        brokerOrders: Object.freeze(
            brokerOrders.map((row) => Object.freeze({ ...row })),
        ),
        exposureScopes: Object.freeze(exposureScopes),
    });
    const handoffSnapshotHash = sha256Canonical(
        snapshot,
        'protection relinquishment handoff snapshot',
    );
    const counts = Object.freeze({
        obligationCount: obligations.length,
        commitmentCount: commitments.length,
        reservationCount: reservations.length,
        exitClaimCount: claims.length,
        sideEffectIntentCount: sideEffectIntents.length,
        brokerOrderCount: brokerOrders.length,
    });
    const unmonitoredAuditHash = sha256Canonical(
        {
            schemaVersion:
                'smart-order-protection-unmonitored-audit/2026-08-13.1',
            strategyId,
            expectedRevision,
            handoffSnapshotHash,
            counts,
            brokerOutcomeInferred: false,
            originalIntentRedispatchAllowed: false,
        },
        'protection relinquishment audit',
    );
    return Object.freeze({
        snapshot,
        handoffSnapshotHash,
        unmonitoredAuditHash,
        counts,
    });
}

function prepareProtectionRelinquishment(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'requestId',
            'strategyId',
            'expectedRevision',
            'confirmationEvidenceHash',
            'nowEpochMs',
        ])
    ) {
        throw new TypeError('protection relinquishment preparation input is invalid');
    }
    const requestId = boundedToken(input.requestId, 'relinquish.requestId');
    const strategyId = boundedToken(input.strategyId, 'relinquish.strategyId');
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'relinquish.expectedRevision',
    );
    const confirmationEvidenceHash = sha256Digest(
        input.confirmationEvidenceHash,
        'relinquish.confirmationEvidenceHash',
    );
    const now = safeInteger(input.nowEpochMs, 'relinquish.nowEpochMs');
    const payloadHash = sha256Canonical(
        {
            schemaVersion:
                'smart-order-protection-relinquishment-prepare/2026-08-13.1',
            requestId,
            strategyId,
            expectedRevision,
            confirmationEvidenceHash,
        },
        'protection relinquishment preparation',
    );
    return transaction(database, () => {
        const replay = reserveRequestReplayInTransaction(database, {
            requestId,
            operationKind: PROTECTION_RELINQUISH_PREPARE_OPERATION_KIND,
            payloadHash,
            nowEpochMs: now,
        });
        if (replay.replayed) {
            if (replay.state !== 'completed') {
                throw new Error('protection relinquishment preparation is unresolved');
            }
            return Object.freeze({ ...replay.result, replayed: true });
        }
        if (lifecycleMutationFenceOperation(database) !== undefined) {
            throw new Error('protection relinquishment cannot cross a lifecycle fence');
        }
        const current = protectionRelinquishmentSnapshot(
            database,
            strategyId,
            expectedRevision,
        );
        assertManualResolutionOperationAllowed(database, {
            strategyId,
            strategyState: current.snapshot.strategy.state,
            operation: 'break_glass_relinquish',
        });
        const result = Object.freeze({
            schemaVersion:
                'smart-order-protection-relinquishment-challenge/2026-08-13.1',
            challengeId: requestId,
            challengeEvidenceHash: confirmationEvidenceHash,
            strategyId,
            strategyRevision: expectedRevision,
            handoffSnapshotHash: current.handoffSnapshotHash,
            unmonitoredAuditHash: current.unmonitoredAuditHash,
            ...current.counts,
            relinquished: false,
            brokerWriteAttempted: false,
            brokerOutcomeInferred: false,
            replayed: false,
        });
        completeRequestReplayInTransaction(database, {
            requestId,
            operationKind: PROTECTION_RELINQUISH_PREPARE_OPERATION_KIND,
            payloadHash,
            resultStatus: 200,
            result,
            nowEpochMs: now,
        });
        return result;
    });
}

function commitProtectionRelinquishment(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'requestId',
            'challengeId',
            'strategyId',
            'expectedRevision',
            'confirmationEvidenceHash',
            'operatorAcknowledgedManualHandoff',
            'nowEpochMs',
        ])
    ) {
        throw new TypeError('protection relinquishment commit input is invalid');
    }
    const requestId = boundedToken(input.requestId, 'relinquishCommit.requestId');
    const challengeId = boundedToken(
        input.challengeId,
        'relinquishCommit.challengeId',
    );
    if (requestId === challengeId) {
        throw new TypeError('protection relinquishment confirmations must be distinct');
    }
    const strategyId = boundedToken(
        input.strategyId,
        'relinquishCommit.strategyId',
    );
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'relinquishCommit.expectedRevision',
    );
    const confirmationEvidenceHash = sha256Digest(
        input.confirmationEvidenceHash,
        'relinquishCommit.confirmationEvidenceHash',
    );
    if (input.operatorAcknowledgedManualHandoff !== true) {
        throw new TypeError('manual protection handoff must be acknowledged');
    }
    const now = safeInteger(input.nowEpochMs, 'relinquishCommit.nowEpochMs');
    return transaction(database, () => {
        const existingReplay = database
            .prepare(`
                SELECT operation_kind, state, result_status, result_json
                  FROM request_replays WHERE request_id=?
            `)
            .get(requestId);
        if (existingReplay) {
            if (
                existingReplay.operation_kind !==
                    PROTECTION_RELINQUISH_COMMIT_OPERATION_KIND ||
                existingReplay.state !== 'completed' ||
                existingReplay.result_status !== 200
            ) {
                throw new Error('protection relinquishment commit is unresolved');
            }
            const result = parseStoredCanonicalObject(
                existingReplay.result_json,
                'protection relinquishment replay result',
            );
            const replayAuthorityId = sha256Canonical(
                { challengeId, requestId, strategyId },
                'protection relinquishment authority identity',
            );
            const replayAuthority = database
                .prepare(`
                    SELECT authority_payload_hash, scope_hash
                      FROM authority_consumptions
                     WHERE authority_kind=? AND authority_id=?
                `)
                .get(
                    PROTECTION_RELINQUISH_AUTHORITY_KIND,
                    replayAuthorityId,
                );
            if (
                result.strategyId !== strategyId ||
                result.strategyRevision < expectedRevision ||
                result.relinquished !== true ||
                result.authorizationConsumed !== true ||
                !replayAuthority ||
                replayAuthority.authority_payload_hash !==
                    confirmationEvidenceHash ||
                replayAuthority.scope_hash !== result.handoffSnapshotHash
            ) {
                throw new Error('protection relinquishment replay scope changed');
            }
            return Object.freeze({ ...result, replayed: true });
        }
        if (lifecycleMutationFenceOperation(database) !== undefined) {
            throw new Error('protection relinquishment cannot cross a lifecycle fence');
        }
        const challengeReplay = database
            .prepare(`
                SELECT operation_kind, payload_hash, result_json, state,
                       result_status
                  FROM request_replays WHERE request_id=?
            `)
            .get(challengeId);
        if (
            !challengeReplay ||
            challengeReplay.operation_kind !==
                PROTECTION_RELINQUISH_PREPARE_OPERATION_KIND ||
            challengeReplay.state !== 'completed' ||
            challengeReplay.result_status !== 200
        ) {
            throw new Error('protection relinquishment challenge is not current');
        }
        const challenge = parseStoredCanonicalObject(
            challengeReplay.result_json,
            'protection relinquishment challenge result',
        );
        if (
            challenge.strategyId !== strategyId ||
            challenge.strategyRevision !== expectedRevision ||
            challenge.challengeId !== challengeId ||
            challenge.relinquished !== false
        ) {
            throw new Error('protection relinquishment challenge scope is invalid');
        }
        const firstEvidenceHash = sha256Digest(
            challenge.challengeEvidenceHash,
            'relinquishCommit.challengeEvidenceHash',
        );
        if (firstEvidenceHash === confirmationEvidenceHash) {
            throw new Error('protection relinquishment confirmations are not distinct');
        }
        const current = protectionRelinquishmentSnapshot(
            database,
            strategyId,
            expectedRevision,
        );
        assertManualResolutionOperationAllowed(database, {
            strategyId,
            strategyState: current.snapshot.strategy.state,
            operation: 'break_glass_relinquish',
        });
        if (
            challenge.handoffSnapshotHash !== current.handoffSnapshotHash ||
            challenge.unmonitoredAuditHash !== current.unmonitoredAuditHash
        ) {
            throw new Error('protection relinquishment snapshot changed');
        }
        const payloadHash = sha256Canonical(
            {
                schemaVersion:
                    'smart-order-protection-relinquishment-commit/2026-08-13.1',
                requestId,
                challengeId,
                strategyId,
                expectedRevision,
                firstEvidenceHash,
                confirmationEvidenceHash,
                handoffSnapshotHash: current.handoffSnapshotHash,
                unmonitoredAuditHash: current.unmonitoredAuditHash,
                operatorAcknowledgedManualHandoff: true,
            },
            'protection relinquishment commit',
        );
        const replay = reserveRequestReplayInTransaction(database, {
            requestId,
            operationKind: PROTECTION_RELINQUISH_COMMIT_OPERATION_KIND,
            payloadHash,
            nowEpochMs: now,
        });
        if (replay.replayed) {
            if (replay.state !== 'completed') {
                throw new Error('protection relinquishment commit is unresolved');
            }
            return Object.freeze({ ...replay.result, replayed: true });
        }
        for (const obligation of current.snapshot.obligations) {
            const activeExitClaimCount = current.snapshot.claims.filter(
                (claim) => claim.obligation_id === obligation.obligation_id,
            ).length;
            const decision = evaluateProtectionObligationRelease({
                path: 'break_glass_relinquish',
                entryTerminal: false,
                filledShares: obligation.filled_shares,
                confirmedExitedShares: obligation.confirmed_exited_shares,
                positionShares: 0,
                brokerEvidenceHash: null,
                accountReconciliationEvidenceHash: null,
                resources: {
                    activeEntryReservationCount:
                        current.snapshot.reservations.length,
                    activeExitClaimCount,
                    atomicReleasePrepared: true,
                },
                breakGlass: {
                    confirmationEvidenceHashes: [
                        firstEvidenceHash,
                        confirmationEvidenceHash,
                    ],
                    handoffSnapshotHash: current.handoffSnapshotHash,
                    unmonitoredAuditHash: current.unmonitoredAuditHash,
                    operatorAcknowledgedManualHandoff: true,
                },
            });
            if (
                decision.allowed !== true ||
                decision.brokerOutcomeInferred !== false ||
                decision.unmonitored !== true
            ) {
                throw new Error('protection relinquishment policy rejected the handoff');
            }
        }
        resolveManualCasesForBreakGlass(database, {
            strategyId,
            strategyState: current.snapshot.strategy.state,
            evidenceHash: current.handoffSnapshotHash,
            nowEpochMs: now,
        });
        const authorityId = sha256Canonical(
            { challengeId, requestId, strategyId },
            'protection relinquishment authority identity',
        );
        database
            .prepare(`
                INSERT INTO authority_consumptions(
                    authority_kind, authority_id, authority_payload_hash,
                    scope_hash, consumed_by, runtime_epoch_id,
                    consumed_at_epoch_ms
                ) VALUES (?, ?, ?, ?, 'interactive_user', NULL, ?)
            `)
            .run(
                PROTECTION_RELINQUISH_AUTHORITY_KIND,
                authorityId,
                confirmationEvidenceHash,
                current.handoffSnapshotHash,
                now,
            );
        const openedBlockers = [];
        for (const exposure of current.snapshot.exposureScopes) {
            const identity = sha256Canonical(
                {
                    requestId,
                    strategyId,
                    obligationId: exposure.obligationId,
                    scopeMembersHash: exposure.scopeMembersHash,
                    handoffSnapshotHash: current.handoffSnapshotHash,
                },
                'relinquished unknown exposure identity',
            ).slice('sha256:'.length);
            const resolutionCaseId = `resolution-${identity}`;
            const blockerId = `blocker-${identity}`;
            const exposureId = `relinquished-${identity}`;
            const scopeHash = sha256Canonical(
                {
                    schemaVersion:
                        'smart-order-relinquished-unknown-exposure-scope/2026-08-13.1',
                    accountBrokerRef: exposure.accountBrokerRef,
                    accountIdRef: exposure.accountIdRef,
                    identityGroupId: exposure.identityGroupId,
                    tradeDate: exposure.tradeDate,
                    contractKey: exposure.contractKey,
                    side: exposure.side,
                    positionLineageId: exposure.positionLineageId,
                    scopeMembers: exposure.scopeMembers,
                    worstCasePositionDeltaShares:
                        exposure.worstCasePositionDeltaShares,
                    possiblyWorkingShares: exposure.possiblyWorkingShares,
                },
                'relinquished unknown exposure scope',
            );
            database
                .prepare(`
                    INSERT INTO resolution_cases(
                        resolution_case_id, strategy_id, reason_code,
                        scope_hash, evidence_snapshot_hash, state,
                        created_at_epoch_ms, updated_at_epoch_ms,
                        terminal_at_epoch_ms, revision
                    ) VALUES (?, ?, 'BROKER_OUTCOME_UNKNOWN', ?, ?,
                              'relinquished_unknown', ?, ?, ?, 0)
                `)
                .run(
                    resolutionCaseId,
                    strategyId,
                    scopeHash,
                    current.handoffSnapshotHash,
                    now,
                    now,
                    now,
                );
            database
                .prepare(`
                    INSERT INTO safety_blockers(
                        blocker_id, resolution_case_id, scope_hash,
                        reason_code, state, created_at_epoch_ms,
                        resolved_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, 'RELINQUISHED_UNKNOWN_EXPOSURE',
                              'open', ?, NULL, 0)
                `)
                .run(blockerId, resolutionCaseId, scopeHash, now);
            database
                .prepare(`
                    INSERT INTO relinquished_unknown_exposures(
                        exposure_id, blocker_id, resolution_case_id,
                        operation_kind, intent_lineage_json,
                        intent_lineage_hash, account_broker_ref,
                        account_id_ref, identity_group_id, trade_date,
                        contract_key, side, position_lineage_id,
                        scope_members_json, scope_members_hash,
                        worst_case_position_delta_shares,
                        possibly_working_shares, pnl_uncertainty,
                        claim_uncertainty_count, evidence_snapshot_hash,
                        first_confirmation_hash, second_confirmation_hash,
                        actor_kind, created_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                              ?, ?, 1, ?, ?, ?, ?, 'interactive_user', ?, 0)
                `)
                .run(
                    exposureId,
                    blockerId,
                    resolutionCaseId,
                    exposure.operationKind,
                    stableCanonicalJson(exposure.intentLineage),
                    exposure.intentLineageHash,
                    exposure.accountBrokerRef,
                    exposure.accountIdRef,
                    exposure.identityGroupId,
                    exposure.tradeDate,
                    exposure.contractKey,
                    exposure.side,
                    exposure.positionLineageId,
                    stableCanonicalJson(exposure.scopeMembers),
                    exposure.scopeMembersHash,
                    exposure.worstCasePositionDeltaShares,
                    exposure.possiblyWorkingShares,
                    exposure.claimUncertaintyCount,
                    current.handoffSnapshotHash,
                    firstEvidenceHash,
                    confirmationEvidenceHash,
                    now,
                );
            insertTransitionJournalEvent(database, {
                entityKind: 'resolution_case',
                entityId: resolutionCaseId,
                revision: 0,
                reasonCode: 'MANUAL_BREAK_GLASS_RELINQUISHED',
                summaryCode: 'resolution_case_relinquished_unknown',
                nowEpochMs: now,
                payloadHash: current.handoffSnapshotHash,
                eventSuffix: `relinquish-${requestId}`,
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'safety_blocker',
                entityId: blockerId,
                revision: 0,
                reasonCode: 'RELINQUISHED_UNKNOWN_EXPOSURE_OPENED',
                summaryCode: 'relinquished_unknown_exposure_opened',
                nowEpochMs: now,
                payloadHash: scopeHash,
                eventSuffix: `relinquish-${requestId}`,
            });
            openedBlockers.push(
                Object.freeze({
                    blockerId,
                    resolutionCaseId,
                    exposureId,
                    scopeHash,
                }),
            );
        }
        if (openedBlockers.length !== current.snapshot.obligations.length) {
            throw new Error(
                'every relinquished obligation requires an unknown exposure blocker',
            );
        }
        for (const intent of current.snapshot.sideEffectIntents) {
            const terminalOutcome = `${intent.operation_kind}_relinquished_unknown`;
            const updated = database
                .prepare(`
                    UPDATE order_intents
                       SET state='terminal', terminal_outcome=?,
                           updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                           revision=revision+1
                     WHERE intent_id=?
                       AND state NOT IN ('terminal','cancelled_proven_unsent')
                       AND revision=?
                `)
                .run(
                    terminalOutcome,
                    now,
                    now,
                    intent.intent_id,
                    intent.revision,
                );
            if (Number(updated.changes) !== 1) {
                throw new Error('relinquished intent CAS failed');
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: intent.intent_id,
                revision: intent.revision + 1,
                reasonCode: 'MANUAL_BREAK_GLASS_RELINQUISHED',
                summaryCode: 'intent_relinquished_unknown_no_redispatch',
                nowEpochMs: now,
                payloadHash: current.unmonitoredAuditHash,
                eventSuffix: `relinquish-${requestId}`,
            });
        }
        advanceLifecycleSideEffectRevision(database);
        for (const claim of current.snapshot.claims) {
            const updated = database
                .prepare(`
                    UPDATE exit_claims
                       SET state='released', updated_at_epoch_ms=?,
                           terminal_at_epoch_ms=?, revision=revision+1
                     WHERE exit_claim_id=? AND external_lineage=0
                       AND state NOT IN ('consumed','released') AND revision=?
                `)
                .run(now, now, claim.exit_claim_id, claim.revision);
            if (Number(updated.changes) !== 1) {
                throw new Error('protection relinquishment exit claim CAS failed');
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'exit_claim',
                entityId: claim.exit_claim_id,
                revision: claim.revision + 1,
                reasonCode: 'PROTECTION_BREAK_GLASS_RELINQUISHED',
                summaryCode: 'exit_claim_released_manual_unmonitored',
                nowEpochMs: now,
                payloadHash: current.unmonitoredAuditHash,
                eventSuffix: `relinquish-${requestId}`,
            });
        }
        for (const reservation of current.snapshot.reservations) {
            const updated = database
                .prepare(`
                    UPDATE entry_exposure_reservations
                       SET state='released', updated_at_epoch_ms=?,
                           terminal_at_epoch_ms=?, revision=revision+1
                     WHERE reservation_id=?
                       AND state NOT IN ('consumed','released') AND revision=?
                `)
                .run(now, now, reservation.reservation_id, reservation.revision);
            if (Number(updated.changes) !== 1) {
                throw new Error('protection relinquishment reservation CAS failed');
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'entry_exposure_reservation',
                entityId: reservation.reservation_id,
                revision: reservation.revision + 1,
                reasonCode: 'PROTECTION_BREAK_GLASS_RELINQUISHED',
                summaryCode: 'entry_reservation_released_manual_unmonitored',
                nowEpochMs: now,
                payloadHash: current.unmonitoredAuditHash,
                eventSuffix: `relinquish-${requestId}`,
            });
        }
        for (const commitment of current.snapshot.commitments) {
            const updated = database
                .prepare(`
                    UPDATE pending_protection_commitments
                       SET state='released_manual', updated_at_epoch_ms=?,
                           revision=revision+1
                     WHERE commitment_id=?
                       AND state NOT IN ('materialized','zero_fill_terminal',
                                        'released_pre_dispatch','released_manual')
                       AND revision=?
                `)
                .run(now, commitment.commitment_id, commitment.revision);
            if (Number(updated.changes) !== 1) {
                throw new Error('protection relinquishment commitment CAS failed');
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'pending_protection_commitment',
                entityId: commitment.commitment_id,
                revision: commitment.revision + 1,
                reasonCode: 'PROTECTION_BREAK_GLASS_RELINQUISHED',
                summaryCode: 'protection_commitment_released_manual_unmonitored',
                nowEpochMs: now,
                payloadHash: current.unmonitoredAuditHash,
                eventSuffix: `relinquish-${requestId}`,
            });
        }
        for (const obligation of current.snapshot.obligations) {
            const updated = database
                .prepare(`
                    UPDATE protection_obligations
                       SET state='released_manual', updated_at_epoch_ms=?,
                           terminal_at_epoch_ms=?, revision=revision+1
                     WHERE obligation_id=?
                       AND state NOT IN ('fulfilled','zero_fill_terminal',
                                        'released_manual')
                       AND revision=?
                `)
                .run(now, now, obligation.obligation_id, obligation.revision);
            if (Number(updated.changes) !== 1) {
                throw new Error('protection relinquishment obligation CAS failed');
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'protection_obligation',
                entityId: obligation.obligation_id,
                revision: obligation.revision + 1,
                reasonCode: 'PROTECTION_BREAK_GLASS_RELINQUISHED',
                summaryCode: 'protection_obligation_released_manual_unmonitored',
                nowEpochMs: now,
                payloadHash: current.unmonitoredAuditHash,
                eventSuffix: `relinquish-${requestId}`,
            });
        }
        insertTransitionJournalEvent(database, {
            entityKind: 'authority_consumption',
            entityId: authorityId,
            revision: 0,
            reasonCode: 'ONE_TIME_AUTHORITY_DURABLY_CONSUMED',
            summaryCode: 'protection_break_glass_authority_consumed',
            nowEpochMs: now,
            payloadHash: current.unmonitoredAuditHash,
            eventSuffix: 'consumed',
        });
        const strategy = database
            .prepare('SELECT state, revision FROM strategies WHERE strategy_id=?')
            .get(strategyId);
        let strategyState = strategy.state;
        let strategyRevision = strategy.revision;
        if (
            strategy.state === 'cancel_pending' &&
            strategySideEffectBlockers(database, strategyId).length === 0
        ) {
            const updated = database
                .prepare(`
                    UPDATE strategies
                       SET state='cancelled', updated_at_epoch_ms=?,
                           terminal_at_epoch_ms=?, revision=revision+1
                     WHERE strategy_id=? AND state='cancel_pending'
                       AND revision=?
                `)
                .run(now, now, strategyId, strategy.revision);
            if (Number(updated.changes) !== 1) {
                throw new Error('protection relinquishment strategy CAS failed');
            }
            strategyState = 'cancelled';
            strategyRevision += 1;
        }
        const result = Object.freeze({
            schemaVersion:
                'smart-order-protection-relinquishment-result/2026-08-13.1',
            strategyId,
            strategyState,
            strategyRevision,
            handoffSnapshotHash: current.handoffSnapshotHash,
            unmonitoredAuditHash: current.unmonitoredAuditHash,
            ...current.counts,
            safetyBlockerCount: openedBlockers.length,
            authorizationConsumed: true,
            relinquished: true,
            unmonitored: true,
            brokerOutcomeInferred: false,
            originalIntentRedispatchAllowed: false,
            brokerWriteAttempted: false,
            replayed: false,
        });
        completeRequestReplayInTransaction(database, {
            requestId,
            operationKind: PROTECTION_RELINQUISH_COMMIT_OPERATION_KIND,
            payloadHash,
            resultStatus: 200,
            result,
            nowEpochMs: now,
        });
        return result;
    });
}

const BROKER_EVENT_STATUS_TO_ORDER_STATE = Object.freeze({
    PendingSubmit: 'pending_submit',
    PreSubmitted: 'pre_submitted',
    Submitted: 'submitted',
    PartFilled: 'part_filled',
});

function durableOriginatingIntentContractUnit(brokerOrder) {
    const payload = canonicalIntentPayload(
        brokerOrder.originating_payload_json,
        'dispatch target originating intent payload',
    );
    if (
        sha256Canonical(
            payload,
            'dispatch target originating intent payload',
        ) !== brokerOrder.originating_payload_hash
    ) {
        throw new Error(
            'dispatch target originating intent payload hash is inconsistent',
        );
    }
    let contractUnit;
    let contractKey = brokerOrder.contract_key;
    let quantityShares;
    if (
        payload.schemaVersion ===
        DURABLE_STOCK_ORDER_UNIT_INTENT_SCHEMA_VERSION
    ) {
        const durable = canonicalDurableStockOrderUnitPayload(payload);
        contractUnit = durable.contractUnit;
        contractKey = durable.contractKey;
        quantityShares = durable.quantityShares;
    } else if (payload.schemaVersion === SMART_ORDER_PROTECTED_ENTRY_INTENT_SCHEMA_VERSION) {
        const protectedIntent = canonicalProtectedEntryIntentPayload(payload);
        const plan = canonicalProtectedEntryPlan(
            protectedIntent.payload.protectionPlan,
        );
        contractUnit = plan.plan.entryOrder.contractUnit;
        contractKey = plan.plan.contractKey;
        quantityShares = plan.baseShares;
    } else if (
        payload.schemaVersion ===
        SMART_ORDER_PROTECTIVE_BROKER_INTENT_SCHEMA_VERSION
    ) {
        const protective =
            canonicalSmartOrderProtectiveBrokerIntentPayload(payload).payload;
        contractUnit = protective.contractUnit;
        quantityShares = protective.quantityShares;
    } else if (payload.schemaVersion === GOOD_TILL_INTENT_SCHEMA_VERSION) {
        const goodTill = canonicalGoodTillIntentPayload(payload);
        contractUnit = goodTill.order.contractUnit;
        contractKey = goodTill.order.contractKey;
        quantityShares = goodTill.order.baseShares;
    } else if (payload.schemaVersion === PARENT_CHILD_INTENT_SCHEMA_VERSION) {
        const parentChild = canonicalParentChildIntentPayload(payload);
        contractUnit = parentChild.order.contractUnit;
        contractKey = parentChild.order.contractKey;
        quantityShares = parentChild.order.baseShares;
    } else {
        throw new Error(
            'dispatch target originating intent has no durable canonical contract unit',
        );
    }
    if (
        !Number.isSafeInteger(contractUnit) ||
        contractUnit < 1 ||
        contractKey !== brokerOrder.contract_key ||
        quantityShares !== brokerOrder.quantity_shares ||
        quantityShares % contractUnit !== 0
    ) {
        throw new Error(
            'dispatch target originating intent unit does not match its durable BrokerOrder',
        );
    }
    return contractUnit;
}

function currentDispatchAdapterTarget(database, intent) {
    if (!['update', 'cancel'].includes(intent.operation_kind)) return null;
    const brokerOrderId = boundedToken(
        intent.target_broker_order_id,
        'dispatch.targetBrokerOrderId',
    );
    const targetControlRevision = safeInteger(
        intent.target_control_revision,
        'dispatch.targetControlRevision',
    );
    const brokerOrder = database.prepare(`
        SELECT orders.broker_order_id, orders.intent_id, orders.state,
               orders.control_revision, orders.quantity_shares,
               orders.filled_shares, orders.remaining_shares,
               orders.evidence_hash, orders.revision,
               targets.account_broker_ref, targets.account_id_ref,
               targets.trade_date, targets.contract_key, targets.side,
               targets.payload_hash AS originating_payload_hash,
               targets.payload_json AS originating_payload_json
          FROM broker_orders AS orders
          JOIN order_intents AS targets ON targets.intent_id=orders.intent_id
         WHERE orders.broker_order_id=?
    `).get(brokerOrderId);
    if (
        !brokerOrder ||
        brokerOrder.control_revision !== targetControlRevision ||
        !['pending_submit', 'pre_submitted', 'submitted', 'part_filled'].includes(
            brokerOrder.state,
        ) ||
        brokerOrder.remaining_shares < 1 ||
        brokerOrder.filled_shares + brokerOrder.remaining_shares !==
            brokerOrder.quantity_shares ||
        brokerOrder.account_broker_ref !== intent.account_broker_ref ||
        brokerOrder.account_id_ref !== intent.account_id_ref ||
        brokerOrder.trade_date !== intent.trade_date ||
        brokerOrder.contract_key !== intent.contract_key ||
        brokerOrder.side !== intent.side
    ) {
        throw new Error(
            'dispatch target BrokerOrder is missing, stale, terminal, or outside the fixed intent scope',
        );
    }
    const correlations = database.prepare(`
        SELECT correlation_id, canonical_key_hash, account_broker_ref,
               account_id_ref, trade_date, contract_key, side, trade_id,
               order_id, seqno, ordno, exchange_sequence, custom_field,
               evidence_hash, revision
          FROM broker_correlations
         WHERE broker_order_id=? AND intent_id=?
         ORDER BY correlation_id
    `).all(brokerOrder.broker_order_id, brokerOrder.intent_id);
    if (correlations.length !== 1) {
        throw new Error(
            'dispatch target requires exactly one durable broker correlation',
        );
    }
    const [correlation] = correlations;
    if (
        correlation.account_broker_ref !== brokerOrder.account_broker_ref ||
        correlation.account_id_ref !== brokerOrder.account_id_ref ||
        correlation.trade_date !== brokerOrder.trade_date ||
        correlation.contract_key !== brokerOrder.contract_key ||
        correlation.side !== brokerOrder.side ||
        correlation.trade_id === null ||
        correlation.seqno === null ||
        correlation.ordno === null
    ) {
        throw new Error(
            'dispatch target correlation is incomplete or outside the fixed BrokerOrder scope',
        );
    }
    const matchingHeads = database.prepare(`
        SELECT heads.status, heads.order_quantity,
               heads.cumulative_deal_quantity,
               heads.cumulative_cancel_quantity, heads.remaining_quantity,
               heads.quantity_unit, heads.exchange_epoch_ms,
               heads.broker_event_key_hash, heads.evidence_hash,
               heads.revision AS head_revision,
               records.trade_id, records.order_id, records.seqno,
               records.ordno, records.exchange_sequence,
               records.custom_field, records.order_condition,
               records.order_lot, records.price_type,
               records.time_in_force, records.price_decimal,
               records.mapping_revision, records.payload_hash
          FROM broker_event_heads AS heads
          JOIN broker_event_records AS records
            ON records.broker_event_key_hash=heads.broker_event_key_hash
         WHERE heads.account_broker_ref=? AND heads.account_id_ref=?
           AND heads.trade_date=? AND heads.intent_id=?
           AND records.intent_id=? AND records.contract_key=?
           AND records.side=?
    `).all(
        brokerOrder.account_broker_ref,
        brokerOrder.account_id_ref,
        brokerOrder.trade_date,
        brokerOrder.intent_id,
        brokerOrder.intent_id,
        brokerOrder.contract_key,
        brokerOrder.side,
    );
    const exactHeads = matchingHeads.filter(
        (candidate) =>
            candidate.trade_id === correlation.trade_id &&
            candidate.order_id === correlation.order_id &&
            candidate.seqno === correlation.seqno &&
            candidate.ordno === correlation.ordno &&
            candidate.exchange_sequence === correlation.exchange_sequence &&
            candidate.custom_field === correlation.custom_field,
    );
    const head = exactHeads.length === 1 ? exactHeads[0] : undefined;
    const expectedState = head
        ? BROKER_EVENT_STATUS_TO_ORDER_STATE[head.status]
        : undefined;
    if (
        !head ||
        expectedState !== brokerOrder.state ||
        exactHeads.length !== 1
    ) {
        throw new Error(
            'dispatch target broker event head is missing or no longer matches its durable correlation',
        );
    }
    const activeBrokerQuantity =
        head.order_quantity - head.cumulative_cancel_quantity;
    if (activeBrokerQuantity < 1 || head.remaining_quantity < 1) {
        throw new Error('dispatch target broker event quantity is terminal');
    }
    const contractUnit = durableOriginatingIntentContractUnit(brokerOrder);
    let brokerQuantityMultiplier;
    if (head.quantity_unit === 'CommonLot') {
        brokerQuantityMultiplier = contractUnit;
        if (activeBrokerQuantity * contractUnit !== brokerOrder.quantity_shares) {
            throw new Error(
                'dispatch target CommonLot quantity conflicts with its durable contract unit',
            );
        }
    } else if (head.quantity_unit === 'Share') {
        brokerQuantityMultiplier = 1;
        if (activeBrokerQuantity !== brokerOrder.quantity_shares) {
            throw new Error(
                'dispatch target Share quantity conflicts with its durable BrokerOrder',
            );
        }
    } else {
        throw new Error('dispatch target quantity unit is unsupported');
    }
    const toShares = (quantity, label) => {
        const shares = BigInt(quantity) * BigInt(brokerQuantityMultiplier);
        if (shares > BigInt(Number.MAX_SAFE_INTEGER)) {
            throw new Error(`${label} exceeds safe Share bounds`);
        }
        return Number(shares);
    };
    if (
        toShares(head.cumulative_deal_quantity, 'dispatch target filled quantity') !==
            brokerOrder.filled_shares ||
        toShares(head.remaining_quantity, 'dispatch target remaining quantity') !==
            brokerOrder.remaining_shares
    ) {
        throw new Error(
            'dispatch target event quantities do not match the durable BrokerOrder',
        );
    }
    const base = Object.freeze({
        account: Object.freeze({
            brokerId: brokerOrder.account_broker_ref,
            accountId: brokerOrder.account_id_ref,
            accountType: 'S',
        }),
        brokerOrderId: brokerOrder.broker_order_id,
        brokerOrderRevision: brokerOrder.revision,
        contractKey: brokerOrder.contract_key,
        contractUnit,
        controlRevision: brokerOrder.control_revision,
        evidenceSha256: sha256Canonical(
            {
                brokerOrderEvidenceHash: brokerOrder.evidence_hash,
                brokerOrderRevision: brokerOrder.revision,
                correlationEvidenceHash: correlation.evidence_hash,
                correlationRevision: correlation.revision,
                eventEvidenceHash: head.evidence_hash,
                eventHeadRevision: head.head_revision,
                eventMappingRevision: head.mapping_revision,
                eventPayloadHash: head.payload_hash,
                originatingIntentPayloadHash:
                    brokerOrder.originating_payload_hash,
            },
            'dispatch adapter target evidence',
        ),
        filledShares: brokerOrder.filled_shares,
        identifiers: Object.freeze({
            tradeId: correlation.trade_id,
            orderId: correlation.order_id,
            seqno: correlation.seqno,
            ordno: correlation.ordno,
            exchangeSequence: correlation.exchange_sequence,
            customField: correlation.custom_field,
        }),
        orderCondition: head.order_condition,
        orderLot: head.order_lot,
        priceDecimal: head.price_decimal,
        priceType: head.price_type,
        quantityShares: brokerOrder.quantity_shares,
        quantityUnit: head.quantity_unit,
        remainingShares: brokerOrder.remaining_shares,
        side: brokerOrder.side,
        state: brokerOrder.state,
        timeInForce: head.time_in_force,
        tradeDate: brokerOrder.trade_date,
    });
    return Object.freeze({
        ...base,
        targetRevision: sha256Canonical(
            base,
            'dispatch adapter target revision',
        ),
    });
}

function markIntentDispatching(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    const now = safeInteger(input.nowEpochMs, 'dispatch.nowEpochMs');
    const outcome = transaction(database, () => {
        const intentId = boundedToken(input.intentId, 'intentId');
        const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
        const senderFence = boundedToken(input.senderFence, 'senderFence');
        const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
        if (
            !currentReadySenderMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error('current ready sender fence mismatch');
        }
        const companion = database
            .prepare(`
                SELECT intents.intent_id, intents.activation_id,
                       intents.strategy_id,
                       intents.payload_hash,
                       intents.payload_json, intents.account_broker_ref,
                       intents.account_id_ref, intents.trade_date,
                       intents.contract_key,
                       intents.operation_kind, intents.owner_kind, intents.side,
                       intents.target_broker_order_id,
                       intents.target_control_revision,
                       activations.evidence_hash AS activation_evidence_hash,
                       activations.state AS activation_state,
                       activations.revision AS activation_revision,
                       strategies.state AS strategy_state,
                       strategies.revision AS strategy_revision,
                       strategies.definition_hash AS strategy_definition_hash
                  FROM order_intents AS intents
                  JOIN activations
                    ON activations.activation_id=intents.activation_id
                  JOIN strategies
                    ON strategies.strategy_id=intents.strategy_id
                 WHERE intents.intent_id=? AND intents.state='prepared'
                   AND intents.revision=?
                   AND intents.adapter_authority_granted=0
                   AND (
                       strategies.state IN ('observing','monitoring','recovery')
                       OR (
                           intents.operation_kind='cancel'
                           AND intents.owner_kind='manual_request'
                           AND strategies.state IN (
                               'paused','manual_intervention','cancel_pending',
                               'expired_with_obligation'
                           )
                       )
                   )
            `)
            .get(intentId, safeInteger(input.expectedRevision, 'expectedRevision'));
        if (!companion?.activation_id) {
            throw new Error('intent dispatch transition lost its CAS or activation');
        }
        const trustedDispatchNow = canonicalConfirmationClockNowEpochMs(now);
        if (
            !parentChildDispatchWindowIsCurrent(database, {
                intentId,
                strategyId: companion.strategy_id,
                payloadJson: companion.payload_json,
                nowEpochMs: trustedDispatchNow,
            })
        ) {
            throw new Error('parent-child dispatch window is closed');
        }
        const strategyConfirmationHash = database.prepare(`
            SELECT confirmation_snapshot_hash FROM strategies
             WHERE strategy_id=?
        `).get(companion.strategy_id)?.confirmation_snapshot_hash;
        if (typeof strategyConfirmationHash !== 'string') {
            throw new Error('intent dispatch strategy confirmation is missing');
        }
        assertCanonicalConfirmationCurrent(database, {
            strategyId: companion.strategy_id,
            snapshotHash: strategyConfirmationHash,
            runtimeEpochId,
            senderFence,
            apiGeneration,
            nowEpochMs: trustedDispatchNow,
        });
        const rearm = database
            .prepare(`
                SELECT rearms.rearm_authorization_id,
                       rearms.authorized_intent_revision,
                       rearms.confirmation_snapshot_hash,
                       rearms.risk_revision, rearms.reconciliation_evidence_hash,
                       rearms.user_rearm_evidence_hash, rearms.state,
                       rearms.revision,
                       epochs.reconciliation_evidence_hash AS epoch_reconciliation_hash
                  FROM intent_rearm_authorizations AS rearms
                  JOIN runtime_epochs AS epochs
                    ON epochs.runtime_epoch_id=rearms.runtime_epoch_id
                 WHERE rearms.intent_id=? AND rearms.runtime_epoch_id=?
                   AND rearms.sender_fence=? AND rearms.api_generation=?
                   AND rearms.state='active'
            `)
            .get(intentId, runtimeEpochId, senderFence, apiGeneration);
        if (
            !rearm ||
            rearm.authorized_intent_revision !== input.expectedRevision ||
            rearm.revision !==
                safeInteger(input.expectedRearmRevision, 'expectedRearmRevision') ||
            rearm.risk_revision !== input.riskRevision ||
            rearm.reconciliation_evidence_hash !==
                rearm.epoch_reconciliation_hash
        ) {
            throw new Error(
                'intent dispatch requires durable current-epoch user re-arm evidence',
            );
        }
        const expectedActivationRevision = safeInteger(
            input.expectedActivationRevision,
            'expectedActivationRevision',
        );
        const reservation = database
            .prepare(`
                SELECT *
                  FROM entry_exposure_reservations
                 WHERE intent_id=?
            `)
            .get(intentId);
        if (
            reservation &&
            reservation.revision !==
                safeInteger(
                    input.expectedReservationRevision,
                    'expectedReservationRevision',
                )
        ) {
            throw new Error('intent reservation dispatch transition lost its CAS');
        }
        if (!reservation && input.expectedReservationRevision !== undefined) {
            throw new Error('dispatch input expected a missing reservation');
        }
        let exposureDecisionHash;
        try {
            exposureDecisionHash = currentDispatchExposureDecision(
                database,
                {
                    ...companion,
                    intent_id: intentId,
                    runtime_epoch_id: runtimeEpochId,
                    api_generation: apiGeneration,
                },
                reservation,
            );
        } catch (error) {
            if (
                companion.operation_kind !== 'place' ||
                companion.side !== 'Sell' ||
                !isExternalSellVisibilityError(error)
            ) {
                throw error;
            }
            if (
                companion.activation_state !== 'prepared' ||
                companion.activation_revision !== expectedActivationRevision
            ) {
                throw new Error(
                    'external visibility invalidation lost the activation CAS',
                );
            }
            const exitClaim = database.prepare(`
                SELECT claims.exit_claim_id, claims.obligation_id,
                       claims.evidence_hash, claims.revision,
                       obligations.state AS obligation_state,
                       obligations.revision AS obligation_revision
                  FROM exit_claims AS claims
                  JOIN protection_obligations AS obligations
                    ON obligations.obligation_id=claims.obligation_id
                 WHERE claims.intent_id=? AND claims.external_lineage=0
                   AND claims.state='intent_reserved'
            `).get(intentId);
            if (
                !exitClaim ||
                exitClaim.obligation_state !== 'monitoring'
            ) {
                throw new Error(
                    'external visibility invalidation requires the exact live protection claim',
                );
            }
            const intentResult = database.prepare(`
                UPDATE order_intents
                   SET state='cancelled_proven_unsent',
                       terminal_outcome='place_cancelled_proven_unsent',
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE intent_id=? AND state='prepared' AND revision=?
                   AND adapter_authority_granted=0
            `).run(now, now, intentId, input.expectedRevision);
            const activationResult = database.prepare(`
                UPDATE activations
                   SET state='cancelled', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE activation_id=? AND state='prepared' AND revision=?
            `).run(
                now,
                companion.activation_id,
                expectedActivationRevision,
            );
            const strategyResult = database.prepare(`
                UPDATE strategies
                   SET state='manual_intervention', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE strategy_id=? AND state=? AND revision=?
            `).run(
                now,
                companion.strategy_id,
                companion.strategy_state,
                companion.strategy_revision,
            );
            const claimResult = database.prepare(`
                UPDATE exit_claims
                   SET state='released', updated_at_epoch_ms=?,
                       terminal_at_epoch_ms=?, revision=revision+1
                 WHERE exit_claim_id=? AND external_lineage=0
                   AND state='intent_reserved' AND revision=?
            `).run(
                now,
                now,
                exitClaim.exit_claim_id,
                exitClaim.revision,
            );
            const obligationResult = database.prepare(`
                UPDATE protection_obligations
                   SET state='safety_blocked', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE obligation_id=? AND state='monitoring' AND revision=?
            `).run(
                now,
                exitClaim.obligation_id,
                exitClaim.obligation_revision,
            );
            const rearmResult = database.prepare(`
                UPDATE intent_rearm_authorizations
                   SET state='superseded', revision=revision+1
                 WHERE rearm_authorization_id=? AND state='active'
                   AND revision=?
            `).run(rearm.rearm_authorization_id, rearm.revision);
            if (
                Number(intentResult.changes) !== 1 ||
                Number(activationResult.changes) !== 1 ||
                Number(strategyResult.changes) !== 1 ||
                Number(claimResult.changes) !== 1 ||
                Number(obligationResult.changes) !== 1 ||
                Number(rearmResult.changes) !== 1
            ) {
                throw new Error(
                    'external visibility invalidation lost its atomic CAS',
                );
            }
            const resolutionScopeHash = sha256Canonical(
                {
                    accountBrokerRef: companion.account_broker_ref,
                    accountIdRef: companion.account_id_ref,
                    contractKey: companion.contract_key,
                    tradeDate: companion.trade_date,
                },
                'external position drift resolution scope',
            );
            const resolutionEvidenceHash = sha256Canonical(
                {
                    errorCode: 'EXTERNAL_POSITION_DRIFT',
                    intentId,
                    intentRevision: input.expectedRevision,
                    visibilityFailure: error.message,
                },
                'external position drift evidence snapshot',
            );
            const resolutionIdentity = sha256Canonical(
                {
                    intentId,
                    intentRevision: input.expectedRevision,
                    reasonCode: 'EXTERNAL_POSITION_DRIFT',
                    strategyId: companion.strategy_id,
                },
                'external position drift resolution identity',
            ).slice('sha256:'.length);
            const resolutionCaseId = `resolution-${resolutionIdentity}`;
            const blockerId = `blocker-${resolutionIdentity}`;
            database.prepare(`
                INSERT INTO resolution_cases(
                    resolution_case_id, strategy_id, reason_code, scope_hash,
                    evidence_snapshot_hash, state, created_at_epoch_ms,
                    updated_at_epoch_ms, terminal_at_epoch_ms, revision
                ) VALUES (?, ?, 'EXTERNAL_POSITION_DRIFT', ?, ?, 'open',
                          ?, ?, NULL, 0)
            `).run(
                resolutionCaseId,
                companion.strategy_id,
                resolutionScopeHash,
                resolutionEvidenceHash,
                now,
                now,
            );
            database.prepare(`
                INSERT INTO safety_blockers(
                    blocker_id, resolution_case_id, scope_hash, reason_code,
                    state, created_at_epoch_ms, resolved_at_epoch_ms, revision
                ) VALUES (?, ?, ?, 'EXTERNAL_POSITION_DRIFT', 'open',
                          ?, NULL, 0)
            `).run(
                blockerId,
                resolutionCaseId,
                resolutionScopeHash,
                now,
            );
            advanceLifecycleSideEffectRevision(database);
            const intentRevision = input.expectedRevision + 1;
            const activationRevision = expectedActivationRevision + 1;
            const strategyRevision = companion.strategy_revision + 1;
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: intentId,
                revision: intentRevision,
                reasonCode: 'INTENT_CANCELLED_PROVEN_UNSENT',
                summaryCode: 'sell_intent_cancelled_proven_unsent',
                nowEpochMs: now,
                payloadHash: companion.payload_hash,
                eventSuffix: 'external-visibility-drift',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'activation',
                entityId: companion.activation_id,
                revision: activationRevision,
                reasonCode: 'INTENT_CANCELLED_PROVEN_UNSENT',
                summaryCode: 'activation_cancelled_proven_unsent',
                nowEpochMs: now,
                payloadHash: companion.activation_evidence_hash,
                eventSuffix: 'external-visibility-drift',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: companion.strategy_id,
                revision: strategyRevision,
                reasonCode: 'EXTERNAL_POSITION_DRIFT',
                summaryCode: 'strategy_manual_intervention_required',
                nowEpochMs: now,
                payloadHash: companion.strategy_definition_hash,
                eventSuffix: 'external-visibility-drift',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: intentId,
                revision: intentRevision,
                reasonCode:
                    'PREPARED_INTENT_REARM_SUPERSEDED_BY_EXTERNAL_POSITION_DRIFT',
                summaryCode: 'prepared_intent_rearm_superseded',
                nowEpochMs: now,
                payloadHash: rearm.user_rearm_evidence_hash,
                eventSuffix: `rearm-${rearm.rearm_authorization_id}-superseded`,
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'exit_claim',
                entityId: exitClaim.exit_claim_id,
                revision: exitClaim.revision + 1,
                reasonCode: 'EXIT_INTENT_CANCELLED_PROVEN_UNSENT',
                summaryCode: 'exit_claim_released_proven_unsent',
                nowEpochMs: now,
                payloadHash: exitClaim.evidence_hash,
                eventSuffix: 'external-visibility-drift',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'protection_obligation',
                entityId: exitClaim.obligation_id,
                revision: exitClaim.obligation_revision + 1,
                reasonCode: 'EXTERNAL_POSITION_DRIFT',
                summaryCode: 'protection_obligation_safety_blocked',
                nowEpochMs: now,
                payloadHash: resolutionEvidenceHash,
                eventSuffix: 'external-visibility-drift',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'resolution_case',
                entityId: resolutionCaseId,
                revision: 0,
                reasonCode: 'RESOLUTION_CASE_OPENED',
                summaryCode: 'external_position_drift_resolution_opened',
                nowEpochMs: now,
                payloadHash: resolutionEvidenceHash,
                eventSuffix: 'external-visibility-drift',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'safety_blocker',
                entityId: blockerId,
                revision: 0,
                reasonCode: 'EXTERNAL_POSITION_DRIFT',
                summaryCode: 'external_position_drift_safety_blocker_opened',
                nowEpochMs: now,
                payloadHash: resolutionScopeHash,
                eventSuffix: 'external-visibility-drift',
            });
            return Object.freeze({
                externalVisibilityInvalidated: true,
                message: error.message,
            });
        }
        const exitClaims = database
            .prepare(`
                SELECT claims.exit_claim_id, claims.obligation_id,
                       claims.external_lineage, claims.account_broker_ref,
                       claims.account_id_ref, claims.contract_key,
                       claims.position_lineage_id,
                       claims.remainder_generation,
                       claims.allocation_start_share, claims.state,
                       claims.quantity_shares, claims.evidence_hash,
                       claims.revision,
                       groups.protection_group_id,
                       groups.state AS protection_group_state,
                       groups.current_generation AS protection_group_generation,
                       groups.revision AS protection_group_revision,
                       generations.state AS protection_generation_state,
                       generations.winner_leg_id,
                       generations.winner_activation_id,
                       generations.winner_intent_id,
                       generations.revision AS protection_generation_revision,
                       (SELECT evaluations.evidence_hash
                          FROM protection_leg_evaluations AS evaluations
                         WHERE evaluations.protection_group_id=
                                   groups.protection_group_id
                           AND evaluations.remainder_generation=
                                   groups.current_generation
                           AND evaluations.state='winner'
                           AND evaluations.active_dispatch_slot=1)
                           AS winner_evidence_hash,
                       (SELECT COUNT(*) FROM protection_leg_evaluations AS evaluations
                         WHERE evaluations.protection_group_id=groups.protection_group_id
                           AND evaluations.remainder_generation=groups.current_generation)
                           AS candidate_evaluation_count,
                       (SELECT COUNT(*) FROM protection_leg_evaluations AS evaluations
                         WHERE evaluations.protection_group_id=groups.protection_group_id
                           AND evaluations.remainder_generation=groups.current_generation
                           AND evaluations.state='winner'
                           AND evaluations.active_dispatch_slot=1)
                           AS winner_evaluation_count,
                       (SELECT COUNT(*) FROM protection_leg_evaluations AS evaluations
                         WHERE evaluations.protection_group_id=groups.protection_group_id
                           AND evaluations.remainder_generation=groups.current_generation
                           AND evaluations.broker_authority=0)
                           AS zero_authority_evaluation_count,
                       obligations.strategy_id AS obligation_strategy_id,
                       obligations.position_lineage_id
                           AS obligation_position_lineage_id,
                       (SELECT entry_intents.payload_json
                          FROM pending_protection_commitments AS commitments
                          JOIN order_intents AS entry_intents
                            ON entry_intents.intent_id=commitments.entry_intent_id
                         WHERE commitments.commitment_id=obligations.commitment_id)
                           AS entry_payload_json
                       ,(SELECT existing.protection_plan_json
                          FROM existing_position_protection_heads AS existing
                         WHERE existing.strategy_id=obligations.strategy_id
                           AND existing.obligation_id=obligations.obligation_id
                           AND existing.exit_claim_id=claims.exit_claim_id)
                           AS existing_plan_json
                  FROM exit_claims AS claims
             LEFT JOIN protection_obligations AS obligations
                    ON obligations.obligation_id=claims.obligation_id
             LEFT JOIN protection_groups AS groups
                    ON groups.exit_claim_id=claims.exit_claim_id
             LEFT JOIN protection_remainder_generations AS generations
                    ON generations.protection_group_id=groups.protection_group_id
                   AND generations.remainder_generation=groups.current_generation
                 WHERE claims.intent_id=?
                 ORDER BY claims.exit_claim_id
            `)
            .all(intentId);
        const targetBrokerOrder =
            companion.target_broker_order_id === null
                ? undefined
                : database
                      .prepare(`
                          SELECT broker_order_id, intent_id, state,
                                 control_revision, quantity_shares,
                                 filled_shares, remaining_shares,
                                 evidence_hash, revision
                            FROM broker_orders
                           WHERE broker_order_id=?
                      `)
                      .get(companion.target_broker_order_id);
        const targetIntent = targetBrokerOrder
            ? database
                  .prepare(`
                      SELECT intent_id, account_broker_ref, account_id_ref,
                             trade_date, contract_key, side
                        FROM order_intents WHERE intent_id=?
                  `)
                  .get(targetBrokerOrder.intent_id)
            : undefined;
        const targetCorrelations = targetBrokerOrder
            ? database
                  .prepare(`
                      SELECT correlation_id, intent_id, broker_order_id,
                             canonical_key_hash, account_broker_ref,
                             account_id_ref, trade_date, contract_key, side,
                             evidence_hash, revision
                        FROM broker_correlations
                       WHERE broker_order_id=? AND intent_id=?
                       ORDER BY correlation_id
                  `)
                  .all(
                      targetBrokerOrder.broker_order_id,
                      targetBrokerOrder.intent_id,
                  )
            : [];
        const classification = classifyBrokerWriteForKillSwitch({
            intent: companion,
            reservation,
            exitClaims,
            targetBrokerOrder,
            targetIntent,
            targetCorrelations,
            rearm,
        });
        const { operationClass, operationEvidenceHash } = classification;
        const killSwitchArbiter = currentKillSwitchArbiter(database);
        const expectedKillSwitchArbiterRevision = safeInteger(
            input.expectedKillSwitchArbiterRevision,
            'dispatch.expectedKillSwitchArbiterRevision',
        );
        if (
            killSwitchArbiter.arbiterRevision !==
            expectedKillSwitchArbiterRevision
        ) {
            const error = new Error(
                'dispatch lost its shared kill switch arbiter revision CAS',
            );
            error.name = 'KillSwitchArbiterRevisionError';
            throw error;
        }
        const deniedBy = evaluateKillSwitchDenyUnion(
            killSwitchArbiter,
            operationClass,
        );
        if (deniedBy.length > 0) {
            const error = new Error(
                `broker write denied by kill switch union: ${deniedBy.join(',')}`,
            );
            error.name = 'KillSwitchDeniedError';
            throw error;
        }
        if (currentDispatchArbiterGrant(database, intentId)) {
            throw new Error('intent already has a durable dispatch arbiter grant');
        }
        const killSwitchDecisionHash = sha256Canonical(
            {
                arbiterRevision: killSwitchArbiter.arbiterRevision,
                operationClass,
                operationEvidenceHash,
                exposureDecisionHash,
                rearmAuthorizationId: rearm.rearm_authorization_id,
                rearmConfirmationSnapshotHash:
                    rearm.confirmation_snapshot_hash,
                rearmUserEvidenceHash: rearm.user_rearm_evidence_hash,
                switches: Object.fromEntries(
                    KILL_SWITCH_NAMES.map((name) => [
                        name,
                        {
                            enabled: killSwitchArbiter.switches[name].enabled,
                            revision: killSwitchArbiter.switches[name].revision,
                        },
                    ]),
                ),
            },
            'kill switch dispatch decision',
        );
        const adapterTarget = currentDispatchAdapterTarget(database, companion);
        const targetRevision =
            adapterTarget?.targetRevision ??
            boundedToken(input.targetRevision, 'targetRevision');
        const result = database
            .prepare(`
                UPDATE order_intents
                   SET state='dispatching', runtime_epoch_id=?,
                       dispatch_attempt_nonce=?, sender_fence=?,
                       api_generation=?, mode_revision=?, risk_revision=?,
                       account_revision=?, target_revision=?,
                       adapter_authority_granted=1, updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE intent_id=? AND state='prepared' AND revision=?
                   AND adapter_authority_granted=0
            `)
            .run(
                runtimeEpochId,
                boundedToken(input.dispatchAttemptNonce, 'dispatchAttemptNonce'),
                senderFence,
                apiGeneration,
                boundedToken(input.modeRevision, 'modeRevision'),
                boundedToken(input.riskRevision, 'riskRevision'),
                boundedToken(input.accountRevision, 'accountRevision'),
                targetRevision,
                now,
                intentId,
                input.expectedRevision,
            );
        if (Number(result.changes) !== 1) {
            throw new Error('intent dispatch transition lost its CAS or is not prepared');
        }
        const activationResult = database
            .prepare(`
                UPDATE activations
                   SET state='dispatching', updated_at_epoch_ms=?, revision=revision+1
                 WHERE activation_id=? AND state='prepared' AND revision=?
            `)
            .run(now, companion.activation_id, expectedActivationRevision);
        if (Number(activationResult.changes) !== 1) {
            throw new Error('activation dispatch transition lost its CAS');
        }
        let reservationRevision;
        if (reservation) {
            if (reservation.state !== 'reserved') {
                throw new Error('dispatch requires an active reserved exposure ledger');
            }
            reservationRevision = input.expectedReservationRevision;
        }
        const rearmResult = database
            .prepare(`
                UPDATE intent_rearm_authorizations
                   SET state='consumed', consumed_at_epoch_ms=?, revision=revision+1
                 WHERE rearm_authorization_id=? AND state='active' AND revision=?
            `)
            .run(now, rearm.rearm_authorization_id, input.expectedRearmRevision);
        if (Number(rearmResult.changes) !== 1) {
            throw new Error('intent dispatch re-arm consumption lost its CAS');
        }
        advanceLifecycleSideEffectRevision(database);
        const revision = input.expectedRevision + 1;
        const dispatchArbiterGrant = validateDispatchArbiterGrant(
            {
                schemaVersion: DISPATCH_ARBITER_GRANT_SCHEMA_VERSION,
                intentId,
                intentRevision: revision,
                arbiterRevision: killSwitchArbiter.arbiterRevision,
                operationClass,
                operationEvidenceHash,
                decisionHash: killSwitchDecisionHash,
                exposureDecisionHash,
                rearmAuthorizationId: rearm.rearm_authorization_id,
                rearmConfirmationSnapshotHash:
                    rearm.confirmation_snapshot_hash,
                rearmUserEvidenceHash: rearm.user_rearm_evidence_hash,
                grantedAtEpochMs: now,
            },
            intentId,
        );
        setRepositoryMeta(
            database,
            dispatchArbiterGrantMetaKey(intentId),
            canonicalJson(
                dispatchArbiterGrant,
                'durable dispatch arbiter grant',
            ),
        );
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: intentId,
            revision,
            reasonCode: 'ORDER_INTENT_DISPATCH_AUTHORITY_DURABLE',
            summaryCode: 'order_intent_dispatching',
            nowEpochMs: now,
            payloadHash: companion.payload_hash,
            eventSuffix: 'dispatching',
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'activation',
            entityId: companion.activation_id,
            revision: expectedActivationRevision + 1,
            reasonCode: 'ACTIVATION_DISPATCHING_WITH_FENCE',
            summaryCode: 'activation_dispatching',
            nowEpochMs: now,
            payloadHash: companion.activation_evidence_hash,
            eventSuffix: 'dispatching',
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: intentId,
            revision,
            reasonCode: 'PREPARED_INTENT_REARM_CONSUMED_FOR_DISPATCH',
            summaryCode: 'prepared_intent_rearm_consumed',
            nowEpochMs: now,
            payloadHash: rearm.user_rearm_evidence_hash,
            eventSuffix: `rearm-${rearm.rearm_authorization_id}-consumed`,
        });
        return Object.freeze({
            intentId: input.intentId,
            runtimeEpochId,
            dispatchAttemptNonce: input.dispatchAttemptNonce,
            senderFence,
            apiGeneration,
            state: 'dispatching',
            revision,
            activationRevision: expectedActivationRevision + 1,
            reservationRevision,
            rearmAuthorizationId: rearm.rearm_authorization_id,
            rearmRevision: input.expectedRearmRevision + 1,
            killSwitchArbiterRevision: dispatchArbiterGrant.arbiterRevision,
            killSwitchOperationClass: dispatchArbiterGrant.operationClass,
            killSwitchOperationEvidenceHash:
                dispatchArbiterGrant.operationEvidenceHash,
            killSwitchDecisionHash: dispatchArbiterGrant.decisionHash,
            targetRevision,
            durableBeforeAdapterAuthority: true,
        });
    });
    if (outcome?.externalVisibilityInvalidated === true) {
        throw externalSellVisibilityError(outcome.message);
    }
    return outcome;
}

function currentBrokerWriteClassification(database, intent) {
    const exitClaims = database.prepare(`
        SELECT claims.exit_claim_id, claims.obligation_id,
               claims.external_lineage, claims.account_broker_ref,
               claims.account_id_ref, claims.contract_key,
               claims.position_lineage_id, claims.remainder_generation,
               claims.allocation_start_share, claims.state,
               claims.quantity_shares, claims.evidence_hash, claims.revision,
               groups.protection_group_id,
               groups.state AS protection_group_state,
               groups.current_generation AS protection_group_generation,
               groups.revision AS protection_group_revision,
               generations.state AS protection_generation_state,
               generations.winner_leg_id,
               generations.winner_activation_id,
               generations.winner_intent_id,
               generations.revision AS protection_generation_revision,
               (SELECT evaluations.evidence_hash
                  FROM protection_leg_evaluations AS evaluations
                 WHERE evaluations.protection_group_id=groups.protection_group_id
                   AND evaluations.remainder_generation=groups.current_generation
                   AND evaluations.state='winner'
                   AND evaluations.active_dispatch_slot=1)
                   AS winner_evidence_hash,
               (SELECT COUNT(*) FROM protection_leg_evaluations AS evaluations
                 WHERE evaluations.protection_group_id=groups.protection_group_id
                   AND evaluations.remainder_generation=groups.current_generation)
                   AS candidate_evaluation_count,
               (SELECT COUNT(*) FROM protection_leg_evaluations AS evaluations
                 WHERE evaluations.protection_group_id=groups.protection_group_id
                   AND evaluations.remainder_generation=groups.current_generation
                   AND evaluations.state='winner'
                   AND evaluations.active_dispatch_slot=1)
                   AS winner_evaluation_count,
               (SELECT COUNT(*) FROM protection_leg_evaluations AS evaluations
                 WHERE evaluations.protection_group_id=groups.protection_group_id
                   AND evaluations.remainder_generation=groups.current_generation
                   AND evaluations.broker_authority=0)
                   AS zero_authority_evaluation_count,
               obligations.strategy_id AS obligation_strategy_id,
               obligations.position_lineage_id
                   AS obligation_position_lineage_id,
               (SELECT entry_intents.payload_json
                  FROM pending_protection_commitments AS commitments
                  JOIN order_intents AS entry_intents
                    ON entry_intents.intent_id=commitments.entry_intent_id
                 WHERE commitments.commitment_id=obligations.commitment_id)
                   AS entry_payload_json
               ,(SELECT existing.protection_plan_json
                  FROM existing_position_protection_heads AS existing
                 WHERE existing.strategy_id=obligations.strategy_id
                   AND existing.obligation_id=obligations.obligation_id
                   AND existing.exit_claim_id=claims.exit_claim_id)
                   AS existing_plan_json
          FROM exit_claims AS claims
     LEFT JOIN protection_obligations AS obligations
            ON obligations.obligation_id=claims.obligation_id
     LEFT JOIN protection_groups AS groups
            ON groups.exit_claim_id=claims.exit_claim_id
     LEFT JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
         WHERE claims.intent_id=?
         ORDER BY claims.exit_claim_id
    `).all(intent.intent_id);
    const targetBrokerOrder =
        intent.target_broker_order_id === null
            ? undefined
            : database.prepare(`
                  SELECT broker_order_id, intent_id, state,
                         control_revision, quantity_shares, filled_shares,
                         remaining_shares, evidence_hash, revision
                    FROM broker_orders WHERE broker_order_id=?
              `).get(intent.target_broker_order_id);
    const targetIntent = targetBrokerOrder
        ? database.prepare(`
              SELECT intent_id, account_broker_ref, account_id_ref,
                     trade_date, contract_key, side
                FROM order_intents WHERE intent_id=?
          `).get(targetBrokerOrder.intent_id)
        : undefined;
    const targetCorrelations = targetBrokerOrder
        ? database.prepare(`
              SELECT correlation_id, intent_id, broker_order_id,
                     canonical_key_hash, account_broker_ref, account_id_ref,
                     trade_date, contract_key, side, evidence_hash, revision
                FROM broker_correlations
               WHERE broker_order_id=? AND intent_id=?
               ORDER BY correlation_id
          `).all(
              targetBrokerOrder.broker_order_id,
              targetBrokerOrder.intent_id,
          )
        : [];
    return classifyBrokerWriteForKillSwitch({
        intent,
        reservation:
            intent.reservation_id === null
                ? undefined
                : { reservation_id: intent.reservation_id },
        exitClaims,
        targetBrokerOrder,
        targetIntent,
        targetCorrelations,
        rearm: {
            rearm_authorization_id: intent.rearm_authorization_id,
            confirmation_snapshot_hash:
                intent.rearm_confirmation_snapshot_hash,
            user_rearm_evidence_hash: intent.user_rearm_evidence_hash,
            // Dispatch verification occurs after the exact authorization was
            // atomically consumed. Reclassify against the same immutable
            // evidence while the outer grant checks require `consumed`.
            state: intent.rearm_state === 'consumed' ? 'active' : intent.rearm_state,
        },
    });
}

function verifyDispatchGrant(database, input) {
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const intentId = boundedToken(input.intentId, 'intentId');
    const row = database
        .prepare(`
            SELECT intents.intent_id, intents.activation_id,
                   intents.strategy_id, intents.state,
                   intents.revision, intents.dispatch_attempt_nonce,
                   intents.runtime_epoch_id, intents.sender_fence,
                   intents.api_generation,
                   intents.mode_revision, intents.risk_revision,
                   intents.account_revision, intents.target_revision,
                   intents.operation_kind, intents.owner_kind,
                   intents.payload_hash, intents.payload_json,
                   intents.client_request_id, intents.account_broker_ref,
                   intents.account_id_ref, intents.trade_date,
                   intents.contract_key, intents.side,
                   intents.target_broker_order_id,
                   intents.target_control_revision,
                   intents.adapter_authority_granted,
                   activations.state AS activation_state,
                   activations.revision AS activation_revision,
                   reservations.state AS reservation_state,
                   reservations.revision AS reservation_revision,
                   reservations.reservation_id,
                   reservations.policy_revision AS reservation_policy_revision,
                   reservations.policy_hash AS reservation_policy_hash,
                   reservations.account_broker_ref AS reservation_account_broker_ref,
                   reservations.account_id_ref AS reservation_account_id_ref,
                   reservations.identity_group_id AS reservation_identity_group_id,
                   reservations.quantity_shares,
                   reservations.notional_minor_units,
                   reservations.cash_minor_units,
                   reservations.position_shares,
                   reservations.order_count,
                   rearms.rearm_authorization_id,
                   rearms.state AS rearm_state,
                   rearms.revision AS rearm_revision,
                   rearms.authorized_intent_revision,
                   rearms.confirmation_snapshot_hash AS rearm_confirmation_snapshot_hash,
                   rearms.user_rearm_evidence_hash,
                   rearms.risk_revision AS rearm_risk_revision,
                   rearms.reconciliation_evidence_hash,
                   epochs.reconciliation_evidence_hash AS epoch_reconciliation_hash
              FROM order_intents AS intents
              JOIN activations ON activations.activation_id=intents.activation_id
         LEFT JOIN entry_exposure_reservations AS reservations
                ON reservations.intent_id=intents.intent_id
              JOIN intent_rearm_authorizations AS rearms
                ON rearms.intent_id=intents.intent_id
               AND rearms.runtime_epoch_id=?
              JOIN runtime_epochs AS epochs
                ON epochs.runtime_epoch_id=rearms.runtime_epoch_id
             WHERE intents.intent_id=?
        `)
        .get(runtimeEpochId, intentId);
    const arbiterGrant = currentDispatchArbiterGrant(database, intentId);
    let currentExposureDecisionHash;
    let currentClassification;
    let adapterTarget;
    let currentConfirmationValid = false;
    let currentParentChildDispatchWindowValid = true;
    if (row && arbiterGrant) {
        try {
            currentParentChildDispatchWindowValid =
                parentChildDispatchWindowIsCurrent(database, {
                    intentId,
                    strategyId: row.strategy_id,
                    payloadJson: row.payload_json,
                    nowEpochMs: canonicalConfirmationClockNowEpochMs(
                        input.nowEpochMs,
                    ),
                });
        } catch {
            currentParentChildDispatchWindowValid = false;
        }
        try {
            const strategyConfirmationHash = database.prepare(`
                SELECT confirmation_snapshot_hash FROM strategies
                 WHERE strategy_id=?
            `).get(row.strategy_id)?.confirmation_snapshot_hash;
            if (typeof strategyConfirmationHash !== 'string') {
                throw new Error('dispatch strategy confirmation is missing');
            }
            const trustedDispatchNow = canonicalConfirmationClockNowEpochMs(
                input.nowEpochMs,
            );
            currentConfirmationValid = assertCanonicalConfirmationCurrent(
                database,
                {
                    strategyId: row.strategy_id,
                    snapshotHash: strategyConfirmationHash,
                    runtimeEpochId,
                    senderFence,
                    apiGeneration,
                    nowEpochMs: trustedDispatchNow,
                },
            );
        } catch {
            currentConfirmationValid = false;
        }
        try {
            adapterTarget = currentDispatchAdapterTarget(database, row);
        } catch {
            adapterTarget = undefined;
        }
        try {
            currentExposureDecisionHash = currentDispatchExposureDecision(
                database,
                {
                    operation_kind: row.operation_kind,
                    side: row.side,
                    strategy_id: database.prepare(
                        'SELECT strategy_id FROM order_intents WHERE intent_id=?',
                    ).get(intentId)?.strategy_id,
                    intent_id: intentId,
                    account_broker_ref: row.account_broker_ref,
                    account_id_ref: row.account_id_ref,
                    trade_date: row.trade_date,
                    contract_key: row.contract_key,
                    runtime_epoch_id: row.runtime_epoch_id,
                    api_generation: row.api_generation,
                },
                row.reservation_id === null
                    ? undefined
                    : {
                          reservation_id: row.reservation_id,
                          revision: row.reservation_revision,
                          policy_revision: row.reservation_policy_revision,
                          policy_hash: row.reservation_policy_hash,
                          account_broker_ref: row.reservation_account_broker_ref,
                          account_id_ref: row.reservation_account_id_ref,
                          identity_group_id: row.reservation_identity_group_id,
                          quantity_shares: row.quantity_shares,
                          notional_minor_units: row.notional_minor_units,
                          cash_minor_units: row.cash_minor_units,
                          position_shares: row.position_shares,
                          order_count: row.order_count,
                      },
            );
            currentClassification = currentBrokerWriteClassification(
                database,
                row,
            );
        } catch {
            currentExposureDecisionHash = undefined;
            currentClassification = undefined;
        }
    }
    const authorized = Boolean(
            row &&
            arbiterGrant &&
            currentConfirmationValid &&
            currentParentChildDispatchWindowValid &&
            currentReadySenderMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            }) &&
            row.state === 'dispatching' &&
            row.revision === safeInteger(input.revision, 'revision') &&
            row.dispatch_attempt_nonce === input.dispatchAttemptNonce &&
            row.runtime_epoch_id === runtimeEpochId &&
            row.sender_fence === senderFence &&
            row.api_generation === apiGeneration &&
            row.mode_revision === input.modeRevision &&
            row.risk_revision === input.riskRevision &&
            row.account_revision === input.accountRevision &&
            row.target_revision === input.targetRevision &&
            (['update', 'cancel'].includes(row.operation_kind)
                ? adapterTarget?.targetRevision === row.target_revision
                : adapterTarget === null) &&
            row.rearm_state === 'consumed' &&
            row.rearm_authorization_id === input.rearmAuthorizationId &&
            row.rearm_revision ===
                safeInteger(input.rearmRevision, 'rearmRevision') &&
            row.authorized_intent_revision === row.revision - 1 &&
            row.rearm_risk_revision === input.riskRevision &&
            row.reconciliation_evidence_hash ===
                row.epoch_reconciliation_hash &&
            row.activation_state === 'dispatching' &&
            row.activation_revision ===
                safeInteger(input.activationRevision, 'activationRevision') &&
            (row.reservation_id === null
                ? input.reservationRevision === undefined
                : row.reservation_state === 'reserved' &&
                  row.reservation_revision ===
                      safeInteger(input.reservationRevision, 'reservationRevision')) &&
            arbiterGrant.intentRevision === row.revision &&
            arbiterGrant.exposureDecisionHash === currentExposureDecisionHash &&
            currentClassification?.operationClass ===
                arbiterGrant.operationClass &&
            currentClassification?.operationEvidenceHash ===
                arbiterGrant.operationEvidenceHash &&
            arbiterGrant.rearmAuthorizationId ===
                row.rearm_authorization_id &&
            arbiterGrant.rearmConfirmationSnapshotHash ===
                row.rearm_confirmation_snapshot_hash &&
            arbiterGrant.rearmUserEvidenceHash ===
                row.user_rearm_evidence_hash &&
            arbiterGrant.arbiterRevision ===
                safeInteger(
                    input.killSwitchArbiterRevision,
                    'killSwitchArbiterRevision',
                ) &&
            (input.killSwitchOperationClass === undefined ||
                arbiterGrant.operationClass ===
                    input.killSwitchOperationClass) &&
            (input.killSwitchOperationEvidenceHash === undefined ||
                arbiterGrant.operationEvidenceHash ===
                    input.killSwitchOperationEvidenceHash) &&
            (input.killSwitchDecisionHash === undefined ||
                arbiterGrant.decisionHash === input.killSwitchDecisionHash) &&
            row.adapter_authority_granted === 1,
    );
    if (!authorized) {
        const targetChanged = Boolean(
            row &&
            arbiterGrant &&
            ['update', 'cancel'].includes(row.operation_kind) &&
            row.state === 'dispatching' &&
            row.revision === safeInteger(input.revision, 'revision') &&
            row.dispatch_attempt_nonce === input.dispatchAttemptNonce &&
            row.runtime_epoch_id === runtimeEpochId &&
            row.sender_fence === senderFence &&
            row.api_generation === apiGeneration &&
            row.target_revision === input.targetRevision &&
            adapterTarget?.targetRevision !== row.target_revision,
        );
        return Object.freeze({
            authorized: false,
            ...(!currentParentChildDispatchWindowValid
                ? { reasonCode: 'parent_child_dispatch_window_closed' }
                : targetChanged
                ? { reasonCode: 'broker_target_changed' }
                : {}),
        });
    }
    const payload = parseStoredCanonicalObject(
        row.payload_json,
        'dispatch grant payload',
    );
    if (
        sha256Canonical(payload, 'dispatch grant payload') !== row.payload_hash
    ) {
        throw new Error('dispatch grant payload hash no longer matches');
    }
    const immutablePayload = structuredClone(payload);
    const freezeRecursively = (value) => {
        if (!value || typeof value !== 'object' || Object.isFrozen(value)) {
            return value;
        }
        for (const child of Object.values(value)) freezeRecursively(child);
        return Object.freeze(value);
    };
    return Object.freeze({
        authorized: true,
        envelope: Object.freeze({
            schemaVersion: 'smart-order-dispatch-envelope/2026-08-12.1',
            intentId,
            operationKind: row.operation_kind,
            ownerKind: row.owner_kind,
            payloadHash: row.payload_hash,
            payload: freezeRecursively(immutablePayload),
            clientRequestId: row.client_request_id,
            accountBrokerRef: row.account_broker_ref,
            accountIdRef: row.account_id_ref,
            tradeDate: row.trade_date,
            contractKey: row.contract_key,
            side: row.side,
            targetBrokerOrderId: row.target_broker_order_id,
            targetControlRevision: row.target_control_revision,
            runtimeEpochId,
            dispatchAttemptNonce: row.dispatch_attempt_nonce,
            senderFence,
            apiGeneration,
            modeRevision: row.mode_revision,
            riskRevision: row.risk_revision,
            accountRevision: row.account_revision,
            targetRevision: row.target_revision,
            adapterTarget,
            killSwitchArbiterRevision: arbiterGrant.arbiterRevision,
            killSwitchOperationClass: arbiterGrant.operationClass,
            killSwitchOperationEvidenceHash:
                arbiterGrant.operationEvidenceHash,
            killSwitchDecisionHash: arbiterGrant.decisionHash,
            intentRevision: row.revision,
            activationRevision: row.activation_revision,
            reservationRevision: row.reservation_revision,
            rearmAuthorizationId: row.rearm_authorization_id,
            rearmRevision: row.rearm_revision,
        }),
    });
}

function transitionProtectedEntryCancelOutcomeUnknown(database, intent, now) {
    const payload = canonicalIntentPayload(
        intent.payload_json,
        'protected entry cancel outcome payload',
    );
    if (
        intent.operation_kind !== 'cancel' ||
        intent.owner_kind !== 'activation' ||
        !exactKeys(payload, [
            'brokerOrderId',
            'controlRevision',
            'protectionGroupId',
            'remainderGeneration',
            'schemaVersion',
            'triggerSelectionHash',
        ]) ||
        payload.schemaVersion !==
            PROTECTIVE_ENTRY_CANCEL_INTENT_SCHEMA_VERSION ||
        payload.brokerOrderId !== intent.target_broker_order_id ||
        payload.controlRevision !== intent.target_control_revision
    ) {
        throw new Error(
            'protected entry cancel outcome lost its exact durable envelope',
        );
    }
    const entry = database.prepare(`
        SELECT groups.protection_group_id, groups.state AS group_state,
               groups.current_generation, groups.revision AS group_revision,
               generations.state AS generation_state,
               generations.revision AS generation_revision,
               claims.exit_claim_id, claims.state AS claim_state,
               claims.revision AS claim_revision,
               obligations.obligation_id, obligations.state AS obligation_state,
               obligations.revision AS obligation_revision,
               commitments.entry_intent_id,
               entry_intents.state AS entry_intent_state,
               entry_intents.account_broker_ref,
               entry_intents.account_id_ref, entry_intents.trade_date,
               entry_intents.contract_key,
               strategies.strategy_id, strategies.state AS strategy_state,
               strategies.revision AS strategy_revision
          FROM protection_groups AS groups
          JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
          JOIN exit_claims AS claims
            ON claims.exit_claim_id=groups.exit_claim_id
          JOIN protection_obligations AS obligations
            ON obligations.obligation_id=groups.obligation_id
          JOIN pending_protection_commitments AS commitments
            ON commitments.commitment_id=obligations.commitment_id
          JOIN order_intents AS entry_intents
            ON entry_intents.intent_id=commitments.entry_intent_id
          JOIN strategies ON strategies.strategy_id=obligations.strategy_id
         WHERE groups.protection_group_id=?
           AND generations.remainder_generation=?
    `).get(payload.protectionGroupId, payload.remainderGeneration);
    if (!entry) {
        throw new Error(
            'protected entry cancel outcome lost its durable protection lineage',
        );
    }
    const orders = database.prepare(`
        SELECT broker_order_id, state, control_revision, filled_shares,
               remaining_shares, revision
          FROM broker_orders
         WHERE intent_id=?
         ORDER BY broker_order_id
    `).all(entry.entry_intent_id);
    const target = orders.find(
        (order) => order.broker_order_id === payload.brokerOrderId,
    );
    if (!target || target.control_revision !== payload.controlRevision) {
        throw new Error(
            'protected entry cancel outcome target no longer matches its durable entry order',
        );
    }
    const resolutionIdentity = sha256Canonical(
        {
            entryIntentId: entry.entry_intent_id,
            protectionGroupId: payload.protectionGroupId,
            remainderGeneration: payload.remainderGeneration,
            triggerSelectionHash: payload.triggerSelectionHash,
        },
        'protected entry trigger disposition identity',
    ).slice('sha256:'.length);
    return transitionProtectedEntryTriggerToManual(database, {
        blockerId: `blocker-${resolutionIdentity}`,
        deniedBy: [],
        entry,
        manualReason: 'entry_cancel_result_unknown',
        now,
        orders,
        resolutionCaseId: `resolution-${resolutionIdentity}`,
        triggerSelectionHash: payload.triggerSelectionHash,
    });
}

function markIntentOutcome(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    const states = new Set(['acknowledged', 'reconciling', 'unknown', 'terminal']);
    if (!states.has(input.state)) throw new TypeError('intent outcome state is invalid');
    const now = safeInteger(input.nowEpochMs, 'outcome.nowEpochMs');
    return transaction(database, () => {
        const intentId = boundedToken(input.intentId, 'intentId');
        const intent = database
            .prepare(`
                SELECT payload_hash, payload_json, operation_kind, owner_kind,
                       target_broker_order_id, target_control_revision
                  FROM order_intents WHERE intent_id=?
            `)
            .get(intentId);
        if (!intent) throw new Error('intent outcome target does not exist');
        const arbiterGrant = currentDispatchArbiterGrant(database, intentId);
        if (!arbiterGrant) {
            throw new Error('intent outcome requires its durable dispatch arbiter grant');
        }
        const result = database
            .prepare(`
                UPDATE order_intents
                   SET state=?, terminal_outcome=?, updated_at_epoch_ms=?,
                       terminal_at_epoch_ms=?, revision=revision+1
                 WHERE intent_id=? AND state IN ('dispatching','acknowledged','reconciling','unknown')
                   AND revision=? AND dispatch_attempt_nonce=? AND sender_fence=?
                   AND api_generation=? AND adapter_authority_granted=1
            `)
            .run(
                input.state,
                input.terminalOutcome === undefined
                    ? null
                    : boundedToken(input.terminalOutcome, 'terminalOutcome'),
                now,
                input.state === 'terminal' ? now : null,
                intentId,
                safeInteger(input.expectedRevision, 'expectedRevision'),
                boundedToken(input.dispatchAttemptNonce, 'dispatchAttemptNonce'),
                boundedToken(input.senderFence, 'senderFence'),
                boundedToken(input.apiGeneration, 'apiGeneration'),
            );
        if (Number(result.changes) !== 1) {
            throw new Error('intent outcome transition lost its fenced CAS');
        }
        if (
            input.state === 'unknown' &&
            arbiterGrant.operationClass === 'protective_entry_cancel'
        ) {
            transitionProtectedEntryCancelOutcomeUnknown(
                database,
                intent,
                now,
            );
        }
        advanceLifecycleSideEffectRevision(database);
        const revision = input.expectedRevision + 1;
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: intentId,
            revision,
            reasonCode: `ORDER_INTENT_OUTCOME_${input.state.toUpperCase()}`,
            summaryCode: `order_intent_${input.state}`,
            nowEpochMs: now,
            payloadHash: intent.payload_hash,
            eventSuffix: `outcome-${input.state}`,
        });
        const currentArbiter = currentKillSwitchArbiter(database);
        const emergencyCommittedAfterDispatch = Boolean(
            currentArbiter.arbiterRevision > arbiterGrant.arbiterRevision &&
                currentArbiter.switches.emergency_block_all_writes.enabled,
        );
        return Object.freeze({
            intentId,
            state: input.state,
            revision,
            killSwitchArbiterRevisionAtDispatch:
                arbiterGrant.arbiterRevision,
            emergencyCommittedAfterDispatch,
            withdrawnByKillSwitch: false,
            reconciliationRequired: ['unknown', 'reconciling'].includes(
                input.state,
            ),
        });
    });
}

const BROKER_ORDER_NON_TERMINAL_STATES = new Set([
    'pending_submit',
    'pre_submitted',
    'submitted',
    'part_filled',
    'unknown',
]);
const BROKER_ORDER_TERMINAL_STATES = new Set([
    'filled',
    'cancelled',
    'failed',
    'inactive',
]);
const BROKER_ORDER_ALLOWED_NEXT_STATES = Object.freeze({
    pending_submit: new Set([
        'pre_submitted',
        'submitted',
        'part_filled',
        'filled',
        'cancelled',
        'failed',
        'inactive',
        'unknown',
    ]),
    pre_submitted: new Set([
        'submitted',
        'part_filled',
        'filled',
        'cancelled',
        'failed',
        'inactive',
        'unknown',
    ]),
    submitted: new Set([
        'submitted',
        'part_filled',
        'filled',
        'cancelled',
        'failed',
        'inactive',
        'unknown',
    ]),
    part_filled: new Set([
        'part_filled',
        'filled',
        'cancelled',
        'failed',
        'inactive',
        'unknown',
    ]),
    unknown: new Set([
        'pre_submitted',
        'submitted',
        'part_filled',
        'filled',
        'cancelled',
        'failed',
        'inactive',
        'unknown',
    ]),
});

function validateBrokerOrderQuantityProjection({
    state,
    quantityShares,
    filledShares,
    remainingShares,
}) {
    if (
        quantityShares < 1 ||
        filledShares + remainingShares !== quantityShares
    ) {
        throw new Error('broker order quantity projection is inconsistent');
    }
    if (
        ['pending_submit', 'pre_submitted', 'submitted'].includes(state) &&
        (filledShares !== 0 || remainingShares !== quantityShares)
    ) {
        throw new Error('unfilled broker order state has nonzero filled shares');
    }
    if (
        state === 'part_filled' &&
        !(filledShares > 0 && filledShares < quantityShares && remainingShares > 0)
    ) {
        throw new Error('part-filled broker order quantity projection is invalid');
    }
    if (
        state === 'filled' &&
        (filledShares !== quantityShares || remainingShares !== 0)
    ) {
        throw new Error('filled broker order quantity projection is invalid');
    }
}

const CANONICAL_BROKER_EVENT_PROGRESS = Object.freeze({
    PendingSubmit: 0,
    PreSubmitted: 1,
    Submitted: 2,
    PartFilled: 3,
    Filled: 4,
    Cancelled: 4,
    Inactive: 4,
    Failed: 4,
});

function brokerEventQuantityShares(value, unit, contractUnit, label) {
    const quantity = safeInteger(value, label);
    if (unit === 'Share') return quantity;
    if (unit !== 'CommonLot') {
        throw new TypeError(`${label} uses an unsupported broker quantity unit`);
    }
    const shares = BigInt(quantity) * BigInt(contractUnit);
    if (shares > BigInt(Number.MAX_SAFE_INTEGER)) {
        throw new TypeError(`${label} exceeds safe share bounds`);
    }
    return Number(shares);
}

function projectInternalExitClaimBrokerEvidence(database, { event, intentId }) {
    const claims = database.prepare(`
        SELECT claims.exit_claim_id, claims.external_lineage,
               claims.quantity_shares, claims.state, claims.revision,
               groups.protection_group_id,
               groups.state AS protection_group_state,
               groups.current_generation,
               groups.revision AS protection_group_revision,
               generations.state AS protection_generation_state,
               generations.revision AS protection_generation_revision,
               entry_intents.payload_json AS entry_payload_json,
               existing.protection_plan_json AS existing_plan_json,
               strategies.strategy_kind,
               exit_intents.payload_json AS exit_payload_json
          FROM exit_claims AS claims
          JOIN protection_obligations AS obligations
            ON obligations.obligation_id=claims.obligation_id
          JOIN strategies ON strategies.strategy_id=obligations.strategy_id
          JOIN order_intents AS exit_intents ON exit_intents.intent_id=claims.intent_id
     LEFT JOIN pending_protection_commitments AS commitments
            ON commitments.commitment_id=obligations.commitment_id
     LEFT JOIN order_intents AS entry_intents
            ON entry_intents.intent_id=commitments.entry_intent_id
     LEFT JOIN existing_position_protection_heads AS existing
            ON existing.strategy_id=obligations.strategy_id
           AND existing.obligation_id=obligations.obligation_id
           AND existing.exit_claim_id=claims.exit_claim_id
     LEFT JOIN protection_groups AS groups
            ON groups.exit_claim_id=claims.exit_claim_id
     LEFT JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
         WHERE claims.intent_id=?
         ORDER BY claims.exit_claim_id
    `).all(intentId);
    if (claims.length === 0) return null;
    if (claims.length !== 1) {
        throw new Error(
            'broker event intent has multiple durable ExitClaim lineages',
        );
    }
    const [claim] = claims;
    if (claim.external_lineage !== 0 || event.side !== 'Sell') {
        throw new Error('broker event ExitClaim lineage is not an internal Sell');
    }
    if (
        claim.current_generation < 0 ||
        claim.protection_group_state !== claim.protection_generation_state ||
        !['winner_selected', 'broker_working', 'unknown'].includes(
            claim.protection_group_state,
        )
    ) {
        throw new Error('broker event protection group lineage is invalid');
    }
    const parentChildPayload =
        claim.strategy_kind === 'parent_child'
            ? canonicalParentChildIntentPayload(
                  parseStoredCanonicalObject(
                      claim.exit_payload_json,
                      'parent-child child exit payload',
                  ),
              )
            : null;
    const entryPlan =
        parentChildPayload !== null
            ? null
            : claim.existing_plan_json !== null
              ? canonicalExistingPositionProtectionPlan(
                    parseStoredCanonicalObject(
                        claim.existing_plan_json,
                        'ExitClaim existing-position protection plan',
                    ),
                )
              : canonicalProtectedEntryPlan(
                    canonicalProtectedEntryIntentPayload(
                        parseStoredCanonicalObject(
                            claim.entry_payload_json,
                            'ExitClaim entry intent payload',
                        ),
                    ).payload.protectionPlan,
                );
    const contractUnit =
        parentChildPayload?.order.contractUnit ??
        entryPlan.plan.entryOrder?.contractUnit ??
        entryPlan.contractUnit;
    const orderShares = brokerEventQuantityShares(
        event.quantities.order,
        event.quantities.unit,
        contractUnit,
        'broker event exit order quantity',
    );
    if (orderShares !== claim.quantity_shares) {
        throw new Error(
            'broker event quantity does not match its durable ExitClaim',
        );
    }
    if (
        ![
            'intent_reserved',
            'broker_working',
            'unknown',
            'consumed',
            'released',
        ].includes(claim.state)
    ) {
        throw new Error('broker event ExitClaim state is invalid');
    }
    const terminalStatus = ['Filled', 'Cancelled', 'Inactive', 'Failed'].includes(
        event.status,
    );
    const quantityChanged = event.quantities.cumulativeDeal > 0;
    let nextState = claim.state;
    let reasonCode;
    let summaryCode;
    if (claim.state === 'intent_reserved') {
        if (terminalStatus || quantityChanged) {
            nextState = 'unknown';
            reasonCode = 'EXIT_CLAIM_UNKNOWN';
            summaryCode = terminalStatus
                ? 'exit_claim_terminal_before_working_unknown'
                : 'exit_claim_deal_before_reconciliation_unknown';
        } else {
            nextState = 'broker_working';
            reasonCode = 'EXIT_CLAIM_BROKER_WORKING';
            summaryCode = 'exit_claim_broker_working';
        }
    } else if (
        claim.state === 'broker_working' &&
        (terminalStatus || quantityChanged)
    ) {
        // A terminal order event alone is not unique final deal+position
        // evidence. Keep the same claim lineage, but block every sibling until
        // the account reconciliation path can settle the final partition.
        nextState = 'unknown';
        reasonCode = 'EXIT_CLAIM_UNKNOWN';
        summaryCode = terminalStatus
            ? 'exit_claim_terminal_pending_reconciliation'
            : 'exit_claim_deal_pending_reconciliation';
    }
    if (nextState === claim.state) {
        return Object.freeze({
            exitClaimId: claim.exit_claim_id,
            state: claim.state,
            revision: claim.revision,
            transitioned: false,
        });
    }
    const terminalAtEpochMs = null;
    const result = database.prepare(`
        UPDATE exit_claims
           SET state=?, evidence_hash=?, updated_at_epoch_ms=?,
               terminal_at_epoch_ms=?, revision=revision+1
         WHERE exit_claim_id=? AND external_lineage=0
           AND intent_id=? AND state=? AND revision=?
    `).run(
        nextState,
        event.brokerEventEvidenceSha256,
        event.timestamps.receiveEpochMs,
        terminalAtEpochMs,
        claim.exit_claim_id,
        intentId,
        claim.state,
        claim.revision,
    );
    if (Number(result.changes) !== 1) {
        throw new Error('broker event ExitClaim transition lost its CAS');
    }
    const protectionState =
        nextState === 'broker_working' ? 'broker_working' : 'unknown';
    const generationResult = database.prepare(`
        UPDATE protection_remainder_generations
           SET state=?, evidence_hash=?, updated_at_epoch_ms=?,
               revision=revision+1
         WHERE protection_group_id=? AND remainder_generation=?
           AND state=? AND revision=?
    `).run(
        protectionState,
        event.brokerEventEvidenceSha256,
        event.timestamps.receiveEpochMs,
        claim.protection_group_id,
        claim.current_generation,
        claim.protection_generation_state,
        claim.protection_generation_revision,
    );
    const groupResult = database.prepare(`
        UPDATE protection_groups
           SET state=?, updated_at_epoch_ms=?, revision=revision+1
         WHERE protection_group_id=? AND state=? AND revision=?
    `).run(
        protectionState,
        event.timestamps.receiveEpochMs,
        claim.protection_group_id,
        claim.protection_group_state,
        claim.protection_group_revision,
    );
    if (
        Number(generationResult.changes) !== 1 ||
        Number(groupResult.changes) !== 1
    ) {
        throw new Error('broker event protection group transition lost its CAS');
    }
    const revision = claim.revision + 1;
    insertTransitionJournalEvent(database, {
        entityKind: 'exit_claim',
        entityId: claim.exit_claim_id,
        revision,
        reasonCode,
        summaryCode,
        nowEpochMs: event.timestamps.receiveEpochMs,
        exchangeEpochMs: event.timestamps.exchangeEpochMs,
        brokerEpochMs: event.timestamps.brokerEpochMs ?? undefined,
        payloadHash: event.brokerEventEvidenceSha256,
        eventSuffix: `broker-event-${event.brokerEventKeySha256.slice(7)}`,
    });
    return Object.freeze({
        exitClaimId: claim.exit_claim_id,
        state: nextState,
        revision,
        transitioned: true,
        protectionGroupId: claim.protection_group_id,
        protectionState,
    });
}

function projectEntryExposureReservationBrokerEvidence(
    database,
    { event, intent, runtimeEpochId },
) {
    if (event.side !== 'Buy') return null;
    const reservation = database.prepare(`
        SELECT reservations.*, commitments.commitment_id
          FROM entry_exposure_reservations AS reservations
          JOIN pending_protection_commitments AS commitments
            ON commitments.entry_intent_id=reservations.intent_id
         WHERE reservations.intent_id=?
    `).get(intent.intent_id);
    if (!reservation) return null;
    const protectedIntent = canonicalProtectedEntryIntentPayload(
        parseStoredCanonicalObject(
            intent.payload_json,
            'broker event protected entry payload',
        ),
    );
    const plan = canonicalProtectedEntryPlan(
        protectedIntent.payload.protectionPlan,
    );
    const observedFilledShares = brokerEventQuantityShares(
        event.quantities.cumulativeDeal,
        event.quantities.unit,
        plan.plan.entryOrder.contractUnit,
        'broker event entry cumulative deal quantity',
    );
    const materialized = database.prepare(`
        SELECT cumulative_filled_shares
          FROM protected_entry_fill_heads WHERE intent_id=?
    `).get(intent.intent_id);
    const materializedFilledShares = materialized?.cumulative_filled_shares ?? 0;
    if (observedFilledShares < materializedFilledShares) {
        throw new Error('broker event entry fill cannot precede its durable fill head');
    }
    const terminalStatus = ['Filled', 'Cancelled', 'Inactive', 'Failed'].includes(
        event.status,
    );
    const reconciliationRequired =
        observedFilledShares > materializedFilledShares || terminalStatus;
    if (
        !reconciliationRequired ||
        ['unknown', 'consumed', 'released'].includes(reservation.state)
    ) {
        return Object.freeze({
            reservationId: reservation.reservation_id,
            state: reservation.state,
            revision: reservation.revision,
            transitioned: false,
            runtimeState: database.prepare(
                'SELECT state FROM runtime_epochs WHERE runtime_epoch_id=?',
            ).get(runtimeEpochId)?.state,
        });
    }
    if (!['reserved', 'partially_consumed'].includes(reservation.state)) {
        throw new Error('broker event entry reservation state is invalid');
    }
    const now = event.timestamps.receiveEpochMs;
    const reservationResult = database.prepare(`
        UPDATE entry_exposure_reservations
           SET state='unknown', updated_at_epoch_ms=?, revision=revision+1
         WHERE reservation_id=? AND state=? AND revision=?
    `).run(
        now,
        reservation.reservation_id,
        reservation.state,
        reservation.revision,
    );
    if (Number(reservationResult.changes) !== 1) {
        throw new Error('broker event entry reservation transition lost its CAS');
    }
    const runtime = database.prepare(`
        SELECT state, revision FROM runtime_epochs WHERE runtime_epoch_id=?
    `).get(runtimeEpochId);
    if (!runtime || !['ready', 'reconciling'].includes(runtime.state)) {
        throw new Error('broker event entry reservation lost its Runtime observer');
    }
    let runtimeRevision = runtime.revision;
    if (runtime.state === 'ready') {
        const runtimeResult = database.prepare(`
            UPDATE runtime_epochs
               SET state='reconciling', reconciliation_evidence_hash=NULL,
                   revision=revision+1
             WHERE runtime_epoch_id=? AND state='ready' AND revision=?
        `).run(runtimeEpochId, runtime.revision);
        if (Number(runtimeResult.changes) !== 1) {
            throw new Error(
                'broker event entry reconciliation transition lost its Runtime CAS',
            );
        }
        runtimeRevision += 1;
        insertTransitionJournalEvent(database, {
            entityKind: 'runtime_epoch',
            entityId: runtimeEpochId,
            revision: runtimeRevision,
            reasonCode: 'RUNTIME_RECONCILIATION_REQUIRED',
            summaryCode: 'entry_broker_event_reconciliation_required',
            nowEpochMs: now,
            payloadHash: event.brokerEventEvidenceSha256,
            eventSuffix: `entry-reconciliation-${event.brokerEventKeySha256.slice(7)}`,
        });
    }
    insertTransitionJournalEvent(database, {
        entityKind: 'entry_exposure_reservation',
        entityId: reservation.reservation_id,
        revision: reservation.revision + 1,
        reasonCode: 'ENTRY_RESERVATION_UNKNOWN',
        summaryCode: 'entry_reservation_unknown_pending_reconciliation',
        nowEpochMs: now,
        payloadHash: event.brokerEventEvidenceSha256,
        eventSuffix: `broker-event-${event.brokerEventKeySha256.slice(7)}`,
    });
    return Object.freeze({
        reservationId: reservation.reservation_id,
        state: 'unknown',
        revision: reservation.revision + 1,
        transitioned: true,
        runtimeState: 'reconciling',
        runtimeRevision,
    });
}

function brokerPriceMinorUnits(value, label) {
    if (typeof value !== 'string' || !/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(value)) {
        throw new TypeError(`${label} must be a positive two-decimal TWD price`);
    }
    const [integer, fraction = ''] = value.split('.');
    const amount = BigInt(integer) * 100n + BigInt(fraction.padEnd(2, '0'));
    if (amount < 1n || amount > BigInt(Number.MAX_SAFE_INTEGER)) {
        throw new TypeError(`${label} exceeds safe TWD price bounds`);
    }
    return Number(amount);
}

function beginBrokerEventReconciliation(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'apiGeneration',
            'eventEvidenceSha256',
            'nowEpochMs',
            'runtimeEpochId',
            'senderFence',
        ])
    ) {
        throw new TypeError(
            'broker event reconciliation latch input schema is invalid',
        );
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const eventEvidenceSha256 = sha256Digest(
        input.eventEvidenceSha256,
        'brokerEventReconciliation.eventEvidenceSha256',
    );
    const now = safeInteger(
        input.nowEpochMs,
        'brokerEventReconciliation.nowEpochMs',
    );
    return transaction(database, () => {
        if (
            !currentRuntimeObserverMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error(
                'broker event reconciliation requires the current Runtime observer',
            );
        }
        const runtime = database.prepare(`
            SELECT state, revision FROM runtime_epochs
             WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
        `).get(runtimeEpochId, senderFence, apiGeneration);
        if (!runtime || !['ready', 'reconciling'].includes(runtime.state)) {
            throw new Error(
                'broker event reconciliation lost its durable Runtime state',
            );
        }
        let runtimeRevision = runtime.revision;
        let transitioned = false;
        if (runtime.state === 'ready') {
            const result = database.prepare(`
                UPDATE runtime_epochs
                   SET state='reconciling', reconciliation_evidence_hash=NULL,
                       revision=revision+1
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state='ready' AND revision=?
            `).run(
                runtimeEpochId,
                senderFence,
                apiGeneration,
                runtime.revision,
            );
            if (Number(result.changes) !== 1) {
                throw new Error(
                    'broker event reconciliation Runtime transition lost its CAS',
                );
            }
            runtimeRevision += 1;
            transitioned = true;
            insertTransitionJournalEvent(database, {
                entityKind: 'runtime_epoch',
                entityId: runtimeEpochId,
                revision: runtimeRevision,
                reasonCode: 'RUNTIME_RECONCILIATION_REQUIRED',
                summaryCode: 'broker_event_observed_reconciliation_required',
                nowEpochMs: now,
                payloadHash: eventEvidenceSha256,
                eventSuffix: `broker-observation-${eventEvidenceSha256.slice(7)}`,
            });
        }
        const observationRevision = advanceLifecycleSideEffectRevision(database);
        return Object.freeze({
            state: 'reconciling',
            runtimeRevision,
            observationRevision,
            transitioned,
            dispatchAllowed: false,
            brokerWriteAuthority: false,
        });
    });
}

function recordCanonicalBrokerEvent(database, input) {
    if (!exactKeys(input, [
        'apiGeneration',
        'event',
        'runtimeEpochId',
        'senderFence',
    ])) {
        throw new TypeError('canonical broker event input schema is invalid');
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const event = revalidateNormalizedCanonicalSmartOrderBrokerEvent(input.event);
    return transaction(database, () => {
        if (
            !currentRuntimeObserverMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            }) ||
            event.apiGeneration !== apiGeneration
        ) {
            throw new Error(
                'broker event requires the current reconciling or ready Runtime observer',
            );
        }
        const identifierValues = Object.entries(event.identifiers).filter(
            ([kind, value]) =>
                BROKER_CORRELATION_IDENTIFIER_KINDS.includes(kind) &&
                typeof value === 'string' &&
                value.length > 0,
        );
        if (identifierValues.length === 0) {
            throw new Error(
                'broker event has no durable correlation identifiers',
            );
        }
        const findBinding = database.prepare(`
            SELECT intent_id, correlation_id
              FROM broker_correlation_identifiers
             WHERE account_broker_ref=? AND account_id_ref=?
               AND trade_date=? AND contract_key=? AND side=?
               AND identifier_kind=? AND identifier_value=?
        `);
        const resolved = identifierValues.map(([kind, value]) =>
            findBinding.get(
                event.account.brokerId,
                event.account.accountId,
                event.tradeDate,
                event.contractKey,
                event.side,
                kind,
                value,
            ),
        );
        const requiredLineageKinds = new Set(['tradeId', 'seqno']);
        const missingRequiredLineage = identifierValues.some(
            ([kind], index) =>
                requiredLineageKinds.has(kind) && !resolved[index],
        );
        const matched = resolved.filter(Boolean);
        if (
            missingRequiredLineage ||
            matched.length < requiredLineageKinds.size ||
            new Set(matched.map((row) => row.correlation_id)).size !== 1 ||
            new Set(matched.map((row) => row.intent_id)).size !== 1
        ) {
                throw new Error(
                    'broker event identifiers did not resolve to one durable correlation',
                );
        }
        const [{ intent_id: intentId }] = matched;
        const intent = database
            .prepare(`
                SELECT intent_id, account_broker_ref, account_id_ref,
                       trade_date, contract_key, side, payload_json,
                       state, adapter_authority_granted, runtime_epoch_id,
                       sender_fence, api_generation
                  FROM order_intents WHERE intent_id=?
            `)
            .get(intentId);
        if (!intent) throw new Error('broker event intent does not exist');
        if (
            intent.adapter_authority_granted !== 1 ||
            ![
                'dispatching',
                'acknowledged',
                'reconciling',
                'unknown',
                'terminal',
            ].includes(intent.state) ||
            intent.runtime_epoch_id !== runtimeEpochId ||
            intent.sender_fence !== senderFence ||
            intent.api_generation !== apiGeneration
        ) {
            throw new Error(
                'broker event must bind a dispatched intent and its sender fence',
            );
        }
        if (
            event.account.brokerId !== intent.account_broker_ref ||
            event.account.accountId !== intent.account_id_ref ||
            event.tradeDate !== intent.trade_date ||
            event.contractKey !== intent.contract_key ||
            event.side !== intent.side
        ) {
            throw new Error('broker event scope does not match its durable intent');
        }
        const duplicate = database
            .prepare(`
                SELECT evidence_hash, payload_hash, intent_id
                  FROM broker_event_records WHERE broker_event_key_hash=?
            `)
            .get(event.brokerEventKeySha256);
        if (duplicate) {
            if (
                duplicate.intent_id !== intentId ||
                duplicate.evidence_hash !== event.brokerEventEvidenceSha256 ||
                duplicate.payload_hash !== event.payloadSha256
            ) {
                throw new Error('broker event key collided with different evidence');
            }
            // Exact replay may rebuild a derived projection from already
            // durable canonical evidence. A stale or conflicting event below
            // must never mutate reservation or claim authority.
            const exitClaimProjection = projectInternalExitClaimBrokerEvidence(
                database,
                { event, intentId },
            );
            const entryExposureReservationProjection =
                projectEntryExposureReservationBrokerEvidence(database, {
                    event,
                    intent,
                    runtimeEpochId,
                });
            return Object.freeze({
                state: 'duplicate',
                intentId,
                brokerEventKeySha256: event.brokerEventKeySha256,
                brokerEventEvidenceSha256: event.brokerEventEvidenceSha256,
                exitClaimProjection,
                entryExposureReservationProjection,
                runtimeState:
                    entryExposureReservationProjection?.runtimeState ??
                    database.prepare(
                        'SELECT state FROM runtime_epochs WHERE runtime_epoch_id=?',
                    ).get(runtimeEpochId)?.state,
                repositoryMutationAuthority: false,
                brokerWriteAuthority: false,
            });
        }
        for (const [column, value] of [
            ['deal_id', event.identifiers.dealId],
            ['exchange_sequence', event.identifiers.exchangeSequence],
        ]) {
            if (value === null) continue;
            const conflict = database
                .prepare(`
                    SELECT broker_event_key_hash, intent_id
                      FROM broker_event_records
                     WHERE account_broker_ref=? AND account_id_ref=?
                       AND trade_date=? AND ${column}=?
                     LIMIT 1
                `)
                .get(
                    intent.account_broker_ref,
                    intent.account_id_ref,
                    intent.trade_date,
                    value,
                );
            if (
                conflict &&
                (conflict.broker_event_key_hash !== event.brokerEventKeySha256 ||
                    conflict.intent_id !== intentId)
            ) {
                throw new Error(`${column} collides with another same-date broker event`);
            }
        }
        const head = database
            .prepare(`
                SELECT * FROM broker_event_heads
                 WHERE account_broker_ref=? AND account_id_ref=?
                   AND trade_date=? AND broker_order_correlation_key_hash=?
            `)
            .get(
                intent.account_broker_ref,
                intent.account_id_ref,
                intent.trade_date,
                event.brokerOrderCorrelationKeySha256,
            );
        let headRevision = 0;
        if (head) {
            if (
                head.intent_id !== intentId ||
                head.order_quantity !== event.quantities.order ||
                head.quantity_unit !== event.quantities.unit
            ) {
                throw new Error('broker event changed its durable order lineage');
            }
            const projectionChanged =
                head.status !== event.status ||
                head.cumulative_deal_quantity !==
                    event.quantities.cumulativeDeal ||
                head.cumulative_cancel_quantity !==
                    event.quantities.cumulativeCancel ||
                head.remaining_quantity !== event.quantities.remaining;
            const terminalFillRepartition =
                CANONICAL_BROKER_EVENT_PROGRESS[head.status] === 4 &&
                event.eventKind === 'deal' &&
                event.timestamps.exchangeEpochMs > head.exchange_epoch_ms &&
                head.remaining_quantity === 0 &&
                event.quantities.remaining === 0 &&
                event.quantities.cumulativeDeal >
                    head.cumulative_deal_quantity &&
                event.quantities.cumulativeCancel <
                    head.cumulative_cancel_quantity &&
                event.quantities.cumulativeDeal +
                    event.quantities.cumulativeCancel ===
                    head.order_quantity;
            if (
                head.exchange_epoch_ms === event.timestamps.exchangeEpochMs &&
                projectionChanged
            ) {
                throw new Error('broker event head has conflicting same-time evidence');
            }
            const stale =
                event.timestamps.exchangeEpochMs < head.exchange_epoch_ms ||
                (!terminalFillRepartition &&
                    (event.quantities.cumulativeDeal <
                        head.cumulative_deal_quantity ||
                        event.quantities.cumulativeCancel <
                            head.cumulative_cancel_quantity)) ||
                event.quantities.remaining > head.remaining_quantity ||
                CANONICAL_BROKER_EVENT_PROGRESS[event.status] <
                    CANONICAL_BROKER_EVENT_PROGRESS[head.status];
            if (stale) {
                return Object.freeze({
                    state: 'stale',
                    intentId,
                    brokerEventKeySha256: event.brokerEventKeySha256,
                    brokerEventEvidenceSha256: event.brokerEventEvidenceSha256,
                    runtimeState: database.prepare(
                        'SELECT state FROM runtime_epochs WHERE runtime_epoch_id=?',
                    ).get(runtimeEpochId)?.state,
                    repositoryMutationAuthority: false,
                    brokerWriteAuthority: false,
                });
            }
            if (
                CANONICAL_BROKER_EVENT_PROGRESS[head.status] === 4 &&
                projectionChanged &&
                !terminalFillRepartition
            ) {
                throw new Error('terminal broker event head cannot change');
            }
            headRevision = head.revision + 1;
        }
        const exitClaimProjection = projectInternalExitClaimBrokerEvidence(
            database,
            { event, intentId },
        );
        const entryExposureReservationProjection =
            projectEntryExposureReservationBrokerEvidence(database, {
                event,
                intent,
                runtimeEpochId,
            });
        database
            .prepare(`
                INSERT INTO broker_event_records(
                    broker_event_key_hash, broker_order_correlation_key_hash,
                    intent_id, mapping_revision, api_generation, event_kind,
                    account_broker_ref, account_id_ref, trade_date,
                    contract_key, side, trade_id, order_id, deal_id, seqno,
                    ordno, exchange_sequence, custom_field, operation_type,
                    operation_code, operation_message, status,
                    order_condition, order_lot, price_type, time_in_force,
                    order_quantity, cumulative_deal_quantity,
                    cumulative_cancel_quantity, remaining_quantity,
                    event_deal_quantity, quantity_unit, price_decimal,
                    exchange_epoch_ms, broker_epoch_ms, receive_epoch_ms,
                    evidence_hash, payload_hash
                ) VALUES (
                    ?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,
                    ?,?,?,?,?,?,?,?,?
                )
            `)
            .run(
                event.brokerEventKeySha256,
                event.brokerOrderCorrelationKeySha256,
                intentId,
                event.mappingRevision,
                event.apiGeneration,
                event.eventKind,
                intent.account_broker_ref,
                intent.account_id_ref,
                event.tradeDate,
                event.contractKey,
                event.side,
                event.identifiers.tradeId,
                event.identifiers.orderId,
                event.identifiers.dealId,
                event.identifiers.seqno,
                event.identifiers.ordno,
                event.identifiers.exchangeSequence,
                event.identifiers.customField,
                event.operation.type,
                event.operation.code,
                event.operation.message,
                event.status,
                event.orderClass.orderCondition,
                event.orderClass.orderLot,
                event.orderClass.priceType,
                event.orderClass.timeInForce,
                event.quantities.order,
                event.quantities.cumulativeDeal,
                event.quantities.cumulativeCancel,
                event.quantities.remaining,
                event.quantities.eventDeal,
                event.quantities.unit,
                event.price,
                event.timestamps.exchangeEpochMs,
                event.timestamps.brokerEpochMs,
                event.timestamps.receiveEpochMs,
                event.brokerEventEvidenceSha256,
                event.payloadSha256,
            );
        database
            .prepare(`
                INSERT INTO broker_event_heads(
                    account_broker_ref, account_id_ref, trade_date,
                    broker_order_correlation_key_hash, intent_id, status,
                    order_quantity, cumulative_deal_quantity,
                    cumulative_cancel_quantity, remaining_quantity,
                    quantity_unit, exchange_epoch_ms, broker_event_key_hash,
                    evidence_hash, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(
                    account_broker_ref, account_id_ref, trade_date,
                    broker_order_correlation_key_hash
                ) DO UPDATE SET
                    status=excluded.status,
                    cumulative_deal_quantity=excluded.cumulative_deal_quantity,
                    cumulative_cancel_quantity=excluded.cumulative_cancel_quantity,
                    remaining_quantity=excluded.remaining_quantity,
                    exchange_epoch_ms=excluded.exchange_epoch_ms,
                    broker_event_key_hash=excluded.broker_event_key_hash,
                    evidence_hash=excluded.evidence_hash,
                    revision=excluded.revision
            `)
            .run(
                intent.account_broker_ref,
                intent.account_id_ref,
                intent.trade_date,
                event.brokerOrderCorrelationKeySha256,
                intentId,
                event.status,
                event.quantities.order,
                event.quantities.cumulativeDeal,
                event.quantities.cumulativeCancel,
                event.quantities.remaining,
                event.quantities.unit,
                event.timestamps.exchangeEpochMs,
                event.brokerEventKeySha256,
                event.brokerEventEvidenceSha256,
                headRevision,
            );
        advanceLifecycleSideEffectRevision(database);
        insertTransitionJournalEvent(database, {
            entityKind: 'broker_event',
            entityId: event.brokerEventKeySha256,
            revision: 0,
            reasonCode: 'CANONICAL_BROKER_EVENT_ACCEPTED',
            summaryCode: `broker_${event.eventKind}_${event.status}`,
            nowEpochMs: event.timestamps.receiveEpochMs,
            exchangeEpochMs: event.timestamps.exchangeEpochMs,
            brokerEpochMs: event.timestamps.brokerEpochMs ?? undefined,
            payloadHash: event.payloadSha256,
            eventSuffix: 'accepted',
        });
        return Object.freeze({
            state: 'accepted',
            intentId,
            brokerEventKeySha256: event.brokerEventKeySha256,
            brokerEventEvidenceSha256: event.brokerEventEvidenceSha256,
            brokerOrderCorrelationKeySha256:
                event.brokerOrderCorrelationKeySha256,
            headRevision,
            exitClaimProjection,
            entryExposureReservationProjection,
            runtimeState:
                entryExposureReservationProjection?.runtimeState ??
                database.prepare(
                    'SELECT state FROM runtime_epochs WHERE runtime_epoch_id=?',
                ).get(runtimeEpochId)?.state,
            runtimeRevision:
                entryExposureReservationProjection?.runtimeRevision,
            repositoryMutationAuthority: false,
            brokerWriteAuthority: false,
        });
    });
}

function canonicalReconciliationProjection(input) {
    const baseKeys = [
        'account',
        'asOfEpochMs',
        'coverageComplete',
        'deals',
        'eventStreamWatermarkSha256',
        'evidenceSha256',
        'pnlPolicyDefinitionSha256',
        'pnlPolicyRevision',
        'positions',
        'schemaVersion',
        'snapshotSha256',
        'sourceRevision',
        'sourceSnapshotSha256',
        'tradeDate',
        'workingOrders',
    ];
    const extendedKeys = [
        ...baseKeys,
        'externalSellClaimCandidates',
        'fullDayTotals',
        'reconciliationGeneration',
    ];
    const extended = exactKeys(input, extendedKeys);
    if (
        (!extended && !exactKeys(input, baseKeys)) ||
        input.schemaVersion !==
            'smart-order-account-reconciliation-projection/2026-08-13.2' ||
        input.coverageComplete !== true ||
        !exactKeys(input.account, ['accountId', 'accountType', 'brokerId']) ||
        input.account.accountType !== 'S'
    ) {
        throw new TypeError('account reconciliation projection is invalid');
    }
    assertCanonicalPnlPolicyBinding({
        policyRevision: boundedToken(
            input.pnlPolicyRevision,
            'reconciliation.pnlPolicyRevision',
        ),
        policyDefinitionSha256: sha256Digest(
            input.pnlPolicyDefinitionSha256,
            'reconciliation.pnlPolicyDefinitionSha256',
        ),
    });
    if (!Array.isArray(input.deals)) {
        throw new TypeError('reconciliation deals must be an array');
    }
    const deals = input.deals.map((deal, index) => {
        if (
            !exactKeys(deal, [
                'dealId',
                'feeMinorUnits',
                'realizedMinorUnits',
                'transactionTaxMinorUnits',
            ])
        ) {
            throw new TypeError(`reconciliation deal ${index} is invalid`);
        }
        return Object.freeze({
            dealId: boundedToken(
                deal.dealId,
                `reconciliation.deals[${index}].dealId`,
            ),
            feeMinorUnits: safeInteger(
                deal.feeMinorUnits,
                `reconciliation.deals[${index}].feeMinorUnits`,
            ),
            realizedMinorUnits: safeInteger(
                deal.realizedMinorUnits,
                `reconciliation.deals[${index}].realizedMinorUnits`,
                { minimum: Number.MIN_SAFE_INTEGER },
            ),
            transactionTaxMinorUnits: safeInteger(
                deal.transactionTaxMinorUnits,
                `reconciliation.deals[${index}].transactionTaxMinorUnits`,
            ),
        });
    });
    if (
        new Set(deals.map((deal) => deal.dealId)).size !== deals.length ||
        stableCanonicalJson(deals.map((deal) => deal.dealId)) !==
            stableCanonicalJson(
                deals.map((deal) => deal.dealId).sort(),
            )
    ) {
        throw new TypeError('reconciliation deal IDs must be sorted and unique');
    }
    const positions = input.positions.map((position, index) => {
        if (
            !exactKeys(position, [
                'averagePriceMinorUnits',
                'availableShares',
                'contractKey',
                'lastPriceMinorUnits',
                'positionLineageId',
                'quantityShares',
                'unrealizedMinorUnits',
                'yesterdayQuantityShares',
            ])
        ) {
            throw new TypeError(`reconciliation position ${index} is invalid`);
        }
        const quantityShares = safeInteger(
            position.quantityShares,
            `reconciliation.positions[${index}].quantityShares`,
        );
        const availableShares = safeInteger(
            position.availableShares,
            `reconciliation.positions[${index}].availableShares`,
        );
        if (availableShares > quantityShares) {
            throw new TypeError('reconciliation available shares exceed position');
        }
        return Object.freeze({
            averagePriceMinorUnits: safeInteger(
                position.averagePriceMinorUnits,
                `reconciliation.positions[${index}].averagePriceMinorUnits`,
            ),
            availableShares,
            contractKey: boundedToken(
                position.contractKey,
                `reconciliation.positions[${index}].contractKey`,
            ),
            lastPriceMinorUnits: safeInteger(
                position.lastPriceMinorUnits,
                `reconciliation.positions[${index}].lastPriceMinorUnits`,
            ),
            positionLineageId: boundedToken(
                position.positionLineageId,
                `reconciliation.positions[${index}].positionLineageId`,
            ),
            quantityShares,
            unrealizedMinorUnits: safeInteger(
                position.unrealizedMinorUnits,
                `reconciliation.positions[${index}].unrealizedMinorUnits`,
                { minimum: Number.MIN_SAFE_INTEGER },
            ),
            yesterdayQuantityShares: safeInteger(
                position.yesterdayQuantityShares,
                `reconciliation.positions[${index}].yesterdayQuantityShares`,
            ),
        });
    });
    if (
        new Set(positions.map((position) => position.contractKey)).size !==
        positions.length
    ) {
        throw new TypeError('reconciliation positions contain duplicate contracts');
    }
    const workingOrders = input.workingOrders.map((workingOrder, index) => {
        if (
            !exactKeys(workingOrder, [
                'brokerOrderId',
                'contractKey',
                'filledShares',
                'origin',
                'quantityShares',
                'remainingShares',
                'side',
                'state',
            ]) ||
            !['external', 'runtime'].includes(workingOrder.origin) ||
            !['Buy', 'Sell'].includes(workingOrder.side)
        ) {
            throw new TypeError(`reconciliation working order ${index} is invalid`);
        }
        const quantityShares = safeInteger(
            workingOrder.quantityShares,
            `reconciliation.workingOrders[${index}].quantityShares`,
            { minimum: 1 },
        );
        const filledShares = safeInteger(
            workingOrder.filledShares,
            `reconciliation.workingOrders[${index}].filledShares`,
        );
        const remainingShares = safeInteger(
            workingOrder.remainingShares,
            `reconciliation.workingOrders[${index}].remainingShares`,
        );
        if (filledShares + remainingShares !== quantityShares) {
            throw new TypeError('reconciliation working order quantity is inconsistent');
        }
        return Object.freeze({
            brokerOrderId: boundedToken(
                workingOrder.brokerOrderId,
                `reconciliation.workingOrders[${index}].brokerOrderId`,
            ),
            contractKey: boundedToken(
                workingOrder.contractKey,
                `reconciliation.workingOrders[${index}].contractKey`,
            ),
            filledShares,
            origin: workingOrder.origin,
            quantityShares,
            remainingShares,
            side: workingOrder.side,
            state: boundedToken(
                workingOrder.state,
                `reconciliation.workingOrders[${index}].state`,
            ),
        });
    });
    if (
        new Set(workingOrders.map((order) => order.brokerOrderId)).size !==
        workingOrders.length
    ) {
        throw new TypeError('reconciliation working orders contain duplicate IDs');
    }
    let fullDayTotals;
    let externalSellClaimCandidates;
    let reconciliationGeneration;
    if (extended) {
        if (
            !exactKeys(input.fullDayTotals, [
                'feeMinorUnits',
                'netMinorUnits',
                'realizedMinorUnits',
                'transactionTaxMinorUnits',
                'unrealizedMinorUnits',
            ]) ||
            !Array.isArray(input.externalSellClaimCandidates)
        ) {
            throw new TypeError('extended reconciliation projection is invalid');
        }
        fullDayTotals = Object.freeze({
            feeMinorUnits: safeInteger(
                input.fullDayTotals.feeMinorUnits,
                'reconciliation.fullDayTotals.feeMinorUnits',
            ),
            netMinorUnits: safeInteger(
                input.fullDayTotals.netMinorUnits,
                'reconciliation.fullDayTotals.netMinorUnits',
                { minimum: Number.MIN_SAFE_INTEGER },
            ),
            realizedMinorUnits: safeInteger(
                input.fullDayTotals.realizedMinorUnits,
                'reconciliation.fullDayTotals.realizedMinorUnits',
                { minimum: Number.MIN_SAFE_INTEGER },
            ),
            transactionTaxMinorUnits: safeInteger(
                input.fullDayTotals.transactionTaxMinorUnits,
                'reconciliation.fullDayTotals.transactionTaxMinorUnits',
            ),
            unrealizedMinorUnits: safeInteger(
                input.fullDayTotals.unrealizedMinorUnits,
                'reconciliation.fullDayTotals.unrealizedMinorUnits',
                { minimum: Number.MIN_SAFE_INTEGER },
            ),
        });
        reconciliationGeneration = safeInteger(
            input.reconciliationGeneration,
            'reconciliation.reconciliationGeneration',
            { minimum: 1 },
        );
        externalSellClaimCandidates = Object.freeze(
            input.externalSellClaimCandidates.map((candidate, index) => {
                if (
                    !exactKeys(candidate, [
                        'accountScopeSha256',
                        'brokerOrderId',
                        'candidateId',
                        'contractKey',
                        'evidenceSha256',
                        'positionLineageId',
                        'quantityShares',
                        'repositoryMutationAuthority',
                        'state',
                    ]) ||
                    candidate.repositoryMutationAuthority !== false ||
                    candidate.state !== 'broker_working'
                ) {
                    throw new TypeError(
                        `reconciliation external claim candidate ${index} is invalid`,
                    );
                }
                return Object.freeze({
                    accountScopeSha256: sha256Digest(
                        candidate.accountScopeSha256,
                        `reconciliation.externalSellClaimCandidates[${index}].accountScopeSha256`,
                    ),
                    brokerOrderId: boundedToken(
                        candidate.brokerOrderId,
                        `reconciliation.externalSellClaimCandidates[${index}].brokerOrderId`,
                    ),
                    candidateId: boundedToken(
                        candidate.candidateId,
                        `reconciliation.externalSellClaimCandidates[${index}].candidateId`,
                    ),
                    contractKey: boundedToken(
                        candidate.contractKey,
                        `reconciliation.externalSellClaimCandidates[${index}].contractKey`,
                    ),
                    evidenceSha256: sha256Digest(
                        candidate.evidenceSha256,
                        `reconciliation.externalSellClaimCandidates[${index}].evidenceSha256`,
                    ),
                    positionLineageId: boundedToken(
                        candidate.positionLineageId,
                        `reconciliation.externalSellClaimCandidates[${index}].positionLineageId`,
                    ),
                    quantityShares: safeInteger(
                        candidate.quantityShares,
                        `reconciliation.externalSellClaimCandidates[${index}].quantityShares`,
                        { minimum: 1 },
                    ),
                });
            }),
        );
    }
    return Object.freeze({
        schemaVersion: input.schemaVersion,
        account: Object.freeze({
            brokerId: boundedToken(input.account.brokerId, 'reconciliation.account.brokerId'),
            accountId: boundedToken(input.account.accountId, 'reconciliation.account.accountId'),
            accountType: 'S',
        }),
        tradeDate: taipeiTradeDate(input.tradeDate),
        asOfEpochMs: safeInteger(input.asOfEpochMs, 'reconciliation.asOfEpochMs'),
        sourceRevision: boundedToken(input.sourceRevision, 'reconciliation.sourceRevision'),
        sourceSnapshotSha256: sha256Digest(
            input.sourceSnapshotSha256,
            'reconciliation.sourceSnapshotSha256',
        ),
        snapshotSha256: sha256Digest(
            input.snapshotSha256,
            'reconciliation.snapshotSha256',
        ),
        evidenceSha256: sha256Digest(
            input.evidenceSha256,
            'reconciliation.evidenceSha256',
        ),
        eventStreamWatermarkSha256: sha256Digest(
            input.eventStreamWatermarkSha256,
            'reconciliation.eventStreamWatermarkSha256',
        ),
        deals: Object.freeze(deals),
        pnlPolicyDefinitionSha256:
            SMART_ORDER_CANONICAL_PNL_POLICY_DEFINITION_SHA256,
        pnlPolicyRevision: SMART_ORDER_CANONICAL_PNL_POLICY_REVISION,
        positions: Object.freeze(positions),
        workingOrders: Object.freeze(workingOrders),
        ...(extended
            ? {
                  externalSellClaimCandidates,
                  fullDayTotals,
                  reconciliationGeneration,
              }
            : {}),
    });
}

function reconcileUntriggeredProtectionPositionDrift(
    database,
    { projection, now },
) {
    const activeClaims = database.prepare(`
        SELECT claims.*, obligations.strategy_id AS strategy_id,
               obligations.state AS obligation_state,
               obligations.revision AS obligation_revision,
               strategies.state AS strategy_state,
               strategies.revision AS strategy_revision,
               strategies.definition_hash AS strategy_definition_hash,
               groups.protection_group_id,
               groups.state AS protection_group_state,
               groups.current_generation AS protection_group_generation,
               groups.revision AS protection_group_revision,
               generations.state AS protection_generation_state,
               generations.revision AS protection_generation_revision
          FROM exit_claims AS claims
          JOIN protection_obligations AS obligations
            ON obligations.obligation_id=claims.obligation_id
          JOIN strategies ON strategies.strategy_id=obligations.strategy_id
          JOIN protection_groups AS groups
            ON groups.exit_claim_id=claims.exit_claim_id
          JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
         WHERE claims.external_lineage=0
           AND claims.account_broker_ref=? AND claims.account_id_ref=?
           AND claims.state IN (
               'monitoring_reserved','intent_reserved','broker_working','unknown'
           )
           AND obligations.state='monitoring'
           AND strategies.state IN (
               'observing','monitoring','paused','recovery',
               'cancel_pending','expired_with_obligation'
           )
         ORDER BY strategies.strategy_id, claims.contract_key,
                  claims.position_lineage_id, claims.remainder_generation,
                  claims.allocation_start_share, claims.exit_claim_id
    `).all(projection.account.brokerId, projection.account.accountId);
    const strategies = new Map();
    for (const claim of activeClaims) {
        const strategy = strategies.get(claim.strategy_id) ?? {
            strategyId: claim.strategy_id,
            state: claim.strategy_state,
            revision: claim.strategy_revision,
            definitionHash: claim.strategy_definition_hash,
            claims: [],
        };
        strategy.claims.push(claim);
        strategies.set(claim.strategy_id, strategy);
    }
    let protectionReservationShrinkCount = 0;
    let protectionReservationReleasedCount = 0;
    let protectionManualInterventionCount = 0;
    let protectionShrunkShares = 0;
    for (const strategy of strategies.values()) {
        const claimsByContract = new Map();
        for (const claim of strategy.claims) {
            const claims = claimsByContract.get(claim.contract_key) ?? [];
            claims.push(claim);
            claimsByContract.set(claim.contract_key, claims);
        }
        const shrinkPlans = [];
        const manualReasons = [];
        for (const [contractKey, claims] of claimsByContract) {
            const position = projection.positions.find(
                (candidate) => candidate.contractKey === contractKey,
            );
            const workingSells = projection.workingOrders.filter(
                (order) =>
                    order.contractKey === contractKey &&
                    order.side === 'Sell' &&
                    order.remainingShares > 0,
            );
            let remainingWorkingSellShares = 0;
            for (const order of workingSells) {
                remainingWorkingSellShares = addExposureInteger(
                    remainingWorkingSellShares,
                    order.remainingShares,
                    'position drift working sell shares',
                );
            }
            const safeCapacity = position
                ? Math.min(
                      position.availableShares,
                      Math.max(
                          0,
                          position.quantityShares - remainingWorkingSellShares,
                      ),
                  )
                : 0;
            let priorEnd = 0;
            let intervalConflict = false;
            let lineageConflict = !position;
            let exceedsCapacity = !position;
            for (const claim of claims) {
                const claimEnd = addExposureInteger(
                    claim.allocation_start_share,
                    claim.quantity_shares,
                    'position drift claim interval',
                );
                if (claim.allocation_start_share < priorEnd) {
                    intervalConflict = true;
                }
                priorEnd = Math.max(priorEnd, claimEnd);
                if (
                    !position ||
                    claim.position_lineage_id !== position.positionLineageId
                ) {
                    lineageConflict = true;
                }
                if (claimEnd > safeCapacity) exceedsCapacity = true;
                const nextQuantity = Math.max(
                    0,
                    Math.min(claimEnd, safeCapacity) -
                        claim.allocation_start_share,
                );
                shrinkPlans.push({ claim, nextQuantity, safeCapacity });
            }
            if (!exceedsCapacity && !lineageConflict && !intervalConflict) {
                shrinkPlans.splice(shrinkPlans.length - claims.length, claims.length);
                continue;
            }
            const hasWorkingOrUnknownRace =
                workingSells.length > 0 ||
                claims.some((claim) => claim.state !== 'monitoring_reserved');
            if (
                !position ||
                lineageConflict ||
                intervalConflict ||
                hasWorkingOrUnknownRace
            ) {
                manualReasons.push({
                    contractKey,
                    positionPresent: Boolean(position),
                    lineageConflict,
                    intervalConflict,
                    hasWorkingOrUnknownRace,
                    safeCapacity,
                });
            }
        }
        if (manualReasons.length > 0) {
            const scopeHash = sha256Canonical(
                {
                    strategyId: strategy.strategyId,
                    contractKeys: [...claimsByContract.keys()].sort(),
                    tradeDate: projection.tradeDate,
                },
                'reconciliation position drift resolution scope',
            );
            const evidenceHash = sha256Canonical(
                {
                    projectionEvidenceSha256: projection.evidenceSha256,
                    sourceRevision: projection.sourceRevision,
                    reasons: manualReasons,
                },
                'reconciliation position drift evidence',
            );
            const identity = sha256Canonical(
                {
                    strategyId: strategy.strategyId,
                    reasonCode: 'EXTERNAL_POSITION_DRIFT',
                    evidenceHash,
                },
                'reconciliation position drift identity',
            ).slice('sha256:'.length);
            const resolutionCaseId = `resolution-${identity}`;
            const blockerId = `blocker-${identity}`;
            const strategyUpdate = database.prepare(`
                UPDATE strategies
                   SET state='manual_intervention', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE strategy_id=? AND state=? AND revision=?
            `).run(
                now,
                strategy.strategyId,
                strategy.state,
                strategy.revision,
            );
            if (Number(strategyUpdate.changes) !== 1) {
                throw new Error('position drift strategy transition lost its CAS');
            }
            const obligations = new Map();
            for (const claim of strategy.claims) {
                const claimEvidenceHash = sha256Canonical(
                    {
                        priorEvidenceHash: claim.evidence_hash,
                        reconciliationEvidenceHash: projection.evidenceSha256,
                        disposition: 'unknown_manual_intervention',
                    },
                    'position drift unknown claim evidence',
                );
                const claimUpdate = database.prepare(`
                    UPDATE exit_claims
                       SET state='unknown', evidence_hash=?,
                           updated_at_epoch_ms=?, terminal_at_epoch_ms=NULL,
                           revision=revision+1
                     WHERE exit_claim_id=? AND state=? AND revision=?
                `).run(
                    claimEvidenceHash,
                    now,
                    claim.exit_claim_id,
                    claim.state,
                    claim.revision,
                );
                if (Number(claimUpdate.changes) !== 1) {
                    throw new Error('position drift ExitClaim transition lost its CAS');
                }
                const generationUpdate = database.prepare(`
                    UPDATE protection_remainder_generations
                       SET state='unknown', evidence_hash=?,
                           updated_at_epoch_ms=?, revision=revision+1
                     WHERE protection_group_id=? AND remainder_generation=?
                       AND state=? AND revision=?
                `).run(
                    claimEvidenceHash,
                    now,
                    claim.protection_group_id,
                    claim.protection_group_generation,
                    claim.protection_generation_state,
                    claim.protection_generation_revision,
                );
                const groupUpdate = database.prepare(`
                    UPDATE protection_groups
                       SET state='unknown', updated_at_epoch_ms=?,
                           revision=revision+1
                     WHERE protection_group_id=? AND state=? AND revision=?
                `).run(
                    now,
                    claim.protection_group_id,
                    claim.protection_group_state,
                    claim.protection_group_revision,
                );
                if (
                    Number(generationUpdate.changes) !== 1 ||
                    Number(groupUpdate.changes) !== 1
                ) {
                    throw new Error(
                        'position drift protection group transition lost its CAS',
                    );
                }
                obligations.set(claim.obligation_id, claim);
                insertTransitionJournalEvent(database, {
                    entityKind: 'exit_claim',
                    entityId: claim.exit_claim_id,
                    revision: claim.revision + 1,
                    reasonCode: 'EXIT_CLAIM_UNKNOWN',
                    summaryCode: 'position_drift_exit_claim_unknown',
                    nowEpochMs: now,
                    payloadHash: claimEvidenceHash,
                    eventSuffix: 'account-reconciliation-position-drift',
                });
                insertTransitionJournalEvent(database, {
                    entityKind: 'protection_group',
                    entityId: claim.protection_group_id,
                    revision: claim.protection_group_revision + 1,
                    reasonCode: 'EXTERNAL_POSITION_DRIFT',
                    summaryCode: 'protection_group_unknown_position_drift',
                    nowEpochMs: now,
                    payloadHash: claimEvidenceHash,
                    eventSuffix: 'account-reconciliation-position-drift',
                });
            }
            for (const obligation of obligations.values()) {
                const obligationUpdate = database.prepare(`
                    UPDATE protection_obligations
                       SET state='safety_blocked', updated_at_epoch_ms=?,
                           revision=revision+1
                     WHERE obligation_id=? AND state='monitoring' AND revision=?
                `).run(
                    now,
                    obligation.obligation_id,
                    obligation.obligation_revision,
                );
                if (Number(obligationUpdate.changes) !== 1) {
                    throw new Error(
                        'position drift protection obligation transition lost its CAS',
                    );
                }
                insertTransitionJournalEvent(database, {
                    entityKind: 'protection_obligation',
                    entityId: obligation.obligation_id,
                    revision: obligation.obligation_revision + 1,
                    reasonCode: 'EXTERNAL_POSITION_DRIFT',
                    summaryCode: 'protection_obligation_safety_blocked',
                    nowEpochMs: now,
                    payloadHash: evidenceHash,
                    eventSuffix: 'account-reconciliation-position-drift',
                });
            }
            const activeRearms = database.prepare(`
                SELECT rearms.rearm_authorization_id, rearms.intent_id,
                       rearms.user_rearm_evidence_hash, rearms.revision
                  FROM intent_rearm_authorizations AS rearms
                  JOIN order_intents AS intents
                    ON intents.intent_id=rearms.intent_id
                 WHERE intents.strategy_id=? AND rearms.state='active'
                 ORDER BY rearms.rearm_authorization_id
            `).all(strategy.strategyId);
            for (const rearm of activeRearms) {
                const update = database.prepare(`
                    UPDATE intent_rearm_authorizations
                       SET state='superseded', revision=revision+1
                     WHERE rearm_authorization_id=? AND state='active'
                       AND revision=?
                `).run(rearm.rearm_authorization_id, rearm.revision);
                if (Number(update.changes) !== 1) {
                    throw new Error('position drift re-arm transition lost its CAS');
                }
                insertTransitionJournalEvent(database, {
                    entityKind: 'order_intent',
                    entityId: rearm.intent_id,
                    revision: rearm.revision + 1,
                    reasonCode:
                        'PREPARED_INTENT_REARM_SUPERSEDED_BY_EXTERNAL_POSITION_DRIFT',
                    summaryCode: 'prepared_intent_rearm_superseded',
                    nowEpochMs: now,
                    payloadHash: rearm.user_rearm_evidence_hash,
                    eventSuffix: `position-drift-rearm-${rearm.rearm_authorization_id}`,
                });
            }
            database.prepare(`
                INSERT INTO resolution_cases(
                    resolution_case_id, strategy_id, reason_code, scope_hash,
                    evidence_snapshot_hash, state, created_at_epoch_ms,
                    updated_at_epoch_ms, terminal_at_epoch_ms, revision
                ) VALUES (?, ?, 'EXTERNAL_POSITION_DRIFT', ?, ?, 'open',
                          ?, ?, NULL, 0)
            `).run(
                resolutionCaseId,
                strategy.strategyId,
                scopeHash,
                evidenceHash,
                now,
                now,
            );
            database.prepare(`
                INSERT INTO safety_blockers(
                    blocker_id, resolution_case_id, scope_hash, reason_code,
                    state, created_at_epoch_ms, resolved_at_epoch_ms, revision
                ) VALUES (?, ?, ?, 'EXTERNAL_POSITION_DRIFT', 'open',
                          ?, NULL, 0)
            `).run(blockerId, resolutionCaseId, scopeHash, now);
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: strategy.strategyId,
                revision: strategy.revision + 1,
                reasonCode: 'EXTERNAL_POSITION_DRIFT',
                summaryCode: 'strategy_manual_intervention_required',
                nowEpochMs: now,
                payloadHash: strategy.definitionHash,
                eventSuffix: 'account-reconciliation-position-drift',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'resolution_case',
                entityId: resolutionCaseId,
                revision: 0,
                reasonCode: 'RESOLUTION_CASE_OPENED',
                summaryCode: 'external_position_drift_resolution_opened',
                nowEpochMs: now,
                payloadHash: evidenceHash,
                eventSuffix: 'account-reconciliation-position-drift',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'safety_blocker',
                entityId: blockerId,
                revision: 0,
                reasonCode: 'EXTERNAL_POSITION_DRIFT',
                summaryCode: 'external_position_drift_safety_blocker_opened',
                nowEpochMs: now,
                payloadHash: scopeHash,
                eventSuffix: 'account-reconciliation-position-drift',
            });
            protectionManualInterventionCount += 1;
            continue;
        }
        for (const plan of shrinkPlans) {
            if (plan.nextQuantity >= plan.claim.quantity_shares) continue;
            const released = plan.nextQuantity === 0;
            const evidenceHash = sha256Canonical(
                {
                    priorEvidenceHash: plan.claim.evidence_hash,
                    reconciliationEvidenceHash: projection.evidenceSha256,
                    priorQuantityShares: plan.claim.quantity_shares,
                    nextQuantityShares: plan.nextQuantity,
                    safeCapacityShares: plan.safeCapacity,
                    sourceRevision: projection.sourceRevision,
                },
                'position drift reservation shrink evidence',
            );
            const update = released
                ? database.prepare(`
                      UPDATE exit_claims
                         SET state='released', evidence_hash=?,
                             updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                             revision=revision+1
                       WHERE exit_claim_id=? AND state='monitoring_reserved'
                         AND revision=?
                  `).run(
                      evidenceHash,
                      now,
                      now,
                      plan.claim.exit_claim_id,
                      plan.claim.revision,
                  )
                : database.prepare(`
                      UPDATE exit_claims
                         SET quantity_shares=?, evidence_hash=?,
                             updated_at_epoch_ms=?, revision=revision+1
                       WHERE exit_claim_id=? AND state='monitoring_reserved'
                         AND revision=?
                  `).run(
                      plan.nextQuantity,
                      evidenceHash,
                      now,
                      plan.claim.exit_claim_id,
                      plan.claim.revision,
                  );
            if (Number(update.changes) !== 1) {
                throw new Error('position drift reservation shrink lost its CAS');
            }
            const generationUpdate = released
                ? database.prepare(`
                      UPDATE protection_remainder_generations
                         SET state='unknown', evidence_hash=?,
                             updated_at_epoch_ms=?, revision=revision+1
                       WHERE protection_group_id=? AND remainder_generation=?
                         AND state='monitoring' AND revision=?
                  `).run(
                      evidenceHash,
                      now,
                      plan.claim.protection_group_id,
                      plan.claim.protection_group_generation,
                      plan.claim.protection_generation_revision,
                  )
                : database.prepare(`
                      UPDATE protection_remainder_generations
                         SET quantity_shares=?, evidence_hash=?,
                             updated_at_epoch_ms=?, revision=revision+1
                       WHERE protection_group_id=? AND remainder_generation=?
                         AND state='monitoring' AND quantity_shares=?
                         AND revision=?
                  `).run(
                      plan.nextQuantity,
                      evidenceHash,
                      now,
                      plan.claim.protection_group_id,
                      plan.claim.protection_group_generation,
                      plan.claim.quantity_shares,
                      plan.claim.protection_generation_revision,
                  );
            const groupUpdate = database.prepare(`
                UPDATE protection_groups
                   SET state=?, updated_at_epoch_ms=?, revision=revision+1
                 WHERE protection_group_id=? AND state='monitoring'
                   AND current_generation=? AND revision=?
            `).run(
                released ? 'unknown' : 'monitoring',
                now,
                plan.claim.protection_group_id,
                plan.claim.protection_group_generation,
                plan.claim.protection_group_revision,
            );
            if (
                Number(generationUpdate.changes) !== 1 ||
                Number(groupUpdate.changes) !== 1
            ) {
                throw new Error(
                    'position drift protection group shrink lost its CAS',
                );
            }
            const shrunkShares = plan.claim.quantity_shares - plan.nextQuantity;
            protectionShrunkShares = addExposureInteger(
                protectionShrunkShares,
                shrunkShares,
                'position drift shrunk shares',
            );
            protectionReservationShrinkCount += 1;
            if (released) protectionReservationReleasedCount += 1;
            insertTransitionJournalEvent(database, {
                entityKind: 'exit_claim',
                entityId: plan.claim.exit_claim_id,
                revision: plan.claim.revision + 1,
                reasonCode:
                    'PROTECTION_RESERVATION_SHRUNK_EXTERNAL_POSITION_DRIFT',
                summaryCode: released
                    ? 'untriggered_protection_reservation_released'
                    : 'untriggered_protection_reservation_shrunk',
                nowEpochMs: now,
                payloadHash: evidenceHash,
                eventSuffix: 'account-reconciliation-position-drift',
            });
            insertTransitionJournalEvent(database, {
                entityKind: 'protection_group',
                entityId: plan.claim.protection_group_id,
                revision: plan.claim.protection_group_revision + 1,
                reasonCode:
                    'PROTECTION_RESERVATION_SHRUNK_EXTERNAL_POSITION_DRIFT',
                summaryCode: released
                    ? 'protection_group_unknown_after_reservation_release'
                    : 'protection_group_reservation_shrunk',
                nowEpochMs: now,
                payloadHash: evidenceHash,
                eventSuffix: 'account-reconciliation-position-drift',
            });
        }
    }
    return Object.freeze({
        protectionReservationShrinkCount,
        protectionReservationReleasedCount,
        protectionManualInterventionCount,
        protectionShrunkShares,
    });
}

function reconciliationExposureBaseline(projection) {
    let quantityShares = 0;
    let notionalMinorUnits = 0;
    let positionShares = 0;
    let orderCount = 0;
    let valuationComplete = true;
    for (const position of projection.positions) {
        quantityShares = addExposureInteger(
            quantityShares,
            position.quantityShares,
            'reconciliation baseline quantity shares',
        );
        positionShares = addExposureInteger(
            positionShares,
            position.quantityShares,
            'reconciliation baseline position shares',
        );
        if (position.quantityShares === 0) continue;
        if (position.lastPriceMinorUnits === null) {
            valuationComplete = false;
            continue;
        }
        const product =
            BigInt(position.quantityShares) *
            BigInt(position.lastPriceMinorUnits);
        if (product > BigInt(Number.MAX_SAFE_INTEGER)) {
            throw new Error('reconciliation baseline notional exceeds safe bounds');
        }
        notionalMinorUnits = addExposureInteger(
            notionalMinorUnits,
            Number(product),
            'reconciliation baseline notional',
        );
    }
    for (const order of projection.workingOrders) {
        if (order.side !== 'Buy' || order.remainingShares === 0) continue;
        quantityShares = addExposureInteger(
            quantityShares,
            order.remainingShares,
            'reconciliation working Buy quantity',
        );
        orderCount = addExposureInteger(
            orderCount,
            1,
            'reconciliation working Buy count',
        );
        // The complete working-order projection intentionally has no trusted
        // limit price.  Never invent a zero notional/cash baseline.
        valuationComplete = false;
    }
    return Object.freeze({
        quantityShares,
        notionalMinorUnits,
        cashMinorUnits: notionalMinorUnits,
        positionShares,
        orderCount,
        valuationComplete,
    });
}

function upsertAccountReconciliationHead(database, projection, now) {
    const baseline = reconciliationExposureBaseline(projection);
    const current = database
        .prepare(`
            SELECT * FROM account_reconciliation_heads
             WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
        `)
        .get(
            projection.account.brokerId,
            projection.account.accountId,
            projection.tradeDate,
        );
    if (current) {
        if (projection.asOfEpochMs < current.as_of_epoch_ms) {
            throw new Error('account reconciliation head cannot roll back');
        }
        if (
            projection.asOfEpochMs === current.as_of_epoch_ms &&
            (projection.sourceRevision !== current.source_revision ||
                projection.sourceSnapshotSha256 !== current.source_snapshot_hash ||
                projection.snapshotSha256 !== current.snapshot_hash ||
                projection.evidenceSha256 !== current.evidence_hash)
        ) {
            throw new Error('account reconciliation head has a same-time conflict');
        }
        if (
            projection.asOfEpochMs === current.as_of_epoch_ms &&
            projection.snapshotSha256 === current.snapshot_hash &&
            current.exposure_baseline_quantity_shares ===
                baseline.quantityShares &&
            current.exposure_baseline_notional_minor_units ===
                baseline.notionalMinorUnits &&
            current.exposure_baseline_cash_minor_units ===
                baseline.cashMinorUnits &&
            current.exposure_baseline_position_shares ===
                baseline.positionShares &&
            current.exposure_baseline_order_count === baseline.orderCount &&
            current.exposure_baseline_valuation_complete ===
                Number(baseline.valuationComplete)
        ) {
            return current.revision;
        }
        const nextRevision = current.revision + 1;
        const updateResult = database
            .prepare(`
                UPDATE account_reconciliation_heads
                   SET as_of_epoch_ms=?, source_revision=?,
                       source_snapshot_hash=?, snapshot_hash=?, evidence_hash=?,
                       event_stream_watermark_hash=?,
                       exposure_baseline_quantity_shares=?,
                       exposure_baseline_notional_minor_units=?,
                       exposure_baseline_cash_minor_units=?,
                       exposure_baseline_position_shares=?,
                       exposure_baseline_order_count=?,
                       exposure_baseline_valuation_complete=?,
                       updated_at_epoch_ms=?,
                       revision=?
                 WHERE account_broker_ref=? AND account_id_ref=?
                   AND trade_date=? AND revision=?
            `)
            .run(
                projection.asOfEpochMs,
                projection.sourceRevision,
                projection.sourceSnapshotSha256,
                projection.snapshotSha256,
                projection.evidenceSha256,
                projection.eventStreamWatermarkSha256,
                baseline.quantityShares,
                baseline.notionalMinorUnits,
                baseline.cashMinorUnits,
                baseline.positionShares,
                baseline.orderCount,
                Number(baseline.valuationComplete),
                now,
                nextRevision,
                projection.account.brokerId,
                projection.account.accountId,
                projection.tradeDate,
                current.revision,
            );
        if (Number(updateResult.changes) !== 1) {
            throw new Error('account reconciliation head update lost its CAS');
        }
        return nextRevision;
    }
    database
        .prepare(`
            INSERT INTO account_reconciliation_heads(
                account_broker_ref, account_id_ref, trade_date,
                as_of_epoch_ms, source_revision, source_snapshot_hash,
                snapshot_hash, evidence_hash, event_stream_watermark_hash,
                exposure_baseline_quantity_shares,
                exposure_baseline_notional_minor_units,
                exposure_baseline_cash_minor_units,
                exposure_baseline_position_shares,
                exposure_baseline_order_count,
                exposure_baseline_valuation_complete,
                updated_at_epoch_ms, revision
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
        `)
        .run(
            projection.account.brokerId,
            projection.account.accountId,
            projection.tradeDate,
            projection.asOfEpochMs,
            projection.sourceRevision,
            projection.sourceSnapshotSha256,
            projection.snapshotSha256,
            projection.evidenceSha256,
            projection.eventStreamWatermarkSha256,
            baseline.quantityShares,
            baseline.notionalMinorUnits,
            baseline.cashMinorUnits,
            baseline.positionShares,
            baseline.orderCount,
            Number(baseline.valuationComplete),
            now,
        );
    return 0;
}

function replaceAccountReconciliationPositions(
    database,
    projection,
    accountHeadRevision,
    now,
) {
    const validUntilEpochMs = projection.asOfEpochMs + 5_000;
    if (!Number.isSafeInteger(validUntilEpochMs)) {
        throw new Error('account reconciliation position expiry exceeds safe range');
    }
    const positivePositions = projection.positions.filter(
        (position) => position.quantityShares > 0,
    );
    const expectedContractKeys = new Set(
        positivePositions.map((position) => position.contractKey),
    );
    const existing = database.prepare(`
        SELECT * FROM account_reconciliation_positions
         WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
         ORDER BY contract_key
    `).all(
        projection.account.brokerId,
        projection.account.accountId,
        projection.tradeDate,
    );
    const contractCode = (contractKey, label) => {
        const match = contractKey.match(
            /^(TSE|OTC):([A-Za-z0-9][A-Za-z0-9._-]{0,31}):STK:Common$/,
        );
        if (!match) {
            throw new Error(`${label} is not a canonical stock contract`);
        }
        return match[2];
    };
    const positiveByCode = new Map();
    for (const position of positivePositions) {
        const code = contractCode(
            position.contractKey,
            'reconciliation position contract',
        );
        const previous = positiveByCode.get(code);
        if (previous && previous.contractKey !== position.contractKey) {
            throw new Error(
                'reconciliation position code maps to conflicting exchanges',
            );
        }
        positiveByCode.set(code, position);
    }
    for (const row of existing) {
        const code = contractCode(
            row.contract_key,
            'durable reconciliation position contract',
        );
        const next = positiveByCode.get(code);
        if (next && next.contractKey !== row.contract_key) {
            throw new Error(
                'reconciliation position exchange drift requires manual intervention',
            );
        }
        if (
            next &&
            next.quantityShares > 0 &&
            row.quantity_shares > 0 &&
            next.positionLineageId !== row.position_lineage_id
        ) {
            throw new Error(
                'reconciliation position canonical contract revision drift requires manual intervention',
            );
        }
    }
    for (const row of existing) {
        if (expectedContractKeys.has(row.contract_key)) continue;
        const removed = database.prepare(`
            DELETE FROM account_reconciliation_positions
             WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
               AND contract_key=? AND revision=?
        `).run(
            projection.account.brokerId,
            projection.account.accountId,
            projection.tradeDate,
            row.contract_key,
            row.revision,
        );
        if (Number(removed.changes) !== 1) {
            throw new Error('account reconciliation position removal lost its CAS');
        }
    }
    const existingByContract = new Map(
        existing.map((row) => [row.contract_key, row]),
    );
    for (const position of positivePositions) {
        const averageCostAvailable = position.averagePriceMinorUnits > 0;
        const averagePriceMinorUnits = averageCostAvailable
            ? position.averagePriceMinorUnits
            : null;
        const averageCostReason = averageCostAvailable
            ? null
            : 'broker_average_cost_missing';
        const current = existingByContract.get(position.contractKey);
        if (!current) {
            database.prepare(`
                INSERT INTO account_reconciliation_positions(
                    account_broker_ref, account_id_ref, trade_date,
                    contract_key, account_head_revision, source_revision,
                    source_snapshot_hash, evidence_hash, position_lineage_id,
                    quantity_shares, available_shares, average_cost_state,
                    average_price_minor_units, average_cost_reason,
                    as_of_epoch_ms, valid_until_epoch_ms,
                    updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            `).run(
                projection.account.brokerId,
                projection.account.accountId,
                projection.tradeDate,
                position.contractKey,
                accountHeadRevision,
                projection.sourceRevision,
                projection.sourceSnapshotSha256,
                projection.evidenceSha256,
                position.positionLineageId,
                position.quantityShares,
                position.availableShares,
                averageCostAvailable ? 'available' : 'unavailable',
                averagePriceMinorUnits,
                averageCostReason,
                projection.asOfEpochMs,
                validUntilEpochMs,
                now,
            );
            continue;
        }
        const unchanged =
            current.account_head_revision === accountHeadRevision &&
            current.source_revision === projection.sourceRevision &&
            current.source_snapshot_hash === projection.sourceSnapshotSha256 &&
            current.evidence_hash === projection.evidenceSha256 &&
            current.position_lineage_id === position.positionLineageId &&
            current.quantity_shares === position.quantityShares &&
            current.available_shares === position.availableShares &&
            current.average_cost_state ===
                (averageCostAvailable ? 'available' : 'unavailable') &&
            current.average_price_minor_units === averagePriceMinorUnits &&
            current.average_cost_reason === averageCostReason &&
            current.as_of_epoch_ms === projection.asOfEpochMs &&
            current.valid_until_epoch_ms === validUntilEpochMs;
        if (unchanged) continue;
        const updated = database.prepare(`
            UPDATE account_reconciliation_positions
               SET account_head_revision=?, source_revision=?,
                   source_snapshot_hash=?, evidence_hash=?,
                   position_lineage_id=?, quantity_shares=?,
                   available_shares=?, average_cost_state=?,
                   average_price_minor_units=?, average_cost_reason=?,
                   as_of_epoch_ms=?, valid_until_epoch_ms=?,
                   updated_at_epoch_ms=?, revision=revision+1
             WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
               AND contract_key=? AND revision=?
        `).run(
            accountHeadRevision,
            projection.sourceRevision,
            projection.sourceSnapshotSha256,
            projection.evidenceSha256,
            position.positionLineageId,
            position.quantityShares,
            position.availableShares,
            averageCostAvailable ? 'available' : 'unavailable',
            averagePriceMinorUnits,
            averageCostReason,
            projection.asOfEpochMs,
            validUntilEpochMs,
            now,
            projection.account.brokerId,
            projection.account.accountId,
            projection.tradeDate,
            position.contractKey,
            current.revision,
        );
        if (Number(updated.changes) !== 1) {
            throw new Error('account reconciliation position update lost its CAS');
        }
    }
}

function canonicalPnlDealLedgerHash(deals) {
    return sha256Canonical(
        deals.map((deal) => ({
            dealId: deal.dealId,
            feeMinorUnits: deal.feeMinorUnits,
            realizedMinorUnits: deal.realizedMinorUnits,
            transactionTaxMinorUnits: deal.transactionTaxMinorUnits,
        })),
        'canonical PnL deal ledger',
    );
}

function replaceCanonicalPnlDeals(database, projection, now) {
    const existing = database.prepare(`
        SELECT * FROM canonical_pnl_deals
         WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
         ORDER BY deal_id
    `).all(
        projection.account.brokerId,
        projection.account.accountId,
        projection.tradeDate,
    );
    const nextById = new Map(projection.deals.map((deal) => [deal.dealId, deal]));
    for (const row of existing) {
        if (nextById.has(row.deal_id)) continue;
        const removed = database.prepare(`
            DELETE FROM canonical_pnl_deals
             WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
               AND deal_id=? AND revision=?
        `).run(
            projection.account.brokerId,
            projection.account.accountId,
            projection.tradeDate,
            row.deal_id,
            row.revision,
        );
        if (Number(removed.changes) !== 1) {
            throw new Error('canonical PnL deal removal lost its CAS');
        }
    }
    const currentById = new Map(existing.map((row) => [row.deal_id, row]));
    for (const deal of projection.deals) {
        const current = currentById.get(deal.dealId);
        if (!current) {
            database.prepare(`
                INSERT INTO canonical_pnl_deals(
                    account_broker_ref, account_id_ref, trade_date, deal_id,
                    realized_minor_units, fee_minor_units,
                    transaction_tax_minor_units, source_snapshot_hash,
                    updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            `).run(
                projection.account.brokerId,
                projection.account.accountId,
                projection.tradeDate,
                deal.dealId,
                deal.realizedMinorUnits,
                deal.feeMinorUnits,
                deal.transactionTaxMinorUnits,
                projection.sourceSnapshotSha256,
                now,
            );
            continue;
        }
        if (
            current.realized_minor_units === deal.realizedMinorUnits &&
            current.fee_minor_units === deal.feeMinorUnits &&
            current.transaction_tax_minor_units ===
                deal.transactionTaxMinorUnits &&
            current.source_snapshot_hash === projection.sourceSnapshotSha256
        ) {
            continue;
        }
        const updated = database.prepare(`
            UPDATE canonical_pnl_deals
               SET realized_minor_units=?, fee_minor_units=?,
                   transaction_tax_minor_units=?, source_snapshot_hash=?,
                   updated_at_epoch_ms=?, revision=revision+1
             WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
               AND deal_id=? AND revision=?
        `).run(
            deal.realizedMinorUnits,
            deal.feeMinorUnits,
            deal.transactionTaxMinorUnits,
            projection.sourceSnapshotSha256,
            now,
            projection.account.brokerId,
            projection.account.accountId,
            projection.tradeDate,
            deal.dealId,
            current.revision,
        );
        if (Number(updated.changes) !== 1) {
            throw new Error('canonical PnL deal update lost its CAS');
        }
    }
    return canonicalPnlDealLedgerHash(projection.deals);
}

function upsertCanonicalPnlAccountHead(
    database,
    { projection, identityAdmission, runtimeEpochId, apiGeneration, dealLedgerHash, now },
) {
    const totals = recalculateCanonicalPnlTotals({
        deals: projection.deals,
        positions: projection.positions,
    });
    if (stableCanonicalJson(totals) !== stableCanonicalJson(projection.fullDayTotals)) {
        throw new Error('canonical PnL totals differ from the complete source ledger');
    }
    const values = [
        identityAdmission.identityGroupId,
        SMART_ORDER_CANONICAL_PNL_POLICY_REVISION,
        SMART_ORDER_CANONICAL_PNL_POLICY_DEFINITION_SHA256,
        runtimeEpochId,
        apiGeneration,
        projection.eventStreamWatermarkSha256,
        dealLedgerHash,
        projection.sourceRevision,
        projection.sourceSnapshotSha256,
        projection.evidenceSha256,
        projection.eventStreamWatermarkSha256,
        totals.realizedMinorUnits,
        totals.unrealizedMinorUnits,
        totals.feeMinorUnits,
        totals.transactionTaxMinorUnits,
        totals.netMinorUnits,
        projection.asOfEpochMs,
        projection.asOfEpochMs + SMART_ORDER_CANONICAL_PNL_FRESHNESS_TTL_MS,
        now,
    ];
    const current = database.prepare(`
        SELECT * FROM canonical_pnl_account_heads
         WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
    `).get(
        projection.account.brokerId,
        projection.account.accountId,
        projection.tradeDate,
    );
    if (current && projection.asOfEpochMs < current.as_of_epoch_ms) {
        throw new Error('canonical PnL account head cannot roll back');
    }
    if (current) {
        const updated = database.prepare(`
            UPDATE canonical_pnl_account_heads
               SET identity_group_id=?, policy_revision=?,
                   policy_definition_hash=?, runtime_epoch_id=?,
                   api_generation=?, account_set_revision=?,
                   deal_ledger_hash=?, source_revision=?,
                   source_snapshot_hash=?, evidence_hash=?,
                   event_stream_watermark_hash=?, realized_minor_units=?,
                   unrealized_minor_units=?, fee_minor_units=?,
                   transaction_tax_minor_units=?, net_minor_units=?,
                   complete_components=1, includes_pre_runtime_activity=1,
                   includes_external_client_activity=1, as_of_epoch_ms=?,
                   valid_until_epoch_ms=?, updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
               AND revision=?
        `).run(
            ...values,
            projection.account.brokerId,
            projection.account.accountId,
            projection.tradeDate,
            current.revision,
        );
        if (Number(updated.changes) !== 1) {
            throw new Error('canonical PnL account head update lost its CAS');
        }
        return current.revision + 1;
    }
    database.prepare(`
        INSERT INTO canonical_pnl_account_heads(
            account_broker_ref, account_id_ref, identity_group_id, trade_date,
            policy_revision, policy_definition_hash, runtime_epoch_id,
            api_generation, account_set_revision, deal_ledger_hash,
            source_revision, source_snapshot_hash, evidence_hash,
            event_stream_watermark_hash, realized_minor_units,
            unrealized_minor_units, fee_minor_units,
            transaction_tax_minor_units, net_minor_units,
            complete_components, includes_pre_runtime_activity,
            includes_external_client_activity, as_of_epoch_ms,
            valid_until_epoch_ms, updated_at_epoch_ms, revision
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                  1, 1, 1, ?, ?, ?, 0)
    `).run(
        projection.account.brokerId,
        projection.account.accountId,
        identityAdmission.identityGroupId,
        projection.tradeDate,
        ...values.slice(1),
    );
    return 0;
}

function addCanonicalPnlInteger(left, right, label) {
    const value = left + right;
    if (!Number.isSafeInteger(value)) {
        throw new Error(`${label} exceeds the safe integer range`);
    }
    return value;
}

function rebuildCanonicalPnlIdentityHead(
    database,
    {
        identityGroupId,
        tradeDate,
        eventStreamWatermarkSha256,
        expectedFixedAccountCount,
        runtimeEpochId,
        apiGeneration,
        now,
    },
) {
    database.prepare(
        'DELETE FROM canonical_pnl_identity_heads WHERE identity_group_id=?',
    ).run(identityGroupId);
    const heads = database.prepare(`
        SELECT * FROM canonical_pnl_account_heads
         WHERE identity_group_id=? AND trade_date=?
           AND event_stream_watermark_hash=?
           AND policy_revision=? AND policy_definition_hash=?
           AND runtime_epoch_id=? AND api_generation=?
         ORDER BY account_broker_ref, account_id_ref
    `).all(
        identityGroupId,
        tradeDate,
        eventStreamWatermarkSha256,
        SMART_ORDER_CANONICAL_PNL_POLICY_REVISION,
        SMART_ORDER_CANONICAL_PNL_POLICY_DEFINITION_SHA256,
        runtimeEpochId,
        apiGeneration,
    );
    if (heads.length !== expectedFixedAccountCount) return null;
    const identityBindings = database.prepare(`
        SELECT value FROM repository_meta
         WHERE key LIKE ? ORDER BY key
    `).all(`${IDENTITY_ACCOUNT_BINDING_META_PREFIX}%`)
        .map((row) => JSON.parse(row.value))
        .filter((binding) => binding.identityGroupId === identityGroupId);
    if (identityBindings.length !== expectedFixedAccountCount) return null;
    const accountSet = heads.map((head) => ({
        accountScopeSha256: `sha256:${createHash('sha256')
            .update(`${head.account_broker_ref}\u001f${head.account_id_ref}`)
            .digest('hex')}`,
        dealLedgerHash: head.deal_ledger_hash,
        evidenceHash: head.evidence_hash,
        snapshotHash: head.source_snapshot_hash,
    }));
    if (
        !identityBindings.every((binding) =>
            accountSet.some(
                (entry) => entry.accountScopeSha256 === binding.accountScopeSha256,
            ),
        )
    ) {
        return null;
    }
    const totals = heads.reduce(
        (sum, head) => ({
            realizedMinorUnits: addCanonicalPnlInteger(
                sum.realizedMinorUnits,
                head.realized_minor_units,
                'identity realized PnL',
            ),
            unrealizedMinorUnits: addCanonicalPnlInteger(
                sum.unrealizedMinorUnits,
                head.unrealized_minor_units,
                'identity unrealized PnL',
            ),
            feeMinorUnits: addCanonicalPnlInteger(
                sum.feeMinorUnits,
                head.fee_minor_units,
                'identity fee PnL',
            ),
            transactionTaxMinorUnits: addCanonicalPnlInteger(
                sum.transactionTaxMinorUnits,
                head.transaction_tax_minor_units,
                'identity transaction-tax PnL',
            ),
            netMinorUnits: addCanonicalPnlInteger(
                sum.netMinorUnits,
                head.net_minor_units,
                'identity net PnL',
            ),
        }),
        {
            realizedMinorUnits: 0,
            unrealizedMinorUnits: 0,
            feeMinorUnits: 0,
            transactionTaxMinorUnits: 0,
            netMinorUnits: 0,
        },
    );
    const accountSetHash = sha256Canonical(accountSet, 'canonical PnL account set');
    const dealLedgerHash = sha256Canonical(
        heads.map((head) => head.deal_ledger_hash),
        'canonical PnL identity deal ledger',
    );
    const sourceEvidenceHash = sha256Canonical(
        heads.map((head) => head.evidence_hash),
        'canonical PnL identity source evidence',
    );
    const asOfEpochMs = Math.min(...heads.map((head) => head.as_of_epoch_ms));
    database.prepare(`
        INSERT INTO canonical_pnl_identity_heads(
            identity_group_id, trade_date, policy_revision,
            policy_definition_hash, runtime_epoch_id, api_generation,
            account_set_revision, account_set_hash, expected_account_count,
            observed_account_count, deal_ledger_hash, source_evidence_hash,
            event_stream_watermark_hash, realized_minor_units,
            unrealized_minor_units, fee_minor_units,
            transaction_tax_minor_units, net_minor_units,
            all_accounts_reconciled, identity_mapping_ready, as_of_epoch_ms,
            valid_until_epoch_ms, updated_at_epoch_ms, revision
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                  1, 1, ?, ?, ?, 0)
    `).run(
        identityGroupId,
        tradeDate,
        SMART_ORDER_CANONICAL_PNL_POLICY_REVISION,
        SMART_ORDER_CANONICAL_PNL_POLICY_DEFINITION_SHA256,
        runtimeEpochId,
        apiGeneration,
        eventStreamWatermarkSha256,
        accountSetHash,
        expectedFixedAccountCount,
        heads.length,
        dealLedgerHash,
        sourceEvidenceHash,
        eventStreamWatermarkSha256,
        totals.realizedMinorUnits,
        totals.unrealizedMinorUnits,
        totals.feeMinorUnits,
        totals.transactionTaxMinorUnits,
        totals.netMinorUnits,
        asOfEpochMs,
        asOfEpochMs + SMART_ORDER_CANONICAL_PNL_FRESHNESS_TTL_MS,
        now,
    );
    return Object.freeze({
        accountSetHash,
        accountSetRevision: eventStreamWatermarkSha256,
        dealLedgerHash,
        sourceEvidenceHash,
        totals,
        asOfEpochMs,
        validUntilEpochMs:
            asOfEpochMs + SMART_ORDER_CANONICAL_PNL_FRESHNESS_TTL_MS,
    });
}

function currentCanonicalPnlDecision(
    database,
    {
        accountBrokerRef,
        accountIdRef,
        identityGroupId,
        tradeDate,
        runtimeEpochId,
        apiGeneration,
    },
) {
    const accountHead = database.prepare(`
        SELECT * FROM canonical_pnl_account_heads
         WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
    `).get(accountBrokerRef, accountIdRef, tradeDate);
    const identityHead = database.prepare(`
        SELECT * FROM canonical_pnl_identity_heads
         WHERE identity_group_id=? AND trade_date=?
    `).get(identityGroupId, tradeDate);
    const accountRiskHead = database.prepare(`
        SELECT policy_revision, policy_hash, daily_loss_limit_minor_units
          FROM exposure_account_arbiter_heads
         WHERE account_broker_ref=? AND account_id_ref=?
    `).get(accountBrokerRef, accountIdRef);
    const identityRiskHead = database.prepare(`
        SELECT policy_revision, policy_hash, daily_loss_limit_minor_units
          FROM exposure_identity_arbiter_heads
         WHERE identity_group_id=?
    `).get(identityGroupId);
    const now = exposureClockNowEpochMs();
    if (
        !accountHead ||
        !identityHead ||
        !accountRiskHead ||
        !identityRiskHead ||
        accountHead.identity_group_id !== identityGroupId ||
        accountHead.policy_revision !== SMART_ORDER_CANONICAL_PNL_POLICY_REVISION ||
        identityHead.policy_revision !== SMART_ORDER_CANONICAL_PNL_POLICY_REVISION ||
        accountHead.policy_definition_hash !==
            SMART_ORDER_CANONICAL_PNL_POLICY_DEFINITION_SHA256 ||
        identityHead.policy_definition_hash !==
            SMART_ORDER_CANONICAL_PNL_POLICY_DEFINITION_SHA256 ||
        accountHead.runtime_epoch_id !== runtimeEpochId ||
        identityHead.runtime_epoch_id !== runtimeEpochId ||
        accountHead.api_generation !== apiGeneration ||
        identityHead.api_generation !== apiGeneration ||
        accountHead.account_set_revision !== identityHead.account_set_revision ||
        accountHead.event_stream_watermark_hash !==
            identityHead.event_stream_watermark_hash ||
        accountHead.as_of_epoch_ms > now ||
        identityHead.as_of_epoch_ms > now ||
        accountHead.valid_until_epoch_ms <= now ||
        identityHead.valid_until_epoch_ms <= now ||
        accountHead.complete_components !== 1 ||
        accountHead.includes_pre_runtime_activity !== 1 ||
        accountHead.includes_external_client_activity !== 1 ||
        identityHead.all_accounts_reconciled !== 1 ||
        identityHead.identity_mapping_ready !== 1
    ) {
        throw new Error('current account and identity canonical PnL heads are required');
    }
    if (
        accountRiskHead.policy_revision !== identityRiskHead.policy_revision ||
        accountRiskHead.policy_hash !== identityRiskHead.policy_hash ||
        !Number.isSafeInteger(
            accountRiskHead.daily_loss_limit_minor_units,
        ) ||
        !Number.isSafeInteger(
            identityRiskHead.daily_loss_limit_minor_units,
        ) ||
        accountRiskHead.daily_loss_limit_minor_units < 0 ||
        identityRiskHead.daily_loss_limit_minor_units < 0
    ) {
        throw new Error(
            'canonical PnL daily-loss limits are not bound to one current risk policy',
        );
    }
    if (
        accountHead.net_minor_units <
            -accountRiskHead.daily_loss_limit_minor_units ||
        identityHead.net_minor_units <
            -identityRiskHead.daily_loss_limit_minor_units
    ) {
        throw new Error(
            'canonical account or identity daily-loss limit is exceeded',
        );
    }
    return sha256Canonical(
        {
            account: {
                dealLedgerHash: accountHead.deal_ledger_hash,
                netMinorUnits: accountHead.net_minor_units,
                revision: accountHead.revision,
            },
            identity: {
                accountSetHash: identityHead.account_set_hash,
                dealLedgerHash: identityHead.deal_ledger_hash,
                netMinorUnits: identityHead.net_minor_units,
                revision: identityHead.revision,
            },
            policyDefinitionSha256:
                SMART_ORDER_CANONICAL_PNL_POLICY_DEFINITION_SHA256,
            policyRevision: SMART_ORDER_CANONICAL_PNL_POLICY_REVISION,
            riskPolicy: {
                accountDailyLossLimitMinorUnits:
                    accountRiskHead.daily_loss_limit_minor_units,
                identityDailyLossLimitMinorUnits:
                    identityRiskHead.daily_loss_limit_minor_units,
                policyHash: accountRiskHead.policy_hash,
                policyRevision: accountRiskHead.policy_revision,
            },
        },
        'current canonical PnL decision',
    );
}

function storedRuntimeRiskPolicy(database) {
    const row = database
        .prepare("SELECT * FROM runtime_risk_policies WHERE singleton_id='current'")
        .get();
    if (!row) return null;
    let parsed;
    try {
        parsed = JSON.parse(row.policy_json);
    } catch {
        throw new Error('runtime risk policy JSON is invalid');
    }
    const verified = revalidateRuntimeRiskPolicy(parsed);
    if (
        verified.policyJson !== row.policy_json ||
        verified.policyHash !== row.policy_hash ||
        verified.executionPolicyHash !== row.execution_policy_hash ||
        verified.policyRevision !== row.policy_revision ||
        verified.policy.revision !== row.revision
    ) {
        throw new Error('runtime risk policy durable binding is invalid');
    }
    return Object.freeze({ row, verified });
}

function runtimeRiskPolicyView(database) {
    const stored = storedRuntimeRiskPolicy(database);
    if (!stored) {
        return Object.freeze({
            schemaVersion: 'smart-order-runtime-risk-policy-view/2026-08-14.1',
            state: 'missing',
            revision: null,
            policyHash: null,
            executionPolicyHash: null,
            policy: null,
            exposureHeadsCurrent: false,
            brokerWriteAuthority: false,
            accountIdentifiersExposed: false,
            identityIdentifiersExposed: false,
        });
    }
    const headProjection = currentRuntimeRiskHeadProjection(database, stored);
    return Object.freeze({
        schemaVersion: 'smart-order-runtime-risk-policy-view/2026-08-14.1',
        state:
            headProjection.current
                ? 'current'
                : 'reconciliation_required',
        revision: stored.verified.policy.revision,
        policyHash: stored.verified.policyHash,
        executionPolicyHash: stored.verified.executionPolicyHash,
        policy: stored.verified.policy,
        exposureHeadsCurrent: headProjection.current,
        publishedAtEpochMs: stored.row.published_at_epoch_ms,
        brokerWriteAuthority: false,
        accountIdentifiersExposed: false,
        identityIdentifiersExposed: false,
    });
}

function currentRuntimeRiskHeadProjection(database, stored) {
    const runtimeEpochId = repositoryMetaValue(
        database,
        'current_runtime_epoch_id',
    );
    const apiGeneration = repositoryMetaValue(
        database,
        'current_api_generation',
    );
    if (!runtimeEpochId || !apiGeneration) {
        return Object.freeze({ current: false, expectedAccountCount: 0 });
    }
    const runtime = database.prepare(`
        SELECT state FROM runtime_epochs
         WHERE runtime_epoch_id=? AND api_generation=?
    `).get(runtimeEpochId, apiGeneration);
    if (!runtime || !['reconciling', 'ready'].includes(runtime.state)) {
        return Object.freeze({ current: false, expectedAccountCount: 0 });
    }
    const identityHeads = database.prepare(`
        SELECT identity_group_id, policy_revision, policy_hash,
               source_revision, source_sequence, valid_until_epoch_ms
          FROM exposure_identity_arbiter_heads
         ORDER BY identity_group_id
    `).all();
    if (identityHeads.length !== 1) {
        return Object.freeze({ current: false, expectedAccountCount: 0 });
    }
    const identityHead = identityHeads[0];
    const pnlIdentity = database.prepare(`
        SELECT expected_account_count, revision
          FROM canonical_pnl_identity_heads
         WHERE identity_group_id=?
           AND event_stream_watermark_hash=?
           AND runtime_epoch_id=?
           AND api_generation=?
         ORDER BY updated_at_epoch_ms DESC
         LIMIT 1
    `).get(
        identityHead.identity_group_id,
        identityHead.source_revision,
        runtimeEpochId,
        apiGeneration,
    );
    const expectedAccountCount = pnlIdentity?.expected_account_count ?? 0;
    const matchingAccountHeads = database.prepare(`
        SELECT COUNT(*) AS count
          FROM exposure_account_arbiter_heads
         WHERE identity_group_id=?
           AND policy_revision=?
           AND policy_hash=?
    `).get(
        identityHead.identity_group_id,
        stored.verified.policyRevision,
        stored.verified.executionPolicyHash,
    )?.count;
    const totalAccountHeads = database
        .prepare('SELECT COUNT(*) AS count FROM exposure_account_arbiter_heads')
        .get()?.count;
    return Object.freeze({
        current:
            identityHead.policy_revision === stored.verified.policyRevision &&
            identityHead.policy_hash === stored.verified.executionPolicyHash &&
            pnlIdentity !== undefined &&
            identityHead.source_sequence === pnlIdentity.revision + 1 &&
            Number.isSafeInteger(expectedAccountCount) &&
            expectedAccountCount > 0 &&
            matchingAccountHeads === expectedAccountCount &&
            totalAccountHeads === expectedAccountCount,
        expectedAccountCount,
    });
}

function assertRuntimeRiskReadinessCurrent(
    database,
    { apiGeneration, now, reconciliationEvidenceHash, runtimeEpochId },
) {
    const runtime = database.prepare(`
        SELECT reconciliation_evidence_hash
          FROM runtime_epochs
         WHERE runtime_epoch_id=? AND api_generation=?
    `).get(runtimeEpochId, apiGeneration);
    if (
        !runtime ||
        runtime.reconciliation_evidence_hash !== reconciliationEvidenceHash
    ) {
        throw new Error(
            'runtime ready requires the current durable reconciliation evidence',
        );
    }
    const stored = storedRuntimeRiskPolicy(database);
    if (!stored || !currentRuntimeRiskHeadProjection(database, stored).current) {
        throw new Error(
            'runtime ready requires current account and identity risk heads',
        );
    }
    const currentHeads = database.prepare(`
        SELECT
            (SELECT COUNT(*) FROM exposure_account_arbiter_heads
              WHERE valid_until_epoch_ms<=?) AS stale_accounts,
            (SELECT COUNT(*) FROM exposure_identity_arbiter_heads
              WHERE valid_until_epoch_ms<=?) AS stale_identities,
            (SELECT COUNT(*) FROM canonical_pnl_identity_heads
              WHERE runtime_epoch_id=? AND api_generation=?
                AND valid_until_epoch_ms>?) AS current_pnl_identities
    `).get(now, now, runtimeEpochId, apiGeneration, now);
    if (
        currentHeads.stale_accounts !== 0 ||
        currentHeads.stale_identities !== 0 ||
        currentHeads.current_pnl_identities !== 1
    ) {
        throw new Error(
            'runtime ready requires fresh current-generation canonical risk and PnL heads',
        );
    }
}

function publishRuntimeRiskPolicyInTransaction(database, input) {
    if (
        !exactKeys(input, [
            'apiGeneration',
            'expectedRevision',
            'nowEpochMs',
            'policy',
            'runtimeEpochId',
            'senderFence',
        ])
    ) {
        throw new TypeError('runtime risk policy mutation schema is invalid');
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const now = safeInteger(input.nowEpochMs, 'riskPolicy.nowEpochMs');
    const runtime = database.prepare(`
        SELECT state, revision FROM runtime_epochs
         WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
    `).get(runtimeEpochId, senderFence, apiGeneration);
    if (!runtime || !['ready', 'reconciling'].includes(runtime.state)) {
        throw new Error('runtime risk policy requires the current Runtime');
    }
    const current = storedRuntimeRiskPolicy(database);
    const expectedRevision = input.expectedRevision;
    if (
        (current === null && expectedRevision !== null) ||
        (current !== null &&
            (!Number.isSafeInteger(expectedRevision) ||
                expectedRevision !== current.verified.policy.revision))
    ) {
        const error = new Error('runtime risk policy revision is stale');
        error.name = 'RiskPolicyRevisionError';
        throw error;
    }
    const activeReservations = database.prepare(`
        SELECT COUNT(*) AS count FROM entry_exposure_reservations
         WHERE state IN ('reserved','partially_consumed','unknown')
    `).get()?.count;
    if (activeReservations !== 0) {
        throw new Error(
            'runtime risk policy cannot change while exposure reservations are active',
        );
    }
    const nextRevision = current ? current.verified.policy.revision + 1 : 0;
    const materialized = materializeRuntimeRiskPolicy(
        input.policy,
        nextRevision,
    );
    if (current) {
        const updated = database.prepare(`
            UPDATE runtime_risk_policies
               SET policy_revision=?, policy_hash=?, execution_policy_hash=?,
                   policy_json=?, runtime_epoch_id=?, api_generation=?,
                   published_at_epoch_ms=?, revision=?
             WHERE singleton_id='current' AND revision=?
        `).run(
            materialized.policyRevision,
            materialized.policyHash,
            materialized.executionPolicyHash,
            materialized.policyJson,
            runtimeEpochId,
            apiGeneration,
            now,
            nextRevision,
            current.verified.policy.revision,
        );
        if (Number(updated.changes) !== 1) {
            throw new Error('runtime risk policy update lost its CAS');
        }
    } else {
        database.prepare(`
            INSERT INTO runtime_risk_policies(
                singleton_id, policy_revision, policy_hash,
                execution_policy_hash, policy_json, runtime_epoch_id,
                api_generation, published_at_epoch_ms, revision
            ) VALUES ('current', ?, ?, ?, ?, ?, ?, ?, 0)
        `).run(
            materialized.policyRevision,
            materialized.policyHash,
            materialized.executionPolicyHash,
            materialized.policyJson,
            runtimeEpochId,
            apiGeneration,
            now,
        );
    }
    database.prepare('DELETE FROM exposure_account_arbiter_heads').run();
    database.prepare('DELETE FROM exposure_identity_arbiter_heads').run();
    const runtimeUpdate = database.prepare(`
        UPDATE runtime_epochs
           SET state='reconciling', reconciliation_evidence_hash=NULL,
               revision=revision+1
         WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
           AND state=? AND revision=?
    `).run(
        runtimeEpochId,
        senderFence,
        apiGeneration,
        runtime.state,
        runtime.revision,
    );
    if (Number(runtimeUpdate.changes) !== 1) {
        throw new Error('runtime risk policy invalidation lost its Runtime CAS');
    }
    insertTransitionJournalEvent(database, {
        entityKind: 'risk_policy',
        entityId: materialized.policyRevision,
        revision: nextRevision,
        reasonCode: 'RUNTIME_RISK_POLICY_PUBLISHED',
        summaryCode: 'risk_policy_reconciliation_required',
        nowEpochMs: now,
        payloadHash: materialized.policyHash,
        eventSuffix: `risk-policy-${nextRevision}`,
    });
    return Object.freeze({
        ...runtimeRiskPolicyView(database),
        runtimeState: 'reconciling',
        runtimeRevision: runtime.revision + 1,
        dispatchAllowed: false,
        replayed: false,
    });
}

function canonicalPnlDecisionForExposure(database, scope) {
    if (!canonicalPnlRequired) {
        return sha256Canonical(
            { fixtureOnlyBypass: true },
            'test-only canonical PnL bypass',
        );
    }
    try {
        return currentCanonicalPnlDecision(database, scope);
    } catch (error) {
        throw error;
    }
}

function rebuildRuntimeRiskExposureHeads(
    database,
    {
        identityGroupId,
        tradeDate,
        eventStreamWatermarkSha256,
        expectedFixedAccountCount,
        now,
    },
) {
    const stored = storedRuntimeRiskPolicy(database);
    if (!stored) return false;
    const policy = stored.verified.policy;
    const dimensionsJson = JSON.stringify(
        [...policy.reservedDimensions].sort(),
    );
    const rows = database.prepare(`
        SELECT reconciliation.*, pnl.identity_group_id,
               pnl.as_of_epoch_ms AS pnl_as_of_epoch_ms,
               pnl.valid_until_epoch_ms AS pnl_valid_until_epoch_ms
          FROM account_reconciliation_heads AS reconciliation
          JOIN canonical_pnl_account_heads AS pnl
            ON pnl.account_broker_ref=reconciliation.account_broker_ref
           AND pnl.account_id_ref=reconciliation.account_id_ref
           AND pnl.trade_date=reconciliation.trade_date
         WHERE reconciliation.trade_date=?
           AND reconciliation.event_stream_watermark_hash=?
           AND pnl.event_stream_watermark_hash=?
           AND pnl.identity_group_id=?
         ORDER BY reconciliation.account_broker_ref,
                  reconciliation.account_id_ref
    `).all(
        tradeDate,
        eventStreamWatermarkSha256,
        eventStreamWatermarkSha256,
        identityGroupId,
    );
    if (rows.length !== expectedFixedAccountCount) return false;
    if (
        policy.reservedDimensions.some((dimension) =>
            ['notionalMinorUnits', 'cashMinorUnits'].includes(dimension),
        ) &&
        rows.some((row) => row.exposure_baseline_valuation_complete !== 1)
    ) {
        database.prepare('DELETE FROM exposure_account_arbiter_heads').run();
        database.prepare('DELETE FROM exposure_identity_arbiter_heads').run();
        return false;
    }
    const identityBaseline = {
        quantityShares: 0,
        notionalMinorUnits: 0,
        cashMinorUnits: 0,
        positionShares: 0,
        orderCount: 0,
    };
    for (const row of rows) {
        for (const dimension of SMART_ORDER_RUNTIME_RISK_DIMENSIONS) {
            const column =
                EXPOSURE_DIMENSION_COLUMNS[dimension].baseline.replace(
                    'baseline_',
                    'exposure_baseline_',
                );
            identityBaseline[dimension] = addExposureInteger(
                identityBaseline[dimension],
                row[column],
                `identity risk baseline ${dimension}`,
            );
        }
    }
    const identityPnl = database.prepare(`
        SELECT * FROM canonical_pnl_identity_heads
         WHERE identity_group_id=? AND trade_date=?
           AND event_stream_watermark_hash=?
    `).get(identityGroupId, tradeDate, eventStreamWatermarkSha256);
    if (!identityPnl) return false;
    database.prepare(`
        INSERT INTO exposure_identity_arbiter_heads(
            identity_group_id, policy_revision, policy_hash,
            source_revision, source_sequence, source_evidence_hash,
            observed_at_epoch_ms, valid_until_epoch_ms,
            reserved_dimensions_json, baseline_quantity_shares,
            baseline_notional_minor_units, baseline_cash_minor_units,
            baseline_position_shares, baseline_order_count,
            limit_quantity_shares, limit_notional_minor_units,
            limit_cash_minor_units, limit_position_shares,
            limit_order_count, daily_loss_limit_minor_units,
            updated_at_epoch_ms, revision
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
        ON CONFLICT(identity_group_id) DO UPDATE SET
            policy_revision=excluded.policy_revision,
            policy_hash=excluded.policy_hash,
            source_revision=excluded.source_revision,
            source_sequence=excluded.source_sequence,
            source_evidence_hash=excluded.source_evidence_hash,
            observed_at_epoch_ms=excluded.observed_at_epoch_ms,
            valid_until_epoch_ms=excluded.valid_until_epoch_ms,
            reserved_dimensions_json=excluded.reserved_dimensions_json,
            baseline_quantity_shares=excluded.baseline_quantity_shares,
            baseline_notional_minor_units=excluded.baseline_notional_minor_units,
            baseline_cash_minor_units=excluded.baseline_cash_minor_units,
            baseline_position_shares=excluded.baseline_position_shares,
            baseline_order_count=excluded.baseline_order_count,
            limit_quantity_shares=excluded.limit_quantity_shares,
            limit_notional_minor_units=excluded.limit_notional_minor_units,
            limit_cash_minor_units=excluded.limit_cash_minor_units,
            limit_position_shares=excluded.limit_position_shares,
            limit_order_count=excluded.limit_order_count,
            daily_loss_limit_minor_units=excluded.daily_loss_limit_minor_units,
            updated_at_epoch_ms=excluded.updated_at_epoch_ms,
            revision=exposure_identity_arbiter_heads.revision+1
    `).run(
        identityGroupId,
        stored.verified.policyRevision,
        stored.verified.executionPolicyHash,
        eventStreamWatermarkSha256,
        identityPnl.revision + 1,
        identityPnl.source_evidence_hash,
        identityPnl.as_of_epoch_ms,
        identityPnl.valid_until_epoch_ms,
        dimensionsJson,
        identityBaseline.quantityShares,
        identityBaseline.notionalMinorUnits,
        identityBaseline.cashMinorUnits,
        identityBaseline.positionShares,
        identityBaseline.orderCount,
        policy.identityLimits.quantityShares,
        policy.identityLimits.notionalMinorUnits,
        policy.identityLimits.cashMinorUnits,
        policy.identityLimits.positionShares,
        policy.identityLimits.orderCount,
        policy.identityDailyLossLimitMinorUnits,
        now,
    );
    const currentAccountKeys = new Set(
        rows.map((row) => `${row.account_broker_ref}\u001f${row.account_id_ref}`),
    );
    for (const existing of database.prepare(`
        SELECT account_broker_ref, account_id_ref
          FROM exposure_account_arbiter_heads
    `).all()) {
        if (
            !currentAccountKeys.has(
                `${existing.account_broker_ref}\u001f${existing.account_id_ref}`,
            )
        ) {
            database.prepare(`
                DELETE FROM exposure_account_arbiter_heads
                 WHERE account_broker_ref=? AND account_id_ref=?
            `).run(existing.account_broker_ref, existing.account_id_ref);
        }
    }
    for (const row of rows) {
        database.prepare(`
            INSERT INTO exposure_account_arbiter_heads(
                account_broker_ref, account_id_ref, identity_group_id,
                policy_revision, policy_hash, source_revision,
                source_sequence, source_evidence_hash,
                observed_at_epoch_ms, valid_until_epoch_ms,
                reserved_dimensions_json, baseline_quantity_shares,
                baseline_notional_minor_units, baseline_cash_minor_units,
                baseline_position_shares, baseline_order_count,
                limit_quantity_shares, limit_notional_minor_units,
                limit_cash_minor_units, limit_position_shares,
                limit_order_count, daily_loss_limit_minor_units,
                updated_at_epoch_ms, revision
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            ON CONFLICT(account_broker_ref, account_id_ref) DO UPDATE SET
                identity_group_id=excluded.identity_group_id,
                policy_revision=excluded.policy_revision,
                policy_hash=excluded.policy_hash,
                source_revision=excluded.source_revision,
                source_sequence=excluded.source_sequence,
                source_evidence_hash=excluded.source_evidence_hash,
                observed_at_epoch_ms=excluded.observed_at_epoch_ms,
                valid_until_epoch_ms=excluded.valid_until_epoch_ms,
                reserved_dimensions_json=excluded.reserved_dimensions_json,
                baseline_quantity_shares=excluded.baseline_quantity_shares,
                baseline_notional_minor_units=excluded.baseline_notional_minor_units,
                baseline_cash_minor_units=excluded.baseline_cash_minor_units,
                baseline_position_shares=excluded.baseline_position_shares,
                baseline_order_count=excluded.baseline_order_count,
                limit_quantity_shares=excluded.limit_quantity_shares,
                limit_notional_minor_units=excluded.limit_notional_minor_units,
                limit_cash_minor_units=excluded.limit_cash_minor_units,
                limit_position_shares=excluded.limit_position_shares,
                limit_order_count=excluded.limit_order_count,
                daily_loss_limit_minor_units=excluded.daily_loss_limit_minor_units,
                updated_at_epoch_ms=excluded.updated_at_epoch_ms,
                revision=exposure_account_arbiter_heads.revision+1
        `).run(
            row.account_broker_ref,
            row.account_id_ref,
            identityGroupId,
            stored.verified.policyRevision,
            stored.verified.executionPolicyHash,
            row.source_revision,
            row.revision + 1,
            row.evidence_hash,
            row.pnl_as_of_epoch_ms,
            row.pnl_valid_until_epoch_ms,
            dimensionsJson,
            row.exposure_baseline_quantity_shares,
            row.exposure_baseline_notional_minor_units,
            row.exposure_baseline_cash_minor_units,
            row.exposure_baseline_position_shares,
            row.exposure_baseline_order_count,
            policy.accountLimits.quantityShares,
            policy.accountLimits.notionalMinorUnits,
            policy.accountLimits.cashMinorUnits,
            policy.accountLimits.positionShares,
            policy.accountLimits.orderCount,
            policy.accountDailyLossLimitMinorUnits,
            now,
        );
    }
    return true;
}

function settleProtectionOcoFromReconciliation(database, { projection, now }) {
    const groups = database.prepare(`
        SELECT groups.protection_group_id, groups.state AS group_state,
               groups.current_generation, groups.revision AS group_revision,
               generations.state AS generation_state,
               generations.revision AS generation_revision,
               generations.winner_activation_id,
               generations.winner_intent_id,
               claims.exit_claim_id, claims.intent_id, claims.state AS claim_state,
               claims.quantity_shares, claims.allocation_start_share,
               claims.position_lineage_id, claims.revision AS claim_revision,
               obligations.obligation_id, obligations.strategy_id,
               obligations.filled_shares,
               obligations.confirmed_exited_shares,
               obligations.revision AS obligation_revision,
               strategies.state AS strategy_state,
               strategies.revision AS strategy_revision,
               exit_intents.contract_key, exit_intents.account_broker_ref,
               exit_intents.account_id_ref, exit_intents.trade_date,
               exit_intents.activation_id,
               exit_intents.revision AS intent_revision,
               entry_intents.payload_json AS entry_payload_json,
               existing.protection_plan_json AS existing_plan_json,
               existing.revision AS existing_head_revision,
               heads.status, heads.order_quantity,
               heads.cumulative_deal_quantity,
               heads.cumulative_cancel_quantity, heads.remaining_quantity,
               heads.quantity_unit, heads.broker_order_correlation_key_hash
          FROM protection_groups AS groups
          JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
          JOIN exit_claims AS claims
            ON claims.exit_claim_id=groups.exit_claim_id
          JOIN protection_obligations AS obligations
            ON obligations.obligation_id=groups.obligation_id
          JOIN strategies
            ON strategies.strategy_id=obligations.strategy_id
     LEFT JOIN pending_protection_commitments AS commitments
            ON commitments.commitment_id=obligations.commitment_id
     LEFT JOIN order_intents AS entry_intents
            ON entry_intents.intent_id=commitments.entry_intent_id
     LEFT JOIN existing_position_protection_heads AS existing
            ON existing.strategy_id=obligations.strategy_id
           AND existing.obligation_id=obligations.obligation_id
           AND existing.exit_claim_id=claims.exit_claim_id
          JOIN order_intents AS exit_intents
            ON exit_intents.intent_id=generations.winner_intent_id
          JOIN broker_event_heads AS heads
            ON heads.intent_id=exit_intents.intent_id
         WHERE exit_intents.account_broker_ref=?
           AND exit_intents.account_id_ref=?
           AND exit_intents.trade_date=?
           AND groups.state IN ('broker_working','unknown')
           AND generations.state IN ('broker_working','unknown')
           AND strategies.strategy_kind<>'parent_child'
         ORDER BY groups.protection_group_id
    `).all(
        projection.account.brokerId,
        projection.account.accountId,
        projection.tradeDate,
    );
    let settledCount = 0;
    for (const row of groups) {
        if (
            !['Filled', 'Cancelled', 'Inactive', 'Failed'].includes(row.status) ||
            row.remaining_quantity !== 0 ||
            row.claim_state !== 'unknown' ||
            row.intent_id !== row.winner_intent_id ||
            row.winner_activation_id !== row.activation_id
        ) continue;
        const plan = row.existing_plan_json !== null
            ? canonicalExistingPositionProtectionPlan(
                  parseStoredCanonicalObject(
                      row.existing_plan_json,
                      'protection OCO settlement existing-position plan',
                  ),
              )
            : canonicalProtectedEntryPlan(
                  canonicalProtectedEntryIntentPayload(
                      parseStoredCanonicalObject(
                          row.entry_payload_json,
                          'protection OCO settlement entry payload',
                      ),
                  ).payload.protectionPlan,
              );
        const contractUnit =
            plan.plan.entryOrder?.contractUnit ?? plan.contractUnit;
        const orderShares = brokerEventQuantityShares(
            row.order_quantity,
            row.quantity_unit,
            contractUnit,
            'protection OCO order quantity',
        );
        const filledShares = brokerEventQuantityShares(
            row.cumulative_deal_quantity,
            row.quantity_unit,
            contractUnit,
            'protection OCO cumulative fill',
        );
        const cancelledShares = brokerEventQuantityShares(
            row.cumulative_cancel_quantity,
            row.quantity_unit,
            contractUnit,
            'protection OCO cumulative cancel',
        );
        if (
            orderShares !== row.quantity_shares ||
            filledShares + cancelledShares !== orderShares
        ) continue;
        const dealRows = database.prepare(`
            SELECT deal_id, event_deal_quantity, quantity_unit
              FROM broker_event_records
             WHERE intent_id=? AND event_kind='deal'
               AND broker_order_correlation_key_hash=?
             ORDER BY deal_id
        `).all(row.winner_intent_id, row.broker_order_correlation_key_hash);
        const reconciledDealIds = new Set(
            projection.deals.map((deal) => deal.dealId),
        );
        let durableDealShares = 0;
        let dealSetComplete = true;
        for (const deal of dealRows) {
            if (deal.deal_id === null || !reconciledDealIds.has(deal.deal_id)) {
                dealSetComplete = false;
                break;
            }
            durableDealShares += brokerEventQuantityShares(
                deal.event_deal_quantity,
                deal.quantity_unit,
                contractUnit,
                'protection OCO deal quantity',
            );
        }
        const position = projection.positions.find(
            (candidate) => candidate.contractKey === row.contract_key,
        );
        if (
            !dealSetComplete ||
            durableDealShares !== filledShares ||
            !position ||
            position.positionLineageId !== row.position_lineage_id
        ) continue;
        const settlementHash = sha256Canonical(
            {
                schemaVersion:
                    'smart-order-protection-oco-settlement/2026-08-15.1',
                protectionGroupId: row.protection_group_id,
                remainderGeneration: row.current_generation,
                exitClaimId: row.exit_claim_id,
                winnerIntentId: row.winner_intent_id,
                orderShares,
                filledShares,
                cancelledShares,
                reconciliationSnapshotHash: projection.snapshotSha256,
                reconciliationEvidenceHash: projection.evidenceSha256,
            },
            'protection OCO settlement',
        );
        const nextConfirmedExited = row.confirmed_exited_shares + filledShares;
        if (
            !Number.isSafeInteger(nextConfirmedExited) ||
            nextConfirmedExited > row.filled_shares
        ) continue;
        const remainingShares = row.quantity_shares - filledShares;
        const terminalGeneration = database.prepare(`
            UPDATE protection_remainder_generations
               SET state='terminal', evidence_hash=?,
                   updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                   revision=revision+1
             WHERE protection_group_id=? AND remainder_generation=?
               AND state=? AND revision=?
        `).run(
            settlementHash,
            now,
            now,
            row.protection_group_id,
            row.current_generation,
            row.generation_state,
            row.generation_revision,
        );
        const intentTerminal = database.prepare(`
            UPDATE order_intents
               SET state='terminal', terminal_outcome=?,
                   updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                   revision=revision+1
             WHERE intent_id=? AND revision=?
               AND state NOT IN ('terminal','cancelled_proven_unsent')
        `).run(
            filledShares === 0
                ? 'protective_zero_fill_terminal'
                : remainingShares === 0
                  ? 'protective_full_fill_terminal'
                  : 'protective_partial_fill_terminal',
            now,
            now,
            row.winner_intent_id,
            row.intent_revision,
        );
        const activationState =
            filledShares === 0
                ? 'cancelled'
                : remainingShares === 0
                  ? 'filled'
                  : 'part_filled';
        const activationUpdate = database.prepare(`
            UPDATE activations
               SET state=?, evidence_hash=?, updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE activation_id=?
               AND state NOT IN ('filled','cancelled','failed','missed')
        `).run(
            activationState,
            settlementHash,
            now,
            row.winner_activation_id,
        );
        const obligationState =
            nextConfirmedExited === row.filled_shares
                ? 'fulfilled'
                : filledShares > 0
                  ? 'partially_exited'
                  : 'monitoring';
        const obligationUpdate = database.prepare(`
            UPDATE protection_obligations
               SET state=?, confirmed_exited_shares=?,
                   updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                   revision=revision+1
             WHERE obligation_id=? AND revision=?
        `).run(
            obligationState,
            nextConfirmedExited,
            now,
            obligationState === 'fulfilled' ? now : null,
            row.obligation_id,
            row.obligation_revision,
        );
        if (
            Number(terminalGeneration.changes) !== 1 ||
            Number(intentTerminal.changes) !== 1 ||
            Number(activationUpdate.changes) !== 1 ||
            Number(obligationUpdate.changes) !== 1
        ) {
            throw new Error('protection OCO settlement companion CAS failed');
        }
        if (remainingShares === 0) {
            const claimUpdate = database.prepare(`
                UPDATE exit_claims
                   SET state='consumed', evidence_hash=?,
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE exit_claim_id=? AND intent_id=?
                   AND state='unknown' AND revision=?
            `).run(
                settlementHash,
                now,
                now,
                row.exit_claim_id,
                row.winner_intent_id,
                row.claim_revision,
            );
            const groupUpdate = database.prepare(`
                UPDATE protection_groups
                   SET state='fulfilled', updated_at_epoch_ms=?,
                       terminal_at_epoch_ms=?, revision=revision+1
                 WHERE protection_group_id=? AND state=? AND revision=?
            `).run(
                now,
                now,
                row.protection_group_id,
                row.group_state,
                row.group_revision,
            );
            if (
                Number(claimUpdate.changes) !== 1 ||
                Number(groupUpdate.changes) !== 1
            ) throw new Error('protection OCO full settlement lost its CAS');
        } else {
            const nextGeneration = row.current_generation + 1;
            let remainderFormal = null;
            let remainderFormalJson = null;
            let remainderFormalHash = null;
            if (row.existing_plan_json !== null) {
                remainderFormal = deriveExistingPositionFormalProtection(
                    plan.plan,
                    remainingShares,
                );
                remainderFormalJson = stableCanonicalJson(remainderFormal);
                remainderFormalHash = sha256Canonical(
                    remainderFormal,
                    'existing-position formal protection',
                );
            }
            const claimUpdate = database.prepare(`
                UPDATE exit_claims
                   SET intent_id=NULL, remainder_generation=?,
                       allocation_start_share=allocation_start_share+?,
                       quantity_shares=?, state='monitoring_reserved',
                       evidence_hash=?, updated_at_epoch_ms=?,
                       terminal_at_epoch_ms=NULL, revision=revision+1
                 WHERE exit_claim_id=? AND intent_id=?
                   AND state='unknown' AND revision=?
            `).run(
                nextGeneration,
                filledShares,
                remainingShares,
                settlementHash,
                now,
                row.exit_claim_id,
                row.winner_intent_id,
                row.claim_revision,
            );
            const groupUpdate = database.prepare(`
                UPDATE protection_groups
                   SET state='rearm_required', current_generation=?,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE protection_group_id=? AND state=?
                   AND current_generation=? AND revision=?
            `).run(
                nextGeneration,
                now,
                row.protection_group_id,
                row.group_state,
                row.current_generation,
                row.group_revision,
            );
            if (
                Number(claimUpdate.changes) !== 1 ||
                Number(groupUpdate.changes) !== 1
            ) throw new Error('protection OCO remainder settlement lost its CAS');
            database.prepare(`
                INSERT INTO protection_remainder_generations(
                    protection_group_id, remainder_generation, exit_claim_id,
                    state, quantity_shares, evidence_hash,
                    created_at_epoch_ms, updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, 'rearm_required', ?, ?, ?, ?, 0)
            `).run(
                row.protection_group_id,
                nextGeneration,
                row.exit_claim_id,
                remainingShares,
                settlementHash,
                now,
                now,
            );
            if (row.existing_plan_json !== null) {
                const headUpdate = database.prepare(`
                    UPDATE existing_position_protection_heads
                       SET formal_protection_json=?, formal_protection_hash=?,
                           reconciliation_evidence_hash=?,
                           reconciliation_as_of_epoch_ms=?,
                           updated_at_epoch_ms=?, revision=revision+1
                     WHERE strategy_id=? AND obligation_id=? AND exit_claim_id=?
                       AND revision=?
                `).run(
                    remainderFormalJson,
                    remainderFormalHash,
                    projection.evidenceSha256,
                    projection.asOfEpochMs,
                    now,
                    row.strategy_id,
                    row.obligation_id,
                    row.exit_claim_id,
                    row.existing_head_revision,
                );
                if (Number(headUpdate.changes) !== 1) {
                    throw new Error(
                        'existing-position OCO remainder formal projection lost its CAS',
                    );
                }
                if (
                    ['observing', 'monitoring', 'recovery'].includes(
                        row.strategy_state,
                    )
                ) {
                    const strategyPause = database.prepare(`
                        UPDATE strategies
                           SET state='paused', updated_at_epoch_ms=?,
                               revision=revision+1
                         WHERE strategy_id=? AND state=? AND revision=?
                    `).run(
                        now,
                        row.strategy_id,
                        row.strategy_state,
                        row.strategy_revision,
                    );
                    if (Number(strategyPause.changes) !== 1) {
                        throw new Error(
                            'existing-position OCO remainder user-rearm pause lost its CAS',
                        );
                    }
                    insertTransitionJournalEvent(database, {
                        entityKind: 'strategy',
                        entityId: row.strategy_id,
                        revision: row.strategy_revision + 1,
                        reasonCode:
                            'PROTECTION_OCO_REMAINDER_USER_REARM_REQUIRED',
                        summaryCode:
                            'strategy_paused_for_protection_remainder_rearm',
                        nowEpochMs: now,
                        payloadHash: settlementHash,
                        eventSuffix:
                            `generation-${row.current_generation}-remainder-paused`,
                    });
                } else if (row.strategy_state !== 'paused') {
                    throw new Error(
                        'existing-position OCO remainder requires a pausable strategy',
                    );
                }
            }
        }
        database.prepare('DELETE FROM repository_meta WHERE key=?')
            .run(dispatchArbiterGrantMetaKey(row.winner_intent_id));
        database.prepare(`
            UPDATE intent_rearm_authorizations
               SET state='superseded', revision=revision+1
             WHERE intent_id=? AND state='active'
        `).run(row.winner_intent_id);
        advanceLifecycleSideEffectRevision(database);
        insertTransitionJournalEvent(database, {
            entityKind: 'protection_group',
            entityId: row.protection_group_id,
            revision: row.group_revision + 1,
            reasonCode:
                remainingShares === 0
                    ? 'PROTECTION_OCO_GROUP_FULFILLED'
                    : 'PROTECTION_OCO_REMAINDER_REARM_REQUIRED',
            summaryCode:
                remainingShares === 0
                    ? 'protection_oco_group_fulfilled'
                    : 'protection_oco_remainder_rearm_required',
            nowEpochMs: now,
            payloadHash: settlementHash,
            eventSuffix: `generation-${row.current_generation}-settled`,
        });
        settledCount += 1;
    }
    return settledCount;
}

function transitionParentChildToManual(
    database,
    { row, now, evidenceHash, summaryCode },
) {
    if (row.strategy_state !== 'manual_intervention') {
        const strategyUpdate = database.prepare(`
            UPDATE strategies
               SET state='manual_intervention', updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE strategy_id=? AND state=? AND revision=?
        `).run(
            now,
            row.strategy_id,
            row.strategy_state,
            row.strategy_revision,
        );
        if (Number(strategyUpdate.changes) !== 1) {
            throw new Error('parent-child manual transition lost its strategy CAS');
        }
    }
    const progressUpdate = database.prepare(`
        UPDATE parent_child_progress_heads
           SET state='manual_intervention', updated_at_epoch_ms=?,
               revision=revision+1
         WHERE strategy_id=? AND revision=?
           AND state<>'manual_intervention'
    `).run(now, row.strategy_id, row.progress_revision);
    if (
        row.progress_state !== 'manual_intervention' &&
        Number(progressUpdate.changes) !== 1
    ) {
        throw new Error('parent-child manual transition lost its progress CAS');
    }
    if (row.child_exit_claim_id) {
        database.prepare(`
            UPDATE exit_claims SET state='unknown', updated_at_epoch_ms=?,
                   evidence_hash=?, revision=revision+1
             WHERE exit_claim_id=? AND state IN (
                 'monitoring_reserved','intent_reserved','broker_working'
             )
        `).run(now, evidenceHash, row.child_exit_claim_id);
        database.prepare(`
            UPDATE protection_groups SET state='unknown',
                   updated_at_epoch_ms=?, revision=revision+1
             WHERE protection_group_id=? AND state NOT IN ('fulfilled','unknown')
        `).run(now, row.child_protection_group_id);
        database.prepare(`
            UPDATE protection_remainder_generations SET state='unknown',
                   evidence_hash=?, updated_at_epoch_ms=?, revision=revision+1
             WHERE protection_group_id=? AND state NOT IN ('terminal','unknown')
        `).run(
            evidenceHash,
            now,
            row.child_protection_group_id,
        );
        database.prepare(`
            UPDATE protection_obligations SET state='safety_blocked',
                   updated_at_epoch_ms=?, revision=revision+1
             WHERE obligation_id=? AND state NOT IN ('fulfilled','safety_blocked')
        `).run(now, row.child_obligation_id);
    }
    const caseId = `resolution:parent-child:${evidenceHash.slice(7)}`;
    const blockerId = `blocker:parent-child:${evidenceHash.slice(7)}`;
    const scopeHash = sha256Canonical(
        {
            strategyId: row.strategy_id,
            parentIntentId: row.parent_intent_id,
            childIntentId: row.child_intent_id ?? null,
        },
        'parent-child manual scope',
    );
    database.prepare(`
        INSERT OR IGNORE INTO resolution_cases(
            resolution_case_id, strategy_id, reason_code, scope_hash,
            evidence_snapshot_hash, state, created_at_epoch_ms,
            updated_at_epoch_ms, terminal_at_epoch_ms, revision
        ) VALUES (?, ?, 'ENTRY_RESULT_UNKNOWN', ?, ?, 'open', ?, ?, NULL, 0)
    `).run(caseId, row.strategy_id, scopeHash, evidenceHash, now, now);
    database.prepare(`
        INSERT OR IGNORE INTO safety_blockers(
            blocker_id, resolution_case_id, scope_hash, reason_code,
            state, created_at_epoch_ms, resolved_at_epoch_ms, revision
        ) VALUES (?, ?, ?, 'ENTRY_RESULT_UNKNOWN', 'open', ?, NULL, 0)
    `).run(blockerId, caseId, scopeHash, now);
    insertTransitionJournalEvent(database, {
        entityKind: 'strategy',
        entityId: row.strategy_id,
        revision: row.strategy_revision + 1,
        reasonCode: 'ENTRY_RESULT_UNKNOWN',
        summaryCode,
        nowEpochMs: now,
        payloadHash: evidenceHash,
        eventSuffix: 'parent-child-manual',
    });
}

function expireIdleParentChildStrategy(
    database,
    { row, now, evidenceHash, withChildObligation },
) {
    const strategyState = withChildObligation
        ? 'expired_with_obligation'
        : 'expired';
    const progressState = strategyState;
    const strategyUpdate = database.prepare(`
        UPDATE strategies SET state=?, updated_at_epoch_ms=?,
               revision=revision+1, terminal_at_epoch_ms=
                   CASE WHEN ?='expired' THEN ? ELSE terminal_at_epoch_ms END
         WHERE strategy_id=? AND state='monitoring' AND revision=?
    `).run(
        strategyState,
        now,
        strategyState,
        now,
        row.strategy_id,
        row.strategy_revision,
    );
    const progressUpdate = database.prepare(`
        UPDATE parent_child_progress_heads
           SET state=?, updated_at_epoch_ms=?, revision=revision+1
         WHERE strategy_id=? AND revision=? AND state=?
    `).run(
        progressState,
        now,
        row.strategy_id,
        row.progress_revision,
        row.progress_state,
    );
    if (
        Number(strategyUpdate.changes) !== 1 ||
        Number(progressUpdate.changes) !== 1
    ) {
        throw new Error('parent-child idle expiry lost its CAS');
    }
    database.prepare(`
        DELETE FROM parent_child_condition_heads WHERE strategy_id=?
    `).run(row.strategy_id);
    if (withChildObligation) {
        database.prepare(`
            UPDATE exit_claims SET state='released', evidence_hash=?,
                   updated_at_epoch_ms=?, terminal_at_epoch_ms=?, revision=revision+1
             WHERE exit_claim_id=? AND state='monitoring_reserved'
               AND intent_id IS NULL
        `).run(evidenceHash, now, now, row.child_exit_claim_id);
        database.prepare(`
            UPDATE protection_groups SET state='unknown',
                   updated_at_epoch_ms=?, revision=revision+1
             WHERE protection_group_id=? AND state='monitoring'
        `).run(now, row.child_protection_group_id);
        database.prepare(`
            UPDATE protection_remainder_generations SET state='unknown',
                   evidence_hash=?, updated_at_epoch_ms=?, revision=revision+1
             WHERE protection_group_id=? AND state='monitoring'
        `).run(evidenceHash, now, row.child_protection_group_id);
        database.prepare(`
            UPDATE protection_obligations SET state='safety_blocked',
                   updated_at_epoch_ms=?, revision=revision+1
             WHERE obligation_id=? AND state='monitoring'
        `).run(now, row.child_obligation_id);
        const caseId = `resolution:parent-child-expiry:${evidenceHash.slice(7)}`;
        const blockerId = `blocker:parent-child-expiry:${evidenceHash.slice(7)}`;
        const scopeHash = sha256Canonical(
            {
                childExitClaimId: row.child_exit_claim_id,
                strategyId: row.strategy_id,
            },
            'parent-child expiry scope',
        );
        database.prepare(`
            INSERT OR IGNORE INTO resolution_cases(
                resolution_case_id, strategy_id, reason_code, scope_hash,
                evidence_snapshot_hash, state, created_at_epoch_ms,
                updated_at_epoch_ms, terminal_at_epoch_ms, revision
            ) VALUES (?, ?, 'PROTECTION_RESERVATION_EXPIRED', ?, ?,
                      'open', ?, ?, NULL, 0)
        `).run(caseId, row.strategy_id, scopeHash, evidenceHash, now, now);
        database.prepare(`
            INSERT OR IGNORE INTO safety_blockers(
                blocker_id, resolution_case_id, scope_hash, reason_code,
                state, created_at_epoch_ms, resolved_at_epoch_ms, revision
            ) VALUES (?, ?, ?, 'PROTECTION_RESERVATION_EXPIRED',
                      'open', ?, NULL, 0)
        `).run(blockerId, caseId, scopeHash, now);
    }
    insertTransitionJournalEvent(database, {
        entityKind: 'strategy',
        entityId: row.strategy_id,
        revision: row.strategy_revision + 1,
        reasonCode: withChildObligation
            ? 'PROTECTION_RESERVATION_EXPIRED'
            : 'STRATEGY_VALIDITY_EXPIRED',
        summaryCode: withChildObligation
            ? 'parent_child_child_untriggered_expired_with_obligation'
            : 'parent_child_parent_untriggered_expired',
        nowEpochMs: now,
        payloadHash: evidenceHash,
        eventSuffix: 'parent-child-idle-expired',
    });
}

function settleParentChildFromReconciliation(database, { projection, now }) {
    const idleRows = database.prepare(`
        SELECT progress.state AS progress_state,
               progress.revision AS progress_revision, progress.*,
               strategies.state AS strategy_state,
               strategies.revision AS strategy_revision,
               strategies.definition_json
          FROM parent_child_progress_heads AS progress
          JOIN strategies USING(strategy_id)
         WHERE strategies.strategy_kind='parent_child'
           AND strategies.state='monitoring'
           AND strategies.account_broker_ref=?
           AND strategies.account_id_ref=?
           AND progress.state IN ('waiting_parent','child_monitoring')
         ORDER BY progress.strategy_id
         LIMIT 129
    `).all(projection.account.brokerId, projection.account.accountId);
    if (idleRows.length > 128) {
        throw new Error('parent-child idle expiry set exceeds its bound');
    }
    let settledCount = 0;
    let blockedCount = 0;
    for (const row of idleRows) {
        const definition = parseStoredCanonicalObject(
            row.definition_json,
            'parent-child idle expiry definition',
        );
        assertCanonicalSmartOrderDraft(definition, {
            expectedKind: 'parent_child',
        });
        const wallTime = taipeiWallTimeAt(projection.asOfEpochMs);
        const parentExpired =
            row.progress_state === 'waiting_parent' &&
            parentChildParentWindowClosed({
                parentEndDate: definition.parameters.parentValidity.endDate,
                tradeDate: projection.tradeDate,
                wallTime,
            });
        const childExpired =
            row.progress_state === 'child_monitoring' &&
            parentChildChildWindowClosed({
                activationTradeDate: row.child_activation_trade_date,
                cutoffTime: definition.parameters.child.cutoffTime,
                tradeDate: projection.tradeDate,
                wallTime,
            });
        if (!parentExpired && !childExpired) continue;
        const evidenceHash = sha256Canonical(
            {
                asOfEpochMs: projection.asOfEpochMs,
                evidenceSha256: projection.evidenceSha256,
                progressState: row.progress_state,
                strategyId: row.strategy_id,
                tradeDate: projection.tradeDate,
            },
            'parent-child idle expiry',
        );
        expireIdleParentChildStrategy(database, {
            row,
            now,
            evidenceHash,
            withChildObligation: childExpired,
        });
        settledCount += 1;
    }
    const rows = database.prepare(`
        SELECT progress.state AS progress_state,
               progress.revision AS progress_revision, progress.*,
               strategies.state AS strategy_state,
               strategies.revision AS strategy_revision,
               strategies.definition_json,
               strategies.confirmation_snapshot_hash,
               intents.intent_id AS active_intent_id,
               intents.state AS intent_state,
               intents.revision AS intent_revision,
               intents.payload_json, intents.activation_id,
               activations.state AS activation_state,
               activations.revision AS activation_revision,
               reservations.reservation_id,
               reservations.state AS reservation_state,
               reservations.revision AS reservation_revision,
               heads.status, heads.order_quantity,
               heads.cumulative_deal_quantity,
               heads.cumulative_cancel_quantity,
               heads.remaining_quantity, heads.quantity_unit,
               heads.evidence_hash AS broker_evidence_hash,
               heads.broker_order_correlation_key_hash,
               head_events.order_condition AS broker_order_condition,
               head_events.order_lot AS broker_order_lot,
               head_events.price_type AS broker_price_type,
               head_events.time_in_force AS broker_time_in_force,
               head_events.price_decimal AS broker_price_decimal
          FROM parent_child_progress_heads AS progress
          JOIN strategies USING(strategy_id)
          JOIN order_intents AS intents
            ON intents.intent_id=CASE
                 WHEN progress.state IN ('parent_intent_prepared','parent_working')
                   THEN progress.parent_intent_id
                 ELSE progress.child_intent_id END
          JOIN activations ON activations.activation_id=intents.activation_id
     LEFT JOIN entry_exposure_reservations AS reservations
            ON reservations.intent_id=intents.intent_id
     LEFT JOIN broker_event_heads AS heads ON heads.intent_id=intents.intent_id
     LEFT JOIN broker_event_records AS head_events
            ON head_events.broker_event_key_hash=heads.broker_event_key_hash
         WHERE intents.account_broker_ref=? AND intents.account_id_ref=?
           AND progress.state IN (
               'parent_intent_prepared','parent_working',
               'child_intent_prepared','child_working'
           )
         ORDER BY progress.strategy_id
         LIMIT 129
    `).all(projection.account.brokerId, projection.account.accountId);
    if (rows.length > 128) {
        throw new Error('parent-child reconciliation candidate set exceeds its bound');
    }
    for (const row of rows) {
        if (!row.status) continue;
        const payload = canonicalParentChildIntentPayload(
            parseStoredCanonicalObject(
                row.payload_json,
                'parent-child reconciliation intent payload',
            ),
        );
        const orderShares = brokerEventQuantityShares(
            row.order_quantity,
            row.quantity_unit,
            payload.order.contractUnit,
            'parent-child reconciled order quantity',
        );
        const filledShares = brokerEventQuantityShares(
            row.cumulative_deal_quantity,
            row.quantity_unit,
            payload.order.contractUnit,
            'parent-child reconciled fill quantity',
        );
        const cancelledShares = brokerEventQuantityShares(
            row.cumulative_cancel_quantity,
            row.quantity_unit,
            payload.order.contractUnit,
            'parent-child reconciled cancel quantity',
        );
        const remainingShares = brokerEventQuantityShares(
            row.remaining_quantity,
            row.quantity_unit,
            payload.order.contractUnit,
            'parent-child reconciled remaining quantity',
        );
        const terminal = ['Filled', 'Cancelled', 'Inactive', 'Failed'].includes(
            row.status,
        );
        const definition = parseStoredCanonicalObject(
            row.definition_json,
            'parent-child reconciliation definition',
        );
        assertCanonicalSmartOrderDraft(definition, {
            expectedKind: 'parent_child',
        });
        const wallTime = taipeiWallTimeAt(projection.asOfEpochMs);
        const parentWindowClosed =
            payload.leg === 'parent' &&
            parentChildParentWindowClosed({
                parentEndDate: definition.parameters.parentValidity.endDate,
                tradeDate: projection.tradeDate,
                wallTime,
            });
        const childWindowClosed =
            payload.leg === 'child' &&
            parentChildChildWindowClosed({
                activationTradeDate: row.child_activation_trade_date,
                cutoffTime: definition.parameters.child.cutoffTime,
                tradeDate: projection.tradeDate,
                wallTime,
            });
        const brokerRevisionDrift =
            orderShares !== payload.order.baseShares ||
            row.broker_order_condition !== payload.order.orderCond ||
            row.broker_order_lot !== payload.order.orderLot ||
            row.broker_price_type !== payload.order.priceType ||
            row.broker_time_in_force !== payload.order.timeInForce ||
            row.broker_price_decimal !== payload.order.limitPrice;
        if (
            !terminal &&
            (parentWindowClosed || childWindowClosed || brokerRevisionDrift)
        ) {
            transitionParentChildToManual(database, {
                row,
                now,
                evidenceHash: row.broker_evidence_hash,
                summaryCode: brokerRevisionDrift
                    ? 'parent_child_broker_revision_drift_manual'
                    : payload.leg === 'parent'
                      ? 'parent_child_parent_working_expired_manual'
                      : 'parent_child_child_working_cutoff_manual',
            });
            blockedCount += 1;
            continue;
        }
        if (!terminal) {
            const nextState =
                payload.leg === 'parent' ? 'parent_working' : 'child_working';
            if (row.progress_state !== nextState) {
                const changed = database.prepare(`
                    UPDATE parent_child_progress_heads
                       SET state=?, updated_at_epoch_ms=?, revision=revision+1
                     WHERE strategy_id=? AND revision=?
                `).run(
                    nextState,
                    now,
                    row.strategy_id,
                    row.progress_revision,
                );
                if (Number(changed.changes) !== 1) {
                    throw new Error('parent-child working transition lost its CAS');
                }
            }
            blockedCount += 1;
            continue;
        }
        const correlations = database.prepare(`
            SELECT correlation_id, broker_order_id
              FROM broker_correlations
             WHERE intent_id=? AND broker_order_id IS NOT NULL
             ORDER BY correlation_id
        `).all(row.active_intent_id);
        if (correlations.length === 0) continue;
        if (correlations.length !== 1) {
            throw new Error(
                'parent-child terminal reconciliation is not uniquely correlated',
            );
        }
        const brokerOrder = database.prepare(`
            SELECT * FROM broker_orders WHERE broker_order_id=?
        `).get(correlations[0].broker_order_id);
        if (
            !brokerOrder ||
            brokerOrder.intent_id !== row.active_intent_id ||
            projection.workingOrders.some(
                (order) => order.brokerOrderId === brokerOrder.broker_order_id,
            )
        ) {
            throw new Error(
                'parent-child terminal reconciliation conflicts with the complete working set',
            );
        }
        const dealRows = database.prepare(`
            SELECT deal_id, event_deal_quantity, quantity_unit
              FROM broker_event_records
             WHERE intent_id=? AND event_kind='deal'
               AND broker_order_correlation_key_hash=?
             ORDER BY deal_id
        `).all(
            row.active_intent_id,
            row.broker_order_correlation_key_hash,
        );
        const reconciledDealIds = new Set(
            projection.deals.map((deal) => deal.dealId),
        );
        let durableDealShares = 0;
        let dealSetComplete = true;
        for (const deal of dealRows) {
            if (deal.deal_id === null || !reconciledDealIds.has(deal.deal_id)) {
                dealSetComplete = false;
                break;
            }
            durableDealShares += brokerEventQuantityShares(
                deal.event_deal_quantity,
                deal.quantity_unit,
                payload.order.contractUnit,
                'parent-child deal quantity',
            );
        }
        if (!dealSetComplete || durableDealShares !== filledShares) continue;
        const settlementHash = sha256Canonical(
            {
                schemaVersion:
                    'smart-order-parent-child-settlement/2026-08-21.1',
                leg: payload.leg,
                strategyId: row.strategy_id,
                intentId: row.active_intent_id,
                brokerOrderId: brokerOrder.broker_order_id,
                correlationId: correlations[0].correlation_id,
                brokerEvidenceHash: row.broker_evidence_hash,
                status: row.status,
                orderShares,
                filledShares,
                cancelledShares,
                tradeDate: projection.tradeDate,
            },
            'parent-child terminal settlement',
        );
        if (
            (payload.leg === 'parent'
                ? row.parent_settlement_hash
                : row.child_settlement_hash) === settlementHash
        ) {
            continue;
        }
        const quantityChanged =
            orderShares !== payload.order.baseShares ||
            filledShares + cancelledShares + remainingShares !== orderShares;
        const fullFill =
            !quantityChanged &&
            parentChildBrokerTerminalIsExactFullFill({
                brokerStatus: row.status,
                cancelledShares,
                expectedOrderShares: payload.order.baseShares,
                filledShares,
                orderShares,
                remainingShares,
            });
        const brokerState = {
            Filled: 'filled',
            Cancelled: 'cancelled',
            Inactive: 'inactive',
            Failed: 'failed',
        }[row.status];
        if (!BROKER_ORDER_TERMINAL_STATES.has(brokerOrder.state)) {
            const brokerUpdated = database.prepare(`
                UPDATE broker_orders SET state=?, filled_shares=?,
                       remaining_shares=0, evidence_hash=?,
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE broker_order_id=? AND revision=?
                   AND state NOT IN ('filled','cancelled','failed','inactive')
            `).run(
                brokerState,
                filledShares,
                settlementHash,
                now,
                now,
                brokerOrder.broker_order_id,
                brokerOrder.revision,
            );
            if (Number(brokerUpdated.changes) !== 1) {
                throw new Error('parent-child broker settlement lost its CAS');
            }
        }
        if (!['terminal', 'cancelled_proven_unsent'].includes(row.intent_state)) {
            const intentUpdated = database.prepare(`
                UPDATE order_intents SET state='terminal', terminal_outcome=?,
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE intent_id=? AND revision=?
                   AND state NOT IN ('terminal','cancelled_proven_unsent')
            `).run(
                `parent_child_${payload.leg}_${row.status.toLowerCase()}_reconciled`,
                now,
                now,
                row.active_intent_id,
                row.intent_revision,
            );
            if (Number(intentUpdated.changes) !== 1) {
                throw new Error('parent-child intent settlement lost its CAS');
            }
        }
        if (!['filled', 'failed', 'cancelled'].includes(row.activation_state)) {
            const activationUpdated = database.prepare(`
                UPDATE activations SET state=?, evidence_hash=?,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE activation_id=? AND revision=?
            `).run(
                fullFill ? 'filled' : filledShares > 0 ? 'part_filled' : 'cancelled',
                settlementHash,
                now,
                row.activation_id,
                row.activation_revision,
            );
            if (Number(activationUpdated.changes) !== 1) {
                throw new Error('parent-child activation settlement lost its CAS');
            }
        }
        if (row.reservation_id && !['consumed', 'released'].includes(row.reservation_state)) {
            const reservationUpdated = database.prepare(`
                UPDATE entry_exposure_reservations
                   SET state=?, updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE reservation_id=? AND revision=?
            `).run(
                filledShares > 0 ? 'consumed' : 'released',
                now,
                now,
                row.reservation_id,
                row.reservation_revision,
            );
            if (Number(reservationUpdated.changes) !== 1) {
                throw new Error('parent-child reservation settlement lost its CAS');
            }
        }
        if (payload.leg === 'parent' && fullFill) {
            const child = definition.parameters.child;
            const childRuntimeContractKey = `${child.order.contractKey.split(':')[0]}:${child.order.contractKey.split(':')[2]}:STK:Common`;
            const childPosition = projection.positions.find(
                (candidate) =>
                    candidate.contractKey === childRuntimeContractKey,
            );
            const childShares = safeInteger(
                Number(child.order.baseShares),
                'parentChild.child.baseShares',
                { minimum: 1 },
            );
            const externalWorkingSellShares = projection.workingOrders
                .filter(
                    (order) =>
                        order.contractKey === childRuntimeContractKey &&
                        order.side === 'Sell',
                )
                .reduce((total, order) => total + order.remainingShares, 0);
            const withinSameDay =
                projection.tradeDate === row.parent_activation_trade_date;
            const beforeCutoff =
                taipeiWallTimeAt(projection.asOfEpochMs) <= child.cutoffTime;
            const claimId = `claim:parent-child:${settlementHash.slice(7)}`;
            const allocation = childPosition
                ? allocateProtectedEntryExitClaim(database, {
                      accountBrokerRef: projection.account.brokerId,
                      accountIdRef: projection.account.accountId,
                      contractKey: childRuntimeContractKey,
                      exitClaimId: claimId,
                      positionLineageId: childPosition.positionLineageId,
                      positionQuantityShares:
                          childPosition.quantityShares -
                          externalWorkingSellShares,
                      quantityShares: childShares,
                  })
                : null;
            if (
                !withinSameDay ||
                !beforeCutoff ||
                !childPosition ||
                childPosition.availableShares < childShares ||
                allocation === null
            ) {
                transitionParentChildToManual(database, {
                    row,
                    now,
                    evidenceHash: settlementHash,
                    summaryCode:
                        'parent_child_full_fill_child_not_safely_activatable',
                });
            } else {
                const obligationId = `obligation:parent-child:${settlementHash.slice(7)}`;
                const groupId = `protection-group:parent-child:${settlementHash.slice(7)}`;
                database.prepare(`
                    INSERT INTO protection_obligations(
                        obligation_id, strategy_id, commitment_id, state,
                        position_lineage_id, filled_shares,
                        confirmed_exited_shares, created_at_epoch_ms,
                        updated_at_epoch_ms, revision
                    ) VALUES (?, ?, NULL, 'monitoring', ?, ?, 0, ?, ?, 0)
                `).run(
                    obligationId,
                    row.strategy_id,
                    childPosition.positionLineageId,
                    childShares,
                    now,
                    now,
                );
                database.prepare(`
                    INSERT INTO exit_claims(
                        exit_claim_id, obligation_id, intent_id,
                        external_lineage, account_broker_ref, account_id_ref,
                        contract_key, position_lineage_id,
                        remainder_generation, allocation_start_share,
                        quantity_shares, state, evidence_hash,
                        created_at_epoch_ms, updated_at_epoch_ms, revision
                    ) VALUES (?, ?, NULL, 0, ?, ?, ?, ?, 0, ?, ?,
                              'monitoring_reserved', ?, ?, ?, 0)
                `).run(
                    claimId,
                    obligationId,
                    projection.account.brokerId,
                    projection.account.accountId,
                    childRuntimeContractKey,
                    childPosition.positionLineageId,
                    allocation.allocationStartShare,
                    childShares,
                    settlementHash,
                    now,
                    now,
                );
                database.prepare(`
                    INSERT INTO protection_groups(
                        protection_group_id, obligation_id, exit_claim_id,
                        state, current_generation, plan_hash,
                        created_at_epoch_ms, updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, 'monitoring', 0, ?, ?, ?, 0)
                `).run(
                    groupId,
                    obligationId,
                    claimId,
                    row.confirmation_snapshot_hash,
                    now,
                    now,
                );
                database.prepare(`
                    INSERT INTO protection_remainder_generations(
                        protection_group_id, remainder_generation,
                        exit_claim_id, state, quantity_shares, evidence_hash,
                        created_at_epoch_ms, updated_at_epoch_ms, revision
                    ) VALUES (?, 0, ?, 'monitoring', ?, ?, ?, ?, 0)
                `).run(
                    groupId,
                    claimId,
                    childShares,
                    settlementHash,
                    now,
                    now,
                );
                const progressUpdated = database.prepare(`
                    UPDATE parent_child_progress_heads
                       SET state='child_monitoring', parent_settlement_hash=?,
                           child_activation_trade_date=?,
                           child_quantity_shares=?,
                           child_position_lineage_id=?, child_obligation_id=?,
                           child_exit_claim_id=?, child_protection_group_id=?,
                           updated_at_epoch_ms=?, revision=revision+1
                     WHERE strategy_id=? AND revision=?
                       AND state IN ('parent_intent_prepared','parent_working')
                `).run(
                    settlementHash,
                    projection.tradeDate,
                    childShares,
                    childPosition.positionLineageId,
                    obligationId,
                    claimId,
                    groupId,
                    now,
                    row.strategy_id,
                    row.progress_revision,
                );
                if (Number(progressUpdated.changes) !== 1) {
                    throw new Error(
                        'parent-child full-fill child activation lost its CAS',
                    );
                }
            }
        } else if (payload.leg === 'child' && fullFill) {
            const claimUpdated = database.prepare(`
                UPDATE exit_claims SET state='consumed', evidence_hash=?,
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE exit_claim_id=? AND intent_id=?
                   AND state IN ('broker_working','unknown')
            `).run(
                settlementHash,
                now,
                now,
                row.child_exit_claim_id,
                row.child_intent_id,
            );
            const groupUpdated = database.prepare(`
                UPDATE protection_groups SET state='fulfilled',
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE protection_group_id=?
                   AND state IN ('broker_working','unknown')
            `).run(now, now, row.child_protection_group_id);
            const generationUpdated = database.prepare(`
                UPDATE protection_remainder_generations SET state='terminal',
                       evidence_hash=?, updated_at_epoch_ms=?,
                       terminal_at_epoch_ms=?, revision=revision+1
                 WHERE protection_group_id=? AND remainder_generation=0
                   AND state IN ('broker_working','unknown')
            `).run(
                settlementHash,
                now,
                now,
                row.child_protection_group_id,
            );
            const obligationUpdated = database.prepare(`
                UPDATE protection_obligations SET state='fulfilled',
                       confirmed_exited_shares=?, updated_at_epoch_ms=?,
                       terminal_at_epoch_ms=?, revision=revision+1
                 WHERE obligation_id=? AND state<>'fulfilled'
            `).run(
                filledShares,
                now,
                now,
                row.child_obligation_id,
            );
            const progressUpdated = database.prepare(`
                UPDATE parent_child_progress_heads
                   SET state='completed', child_settlement_hash=?,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE strategy_id=? AND revision=?
                   AND state IN ('child_intent_prepared','child_working')
            `).run(
                settlementHash,
                now,
                row.strategy_id,
                row.progress_revision,
            );
            const strategyUpdated = database.prepare(`
                UPDATE strategies SET state='completed',
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE strategy_id=? AND state='monitoring' AND revision=?
            `).run(now, now, row.strategy_id, row.strategy_revision);
            if (
                Number(claimUpdated.changes) !== 1 ||
                Number(groupUpdated.changes) !== 1 ||
                Number(generationUpdated.changes) !== 1 ||
                Number(obligationUpdated.changes) !== 1 ||
                Number(progressUpdated.changes) !== 1 ||
                Number(strategyUpdated.changes) !== 1
            ) {
                throw new Error('parent-child child settlement lost its CAS');
            }
        } else {
            transitionParentChildToManual(database, {
                row,
                now,
                evidenceHash: settlementHash,
                summaryCode:
                    payload.leg === 'parent'
                        ? 'parent_child_parent_partial_or_modified_unprotected'
                        : 'parent_child_child_partial_or_unknown_manual',
            });
        }
        database.prepare('DELETE FROM repository_meta WHERE key=?').run(
            dispatchArbiterGrantMetaKey(row.active_intent_id),
        );
        database.prepare(`
            UPDATE intent_rearm_authorizations
               SET state='superseded', revision=revision+1
             WHERE intent_id=? AND state='active'
        `).run(row.active_intent_id);
        advanceLifecycleSideEffectRevision(database);
        insertTransitionJournalEvent(database, {
            entityKind: 'strategy',
            entityId: row.strategy_id,
            revision: row.strategy_revision,
            reasonCode: 'BROKER_FINAL_EVIDENCE_APPLIED',
            summaryCode:
                payload.leg === 'parent'
                    ? fullFill
                        ? 'parent_child_parent_filled_child_activated'
                        : 'parent_child_parent_terminal_manual'
                    : fullFill
                      ? 'parent_child_child_completed'
                      : 'parent_child_child_terminal_manual',
            nowEpochMs: now,
            payloadHash: settlementHash,
            eventSuffix: `parent-child-${payload.leg}-settled`,
        });
        settledCount += 1;
    }
    return Object.freeze({ settledCount, blockedCount });
}

function settleGoodTillFromReconciliation(database, { projection, now }) {
    const rows = database.prepare(`
        SELECT progress.*, intents.state AS intent_state,
               intents.revision AS intent_revision, intents.payload_json,
               activations.state AS activation_state,
               activations.revision AS activation_revision,
               reservations.reservation_id,
               reservations.state AS reservation_state,
               reservations.revision AS reservation_revision,
               strategies.state AS strategy_state,
               strategies.revision AS strategy_revision,
               heads.status, heads.order_quantity,
               heads.cumulative_deal_quantity,
               heads.cumulative_cancel_quantity,
               heads.remaining_quantity, heads.quantity_unit,
               heads.evidence_hash AS broker_evidence_hash
          FROM good_till_progress_heads AS progress
          JOIN order_intents AS intents
            ON intents.intent_id=progress.active_intent_id
          JOIN activations ON activations.activation_id=progress.active_activation_id
          JOIN entry_exposure_reservations AS reservations
            ON reservations.intent_id=intents.intent_id
          JOIN strategies ON strategies.strategy_id=progress.strategy_id
          LEFT JOIN broker_event_heads AS heads ON heads.intent_id=intents.intent_id
         WHERE intents.account_broker_ref=? AND intents.account_id_ref=?
           AND progress.daily_state IN (
               'intent_prepared','working','unknown_blocked','terminal_consumed'
           )
         ORDER BY progress.strategy_id
         LIMIT 129
    `).all(projection.account.brokerId, projection.account.accountId);
    if (rows.length > 128) {
        throw new Error('good-till reconciliation candidate set exceeds its bound');
    }
    let settledCount = 0;
    let blockedCount = 0;
    for (const row of rows) {
        if (!row.status) continue;
        const payload = canonicalGoodTillIntentPayload(
            parseStoredCanonicalObject(
                row.payload_json,
                'good-till reconciliation intent payload',
            ),
        );
        const orderShares = brokerEventQuantityShares(
            row.order_quantity,
            row.quantity_unit,
            payload.order.contractUnit,
            'good-till reconciled order quantity',
        );
        const filledShares = brokerEventQuantityShares(
            row.cumulative_deal_quantity,
            row.quantity_unit,
            payload.order.contractUnit,
            'good-till reconciled fill quantity',
        );
        const cancelledShares = brokerEventQuantityShares(
            row.cumulative_cancel_quantity,
            row.quantity_unit,
            payload.order.contractUnit,
            'good-till reconciled cancel quantity',
        );
        const remainingShares = brokerEventQuantityShares(
            row.remaining_quantity,
            row.quantity_unit,
            payload.order.contractUnit,
            'good-till reconciled remaining quantity',
        );
        if (
            orderShares !== payload.order.baseShares ||
            filledShares + cancelledShares + remainingShares !== orderShares
        ) {
            throw new Error('good-till reconciliation quantity is inconsistent');
        }
        const terminal = ['Filled', 'Cancelled', 'Inactive', 'Failed'].includes(
            row.status,
        );
        if (!terminal) {
            const settlement = projectGoodTillReconciliationSettlement({
                brokerStatus: row.status,
                cancelledShares,
                confirmedFilledSharesBefore: row.confirmed_filled_shares,
                filledShares,
                intentState: row.intent_state,
                orderShares,
                remainingShares,
                targetShares: row.target_shares,
                timeInForce: payload.order.timeInForce,
            });
            const nextState = settlement.dailyState;
            if (row.daily_state !== nextState) {
                const updated = database.prepare(`
                    UPDATE good_till_progress_heads
                       SET daily_state=?, last_reconciliation_hash=?,
                           updated_at_epoch_ms=?, revision=revision+1
                     WHERE strategy_id=? AND revision=?
                `).run(
                    nextState,
                    projection.evidenceSha256,
                    now,
                    row.strategy_id,
                    row.revision,
                );
                if (Number(updated.changes) !== 1) {
                    throw new Error('good-till working-state update lost its CAS');
                }
            }
            blockedCount += 1;
            continue;
        }
        const correlations = database.prepare(`
            SELECT correlation_id, broker_order_id
              FROM broker_correlations
             WHERE intent_id=? AND broker_order_id IS NOT NULL
             ORDER BY correlation_id
        `).all(row.active_intent_id);
        if (correlations.length === 0) continue;
        if (correlations.length !== 1) {
            throw new Error('good-till terminal reconciliation is not uniquely correlated');
        }
        const brokerOrder = database.prepare(`
            SELECT * FROM broker_orders WHERE broker_order_id=?
        `).get(correlations[0].broker_order_id);
        if (
            !brokerOrder ||
            brokerOrder.intent_id !== row.active_intent_id ||
            projection.workingOrders.some(
                (order) => order.brokerOrderId === brokerOrder.broker_order_id,
            )
        ) {
            throw new Error(
                'good-till terminal reconciliation conflicts with the complete working set',
            );
        }
        const settlementHash = sha256Canonical(
            {
                schemaVersion: 'smart-order-good-till-settlement/2026-08-21.1',
                intentId: row.active_intent_id,
                brokerOrderId: brokerOrder.broker_order_id,
                brokerCorrelationId: correlations[0].correlation_id,
                brokerEvidenceHash: row.broker_evidence_hash,
                brokerStatus: row.status,
                filledShares,
                cancelledShares,
                tradeDate: row.active_trade_date,
            },
            'good-till terminal settlement',
        );
        if (
            row.daily_state === 'terminal_consumed' &&
            row.last_reconciliation_hash === settlementHash
        ) {
            continue;
        }
        const settlement = projectGoodTillReconciliationSettlement({
            brokerStatus: row.status,
            cancelledShares,
            confirmedFilledSharesBefore: row.confirmed_filled_shares,
            filledShares,
            intentState: row.intent_state,
            orderShares,
            remainingShares,
            targetShares: row.target_shares,
            timeInForce: payload.order.timeInForce,
        });
        if (row.active_accounted_filled_shares !== 0) {
            throw new Error('good-till fill was already accounted with different evidence');
        }
        const confirmedFilledShares = settlement.confirmedFilledShares;
        const completed = settlement.dailyState === 'completed';
        const progressUpdate = database.prepare(`
            UPDATE good_till_progress_heads
               SET confirmed_filled_shares=?, remaining_target_shares=?,
                   daily_state=?, active_trade_date=?, active_activation_id=?,
                   active_intent_id=?, active_accounted_filled_shares=?,
                   last_reconciliation_hash=?, updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE strategy_id=? AND revision=?
        `).run(
            confirmedFilledShares,
            settlement.remainingTargetShares,
            settlement.dailyState,
            completed ? null : row.active_trade_date,
            completed ? null : row.active_activation_id,
            completed ? null : row.active_intent_id,
            completed ? 0 : filledShares,
            settlementHash,
            now,
            row.strategy_id,
            row.revision,
        );
        if (Number(progressUpdate.changes) !== 1) {
            throw new Error('good-till settlement progress lost its CAS');
        }
        const brokerState = {
            Filled: 'filled',
            Cancelled: 'cancelled',
            Inactive: 'inactive',
            Failed: 'failed',
        }[row.status];
        if (!BROKER_ORDER_TERMINAL_STATES.has(brokerOrder.state)) {
            const updated = database.prepare(`
                UPDATE broker_orders
                   SET state=?, filled_shares=?, remaining_shares=0,
                       evidence_hash=?, updated_at_epoch_ms=?,
                       terminal_at_epoch_ms=?, revision=revision+1
                 WHERE broker_order_id=? AND revision=?
                   AND state NOT IN ('filled','cancelled','failed','inactive')
            `).run(
                brokerState,
                filledShares,
                settlementHash,
                now,
                now,
                brokerOrder.broker_order_id,
                brokerOrder.revision,
            );
            if (Number(updated.changes) !== 1) {
                throw new Error('good-till broker order settlement lost its CAS');
            }
        } else if (
            brokerOrder.state !== brokerState ||
            brokerOrder.filled_shares !== filledShares ||
            brokerOrder.remaining_shares !== 0
        ) {
            throw new Error('good-till broker order replay is inconsistent');
        }
        if (!['terminal', 'cancelled_proven_unsent'].includes(row.intent_state)) {
            const intentUpdate = database.prepare(`
                UPDATE order_intents
                   SET state='terminal', terminal_outcome=?,
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE intent_id=? AND revision=?
                   AND state NOT IN ('terminal','cancelled_proven_unsent')
            `).run(
                `good_till_${row.status.toLowerCase()}_reconciled`,
                now,
                now,
                row.active_intent_id,
                row.intent_revision,
            );
            if (Number(intentUpdate.changes) !== 1) {
                throw new Error('good-till intent settlement lost its CAS');
            }
        }
        if (!['filled', 'failed', 'cancelled'].includes(row.activation_state)) {
            const activationUpdate = database.prepare(`
                UPDATE activations
                   SET state=?, updated_at_epoch_ms=?, revision=revision+1
                 WHERE activation_id=? AND revision=?
            `).run(
                    settlement.activationState,
                now,
                row.active_activation_id,
                row.activation_revision,
            );
            if (Number(activationUpdate.changes) !== 1) {
                throw new Error('good-till activation settlement lost its CAS');
            }
        }
        if (!['consumed', 'released'].includes(row.reservation_state)) {
            const reservationUpdate = database.prepare(`
                UPDATE entry_exposure_reservations
                   SET state=?, updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE reservation_id=? AND revision=?
                   AND state IN ('reserved','partially_consumed','unknown')
            `).run(
                settlement.reservationState,
                now,
                now,
                row.reservation_id,
                row.reservation_revision,
            );
            if (Number(reservationUpdate.changes) !== 1) {
                throw new Error('good-till reservation settlement lost its CAS');
            }
        }
        if (completed) {
            const strategyUpdate = database.prepare(`
                UPDATE strategies SET state='completed', updated_at_epoch_ms=?,
                       terminal_at_epoch_ms=?, revision=revision+1
                 WHERE strategy_id=? AND state='monitoring' AND revision=?
            `).run(now, now, row.strategy_id, row.strategy_revision);
            if (Number(strategyUpdate.changes) !== 1) {
                throw new Error('good-till completion lost its strategy CAS');
            }
        }
        advanceLifecycleSideEffectRevision(database);
        insertTransitionJournalEvent(database, {
            entityKind: 'strategy',
            entityId: row.strategy_id,
            revision: row.strategy_revision + (completed ? 1 : 0),
            reasonCode: 'BROKER_FINAL_EVIDENCE_APPLIED',
            summaryCode: completed
                ? 'good_till_target_completed'
                : 'good_till_daily_activation_consumed',
            nowEpochMs: now,
            payloadHash: settlementHash,
            eventSuffix: `good-till-${row.active_trade_date}`,
        });
        settledCount += 1;
    }
    return Object.freeze({ settledCount, blockedCount });
}

function recordAccountReconciliation(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'apiGeneration',
            'expectedFixedAccountCount',
            'identityAdmission',
            'nowEpochMs',
            'reconciliation',
            'runtimeEpochId',
            'senderFence',
        ])
    ) {
        throw new TypeError('account reconciliation input schema is invalid');
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const now = safeInteger(input.nowEpochMs, 'accountReconciliation.nowEpochMs');
    const expectedFixedAccountCount = safeInteger(
        input.expectedFixedAccountCount,
        'accountReconciliation.expectedFixedAccountCount',
        { minimum: 1 },
    );
    if (expectedFixedAccountCount > 32) {
        throw new TypeError('account reconciliation fixed-account count exceeds its bound');
    }
    const projection = canonicalReconciliationProjection(input.reconciliation);
    if (
        projection.externalSellClaimCandidates === undefined ||
        projection.fullDayTotals === undefined ||
        projection.reconciliationGeneration === undefined
    ) {
        throw new TypeError('account reconciliation durable projection is incomplete');
    }
    return transaction(database, () => {
        const runtime = database.prepare(`
            SELECT state, revision FROM runtime_epochs
             WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
        `).get(runtimeEpochId, senderFence, apiGeneration);
        if (!runtime || !['reconciling', 'ready'].includes(runtime.state)) {
            throw new Error('account reconciliation requires the current Runtime observer');
        }
        if (projection.asOfEpochMs > now) {
            throw new Error('account reconciliation cannot come from the future');
        }
        const identityAdmission = verifyAuthenticatedIdentityAdmission(
            database,
            input.identityAdmission,
            {
            accountBrokerRef: projection.account.brokerId,
            accountIdRef: projection.account.accountId,
            identityGroupId: boundedToken(
                input.identityAdmission?.identityGroupId,
                'accountReconciliation.identityGroupId',
            ),
            },
        );
        const expectedAccountScopeSha256 = `sha256:${createHash('sha256')
            .update(
                `smart-order-reconciliation-account\u001f${stableCanonicalJson([
                    projection.account.brokerId,
                    projection.account.accountId,
                    'S',
                ])}`,
            )
            .digest('hex')}`;
        const durableExternalCandidates = [];
        for (const candidate of projection.externalSellClaimCandidates) {
            if (candidate.accountScopeSha256 !== expectedAccountScopeSha256) {
                throw new Error('external sell claim candidate account scope mismatch');
            }
            const projectedOrder = projection.workingOrders.find(
                (order) => order.brokerOrderId === candidate.brokerOrderId,
            );
            const projectedPosition = projection.positions.find(
                (position) => position.contractKey === candidate.contractKey,
            );
            const expectedCandidateId = `external-sell-claim:${sha256Canonical(
                [
                    expectedAccountScopeSha256,
                    projection.tradeDate,
                    candidate.brokerOrderId,
                    candidate.contractKey,
                ],
                'external sell claim candidate ID',
            ).slice(7)}`;
            if (
                candidate.candidateId !== expectedCandidateId ||
                candidate.evidenceSha256 !== projection.evidenceSha256 ||
                !projectedOrder ||
                projectedOrder.origin !== 'external' ||
                projectedOrder.side !== 'Sell' ||
                projectedOrder.contractKey !== candidate.contractKey ||
                projectedOrder.remainingShares !== candidate.quantityShares ||
                !projectedPosition ||
                projectedPosition.positionLineageId !==
                    candidate.positionLineageId
            ) {
                throw new Error(
                    'external sell claim candidate does not match the complete working set',
                );
            }
            const matchingOrder = database
                .prepare(`
                    SELECT orders.intent_id, intents.account_broker_ref,
                           intents.account_id_ref, intents.contract_key,
                           intents.side
                      FROM broker_orders AS orders
                      JOIN order_intents AS intents USING(intent_id)
                     WHERE orders.broker_order_id=?
                `)
                .get(candidate.brokerOrderId);
            if (matchingOrder) {
                if (
                    matchingOrder.account_broker_ref !==
                        projection.account.brokerId ||
                    matchingOrder.account_id_ref !==
                        projection.account.accountId ||
                    matchingOrder.contract_key !== candidate.contractKey ||
                    matchingOrder.side !== 'Sell'
                ) {
                    throw new Error(
                        'working order conflicts with its durable Runtime scope',
                    );
                }
                continue;
            }
            durableExternalCandidates.push(candidate);
        }
        const projectedExternalSellIds = projection.workingOrders
            .filter(
                (order) => order.origin === 'external' && order.side === 'Sell',
            )
            .map((order) => order.brokerOrderId)
            .sort();
        const candidateBrokerOrderIds =
            projection.externalSellClaimCandidates
                .map((candidate) => candidate.brokerOrderId)
                .sort();
        if (
            stableCanonicalJson(projectedExternalSellIds) !==
            stableCanonicalJson(candidateBrokerOrderIds)
        ) {
            throw new Error(
                'external sell claim candidates do not cover the complete working set',
            );
        }
        const headRevision = upsertAccountReconciliationHead(
            database,
            projection,
            now,
        );
        replaceAccountReconciliationPositions(
            database,
            projection,
            headRevision,
            now,
        );
        invalidateCanonicalConfirmationsForAccountHead(database, {
            projection,
            accountHeadRevision: headRevision,
            nowEpochMs: now,
        });
        const dealLedgerHash = replaceCanonicalPnlDeals(
            database,
            projection,
            now,
        );
        const pnlAccountHeadRevision = upsertCanonicalPnlAccountHead(database, {
            projection,
            identityAdmission,
            runtimeEpochId,
            apiGeneration,
            dealLedgerHash,
            now,
        });
        setRepositoryMeta(
            database,
            `${ACCOUNT_RECONCILIATION_TOTALS_META_PREFIX}${createHash('sha256')
                .update(
                    `${expectedAccountScopeSha256}\u001f${projection.tradeDate}`,
                )
                .digest('hex')}`,
            canonicalJson({
                schemaVersion:
                    'smart-order-account-reconciliation-totals/2026-08-13.1',
                accountScopeSha256: expectedAccountScopeSha256,
                tradeDate: projection.tradeDate,
                asOfEpochMs: projection.asOfEpochMs,
                sourceRevision: projection.sourceRevision,
                snapshotSha256: projection.snapshotSha256,
                evidenceSha256: projection.evidenceSha256,
                fullDayTotals: projection.fullDayTotals,
            }),
        );
        const candidatesByContract = new Map();
        for (const position of projection.positions) {
            candidatesByContract.set(position.contractKey, []);
        }
        for (const candidate of durableExternalCandidates) {
            const entries = candidatesByContract.get(candidate.contractKey) ?? [];
            entries.push(candidate);
            candidatesByContract.set(candidate.contractKey, entries);
        }
        const currentCandidateIds = new Set(
            durableExternalCandidates.map(
                (candidate) => candidate.candidateId,
            ),
        );
        const priorBindings = database.prepare(`
            SELECT bindings.exit_claim_id, claims.state, claims.revision
              FROM exit_claim_visibility_bindings AS bindings
              JOIN exit_claims AS claims USING(exit_claim_id)
             WHERE bindings.account_broker_ref=?
               AND bindings.account_id_ref=?
               AND bindings.trade_date=?
               AND bindings.binding_kind='external_projection'
        `).all(
            projection.account.brokerId,
            projection.account.accountId,
            projection.tradeDate,
        );
        for (const prior of priorBindings) {
            if (
                currentCandidateIds.has(prior.exit_claim_id) ||
                ['consumed', 'released'].includes(prior.state)
            ) {
                continue;
            }
            const release = database.prepare(`
                UPDATE exit_claims
                   SET state='released', updated_at_epoch_ms=?,
                       terminal_at_epoch_ms=?, revision=revision+1
                 WHERE exit_claim_id=? AND revision=?
                   AND state IN ('broker_working','unknown')
            `).run(now, now, prior.exit_claim_id, prior.revision);
            if (Number(release.changes) !== 1) {
                throw new Error('external sell claim release lost its CAS');
            }
        }
        for (const [contractKey, candidates] of candidatesByContract) {
            const position = projection.positions.find(
                (entry) => entry.contractKey === contractKey,
            );
            if (!position) {
                throw new Error('external sell visibility position is missing');
            }
            const claimedShares = candidates.reduce(
                (sum, candidate) =>
                    addExposureInteger(
                        sum,
                        candidate.quantityShares,
                        'external reconciliation claimed shares',
                    ),
                0,
            );
            if (claimedShares > position.quantityShares) {
                throw new Error(
                    'external working sells exceed the reconciled position',
                );
            }
            const workingSetHash = canonicalExternalWorkingSet(
                candidates.map((candidate) => ({
                    allocationStartShare: 0,
                    evidenceHash: candidate.evidenceSha256,
                    exitClaimId: candidate.candidateId,
                    positionLineageId: candidate.positionLineageId,
                    quantityShares: candidate.quantityShares,
                    remainderGeneration: 0,
                    state: 'broker_working',
                })),
                'account reconciliation external working set',
            ).workingSetHash;
            const currentVisibility = database.prepare(`
                SELECT revision FROM external_sell_visibility_heads
                 WHERE account_broker_ref=? AND account_id_ref=?
                   AND trade_date=? AND contract_key=?
            `).get(
                projection.account.brokerId,
                projection.account.accountId,
                projection.tradeDate,
                contractKey,
            );
            const nextVisibilityRevision = currentVisibility
                ? currentVisibility.revision + 1
                : 0;
            if (currentVisibility) {
                const update = database.prepare(`
                    UPDATE external_sell_visibility_heads
                       SET source_revision=?, source_sequence=?,
                           source_evidence_hash=?, position_revision=?,
                           position_shares=?, working_set_hash=?,
                           collection_complete=1, observed_at_epoch_ms=?,
                           valid_until_epoch_ms=?, updated_at_epoch_ms=?,
                           revision=?
                     WHERE account_broker_ref=? AND account_id_ref=?
                       AND trade_date=? AND contract_key=? AND revision=?
                `).run(
                    projection.sourceRevision,
                    projection.reconciliationGeneration,
                    projection.evidenceSha256,
                    projection.sourceRevision,
                    position.quantityShares,
                    workingSetHash,
                    projection.asOfEpochMs,
                    projection.asOfEpochMs + 5_000,
                    now,
                    nextVisibilityRevision,
                    projection.account.brokerId,
                    projection.account.accountId,
                    projection.tradeDate,
                    contractKey,
                    currentVisibility.revision,
                );
                if (Number(update.changes) !== 1) {
                    throw new Error('external sell visibility update lost its CAS');
                }
            } else {
                database.prepare(`
                    INSERT INTO external_sell_visibility_heads(
                        account_broker_ref, account_id_ref, trade_date,
                        contract_key, source_revision, source_sequence,
                        source_evidence_hash, position_revision,
                        position_shares, working_set_hash, collection_complete,
                        observed_at_epoch_ms, valid_until_epoch_ms,
                        updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, 0)
                `).run(
                    projection.account.brokerId,
                    projection.account.accountId,
                    projection.tradeDate,
                    contractKey,
                    projection.sourceRevision,
                    projection.reconciliationGeneration,
                    projection.evidenceSha256,
                    projection.sourceRevision,
                    position.quantityShares,
                    workingSetHash,
                    projection.asOfEpochMs,
                    projection.asOfEpochMs + 5_000,
                    now,
                );
            }
            for (const candidate of candidates) {
                const stored = database
                    .prepare('SELECT * FROM exit_claims WHERE exit_claim_id=?')
                    .get(candidate.candidateId);
                if (!stored) {
                    database.prepare(`
                        INSERT INTO exit_claims(
                            exit_claim_id, obligation_id, intent_id,
                            external_lineage, account_broker_ref, account_id_ref,
                            contract_key, position_lineage_id,
                            remainder_generation, allocation_start_share,
                            quantity_shares, state, evidence_hash,
                            created_at_epoch_ms, updated_at_epoch_ms, revision
                        ) VALUES (?, NULL, NULL, 1, ?, ?, ?, ?, 0, 0, ?,
                                  'broker_working', ?, ?, ?, 0)
                    `).run(
                        candidate.candidateId,
                        projection.account.brokerId,
                        projection.account.accountId,
                        contractKey,
                        candidate.positionLineageId,
                        candidate.quantityShares,
                        candidate.evidenceSha256,
                        now,
                        now,
                    );
                } else if (
                    stored.external_lineage !== 1 ||
                    stored.account_broker_ref !== projection.account.brokerId ||
                    stored.account_id_ref !== projection.account.accountId ||
                    stored.contract_key !== contractKey ||
                    stored.position_lineage_id !== candidate.positionLineageId ||
                    stored.state !== 'broker_working'
                ) {
                    throw new Error('external sell claim durable lineage conflicts');
                } else if (
                    stored.quantity_shares !== candidate.quantityShares ||
                    stored.evidence_hash !== candidate.evidenceSha256
                ) {
                    const updateClaim = database.prepare(`
                        UPDATE exit_claims
                           SET quantity_shares=?, evidence_hash=?,
                               updated_at_epoch_ms=?, revision=revision+1
                         WHERE exit_claim_id=? AND revision=?
                           AND state='broker_working'
                    `).run(
                        candidate.quantityShares,
                        candidate.evidenceSha256,
                        now,
                        candidate.candidateId,
                        stored.revision,
                    );
                    if (Number(updateClaim.changes) !== 1) {
                        throw new Error('external sell claim update lost its CAS');
                    }
                }
                database.prepare(`
                    INSERT INTO exit_claim_visibility_bindings(
                        exit_claim_id, account_broker_ref, account_id_ref,
                        trade_date, contract_key, source_revision,
                        source_sequence, source_evidence_hash,
                        position_revision, position_shares, working_set_hash,
                        binding_kind, visibility_head_revision,
                        created_at_epoch_ms, updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                              'external_projection', ?, ?, ?, 0)
                    ON CONFLICT(exit_claim_id) DO UPDATE SET
                        source_revision=excluded.source_revision,
                        source_sequence=excluded.source_sequence,
                        source_evidence_hash=excluded.source_evidence_hash,
                        position_revision=excluded.position_revision,
                        position_shares=excluded.position_shares,
                        working_set_hash=excluded.working_set_hash,
                        visibility_head_revision=excluded.visibility_head_revision,
                        updated_at_epoch_ms=excluded.updated_at_epoch_ms,
                        revision=exit_claim_visibility_bindings.revision+1
                `).run(
                    candidate.candidateId,
                    projection.account.brokerId,
                    projection.account.accountId,
                    projection.tradeDate,
                    contractKey,
                    projection.sourceRevision,
                    projection.reconciliationGeneration,
                    projection.evidenceSha256,
                    projection.sourceRevision,
                    position.quantityShares,
                    workingSetHash,
                    nextVisibilityRevision,
                    now,
                    now,
                );
            }
        }
        const protectionOcoSettledCount = settleProtectionOcoFromReconciliation(
            database,
            { projection, now },
        );
        const goodTillSettlement = settleGoodTillFromReconciliation(database, {
            projection,
            now,
        });
        const parentChildSettlement = settleParentChildFromReconciliation(
            database,
            { projection, now },
        );
        const protectionDrift = reconcileUntriggeredProtectionPositionDrift(
            database,
            { projection, now },
        );
        const identityBindings = database
            .prepare(`
                SELECT value FROM repository_meta
                 WHERE key LIKE ? ORDER BY key
            `)
            .all(`${IDENTITY_ACCOUNT_BINDING_META_PREFIX}%`)
            .map((row) => JSON.parse(row.value));
        if (identityBindings.length > expectedFixedAccountCount) {
            throw new Error('authenticated fixed-account set exceeds reconciliation scope');
        }
        const roundHeads = database.prepare(`
            SELECT account_broker_ref, account_id_ref, snapshot_hash,
                   event_stream_watermark_hash
              FROM account_reconciliation_heads
             WHERE trade_date=? AND event_stream_watermark_hash=?
             ORDER BY account_broker_ref, account_id_ref
        `).all(
            projection.tradeDate,
            projection.eventStreamWatermarkSha256,
        );
        const roundScopes = new Set(
            roundHeads.map((head) => `sha256:${createHash('sha256')
                .update(
                    `${head.account_broker_ref}\u001f${head.account_id_ref}`,
                )
                .digest('hex')}`),
        );
        const accountReconciliationCurrent =
            identityBindings.length === expectedFixedAccountCount &&
            roundHeads.length === expectedFixedAccountCount &&
            identityBindings.every((binding) =>
                roundScopes.has(binding.accountScopeSha256),
            );
        const pnlIdentityHead = rebuildCanonicalPnlIdentityHead(database, {
            identityGroupId: identityAdmission.identityGroupId,
            tradeDate: projection.tradeDate,
            eventStreamWatermarkSha256:
                projection.eventStreamWatermarkSha256,
            expectedFixedAccountCount,
            runtimeEpochId,
            apiGeneration,
            now,
        });
        const canonicalPnlCurrent =
            accountReconciliationCurrent && pnlIdentityHead !== null;
        const runtimeRiskPolicyCurrent =
            canonicalPnlCurrent &&
            (configuredTestExposureArbiterHeads.length > 0 ||
                rebuildRuntimeRiskExposureHeads(database, {
                    identityGroupId: identityAdmission.identityGroupId,
                    tradeDate: projection.tradeDate,
                    eventStreamWatermarkSha256:
                        projection.eventStreamWatermarkSha256,
                    expectedFixedAccountCount,
                    now,
                }));
        const evidenceHash = accountReconciliationCurrent
            ? sha256Canonical(
                  {
                      eventStreamWatermarkSha256:
                          projection.eventStreamWatermarkSha256,
                      snapshotHashes: roundHeads.map(
                          (head) => head.snapshot_hash,
                      ),
                      tradeDate: projection.tradeDate,
                  },
                  'durable account reconciliation evidence',
              )
            : null;
        const runtimeUpdate = database.prepare(`
            UPDATE runtime_epochs
               SET reconciliation_evidence_hash=?, revision=revision+1
             WHERE runtime_epoch_id=? AND revision=?
        `).run(evidenceHash, runtimeEpochId, runtime.revision);
        if (Number(runtimeUpdate.changes) !== 1) {
            throw new Error('account reconciliation Runtime update lost its CAS');
        }
        const journalEvidenceHash =
            evidenceHash ??
            sha256Canonical(
                {
                    account: expectedAccountScopeSha256,
                    eventStreamWatermarkSha256:
                        projection.eventStreamWatermarkSha256,
                    snapshotSha256: projection.snapshotSha256,
                },
                'partial account reconciliation evidence',
            );
        advanceLifecycleSideEffectRevision(database);
        insertTransitionJournalEvent(database, {
            entityKind: 'runtime_epoch',
            entityId: runtimeEpochId,
            revision: runtime.revision + 1,
            reasonCode: 'ACCOUNT_RECONCILIATION_RECORDED',
            summaryCode: 'account_reconciliation_complete',
            nowEpochMs: now,
            payloadHash: journalEvidenceHash,
            eventSuffix: `account-reconciliation-${headRevision}`,
        });
        const protectedEntryMaterializationRows = database.prepare(`
            SELECT intents.intent_id, intents.payload_json,
                   broker_heads.cumulative_deal_quantity,
                   broker_heads.remaining_quantity,
                   broker_heads.quantity_unit,
                   fills.intent_id AS fill_intent_id,
                   fills.cumulative_filled_shares,
                   fills.remaining_entry_shares
              FROM order_intents AS intents
              JOIN pending_protection_commitments AS commitments
                ON commitments.entry_intent_id=intents.intent_id
              JOIN entry_exposure_reservations AS reservations
                ON reservations.intent_id=intents.intent_id
              JOIN broker_event_heads AS broker_heads
                ON broker_heads.intent_id=intents.intent_id
         LEFT JOIN protected_entry_fill_heads AS fills
                ON fills.intent_id=intents.intent_id
             WHERE intents.operation_kind='place' AND intents.side='Buy'
               AND intents.account_broker_ref=? AND intents.account_id_ref=?
               AND intents.trade_date=?
               AND reservations.state IN (
                   'reserved','partially_consumed','unknown'
               )
             ORDER BY intents.intent_id
             LIMIT 257
        `).all(
            projection.account.brokerId,
            projection.account.accountId,
            projection.tradeDate,
        );
        const rowsByIntent = new Map();
        for (const row of protectedEntryMaterializationRows) {
            const rows = rowsByIntent.get(row.intent_id) ?? [];
            rows.push(row);
            rowsByIntent.set(row.intent_id, rows);
        }
        if (
            protectedEntryMaterializationRows.length > 256 ||
            rowsByIntent.size > 128
        ) {
            throw new Error(
                'protected entry materialization candidate set exceeds its bound',
            );
        }
        const protectedEntryMaterializationIntentIds = Object.freeze(
            [...rowsByIntent]
                .filter(([, rows]) => {
                    if (rows.length !== 1 || rows[0].fill_intent_id === null) {
                        return true;
                    }
                    try {
                        const protectedIntent =
                            canonicalProtectedEntryIntentPayload(
                                JSON.parse(rows[0].payload_json),
                            );
                        const contractUnit = canonicalProtectedEntryPlan(
                            protectedIntent.payload.protectionPlan,
                        ).plan.entryOrder.contractUnit;
                        return (
                            brokerEventQuantityShares(
                                rows[0].cumulative_deal_quantity,
                                rows[0].quantity_unit,
                                contractUnit,
                                'materialization candidate cumulative fill',
                            ) !== rows[0].cumulative_filled_shares ||
                            brokerEventQuantityShares(
                                rows[0].remaining_quantity,
                                rows[0].quantity_unit,
                                contractUnit,
                                'materialization candidate remaining entry',
                            ) !== rows[0].remaining_entry_shares
                        );
                    } catch {
                        return true;
                    }
                })
                .map(([intentId]) => intentId),
        );
        return Object.freeze({
            state: 'recorded',
            accountReconciliationCurrent,
            externalSellClaimCount:
                durableExternalCandidates.length,
            fullDayTotals: projection.fullDayTotals,
            headRevision,
            canonicalPnlCurrent,
            pnlAccountHeadRevision,
            pnlIdentityHead: pnlIdentityHead
                ? Object.freeze({
                      accountSetRevision:
                          pnlIdentityHead.accountSetRevision,
                      asOfEpochMs: pnlIdentityHead.asOfEpochMs,
                      policyDefinitionSha256:
                          SMART_ORDER_CANONICAL_PNL_POLICY_DEFINITION_SHA256,
                      policyRevision:
                          SMART_ORDER_CANONICAL_PNL_POLICY_REVISION,
                      totals: pnlIdentityHead.totals,
                      validUntilEpochMs:
                          pnlIdentityHead.validUntilEpochMs,
                  })
                : null,
            runtimeState: runtime.state,
            runtimeRevision: runtime.revision + 1,
            runtimeReadinessContribution:
                accountReconciliationCurrent &&
                canonicalPnlCurrent &&
                runtimeRiskPolicyCurrent,
            runtimeRiskPolicyCurrent,
            protectedEntryMaterializationIntentIds,
            protectionOcoSettledCount,
            goodTillSettledCount: goodTillSettlement.settledCount,
            goodTillBlockedCount: goodTillSettlement.blockedCount,
            parentChildSettledCount: parentChildSettlement.settledCount,
            parentChildBlockedCount: parentChildSettlement.blockedCount,
            ...protectionDrift,
            brokerWriteAuthority: false,
        });
    });
}

function protectedEntryReconciliationRequired(
    database,
    { intent, commitment, obligation, reservation, runtimeEpochId, reason, now },
) {
    const runtime = database
        .prepare('SELECT state, revision FROM runtime_epochs WHERE runtime_epoch_id=?')
        .get(runtimeEpochId);
    if (!runtime || !['ready', 'reconciling'].includes(runtime.state)) {
        throw new Error(
            'protected entry reconciliation lost its current Runtime observer',
        );
    }
    let runtimeRevision = runtime.revision;
    let transitioned = false;
    if (runtime.state === 'ready') {
        const runtimeUpdate = database
            .prepare(`
                UPDATE runtime_epochs
                   SET state='reconciling', reconciliation_evidence_hash=NULL,
                       revision=revision+1
                 WHERE runtime_epoch_id=? AND state='ready' AND revision=?
            `)
            .run(runtimeEpochId, runtime.revision);
        if (Number(runtimeUpdate.changes) !== 1) {
            throw new Error(
                'protected entry reconciliation runtime transition lost its CAS',
            );
        }
        runtimeRevision += 1;
        transitioned = true;
    }
    const cancelLineage = protectedEntryCancelControlLineage(
        database,
        intent.intent_id,
    );
    const strategy = database
        .prepare('SELECT state, revision FROM strategies WHERE strategy_id=?')
        .get(intent.strategy_id);
    if (
        !strategy ||
        ['completed', 'cancelled', 'expired'].includes(strategy.state)
    ) {
        throw new Error(
            'protected entry reconciliation strategy transition is unavailable',
        );
    }
    if (
        cancelLineage &&
        ['dispatching', 'acknowledged', 'reconciling', 'unknown'].includes(
            cancelLineage.control.state,
        )
    ) {
        const existingResolution = database
            .prepare(
                'SELECT state FROM resolution_cases WHERE resolution_case_id=?',
            )
            .get(cancelLineage.resolutionCaseId);
        if (existingResolution) {
            if (
                existingResolution.state !== 'open' ||
                strategy.state !== 'manual_intervention'
            ) {
                throw new Error(
                    'protected entry cancel reconciliation replay is inconsistent',
                );
            }
            return Object.freeze({
                state: 'manual_intervention',
                reason: 'protected_entry_cancel_outcome_not_unique',
                intentId: intent.intent_id,
                runtimeState: 'reconciling',
                runtimeRevision,
                automaticRetryAllowed: false,
                replayed: true,
                brokerWriteAuthority: false,
            });
        }
        const manual = transitionProtectedEntryTriggerToManual(database, {
            blockerId: cancelLineage.blockerId,
            deniedBy: [],
            entry: cancelLineage.entry,
            manualReason: 'entry_cancel_result_unknown',
            now,
            orders: cancelLineage.orders,
            resolutionCaseId: cancelLineage.resolutionCaseId,
            triggerSelectionHash:
                cancelLineage.payload.triggerSelectionHash,
        });
        insertTransitionJournalEvent(database, {
            entityKind: 'runtime_epoch',
            entityId: runtimeEpochId,
            revision: runtimeRevision,
            reasonCode: 'PROTECTED_ENTRY_RECONCILIATION_REQUIRED',
            summaryCode: 'protected_entry_cancel_outcome_not_unique',
            nowEpochMs: now,
            payloadHash: cancelLineage.control.payload_hash,
            eventSuffix: `protected-entry-cancel-${cancelLineage.control.intent_id}`,
        });
        return Object.freeze({
            ...manual,
            state: 'manual_intervention',
            reason: 'protected_entry_cancel_outcome_not_unique',
            intentId: intent.intent_id,
            runtimeState: 'reconciling',
            runtimeRevision,
            automaticRetryAllowed: false,
            brokerWriteAuthority: false,
        });
    }
    if (strategy.state !== 'recovery') {
        const strategyUpdate = database
            .prepare(`
                UPDATE strategies SET state='recovery', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE strategy_id=? AND state=? AND revision=?
            `)
            .run(
                now,
                intent.strategy_id,
                strategy.state,
                strategy.revision,
            );
        if (Number(strategyUpdate.changes) !== 1) {
            throw new Error(
                'protected entry reconciliation strategy transition lost its CAS',
            );
        }
        transitioned = true;
    }
    if (
        reservation &&
        !['unknown', 'consumed', 'released'].includes(reservation.state)
    ) {
        const reservationUpdate = database
            .prepare(`
                UPDATE entry_exposure_reservations
                   SET state='unknown', updated_at_epoch_ms=?, revision=revision+1
                 WHERE reservation_id=? AND revision=?
            `)
            .run(now, reservation.reservation_id, reservation.revision);
        if (Number(reservationUpdate.changes) !== 1) {
            throw new Error(
                'protected entry reconciliation reservation transition lost its CAS',
            );
        }
        transitioned = true;
    }
    if (!transitioned) {
        return Object.freeze({
            state: 'reconciliation_required',
            reason,
            intentId: intent.intent_id,
            runtimeState: 'reconciling',
            runtimeRevision,
            automaticRetryAllowed: false,
            replayed: true,
            brokerWriteAuthority: false,
        });
    }
    const evidenceHash = sha256Canonical(
        {
            intentId: intent.intent_id,
            commitmentId: commitment.commitment_id,
            obligationId: obligation.obligation_id,
            reason,
        },
        'protected entry reconciliation blocker',
    );
    insertTransitionJournalEvent(database, {
        entityKind: 'runtime_epoch',
        entityId: runtimeEpochId,
        revision: runtimeRevision,
        reasonCode: 'PROTECTED_ENTRY_RECONCILIATION_REQUIRED',
        summaryCode: reason,
        nowEpochMs: now,
        payloadHash: evidenceHash,
        eventSuffix: `protected-entry-${intent.intent_id}`,
    });
    return Object.freeze({
        state: 'reconciliation_required',
        reason,
        intentId: intent.intent_id,
        runtimeState: 'reconciling',
        runtimeRevision,
        automaticRetryAllowed: false,
        brokerWriteAuthority: false,
    });
}

function protectedEntryCancelControlLineage(database, entryIntentId) {
    const rows = database.prepare(`
        SELECT controls.*, activations.state AS cancel_activation_state,
               activations.revision AS cancel_activation_revision,
               targets.intent_id AS target_intent_id,
               targets.state AS target_order_state,
               targets.control_revision AS current_target_control_revision,
               targets.quantity_shares AS target_quantity_shares,
               targets.filled_shares AS target_filled_shares,
               targets.remaining_shares AS target_remaining_shares,
               targets.evidence_hash AS target_evidence_hash,
               targets.revision AS target_order_revision
          FROM order_intents AS controls
          JOIN activations ON activations.activation_id=controls.activation_id
          JOIN broker_orders AS targets
            ON targets.broker_order_id=controls.target_broker_order_id
         WHERE targets.intent_id=?
           AND controls.operation_kind='cancel'
           AND controls.owner_kind='activation'
           AND controls.client_request_id LIKE 'protective-entry-cancel:%'
         ORDER BY controls.intent_id
    `).all(entryIntentId);
    if (rows.length === 0) return null;
    if (rows.length !== 1) {
        throw new Error(
            'protected entry reconciliation found multiple cancel controls',
        );
    }
    const control = rows[0];
    const payload = canonicalIntentPayload(
        control.payload_json,
        'protected entry reconciliation cancel payload',
    );
    if (
        !exactKeys(payload, [
            'brokerOrderId',
            'controlRevision',
            'protectionGroupId',
            'remainderGeneration',
            'schemaVersion',
            'triggerSelectionHash',
        ]) ||
        payload.schemaVersion !==
            PROTECTIVE_ENTRY_CANCEL_INTENT_SCHEMA_VERSION ||
        sha256Canonical(payload, 'protected entry reconciliation cancel payload') !==
            control.payload_hash ||
        payload.brokerOrderId !== control.target_broker_order_id ||
        payload.controlRevision !== control.target_control_revision ||
        control.target_intent_id !== entryIntentId
    ) {
        throw new Error(
            'protected entry reconciliation cancel envelope is not exact',
        );
    }
    const entry = database.prepare(`
        SELECT groups.protection_group_id, groups.state AS group_state,
               groups.current_generation, groups.revision AS group_revision,
               generations.state AS generation_state,
               generations.revision AS generation_revision,
               claims.exit_claim_id, claims.state AS claim_state,
               claims.revision AS claim_revision,
               obligations.obligation_id, obligations.state AS obligation_state,
               obligations.revision AS obligation_revision,
               commitments.entry_intent_id,
               entry_intents.state AS entry_intent_state,
               entry_intents.account_broker_ref,
               entry_intents.account_id_ref, entry_intents.trade_date,
               entry_intents.contract_key,
               strategies.strategy_id, strategies.state AS strategy_state,
               strategies.revision AS strategy_revision
          FROM protection_groups AS groups
          JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
          JOIN exit_claims AS claims
            ON claims.exit_claim_id=groups.exit_claim_id
          JOIN protection_obligations AS obligations
            ON obligations.obligation_id=groups.obligation_id
          JOIN pending_protection_commitments AS commitments
            ON commitments.commitment_id=obligations.commitment_id
          JOIN order_intents AS entry_intents
            ON entry_intents.intent_id=commitments.entry_intent_id
          JOIN strategies ON strategies.strategy_id=obligations.strategy_id
         WHERE groups.protection_group_id=?
           AND generations.remainder_generation=?
    `).get(payload.protectionGroupId, payload.remainderGeneration);
    if (
        !entry ||
        entry.entry_intent_id !== entryIntentId ||
        entry.strategy_id !== control.strategy_id ||
        entry.account_broker_ref !== control.account_broker_ref ||
        entry.account_id_ref !== control.account_id_ref ||
        entry.trade_date !== control.trade_date ||
        entry.contract_key !== control.contract_key
    ) {
        throw new Error(
            'protected entry reconciliation cancel lost its protection lineage',
        );
    }
    const orders = database.prepare(`
        SELECT broker_order_id, state, control_revision, quantity_shares,
               filled_shares, remaining_shares, evidence_hash, revision
          FROM broker_orders
         WHERE intent_id=?
         ORDER BY broker_order_id
    `).all(entryIntentId);
    const resolutionIdentity = sha256Canonical(
        {
            entryIntentId,
            protectionGroupId: payload.protectionGroupId,
            remainderGeneration: payload.remainderGeneration,
            triggerSelectionHash: payload.triggerSelectionHash,
        },
        'protected entry trigger disposition identity',
    ).slice('sha256:'.length);
    return Object.freeze({
        blockerId: `blocker-${resolutionIdentity}`,
        control,
        entry,
        orders,
        payload,
        resolutionCaseId: `resolution-${resolutionIdentity}`,
    });
}

function settleProtectedEntryTerminalReconciliation(
    database,
    {
        commitment,
        cumulativeCancelledShares,
        cumulativeFilledShares,
        head,
        intent,
        now,
        projection,
    },
) {
    if (
        !['Filled', 'Cancelled', 'Inactive', 'Failed'].includes(head.status) ||
        head.remaining_quantity !== 0
    ) {
        return Object.freeze({ settled: false });
    }
    if (
        cumulativeFilledShares + cumulativeCancelledShares !==
        commitment.committed_shares
    ) {
        throw new Error(
            'protected entry terminal reconciliation quantity is incomplete',
        );
    }
    const correlations = database.prepare(`
        SELECT DISTINCT correlations.correlation_id,
               correlations.broker_order_id, correlations.intent_id
          FROM broker_event_records AS events
          JOIN broker_correlation_identifiers AS trade_ids
            ON trade_ids.account_broker_ref=events.account_broker_ref
           AND trade_ids.account_id_ref=events.account_id_ref
           AND trade_ids.trade_date=events.trade_date
           AND trade_ids.contract_key=events.contract_key
           AND trade_ids.side=events.side
           AND trade_ids.identifier_kind='tradeId'
           AND trade_ids.identifier_value=events.trade_id
          JOIN broker_correlation_identifiers AS sequence_ids
            ON sequence_ids.account_broker_ref=events.account_broker_ref
           AND sequence_ids.account_id_ref=events.account_id_ref
           AND sequence_ids.trade_date=events.trade_date
           AND sequence_ids.contract_key=events.contract_key
           AND sequence_ids.side=events.side
           AND sequence_ids.identifier_kind='seqno'
           AND sequence_ids.identifier_value=events.seqno
           AND sequence_ids.correlation_id=trade_ids.correlation_id
           AND sequence_ids.intent_id=trade_ids.intent_id
          JOIN broker_correlations AS correlations
            ON correlations.correlation_id=trade_ids.correlation_id
           AND correlations.intent_id=trade_ids.intent_id
         WHERE events.broker_event_key_hash=?
           AND events.intent_id=?
         ORDER BY correlations.correlation_id
    `).all(head.broker_event_key_hash, intent.intent_id);
    if (correlations.length === 0 || correlations[0]?.broker_order_id === null) {
        return Object.freeze({ settled: false });
    }
    if (correlations.length !== 1) {
        throw new Error(
            'protected entry terminal reconciliation lacks one exact broker order correlation',
        );
    }
    const brokerOrder = database.prepare(`
        SELECT * FROM broker_orders WHERE broker_order_id=?
    `).get(correlations[0].broker_order_id);
    if (
        !brokerOrder ||
        brokerOrder.intent_id !== intent.intent_id ||
        projection.workingOrders.some(
            (order) => order.brokerOrderId === brokerOrder.broker_order_id,
        )
    ) {
        throw new Error(
            'protected entry terminal reconciliation conflicts with the complete working set',
        );
    }
    const brokerState = Object.freeze({
        Filled: 'filled',
        Cancelled: 'cancelled',
        Inactive: 'inactive',
        Failed: 'failed',
    })[head.status];
    const activationState = Object.freeze({
        Filled: 'filled',
        Cancelled: 'cancelled',
        Inactive: 'failed',
        Failed: 'failed',
    })[head.status];
    const terminalOutcome =
        head.status === 'Filled'
            ? 'protected_entry_filled_reconciled'
            : cumulativeFilledShares > 0
              ? 'protected_entry_part_filled_terminal_reconciled'
              : `protected_entry_${brokerState}_reconciled`;
    const settlementHash = sha256Canonical(
        {
            schemaVersion:
                'smart-order-protected-entry-terminal-settlement/2026-08-20.1',
            intentId: intent.intent_id,
            brokerOrderId: brokerOrder.broker_order_id,
            brokerStatus: head.status,
            cumulativeFilledShares,
            cumulativeCancelledShares,
            reconciliationSnapshotHash: projection.snapshotSha256,
            reconciliationEvidenceHash: projection.evidenceSha256,
        },
        'protected entry terminal settlement',
    );
    let transitioned = false;
    let entryIntentRevision = null;
    let cancelIntentRevision = null;
    if (!BROKER_ORDER_TERMINAL_STATES.has(brokerOrder.state)) {
        const brokerOrderUpdate = database.prepare(`
            UPDATE broker_orders
               SET state=?, control_revision=control_revision+1,
                   filled_shares=?, remaining_shares=?, evidence_hash=?,
                   updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                   revision=revision+1
             WHERE broker_order_id=? AND revision=?
               AND state NOT IN ('filled','cancelled','failed','inactive')
        `).run(
            brokerState,
            cumulativeFilledShares,
            0,
            settlementHash,
            now,
            now,
            brokerOrder.broker_order_id,
            brokerOrder.revision,
        );
        if (Number(brokerOrderUpdate.changes) !== 1) {
            throw new Error(
                'protected entry terminal broker order settlement lost its CAS',
            );
        }
        transitioned = true;
    } else if (
        brokerOrder.state !== brokerState ||
        brokerOrder.filled_shares !== cumulativeFilledShares ||
        brokerOrder.remaining_shares !== 0
    ) {
        throw new Error(
            'protected entry terminal broker order replay is inconsistent',
        );
    }
    if (!['terminal', 'cancelled_proven_unsent'].includes(intent.state)) {
        const intentUpdate = database.prepare(`
            UPDATE order_intents
               SET state='terminal', terminal_outcome=?,
                   updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                   revision=revision+1
             WHERE intent_id=? AND revision=?
               AND state NOT IN ('terminal','cancelled_proven_unsent')
        `).run(
            terminalOutcome,
            now,
            now,
            intent.intent_id,
            intent.revision,
        );
        if (Number(intentUpdate.changes) !== 1) {
            throw new Error(
                'protected entry terminal intent settlement lost its CAS',
            );
        }
        transitioned = true;
        entryIntentRevision = intent.revision + 1;
    }
    const entryActivation = database.prepare(`
        SELECT state, revision FROM activations WHERE activation_id=?
    `).get(intent.activation_id);
    if (
        entryActivation &&
        !['filled', 'cancelled', 'failed', 'missed'].includes(
            entryActivation.state,
        )
    ) {
        const activationUpdate = database.prepare(`
            UPDATE activations
               SET state=?, evidence_hash=?, updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE activation_id=? AND state=? AND revision=?
        `).run(
            activationState,
            settlementHash,
            now,
            intent.activation_id,
            entryActivation.state,
            entryActivation.revision,
        );
        if (Number(activationUpdate.changes) !== 1) {
            throw new Error(
                'protected entry terminal activation settlement lost its CAS',
            );
        }
        transitioned = true;
    }
    const cancelLineage = protectedEntryCancelControlLineage(
        database,
        intent.intent_id,
    );
    if (cancelLineage) {
        const control = cancelLineage.control;
        if (control.state === 'prepared') {
            if (
                control.adapter_authority_granted !== 0 ||
                control.dispatch_attempt_nonce !== null ||
                control.runtime_epoch_id !== null ||
                control.sender_fence !== null ||
                control.api_generation !== null
            ) {
                throw new Error(
                    'prepared protected entry cancel is not proven unsent',
                );
            }
            const controlUpdate = database.prepare(`
                UPDATE order_intents
                   SET state='cancelled_proven_unsent',
                       terminal_outcome='cancel_proven_unsent_after_target_terminal',
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE intent_id=? AND state='prepared' AND revision=?
                   AND adapter_authority_granted=0
                   AND dispatch_attempt_nonce IS NULL
            `).run(now, now, control.intent_id, control.revision);
            if (Number(controlUpdate.changes) !== 1) {
                throw new Error(
                    'protected entry cancel proven-unsent settlement lost its CAS',
                );
            }
            transitioned = true;
            cancelIntentRevision = control.revision + 1;
        } else if (
            ['dispatching', 'acknowledged', 'reconciling', 'unknown'].includes(
                control.state,
            )
        ) {
            const controlUpdate = database.prepare(`
                UPDATE order_intents
                   SET state='terminal',
                       terminal_outcome='cancel_target_terminal_reconciled',
                       updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                       revision=revision+1
                 WHERE intent_id=? AND state=? AND revision=?
            `).run(now, now, control.intent_id, control.state, control.revision);
            if (Number(controlUpdate.changes) !== 1) {
                throw new Error(
                    'protected entry cancel terminal settlement lost its CAS',
                );
            }
            transitioned = true;
            cancelIntentRevision = control.revision + 1;
        } else if (
            !['terminal', 'cancelled_proven_unsent'].includes(control.state)
        ) {
            throw new Error(
                'protected entry cancel terminal replay has an invalid state',
            );
        }
        if (
            !['filled', 'cancelled', 'failed', 'missed'].includes(
                control.cancel_activation_state,
            )
        ) {
            const controlActivationUpdate = database.prepare(`
                UPDATE activations
                   SET state='cancelled', evidence_hash=?,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE activation_id=? AND state=? AND revision=?
            `).run(
                settlementHash,
                now,
                control.activation_id,
                control.cancel_activation_state,
                control.cancel_activation_revision,
            );
            if (Number(controlActivationUpdate.changes) !== 1) {
                throw new Error(
                    'protected entry cancel activation settlement lost its CAS',
                );
            }
            transitioned = true;
        }
        database.prepare(`
            UPDATE intent_rearm_authorizations
               SET state='superseded', revision=revision+1
             WHERE intent_id=? AND state='active'
        `).run(control.intent_id);
        if (cancelIntentRevision !== null) {
            insertTransitionJournalEvent(database, {
                entityKind: 'order_intent',
                entityId: control.intent_id,
                revision: cancelIntentRevision,
                reasonCode: 'BROKER_FINAL_EVIDENCE_APPLIED',
                summaryCode: 'protected_entry_cancel_settled',
                nowEpochMs: now,
                payloadHash: settlementHash,
                eventSuffix: 'protected-entry-cancel-settled',
            });
        }
    }
    if (entryIntentRevision !== null) {
        insertTransitionJournalEvent(database, {
            entityKind: 'order_intent',
            entityId: intent.intent_id,
            revision: entryIntentRevision,
            reasonCode: 'BROKER_FINAL_EVIDENCE_APPLIED',
            summaryCode: 'protected_entry_terminal_settled',
            nowEpochMs: now,
            payloadHash: settlementHash,
            eventSuffix: 'protected-entry-terminal-settled',
        });
    }
    if (transitioned) advanceLifecycleSideEffectRevision(database);
    return Object.freeze({
        brokerOrderId: brokerOrder.broker_order_id,
        cancelIntentId: cancelLineage?.control.intent_id ?? null,
        settlementHash,
        settled: true,
        replayed: !transitioned,
    });
}

function upsertProtectionGroupForMaterializedClaim(
    database,
    { claim, obligationId, planHash, evidenceHash, nowEpochMs },
) {
    const protectionGroupId = protectionGroupIdForClaim(claim.exit_claim_id);
    const existing = database.prepare(`
        SELECT groups.*, generations.state AS generation_state,
               generations.exit_claim_id AS generation_exit_claim_id,
               generations.quantity_shares AS generation_quantity_shares,
               generations.revision AS generation_revision
          FROM protection_groups AS groups
          JOIN protection_remainder_generations AS generations
            ON generations.protection_group_id=groups.protection_group_id
           AND generations.remainder_generation=groups.current_generation
         WHERE groups.protection_group_id=?
    `).get(protectionGroupId);
    if (!existing) {
        database.prepare(`
            INSERT INTO protection_groups(
                protection_group_id, obligation_id, exit_claim_id, state,
                current_generation, plan_hash, created_at_epoch_ms,
                updated_at_epoch_ms, revision
            ) VALUES (?, ?, ?, 'monitoring', ?, ?, ?, ?, 0)
        `).run(
            protectionGroupId,
            obligationId,
            claim.exit_claim_id,
            claim.remainder_generation,
            planHash,
            nowEpochMs,
            nowEpochMs,
        );
        database.prepare(`
            INSERT INTO protection_remainder_generations(
                protection_group_id, remainder_generation, exit_claim_id,
                state, quantity_shares, evidence_hash,
                created_at_epoch_ms, updated_at_epoch_ms, revision
            ) VALUES (?, ?, ?, 'monitoring', ?, ?, ?, ?, 0)
        `).run(
            protectionGroupId,
            claim.remainder_generation,
            claim.exit_claim_id,
            claim.quantity_shares,
            evidenceHash,
            nowEpochMs,
            nowEpochMs,
        );
        return Object.freeze({ protectionGroupId, groupRevision: 0, generationRevision: 0 });
    }
    if (
        existing.obligation_id !== obligationId ||
        existing.exit_claim_id !== claim.exit_claim_id ||
        existing.state !== 'monitoring' ||
        existing.current_generation !== claim.remainder_generation ||
        existing.plan_hash !== planHash ||
        existing.generation_state !== 'monitoring' ||
        existing.generation_exit_claim_id !== claim.exit_claim_id
    ) {
        throw new Error('materialized protection group lineage is not safely monitoring');
    }
    let generationRevision = existing.generation_revision;
    if (
        existing.generation_quantity_shares !== claim.quantity_shares ||
        claim.evidence_hash !== evidenceHash
    ) {
        const generationUpdate = database.prepare(`
            UPDATE protection_remainder_generations
               SET quantity_shares=?, evidence_hash=?, updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE protection_group_id=? AND remainder_generation=?
               AND state='monitoring' AND revision=?
        `).run(
            claim.quantity_shares,
            evidenceHash,
            nowEpochMs,
            protectionGroupId,
            claim.remainder_generation,
            existing.generation_revision,
        );
        if (Number(generationUpdate.changes) !== 1) {
            throw new Error('materialized protection generation lost its CAS');
        }
        generationRevision += 1;
    }
    return Object.freeze({
        protectionGroupId,
        groupRevision: existing.revision,
        generationRevision,
    });
}

function allocateProtectedEntryExitClaim(
    database,
    {
        accountBrokerRef,
        accountIdRef,
        contractKey,
        exitClaimId,
        positionLineageId,
        positionQuantityShares,
        quantityShares,
    },
) {
    const positionCapacity = safeInteger(
        positionQuantityShares,
        'protected entry position quantityShares',
    );
    const requestedQuantity = safeInteger(
        quantityShares,
        'protected entry ExitClaim quantityShares',
    );
    if (requestedQuantity <= 0 || requestedQuantity > positionCapacity) {
        return null;
    }
    const existingClaim = database
        .prepare('SELECT * FROM exit_claims WHERE exit_claim_id=?')
        .get(exitClaimId);
    const competingClaims = database.prepare(`
        SELECT exit_claim_id, position_lineage_id, allocation_start_share,
               quantity_shares, state
          FROM exit_claims
         WHERE account_broker_ref=? AND account_id_ref=? AND contract_key=?
           AND exit_claim_id<>?
           AND state IN (
               'monitoring_reserved','intent_reserved','broker_working','unknown'
           )
         ORDER BY allocation_start_share, exit_claim_id
    `).all(
        accountBrokerRef,
        accountIdRef,
        contractKey,
        exitClaimId,
    );
    const intervals = [];
    for (const claim of competingClaims) {
        if (
            claim.state === 'unknown' ||
            claim.position_lineage_id !== positionLineageId
        ) {
            return null;
        }
        const start = safeInteger(
            claim.allocation_start_share,
            'competing ExitClaim allocationStartShare',
        );
        const quantity = safeInteger(
            claim.quantity_shares,
            'competing ExitClaim quantityShares',
        );
        const end = addExposureInteger(
            start,
            quantity,
            'competing ExitClaim allocation interval',
        );
        if (quantity <= 0 || end > positionCapacity) return null;
        intervals.push({
            exitClaimId: claim.exit_claim_id,
            start,
            end,
        });
    }
    intervals.sort((left, right) =>
        left.start - right.start ||
        left.exitClaimId.localeCompare(right.exitClaimId),
    );
    for (let index = 1; index < intervals.length; index += 1) {
        if (intervals[index].start < intervals[index - 1].end) return null;
    }
    let allocationStartShare;
    if (existingClaim) {
        if (
            existingClaim.position_lineage_id !== positionLineageId ||
            existingClaim.state === 'unknown'
        ) {
            return null;
        }
        allocationStartShare = safeInteger(
            existingClaim.allocation_start_share,
            'existing protected entry ExitClaim allocationStartShare',
        );
        const requestedEnd = addExposureInteger(
            allocationStartShare,
            requestedQuantity,
            'existing protected entry ExitClaim allocation interval',
        );
        if (
            requestedEnd > positionCapacity ||
            intervals.some(
                (interval) =>
                    allocationStartShare < interval.end &&
                    interval.start < requestedEnd,
            )
        ) {
            return null;
        }
    } else {
        allocationStartShare = 0;
        for (const interval of intervals) {
            const requestedEnd = addExposureInteger(
                allocationStartShare,
                requestedQuantity,
                'new protected entry ExitClaim allocation interval',
            );
            if (requestedEnd <= interval.start) break;
            allocationStartShare = Math.max(allocationStartShare, interval.end);
        }
        if (
            addExposureInteger(
                allocationStartShare,
                requestedQuantity,
                'new protected entry ExitClaim allocation interval',
            ) > positionCapacity
        ) {
            return null;
        }
    }
    return Object.freeze({
        allocationStartShare,
        activeClaimSetHash: sha256Canonical(
            intervals.map((interval) => ({
                allocationStartShare: interval.start,
                allocationEndShare: interval.end,
                exitClaimId: interval.exitClaimId,
            })),
            'protected entry active ExitClaim set',
        ),
        existingClaim,
    });
}

function materializeProtectedEntryFill(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'apiGeneration',
            'intentId',
            'nowEpochMs',
            'reconciliation',
            'runtimeEpochId',
            'senderFence',
        ])
    ) {
        throw new TypeError('protected entry fill input schema is invalid');
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const intentId = boundedToken(input.intentId, 'intentId');
    const now = safeInteger(input.nowEpochMs, 'protectedEntryFill.nowEpochMs');
    const projection = canonicalReconciliationProjection(input.reconciliation);
    return transaction(database, () => {
        if (
            !currentRuntimeObserverMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error(
                'protected entry fill requires the current Runtime observer',
            );
        }
        if (projection.asOfEpochMs > now) {
            throw new Error('protected entry reconciliation cannot come from the future');
        }
        upsertAccountReconciliationHead(database, projection, now);
        const intent = database
            .prepare(`
                SELECT * FROM order_intents WHERE intent_id=?
            `)
            .get(intentId);
        if (!intent) throw new Error('protected entry intent does not exist');
        if (
            intent.operation_kind !== 'place' ||
            intent.side !== 'Buy' ||
            intent.account_broker_ref !== projection.account.brokerId ||
            intent.account_id_ref !== projection.account.accountId ||
            intent.trade_date !== projection.tradeDate
        ) {
            throw new Error('protected entry reconciliation scope is invalid');
        }
        const protectedIntent = canonicalProtectedEntryIntentPayload(
            JSON.parse(intent.payload_json),
        );
        const plan = canonicalProtectedEntryPlan(
            protectedIntent.payload.protectionPlan,
        );
        const commitment = database
            .prepare(`
                SELECT * FROM pending_protection_commitments
                 WHERE entry_intent_id=?
            `)
            .get(intentId);
        const obligation = commitment
            ? database
                  .prepare('SELECT * FROM protection_obligations WHERE commitment_id=?')
                  .get(commitment.commitment_id)
            : undefined;
        const reservation = database
            .prepare('SELECT * FROM entry_exposure_reservations WHERE intent_id=?')
            .get(intentId);
        if (!commitment || !obligation || !reservation) {
            throw new Error('protected entry durable companions are incomplete');
        }
        if (
            plan.plan.contractKey !== intent.contract_key ||
            commitment.committed_shares !== plan.baseShares ||
            obligation.position_lineage_id.length === 0
        ) {
            throw new Error('protected entry durable plan lineage is invalid');
        }
        const heads = database
            .prepare('SELECT * FROM broker_event_heads WHERE intent_id=?')
            .all(intentId);
        if (heads.length !== 1) {
            return protectedEntryReconciliationRequired(database, {
                intent,
                commitment,
                obligation,
                reservation,
                runtimeEpochId,
                reason: 'protected_entry_broker_event_lineage_ambiguous',
                now,
            });
        }
        const head = heads[0];
        const contractUnit = plan.plan.entryOrder.contractUnit;
        const cumulativeFilledShares = brokerEventQuantityShares(
            head.cumulative_deal_quantity,
            head.quantity_unit,
            contractUnit,
            'broker event cumulative filled quantity',
        );
        const remainingEntryShares = brokerEventQuantityShares(
            head.remaining_quantity,
            head.quantity_unit,
            contractUnit,
            'broker event remaining quantity',
        );
        const cumulativeCancelledShares = brokerEventQuantityShares(
            head.cumulative_cancel_quantity,
            head.quantity_unit,
            contractUnit,
            'broker event cumulative cancelled quantity',
        );
        if (
            cumulativeFilledShares + remainingEntryShares +
                cumulativeCancelledShares !== commitment.committed_shares
        ) {
            return protectedEntryReconciliationRequired(database, {
                intent,
                commitment,
                obligation,
                reservation,
                runtimeEpochId,
                reason: 'protected_entry_quantity_projection_conflict',
                now,
            });
        }
        const dealRows = database
            .prepare(`
                SELECT * FROM broker_event_records
                 WHERE intent_id=? AND event_kind='deal'
                   AND broker_order_correlation_key_hash=?
                 ORDER BY deal_id
            `)
            .all(intentId, head.broker_order_correlation_key_hash);
        const reconciledDealIds = new Set(
            projection.deals.map((deal) => deal.dealId),
        );
        let dealShares = 0;
        let fillNotionalMinorUnits = 0n;
        let dealProjectionValid = true;
        for (const deal of dealRows) {
            if (
                deal.deal_id === null ||
                !reconciledDealIds.has(deal.deal_id) ||
                deal.price_decimal === null
            ) {
                dealProjectionValid = false;
                break;
            }
            const shares = brokerEventQuantityShares(
                deal.event_deal_quantity,
                deal.quantity_unit,
                contractUnit,
                'broker deal quantity',
            );
            const priceMinorUnits = brokerPriceMinorUnits(
                deal.price_decimal,
                'broker deal price',
            );
            dealShares += shares;
            fillNotionalMinorUnits += BigInt(shares) * BigInt(priceMinorUnits);
        }
        if (
            !Number.isSafeInteger(dealShares) ||
            dealShares !== cumulativeFilledShares ||
            fillNotionalMinorUnits > BigInt(Number.MAX_SAFE_INTEGER)
        ) {
            dealProjectionValid = false;
        }
        const position = projection.positions.find(
            (candidate) => candidate.contractKey === intent.contract_key,
        );
        let competingWorkingSellShares = 0;
        for (const workingOrder of projection.workingOrders) {
            if (
                workingOrder.contractKey === intent.contract_key &&
                workingOrder.side === 'Sell' &&
                workingOrder.remainingShares > 0
            ) {
                competingWorkingSellShares += workingOrder.remainingShares;
                if (!Number.isSafeInteger(competingWorkingSellShares)) break;
            }
        }
        if (
            !dealProjectionValid ||
            !position ||
            position.positionLineageId !== obligation.position_lineage_id ||
            position.quantityShares < cumulativeFilledShares ||
            position.availableShares < cumulativeFilledShares ||
            !Number.isSafeInteger(competingWorkingSellShares) ||
            position.quantityShares - competingWorkingSellShares <
                cumulativeFilledShares
        ) {
            return protectedEntryReconciliationRequired(database, {
                intent,
                commitment,
                obligation,
                reservation,
                runtimeEpochId,
                reason: !dealProjectionValid
                    ? 'protected_entry_deal_projection_conflict'
                    : 'protected_entry_protectable_availability_conflict',
                now,
            });
        }
        const terminal = ['Filled', 'Cancelled', 'Inactive', 'Failed'].includes(
            head.status,
        );
        const terminalSettlement =
            terminal && remainingEntryShares === 0
                ? settleProtectedEntryTerminalReconciliation(database, {
                      commitment,
                      cumulativeCancelledShares,
                      cumulativeFilledShares,
                      head,
                      intent,
                      now,
                      projection,
                  })
                : Object.freeze({ settled: false });
        const existingFill = database
            .prepare('SELECT * FROM protected_entry_fill_heads WHERE intent_id=?')
            .get(intentId);
        if (
            existingFill &&
            (cumulativeFilledShares < existingFill.cumulative_filled_shares ||
                Number(fillNotionalMinorUnits) <
                    existingFill.fill_notional_minor_units)
        ) {
            throw new Error('protected entry fill head cannot roll back');
        }
        if (cumulativeFilledShares === 0) {
            if (!terminal || remainingEntryShares !== 0) {
                return Object.freeze({
                    state: 'waiting_entry_fill',
                    intentId,
                    cumulativeFilledShares: 0,
                    remainingEntryShares,
                    brokerWriteAuthority: false,
                });
            }
            if (existingFill && existingFill.state !== 'zero_fill') {
                throw new Error('protected entry zero-fill conflicts with prior fill');
            }
            if (
                existingFill &&
                existingFill.reconciliation_snapshot_hash ===
                    projection.snapshotSha256
            ) {
                return Object.freeze({
                    state: 'zero_fill_terminal',
                    intentId,
                    cumulativeFilledShares: 0,
                    remainingEntryShares: 0,
                    exitClaimId: null,
                    replayed: true,
                    terminalSettlement,
                    brokerWriteAuthority: false,
                });
            }
            const claimCount = Number(
                database
                    .prepare('SELECT COUNT(*) AS count FROM exit_claims WHERE obligation_id=?')
                    .get(obligation.obligation_id)?.count,
            );
            if (claimCount !== 0) {
                throw new Error('zero-fill protected entry cannot have an exit claim');
            }
            const nextCommitmentRevision = commitment.revision + 1;
            const nextObligationRevision = obligation.revision + 1;
            const nextReservationRevision = reservation.revision + 1;
            const commitmentUpdate = database
                .prepare(`
                    UPDATE pending_protection_commitments
                       SET state='zero_fill_terminal', materialized_shares=0,
                           updated_at_epoch_ms=?, revision=revision+1
                     WHERE commitment_id=? AND revision=?
                `)
                .run(now, commitment.commitment_id, commitment.revision);
            if (Number(commitmentUpdate.changes) !== 1) {
                throw new Error('protected entry zero-fill commitment CAS failed');
            }
            const obligationUpdate = database
                .prepare(`
                    UPDATE protection_obligations
                       SET state='zero_fill_terminal', filled_shares=0,
                           updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                           revision=revision+1
                     WHERE obligation_id=? AND revision=?
                `)
                .run(now, now, obligation.obligation_id, obligation.revision);
            if (Number(obligationUpdate.changes) !== 1) {
                throw new Error('protected entry zero-fill obligation CAS failed');
            }
            const reservationUpdate = database
                .prepare(`
                    UPDATE entry_exposure_reservations
                       SET state='released', quantity_shares=0,
                           notional_minor_units=0, cash_minor_units=0,
                           position_shares=0, order_count=0,
                           updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                           revision=revision+1
                     WHERE reservation_id=? AND revision=?
                `)
                .run(now, now, reservation.reservation_id, reservation.revision);
            if (Number(reservationUpdate.changes) !== 1) {
                throw new Error('protected entry zero-fill reservation CAS failed');
            }
            const dealSetHash = sha256Canonical([], 'protected entry zero-fill deal set');
            const fillRevision = existingFill ? existingFill.revision : 0;
            if (!existingFill) {
                database.prepare(`
                    INSERT INTO protected_entry_fill_heads(
                        intent_id, commitment_id, obligation_id, exit_claim_id,
                        protection_plan_hash, atr_snapshot_hash,
                        formal_protection_json, formal_protection_hash,
                        cumulative_filled_shares, remaining_entry_shares,
                        fill_notional_minor_units,
                        weighted_average_numerator_minor_units,
                        weighted_average_denominator_shares,
                        position_lineage_id, position_quantity_shares,
                        deal_set_hash, reconciliation_snapshot_hash,
                        reconciliation_evidence_hash,
                        reconciliation_source_revision,
                        reconciliation_as_of_epoch_ms, state,
                        created_at_epoch_ms, updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, NULL, ?, ?, NULL, NULL, 0, 0, 0, 0, 0, ?, ?, ?, ?, ?, ?, ?, 'zero_fill', ?, ?, 0)
                `).run(
                    intentId,
                    commitment.commitment_id,
                    obligation.obligation_id,
                    plan.planSha256,
                    plan.plan.fixedAtrSnapshot === null
                        ? null
                        : sha256Canonical(plan.plan.fixedAtrSnapshot, 'fixed ATR snapshot'),
                    obligation.position_lineage_id,
                    position.quantityShares,
                    dealSetHash,
                    projection.snapshotSha256,
                    projection.evidenceSha256,
                    projection.sourceRevision,
                    projection.asOfEpochMs,
                    now,
                    now,
                );
            }
            advanceLifecycleSideEffectRevision(database);
            insertTransitionJournalEvent(database, {
                entityKind: 'protected_entry_fill',
                entityId: intentId,
                revision: fillRevision,
                reasonCode: 'PROTECTED_ENTRY_ZERO_FILL_CONFIRMED',
                summaryCode: 'protected_entry_zero_fill',
                nowEpochMs: now,
                payloadHash: projection.evidenceSha256,
                eventSuffix: 'zero-fill',
            });
            return Object.freeze({
                state: 'zero_fill_terminal',
                intentId,
                cumulativeFilledShares: 0,
                remainingEntryShares: 0,
                commitmentRevision: nextCommitmentRevision,
                obligationRevision: nextObligationRevision,
                reservationRevision: nextReservationRevision,
                exitClaimId: null,
                terminalSettlement,
                brokerWriteAuthority: false,
            });
        }
        const fillNotional = Number(fillNotionalMinorUnits);
        const dealSetHash = sha256Canonical(
            dealRows.map((deal) => ({
                dealId: deal.deal_id,
                evidenceHash: deal.evidence_hash,
                eventDealQuantity: deal.event_deal_quantity,
                price: deal.price_decimal,
                unit: deal.quantity_unit,
            })),
            'protected entry deal set',
        );
        if (
            existingFill &&
            existingFill.cumulative_filled_shares === cumulativeFilledShares &&
            existingFill.fill_notional_minor_units === fillNotional &&
            existingFill.deal_set_hash === dealSetHash &&
            existingFill.reconciliation_snapshot_hash === projection.snapshotSha256
        ) {
            return Object.freeze({
                state: existingFill.state,
                intentId,
                cumulativeFilledShares,
                remainingEntryShares,
                fillNotionalMinorUnits: fillNotional,
                weightedAverage: Object.freeze({
                    numeratorMinorUnits: fillNotional,
                    denominatorShares: cumulativeFilledShares,
                }),
                exitClaimId: existingFill.exit_claim_id,
                replayed: true,
                terminalSettlement,
                brokerWriteAuthority: false,
            });
        }
        const exitClaimId = existingFill?.exit_claim_id ??
            `exit-claim:${sha256Canonical(
                [intentId, obligation.obligation_id, plan.planSha256],
                'protected entry exit claim ID',
            ).slice(7)}`;
        const claimAllocation = allocateProtectedEntryExitClaim(database, {
            accountBrokerRef: intent.account_broker_ref,
            accountIdRef: intent.account_id_ref,
            contractKey: intent.contract_key,
            exitClaimId,
            positionLineageId: obligation.position_lineage_id,
            positionQuantityShares: position.quantityShares,
            quantityShares: cumulativeFilledShares,
        });
        if (!claimAllocation) {
            return protectedEntryReconciliationRequired(database, {
                intent,
                commitment,
                obligation,
                reservation,
                runtimeEpochId,
                reason: 'protected_entry_exit_claim_capacity_conflict',
                now,
            });
        }
        const materializationEvidenceHash = sha256Canonical(
            {
                intentId,
                cumulativeFilledShares,
                fillNotionalMinorUnits: fillNotional,
                allocationStartShare: claimAllocation.allocationStartShare,
                activeClaimSetHash: claimAllocation.activeClaimSetHash,
                positionLineageId: position.positionLineageId,
                positionQuantityShares: position.quantityShares,
                dealSetHash,
                reconciliationSnapshotHash: projection.snapshotSha256,
                protectionPlanHash: plan.planSha256,
            },
            'protected entry fill materialization',
        );
        const existingClaim = claimAllocation.existingClaim;
        let claimRevision;
        if (!existingClaim) {
            database.prepare(`
                INSERT INTO exit_claims(
                    exit_claim_id, obligation_id, intent_id, external_lineage,
                    account_broker_ref, account_id_ref, contract_key,
                    position_lineage_id, remainder_generation,
                    allocation_start_share, quantity_shares, state,
                    evidence_hash, created_at_epoch_ms, updated_at_epoch_ms,
                    revision
                ) VALUES (?, ?, NULL, 0, ?, ?, ?, ?, 0, ?, ?,
                          'monitoring_reserved', ?, ?, ?, 0)
            `).run(
                exitClaimId,
                obligation.obligation_id,
                intent.account_broker_ref,
                intent.account_id_ref,
                intent.contract_key,
                obligation.position_lineage_id,
                claimAllocation.allocationStartShare,
                cumulativeFilledShares,
                materializationEvidenceHash,
                now,
                now,
            );
            claimRevision = 0;
        } else {
            if (
                existingClaim.obligation_id !== obligation.obligation_id ||
                existingClaim.external_lineage !== 0 ||
                existingClaim.state !== 'monitoring_reserved' ||
                existingClaim.intent_id !== null ||
                existingClaim.position_lineage_id !==
                    obligation.position_lineage_id ||
                existingClaim.allocation_start_share !==
                    claimAllocation.allocationStartShare ||
                existingClaim.quantity_shares > cumulativeFilledShares
            ) {
                return protectedEntryReconciliationRequired(database, {
                    intent,
                    commitment,
                    obligation,
                    reservation,
                    runtimeEpochId,
                    reason: 'protected_entry_exit_claim_conflict',
                    now,
                });
            }
            const claimUpdate = database.prepare(`
                UPDATE exit_claims
                   SET quantity_shares=?, evidence_hash=?,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE exit_claim_id=? AND revision=?
            `).run(
                cumulativeFilledShares,
                materializationEvidenceHash,
                now,
                exitClaimId,
                existingClaim.revision,
            );
            if (Number(claimUpdate.changes) !== 1) {
                throw new Error('protected entry ExitClaim update lost its CAS');
            }
            claimRevision = existingClaim.revision + 1;
        }
        const durableClaim = database
            .prepare('SELECT * FROM exit_claims WHERE exit_claim_id=?')
            .get(exitClaimId);
        const protectionGroup = upsertProtectionGroupForMaterializedClaim(
            database,
            {
                claim: durableClaim,
                obligationId: obligation.obligation_id,
                planHash: plan.planSha256,
                evidenceHash: materializationEvidenceHash,
                nowEpochMs: now,
            },
        );
        const monitoringAuthority = database.prepare(`
            SELECT strategies.state AS strategy_state,
                   strategies.revision AS strategy_revision,
                   strategies.confirmation_snapshot_hash,
                   runtime.reconciliation_evidence_hash,
                   rearms.confirmation_snapshot_hash AS rearm_confirmation_snapshot_hash,
                   rearms.risk_revision,
                   rearms.reconciliation_evidence_hash AS rearm_reconciliation_evidence_hash,
                   rearms.user_rearm_evidence_hash,
                   rearms.rearm_authorization_id
              FROM strategies
              JOIN runtime_epochs AS runtime
                ON runtime.runtime_epoch_id=?
               AND runtime.sender_fence=?
               AND runtime.api_generation=?
              JOIN intent_rearm_authorizations AS rearms
                ON rearms.intent_id=?
               AND rearms.runtime_epoch_id=runtime.runtime_epoch_id
               AND rearms.sender_fence=runtime.sender_fence
               AND rearms.api_generation=runtime.api_generation
               AND rearms.state='consumed'
             WHERE strategies.strategy_id=?
        `).get(
            runtimeEpochId,
            senderFence,
            apiGeneration,
            intentId,
            intent.strategy_id,
        );
        if (
            monitoringAuthority &&
            monitoringAuthority.strategy_state === 'observing' &&
            monitoringAuthority.confirmation_snapshot_hash ===
                plan.plan.confirmationSnapshotHash &&
            monitoringAuthority.rearm_confirmation_snapshot_hash ===
                plan.plan.confirmationSnapshotHash &&
            monitoringAuthority.risk_revision === plan.plan.riskRevision &&
            monitoringAuthority.reconciliation_evidence_hash !== null &&
            monitoringAuthority.rearm_reconciliation_evidence_hash ===
                monitoringAuthority.reconciliation_evidence_hash
        ) {
            const strategyUpdate = database.prepare(`
                UPDATE strategies
                   SET state='monitoring', updated_at_epoch_ms=?,
                       revision=revision+1
                 WHERE strategy_id=? AND state='observing' AND revision=?
            `).run(
                now,
                intent.strategy_id,
                monitoringAuthority.strategy_revision,
            );
            if (Number(strategyUpdate.changes) !== 1) {
                throw new Error(
                    'protected entry monitoring transition lost its strategy CAS',
                );
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'strategy',
                entityId: intent.strategy_id,
                revision: monitoringAuthority.strategy_revision + 1,
                reasonCode: 'PROTECTION_MONITORING_REVISION_UPDATED',
                summaryCode: 'protection_monitoring_started',
                nowEpochMs: now,
                payloadHash: materializationEvidenceHash,
                eventSuffix: 'protection-monitoring-started',
            });
        }
        const finalFill = terminal && remainingEntryShares === 0;
        const commitmentState = finalFill ? 'materialized' : 'materializing';
        const commitmentUpdate = database.prepare(`
            UPDATE pending_protection_commitments
               SET state=?, materialized_shares=?, updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE commitment_id=? AND revision=?
        `).run(
            commitmentState,
            cumulativeFilledShares,
            now,
            commitment.commitment_id,
            commitment.revision,
        );
        if (Number(commitmentUpdate.changes) !== 1) {
            throw new Error('protected entry fill commitment update lost its CAS');
        }
        const obligationUpdate = database.prepare(`
            UPDATE protection_obligations
               SET state='monitoring', filled_shares=?,
                   updated_at_epoch_ms=?, revision=revision+1
             WHERE obligation_id=? AND revision=?
        `).run(
            cumulativeFilledShares,
            now,
            obligation.obligation_id,
            obligation.revision,
        );
        if (Number(obligationUpdate.changes) !== 1) {
            throw new Error('protected entry fill obligation update lost its CAS');
        }
        const remainingExposure = deriveProtectedEntryWorstCaseExposure(
            plan.plan,
            remainingEntryShares,
        );
        const reservationUpdate = database.prepare(`
            UPDATE entry_exposure_reservations
               SET state=?, quantity_shares=?, notional_minor_units=?,
                   cash_minor_units=?, position_shares=?, order_count=?,
                   updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                   revision=revision+1
             WHERE reservation_id=? AND revision=?
        `).run(
            remainingEntryShares === 0 ? 'consumed' : 'partially_consumed',
            remainingExposure.quantityShares,
            remainingExposure.notionalMinorUnits,
            remainingExposure.cashMinorUnits,
            remainingExposure.positionShares,
            remainingExposure.orderCount,
            now,
            remainingEntryShares === 0 ? now : null,
            reservation.reservation_id,
            reservation.revision,
        );
        if (Number(reservationUpdate.changes) !== 1) {
            throw new Error('protected entry fill reservation update lost its CAS');
        }
        const activationState = finalFill ? 'filled' : 'part_filled';
        database.prepare(`
            UPDATE activations SET state=?, updated_at_epoch_ms=?,
                   revision=revision+1
             WHERE activation_id=?
               AND state NOT IN ('filled','cancelled','failed','missed')
        `).run(activationState, now, intent.activation_id);
        const fillState = finalFill ? 'final' : 'partial';
        const formalProtection = deriveProtectedEntryFormalProtection(
            plan.plan,
            fillNotional,
            cumulativeFilledShares,
        );
        const formalProtectionJson = stableCanonicalJson(formalProtection);
        const formalProtectionHash = sha256Canonical(
            formalProtection,
            'formal protected entry projection',
        );
        const atrSnapshotHash = plan.plan.fixedAtrSnapshot === null
            ? null
            : sha256Canonical(plan.plan.fixedAtrSnapshot, 'fixed ATR snapshot');
        let fillRevision;
        if (!existingFill) {
            database.prepare(`
                INSERT INTO protected_entry_fill_heads(
                    intent_id, commitment_id, obligation_id, exit_claim_id,
                    protection_plan_hash, atr_snapshot_hash,
                    formal_protection_json, formal_protection_hash,
                    cumulative_filled_shares, remaining_entry_shares,
                    fill_notional_minor_units,
                    weighted_average_numerator_minor_units,
                    weighted_average_denominator_shares,
                    position_lineage_id, position_quantity_shares,
                    deal_set_hash, reconciliation_snapshot_hash,
                    reconciliation_evidence_hash,
                    reconciliation_source_revision,
                    reconciliation_as_of_epoch_ms, state,
                    created_at_epoch_ms, updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            `).run(
                intentId,
                commitment.commitment_id,
                obligation.obligation_id,
                exitClaimId,
                plan.planSha256,
                atrSnapshotHash,
                formalProtectionJson,
                formalProtectionHash,
                cumulativeFilledShares,
                remainingEntryShares,
                fillNotional,
                fillNotional,
                cumulativeFilledShares,
                obligation.position_lineage_id,
                position.quantityShares,
                dealSetHash,
                projection.snapshotSha256,
                projection.evidenceSha256,
                projection.sourceRevision,
                projection.asOfEpochMs,
                fillState,
                now,
                now,
            );
            fillRevision = 0;
        } else {
            database.prepare(`
                UPDATE protected_entry_fill_heads
                   SET exit_claim_id=?, cumulative_filled_shares=?,
                       remaining_entry_shares=?, fill_notional_minor_units=?,
                       weighted_average_numerator_minor_units=?,
                       weighted_average_denominator_shares=?,
                       position_quantity_shares=?, deal_set_hash=?,
                       reconciliation_snapshot_hash=?,
                       reconciliation_evidence_hash=?,
                       reconciliation_source_revision=?,
                       reconciliation_as_of_epoch_ms=?,
                       formal_protection_json=?, formal_protection_hash=?, state=?,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE intent_id=? AND revision=?
            `).run(
                exitClaimId,
                cumulativeFilledShares,
                remainingEntryShares,
                fillNotional,
                fillNotional,
                cumulativeFilledShares,
                position.quantityShares,
                dealSetHash,
                projection.snapshotSha256,
                projection.evidenceSha256,
                projection.sourceRevision,
                projection.asOfEpochMs,
                formalProtectionJson,
                formalProtectionHash,
                fillState,
                now,
                intentId,
                existingFill.revision,
            );
            fillRevision = existingFill.revision + 1;
        }
        advanceLifecycleSideEffectRevision(database);
        insertTransitionJournalEvent(database, {
            entityKind: 'protected_entry_fill',
            entityId: intentId,
            revision: fillRevision,
            reasonCode: finalFill
                ? 'PROTECTED_ENTRY_FILL_FINAL_MATERIALIZED'
                : 'PROTECTED_ENTRY_PARTIAL_FILL_MATERIALIZED',
            summaryCode: finalFill
                ? 'protected_entry_fill_final'
                : 'protected_entry_fill_partial',
            nowEpochMs: now,
            payloadHash: materializationEvidenceHash,
            eventSuffix: finalFill ? 'final' : 'partial',
        });
        return Object.freeze({
            state: fillState,
            intentId,
            cumulativeFilledShares,
            remainingEntryShares,
            fillNotionalMinorUnits: fillNotional,
            weightedAverage: Object.freeze({
                numeratorMinorUnits: fillNotional,
                denominatorShares: cumulativeFilledShares,
            }),
            atrSnapshotHash,
            exitClaimId,
            exitClaimRevision: claimRevision,
            protectionGroupId: protectionGroup.protectionGroupId,
            protectionGroupRevision: protectionGroup.groupRevision,
            protectionGenerationRevision:
                protectionGroup.generationRevision,
            commitmentRevision: commitment.revision + 1,
            obligationRevision: obligation.revision + 1,
            reservationRevision: reservation.revision + 1,
            fillRevision,
            terminalSettlement,
            brokerWriteAuthority: false,
        });
    });
}

function canonicalTradingContractKeyFromQuickQuote(contractKey) {
    const value = boundedToken(contractKey, 'protectiveQuote.contractKey');
    const match = /^(TSE|OTC):STK:([A-Za-z0-9][A-Za-z0-9._-]{0,31})$/.exec(
        value,
    );
    if (!match) {
        throw new TypeError('protective quote contract key is unsupported');
    }
    return `${match[1]}:${match[2]}:STK:Common`;
}

function canonicalQuickQuoteObservation(input) {
    if (
        !exactKeys(input, [
            'contractKey',
            'disabledFields',
            'eventKind',
            'exchangeTimeMs',
            'mappingDefinitionSha256',
            'mappingRevision',
            'observationId',
            'projections',
            'receiveTimeMs',
            'sequence',
            'streamEpoch',
            'tradeDate',
        ]) ||
        !Array.isArray(input.projections) ||
        !Array.isArray(input.disabledFields)
    ) {
        throw new TypeError('quick quote observation schema is invalid');
    }
    const mappingDefinitionSha256 = sha256Digest(
        input.mappingDefinitionSha256,
        'quickQuote.mappingDefinitionSha256',
    );
    if (
        input.mappingRevision !== SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
        mappingDefinitionSha256 !==
            SMART_ORDER_QUICK_FIELD_MAPPING_DEFINITION_SHA256 ||
        !['tick', 'bidask'].includes(input.eventKind)
    ) {
        throw new Error('quick quote mapping evidence is not current');
    }
    const mappingFields = new Set(
        SMART_ORDER_QUICK_FIELD_MAPPING.map((row) => row.field),
    );
    const projections = input.projections.map((projection) => {
        if (
            !exactKeys(projection, [
                'field',
                'localUnit',
                'mappingDefinitionSha256',
                'mappingRevision',
                'sourceField',
                'sourceKind',
                'value',
            ])
        ) {
            throw new TypeError('quick quote field projection schema is invalid');
        }
        const mapping = currentSmartOrderQuickFieldMapping(projection.field);
        if (
            !mapping ||
            mapping.sourceKind !== input.eventKind ||
            projection.sourceKind !== mapping.sourceKind ||
            projection.sourceField !== mapping.sourceField ||
            projection.localUnit !== mapping.localUnit ||
            projection.mappingRevision !==
                SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
            projection.mappingDefinitionSha256 !==
                SMART_ORDER_QUICK_FIELD_MAPPING_DEFINITION_SHA256
        ) {
            throw new Error('quick quote field projection mapping changed');
        }
        return Object.freeze({
            field: mapping.field,
            localUnit: mapping.localUnit,
            value: boundedToken(projection.value, 'quickQuote.value', 80),
        });
    });
    const disabledFields = input.disabledFields.map((disabled) => {
        if (
            !exactKeys(disabled, [
                'field',
                'localUnit',
                'mappingDefinitionSha256',
                'mappingRevision',
                'reason',
            ])
        ) {
            throw new TypeError('quick disabled field schema is invalid');
        }
        const mapping = currentSmartOrderQuickFieldMapping(disabled.field);
        if (
            !mapping ||
            disabled.localUnit !== mapping.localUnit ||
            disabled.mappingRevision !==
                SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
            disabled.mappingDefinitionSha256 !==
                SMART_ORDER_QUICK_FIELD_MAPPING_DEFINITION_SHA256
        ) {
            throw new Error('quick disabled field mapping changed');
        }
        boundedToken(disabled.reason, 'quickQuote.disabledReason');
        return Object.freeze({ field: mapping.field });
    });
    const projectedFields = [...projections, ...disabledFields].map(
        (entry) => entry.field,
    );
    const expectedFields = SMART_ORDER_QUICK_FIELD_MAPPING.filter(
        (row) => row.sourceKind === input.eventKind,
    ).map((row) => row.field);
    if (
        projectedFields.length !== expectedFields.length ||
        new Set(projectedFields).size !== projectedFields.length ||
        expectedFields.some((field) => !projectedFields.includes(field)) ||
        projectedFields.some((field) => !mappingFields.has(field))
    ) {
        throw new Error('quick quote field coverage is incomplete or duplicated');
    }
    return Object.freeze({
        contractKey: boundedToken(input.contractKey, 'quickQuote.contractKey'),
        disabledFields: Object.freeze(disabledFields),
        eventKind: input.eventKind,
        exchangeTimeMs: safeInteger(
            input.exchangeTimeMs,
            'quickQuote.exchangeTimeMs',
        ),
        mappingDefinitionSha256,
        mappingRevision: input.mappingRevision,
        observationId: sha256Digest(
            input.observationId,
            'quickQuote.observationId',
        ),
        projections: Object.freeze(projections),
        receiveTimeMs: safeInteger(
            input.receiveTimeMs,
            'quickQuote.receiveTimeMs',
        ),
        sequence: safeInteger(input.sequence, 'quickQuote.sequence'),
        streamEpoch: boundedToken(input.streamEpoch, 'quickQuote.streamEpoch'),
        tradeDate: taipeiTradeDate(input.tradeDate),
    });
}

function goodTillWorstCaseReservation(order, riskPolicy) {
    const executionPolicy = riskPolicy.executionPolicy;
    if (!executionPolicy) {
        throw new Error('good-till execution risk policy is missing');
    }
    const priceMinorUnits = brokerPriceMinorUnits(
        order.limitPrice,
        'goodTill.order.limitPrice',
    );
    const notional = BigInt(order.baseShares) * BigInt(priceMinorUnits);
    const fee =
        (notional * BigInt(executionPolicy.buyFeeBps) + 9_999n) / 10_000n;
    const feeMinorUnits = BigInt(
        Math.max(Number(fee), executionPolicy.minimumBuyFeeMinorUnits),
    );
    const cash =
        notional +
        feeMinorUnits +
        BigInt(executionPolicy.cashBufferMinorUnits);
    if (
        notional > BigInt(Number.MAX_SAFE_INTEGER) ||
        cash > BigInt(Number.MAX_SAFE_INTEGER)
    ) {
        throw new Error('good-till worst-case exposure exceeds safe integers');
    }
    return Object.freeze({
        quantityShares: order.baseShares,
        notionalMinorUnits: Number(notional),
        cashMinorUnits: Number(cash),
        positionShares: order.baseShares,
        orderCount: 1,
    });
}

function recordGoodTillQuoteObservationInTransaction(
    database,
    { apiGeneration, now, observation, runtimeEpochId, senderFence },
) {
    const strategies = database.prepare(`
        SELECT * FROM strategies
         WHERE strategy_kind='good_till' AND state='monitoring'
           AND confirmation_snapshot_hash IS NOT NULL
         ORDER BY strategy_id
    `).all();
    let observedStrategyCount = 0;
    let replayedStrategyCount = 0;
    let preparedIntentCount = 0;
    let blockedStrategyCount = 0;
    for (const strategy of strategies) {
        const definition = parseStoredCanonicalObject(
            strategy.definition_json,
            'good-till strategy definition',
        );
        assertCanonicalSmartOrderDraft(definition, {
            expectedKind: 'good_till',
        });
        if (
            definition.parameters.monitorContractKey !==
            observation.contractKey
        ) {
            continue;
        }
        const validity = definition.parameters.validity;
        if (
            observation.tradeDate < validity.startDate ||
            observation.tradeDate > validity.endDate
        ) {
            continue;
        }
        try {
            assertCanonicalConfirmationCurrent(database, {
                strategyId: strategy.strategy_id,
                snapshotHash: strategy.confirmation_snapshot_hash,
                runtimeEpochId,
                senderFence,
                apiGeneration,
                nowEpochMs: canonicalConfirmationClockNowEpochMs(now),
            });
        } catch {
            blockedStrategyCount += 1;
            continue;
        }
        let progress = database.prepare(`
            SELECT * FROM good_till_progress_heads WHERE strategy_id=?
        `).get(strategy.strategy_id);
        if (!progress) {
            throw new Error('good-till progress head is missing');
        }
        if (progress.daily_state === 'completed') continue;
        if (
            progress.active_trade_date !== null &&
            progress.active_trade_date < observation.tradeDate
        ) {
            if (progress.daily_state !== 'terminal_consumed') {
                blockedStrategyCount += 1;
                continue;
            }
            const reset = database.prepare(`
                UPDATE good_till_progress_heads
                   SET daily_state='waiting', active_trade_date=NULL,
                       active_activation_id=NULL, active_intent_id=NULL,
                       active_accounted_filled_shares=0,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE strategy_id=? AND revision=?
                   AND daily_state='terminal_consumed'
            `).run(now, strategy.strategy_id, progress.revision);
            if (Number(reset.changes) !== 1) {
                throw new Error('good-till daily reset lost its CAS');
            }
            progress = database.prepare(`
                SELECT * FROM good_till_progress_heads WHERE strategy_id=?
            `).get(strategy.strategy_id);
        }
        if (
            progress.active_trade_date === observation.tradeDate &&
            progress.daily_state !== 'waiting'
        ) {
            blockedStrategyCount += 1;
            continue;
        }
        const condition = canonicalSmartOrderQuickCondition(
            definition.parameters.condition,
        );
        const projection = observation.projections.find(
            (entry) => entry.field === condition.field,
        );
        if (!projection) {
            if (
                observation.disabledFields.some(
                    (entry) => entry.field === condition.field,
                )
            ) {
                blockedStrategyCount += 1;
                continue;
            }
            throw new Error(
                'good-till condition field is absent without disable evidence',
            );
        }
        const durableObservationId = `good-till-observation:${sha256Canonical(
            [strategy.strategy_id, observation.observationId],
            'good-till observation identity',
        ).slice(7)}`;
        const previous = database.prepare(`
            SELECT * FROM good_till_condition_heads
             WHERE strategy_id=? AND trade_date=?
        `).get(strategy.strategy_id, observation.tradeDate);
        const duplicate = database.prepare(`
            SELECT observation_id FROM observations WHERE observation_id=?
        `).get(durableObservationId);
        if (duplicate) {
            if (previous?.last_observation_id !== durableObservationId) {
                throw new Error('good-till quote replay is older than its daily head');
            }
            replayedStrategyCount += 1;
            continue;
        }
        if (
            previous &&
            (previous.arm_strategy_revision !== strategy.revision ||
                previous.stream_epoch !== observation.streamEpoch ||
                observation.exchangeTimeMs < previous.last_exchange_epoch_ms ||
                observation.sequence <= previous.last_local_sequence)
        ) {
            throw new Error('good-till quote lineage, arm, or ordering changed');
        }
        if (previous?.state === 'triggered') continue;
        const evaluation = evaluateSmartOrderQuickCondition(
            definition.parameters.condition,
            {
                field: projection.field,
                localUnit: projection.localUnit,
                mappingRevision: observation.mappingRevision,
                mappingDefinitionSha256:
                    observation.mappingDefinitionSha256,
                value: projection.value,
            },
        );
        const evidenceHash = sha256Canonical(
            {
                apiGeneration,
                confirmationSnapshotHash:
                    strategy.confirmation_snapshot_hash,
                observation,
                strategyId: strategy.strategy_id,
                strategyRevision: strategy.revision,
                tradeDate: observation.tradeDate,
            },
            'good-till condition evidence',
        );
        database.prepare(`
            INSERT INTO observations(
                observation_id, strategy_id, contract_key, field_name,
                value_decimal, exchange_epoch_ms, broker_epoch_ms,
                receive_epoch_ms, local_sequence, api_generation,
                evidence_hash, created_at_epoch_ms
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).run(
            durableObservationId,
            strategy.strategy_id,
            observation.contractKey,
            condition.field,
            projection.value,
            observation.exchangeTimeMs,
            observation.exchangeTimeMs,
            observation.receiveTimeMs,
            observation.sequence,
            apiGeneration,
            evidenceHash,
            now,
        );
        const transition = projectSmartOrderQuickConditionTransition({
            activationPolicy: definition.parameters.activationPolicy,
            previousState: previous?.state ?? null,
            conditionTrue: evaluation.conditionTrue,
        });
        let activationId = null;
        if (transition.triggerNow) {
            const runtime = database.prepare(`
                SELECT reconciliation_evidence_hash FROM runtime_epochs
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state='ready'
            `).get(runtimeEpochId, senderFence, apiGeneration);
            const resumeArm = database.prepare(`
                SELECT authority_id, authority_payload_hash
                  FROM authority_consumptions
                 WHERE authority_kind='strategy_resume_arm'
                   AND consumed_by=? AND runtime_epoch_id=?
                 ORDER BY consumed_at_epoch_ms DESC, authority_id DESC
                 LIMIT 1
            `).get(strategy.strategy_id, runtimeEpochId);
            const risk = runtimeRiskPolicyView(database);
            if (
                !runtime?.reconciliation_evidence_hash ||
                !resumeArm ||
                risk.state !== 'current' ||
                risk.policy === null ||
                risk.policyHash === null
            ) {
                throw new Error(
                    'good-till activation requires current reconciliation, risk, and user arm',
                );
            }
            const remaining = progress.remaining_target_shares;
            const perOrderMaximum = safeInteger(
                Number(definition.parameters.perOrderMaxBaseShares),
                'goodTill.perOrderMaxBaseShares',
                { minimum: 1 },
            );
            const baseShares = Math.min(remaining, perOrderMaximum);
            const contractUnit = safeInteger(
                Number(definition.parameters.order.contractUnit),
                'goodTill.order.contractUnit',
                { minimum: 1 },
            );
            if (baseShares % contractUnit !== 0) {
                throw new Error('good-till final remainder is not a Common lot');
            }
            const order = Object.freeze({
                baseShares,
                commonLots: baseShares / contractUnit,
                contractKey: database.prepare(`
                    SELECT contract_key FROM canonical_confirmation_snapshots
                     WHERE strategy_id=? AND state='accepted'
                       AND snapshot_hash=?
                `).get(
                    strategy.strategy_id,
                    strategy.confirmation_snapshot_hash,
                )?.contract_key,
                contractUnit,
                limitPrice: definition.parameters.order.limitPrice,
                orderCond: 'Cash',
                orderLot: 'Common',
                policyRevision: risk.policy.policyRevision,
                priceType: 'LMT',
                side: 'Buy',
                timeInForce: definition.parameters.order.timeInForce,
            });
            const payload = canonicalGoodTillIntentPayload({
                schemaVersion: GOOD_TILL_INTENT_SCHEMA_VERSION,
                strategyId: strategy.strategy_id,
                confirmationSnapshotHash:
                    strategy.confirmation_snapshot_hash,
                activationTradeDate: observation.tradeDate,
                conditionEvidenceHash: evidenceHash,
                order,
                progress: {
                    targetShares: progress.target_shares,
                    confirmedFilledSharesBefore:
                        progress.confirmed_filled_shares,
                    remainingTargetSharesAfter: remaining - baseShares,
                },
            });
            const payloadJson = canonicalJson(payload, 'good-till intent payload');
            const payloadHash = `sha256:${createHash('sha256')
                .update(payloadJson)
                .digest('hex')}`;
            const lineage = sha256Canonical(
                [strategy.strategy_id, observation.tradeDate],
                'good-till daily activation lineage',
            ).slice(7);
            activationId = `activation:good-till:${lineage}`;
            const intentId = `intent:good-till:${lineage}`;
            const reservation = goodTillWorstCaseReservation(order, risk.policy);
            const prepared = prepareIntent(
                database,
                {
                    activation: {
                        activationId,
                        logicalKey: `good-till:${observation.tradeDate}`,
                        generation: Number(observation.tradeDate.replaceAll('-', '')),
                        evidenceHash,
                    },
                    apiGeneration,
                    intent: {
                        intentId,
                        operationKind: 'place',
                        ownerKind: 'activation',
                        payload,
                        payloadHash,
                        clientRequestId: `good-till:${lineage}`,
                        accountBrokerRef: strategy.account_broker_ref,
                        accountIdRef: strategy.account_id_ref,
                        tradeDate: observation.tradeDate,
                        contractKey: order.contractKey,
                        side: 'Buy',
                    },
                    nowEpochMs: now,
                    reservation: {
                        reservationId: `reservation:good-till:${lineage}`,
                        strategyId: strategy.strategy_id,
                        intentId,
                        accountBrokerRef: strategy.account_broker_ref,
                        accountIdRef: strategy.account_id_ref,
                        identityGroupId: strategy.identity_group_id,
                        policyRevision: risk.policy.policyRevision,
                        policyHash: risk.executionPolicyHash,
                        ...reservation,
                    },
                    runtimeEpochId,
                    senderFence,
                    strategyId: strategy.strategy_id,
                },
                true,
            );
            rearmPreparedIntent(
                database,
                {
                    apiGeneration,
                    confirmationSnapshotHash:
                        strategy.confirmation_snapshot_hash,
                    expectedIntentRevision: prepared.revision,
                    intentId,
                    nowEpochMs: now,
                    rearmAuthorizationId: `rearm:good-till:${lineage}`,
                    rearmRequestId: `rearm-request:good-till:${lineage}`,
                    reconciliationEvidenceHash:
                        runtime.reconciliation_evidence_hash,
                    riskRevision: risk.policy.policyRevision,
                    runtimeEpochId,
                    senderFence,
                    userRearmEvidenceHash:
                        resumeArm.authority_payload_hash,
                },
                true,
            );
            const progressUpdate = database.prepare(`
                UPDATE good_till_progress_heads
                   SET daily_state='intent_prepared', active_trade_date=?,
                       active_activation_id=?, active_intent_id=?,
                       active_accounted_filled_shares=0,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE strategy_id=? AND revision=? AND daily_state='waiting'
            `).run(
                observation.tradeDate,
                activationId,
                intentId,
                now,
                strategy.strategy_id,
                progress.revision,
            );
            if (Number(progressUpdate.changes) !== 1) {
                throw new Error('good-till activation progress lost its CAS');
            }
            preparedIntentCount += 1;
        }
        if (!previous) {
            database.prepare(`
                INSERT INTO good_till_condition_heads(
                    strategy_id, trade_date, state, activation_policy,
                    arm_strategy_revision, stream_epoch, field_name,
                    comparator, threshold_decimal, local_unit,
                    mapping_revision, mapping_definition_hash,
                    last_observation_id, last_exchange_epoch_ms,
                    last_receive_epoch_ms, last_local_sequence,
                    last_value_decimal, last_condition_true, activation_id,
                    created_at_epoch_ms, updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            `).run(
                strategy.strategy_id,
                observation.tradeDate,
                transition.nextState,
                definition.parameters.activationPolicy,
                strategy.revision,
                observation.streamEpoch,
                condition.field,
                condition.comparator,
                condition.threshold,
                condition.localUnit,
                condition.mappingRevision,
                condition.mappingDefinitionSha256,
                durableObservationId,
                observation.exchangeTimeMs,
                observation.receiveTimeMs,
                observation.sequence,
                projection.value,
                evaluation.conditionTrue ? 1 : 0,
                activationId,
                now,
                now,
            );
        } else {
            const updated = database.prepare(`
                UPDATE good_till_condition_heads
                   SET state=?, last_observation_id=?,
                       last_exchange_epoch_ms=?, last_receive_epoch_ms=?,
                       last_local_sequence=?, last_value_decimal=?,
                       last_condition_true=?, activation_id=?,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE strategy_id=? AND trade_date=? AND revision=?
            `).run(
                transition.nextState,
                durableObservationId,
                observation.exchangeTimeMs,
                observation.receiveTimeMs,
                observation.sequence,
                projection.value,
                evaluation.conditionTrue ? 1 : 0,
                activationId,
                now,
                strategy.strategy_id,
                observation.tradeDate,
                previous.revision,
            );
            if (Number(updated.changes) !== 1) {
                throw new Error('good-till condition head lost its CAS');
            }
        }
        observedStrategyCount += 1;
    }
    return Object.freeze({
        observedStrategyCount,
        replayedStrategyCount,
        preparedIntentCount,
        blockedStrategyCount,
    });
}

function recordMultiConditionQuoteObservationInTransaction(
    database,
    { apiGeneration, now, observation, runtimeEpochId, senderFence },
) {
    const strategies = database.prepare(`
        SELECT * FROM strategies
         WHERE strategy_kind='multi_condition' AND state='monitoring'
           AND confirmation_snapshot_hash IS NOT NULL
         ORDER BY strategy_id
    `).all();
    let observedStrategyCount = 0;
    let disabledStrategyCount = 0;
    let replayedStrategyCount = 0;
    let triggeredStrategyCount = 0;
    for (const strategy of strategies) {
        const definition = parseStoredCanonicalObject(
            strategy.definition_json,
            'multi-condition strategy definition',
        );
        assertCanonicalSmartOrderDraft(definition, {
            expectedKind: 'multi_condition',
        });
        const matching = definition.parameters.conditions
            .map((entry, conditionIndex) => ({
                conditionIndex,
                entry,
                condition: canonicalSmartOrderQuickCondition(entry.condition),
            }))
            .filter(({ entry }) => entry.monitorContractKey === observation.contractKey);
        if (matching.length === 0) continue;
        const validity = definition.parameters.validity;
        if (
            observation.tradeDate < validity.startDate ||
            observation.tradeDate > validity.endDate
        ) {
            continue;
        }
        assertCanonicalConfirmationCurrent(database, {
            strategyId: strategy.strategy_id,
            snapshotHash: strategy.confirmation_snapshot_hash,
            runtimeEpochId,
            senderFence,
            apiGeneration,
            nowEpochMs: canonicalConfirmationClockNowEpochMs(now),
        });
        let changed = false;
        let replayed = true;
        for (const { conditionIndex, entry, condition } of matching) {
            const projection = observation.projections.find(
                (candidate) => candidate.field === condition.field,
            );
            if (!projection) {
                if (
                    observation.disabledFields.some(
                        (candidate) => candidate.field === condition.field,
                    )
                ) {
                    database.prepare(`
                        DELETE FROM multi_condition_leg_heads
                         WHERE strategy_id=? AND condition_index=?
                    `).run(strategy.strategy_id, conditionIndex);
                    database.prepare(`
                        DELETE FROM multi_condition_group_heads
                         WHERE strategy_id=? AND state<>'triggered'
                    `).run(strategy.strategy_id);
                    disabledStrategyCount += 1;
                    replayed = false;
                    changed = true;
                    continue;
                }
                throw new Error(
                    'multi-condition field is absent without disable evidence',
                );
            }
            const durableObservationId = `multi-observation:${sha256Canonical(
                [
                    strategy.strategy_id,
                    observation.observationId,
                    observation.contractKey,
                    condition.field,
                ],
                'multi-condition observation identity',
            ).slice(7)}`;
            const previous = database.prepare(`
                SELECT * FROM multi_condition_leg_heads
                 WHERE strategy_id=? AND condition_index=?
            `).get(strategy.strategy_id, conditionIndex);
            const duplicate = database.prepare(`
                SELECT * FROM observations WHERE observation_id=?
            `).get(durableObservationId);
            if (duplicate && previous?.last_observation_id === durableObservationId) {
                continue;
            }
            replayed = false;
            if (
                previous &&
                (previous.arm_strategy_revision !== strategy.revision ||
                    previous.monitor_contract_key !== entry.monitorContractKey ||
                    previous.trade_date !== observation.tradeDate ||
                    previous.stream_epoch !== observation.streamEpoch ||
                    observation.exchangeTimeMs < previous.last_exchange_epoch_ms ||
                    observation.sequence <= previous.last_local_sequence)
            ) {
                throw new Error('multi-condition quote lineage, arm, or ordering changed');
            }
            const evaluation = evaluateSmartOrderQuickCondition(entry.condition, {
                field: projection.field,
                localUnit: projection.localUnit,
                mappingRevision: observation.mappingRevision,
                mappingDefinitionSha256: observation.mappingDefinitionSha256,
                value: projection.value,
            });
            const evidenceHash = sha256Canonical(
                {
                    apiGeneration,
                    observation,
                    strategyId: strategy.strategy_id,
                    strategyRevision: strategy.revision,
                },
                'multi-condition leg observation evidence',
            );
            if (!duplicate) {
                database.prepare(`
                    INSERT INTO observations(
                        observation_id, strategy_id, contract_key, field_name,
                        value_decimal, exchange_epoch_ms, broker_epoch_ms,
                        receive_epoch_ms, local_sequence, api_generation,
                        evidence_hash, created_at_epoch_ms
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                `).run(
                    durableObservationId,
                    strategy.strategy_id,
                    observation.contractKey,
                    condition.field,
                    projection.value,
                    observation.exchangeTimeMs,
                    observation.exchangeTimeMs,
                    observation.receiveTimeMs,
                    observation.sequence,
                    apiGeneration,
                    evidenceHash,
                    now,
                );
            } else if (
                duplicate.strategy_id !== strategy.strategy_id ||
                duplicate.contract_key !== observation.contractKey ||
                duplicate.field_name !== condition.field ||
                duplicate.value_decimal !== projection.value ||
                duplicate.evidence_hash !== evidenceHash
            ) {
                throw new Error('multi-condition observation identity collision');
            }
            if (!previous) {
                database.prepare(`
                    INSERT INTO multi_condition_leg_heads(
                        strategy_id, condition_index, arm_strategy_revision,
                        monitor_contract_key, trade_date, stream_epoch,
                        field_name, comparator, threshold_decimal, local_unit,
                        mapping_revision, mapping_definition_hash,
                        last_observation_id, last_exchange_epoch_ms,
                        last_receive_epoch_ms, last_local_sequence,
                        last_value_decimal, last_condition_true,
                        created_at_epoch_ms, updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
                `).run(
                    strategy.strategy_id,
                    conditionIndex,
                    strategy.revision,
                    entry.monitorContractKey,
                    observation.tradeDate,
                    observation.streamEpoch,
                    condition.field,
                    condition.comparator,
                    condition.threshold,
                    condition.localUnit,
                    condition.mappingRevision,
                    condition.mappingDefinitionSha256,
                    durableObservationId,
                    observation.exchangeTimeMs,
                    observation.receiveTimeMs,
                    observation.sequence,
                    projection.value,
                    evaluation.conditionTrue ? 1 : 0,
                    now,
                    now,
                );
            } else {
                const update = database.prepare(`
                    UPDATE multi_condition_leg_heads
                       SET last_observation_id=?, last_exchange_epoch_ms=?,
                           last_receive_epoch_ms=?, last_local_sequence=?,
                           last_value_decimal=?, last_condition_true=?,
                           updated_at_epoch_ms=?, revision=revision+1
                     WHERE strategy_id=? AND condition_index=? AND revision=?
                `).run(
                    durableObservationId,
                    observation.exchangeTimeMs,
                    observation.receiveTimeMs,
                    observation.sequence,
                    projection.value,
                    evaluation.conditionTrue ? 1 : 0,
                    now,
                    strategy.strategy_id,
                    conditionIndex,
                    previous.revision,
                );
                if (Number(update.changes) !== 1) {
                    throw new Error('multi-condition leg head lost its CAS');
                }
            }
            changed = true;
        }
        if (replayed) {
            replayedStrategyCount += 1;
            continue;
        }
        if (!changed) continue;
        const heads = database.prepare(`
            SELECT * FROM multi_condition_leg_heads
             WHERE strategy_id=? ORDER BY condition_index
        `).all(strategy.strategy_id);
        if (
            heads.length !== definition.parameters.conditions.length ||
            heads.some((head, index) => head.condition_index !== index)
        ) {
            continue;
        }
        const tradeDates = new Set(heads.map((head) => head.trade_date));
        const streamEpochs = new Set(heads.map((head) => head.stream_epoch));
        const exchangeTimes = heads.map((head) => head.last_exchange_epoch_ms);
        const receiveTimes = heads.map((head) => head.last_receive_epoch_ms);
        const coherent =
            tradeDates.size === 1 &&
            streamEpochs.size === 1 &&
            Math.max(...receiveTimes) <= now &&
            now - Math.min(...receiveTimes) <= 3_000 &&
            (definition.parameters.operator !== 'AND' ||
                (Math.max(...exchangeTimes) - Math.min(...exchangeTimes) <= 3_000 &&
                    Math.max(...receiveTimes) - Math.min(...receiveTimes) <= 3_000));
        if (!coherent) continue;
        const conditionTrue =
            definition.parameters.operator === 'AND'
                ? heads.every((head) => head.last_condition_true === 1)
                : heads.some((head) => head.last_condition_true === 1);
        const group = database.prepare(`
            SELECT * FROM multi_condition_group_heads WHERE strategy_id=?
        `).get(strategy.strategy_id);
        if (group?.state === 'triggered') continue;
        if (
            group &&
            (group.arm_strategy_revision !== strategy.revision ||
                group.operator !== definition.parameters.operator ||
                group.condition_count !== heads.length)
        ) {
            throw new Error('multi-condition group arm or definition changed');
        }
        const transition = projectSmartOrderQuickConditionTransition({
            activationPolicy: definition.parameters.activationPolicy,
            previousState: group?.state ?? null,
            conditionTrue,
        });
        const evaluationHash = sha256Canonical(
            {
                operator: definition.parameters.operator,
                observations: heads.map((head) => ({
                    conditionIndex: head.condition_index,
                    observationId: head.last_observation_id,
                    conditionTrue: head.last_condition_true === 1,
                })),
                strategyId: strategy.strategy_id,
                strategyRevision: strategy.revision,
                tradeDate: heads[0].trade_date,
                streamEpoch: heads[0].stream_epoch,
            },
            'multi-condition group evaluation',
        );
        let activationId = null;
        if (transition.triggerNow) {
            activationId = `activation:multi-condition:${sha256Canonical(
                [
                    strategy.strategy_id,
                    strategy.confirmation_snapshot_hash,
                    strategy.revision,
                ],
                'multi-condition activation identity',
            ).slice(7)}`;
            database.prepare(`
                INSERT INTO activations(
                    activation_id, strategy_id, logical_key, state,
                    generation, evidence_hash, created_at_epoch_ms,
                    updated_at_epoch_ms, revision
                ) VALUES (?, ?, 'multi-condition-edge', 'triggered', ?, ?, ?, ?, 0)
            `).run(
                activationId,
                strategy.strategy_id,
                strategy.revision,
                evaluationHash,
                now,
                now,
            );
            insertTransitionJournalEvent(database, {
                entityKind: 'activation',
                entityId: activationId,
                revision: 0,
                reasonCode:
                    definition.parameters.operator === 'OR'
                        ? 'MULTI_CONDITION_OR_EDGE'
                        : 'MULTI_CONDITION_AND_COHERENT_EDGE',
                summaryCode: 'multi_condition_triggered',
                nowEpochMs: now,
                payloadHash: evaluationHash,
                eventSuffix: 'triggered',
                exchangeEpochMs: Math.max(...exchangeTimes),
            });
            triggeredStrategyCount += 1;
        }
        const definitionHash = sha256Canonical(
            definition.parameters.conditions,
            'multi-condition definition',
        );
        if (!group) {
            database.prepare(`
                INSERT INTO multi_condition_group_heads(
                    strategy_id, state, activation_policy,
                    arm_strategy_revision, operator, condition_count,
                    definition_hash, last_trade_date, last_stream_epoch,
                    last_evaluation_hash, last_condition_true, activation_id,
                    created_at_epoch_ms, updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            `).run(
                strategy.strategy_id,
                transition.nextState,
                definition.parameters.activationPolicy,
                strategy.revision,
                definition.parameters.operator,
                heads.length,
                definitionHash,
                heads[0].trade_date,
                heads[0].stream_epoch,
                evaluationHash,
                conditionTrue ? 1 : 0,
                activationId,
                now,
                now,
            );
        } else {
            const updated = database.prepare(`
                UPDATE multi_condition_group_heads
                   SET state=?, last_trade_date=?, last_stream_epoch=?,
                       last_evaluation_hash=?, last_condition_true=?,
                       activation_id=?, updated_at_epoch_ms=?, revision=revision+1
                 WHERE strategy_id=? AND revision=?
            `).run(
                transition.nextState,
                heads[0].trade_date,
                heads[0].stream_epoch,
                evaluationHash,
                conditionTrue ? 1 : 0,
                activationId,
                now,
                strategy.strategy_id,
                group.revision,
            );
            if (Number(updated.changes) !== 1) {
                throw new Error('multi-condition group head lost its CAS');
            }
        }
        observedStrategyCount += 1;
    }
    return Object.freeze({
        observedStrategyCount,
        disabledStrategyCount,
        replayedStrategyCount,
        triggeredStrategyCount,
    });
}

function taipeiWallTimeAt(epochMs) {
    const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone: 'Asia/Taipei',
        hour12: false,
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
    }).formatToParts(new Date(epochMs));
    const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
    return `${values.hour}:${values.minute}:${values.second}`;
}

function taipeiTradeDateAt(epochMs) {
    const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone: 'Asia/Taipei',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
    }).formatToParts(
        new Date(safeInteger(epochMs, 'taipeiTradeDateAt.epochMs')),
    );
    const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
    return `${values.year}-${values.month}-${values.day}`;
}

function parentChildDispatchWindowIsCurrent(
    database,
    { intentId, nowEpochMs, payloadJson, strategyId },
) {
    const lineage = database.prepare(`
        SELECT strategies.strategy_kind, strategies.definition_json,
               progress.state AS progress_state,
               progress.parent_activation_trade_date,
               progress.parent_intent_id,
               progress.parent_settlement_hash,
               progress.child_activation_trade_date,
               progress.child_intent_id
          FROM strategies
     LEFT JOIN parent_child_progress_heads AS progress USING(strategy_id)
         WHERE strategies.strategy_id=?
    `).get(strategyId);
    if (!lineage) throw new Error('dispatch strategy is missing');
    if (lineage.strategy_kind !== 'parent_child') return true;
    const definition = parseStoredCanonicalObject(
        lineage.definition_json,
        'parent-child dispatch definition',
    );
    assertCanonicalSmartOrderDraft(definition, {
        expectedKind: 'parent_child',
    });
    const payload = canonicalParentChildIntentPayload(
        parseStoredCanonicalObject(
            payloadJson,
            'parent-child dispatch intent payload',
        ),
    );
    const expectedState =
        payload.leg === 'parent'
            ? 'parent_intent_prepared'
            : 'child_intent_prepared';
    const progressIntentId =
        payload.leg === 'parent'
            ? lineage.parent_intent_id
            : lineage.child_intent_id;
    const progressActivationTradeDate =
        payload.leg === 'parent'
            ? lineage.parent_activation_trade_date
            : lineage.child_activation_trade_date;
    if (
        payload.strategyId !== strategyId ||
        lineage.progress_state !== expectedState ||
        progressIntentId !== intentId ||
        progressActivationTradeDate !== payload.activationTradeDate ||
        (payload.leg === 'child' &&
            lineage.parent_settlement_hash !== payload.parentSettlementHash)
    ) {
        return false;
    }
    const trustedNow = safeInteger(
        nowEpochMs,
        'parentChildDispatchWindow.nowEpochMs',
    );
    return parentChildIntentDispatchWindowOpen({
        activationTradeDate: payload.activationTradeDate,
        childCutoffTime: definition.parameters.child.cutoffTime,
        leg: payload.leg,
        parentEndDate: definition.parameters.parentValidity.endDate,
        parentStartDate: definition.parameters.parentValidity.startDate,
        tradeDate: taipeiTradeDateAt(trustedNow),
        wallTime: taipeiWallTimeAt(trustedNow),
    });
}

function recordParentChildQuoteObservationInTransaction(
    database,
    { apiGeneration, now, observation, runtimeEpochId, senderFence },
) {
    const strategies = database.prepare(`
        SELECT strategies.*, progress.*,
               progress.state AS progress_state,
               strategies.revision AS strategy_revision,
               progress.revision AS progress_revision
          FROM strategies
          JOIN parent_child_progress_heads AS progress USING(strategy_id)
         WHERE strategies.strategy_kind='parent_child'
           AND strategies.state='monitoring'
           AND strategies.confirmation_snapshot_hash IS NOT NULL
           AND progress.state IN ('waiting_parent','child_monitoring')
         ORDER BY strategies.strategy_id
    `).all();
    let observedStrategyCount = 0;
    let replayedStrategyCount = 0;
    let preparedIntentCount = 0;
    let blockedStrategyCount = 0;
    for (const strategy of strategies) {
        const definition = parseStoredCanonicalObject(
            strategy.definition_json,
            'parent-child strategy definition',
        );
        assertCanonicalSmartOrderDraft(definition, {
            expectedKind: 'parent_child',
        });
        const legKind =
            strategy.progress_state === 'waiting_parent' ? 'parent' : 'child';
        const leg = definition.parameters[legKind];
        if (leg.monitorContractKey !== observation.contractKey) continue;
        if (
            !parentChildIntentDispatchWindowOpen({
                activationTradeDate:
                    legKind === 'parent'
                        ? observation.tradeDate
                        : strategy.child_activation_trade_date,
                childCutoffTime: definition.parameters.child.cutoffTime,
                leg: legKind,
                parentEndDate: definition.parameters.parentValidity.endDate,
                parentStartDate:
                    definition.parameters.parentValidity.startDate,
                tradeDate: observation.tradeDate,
                wallTime: taipeiWallTimeAt(observation.exchangeTimeMs),
            })
        ) {
            blockedStrategyCount += 1;
            continue;
        }
        try {
            assertCanonicalConfirmationCurrent(database, {
                strategyId: strategy.strategy_id,
                snapshotHash: strategy.confirmation_snapshot_hash,
                runtimeEpochId,
                senderFence,
                apiGeneration,
                nowEpochMs: canonicalConfirmationClockNowEpochMs(now),
            });
        } catch {
            blockedStrategyCount += 1;
            continue;
        }
        const condition = canonicalSmartOrderQuickCondition(leg.condition);
        const projection = observation.projections.find(
            (entry) => entry.field === condition.field,
        );
        if (!projection) {
            if (
                observation.disabledFields.some(
                    (entry) => entry.field === condition.field,
                )
            ) {
                blockedStrategyCount += 1;
                continue;
            }
            throw new Error(
                'parent-child condition field is absent without disable evidence',
            );
        }
        const durableObservationId = `parent-child-observation:${sha256Canonical(
            [strategy.strategy_id, legKind, observation.observationId],
            'parent-child observation identity',
        ).slice(7)}`;
        const previous = database.prepare(`
            SELECT * FROM parent_child_condition_heads
             WHERE strategy_id=? AND leg_kind=?
        `).get(strategy.strategy_id, legKind);
        const duplicate = database.prepare(`
            SELECT observation_id FROM observations WHERE observation_id=?
        `).get(durableObservationId);
        if (duplicate) {
            if (previous?.last_observation_id !== durableObservationId) {
                throw new Error(
                    'parent-child quote replay is older than its durable leg head',
                );
            }
            replayedStrategyCount += 1;
            continue;
        }
        if (
            previous &&
            (previous.arm_strategy_revision !== strategy.strategy_revision ||
                previous.trade_date !== observation.tradeDate ||
                previous.stream_epoch !== observation.streamEpoch ||
                observation.exchangeTimeMs < previous.last_exchange_epoch_ms ||
                observation.sequence <= previous.last_local_sequence)
        ) {
            throw new Error(
                'parent-child quote lineage, arm, or ordering changed',
            );
        }
        if (previous?.state === 'triggered') continue;
        const evaluation = evaluateSmartOrderQuickCondition(leg.condition, {
            field: projection.field,
            localUnit: projection.localUnit,
            mappingRevision: observation.mappingRevision,
            mappingDefinitionSha256: observation.mappingDefinitionSha256,
            value: projection.value,
        });
        const evidenceHash = sha256Canonical(
            {
                apiGeneration,
                confirmationSnapshotHash: strategy.confirmation_snapshot_hash,
                legKind,
                observation,
                parentSettlementHash: strategy.parent_settlement_hash,
                strategyId: strategy.strategy_id,
                strategyRevision: strategy.strategy_revision,
            },
            'parent-child condition evidence',
        );
        database.prepare(`
            INSERT INTO observations(
                observation_id, strategy_id, contract_key, field_name,
                value_decimal, exchange_epoch_ms, broker_epoch_ms,
                receive_epoch_ms, local_sequence, api_generation,
                evidence_hash, created_at_epoch_ms
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).run(
            durableObservationId,
            strategy.strategy_id,
            observation.contractKey,
            condition.field,
            projection.value,
            observation.exchangeTimeMs,
            observation.exchangeTimeMs,
            observation.receiveTimeMs,
            observation.sequence,
            apiGeneration,
            evidenceHash,
            now,
        );
        const transition = projectSmartOrderQuickConditionTransition({
            activationPolicy: definition.parameters.activationPolicy,
            previousState: previous?.state ?? null,
            conditionTrue: evaluation.conditionTrue,
        });
        let activationId = null;
        if (transition.triggerNow) {
            const runtime = database.prepare(`
                SELECT reconciliation_evidence_hash FROM runtime_epochs
                 WHERE runtime_epoch_id=? AND sender_fence=?
                   AND api_generation=? AND state='ready'
            `).get(runtimeEpochId, senderFence, apiGeneration);
            const resumeArm = database.prepare(`
                SELECT authority_id, authority_payload_hash
                  FROM authority_consumptions
                 WHERE authority_kind='strategy_resume_arm'
                   AND consumed_by=? AND runtime_epoch_id=?
                 ORDER BY consumed_at_epoch_ms DESC, authority_id DESC
                 LIMIT 1
            `).get(strategy.strategy_id, runtimeEpochId);
            const risk = runtimeRiskPolicyView(database);
            if (
                !runtime?.reconciliation_evidence_hash ||
                !resumeArm ||
                risk.state !== 'current' ||
                risk.policy === null ||
                risk.policyHash === null
            ) {
                throw new Error(
                    'parent-child activation requires current reconciliation, risk, and user arm',
                );
            }
            const order = Object.freeze({
                baseShares: safeInteger(
                    Number(leg.order.baseShares),
                    `parentChild.${legKind}.baseShares`,
                    { minimum: 1 },
                ),
                commonLots: safeInteger(
                    Number(leg.order.commonLots),
                    `parentChild.${legKind}.commonLots`,
                    { minimum: 1 },
                ),
                contractKey:
                    legKind === 'parent'
                        ? database.prepare(`
                              SELECT contract_key
                                FROM canonical_confirmation_snapshots
                               WHERE strategy_id=? AND state='accepted'
                                 AND snapshot_hash=?
                          `).get(
                              strategy.strategy_id,
                              strategy.confirmation_snapshot_hash,
                          )?.contract_key
                        : database.prepare(`
                              SELECT contract_key FROM exit_claims
                               WHERE exit_claim_id=?
                          `).get(strategy.child_exit_claim_id)?.contract_key,
                contractUnit: safeInteger(
                    Number(leg.order.contractUnit),
                    `parentChild.${legKind}.contractUnit`,
                    { minimum: 1 },
                ),
                limitPrice: leg.order.limitPrice,
                orderCond: 'Cash',
                orderLot: 'Common',
                policyRevision: risk.policy.policyRevision,
                priceType: 'LMT',
                side: legKind === 'parent' ? 'Buy' : 'Sell',
                timeInForce: leg.order.timeInForce,
            });
            const payload = canonicalParentChildIntentPayload({
                schemaVersion: PARENT_CHILD_INTENT_SCHEMA_VERSION,
                strategyId: strategy.strategy_id,
                confirmationSnapshotHash: strategy.confirmation_snapshot_hash,
                leg: legKind,
                activationTradeDate: observation.tradeDate,
                conditionEvidenceHash: evidenceHash,
                parentSettlementHash:
                    legKind === 'parent'
                        ? null
                        : strategy.parent_settlement_hash,
                childPositionLineageId:
                    legKind === 'parent'
                        ? null
                        : strategy.child_position_lineage_id,
                order,
            });
            const payloadJson = canonicalJson(
                payload,
                'parent-child intent payload',
            );
            const payloadHash = `sha256:${createHash('sha256')
                .update(payloadJson)
                .digest('hex')}`;
            const lineage = sha256Canonical(
                [strategy.strategy_id, legKind, observation.tradeDate],
                'parent-child activation lineage',
            ).slice(7);
            activationId = `activation:parent-child:${lineage}`;
            const intentId = `intent:parent-child:${lineage}`;
            let exitClaim;
            let reservation;
            if (legKind === 'parent') {
                const exposure = goodTillWorstCaseReservation(order, risk.policy);
                reservation = {
                    reservationId: `reservation:parent-child:${lineage}`,
                    strategyId: strategy.strategy_id,
                    intentId,
                    accountBrokerRef: strategy.account_broker_ref,
                    accountIdRef: strategy.account_id_ref,
                    identityGroupId: strategy.identity_group_id,
                    policyRevision: risk.policy.policyRevision,
                    policyHash: risk.executionPolicyHash,
                    ...exposure,
                };
            } else {
                const claim = database.prepare(`
                    SELECT claims.*, groups.protection_group_id,
                           groups.revision AS group_revision,
                           generations.revision AS generation_revision
                      FROM exit_claims AS claims
                      JOIN protection_groups AS groups
                        ON groups.exit_claim_id=claims.exit_claim_id
                      JOIN protection_remainder_generations AS generations
                        ON generations.protection_group_id=groups.protection_group_id
                       AND generations.remainder_generation=groups.current_generation
                     WHERE claims.exit_claim_id=?
                       AND claims.state='monitoring_reserved'
                       AND claims.intent_id IS NULL
                       AND groups.state='monitoring'
                       AND generations.state='monitoring'
                `).get(strategy.child_exit_claim_id);
                if (!claim || claim.quantity_shares !== order.baseShares) {
                    throw new Error('parent-child child claim is no longer current');
                }
                exitClaim = {
                    accountBrokerRef: claim.account_broker_ref,
                    accountIdRef: claim.account_id_ref,
                    allocationStartShare: claim.allocation_start_share,
                    candidateEvaluations: [
                        {
                            evidenceHash,
                            legId: 'child',
                            observedAtEpochMs: observation.exchangeTimeMs,
                        },
                    ],
                    contractKey: claim.contract_key,
                    evidenceHash,
                    exitClaimId: claim.exit_claim_id,
                    expectedGenerationRevision: claim.generation_revision,
                    expectedGroupRevision: claim.group_revision,
                    expectedRevision: claim.revision,
                    obligationId: claim.obligation_id,
                    positionLineageId: claim.position_lineage_id,
                    protectionGroupId: claim.protection_group_id,
                    quantityShares: claim.quantity_shares,
                    remainderGeneration: claim.remainder_generation,
                };
                exitClaim.evidenceHash =
                    canonicalProtectionOcoSelection(exitClaim).selectionHash;
            }
            const prepared = prepareIntent(
                database,
                {
                    activation: {
                        activationId,
                        logicalKey: `parent-child:${legKind}:${observation.tradeDate}`,
                        generation:
                            legKind === 'parent'
                                ? 0
                                : exitClaim.remainderGeneration,
                        evidenceHash,
                    },
                    apiGeneration,
                    ...(exitClaim ? { exitClaim } : {}),
                    intent: {
                        intentId,
                        operationKind: 'place',
                        ownerKind: 'activation',
                        payload,
                        payloadHash,
                        clientRequestId: `parent-child:${lineage}`,
                        accountBrokerRef: strategy.account_broker_ref,
                        accountIdRef: strategy.account_id_ref,
                        tradeDate: observation.tradeDate,
                        contractKey: order.contractKey,
                        side: order.side,
                    },
                    nowEpochMs: now,
                    ...(reservation ? { reservation } : {}),
                    runtimeEpochId,
                    senderFence,
                    strategyId: strategy.strategy_id,
                },
                true,
            );
            rearmPreparedIntent(
                database,
                {
                    apiGeneration,
                    confirmationSnapshotHash:
                        strategy.confirmation_snapshot_hash,
                    expectedIntentRevision: prepared.revision,
                    intentId,
                    nowEpochMs: now,
                    rearmAuthorizationId: `rearm:parent-child:${lineage}`,
                    rearmRequestId: `rearm-request:parent-child:${lineage}`,
                    reconciliationEvidenceHash:
                        runtime.reconciliation_evidence_hash,
                    riskRevision: risk.policy.policyRevision,
                    runtimeEpochId,
                    senderFence,
                    userRearmEvidenceHash: resumeArm.authority_payload_hash,
                },
                true,
            );
            const progressUpdated = database.prepare(`
                UPDATE parent_child_progress_heads
                   SET state=?, parent_activation_trade_date=
                           CASE WHEN ?='parent' THEN ? ELSE parent_activation_trade_date END,
                       parent_activation_id=
                           CASE WHEN ?='parent' THEN ? ELSE parent_activation_id END,
                       parent_intent_id=
                           CASE WHEN ?='parent' THEN ? ELSE parent_intent_id END,
                       child_activation_id=
                           CASE WHEN ?='child' THEN ? ELSE child_activation_id END,
                       child_intent_id=
                           CASE WHEN ?='child' THEN ? ELSE child_intent_id END,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE strategy_id=? AND revision=? AND state=?
            `).run(
                legKind === 'parent'
                    ? 'parent_intent_prepared'
                    : 'child_intent_prepared',
                legKind,
                observation.tradeDate,
                legKind,
                activationId,
                legKind,
                intentId,
                legKind,
                activationId,
                legKind,
                intentId,
                now,
                strategy.strategy_id,
                strategy.progress_revision,
                legKind === 'parent' ? 'waiting_parent' : 'child_monitoring',
            );
            if (Number(progressUpdated.changes) !== 1) {
                throw new Error('parent-child activation progress lost its CAS');
            }
            preparedIntentCount += 1;
        }
        if (!previous) {
            database.prepare(`
                INSERT INTO parent_child_condition_heads(
                    strategy_id, leg_kind, state, activation_policy,
                    arm_strategy_revision, trade_date, stream_epoch,
                    field_name, comparator, threshold_decimal, local_unit,
                    mapping_revision, mapping_definition_hash,
                    last_observation_id, last_exchange_epoch_ms,
                    last_receive_epoch_ms, last_local_sequence,
                    last_value_decimal, last_condition_true, activation_id,
                    created_at_epoch_ms, updated_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            `).run(
                strategy.strategy_id,
                legKind,
                transition.nextState,
                definition.parameters.activationPolicy,
                strategy.strategy_revision,
                observation.tradeDate,
                observation.streamEpoch,
                condition.field,
                condition.comparator,
                condition.threshold,
                condition.localUnit,
                condition.mappingRevision,
                condition.mappingDefinitionSha256,
                durableObservationId,
                observation.exchangeTimeMs,
                observation.receiveTimeMs,
                observation.sequence,
                projection.value,
                evaluation.conditionTrue ? 1 : 0,
                activationId,
                now,
                now,
            );
        } else {
            const updated = database.prepare(`
                UPDATE parent_child_condition_heads
                   SET state=?, last_observation_id=?,
                       last_exchange_epoch_ms=?, last_receive_epoch_ms=?,
                       last_local_sequence=?, last_value_decimal=?,
                       last_condition_true=?, activation_id=?,
                       updated_at_epoch_ms=?, revision=revision+1
                 WHERE strategy_id=? AND leg_kind=? AND revision=?
            `).run(
                transition.nextState,
                durableObservationId,
                observation.exchangeTimeMs,
                observation.receiveTimeMs,
                observation.sequence,
                projection.value,
                evaluation.conditionTrue ? 1 : 0,
                activationId,
                now,
                strategy.strategy_id,
                legKind,
                previous.revision,
            );
            if (Number(updated.changes) !== 1) {
                throw new Error('parent-child condition head lost its CAS');
            }
        }
        observedStrategyCount += 1;
    }
    return Object.freeze({
        observedStrategyCount,
        replayedStrategyCount,
        preparedIntentCount,
        blockedStrategyCount,
    });
}

function recordQuickQuoteObservation(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'apiGeneration',
            'nowEpochMs',
            'observation',
            'runtimeEpochId',
            'senderFence',
        ])
    ) {
        throw new TypeError('quick quote observation input schema is invalid');
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const now = safeInteger(input.nowEpochMs, 'quickQuote.nowEpochMs');
    const observation = canonicalQuickQuoteObservation(input.observation);
    if (
        observation.exchangeTimeMs > observation.receiveTimeMs ||
        observation.receiveTimeMs > now ||
        observation.receiveTimeMs - observation.exchangeTimeMs > 3_000 ||
        now - observation.receiveTimeMs > 3_000
    ) {
        throw new Error('quick quote observation is stale or future-dated');
    }
    return transaction(database, () => {
        if (
            !currentReadySenderMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error('quick quote observation requires current ready Runtime');
        }
        const strategies = database.prepare(`
            SELECT * FROM strategies
             WHERE strategy_kind='quick' AND state='monitoring'
               AND confirmation_snapshot_hash IS NOT NULL
             ORDER BY strategy_id
        `).all();
        let observedStrategyCount = 0;
        let disabledStrategyCount = 0;
        let replayedStrategyCount = 0;
        let triggeredStrategyCount = 0;
        for (const strategy of strategies) {
            let definition;
            try {
                definition = JSON.parse(strategy.definition_json);
            } catch {
                throw new Error('stored quick strategy definition is invalid');
            }
            assertCanonicalSmartOrderDraft(definition, { expectedKind: 'quick' });
            if (
                definition.parameters.monitorContractKey !==
                observation.contractKey
            ) {
                continue;
            }
            try {
                assertCanonicalConfirmationCurrent(database, {
                    strategyId: strategy.strategy_id,
                    snapshotHash: strategy.confirmation_snapshot_hash,
                    runtimeEpochId,
                    senderFence,
                    apiGeneration,
                    nowEpochMs: canonicalConfirmationClockNowEpochMs(now),
                });
            } catch {
                disabledStrategyCount += 1;
                continue;
            }
            const condition = canonicalSmartOrderQuickCondition(
                definition.parameters.condition,
            );
            const projection = observation.projections.find(
                (entry) => entry.field === condition.field,
            );
            if (!projection) {
                if (
                    observation.disabledFields.some(
                        (entry) => entry.field === condition.field,
                    )
                ) {
                    disabledStrategyCount += 1;
                    continue;
                }
                throw new Error('quick condition field is absent without disable evidence');
            }
            const durableObservationId = `quick-observation:${sha256Canonical(
                [strategy.strategy_id, observation.observationId],
                'quick strategy observation ID',
            ).slice(7)}`;
            const previous = database.prepare(`
                SELECT * FROM quick_condition_heads WHERE strategy_id=?
            `).get(strategy.strategy_id);
            const duplicate = database.prepare(`
                SELECT observation_id FROM observations WHERE observation_id=?
            `).get(durableObservationId);
            if (duplicate) {
                if (previous?.last_observation_id !== durableObservationId) {
                    throw new Error('quick quote replay is older than the durable head');
                }
                replayedStrategyCount += 1;
                continue;
            }
            if (
                previous &&
                (previous.arm_strategy_revision !== strategy.revision ||
                    previous.trade_date !== observation.tradeDate ||
                    previous.stream_epoch !== observation.streamEpoch ||
                    observation.exchangeTimeMs <
                        previous.last_exchange_epoch_ms ||
                    observation.sequence <= previous.last_local_sequence)
            ) {
                throw new Error('quick quote lineage, arm, or ordering changed');
            }
            if (previous?.state === 'triggered') {
                continue;
            }
            const evaluation = evaluateSmartOrderQuickCondition(
                definition.parameters.condition,
                {
                field: projection.field,
                localUnit: projection.localUnit,
                mappingRevision: observation.mappingRevision,
                mappingDefinitionSha256:
                    observation.mappingDefinitionSha256,
                value: projection.value,
                },
            );
            const evidenceHash = sha256Canonical(
                {
                    apiGeneration,
                    condition,
                    observation,
                    strategyId: strategy.strategy_id,
                    strategyRevision: strategy.revision,
                },
                'quick condition observation evidence',
            );
            database.prepare(`
                INSERT INTO observations(
                    observation_id, strategy_id, contract_key, field_name,
                    value_decimal, exchange_epoch_ms, broker_epoch_ms,
                    receive_epoch_ms, local_sequence, api_generation,
                    evidence_hash, created_at_epoch_ms
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            `).run(
                durableObservationId,
                strategy.strategy_id,
                observation.contractKey,
                condition.field,
                projection.value,
                observation.exchangeTimeMs,
                observation.exchangeTimeMs,
                observation.receiveTimeMs,
                observation.sequence,
                apiGeneration,
                evidenceHash,
                now,
            );
            const activationPolicy = definition.parameters.activationPolicy;
            const transition = projectSmartOrderQuickConditionTransition({
                activationPolicy,
                previousState: previous?.state ?? null,
                conditionTrue: evaluation.conditionTrue,
            });
            const { nextState, triggerNow } = transition;
            let activationId = null;
            if (triggerNow) {
                activationId = `activation:quick:${sha256Canonical(
                    [
                        strategy.strategy_id,
                        strategy.confirmation_snapshot_hash,
                        strategy.revision,
                    ],
                    'quick activation identity',
                ).slice(7)}`;
                database.prepare(`
                    INSERT INTO activations(
                        activation_id, strategy_id, logical_key, state,
                        generation, evidence_hash, created_at_epoch_ms,
                        updated_at_epoch_ms, revision
                    ) VALUES (?, ?, 'quick-condition-edge', 'triggered', ?, ?, ?, ?, 0)
                `).run(
                    activationId,
                    strategy.strategy_id,
                    strategy.revision,
                    evidenceHash,
                    now,
                    now,
                );
                insertTransitionJournalEvent(database, {
                    entityKind: 'activation',
                    entityId: activationId,
                    revision: 0,
                    reasonCode:
                        activationPolicy === 'immediate_if_true'
                            ? 'CONDITION_IMMEDIATE_CONFIRMED'
                            : 'CONDITION_EDGE_FALSE_TO_TRUE',
                    summaryCode: 'quick_condition_triggered',
                    nowEpochMs: now,
                    payloadHash: evidenceHash,
                    eventSuffix: 'triggered',
                    exchangeEpochMs: observation.exchangeTimeMs,
                });
                triggeredStrategyCount += 1;
            }
            if (!previous) {
                database.prepare(`
                    INSERT INTO quick_condition_heads(
                        strategy_id, state, activation_policy,
                        arm_strategy_revision, trade_date, stream_epoch,
                        field_name, comparator, threshold_decimal, local_unit,
                        mapping_revision, mapping_definition_hash,
                        last_observation_id, last_exchange_epoch_ms,
                        last_receive_epoch_ms, last_local_sequence,
                        last_value_decimal, last_condition_true, activation_id,
                        created_at_epoch_ms, updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
                `).run(
                    strategy.strategy_id,
                    nextState,
                    activationPolicy,
                    strategy.revision,
                    observation.tradeDate,
                    observation.streamEpoch,
                    condition.field,
                    condition.comparator,
                    condition.threshold,
                    condition.localUnit,
                    condition.mappingRevision,
                    condition.mappingDefinitionSha256,
                    durableObservationId,
                    observation.exchangeTimeMs,
                    observation.receiveTimeMs,
                    observation.sequence,
                    projection.value,
                    evaluation.conditionTrue ? 1 : 0,
                    activationId,
                    now,
                    now,
                );
            } else {
                const updated = database.prepare(`
                    UPDATE quick_condition_heads
                       SET state=?, last_observation_id=?,
                           last_exchange_epoch_ms=?, last_receive_epoch_ms=?,
                           last_local_sequence=?, last_value_decimal=?,
                           last_condition_true=?, activation_id=?,
                           updated_at_epoch_ms=?, revision=revision+1
                     WHERE strategy_id=? AND revision=?
                `).run(
                    nextState,
                    durableObservationId,
                    observation.exchangeTimeMs,
                    observation.receiveTimeMs,
                    observation.sequence,
                    projection.value,
                    evaluation.conditionTrue ? 1 : 0,
                    activationId,
                    now,
                    strategy.strategy_id,
                    previous.revision,
                );
                if (Number(updated.changes) !== 1) {
                    throw new Error('quick condition head lost its CAS');
                }
            }
            observedStrategyCount += 1;
        }
        const goodTill = recordGoodTillQuoteObservationInTransaction(database, {
            apiGeneration,
            now,
            observation,
            runtimeEpochId,
            senderFence,
        });
        const multiCondition = recordMultiConditionQuoteObservationInTransaction(
            database,
            {
                apiGeneration,
                now,
                observation,
                runtimeEpochId,
                senderFence,
            },
        );
        const parentChild = recordParentChildQuoteObservationInTransaction(
            database,
            {
                apiGeneration,
                now,
                observation,
                runtimeEpochId,
                senderFence,
            },
        );
        return Object.freeze({
            state:
                triggeredStrategyCount > 0 ||
                multiCondition.triggeredStrategyCount > 0
                    ? 'activation_triggered'
                    : 'observed',
            observedStrategyCount,
            disabledStrategyCount,
            replayedStrategyCount,
            triggeredStrategyCount,
            goodTillObservedStrategyCount:
                goodTill.observedStrategyCount,
            goodTillReplayedStrategyCount:
                goodTill.replayedStrategyCount,
            goodTillPreparedIntentCount:
                goodTill.preparedIntentCount,
            goodTillBlockedStrategyCount:
                goodTill.blockedStrategyCount,
            multiConditionObservedStrategyCount:
                multiCondition.observedStrategyCount,
            multiConditionDisabledStrategyCount:
                multiCondition.disabledStrategyCount,
            multiConditionReplayedStrategyCount:
                multiCondition.replayedStrategyCount,
            multiConditionTriggeredStrategyCount:
                multiCondition.triggeredStrategyCount,
            parentChildObservedStrategyCount:
                parentChild.observedStrategyCount,
            parentChildReplayedStrategyCount:
                parentChild.replayedStrategyCount,
            parentChildPreparedIntentCount:
                parentChild.preparedIntentCount,
            parentChildBlockedStrategyCount:
                parentChild.blockedStrategyCount,
            automaticDispatchAllowed: false,
            brokerWriteAuthority: false,
        });
    });
}

function recordProtectiveQuoteObservation(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'apiGeneration',
            'nowEpochMs',
            'observation',
            'runtimeEpochId',
            'senderFence',
        ]) ||
        !exactKeys(input.observation, [
            'contractKey',
            'exchangeTimeMs',
            'field',
            'mappingDefinitionSha256',
            'mappingRevision',
            'observationId',
            'receiveTimeMs',
            'sequence',
            'streamEpoch',
            'tradeDate',
            'value',
        ])
    ) {
        throw new TypeError('protective quote observation input schema is invalid');
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const now = safeInteger(input.nowEpochMs, 'protectiveQuote.nowEpochMs');
    const observation = input.observation;
    const sourceObservationId = sha256Digest(
        observation.observationId,
        'protectiveQuote.observationId',
    );
    const mappingDefinitionSha256 = sha256Digest(
        observation.mappingDefinitionSha256,
        'protectiveQuote.mappingDefinitionSha256',
    );
    const exchangeTimeMs = safeInteger(
        observation.exchangeTimeMs,
        'protectiveQuote.exchangeTimeMs',
    );
    const receiveTimeMs = safeInteger(
        observation.receiveTimeMs,
        'protectiveQuote.receiveTimeMs',
    );
    const sequence = safeInteger(
        observation.sequence,
        'protectiveQuote.sequence',
    );
    const streamEpoch = boundedToken(
        observation.streamEpoch,
        'protectiveQuote.streamEpoch',
    );
    const tradeDate = taipeiTradeDate(observation.tradeDate);
    const value = boundedToken(observation.value, 'protectiveQuote.value', 80);
    const quoteContractKey = boundedToken(
        observation.contractKey,
        'protectiveQuote.contractKey',
    );
    const contractKey = canonicalTradingContractKeyFromQuickQuote(
        quoteContractKey,
    );
    if (
        observation.field !== 'last_price' ||
        observation.mappingRevision !== SMART_ORDER_QUICK_FIELD_MAPPING_REVISION ||
        mappingDefinitionSha256 !==
            SMART_ORDER_QUICK_FIELD_MAPPING_DEFINITION_SHA256 ||
        exchangeTimeMs > receiveTimeMs ||
        receiveTimeMs > now ||
        receiveTimeMs - exchangeTimeMs > 3_000 ||
        now - receiveTimeMs > 3_000
    ) {
        throw new Error('protective quote observation is not current and eligible');
    }
    return transaction(database, () => {
        if (
            !currentReadySenderMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error(
                'protective quote observation requires the current ready Runtime sender',
            );
        }
        const groups = database.prepare(`
            SELECT strategies.strategy_id, strategies.state AS strategy_state,
                   strategies.confirmation_snapshot_hash,
                   groups.protection_group_id, groups.current_generation,
                   groups.plan_hash, groups.revision AS group_revision,
                   generations.state AS generation_state,
                   generations.quantity_shares,
                   generations.revision AS generation_revision,
                   claims.exit_claim_id, claims.obligation_id,
                   claims.account_broker_ref, claims.account_id_ref,
                   claims.contract_key, claims.position_lineage_id,
                   claims.allocation_start_share, claims.quantity_shares AS claim_quantity_shares,
                   claims.state AS claim_state, claims.revision AS claim_revision,
                   commitments.entry_intent_id,
                   COALESCE(entry_intents.trade_date, existing.trade_date) AS trade_date,
                   entry_intents.payload_json,
                   existing.protection_plan_json AS existing_plan_json,
                   COALESCE(fills.formal_protection_json,
                            existing.formal_protection_json) AS formal_protection_json,
                   COALESCE(fills.formal_protection_hash,
                            existing.formal_protection_hash) AS formal_protection_hash,
                   COALESCE(fills.reconciliation_evidence_hash,
                            existing.reconciliation_evidence_hash)
                       AS fill_reconciliation_evidence_hash,
                   rearms.confirmation_snapshot_hash AS rearm_confirmation_snapshot_hash,
                   rearms.risk_revision,
                   rearms.reconciliation_evidence_hash AS rearm_reconciliation_evidence_hash,
                   rearms.user_rearm_evidence_hash,
                   resume_arms.authority_payload_hash AS resume_user_arm_evidence_hash,
                   runtime.reconciliation_evidence_hash AS runtime_reconciliation_evidence_hash
              FROM protection_groups AS groups
              JOIN protection_remainder_generations AS generations
                ON generations.protection_group_id=groups.protection_group_id
               AND generations.remainder_generation=groups.current_generation
              JOIN exit_claims AS claims
                ON claims.exit_claim_id=groups.exit_claim_id
              JOIN protection_obligations AS obligations
                ON obligations.obligation_id=groups.obligation_id
         LEFT JOIN pending_protection_commitments AS commitments
                ON commitments.commitment_id=obligations.commitment_id
         LEFT JOIN order_intents AS entry_intents
                ON entry_intents.intent_id=commitments.entry_intent_id
         LEFT JOIN protected_entry_fill_heads AS fills
                ON fills.intent_id=entry_intents.intent_id
         LEFT JOIN existing_position_protection_heads AS existing
                ON existing.strategy_id=obligations.strategy_id
               AND existing.obligation_id=obligations.obligation_id
               AND existing.exit_claim_id=claims.exit_claim_id
              JOIN strategies
                ON strategies.strategy_id=obligations.strategy_id
              JOIN runtime_epochs AS runtime
                ON runtime.runtime_epoch_id=?
               AND runtime.sender_fence=?
               AND runtime.api_generation=?
               AND runtime.state='ready'
              LEFT JOIN intent_rearm_authorizations AS rearms
                ON rearms.intent_id=entry_intents.intent_id
               AND rearms.runtime_epoch_id=runtime.runtime_epoch_id
               AND rearms.sender_fence=runtime.sender_fence
               AND rearms.api_generation=runtime.api_generation
               AND rearms.state='consumed'
              LEFT JOIN authority_consumptions AS resume_arms
                ON resume_arms.rowid=(
                    SELECT candidate.rowid
                      FROM authority_consumptions AS candidate
                     WHERE candidate.authority_kind='strategy_resume_arm'
                       AND candidate.consumed_by=strategies.strategy_id
                       AND candidate.runtime_epoch_id=runtime.runtime_epoch_id
                     ORDER BY candidate.consumed_at_epoch_ms DESC,
                              candidate.authority_id DESC
                     LIMIT 1
                )
             WHERE strategies.state='monitoring'
               AND groups.state='monitoring'
               AND generations.state='monitoring'
               AND claims.state='monitoring_reserved'
               AND claims.intent_id IS NULL
               AND claims.external_lineage=0
               AND claims.contract_key=?
               AND COALESCE(entry_intents.trade_date, existing.trade_date)=?
               AND ((entry_intents.intent_id IS NOT NULL AND
                     existing.strategy_id IS NULL) OR
                    (entry_intents.intent_id IS NULL AND
                     existing.strategy_id IS NOT NULL))
               AND (rearms.rearm_authorization_id IS NOT NULL OR
                    resume_arms.authority_id IS NOT NULL)
             ORDER BY groups.protection_group_id
        `).all(
            runtimeEpochId,
            senderFence,
            apiGeneration,
            contractKey,
            tradeDate,
        );
        let observedGroups = 0;
        let preparedWinnerCount = 0;
        let replayedGroups = 0;
        for (const row of groups) {
            if (
                row.claim_quantity_shares !== row.quantity_shares ||
                row.formal_protection_json === null ||
                row.formal_protection_hash === null ||
                row.fill_reconciliation_evidence_hash === null ||
                (row.rearm_confirmation_snapshot_hash !== null &&
                    (row.rearm_confirmation_snapshot_hash !==
                        row.confirmation_snapshot_hash ||
                        row.rearm_reconciliation_evidence_hash === null ||
                        row.rearm_reconciliation_evidence_hash !==
                            row.runtime_reconciliation_evidence_hash)) ||
                (row.rearm_confirmation_snapshot_hash === null &&
                    row.resume_user_arm_evidence_hash === null)
            ) {
                throw new Error('protective quote durable lineage is incomplete');
            }
            const canonicalNow = canonicalConfirmationClockNowEpochMs(now);
            if (row.existing_plan_json !== null) {
                const currentRemainder =
                    currentExistingPositionProtectionArm(database, {
                        apiGeneration,
                        expectedGroupState: 'monitoring',
                        nowEpochMs: canonicalNow,
                        runtimeEpochId,
                        senderFence,
                        strategyId: row.strategy_id,
                    });
                if (
                    currentRemainder === null ||
                    currentRemainder.protection_group_id !==
                        row.protection_group_id ||
                    currentRemainder.current_generation !==
                        row.current_generation
                ) {
                    throw new Error(
                        'protective quote existing-position re-arm is not current',
                    );
                }
            } else {
                assertCanonicalConfirmationCurrent(database, {
                    strategyId: row.strategy_id,
                    snapshotHash: row.confirmation_snapshot_hash,
                    runtimeEpochId,
                    senderFence,
                    apiGeneration,
                    nowEpochMs: canonicalNow,
                });
            }
            let plan;
            let formal;
            if (row.existing_plan_json !== null) {
                plan = canonicalExistingPositionProtectionPlan(
                    parseStoredCanonicalObject(
                        row.existing_plan_json,
                        'existing-position protection plan',
                    ),
                );
                formal = deriveExistingPositionFormalProtection(
                    plan.plan,
                    row.claim_quantity_shares,
                );
            } else {
                const entryPayload = canonicalProtectedEntryIntentPayload(
                    parseStoredCanonicalObject(
                        row.payload_json,
                        'protective quote entry payload',
                    ),
                );
                plan = canonicalProtectedEntryPlan(
                    entryPayload.payload.protectionPlan,
                );
                formal = deriveProtectedEntryFormalProtection(
                    plan.plan,
                    database.prepare(`
                        SELECT fill_notional_minor_units
                          FROM protected_entry_fill_heads WHERE intent_id=?
                    `).get(row.entry_intent_id).fill_notional_minor_units,
                    row.claim_quantity_shares,
                );
            }
            if (
                plan.planSha256 !== row.plan_hash ||
                plan.plan.contractKey !== contractKey ||
                stableCanonicalJson(formal) !== row.formal_protection_json ||
                sha256Canonical(formal, 'formal protected entry projection') !==
                    row.formal_protection_hash ||
                (row.risk_revision !== null &&
                    plan.plan.riskRevision !== row.risk_revision)
            ) {
                throw new Error('protective quote formal protection is not current');
            }
            const durableObservationId = `protection-observation:${sha256Canonical(
                [row.strategy_id, sourceObservationId],
                'protective strategy observation ID',
            ).slice(7)}`;
            const existingObservation = database.prepare(`
                SELECT observation_id FROM observations WHERE observation_id=?
            `).get(durableObservationId);
            const previousHead = database.prepare(`
                SELECT * FROM protection_trigger_heads
                 WHERE protection_group_id=? AND remainder_generation=?
            `).get(row.protection_group_id, row.current_generation);
            if (existingObservation) {
                if (previousHead?.last_observation_id !== durableObservationId) {
                    throw new Error(
                        'protective quote replay is older than the durable head',
                    );
                }
                replayedGroups += 1;
                continue;
            }
            if (
                previousHead &&
                (previousHead.trade_date !== tradeDate ||
                    previousHead.stream_epoch !== streamEpoch ||
                    exchangeTimeMs < previousHead.last_exchange_epoch_ms ||
                    sequence <= previousHead.last_local_sequence)
            ) {
                throw new Error(
                    'protective quote lineage changed or moved out of order',
                );
            }
            const evidenceHash = sha256Canonical(
                {
                    apiGeneration,
                    contractKey,
                    exchangeTimeMs,
                    mappingDefinitionSha256,
                    mappingRevision: observation.mappingRevision,
                    receiveTimeMs,
                    sequence,
                    sourceObservationId,
                    strategyId: row.strategy_id,
                    streamEpoch,
                    tradeDate,
                    value,
                },
                'protective quote observation evidence',
            );
            database.prepare(`
                INSERT INTO observations(
                    observation_id, strategy_id, contract_key, field_name,
                    value_decimal, exchange_epoch_ms, broker_epoch_ms,
                    receive_epoch_ms, local_sequence, api_generation,
                    evidence_hash, created_at_epoch_ms
                ) VALUES (?, ?, ?, 'last_price', ?, ?, ?, ?, ?, ?, ?, ?)
            `).run(
                durableObservationId,
                row.strategy_id,
                contractKey,
                value,
                exchangeTimeMs,
                exchangeTimeMs,
                receiveTimeMs,
                sequence,
                apiGeneration,
                evidenceHash,
                now,
            );
            const previousEvaluationHead = previousHead
                ? Object.freeze({
                      family: previousHead.family,
                      savedHighDecimal: previousHead.saved_high_decimal,
                      state: previousHead.state,
                  })
                : null;
            const evaluation = evaluateSmartOrderProtectiveTrigger({
                formalProtection: formal,
                observedPrice: value,
                previousHead: previousEvaluationHead,
                protectionPlan: plan.plan,
            });
            const candidateEvaluations = evaluation.triggeredLegIds.map(
                (legId) =>
                    Object.freeze({
                        evidenceHash: sha256Canonical(
                            {
                                durableObservationId,
                                formalProtectionHash:
                                    row.formal_protection_hash,
                                legId,
                                protectionGroupId: row.protection_group_id,
                                remainderGeneration: row.current_generation,
                                savedHighDecimal: evaluation.savedHighDecimal,
                            },
                            'protective trigger candidate evidence',
                        ),
                        legId,
                        observedAtEpochMs: exchangeTimeMs,
                    }),
            );
            let winnerPrepared = false;
            let winnerLegId = null;
            if (candidateEvaluations.length > 0) {
                const claimEnvelope = {
                    accountBrokerRef: row.account_broker_ref,
                    accountIdRef: row.account_id_ref,
                    allocationStartShare: row.allocation_start_share,
                    candidateEvaluations,
                    contractKey: row.contract_key,
                    evidenceHash,
                    exitClaimId: row.exit_claim_id,
                    expectedGenerationRevision: row.generation_revision,
                    expectedGroupRevision: row.group_revision,
                    expectedRevision: row.claim_revision,
                    obligationId: row.obligation_id,
                    positionLineageId: row.position_lineage_id,
                    protectionGroupId: row.protection_group_id,
                    quantityShares: row.claim_quantity_shares,
                    remainderGeneration: row.current_generation,
                };
                const selection = canonicalProtectionOcoSelection(claimEnvelope);
                claimEnvelope.evidenceHash = selection.selectionHash;
                const protectivePayload =
                    buildSmartOrderProtectiveBrokerIntentPayload({
                        legId: selection.winner.legId,
                        protectionPlan: plan.plan,
                        quantityShares: row.claim_quantity_shares,
                        triggerPolicyHash: selection.winner.evidenceHash,
                    });
                const lineageDigest = selection.selectionHash.slice(7);
                const activationId = `activation:protective:${lineageDigest}`;
                const intentId = `intent:protective:${lineageDigest}`;
                const prepared = prepareIntent(
                    database,
                    {
                        activation: {
                            activationId,
                            evidenceHash: selection.selectionHash,
                            generation: row.current_generation,
                            logicalKey: `protective:${row.protection_group_id}:${row.current_generation}`,
                        },
                        apiGeneration,
                        exitClaim: claimEnvelope,
                        intent: {
                            accountBrokerRef: row.account_broker_ref,
                            accountIdRef: row.account_id_ref,
                            clientRequestId: `protective:${lineageDigest}`,
                            contractKey: row.contract_key,
                            intentId,
                            operationKind: 'place',
                            ownerKind: 'activation',
                            payload: protectivePayload.payload,
                            payloadHash: protectivePayload.payloadSha256,
                            side: 'Sell',
                            tradeDate: row.trade_date,
                        },
                        nowEpochMs: now,
                        runtimeEpochId,
                        senderFence,
                        strategyId: row.strategy_id,
                    },
                    true,
                );
                if (prepared.state === 'prepared' && prepared.winnerLegId) {
                    rearmPreparedIntent(
                        database,
                        {
                            apiGeneration,
                            confirmationSnapshotHash:
                                row.confirmation_snapshot_hash,
                            expectedIntentRevision: prepared.revision,
                            intentId,
                            nowEpochMs: now,
                            rearmAuthorizationId: `rearm:protective:${lineageDigest}`,
                            rearmRequestId: `rearm-request:protective:${lineageDigest}`,
                            reconciliationEvidenceHash:
                                row.runtime_reconciliation_evidence_hash,
                            riskRevision: plan.plan.riskRevision,
                            runtimeEpochId,
                            senderFence,
                            userRearmEvidenceHash:
                                row.user_rearm_evidence_hash ??
                                row.resume_user_arm_evidence_hash,
                        },
                        true,
                    );
                    winnerPrepared = true;
                    winnerLegId = selection.winner.legId;
                    preparedWinnerCount += 1;
                }
            }
            const durableState = winnerPrepared
                ? 'triggered'
                : evaluation.nextState === 'triggered'
                  ? evaluation.family === 'fixed'
                      ? 'monitoring'
                      : evaluation.savedHighDecimal === null
                        ? 'pending_activation'
                        : 'active'
                  : evaluation.nextState;
            const savedHighObservationId =
                evaluation.savedHighDecimal === null
                    ? null
                    : previousHead?.saved_high_decimal ===
                        evaluation.savedHighDecimal
                      ? previousHead.saved_high_observation_id
                      : durableObservationId;
            if (!previousHead) {
                database.prepare(`
                    INSERT INTO protection_trigger_heads(
                        protection_group_id, remainder_generation, strategy_id,
                        family, state, trade_date, stream_epoch,
                        last_observation_id, last_exchange_epoch_ms,
                        last_receive_epoch_ms, last_local_sequence,
                        last_price_decimal, saved_high_decimal,
                        saved_high_observation_id, retracement_trigger_decimal,
                        triggered_leg_id, created_at_epoch_ms,
                        updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
                `).run(
                    row.protection_group_id,
                    row.current_generation,
                    row.strategy_id,
                    evaluation.family,
                    durableState,
                    tradeDate,
                    streamEpoch,
                    durableObservationId,
                    exchangeTimeMs,
                    receiveTimeMs,
                    sequence,
                    value,
                    evaluation.savedHighDecimal,
                    savedHighObservationId,
                    evaluation.retracementTriggerDecimal,
                    winnerPrepared ? winnerLegId : null,
                    now,
                    now,
                );
            } else {
                const updated = database.prepare(`
                    UPDATE protection_trigger_heads
                       SET state=?, last_observation_id=?,
                           last_exchange_epoch_ms=?, last_receive_epoch_ms=?,
                           last_local_sequence=?, last_price_decimal=?,
                           saved_high_decimal=?, saved_high_observation_id=?,
                           retracement_trigger_decimal=?, triggered_leg_id=?,
                           updated_at_epoch_ms=?, revision=revision+1
                     WHERE protection_group_id=? AND remainder_generation=?
                       AND revision=?
                `).run(
                    durableState,
                    durableObservationId,
                    exchangeTimeMs,
                    receiveTimeMs,
                    sequence,
                    value,
                    evaluation.savedHighDecimal,
                    savedHighObservationId,
                    evaluation.retracementTriggerDecimal,
                    winnerPrepared ? winnerLegId : null,
                    now,
                    row.protection_group_id,
                    row.current_generation,
                    previousHead.revision,
                );
                if (Number(updated.changes) !== 1) {
                    throw new Error('protective trigger head lost its CAS');
                }
            }
            const headRevision = previousHead ? previousHead.revision + 1 : 0;
            const evaluationEntityId = `${row.protection_group_id}:${row.current_generation}`;
            if (
                evaluation.family === 'trailing' &&
                durableState === 'active' &&
                previousHead?.state !== 'active'
            ) {
                insertTransitionJournalEvent(database, {
                    entityKind: 'protection_leg_evaluation',
                    entityId: evaluationEntityId,
                    revision: headRevision,
                    reasonCode: 'PROTECTION_MONITORING_REVISION_UPDATED',
                    summaryCode: 'protection_trailing_activated',
                    nowEpochMs: now,
                    payloadHash: evidenceHash,
                    eventSuffix: 'activation',
                    exchangeEpochMs: exchangeTimeMs,
                });
            }
            if (
                evaluation.family === 'trailing' &&
                previousHead?.state === 'active' &&
                previousHead.saved_high_decimal !==
                    evaluation.savedHighDecimal
            ) {
                insertTransitionJournalEvent(database, {
                    entityKind: 'protection_leg_evaluation',
                    entityId: evaluationEntityId,
                    revision: headRevision,
                    reasonCode: 'PROTECTION_MONITORING_REVISION_UPDATED',
                    summaryCode: 'protection_trailing_extreme_updated',
                    nowEpochMs: now,
                    payloadHash: evidenceHash,
                    eventSuffix: 'extreme',
                    exchangeEpochMs: exchangeTimeMs,
                });
            }
            if (winnerPrepared) {
                insertTransitionJournalEvent(database, {
                    entityKind: 'protection_leg_evaluation',
                    entityId: evaluationEntityId,
                    revision: headRevision,
                    reasonCode: 'PROTECTION_MONITORING_REVISION_UPDATED',
                    summaryCode: 'protection_trigger_winner_prepared',
                    nowEpochMs: now,
                    payloadHash: evidenceHash,
                    eventSuffix: 'trigger',
                    exchangeEpochMs: exchangeTimeMs,
                });
            }
            observedGroups += 1;
        }
        return Object.freeze({
            state: preparedWinnerCount > 0 ? 'winner_prepared' : 'observed',
            observedGroupCount: observedGroups,
            preparedWinnerCount,
            replayedGroupCount: replayedGroups,
            brokerWriteAuthority: false,
            automaticDispatchAllowed: false,
        });
    });
}

/**
 * Persists a write-adjacent broker-order projection through the normal worker
 * boundary.  It deliberately derives account/contract/side from the durable
 * intent and grants no broker authority; a verified correlation must still be
 * stored separately before a manual-cancel exception can be classified.
 */
function recordBrokerOrderEvidence(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'apiGeneration',
            'brokerOrderId',
            'controlRevision',
            'evidenceHash',
            'expectedRevision',
            'filledShares',
            'intentId',
            'nowEpochMs',
            'quantityShares',
            'remainingShares',
            'runtimeEpochId',
            'senderFence',
            'state',
        ])
    ) {
        throw new TypeError('broker order evidence input schema is invalid');
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const brokerOrderId = boundedToken(input.brokerOrderId, 'brokerOrderId');
    const intentId = boundedToken(input.intentId, 'intentId');
    const state = boundedToken(input.state, 'brokerOrder.state');
    if (
        !BROKER_ORDER_NON_TERMINAL_STATES.has(state) &&
        !BROKER_ORDER_TERMINAL_STATES.has(state)
    ) {
        throw new TypeError('broker order state is unsupported');
    }
    const controlRevision = safeInteger(
        input.controlRevision,
        'brokerOrder.controlRevision',
    );
    const quantityShares = safeInteger(
        input.quantityShares,
        'brokerOrder.quantityShares',
        { minimum: 1 },
    );
    const filledShares = safeInteger(
        input.filledShares,
        'brokerOrder.filledShares',
    );
    const remainingShares = safeInteger(
        input.remainingShares,
        'brokerOrder.remainingShares',
    );
    validateBrokerOrderQuantityProjection({
        state,
        quantityShares,
        filledShares,
        remainingShares,
    });
    const evidenceHash = sha256Digest(input.evidenceHash, 'brokerOrder.evidenceHash');
    const now = safeInteger(input.nowEpochMs, 'brokerOrder.nowEpochMs');
    return transaction(database, () => {
        if (
            !currentReadySenderMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error('broker order evidence requires current ready sender');
        }
        const intent = database
            .prepare(`
                SELECT state, adapter_authority_granted, runtime_epoch_id,
                       sender_fence, api_generation
                  FROM order_intents WHERE intent_id=?
            `)
            .get(intentId);
        if (
            !intent ||
            intent.adapter_authority_granted !== 1 ||
            !['dispatching', 'acknowledged', 'reconciling', 'unknown', 'terminal'].includes(
                intent.state,
            ) ||
            intent.runtime_epoch_id !== runtimeEpochId ||
            intent.sender_fence !== senderFence ||
            intent.api_generation !== apiGeneration
        ) {
            throw new Error(
                'broker order evidence must bind a dispatched intent and its sender fence',
            );
        }
        const existing = database
            .prepare(`
                SELECT intent_id, state, control_revision, quantity_shares,
                       filled_shares, remaining_shares, evidence_hash, revision
                  FROM broker_orders WHERE broker_order_id=?
            `)
            .get(brokerOrderId);
        let revision;
        let replayed = false;
        if (!existing) {
            if (input.expectedRevision !== null || controlRevision !== 0) {
                throw new Error(
                    'new broker order evidence requires null expected revision and control revision zero',
                );
            }
            database
                .prepare(`
                    INSERT INTO broker_orders(
                        broker_order_id, intent_id, state, control_revision,
                        quantity_shares, filled_shares, remaining_shares,
                        evidence_hash, updated_at_epoch_ms,
                        terminal_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
                `)
                .run(
                    brokerOrderId,
                    intentId,
                    state,
                    controlRevision,
                    quantityShares,
                    filledShares,
                    remainingShares,
                    evidenceHash,
                    now,
                    BROKER_ORDER_TERMINAL_STATES.has(state) ? now : null,
                );
            revision = 0;
        } else if (
            existing.intent_id === intentId &&
            existing.state === state &&
            existing.control_revision === controlRevision &&
            existing.quantity_shares === quantityShares &&
            existing.filled_shares === filledShares &&
            existing.remaining_shares === remainingShares &&
            existing.evidence_hash === evidenceHash &&
            ((existing.revision === 0 && input.expectedRevision === null) ||
                (existing.revision > 0 &&
                    input.expectedRevision === existing.revision - 1))
        ) {
            // Broker callbacks may be delivered more than once or arrive
            // before the HTTP acknowledgement. An exact canonical replay is
            // observationally idempotent: it must not consume a revision or
            // append a second journal transition. Any content drift continues
            // through the normal CAS/state checks below and fails closed.
            revision = existing.revision;
            replayed = true;
        } else if (input.expectedRevision === null) {
            throw new Error(
                'broker order evidence collided with a different first-event projection',
            );
        } else {
            const expectedRevision = safeInteger(
                input.expectedRevision,
                'brokerOrder.expectedRevision',
            );
            if (
                existing.intent_id !== intentId ||
                existing.revision !== expectedRevision ||
                !BROKER_ORDER_ALLOWED_NEXT_STATES[existing.state]?.has(state) ||
                controlRevision < existing.control_revision ||
                controlRevision > existing.control_revision + 1 ||
                filledShares < existing.filled_shares ||
                (controlRevision === existing.control_revision &&
                    quantityShares !== existing.quantity_shares)
            ) {
                throw new Error(
                    'broker order evidence lost its lineage, state, quantity, or revision CAS',
                );
            }
            const result = database
                .prepare(`
                    UPDATE broker_orders
                       SET state=?, control_revision=?, quantity_shares=?,
                           filled_shares=?, remaining_shares=?, evidence_hash=?,
                           updated_at_epoch_ms=?, terminal_at_epoch_ms=?,
                           revision=revision+1
                     WHERE broker_order_id=? AND intent_id=? AND revision=?
                `)
                .run(
                    state,
                    controlRevision,
                    quantityShares,
                    filledShares,
                    remainingShares,
                    evidenceHash,
                    now,
                    BROKER_ORDER_TERMINAL_STATES.has(state) ? now : null,
                    brokerOrderId,
                    intentId,
                    expectedRevision,
                );
            if (Number(result.changes) !== 1) {
                throw new Error('broker order evidence update lost its CAS');
            }
            revision = expectedRevision + 1;
        }
        if (!replayed) {
            advanceLifecycleSideEffectRevision(database);
            insertTransitionJournalEvent(database, {
                entityKind: 'broker_order',
                entityId: brokerOrderId,
                revision,
                reasonCode: 'BROKER_ORDER_EVIDENCE_VERIFIED_AND_STORED',
                summaryCode: `broker_order_${state}`,
                nowEpochMs: now,
                payloadHash: evidenceHash,
                eventSuffix: `evidence-${state}`,
            });
        }
        return Object.freeze({
            brokerOrderId,
            intentId,
            state,
            controlRevision,
            quantityShares,
            filledShares,
            remainingShares,
            revision,
            replayed,
            brokerAuthorityGranted: false,
        });
    });
}

function createExternalExitClaim(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    const now = safeInteger(input.nowEpochMs, 'externalClaim.nowEpochMs');
    const state = boundedToken(input.state, 'externalClaim.state');
    if (!['broker_working', 'unknown'].includes(state)) {
        throw new TypeError(
            'external exit claim must begin as broker_working or unknown',
        );
    }
    const exitClaimId = boundedToken(input.exitClaimId, 'exitClaimId');
    return transaction(database, () => {
        database
            .prepare(`
                INSERT INTO exit_claims(
                    exit_claim_id, obligation_id, intent_id, external_lineage,
                    account_broker_ref, account_id_ref, contract_key,
                    position_lineage_id, remainder_generation,
                    allocation_start_share, quantity_shares, state,
                    evidence_hash, created_at_epoch_ms, updated_at_epoch_ms,
                    revision
                ) VALUES (?, NULL, NULL, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            `)
            .run(
                exitClaimId,
                boundedToken(input.accountBrokerRef, 'externalClaim.accountBrokerRef'),
                boundedToken(input.accountIdRef, 'externalClaim.accountIdRef'),
                boundedToken(input.contractKey, 'externalClaim.contractKey'),
                boundedToken(
                    input.positionLineageId,
                    'externalClaim.positionLineageId',
                ),
                safeInteger(
                    input.remainderGeneration,
                    'externalClaim.remainderGeneration',
                ),
                safeInteger(
                    input.allocationStartShare,
                    'externalClaim.allocationStartShare',
                ),
                safeInteger(input.quantityShares, 'externalClaim.quantityShares', {
                    minimum: 1,
                }),
                state,
                sha256Digest(input.evidenceHash, 'externalClaim.evidenceHash'),
                now,
                now,
            );
        insertTransitionJournalEvent(database, {
            entityKind: 'exit_claim',
            entityId: exitClaimId,
            revision: 0,
            reasonCode:
                state === 'broker_working'
                    ? 'EXTERNAL_WORKING_SELL_OBSERVED'
                    : 'EXTERNAL_SELL_RESULT_UNKNOWN',
            summaryCode:
                state === 'broker_working'
                    ? 'external_working_sell_observed'
                    : 'external_sell_unknown',
            nowEpochMs: now,
            payloadHash: input.evidenceHash,
            eventSuffix: `external-${state}`,
        });
        advanceLifecycleSideEffectRevision(database);
        return Object.freeze({
            exitClaimId,
            externalLineage: true,
            obligationId: null,
            state,
            revision: 0,
        });
    });
}

function recordTask03cExternalWorkingSet(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    if (
        !exactKeys(input, [
            'accountBrokerRef',
            'accountIdRef',
            'accountScopeSha256',
            'apiGeneration',
            'claims',
            'contractKey',
            'nowEpochMs',
            'observedAtEpochMs',
            'positionLineageId',
            'positionRevision',
            'positionShares',
            'runtimeEpochId',
            'senderFence',
            'sourceEvidenceHash',
            'sourceRevision',
            'sourceSequence',
            'tradeDate',
            'validUntilEpochMs',
        ])
    ) {
        throw new TypeError('Task 0.3c external working-set input is invalid');
    }
    const accountBrokerRef = boundedToken(
        input.accountBrokerRef,
        'task03c.accountBrokerRef',
    );
    const accountIdRef = boundedToken(input.accountIdRef, 'task03c.accountIdRef');
    const accountScopeSha256 = sha256Digest(
        input.accountScopeSha256,
        'task03c.accountScopeSha256',
    );
    const expectedAccountScopeSha256 = `sha256:${createHash('sha256')
        .update(
            `smart-order-reconciliation-account\u001f${stableCanonicalJson([
                accountBrokerRef,
                accountIdRef,
                'S',
            ])}`,
        )
        .digest('hex')}`;
    if (accountScopeSha256 !== expectedAccountScopeSha256) {
        throw new Error('Task 0.3c account scope does not match the fixed account');
    }
    const runtimeEpochId = boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const senderFence = boundedToken(input.senderFence, 'senderFence');
    const apiGeneration = boundedToken(input.apiGeneration, 'apiGeneration');
    const tradeDate = taipeiTradeDate(input.tradeDate);
    const contractKey = boundedToken(input.contractKey, 'task03c.contractKey');
    if (contractKey !== 'TSE:2330:STK:Common') {
        throw new Error('Task 0.3c contract scope is invalid');
    }
    const now = safeInteger(input.nowEpochMs, 'task03c.nowEpochMs');
    const observedAtEpochMs = safeInteger(
        input.observedAtEpochMs,
        'task03c.observedAtEpochMs',
    );
    const validUntilEpochMs = safeInteger(
        input.validUntilEpochMs,
        'task03c.validUntilEpochMs',
    );
    if (
        validUntilEpochMs <= observedAtEpochMs ||
        validUntilEpochMs - observedAtEpochMs > 5_000 ||
        observedAtEpochMs > now
    ) {
        throw new Error('Task 0.3c observation clock is invalid');
    }
    const sourceRevision = sha256Digest(
        input.sourceRevision,
        'task03c.sourceRevision',
    );
    const sourceEvidenceHash = sha256Digest(
        input.sourceEvidenceHash,
        'task03c.sourceEvidenceHash',
    );
    const positionRevision = sha256Digest(
        input.positionRevision,
        'task03c.positionRevision',
    );
    const sourceSequence = safeInteger(
        input.sourceSequence,
        'task03c.sourceSequence',
        { minimum: 1 },
    );
    const positionShares = safeInteger(
        input.positionShares,
        'task03c.positionShares',
        { minimum: 1 },
    );
    const positionLineageId = boundedToken(
        input.positionLineageId,
        'task03c.positionLineageId',
    );
    if (!Array.isArray(input.claims) || input.claims.length !== 2) {
        throw new Error('Task 0.3c requires exactly two external claims');
    }
    const claims = input.claims.map((claim, index) => {
        if (
            !exactKeys(claim, [
                'brokerOrderId',
                'evidenceHash',
                'exitClaimId',
                'quantityShares',
            ])
        ) {
            throw new TypeError(`Task 0.3c claim ${index} is invalid`);
        }
        const brokerOrderId = boundedToken(
            claim.brokerOrderId,
            `task03c.claims[${index}].brokerOrderId`,
        );
        const expectedExitClaimId = `external-sell-claim:${sha256Canonical(
            [accountScopeSha256, tradeDate, brokerOrderId, contractKey],
            'Task 0.3c external claim ID',
        ).slice(7)}`;
        if (claim.exitClaimId !== expectedExitClaimId) {
            throw new Error('Task 0.3c external claim lineage is invalid');
        }
        return Object.freeze({
            allocationStartShare: 0,
            evidenceHash: sha256Digest(
                claim.evidenceHash,
                `task03c.claims[${index}].evidenceHash`,
            ),
            exitClaimId: expectedExitClaimId,
            positionLineageId,
            quantityShares: safeInteger(
                claim.quantityShares,
                `task03c.claims[${index}].quantityShares`,
                { minimum: 1 },
            ),
            remainderGeneration: 0,
            state: 'broker_working',
        });
    });
    if (new Set(input.claims.map((claim) => claim.brokerOrderId)).size !== 2) {
        throw new Error('Task 0.3c broker order set is not unique');
    }
    const workingSet = canonicalExternalWorkingSet(claims, 'task03c');
    if (
        workingSet.claims.reduce(
            (total, claim) =>
                addExposureInteger(total, claim.quantityShares, 'task03c shares'),
            0,
        ) > positionShares
    ) {
        throw new Error('Task 0.3c working sells exceed the position');
    }
    return transaction(database, () => {
        const runtime = database
            .prepare(`
                SELECT state, started_at_epoch_ms FROM runtime_epochs
                 WHERE runtime_epoch_id=? AND sender_fence=? AND api_generation=?
            `)
            .get(runtimeEpochId, senderFence, apiGeneration);
        if (
            !runtime ||
            !['reconciling', 'ready'].includes(runtime.state) ||
            observedAtEpochMs < runtime.started_at_epoch_ms
        ) {
            throw new Error(
                'Task 0.3c reconciliation requires the restarted current Runtime',
            );
        }
        const currentBindings = database
            .prepare(`
                SELECT bindings.exit_claim_id
                  FROM exit_claim_visibility_bindings AS bindings
                  JOIN exit_claims AS claims USING(exit_claim_id)
                 WHERE bindings.account_broker_ref=? AND bindings.account_id_ref=?
                   AND bindings.trade_date=? AND bindings.contract_key=?
                   AND bindings.binding_kind='external_projection'
                   AND claims.external_lineage=1
                   AND claims.state IN ('broker_working','unknown')
                 ORDER BY bindings.exit_claim_id
            `)
            .all(accountBrokerRef, accountIdRef, tradeDate, contractKey)
            .map((row) => row.exit_claim_id);
        const expectedClaimIds = workingSet.claims
            .map((claim) => claim.exitClaimId)
            .sort();
        if (
            currentBindings.some(
                (exitClaimId) => !expectedClaimIds.includes(exitClaimId),
            )
        ) {
            throw new Error('Task 0.3c conflicts with another external claim');
        }
        const currentHead = database
            .prepare(`
                SELECT revision FROM external_sell_visibility_heads
                 WHERE account_broker_ref=? AND account_id_ref=?
                   AND trade_date=? AND contract_key=?
            `)
            .get(accountBrokerRef, accountIdRef, tradeDate, contractKey);
        const headRevision = currentHead ? currentHead.revision + 1 : 0;
        if (currentHead) {
            const update = database
                .prepare(`
                    UPDATE external_sell_visibility_heads
                       SET source_revision=?, source_sequence=?,
                           source_evidence_hash=?, position_revision=?,
                           position_shares=?, working_set_hash=?,
                           collection_complete=1, observed_at_epoch_ms=?,
                           valid_until_epoch_ms=?, updated_at_epoch_ms=?, revision=?
                     WHERE account_broker_ref=? AND account_id_ref=?
                       AND trade_date=? AND contract_key=? AND revision=?
                `)
                .run(
                    sourceRevision,
                    sourceSequence,
                    sourceEvidenceHash,
                    positionRevision,
                    positionShares,
                    workingSet.workingSetHash,
                    observedAtEpochMs,
                    validUntilEpochMs,
                    now,
                    headRevision,
                    accountBrokerRef,
                    accountIdRef,
                    tradeDate,
                    contractKey,
                    currentHead.revision,
                );
            if (Number(update.changes) !== 1) {
                throw new Error('Task 0.3c visibility update lost its CAS');
            }
        } else {
            database
                .prepare(`
                    INSERT INTO external_sell_visibility_heads(
                        account_broker_ref, account_id_ref, trade_date,
                        contract_key, source_revision, source_sequence,
                        source_evidence_hash, position_revision,
                        position_shares, working_set_hash, collection_complete,
                        observed_at_epoch_ms, valid_until_epoch_ms,
                        updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, 0)
                `)
                .run(
                    accountBrokerRef,
                    accountIdRef,
                    tradeDate,
                    contractKey,
                    sourceRevision,
                    sourceSequence,
                    sourceEvidenceHash,
                    positionRevision,
                    positionShares,
                    workingSet.workingSetHash,
                    observedAtEpochMs,
                    validUntilEpochMs,
                    now,
                );
        }
        for (const claim of workingSet.claims) {
            const stored = database
                .prepare('SELECT * FROM exit_claims WHERE exit_claim_id=?')
                .get(claim.exitClaimId);
            if (!stored) {
                database
                    .prepare(`
                        INSERT INTO exit_claims(
                            exit_claim_id, obligation_id, intent_id,
                            external_lineage, account_broker_ref, account_id_ref,
                            contract_key, position_lineage_id,
                            remainder_generation, allocation_start_share,
                            quantity_shares, state, evidence_hash,
                            created_at_epoch_ms, updated_at_epoch_ms, revision
                        ) VALUES (?, NULL, NULL, 1, ?, ?, ?, ?, 0, 0, ?,
                                  'broker_working', ?, ?, ?, 0)
                    `)
                    .run(
                        claim.exitClaimId,
                        accountBrokerRef,
                        accountIdRef,
                        contractKey,
                        positionLineageId,
                        claim.quantityShares,
                        claim.evidenceHash,
                        now,
                        now,
                    );
            } else if (
                stored.external_lineage !== 1 ||
                stored.account_broker_ref !== accountBrokerRef ||
                stored.account_id_ref !== accountIdRef ||
                stored.contract_key !== contractKey ||
                stored.position_lineage_id !== positionLineageId ||
                stored.quantity_shares !== claim.quantityShares ||
                stored.state !== 'broker_working'
            ) {
                throw new Error('Task 0.3c external claim conflicts');
            }
            database
                .prepare(`
                    INSERT INTO exit_claim_visibility_bindings(
                        exit_claim_id, account_broker_ref, account_id_ref,
                        trade_date, contract_key, source_revision,
                        source_sequence, source_evidence_hash,
                        position_revision, position_shares, working_set_hash,
                        binding_kind, visibility_head_revision,
                        created_at_epoch_ms, updated_at_epoch_ms, revision
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                              'external_projection', ?, ?, ?, 0)
                    ON CONFLICT(exit_claim_id) DO UPDATE SET
                        source_revision=excluded.source_revision,
                        source_sequence=excluded.source_sequence,
                        source_evidence_hash=excluded.source_evidence_hash,
                        position_revision=excluded.position_revision,
                        position_shares=excluded.position_shares,
                        working_set_hash=excluded.working_set_hash,
                        visibility_head_revision=excluded.visibility_head_revision,
                        updated_at_epoch_ms=excluded.updated_at_epoch_ms,
                        revision=exit_claim_visibility_bindings.revision+1
                `)
                .run(
                    claim.exitClaimId,
                    accountBrokerRef,
                    accountIdRef,
                    tradeDate,
                    contractKey,
                    sourceRevision,
                    sourceSequence,
                    sourceEvidenceHash,
                    positionRevision,
                    positionShares,
                    workingSet.workingSetHash,
                    headRevision,
                    now,
                    now,
                );
        }
        for (const claim of workingSet.claims) {
            insertTransitionJournalEvent(database, {
                entityKind: 'exit_claim',
                entityId: claim.exitClaimId,
                revision: 0,
                reasonCode: 'TASK_0_3C_EXTERNAL_WORKING_SELL_RECONCILED',
                summaryCode: 'task_0_3c_external_working_sell_reconciled',
                nowEpochMs: now,
                payloadHash: sourceEvidenceHash,
                eventSuffix: `task-0-3c-${headRevision}`,
            });
        }
        advanceLifecycleSideEffectRevision(database);
        return Object.freeze({
            state: 'recorded',
            externalSellClaimCount: workingSet.claims.length,
            workingSetHash: workingSet.workingSetHash,
            visibilityRevision: headRevision,
            brokerWriteAuthority: false,
        });
    });
}

function markExternalExitClaimTerminal(database, input) {
    rejectCallerSuppliedJournalEvent(input);
    const exitClaimId = boundedToken(input.exitClaimId, 'exitClaimId');
    const state = boundedToken(input.state, 'externalClaim.state');
    if (!['consumed', 'released'].includes(state)) {
        throw new TypeError('external exit claim terminal state is invalid');
    }
    const now = safeInteger(input.nowEpochMs, 'externalClaim.nowEpochMs');
    const evidenceHash = sha256Digest(
        input.evidenceHash,
        'externalClaim.evidenceHash',
    );
    const expectedRevision = safeInteger(
        input.expectedRevision,
        'externalClaim.expectedRevision',
    );
    return transaction(database, () => {
        const result = database
            .prepare(`
                UPDATE exit_claims
                   SET state=?, evidence_hash=?, updated_at_epoch_ms=?,
                       terminal_at_epoch_ms=?, revision=revision+1
                 WHERE exit_claim_id=? AND external_lineage=1
                   AND obligation_id IS NULL
                   AND state IN ('broker_working','unknown') AND revision=?
            `)
            .run(
                state,
                evidenceHash,
                now,
                now,
                exitClaimId,
                expectedRevision,
            );
        if (Number(result.changes) !== 1) {
            throw new Error(
                'external exit claim terminal transition lost its optimistic revision',
            );
        }
        const revision = expectedRevision + 1;
        insertTransitionJournalEvent(database, {
            entityKind: 'exit_claim',
            entityId: exitClaimId,
            revision,
            reasonCode:
                state === 'consumed'
                    ? 'EXTERNAL_SELL_CONFIRMED_CONSUMED'
                    : 'EXTERNAL_SELL_CONFIRMED_RELEASED',
            summaryCode: `external_exit_claim_${state}`,
            nowEpochMs: now,
            payloadHash: evidenceHash,
            eventSuffix: `external-${state}`,
        });
        advanceLifecycleSideEffectRevision(database);
        return Object.freeze({
            exitClaimId,
            externalLineage: true,
            obligationId: null,
            state,
            terminalAtEpochMs: now,
            revision,
        });
    });
}

function addBrokerCorrelation(database, input) {
    const requiredKeys = [
        'accountBrokerRef',
        'accountIdRef',
        'contractKey',
        'correlationId',
        'createdAtEpochMs',
        'evidenceHash',
        'intentId',
        'side',
        'tradeDate',
    ];
    const optionalKeys = [
        'brokerOrderId',
        'customField',
        ...BROKER_CORRELATION_IDENTIFIER_KINDS,
    ];
    if (
        !input ||
        typeof input !== 'object' ||
        Array.isArray(input) ||
        requiredKeys.some((key) => !Object.hasOwn(input, key)) ||
        Object.keys(input).some(
            (key) => !requiredKeys.includes(key) && !optionalKeys.includes(key),
        )
    ) {
        throw new TypeError('broker correlation input schema is invalid');
    }
    const identifierEntries = BROKER_CORRELATION_IDENTIFIER_KINDS.filter(
        (kind) => typeof input[kind] === 'string' && input[kind].length > 0,
    );
    if (identifierEntries.length === 0) {
        throw new TypeError('broker correlation needs at least one verified identifier');
    }
    const unavailableIdentifier = identifierEntries.find(
        (kind) => !enabledBrokerCorrelationIdentifierKinds.has(kind),
    );
    if (unavailableIdentifier) {
        throw new Error(
            `broker correlation identifier capability is not verified: ${unavailableIdentifier}`,
        );
    }
    const canonical = {
        accountBrokerRef: boundedToken(input.accountBrokerRef, 'accountBrokerRef'),
        accountIdRef: boundedToken(input.accountIdRef, 'accountIdRef'),
        tradeDate: taipeiTradeDate(input.tradeDate),
        contractKey: boundedToken(input.contractKey, 'contractKey'),
        side: boundedToken(input.side, 'side'),
    };
    if (!['Buy', 'Sell'].includes(canonical.side)) {
        throw new TypeError('side must be Buy or Sell');
    }
    const optionalIdentifier = (value, label) =>
        value === undefined ? undefined : boundedToken(value, label);
    const tradeId = optionalIdentifier(input.tradeId, 'tradeId');
    const orderId = optionalIdentifier(input.orderId, 'orderId');
    const dealId = optionalIdentifier(input.dealId, 'dealId');
    const seqno = optionalIdentifier(input.seqno, 'seqno');
    const ordno = optionalIdentifier(input.ordno, 'ordno');
    const exchangeSequence = optionalIdentifier(
        input.exchangeSequence,
        'exchangeSequence',
    );
    const customField =
        input.customField === undefined
            ? undefined
            : boundedToken(input.customField, 'customField', 6);
    if (customField !== undefined && !/^[A-Za-z0-9]{1,6}$/.test(customField)) {
        throw new TypeError('customField must be 1-6 alphanumeric characters');
    }
    const correlationId = boundedToken(input.correlationId, 'correlationId');
    const intentId = boundedToken(input.intentId, 'intentId');
    const evidenceHash = sha256Digest(input.evidenceHash, 'evidenceHash');
    const createdAtEpochMs = safeInteger(
        input.createdAtEpochMs,
        'createdAtEpochMs',
    );
    const brokerOrderId =
        input.brokerOrderId === undefined
            ? null
            : boundedToken(input.brokerOrderId, 'brokerOrderId');
    Object.assign(canonical, {
        tradeId,
        orderId,
        dealId,
        seqno,
        ordno,
        exchangeSequence,
    });
    const validatedIdentifierValues = {
        tradeId,
        orderId,
        dealId,
        seqno,
        ordno,
        exchangeSequence,
    };
    const identifierBindings = identifierEntries.map((kind) =>
        Object.freeze({ kind, value: validatedIdentifierValues[kind] }),
    );
    const canonicalKeyHash = hashCanonicalCorrelation(canonical);
    return transaction(database, () => {
        const intent = database
            .prepare(`
                SELECT account_broker_ref, account_id_ref, trade_date,
                       contract_key, side
                  FROM order_intents WHERE intent_id=?
            `)
            .get(intentId);
        if (!intent) throw new Error('broker correlation intent does not exist');
        if (
            intent.account_broker_ref !== canonical.accountBrokerRef ||
            intent.account_id_ref !== canonical.accountIdRef ||
            intent.trade_date !== canonical.tradeDate ||
            intent.contract_key !== canonical.contractKey ||
            intent.side !== canonical.side
        ) {
            throw new Error(
                'broker correlation scope must exactly match its fixed intent scope',
            );
        }
        if (brokerOrderId !== null) {
            const brokerOrder = database
                .prepare('SELECT intent_id FROM broker_orders WHERE broker_order_id=?')
                .get(brokerOrderId);
            if (!brokerOrder || brokerOrder.intent_id !== intentId) {
                throw new Error(
                    'broker correlation order must belong to the same fixed intent',
                );
            }
        }
        const findIdentifierBinding = database.prepare(`
            SELECT intent_id, correlation_id
              FROM broker_correlation_identifiers
             WHERE account_broker_ref=? AND account_id_ref=? AND trade_date=?
               AND contract_key=? AND side=? AND identifier_kind=?
               AND identifier_value=?
        `);
        for (const binding of identifierBindings) {
            const existingBinding = findIdentifierBinding.get(
                canonical.accountBrokerRef,
                canonical.accountIdRef,
                canonical.tradeDate,
                canonical.contractKey,
                canonical.side,
                binding.kind,
                binding.value,
            );
            if (existingBinding) {
                if (existingBinding.intent_id !== intentId) {
                    throw new Error(
                        `broker correlation ${binding.kind} is already bound to a different intent in this fixed scope`,
                    );
                }
                if (existingBinding.correlation_id !== correlationId) {
                    throw new Error(
                        `broker correlation ${binding.kind} is already bound to a different correlation in this fixed scope`,
                    );
                }
            }
        }
        database
            .prepare(`
                INSERT INTO broker_correlations(
                    correlation_id, intent_id, broker_order_id,
                    canonical_key_hash, account_broker_ref, account_id_ref,
                    trade_date, contract_key, side, trade_id, order_id,
                    deal_id, seqno, ordno, exchange_sequence, custom_field,
                    evidence_hash, created_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            `)
            .run(
                correlationId,
                intentId,
                brokerOrderId,
                canonicalKeyHash,
                canonical.accountBrokerRef,
                canonical.accountIdRef,
                canonical.tradeDate,
                canonical.contractKey,
                canonical.side,
                tradeId ?? null,
                orderId ?? null,
                dealId ?? null,
                seqno ?? null,
                ordno ?? null,
                exchangeSequence ?? null,
                customField ?? null,
                evidenceHash,
                createdAtEpochMs,
            );
        const insertIdentifierBinding = database.prepare(`
            INSERT INTO broker_correlation_identifiers(
                account_broker_ref, account_id_ref, trade_date, contract_key,
                side, identifier_kind, identifier_value, intent_id,
                correlation_id, created_at_epoch_ms
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(
                account_broker_ref, account_id_ref, trade_date, contract_key,
                side, identifier_kind, identifier_value
            ) DO NOTHING
        `);
        for (const binding of identifierBindings) {
            insertIdentifierBinding.run(
                canonical.accountBrokerRef,
                canonical.accountIdRef,
                canonical.tradeDate,
                canonical.contractKey,
                canonical.side,
                binding.kind,
                binding.value,
                intentId,
                correlationId,
                createdAtEpochMs,
            );
            const storedBinding = findIdentifierBinding.get(
                canonical.accountBrokerRef,
                canonical.accountIdRef,
                canonical.tradeDate,
                canonical.contractKey,
                canonical.side,
                binding.kind,
                binding.value,
            );
            if (
                storedBinding?.intent_id !== intentId ||
                storedBinding?.correlation_id !== correlationId
            ) {
                throw new Error(
                    'broker correlation identifier binding lost its single-writer invariant',
                );
            }
        }
        insertTransitionJournalEvent(database, {
            entityKind: 'broker_correlation',
            entityId: correlationId,
            revision: 0,
            reasonCode: 'BROKER_CORRELATION_VERIFIED_AND_STORED',
            summaryCode: 'broker_correlation_stored',
            nowEpochMs: createdAtEpochMs,
            payloadHash: evidenceHash,
            eventSuffix: 'stored',
        });
        advanceLifecycleSideEffectRevision(database);
        return { correlationId, canonicalKeyHash };
    });
}

function storeGateManifestInTransaction(database, input) {
    const canonical = canonicalGateManifest(input, input.nowEpochMs);
    const existing = database
        .prepare(`
            SELECT manifest_sha256, manifest_json, state, revision
              FROM gate_manifests WHERE manifest_id=?
        `)
        .get(canonical.manifest.manifestId);
    if (existing) {
        if (
            existing.manifest_sha256 === canonical.manifest.manifestSha256 &&
            existing.manifest_json === canonical.serialized
        ) {
            return {
                manifestId: canonical.manifest.manifestId,
                manifestSha256: canonical.manifest.manifestSha256,
                state: existing.state,
                revision: existing.revision,
                replayed: true,
                authoritativeForDispatch: false,
            };
        }
        throw new Error('gate manifest id was reused with different content');
    }
    const superseded = database
            .prepare(`
                SELECT manifest_id, manifest_sha256, revision
                  FROM gate_manifests
                 WHERE provenance=? AND state IN ('observe_only','eligible')
            `)
            .all(canonical.provenance);
        database
            .prepare(`
                UPDATE gate_manifests
                   SET state='invalidated', invalidated_at_epoch_ms=?,
                       invalidation_reason='superseded', revision=revision+1
                 WHERE provenance=? AND state IN ('observe_only','eligible')
            `)
            .run(input.nowEpochMs, canonical.provenance);
        for (const row of superseded) {
            insertTransitionJournalEvent(database, {
                entityKind: 'gate_manifest',
                entityId: row.manifest_id,
                revision: row.revision + 1,
                reasonCode: 'GATE_MANIFEST_SUPERSEDED',
                summaryCode: 'gate_manifest_invalidated',
                nowEpochMs: input.nowEpochMs,
                payloadHash: row.manifest_sha256,
                eventSuffix: 'superseded',
            });
        }
        database
            .prepare(`
                INSERT INTO gate_manifests(
                    manifest_id, manifest_revision, manifest_sha256,
                    schema_version, provenance, manifest_json,
                    fingerprints_sha256, evidence_catalog_sha256,
                    feature_gates_sha256, product_boundary_consent_version,
                    state, valid_until_epoch_ms, created_at_epoch_ms, revision
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            `)
            .run(
                canonical.manifest.manifestId,
                canonical.manifest.manifestRevision,
                canonical.manifest.manifestSha256,
                canonical.manifest.schemaVersion,
                canonical.provenance,
                canonical.serialized,
                canonical.fingerprintsSha256,
                canonical.evidenceCatalogSha256,
                canonical.featureGatesSha256,
                canonical.manifest.productBoundaryConsentVersion,
                canonical.manifest.state,
                canonical.validUntilEpochMs,
                canonical.createdAtEpochMs,
            );
        insertJournalEvent(
            database,
            {
                eventId: `gate-manifest:${canonical.manifest.manifestId}:stored`,
                entityKind: 'gate_manifest',
                entityId: canonical.manifest.manifestId,
                reasonCode: 'GATE_MANIFEST_STORED',
                receiveEpochMs: input.nowEpochMs,
                payloadHash: canonical.manifest.manifestSha256,
                summaryCode:
                    canonical.manifest.state === 'eligible'
                        ? 'gate_manifest_eligible_data_stored'
                        : 'gate_manifest_observe_only_stored',
                createdAtEpochMs: input.nowEpochMs,
            },
            0,
        );
    return {
        manifestId: canonical.manifest.manifestId,
        manifestSha256: canonical.manifest.manifestSha256,
        state: canonical.manifest.state,
        revision: 0,
        replayed: false,
        // Persistence never grants broker authority by itself. Dispatch must
        // revalidate current verifier-issued evidence and the current arm.
        authoritativeForDispatch: false,
    };
}

function storeGateManifest(database, input) {
    return transaction(database, () =>
        storeGateManifestInTransaction(database, input),
    );
}

function storeGateManifestBatch(database, input) {
    if (!exactKeys(input, ['manifests', 'nowEpochMs'])) {
        throw new TypeError('gate manifest batch input is not exact');
    }
    if (!Array.isArray(input.manifests) || input.manifests.length !== 3) {
        throw new TypeError('gate manifest batch must contain three manifests');
    }
    const nowEpochMs = safeInteger(
        input.nowEpochMs,
        'gateManifestBatch.nowEpochMs',
    );
    const canonical = input.manifests.map((manifest) =>
        canonicalGateManifest({ manifest }, nowEpochMs),
    );
    const provenances = canonical.map((item) => item.provenance).sort();
    if (
        JSON.stringify(provenances) !==
        JSON.stringify(Object.keys(GATE_PROVENANCE_REQUIRED_EVIDENCE).sort())
    ) {
        throw new TypeError(
            'gate manifest batch must contain each provenance exactly once',
        );
    }
    return transaction(database, () => ({
        stored: storeGateManifestBatchInTransaction(
            database,
            input.manifests,
            nowEpochMs,
        ),
        authoritativeForDispatch: false,
    }));
}

function storeGateManifestBatchInTransaction(
    database,
    manifests,
    nowEpochMs,
) {
    return manifests.map((manifest) =>
        storeGateManifestInTransaction(database, {
            manifest,
            nowEpochMs,
        }),
    );
}

function gateManifestStatus(database, input) {
    const provenance = boundedToken(input.provenance, 'provenance');
    if (!Object.hasOwn(GATE_PROVENANCE_REQUIRED_EVIDENCE, provenance)) {
        throw new TypeError('gate manifest provenance is unsupported');
    }
    const now = safeInteger(input.nowEpochMs, 'gateManifestStatus.nowEpochMs');
    const row = database
        .prepare(`
            SELECT manifest_id, manifest_revision, manifest_sha256,
                   schema_version, provenance, state, manifest_json,
                   valid_until_epoch_ms,
                   created_at_epoch_ms, invalidated_at_epoch_ms,
                   invalidation_reason, revision
              FROM gate_manifests
             WHERE provenance=?
             ORDER BY created_at_epoch_ms DESC, rowid DESC
             LIMIT 1
        `)
        .get(provenance);
    if (!row) {
        return {
            present: false,
            state: 'observe_only',
            blocker: 'gate_manifest_missing',
            featureGates: Object.freeze(
                Object.fromEntries(GATE_FEATURE_IDS.map((feature) => [feature, false])),
            ),
            mappingRevision: null,
            pnlPolicyDefinitionSha256: null,
            pnlPolicyRevision: null,
            authoritativeForDispatch: false,
        };
    }
    const expired = row.valid_until_epoch_ms <= now;
    let featureGates = Object.freeze(
        Object.fromEntries(GATE_FEATURE_IDS.map((feature) => [feature, false])),
    );
    let mappingRevision = null;
    let pnlPolicyDefinitionSha256 = null;
    let pnlPolicyRevision = null;
    let accountReconciliationCapabilitySha256 = null;
    let accountReconciliationCapabilityVerified = false;
    let manifestProjectionInvalid = false;
    try {
        const manifest = JSON.parse(row.manifest_json);
        if (!testOnlyAllowSyntheticGateManifestProjection) {
            if (row.created_at_epoch_ms > now) {
                throw new Error('stored Gate manifest is future-dated');
            }
            const validationNow = expired
                ? row.valid_until_epoch_ms - 1
                : now;
            const canonical = canonicalGateManifest(
                { manifest },
                validationNow,
            );
            const invalidated = row.state === 'invalidated';
            if (invalidated) {
                if (
                    !Number.isSafeInteger(row.invalidated_at_epoch_ms) ||
                    row.invalidated_at_epoch_ms < row.created_at_epoch_ms ||
                    row.invalidated_at_epoch_ms > now ||
                    typeof row.invalidation_reason !== 'string' ||
                    row.invalidation_reason.length === 0 ||
                    row.invalidation_reason.length > 240
                ) {
                    throw new Error(
                        'stored Gate manifest invalidation metadata is invalid',
                    );
                }
            } else if (
                row.invalidated_at_epoch_ms !== null ||
                row.invalidation_reason !== null
            ) {
                throw new Error(
                    'active Gate manifest retains invalidation metadata',
                );
            }
            if (
                canonical.serialized !== row.manifest_json ||
                canonical.manifest.manifestId !== row.manifest_id ||
                canonical.manifest.manifestRevision !== row.manifest_revision ||
                canonical.manifest.manifestSha256 !== row.manifest_sha256 ||
                canonical.manifest.schemaVersion !== row.schema_version ||
                canonical.provenance !== row.provenance ||
                canonical.createdAtEpochMs !== row.created_at_epoch_ms ||
                canonical.validUntilEpochMs !== row.valid_until_epoch_ms ||
                (!invalidated && canonical.manifest.state !== row.state)
            ) {
                throw new Error(
                    'stored Gate manifest row does not match canonical content',
                );
            }
        }
        if (!exactKeys(manifest?.featureGates, GATE_FEATURE_IDS)) {
            throw new TypeError('stored feature gate projection is not exact');
        }
        const projected = {};
        for (const feature of GATE_FEATURE_IDS) {
            if (typeof manifest.featureGates[feature] !== 'boolean') {
                throw new TypeError('stored feature gate projection is invalid');
            }
            projected[feature] = manifest.featureGates[feature];
        }
        featureGates = Object.freeze(projected);
        mappingRevision = boundedToken(
            manifest?.fingerprints?.mappingRevision,
            'stored gate manifest mappingRevision',
        );
        if (
            manifest?.fingerprints?.pnlPolicyDefinitionSha256 !== undefined ||
            manifest?.fingerprints?.pnlPolicyRevision !== undefined
        ) {
            pnlPolicyDefinitionSha256 = sha256Digest(
                manifest?.fingerprints?.pnlPolicyDefinitionSha256,
                'stored gate manifest pnlPolicyDefinitionSha256',
            );
            pnlPolicyRevision = boundedToken(
                manifest?.fingerprints?.pnlPolicyRevision,
                'stored gate manifest pnlPolicyRevision',
            );
        }
        const evidenceByClass = new Map();
        let nodeSqliteCapabilityEvidence = null;
        for (const entry of manifest.evidence ?? []) {
            const normalizedClass =
                entry?.evidenceClass === 'live_readonly'
                    ? 'readonly_contract'
                    : entry?.evidenceClass;
            if (
                ACCOUNT_RECONCILIATION_CAPABILITY_EVIDENCE.includes(
                    normalizedClass,
                )
            ) {
                evidenceByClass.set(normalizedClass, {
                    evidenceClass: normalizedClass,
                    evidenceId: boundedToken(
                        entry.evidenceId,
                        'stored reconciliation evidenceId',
                    ),
                    resultSha256: sha256Digest(
                        entry.resultSha256,
                        'stored reconciliation resultSha256',
                    ),
                    sourceSha256: sha256Digest(
                        entry.sourceSha256,
                        'stored reconciliation sourceSha256',
                    ),
                });
            }
            if (normalizedClass === 'node_sqlite_capability') {
                if (nodeSqliteCapabilityEvidence !== null) {
                    throw new Error(
                        'stored Node SQLite capability evidence is duplicated',
                    );
                }
                nodeSqliteCapabilityEvidence = {
                    sourceSha256: sha256Digest(
                        entry.sourceSha256,
                        'stored Node SQLite capability sourceSha256',
                    ),
                };
            }
        }
        if (nodeSqliteCapabilityEvidence !== null) {
            if (
                typeof appSupportRoot !== 'string' ||
                !path.isAbsolute(appSupportRoot)
            ) {
                throw new Error(
                    'Node SQLite capability current-state binding is unavailable',
                );
            }
            const currentNodeSqliteAuthority =
                currentSmartOrderNodeSqliteCapabilityAuthorityStateSync(
                    appSupportRoot,
                );
            if (
                nodeSqliteCapabilityEvidence.sourceSha256 !==
                currentNodeSqliteAuthority.authoritySha256
            ) {
                throw new Error(
                    'stored Node SQLite capability authority has drifted',
                );
            }
        }
        accountReconciliationCapabilityVerified =
            row.provenance === 'automation' &&
            row.state === 'eligible' &&
            pnlPolicyDefinitionSha256 ===
                SMART_ORDER_CANONICAL_PNL_POLICY_DEFINITION_SHA256 &&
            pnlPolicyRevision === SMART_ORDER_CANONICAL_PNL_POLICY_REVISION &&
            ACCOUNT_RECONCILIATION_CAPABILITY_EVIDENCE.every((evidenceClass) =>
                evidenceByClass.has(evidenceClass),
            );
        if (accountReconciliationCapabilityVerified) {
            accountReconciliationCapabilitySha256 = sha256Canonical(
                [
                    'smart-order-account-reconciliation-capability/2026-08-13.1',
                    row.manifest_id,
                    row.manifest_revision,
                    row.manifest_sha256,
                    mappingRevision,
                    pnlPolicyDefinitionSha256,
                    pnlPolicyRevision,
                    ACCOUNT_RECONCILIATION_CAPABILITY_EVIDENCE.map(
                        (evidenceClass) => evidenceByClass.get(evidenceClass),
                    ),
                ],
                'account reconciliation capability',
            );
        }
    } catch {
        manifestProjectionInvalid = true;
        featureGates = Object.freeze(
            Object.fromEntries(
                GATE_FEATURE_IDS.map((feature) => [feature, false]),
            ),
        );
        mappingRevision = null;
        pnlPolicyDefinitionSha256 = null;
        pnlPolicyRevision = null;
        accountReconciliationCapabilitySha256 = null;
        accountReconciliationCapabilityVerified = false;
    }
    if (
        row.valid_until_epoch_ms <= now ||
        row.state === 'invalidated' ||
        manifestProjectionInvalid
    ) {
        accountReconciliationCapabilitySha256 = null;
        accountReconciliationCapabilityVerified = false;
    }
    return {
        present: true,
        manifestId: row.manifest_id,
        manifestRevision: row.manifest_revision,
        manifestSha256: row.manifest_sha256,
        schemaVersion: row.schema_version,
        provenance: row.provenance,
        state:
            expired || row.state === 'invalidated' || manifestProjectionInvalid
                ? 'observe_only'
                : row.state,
        blocker: manifestProjectionInvalid
            ? 'gate_manifest_projection_invalid'
            : expired
            ? 'gate_manifest_expired'
            : row.state === 'invalidated'
              ? row.invalidation_reason ?? 'gate_manifest_invalidated'
              : null,
        featureGates,
        mappingRevision,
        pnlPolicyDefinitionSha256,
        pnlPolicyRevision,
        accountReconciliationCapabilitySha256,
        accountReconciliationCapabilityVerified,
        validUntilEpochMs: row.valid_until_epoch_ms,
        createdAtEpochMs: row.created_at_epoch_ms,
        revision: row.revision,
        authoritativeForDispatch: false,
    };
}

function invalidateGateManifests(database, input) {
    const now = safeInteger(
        input.nowEpochMs,
        'invalidateGateManifests.nowEpochMs',
    );
    const reason = boundedToken(input.reason, 'invalidationReason');
    const provenance =
        input.provenance === undefined
            ? undefined
            : boundedToken(input.provenance, 'provenance');
    if (
        provenance !== undefined &&
        !Object.hasOwn(GATE_PROVENANCE_REQUIRED_EVIDENCE, provenance)
    ) {
        throw new TypeError('gate manifest provenance is unsupported');
    }
    return transaction(database, () => {
        const rows = provenance
            ? database
                  .prepare(`
                      SELECT manifest_id, manifest_sha256, revision
                        FROM gate_manifests
                       WHERE provenance=? AND state IN ('observe_only','eligible')
                  `)
                  .all(provenance)
            : database
                  .prepare(`
                      SELECT manifest_id, manifest_sha256, revision
                        FROM gate_manifests
                       WHERE state IN ('observe_only','eligible')
                  `)
                  .all();
        const result = provenance
            ? database
                  .prepare(`
                      UPDATE gate_manifests
                         SET state='invalidated', invalidated_at_epoch_ms=?,
                             invalidation_reason=?, revision=revision+1
                       WHERE provenance=? AND state IN ('observe_only','eligible')
                  `)
                  .run(now, reason, provenance)
            : database
                  .prepare(`
                      UPDATE gate_manifests
                         SET state='invalidated', invalidated_at_epoch_ms=?,
                             invalidation_reason=?, revision=revision+1
                       WHERE state IN ('observe_only','eligible')
                  `)
                  .run(now, reason);
        for (const row of rows) {
            insertTransitionJournalEvent(database, {
                entityKind: 'gate_manifest',
                entityId: row.manifest_id,
                revision: row.revision + 1,
                reasonCode: 'GATE_MANIFEST_EXPLICITLY_INVALIDATED',
                summaryCode: 'gate_manifest_invalidated',
                nowEpochMs: now,
                payloadHash: row.manifest_sha256,
                eventSuffix: 'invalidated',
            });
        }
        return { invalidatedCount: Number(result.changes), reason };
    });
}

function consumeAuthority(database, input) {
    const authorityKind = boundedToken(input.authorityKind, 'authorityKind');
    const authorityId = boundedToken(input.authorityId, 'authorityId');
    const payloadHash = sha256Digest(
        input.authorityPayloadHash,
        'authorityPayloadHash',
    );
    const scopeHash = sha256Digest(input.scopeHash, 'scopeHash');
    const consumedBy = boundedToken(input.consumedBy, 'consumedBy');
    const runtimeEpochId =
        input.runtimeEpochId === undefined
            ? null
            : boundedToken(input.runtimeEpochId, 'runtimeEpochId');
    const consumedAtEpochMs = safeInteger(
        input.consumedAtEpochMs,
        'consumedAtEpochMs',
    );
    return transaction(database, () => {
        const existing = database
            .prepare(`
                SELECT authority_payload_hash, scope_hash, consumed_by,
                       runtime_epoch_id, consumed_at_epoch_ms
                  FROM authority_consumptions
                 WHERE authority_kind=? AND authority_id=?
            `)
            .get(authorityKind, authorityId);
        if (existing) {
            throw new Error('authority was already durably consumed');
        }
        database
            .prepare(`
                INSERT INTO authority_consumptions(
                    authority_kind, authority_id, authority_payload_hash,
                    scope_hash, consumed_by, runtime_epoch_id,
                    consumed_at_epoch_ms
                ) VALUES (?, ?, ?, ?, ?, ?, ?)
            `)
            .run(
                authorityKind,
                authorityId,
                payloadHash,
                scopeHash,
                consumedBy,
                runtimeEpochId,
                consumedAtEpochMs,
            );
        const consumptionEntityId = sha256Canonical(
            { authorityKind, authorityId },
            'authority consumption identity',
        );
        insertTransitionJournalEvent(database, {
            entityKind: 'authority_consumption',
            entityId: consumptionEntityId,
            revision: 0,
            reasonCode: 'ONE_TIME_AUTHORITY_DURABLY_CONSUMED',
            summaryCode: 'authority_consumed',
            nowEpochMs: consumedAtEpochMs,
            payloadHash,
            eventSuffix: 'consumed',
        });
        return {
            consumed: true,
            authorityKind,
            authorityId,
            authorityPayloadHash: payloadHash,
            scopeHash,
            consumedAtEpochMs,
        };
    });
}

function reserveRequestReplayInTransaction(database, input) {
    const requestId = boundedToken(input.requestId, 'requestId');
    const operationKind = boundedToken(input.operationKind, 'operationKind');
    const payloadHash = sha256Digest(input.payloadHash, 'payloadHash');
    const now = safeInteger(input.nowEpochMs, 'requestReplay.nowEpochMs');
    const existing = database
            .prepare(`
                SELECT operation_kind, payload_hash, result_hash,
                       result_status, result_json, state
                  FROM request_replays WHERE request_id=?
            `)
            .get(requestId);
    if (existing) {
            if (
                existing.operation_kind !== operationKind ||
                existing.payload_hash !== payloadHash
            ) {
                throw new Error('request id was reused with different content');
            }
            if (existing.state === 'reserved') {
                if (
                    existing.result_hash !== null ||
                    existing.result_status !== null ||
                    existing.result_json !== null
                ) {
                    throw new Error('reserved request replay contains a result');
                }
                return {
                    requestId,
                    state: existing.state,
                    replayed: true,
                    mayExecute: false,
                };
            }
            if (existing.state === 'outcome_unknown') {
                if (
                    existing.result_status !== null ||
                    existing.result_json !== null
                ) {
                    throw new Error('unknown request replay contains a public result');
                }
                return {
                    requestId,
                    state: existing.state,
                    resultHash: existing.result_hash ?? undefined,
                    replayed: true,
                    mayExecute: false,
                };
            }
            const resultStatus = safeInteger(
                existing.result_status,
                'requestReplay.resultStatus',
            );
            if (
                (existing.state === 'completed' && resultStatus !== 200) ||
                (existing.state === 'failed' &&
                    (resultStatus < 400 || resultStatus > 599))
            ) {
                throw new Error('request replay result status does not match its state');
            }
            const result = parseStoredCanonicalObject(
                existing.result_json,
                'requestReplay.result',
            );
            const resultHash = sha256Canonical(result, 'requestReplay.result');
            if (existing.result_hash !== resultHash) {
                throw new Error('request replay result hash mismatch');
            }
        return {
                requestId,
                state: existing.state,
                resultHash,
                resultStatus,
                result,
                replayed: true,
                mayExecute: false,
        };
    }
    const replayCount = Number(
        database
            .prepare('SELECT COUNT(*) AS count FROM request_replays')
            .get()?.count,
    );
    if (replayCount >= configuredRequestReplayMaxRows) {
        throw new Error('request replay repository capacity exhausted');
    }
    database
            .prepare(`
                INSERT INTO request_replays(
                    request_id, operation_kind, payload_hash, state,
                    created_at_epoch_ms, updated_at_epoch_ms
                ) VALUES (?, ?, ?, 'reserved', ?, ?)
            `)
            .run(requestId, operationKind, payloadHash, now, now);
        insertTransitionJournalEvent(database, {
            entityKind: 'request_replay',
            entityId: requestId,
            revision: 0,
            reasonCode: 'REQUEST_REPLAY_RESERVED',
            summaryCode: 'request_replay_reserved',
            nowEpochMs: now,
            payloadHash,
            eventSuffix: 'reserved',
        });
    return {
            requestId,
            state: 'reserved',
            replayed: false,
            mayExecute: true,
    };
}

function reserveRequestReplay(database, input) {
    return transaction(database, () =>
        reserveRequestReplayInTransaction(database, input),
    );
}

function completeRequestReplayInTransaction(database, input) {
    const requestId = boundedToken(input.requestId, 'requestId');
    const operationKind = boundedToken(input.operationKind, 'operationKind');
    const payloadHash = sha256Digest(input.payloadHash, 'payloadHash');
    const resultStatus = safeInteger(
        input.resultStatus,
        'requestReplay.resultStatus',
    );
    if (resultStatus !== 200) {
        throw new TypeError('completed request replay resultStatus must be 200');
    }
    const resultJson = canonicalJson(input.result, 'requestReplay.result');
    const resultHash = sha256Canonical(input.result, 'requestReplay.result');
    const now = safeInteger(input.nowEpochMs, 'requestReplay.nowEpochMs');
    const update = database
            .prepare(`
                UPDATE request_replays
                   SET state='completed', result_hash=?, result_status=?,
                       result_json=?, updated_at_epoch_ms=?
                 WHERE request_id=? AND operation_kind=? AND payload_hash=?
                   AND state='reserved'
            `)
            .run(
                resultHash,
                resultStatus,
                resultJson,
                now,
                requestId,
                operationKind,
                payloadHash,
            );
    if (Number(update.changes) !== 1) {
        throw new Error('request replay completion lost its durable CAS');
    }
    insertTransitionJournalEvent(database, {
            entityKind: 'request_replay',
            entityId: requestId,
            revision: 1,
            reasonCode: 'REQUEST_REPLAY_COMPLETED',
            summaryCode: 'request_replay_completed',
            nowEpochMs: now,
            payloadHash: resultHash,
            eventSuffix: 'completed',
        });
    return {
            requestId,
            state: 'completed',
            resultHash,
            resultStatus,
    };
}

function completeRequestReplay(database, input) {
    return transaction(database, () =>
        completeRequestReplayInTransaction(database, input),
    );
}

function failRequestReplayInTransaction(database, input) {
    const requestId = boundedToken(input.requestId, 'requestId');
    const operationKind = boundedToken(input.operationKind, 'operationKind');
    const payloadHash = sha256Digest(input.payloadHash, 'payloadHash');
    const resultStatus = safeInteger(
        input.resultStatus,
        'requestReplay.resultStatus',
    );
    if (resultStatus < 400 || resultStatus > 599) {
        throw new TypeError('failed request replay resultStatus must be 400..599');
    }
    const resultJson = canonicalJson(input.result, 'requestReplay.result');
    const resultHash = sha256Canonical(input.result, 'requestReplay.result');
    const now = safeInteger(input.nowEpochMs, 'requestReplay.nowEpochMs');
    const update = database
            .prepare(`
                UPDATE request_replays
                   SET state='failed', result_hash=?, result_status=?,
                       result_json=?, updated_at_epoch_ms=?
                 WHERE request_id=? AND operation_kind=? AND payload_hash=?
                   AND state='reserved'
            `)
            .run(
                resultHash,
                resultStatus,
                resultJson,
                now,
                requestId,
                operationKind,
                payloadHash,
            );
    if (Number(update.changes) !== 1) {
        throw new Error('request replay failure lost its durable CAS');
    }
    insertTransitionJournalEvent(database, {
            entityKind: 'request_replay',
            entityId: requestId,
            revision: 1,
            reasonCode: 'REQUEST_REPLAY_FAILED',
            summaryCode: 'request_replay_failed',
            nowEpochMs: now,
            payloadHash: resultHash,
            eventSuffix: 'failed',
        });
    return {
            requestId,
            state: 'failed',
            resultHash,
            resultStatus,
    };
}

function failRequestReplay(database, input) {
    return transaction(database, () =>
        failRequestReplayInTransaction(database, input),
    );
}

const GATE_PROBE_OPERATION_KIND = 'gate_probe_operation';
const GATE_PROBE_RESULT_SCHEMA_VERSION =
    'smart-order-gate-probe-durable-result/2026-08-20.1';
const GATE_PROBE_MAX_DURABLE_OPERATIONS = 256;

function gateProbeTargetMatches(left, right) {
    return Boolean(
        left &&
            right &&
            left.originRunId === right.originRunId &&
            left.targetIdSha256 === right.targetIdSha256 &&
            left.tradeIdSha256 === right.tradeIdSha256 &&
            left.accountScopeSha256 === right.accountScopeSha256 &&
            left.tradeDate === right.tradeDate &&
            left.revision === right.revision &&
            left.quantityCommonLots === 1 &&
            right.quantityCommonLots === 1 &&
            left.nonTerminal === true &&
            right.nonTerminal === true &&
            left.correlationUnique === true &&
            right.correlationUnique === true,
    );
}

function canonicalStoredGateProbeResult(value, label) {
    if (
        !exactKeys(value, [
            'accountScopeSha256',
            'automaticRetryAllowed',
            'brokerAuthority',
            'cleanupAllowed',
            'cliAuthorizationSha256',
            'envelopeSha256',
            'manifestSha256',
            'operation',
            'postTarget',
            'resultEvidenceSha256',
            'runId',
            'safetyAttestationSha256',
            'schemaVersion',
            'state',
            'target',
            'tradeDate',
            'validUntilEpochMs',
            'writeMasterAuthority',
        ]) ||
        value.schemaVersion !== GATE_PROBE_RESULT_SCHEMA_VERSION ||
        !['prepared', 'broker_rejected', 'confirmed'].includes(value.state) ||
        !['place', 'update', 'cancel'].includes(value.operation) ||
        !/^[0-9a-f-]{36}$/.test(value.runId ?? '') ||
        !/^\d{4}-\d{2}-\d{2}$/.test(value.tradeDate ?? '') ||
        value.automaticRetryAllowed !== false ||
        value.cleanupAllowed !== false ||
        value.brokerAuthority !== false ||
        value.writeMasterAuthority !== false
    ) {
        throw new Error(`${label} schema is invalid`);
    }
    sha256Digest(value.envelopeSha256, `${label}.envelopeSha256`);
    sha256Digest(
        value.cliAuthorizationSha256,
        `${label}.cliAuthorizationSha256`,
    );
    sha256Digest(value.accountScopeSha256, `${label}.accountScopeSha256`);
    sha256Digest(value.manifestSha256, `${label}.manifestSha256`);
    sha256Digest(
        value.safetyAttestationSha256,
        `${label}.safetyAttestationSha256`,
    );
    safeInteger(value.validUntilEpochMs, `${label}.validUntilEpochMs`);
    const target =
        value.target === null
            ? null
            : canonicalSmartOrderGateProbeTarget(value.target, `${label}.target`);
    const postTarget =
        value.postTarget === null
            ? null
            : canonicalSmartOrderGateProbeTarget(
                  value.postTarget,
                  `${label}.postTarget`,
              );
    if (
        (value.state === 'prepared' &&
            (value.postTarget !== null || value.resultEvidenceSha256 !== null)) ||
        (value.state !== 'prepared' &&
            !/^sha256:[0-9a-f]{64}$/.test(value.resultEvidenceSha256 ?? '')) ||
        (value.operation === 'place' && target !== null) ||
        (value.operation !== 'place' && target === null) ||
        (value.state === 'broker_rejected' && postTarget !== null) ||
        (value.state === 'confirmed' &&
            value.operation === 'cancel' &&
            postTarget !== null) ||
        (value.state === 'confirmed' &&
            value.operation !== 'cancel' &&
            postTarget === null)
    ) {
        throw new Error(`${label} state projection is invalid`);
    }
    return Object.freeze({ ...value, target, postTarget });
}

function gateProbeLedger(database, { ignoreRequestId } = {}) {
    const rows = database
        .prepare(`
            SELECT request_id, payload_hash, result_hash, result_status,
                   result_json, state, created_at_epoch_ms,
                   updated_at_epoch_ms
              FROM request_replays
             WHERE operation_kind=?
             ORDER BY created_at_epoch_ms, request_id
        `)
        .all(GATE_PROBE_OPERATION_KIND);
    if (rows.length > GATE_PROBE_MAX_DURABLE_OPERATIONS) {
        throw new Error('gate probe durable operation capacity is exhausted');
    }
    const targets = new Map();
    let unknownCount = 0;
    let unresolvedCount = 0;
    let terminalCount = 0;
    for (const row of rows) {
        if (row.request_id === ignoreRequestId) continue;
        if (row.state === 'outcome_unknown') {
            unknownCount += 1;
            continue;
        }
        if (row.state !== 'completed' || row.result_status !== 200) {
            unresolvedCount += 1;
            continue;
        }
        const stored = parseStoredCanonicalObject(
            row.result_json,
            'gate probe durable result',
        );
        if (
            sha256Canonical(stored, 'gate probe durable result') !==
            row.result_hash
        ) {
            throw new Error('gate probe durable result hash mismatch');
        }
        const result = canonicalStoredGateProbeResult(
            stored,
            'gate probe durable result',
        );
        if (result.state === 'prepared') {
            unresolvedCount += 1;
            continue;
        }
        terminalCount += 1;
        if (result.state === 'broker_rejected') continue;
        if (result.operation === 'place') {
            if (targets.has(result.postTarget.targetIdSha256)) {
                throw new Error('gate probe target lineage was duplicated');
            }
            targets.set(result.postTarget.targetIdSha256, result.postTarget);
            continue;
        }
        const current = targets.get(result.target.targetIdSha256);
        if (!gateProbeTargetMatches(current, result.target)) {
            throw new Error('gate probe target lineage or revision is non-canonical');
        }
        if (result.operation === 'update') {
            if (
                result.postTarget.targetIdSha256 !==
                    result.target.targetIdSha256 ||
                result.postTarget.tradeIdSha256 !==
                    result.target.tradeIdSha256 ||
                result.postTarget.originRunId !== result.target.originRunId ||
                result.postTarget.accountScopeSha256 !==
                    result.target.accountScopeSha256 ||
                result.postTarget.tradeDate !== result.target.tradeDate ||
                result.postTarget.revision <= result.target.revision
            ) {
                throw new Error('gate probe update target projection is invalid');
            }
            targets.set(
                result.postTarget.targetIdSha256,
                result.postTarget,
            );
        } else {
            targets.delete(result.target.targetIdSha256);
        }
    }
    return Object.freeze({
        rows: Object.freeze(rows),
        targets,
        unknownCount,
        unresolvedCount,
        terminalCount,
    });
}

function gateProbePreparedResult(
    canonical,
    manifestSha256,
    safetyAttestationSha256,
    cliAuthorizationSha256,
) {
    return Object.freeze({
        schemaVersion: GATE_PROBE_RESULT_SCHEMA_VERSION,
        state: 'prepared',
        operation: canonical.envelope.operation,
        runId: canonical.envelope.runId,
        envelopeSha256: canonical.envelopeSha256,
        accountScopeSha256: canonical.envelope.accountScopeSha256,
        cliAuthorizationSha256,
        tradeDate: canonical.envelope.tradeDate,
        target: canonical.envelope.target,
        postTarget: null,
        manifestSha256,
        safetyAttestationSha256,
        validUntilEpochMs: canonical.envelope.validUntilEpochMs,
        resultEvidenceSha256: null,
        automaticRetryAllowed: false,
        cleanupAllowed: false,
        brokerAuthority: false,
        writeMasterAuthority: false,
    });
}

function prepareGateProbeSafetyEnvelope(database, input) {
    if (
        !exactKeys(input, [
            'apiGeneration',
            'cliAuthorizationSha256',
            'envelope',
            'manifestSha256',
            'nowEpochMs',
            'runtimeEpochId',
            'safetyAttestationSha256',
            'senderFence',
        ])
    ) {
        throw new TypeError('gate probe prepare input is invalid');
    }
    const canonical = canonicalSmartOrderGateProbeSafetyEnvelope(
        input.envelope,
    );
    const now = safeInteger(input.nowEpochMs, 'gateProbe.nowEpochMs');
    const runtimeEpochId = boundedToken(
        input.runtimeEpochId,
        'gateProbe.runtimeEpochId',
    );
    const senderFence = boundedToken(input.senderFence, 'gateProbe.senderFence');
    const apiGeneration = boundedToken(
        input.apiGeneration,
        'gateProbe.apiGeneration',
    );
    const manifestSha256 = sha256Digest(
        input.manifestSha256,
        'gateProbe.manifestSha256',
    );
    const safetyAttestationSha256 = sha256Digest(
        input.safetyAttestationSha256,
        'gateProbe.safetyAttestationSha256',
    );
    const cliAuthorizationSha256 = sha256Digest(
        input.cliAuthorizationSha256,
        'gateProbe.cliAuthorizationSha256',
    );
    if (!smartOrderGateProbeEnvelopeIsCurrent(canonical.envelope, now)) {
        throw new Error('gate probe explicit authorization is expired or overlong');
    }
    return transaction(database, () => {
        const durableNow = Date.now();
        if (
            durableNow < now ||
            !smartOrderGateProbeEnvelopeIsCurrent(
                canonical.envelope,
                durableNow,
            )
        ) {
            throw new Error(
                'gate probe authorization expired before durable nonce consumption',
            );
        }
        if (
            !currentReadySenderMatches(database, {
                runtimeEpochId,
                senderFence,
                apiGeneration,
            })
        ) {
            throw new Error('gate probe requires the current ready runtime sender');
        }
        const gate = gateManifestStatus(database, {
            provenance: 'gate_probe',
            nowEpochMs: durableNow,
        });
        if (
            gate.present !== true ||
            gate.state !== 'eligible' ||
            gate.manifestSha256 !== manifestSha256 ||
            gate.validUntilEpochMs <= durableNow
        ) {
            throw new Error('current eligible gate probe manifest is unavailable');
        }
        const replay = reserveRequestReplayInTransaction(database, {
            requestId: canonical.envelope.operationId,
            operationKind: GATE_PROBE_OPERATION_KIND,
            payloadHash: canonical.envelopeSha256,
            nowEpochMs: durableNow,
        });
        if (replay.replayed) {
            if (replay.state === 'completed') {
                return Object.freeze({
                    ...canonicalStoredGateProbeResult(
                        replay.result,
                        'gate probe replay result',
                    ),
                    replayed: true,
                });
            }
            return Object.freeze({
                schemaVersion: GATE_PROBE_RESULT_SCHEMA_VERSION,
                state: 'unknown',
                replayed: true,
                automaticRetryAllowed: false,
                cleanupAllowed: false,
                brokerAuthority: false,
                writeMasterAuthority: false,
            });
        }
        const ledger = gateProbeLedger(database, {
            ignoreRequestId: canonical.envelope.operationId,
        });
        if (ledger.unknownCount > 0 || ledger.unresolvedCount > 0) {
            throw new Error(
                'gate probe safety ledger is latched by an unresolved operation',
            );
        }
        if (canonical.envelope.operation === 'place') {
            if (ledger.targets.size !== 0) {
                throw new Error(
                    'gate probe cannot create a new run while a prior target remains live',
                );
            }
        } else {
            const target = ledger.targets.get(
                canonical.envelope.target.targetIdSha256,
            );
            if (!gateProbeTargetMatches(target, canonical.envelope.target)) {
                throw new Error(
                    'gate probe target is not the current same-run durable target',
                );
            }
        }
        const nonceExisting = database
            .prepare(`
                SELECT 1 FROM authority_consumptions
                 WHERE authority_kind='gate_probe_nonce'
                   AND authority_id=?
            `)
            .get(canonical.envelope.nonceSha256);
        if (nonceExisting) {
            throw new Error('gate probe nonce was already durably consumed');
        }
        const scopeHash = sha256Canonical(
            {
                accountScopeSha256: canonical.envelope.accountScopeSha256,
                runId: canonical.envelope.runId,
                tradeDate: canonical.envelope.tradeDate,
            },
            'gate probe durable scope',
        );
        database
            .prepare(`
                INSERT INTO authority_consumptions(
                    authority_kind, authority_id, authority_payload_hash,
                    scope_hash, consumed_by, runtime_epoch_id,
                    consumed_at_epoch_ms
                ) VALUES ('gate_probe_nonce', ?, ?, ?, ?, ?, ?)
            `)
            .run(
                canonical.envelope.nonceSha256,
                canonical.envelopeSha256,
                scopeHash,
                canonical.envelope.operationId,
                runtimeEpochId,
                durableNow,
            );
        insertTransitionJournalEvent(database, {
            entityKind: 'authority_consumption',
            entityId: sha256Canonical(
                {
                    authorityKind: 'gate_probe_nonce',
                    authorityId: canonical.envelope.nonceSha256,
                },
                'gate probe nonce consumption identity',
            ),
            revision: 0,
            reasonCode: 'ONE_TIME_AUTHORITY_DURABLY_CONSUMED',
            summaryCode: 'gate_probe_nonce_consumed',
            nowEpochMs: durableNow,
            payloadHash: canonical.envelopeSha256,
            eventSuffix: 'consumed',
        });
        const result = gateProbePreparedResult(
            canonical,
            manifestSha256,
            safetyAttestationSha256,
            cliAuthorizationSha256,
        );
        completeRequestReplayInTransaction(database, {
            requestId: canonical.envelope.operationId,
            operationKind: GATE_PROBE_OPERATION_KIND,
            payloadHash: canonical.envelopeSha256,
            resultStatus: 200,
            result,
            nowEpochMs: durableNow,
        });
        return Object.freeze({ ...result, replayed: false });
    });
}

function loadGateProbePreparedResult(
    database,
    canonical,
    label = 'gate probe prepared result',
) {
    const current = database
        .prepare(`
            SELECT result_hash, result_json, state, result_status
              FROM request_replays
             WHERE request_id=? AND operation_kind=? AND payload_hash=?
        `)
        .get(
            canonical.envelope.operationId,
            GATE_PROBE_OPERATION_KIND,
            canonical.envelopeSha256,
        );
    if (
        !current ||
        current.state !== 'completed' ||
        current.result_status !== 200
    ) {
        throw new Error('gate probe operation is not durably prepared');
    }
    const stored = canonicalStoredGateProbeResult(
        parseStoredCanonicalObject(current.result_json, label),
        label,
    );
    if (
        stored.state !== 'prepared' ||
        stored.envelopeSha256 !== canonical.envelopeSha256 ||
        sha256Canonical(stored, label) !== current.result_hash
    ) {
        throw new Error('gate probe prepared result changed or was already settled');
    }
    return Object.freeze({ current, stored });
}

function replaceGateProbePreparedResult(
    database,
    { canonical, nextResult, nowEpochMs },
) {
    const { current } = loadGateProbePreparedResult(database, canonical);
    const nextJson = stableCanonicalJson(nextResult);
    const nextHash = sha256Canonical(nextResult, 'gate probe durable result');
    const updated = database
        .prepare(`
            UPDATE request_replays
               SET result_hash=?, result_json=?, updated_at_epoch_ms=?
             WHERE request_id=? AND operation_kind=? AND payload_hash=?
               AND state='completed' AND result_status=200
               AND result_hash=? AND result_json=?
        `)
        .run(
            nextHash,
            nextJson,
            nowEpochMs,
            canonical.envelope.operationId,
            GATE_PROBE_OPERATION_KIND,
            canonical.envelopeSha256,
            current.result_hash,
            current.result_json,
        );
    if (Number(updated.changes) !== 1) {
        throw new Error('gate probe settlement lost its durable CAS');
    }
    insertTransitionJournalEvent(database, {
        entityKind: 'request_replay',
        entityId: canonical.envelope.operationId,
        revision: 2,
        reasonCode: 'REQUEST_REPLAY_COMPLETED',
        summaryCode: 'gate_probe_result_settled',
        nowEpochMs,
        payloadHash: nextHash,
        eventSuffix: 'gate-probe-settled',
    });
    return nextResult;
}

function settleGateProbeSafetyEnvelope(database, input) {
    if (
        !exactKeys(input, [
            'envelope',
            'nowEpochMs',
            'outcome',
            'postTarget',
            'resultEvidenceSha256',
        ])
    ) {
        throw new TypeError('gate probe settlement input is invalid');
    }
    const canonical = canonicalSmartOrderGateProbeSafetyEnvelope(
        input.envelope,
    );
    const now = safeInteger(input.nowEpochMs, 'gateProbe.settleNowEpochMs');
    const resultEvidenceSha256 = sha256Digest(
        input.resultEvidenceSha256,
        'gateProbe.resultEvidenceSha256',
    );
    if (!['confirmed', 'broker_rejected', 'response_lost'].includes(input.outcome)) {
        throw new TypeError('gate probe settlement outcome is invalid');
    }
    return transaction(database, () => {
        if (input.outcome === 'response_lost') {
            const { current } = loadGateProbePreparedResult(
                database,
                canonical,
                'gate probe response-loss prepared result',
            );
            const updated = database
                .prepare(`
                    UPDATE request_replays
                       SET state='outcome_unknown', result_hash=?,
                           result_status=NULL, result_json=NULL,
                           updated_at_epoch_ms=?
                     WHERE request_id=? AND operation_kind=? AND payload_hash=?
                       AND state='completed' AND result_status=200
                       AND result_hash=? AND result_json=?
                `)
                .run(
                    resultEvidenceSha256,
                    now,
                    canonical.envelope.operationId,
                    GATE_PROBE_OPERATION_KIND,
                    canonical.envelopeSha256,
                    current.result_hash,
                    current.result_json,
                );
            if (Number(updated.changes) !== 1) {
                throw new Error('gate probe response-loss latch lost its CAS');
            }
            insertTransitionJournalEvent(database, {
                entityKind: 'request_replay',
                entityId: canonical.envelope.operationId,
                revision: 2,
                reasonCode: 'BROKER_RESULT_UNRESOLVED',
                summaryCode: 'gate_probe_response_lost_no_retry_no_cleanup',
                nowEpochMs: now,
                payloadHash: resultEvidenceSha256,
                eventSuffix: 'gate-probe-unknown',
            });
            return Object.freeze({
                schemaVersion: GATE_PROBE_RESULT_SCHEMA_VERSION,
                state: 'unknown',
                automaticRetryAllowed: false,
                cleanupAllowed: false,
                manualInterventionRequired: true,
                reconciliationRequired: true,
                durableReplayProtection: true,
                brokerAuthority: false,
                writeMasterAuthority: false,
            });
        }

        const ledger = gateProbeLedger(database, {
            ignoreRequestId: canonical.envelope.operationId,
        });
        const { stored: prepared } = loadGateProbePreparedResult(
            database,
            canonical,
        );
        let postTarget = null;
        if (input.outcome === 'confirmed' && canonical.envelope.operation !== 'cancel') {
            postTarget = canonicalSmartOrderGateProbeTarget(
                input.postTarget,
                'gate probe confirmed post target',
            );
            if (
                postTarget.originRunId !== canonical.envelope.runId ||
                postTarget.accountScopeSha256 !==
                    canonical.envelope.accountScopeSha256 ||
                postTarget.tradeDate !== canonical.envelope.tradeDate
            ) {
                throw new Error('gate probe confirmed target scope is invalid');
            }
            if (canonical.envelope.operation === 'place') {
                if (ledger.targets.has(postTarget.targetIdSha256)) {
                    throw new Error('gate probe confirmed target already exists');
                }
            } else {
                const current = ledger.targets.get(
                    canonical.envelope.target.targetIdSha256,
                );
                if (
                    !gateProbeTargetMatches(current, canonical.envelope.target) ||
                    postTarget.targetIdSha256 !== current.targetIdSha256 ||
                    postTarget.tradeIdSha256 !== current.tradeIdSha256 ||
                    postTarget.revision <= current.revision
                ) {
                    throw new Error('gate probe confirmed update target is stale');
                }
            }
        } else if (input.postTarget !== null) {
            throw new Error('gate probe settlement must not invent a post target');
        }
        if (canonical.envelope.operation !== 'place') {
            const current = ledger.targets.get(
                canonical.envelope.target.targetIdSha256,
            );
            if (!gateProbeTargetMatches(current, canonical.envelope.target)) {
                throw new Error('gate probe settlement target changed');
            }
        }
        const nextResult = Object.freeze({
            ...prepared,
            state: input.outcome,
            postTarget,
            resultEvidenceSha256,
        });
        return Object.freeze(
            replaceGateProbePreparedResult(database, {
                canonical,
                nextResult,
                nowEpochMs: now,
            }),
        );
    });
}

function gateProbeSafetyStatus(database, input) {
    if (!exactKeys(input, [])) {
        throw new TypeError('gate probe safety status input must be empty');
    }
    const ledger = gateProbeLedger(database);
    return Object.freeze({
        schemaVersion: GATE_PROBE_RESULT_SCHEMA_VERSION,
        state:
            ledger.unknownCount > 0
                ? 'unknown_manual_intervention'
                : ledger.unresolvedCount > 0
                  ? 'prepared_no_retry'
                  : 'idle',
        unknownOperationCount: ledger.unknownCount,
        unresolvedOperationCount: ledger.unresolvedCount,
        terminalOperationCount: ledger.terminalCount,
        activeTargetCount: ledger.targets.size,
        automaticRetryAllowed: false,
        cleanupAllowed: false,
        durableReplayProtection: true,
        brokerAuthority: false,
        writeMasterAuthority: false,
    });
}

function executeStrategyMutationInTransaction(database, input) {
    if (!input || typeof input !== 'object' || Array.isArray(input)) {
        throw new TypeError('strategy mutation descriptor is invalid');
    }
    switch (input.kind) {
        case 'create':
            return createDraftStrategy(database, input, true);
        case 'update':
            return replaceDraftStrategy(database, input, true);
        case 'pause':
            return pauseStrategy(database, input, true);
        case 'cancel':
            return requestStrategyCancellation(database, input, true);
        case 'copy': {
            const sourceId = boundedToken(
                input.sourceStrategyId,
                'sourceStrategyId',
            );
            const expectedRevision = safeInteger(
                input.expectedRevision,
                'expectedRevision',
            );
            const source = database
                .prepare('SELECT revision FROM strategies WHERE strategy_id=?')
                .get(sourceId);
            if (!source || source.revision !== expectedRevision) {
                throw new Error('strategy copy lost its optimistic revision');
            }
            return copyStrategyToDraft(database, input, true);
        }
        case 'resume':
            return resumeStrategy(
                database,
                Object.fromEntries(
                    Object.entries(input).filter(([key]) => key !== 'kind'),
                ),
                true,
            );
        case 'cancel_broker_order':
            return requestBrokerOrderCancellation(
                database,
                Object.fromEntries(
                    Object.entries(input).filter(([key]) => key !== 'kind'),
                ),
                true,
            );
        case 'update_broker_order':
            return requestBrokerOrderQuantityReduction(
                database,
                Object.fromEntries(
                    Object.entries(input).filter(([key]) => key !== 'kind'),
                ),
                true,
            );
        case 'risk_policy_publish':
            return publishRuntimeRiskPolicyInTransaction(
                database,
                Object.fromEntries(
                    Object.entries(input).filter(([key]) => key !== 'kind'),
                ),
            );
        case 'risk_kill_switch':
            return mutateKillSwitchInTransaction(
                database,
                Object.fromEntries(
                    Object.entries(input).filter(([key]) => key !== 'kind'),
                ),
            );
        case 'manual_resolution_apply_unique_final':
            return applyManualResolutionUniqueFinalInTransaction(
                database,
                Object.fromEntries(
                    Object.entries(input).filter(([key]) => key !== 'kind'),
                ),
            );
        case 'strategy_confirmation_preview':
            return previewStrategyConfirmation(database, input);
        case 'strategy_confirmation_accept':
            return acceptStrategyConfirmation(database, input);
        case 'protected_entry_confirmation_preview':
            return previewProtectedEntryConfirmation(database, input);
        case 'protected_entry_confirmation_accept':
            return acceptProtectedEntryConfirmation(database, input);
        default:
            throw new TypeError('strategy mutation kind is unsupported');
    }
}

function executeReplayProtectedStrategyMutation(database, input) {
    const request = {
        requestId: input.requestId,
        operationKind: input.operationKind,
        payloadHash: input.payloadHash,
        nowEpochMs: input.nowEpochMs,
    };
    const acceptedOperationKinds = new Map([
        ['create', 'strategy_create_draft'],
        ['update', 'strategy_update_draft'],
        ['pause', 'strategy_pause'],
        ['resume', 'strategy_resume'],
        ['cancel_broker_order', 'broker_order_cancel_request'],
        ['update_broker_order', 'broker_order_update_request'],
        ['cancel', 'strategy_cancel'],
        ['copy', 'strategy_copy'],
        ['risk_policy_publish', 'risk_policy_publish'],
        ['risk_kill_switch', 'risk_kill_switch'],
        [
            'strategy_confirmation_preview',
            'strategy_confirmation_preview',
        ],
        [
            'strategy_confirmation_accept',
            'strategy_confirmation_accept',
        ],
        [
            'protected_entry_confirmation_preview',
            'protected_entry_confirmation_preview',
        ],
        [
            'protected_entry_confirmation_accept',
            'protected_entry_confirmation_accept',
        ],
        [
            'manual_resolution_apply_unique_final',
            'manual_resolution_apply_unique_final',
        ],
    ]);
    if (
        acceptedOperationKinds.get(input.mutation?.kind) !== input.operationKind
    ) {
        throw new TypeError('strategy mutation operation binding is invalid');
    }
    return transaction(database, () => {
        const replay = reserveRequestReplayInTransaction(database, request);
        if (replay.replayed) return replay;

        database.exec('SAVEPOINT strategy_mutation_effect');
        let result;
        try {
            result = executeStrategyMutationInTransaction(
                database,
                input.mutation,
            );
            database.exec('RELEASE strategy_mutation_effect');
        } catch (error) {
            database.exec('ROLLBACK TO strategy_mutation_effect');
            database.exec('RELEASE strategy_mutation_effect');
            const publicError = publicStrategyOperationError(error);
            const publicResult = {
                code: publicError.code,
                status: publicError.status,
            };
            const failed = failRequestReplayInTransaction(database, {
                ...request,
                resultStatus: publicError.status,
                result: publicResult,
            });
            return {
                ...failed,
                result: publicResult,
                replayed: false,
                mayExecute: false,
            };
        }

        if (testOnlyFailReplayCompletionAfterMutation === true) {
            if (process.env.VITEST !== 'true') {
                throw new Error('test-only replay fault injection is unavailable');
            }
            throw new Error('test replay failure after mutation before outcome commit');
        }
        const completed = completeRequestReplayInTransaction(database, {
            ...request,
            resultStatus: 200,
            result,
        });
        return {
            ...completed,
            result,
            replayed: false,
            mayExecute: false,
        };
    });
}

async function createRepositoryBackup(database, input) {
    const backupRoot = privateDirectoryRealpath(
        backupDirectory,
        'backupDirectory',
    );
    const backupName = boundedToken(input.backupName, 'backupName', 160);
    if (
        !/^[A-Za-z0-9][A-Za-z0-9._-]*\.sqlite3$/.test(backupName) ||
        backupName.includes('..')
    ) {
        throw new TypeError('backupName must be a safe .sqlite3 filename');
    }
    const finalPath = path.join(backupRoot, backupName);
    const manifestPath = `${finalPath}.manifest.json`;
    if (path.dirname(finalPath) !== backupRoot) {
        throw new Error('backup path escaped backupDirectory');
    }
    assertPathDoesNotExist(finalPath, 'backup artifact');
    assertPathDoesNotExist(manifestPath, 'backup manifest');

    const nonce = randomUUID();
    const pendingPath = path.join(backupRoot, `.${backupName}.pending-${nonce}`);
    const pendingManifestPath = `${pendingPath}.manifest.json`;
    let finalLinked = false;
    let manifestLinked = false;
    try {
        const copiedPages = await backup(database, pendingPath);
        chmodSync(pendingPath, PRIVATE_FILE_MODE);
        const snapshot = new DatabaseSync(pendingPath, { readOnly: true });
        let rowCounts;
        try {
            const integrity = snapshot.prepare('PRAGMA integrity_check').get()?.integrity_check;
            if (integrity !== 'ok') throw new Error('backup integrity check failed');
            if (snapshot.prepare('PRAGMA foreign_key_check').get()) {
                throw new Error('backup foreign-key check failed');
            }
            const schemaVersion = snapshot.prepare('PRAGMA user_version').get()?.user_version;
            const schemaId = snapshot
                .prepare("SELECT value FROM repository_meta WHERE key='schema_id'")
                .get()?.value;
            if (
                schemaVersion !== SMART_ORDER_REPOSITORY_SCHEMA_VERSION ||
                schemaId !== SMART_ORDER_REPOSITORY_SCHEMA_ID
            ) {
                throw new Error('backup schema identity mismatch');
            }
            rowCounts = Object.fromEntries(
                REQUIRED_SMART_ORDER_TABLES.map((table) => [
                    table,
                    snapshot.prepare(`SELECT COUNT(*) AS count FROM ${table}`).get()
                        ?.count,
                ]),
            );
        } finally {
            snapshot.close();
        }
        const databaseSha256 = `sha256:${createHash('sha256')
            .update(readFileSync(pendingPath))
            .digest('hex')}`;
        const manifest = Object.freeze({
            schemaVersion: 'smart-order-backup-manifest/2026-08-11.1',
            repositorySchemaId: SMART_ORDER_REPOSITORY_SCHEMA_ID,
            repositorySchemaVersion: SMART_ORDER_REPOSITORY_SCHEMA_VERSION,
            backupName,
            createdAtEpochMs: safeInteger(
                input.createdAtEpochMs,
                'backup.createdAtEpochMs',
            ),
            databaseSha256,
            copiedPages: safeInteger(copiedPages, 'backup.copiedPages'),
            rowCounts,
            containsSecrets: false,
        });
        writeFileSync(pendingManifestPath, `${JSON.stringify(manifest)}\n`, {
            encoding: 'utf8',
            flag: 'wx',
            mode: PRIVATE_FILE_MODE,
        });
        chmodSync(pendingManifestPath, PRIVATE_FILE_MODE);
        fsyncPath(pendingPath);
        fsyncPath(pendingManifestPath);

        linkSync(pendingManifestPath, manifestPath);
        manifestLinked = true;
        linkSync(pendingPath, finalPath);
        finalLinked = true;
        fsyncPath(backupRoot);
        unlinkSync(pendingPath);
        unlinkSync(pendingManifestPath);
        return Object.freeze({
            ...manifest,
            artifactPermissions: '0600',
            manifestPermissions: '0600',
        });
    } catch (error) {
        if (finalLinked) unlinkIfPresent(finalPath);
        if (manifestLinked) unlinkIfPresent(manifestPath);
        unlinkIfPresent(pendingPath);
        unlinkIfPresent(pendingManifestPath);
        throw error;
    }
}

const RETENTION_TERMINAL_STATES = Object.freeze({
    activations: new Set(['filled', 'cancelled', 'failed', 'missed']),
    order_intents: new Set(['terminal', 'cancelled_proven_unsent']),
    broker_orders: new Set(['filled', 'cancelled', 'failed', 'inactive']),
    pending_protection_commitments: new Set([
        'materialized',
        'zero_fill_terminal',
        'released_pre_dispatch',
        'released_manual',
    ]),
    protection_obligations: new Set([
        'fulfilled',
        'zero_fill_terminal',
        'released_manual',
    ]),
    entry_exposure_reservations: new Set(['consumed', 'released']),
    exit_claims: new Set(['consumed', 'released']),
    resolution_cases: new Set(['resolved']),
    safety_blockers: new Set(['resolved']),
});

function rowsHaveOnlyTerminalStates(table, rows) {
    const allowed = RETENTION_TERMINAL_STATES[table];
    if (!allowed) throw new Error(`retention state policy missing for ${table}`);
    return rows.every((row) => allowed.has(row.state));
}

const COMPACTABLE_TERMINAL_REPLAY_OPERATIONS = Object.freeze([
    'strategy_update_draft',
    'strategy_pause',
    'strategy_resume',
    'strategy_cancel',
]);

function compactTerminalRequestReplaysInTransaction(database, input) {
    const nowEpochMs = safeInteger(
        input.nowEpochMs,
        'requestReplayRetention.nowEpochMs',
    );
    const batchLimit = Math.min(
        safeInteger(
            input.batchLimit ?? 25,
            'requestReplayRetention.batchLimit',
            { minimum: 1 },
        ),
        100,
    );
    const operationPlaceholders = COMPACTABLE_TERMINAL_REPLAY_OPERATIONS.map(
        () => '?',
    ).join(',');
    const candidates = database
        .prepare(`
            SELECT request_id, operation_kind, payload_hash, result_hash,
                   result_status, result_json, updated_at_epoch_ms
              FROM request_replays
             WHERE state='completed'
               AND operation_kind IN (${operationPlaceholders})
             ORDER BY updated_at_epoch_ms, request_id
             LIMIT ?
        `)
        .all(...COMPACTABLE_TERMINAL_REPLAY_OPERATIONS, batchLimit);
    const compactedRequestIds = [];
    const retained = [];
    const selectStrategy = database.prepare(`
        SELECT state, terminal_at_epoch_ms, updated_at_epoch_ms
          FROM strategies WHERE strategy_id=?
    `);
    const selectLatestJournal = database.prepare(`
        SELECT MAX(created_at_epoch_ms) AS latest
          FROM event_journal
         WHERE entity_kind='request_replay' AND entity_id=?
    `);
    const deleteJournal = database.prepare(`
        DELETE FROM event_journal
         WHERE entity_kind='request_replay' AND entity_id=?
    `);
    const deleteReplay = database.prepare(`
        DELETE FROM request_replays
         WHERE request_id=? AND operation_kind=? AND payload_hash=?
           AND result_hash=? AND result_status=200 AND result_json=?
           AND state='completed' AND updated_at_epoch_ms=?
    `);

    for (const candidate of candidates) {
        const result = parseStoredCanonicalObject(
            candidate.result_json,
            'requestReplayRetention.result',
        );
        const strategyId = boundedToken(
            result.strategyId,
            'requestReplayRetention.strategyId',
        );
        const strategy = selectStrategy.get(strategyId);
        if (
            !strategy ||
            !STRATEGY_TERMINAL_STATES.has(strategy.state) ||
            strategy.terminal_at_epoch_ms === null
        ) {
            retained.push({
                requestId: candidate.request_id,
                reason: 'linked_strategy_not_safely_terminal',
            });
            continue;
        }
        if (historyTerminalBlockers(database, strategyId).length > 0) {
            retained.push({
                requestId: candidate.request_id,
                reason: 'linked_strategy_has_live_dependencies',
            });
            continue;
        }
        const latestJournalEpochMs = selectLatestJournal.get(
            candidate.request_id,
        )?.latest;
        const retentionBaseEpochMs = Math.max(
            safeInteger(
                candidate.updated_at_epoch_ms,
                'requestReplayRetention.updatedAtEpochMs',
            ),
            safeInteger(
                strategy.updated_at_epoch_ms,
                'requestReplayRetention.strategyUpdatedAtEpochMs',
            ),
            safeInteger(
                strategy.terminal_at_epoch_ms,
                'requestReplayRetention.strategyTerminalAtEpochMs',
            ),
            latestJournalEpochMs === null || latestJournalEpochMs === undefined
                ? 0
                : safeInteger(
                      latestJournalEpochMs,
                      'requestReplayRetention.latestJournalEpochMs',
                  ),
        );
        const eligibleAtEpochMs = addTaipeiCalendarYear(
            retentionBaseEpochMs,
        );
        if (nowEpochMs < eligibleAtEpochMs) {
            retained.push({
                requestId: candidate.request_id,
                reason: 'retention_period_active',
                eligibleAtEpochMs,
            });
            continue;
        }
        deleteJournal.run(candidate.request_id);
        const deleted = deleteReplay.run(
            candidate.request_id,
            candidate.operation_kind,
            candidate.payload_hash,
            candidate.result_hash,
            candidate.result_json,
            candidate.updated_at_epoch_ms,
        );
        if (Number(deleted.changes) !== 1) {
            throw new Error('request replay compaction lost its terminal CAS');
        }
        compactedRequestIds.push(candidate.request_id);
    }

    const protectedCounts = Object.fromEntries(
        database
            .prepare(`
                SELECT state, COUNT(*) AS count
                  FROM request_replays
                 WHERE state IN ('reserved','failed','outcome_unknown')
                 GROUP BY state
            `)
            .all()
            .map((row) => [row.state, Number(row.count)]),
    );
    return Object.freeze({
        schemaVersion: SMART_ORDER_REQUEST_REPLAY_RETENTION_SCHEMA_VERSION,
        policy:
            'terminal-linked-safe-action-plus-one-taipei-calendar-year-v1',
        batchLimit,
        scanned: candidates.length,
        compactedRequestIds: Object.freeze(compactedRequestIds),
        retained: Object.freeze(
            retained.map((entry) => Object.freeze(entry)),
        ),
        protectedCounts: Object.freeze({
            reserved: protectedCounts.reserved ?? 0,
            failed: protectedCounts.failed ?? 0,
            outcomeUnknown: protectedCounts.outcome_unknown ?? 0,
        }),
    });
}

function compactTerminalRequestReplays(database, input) {
    return transaction(database, () =>
        compactTerminalRequestReplaysInTransaction(database, input),
    );
}

function pendingCompactableReplayStrategyIds(database) {
    const operationPlaceholders = COMPACTABLE_TERMINAL_REPLAY_OPERATIONS.map(
        () => '?',
    ).join(',');
    const rows = database
        .prepare(`
            SELECT result_json FROM request_replays
             WHERE state='completed'
               AND operation_kind IN (${operationPlaceholders})
        `)
        .all(...COMPACTABLE_TERMINAL_REPLAY_OPERATIONS);
    return new Set(
        rows.map((row) =>
            boundedToken(
                parseStoredCanonicalObject(
                    row.result_json,
                    'requestReplayRetention.pendingResult',
                ).strategyId,
                'requestReplayRetention.pendingStrategyId',
            ),
        ),
    );
}

function purgeEligibleHistory(database, input) {
    const nowEpochMs = safeInteger(input.nowEpochMs, 'retention.nowEpochMs');
    const batchLimit = Math.min(
        safeInteger(input.batchLimit ?? 25, 'retention.batchLimit', { minimum: 1 }),
        100,
    );
    return transaction(database, () => {
        compactTerminalRequestReplaysInTransaction(database, {
            nowEpochMs,
            batchLimit,
        });
        const replayRetentionPendingStrategyIds =
            pendingCompactableReplayStrategyIds(database);
        const candidates = database
            .prepare(`
                SELECT strategy_id, terminal_at_epoch_ms, updated_at_epoch_ms
                  FROM strategies
                 WHERE state IN ('cancelled','completed','expired','failed')
                   AND terminal_at_epoch_ms IS NOT NULL
                 ORDER BY terminal_at_epoch_ms, strategy_id
                 LIMIT ?
            `)
            .all(batchLimit);
        const purgedStrategyIds = [];
        const retained = [];

        for (const strategy of candidates) {
            const strategyId = strategy.strategy_id;
            if (replayRetentionPendingStrategyIds.has(strategyId)) {
                retained.push({
                    strategyId,
                    reason: 'request_replay_retention_pending',
                });
                continue;
            }
            const activations = database
                .prepare(`
                    SELECT activation_id, state, updated_at_epoch_ms
                      FROM activations WHERE strategy_id=?
                `)
                .all(strategyId);
            const intents = database
                .prepare(`
                    SELECT intent_id, state, updated_at_epoch_ms, terminal_at_epoch_ms
                      FROM order_intents WHERE strategy_id=?
                `)
                .all(strategyId);
            const intentIds = intents.map((row) => row.intent_id);
            const selectForIntents = (sql) => {
                if (intentIds.length === 0) return [];
                return database
                    .prepare(sql.replace('__IDS__', intentIds.map(() => '?').join(',')))
                    .all(...intentIds);
            };
            const brokerOrders = selectForIntents(`
                SELECT broker_order_id, state, updated_at_epoch_ms, terminal_at_epoch_ms
                  FROM broker_orders WHERE intent_id IN (__IDS__)
            `);
            const correlations = selectForIntents(`
                SELECT correlation_id, created_at_epoch_ms
                  FROM broker_correlations WHERE intent_id IN (__IDS__)
            `);
            const commitments = database
                .prepare(`
                    SELECT commitment_id, state, updated_at_epoch_ms
                      FROM pending_protection_commitments WHERE strategy_id=?
                `)
                .all(strategyId);
            const obligations = database
                .prepare(`
                    SELECT obligation_id, state, updated_at_epoch_ms,
                           terminal_at_epoch_ms
                      FROM protection_obligations WHERE strategy_id=?
                `)
                .all(strategyId);
            const reservations = database
                .prepare(`
                    SELECT reservation_id, state, updated_at_epoch_ms,
                           terminal_at_epoch_ms
                      FROM entry_exposure_reservations WHERE strategy_id=?
                `)
                .all(strategyId);
            const obligationIds = obligations.map((row) => row.obligation_id);
            const exitClaims =
                obligationIds.length === 0
                    ? []
                    : database
                          .prepare(`
                              SELECT exit_claim_id, state, updated_at_epoch_ms,
                                     terminal_at_epoch_ms
                                FROM exit_claims
                               WHERE obligation_id IN (${obligationIds
                                   .map(() => '?')
                                   .join(',')})
                          `)
                          .all(...obligationIds);
            const observations = database
                .prepare(`
                    SELECT observation_id, created_at_epoch_ms
                      FROM observations WHERE strategy_id=?
                `)
                .all(strategyId);
            const resolutionCases = database
                .prepare(`
                    SELECT resolution_case_id, state, updated_at_epoch_ms,
                           terminal_at_epoch_ms
                      FROM resolution_cases WHERE strategy_id=?
                `)
                .all(strategyId);
            const resolutionCaseIds = resolutionCases.map(
                (row) => row.resolution_case_id,
            );
            const safetyBlockers =
                resolutionCaseIds.length === 0
                    ? []
                    : database
                          .prepare(`
                              SELECT blocker_id, state, created_at_epoch_ms,
                                     resolved_at_epoch_ms
                                FROM safety_blockers
                               WHERE resolution_case_id IN (${resolutionCaseIds
                                   .map(() => '?')
                                   .join(',')})
                          `)
                          .all(...resolutionCaseIds);

            const lifecycleTables = [
                ['activations', activations],
                ['order_intents', intents],
                ['broker_orders', brokerOrders],
                ['pending_protection_commitments', commitments],
                ['protection_obligations', obligations],
                ['entry_exposure_reservations', reservations],
                ['exit_claims', exitClaims],
                ['resolution_cases', resolutionCases],
                ['safety_blockers', safetyBlockers],
            ];
            const nonTerminalTable = lifecycleTables.find(
                ([table, rows]) => !rowsHaveOnlyTerminalStates(table, rows),
            )?.[0];
            if (nonTerminalTable) {
                retained.push({ strategyId, reason: `live_${nonTerminalTable}` });
                continue;
            }

            const journalEntities = [
                ['strategy', strategyId],
                ...activations.map((row) => ['activation', row.activation_id]),
                ...intents.map((row) => ['order_intent', row.intent_id]),
                ...brokerOrders.map((row) => ['broker_order', row.broker_order_id]),
                ...correlations.map((row) => [
                    'broker_correlation',
                    row.correlation_id,
                ]),
                ...commitments.map((row) => [
                    'pending_protection_commitment',
                    row.commitment_id,
                ]),
                ...obligations.map((row) => [
                    'protection_obligation',
                    row.obligation_id,
                ]),
                ...reservations.map((row) => [
                    'entry_exposure_reservation',
                    row.reservation_id,
                ]),
                ...exitClaims.map((row) => ['exit_claim', row.exit_claim_id]),
                ...observations.map((row) => ['observation', row.observation_id]),
                ...resolutionCases.map((row) => [
                    'resolution_case',
                    row.resolution_case_id,
                ]),
                ...safetyBlockers.map((row) => [
                    'safety_blocker',
                    row.blocker_id,
                ]),
            ];
            const timestampCandidates = [
                strategy.terminal_at_epoch_ms,
                strategy.updated_at_epoch_ms,
                ...activations.map((row) => row.updated_at_epoch_ms),
                ...intents.flatMap((row) => [
                    row.updated_at_epoch_ms,
                    row.terminal_at_epoch_ms,
                ]),
                ...brokerOrders.flatMap((row) => [
                    row.updated_at_epoch_ms,
                    row.terminal_at_epoch_ms,
                ]),
                ...correlations.map((row) => row.created_at_epoch_ms),
                ...commitments.map((row) => row.updated_at_epoch_ms),
                ...obligations.flatMap((row) => [
                    row.updated_at_epoch_ms,
                    row.terminal_at_epoch_ms,
                ]),
                ...reservations.flatMap((row) => [
                    row.updated_at_epoch_ms,
                    row.terminal_at_epoch_ms,
                ]),
                ...exitClaims.flatMap((row) => [
                    row.updated_at_epoch_ms,
                    row.terminal_at_epoch_ms,
                ]),
                ...observations.map((row) => row.created_at_epoch_ms),
                ...resolutionCases.flatMap((row) => [
                    row.updated_at_epoch_ms,
                    row.terminal_at_epoch_ms,
                ]),
                ...safetyBlockers.flatMap((row) => [
                    row.created_at_epoch_ms,
                    row.resolved_at_epoch_ms,
                ]),
            ].filter((value) => value !== null && value !== undefined);
            const journalSelect = database.prepare(`
                SELECT MAX(created_at_epoch_ms) AS latest
                  FROM event_journal WHERE entity_kind=? AND entity_id=?
            `);
            for (const [entityKind, entityId] of journalEntities) {
                const latest = journalSelect.get(entityKind, entityId)?.latest;
                if (latest !== null && latest !== undefined) {
                    timestampCandidates.push(latest);
                }
            }
            const retentionBaseEpochMs = Math.max(...timestampCandidates);
            const eligibleAtEpochMs = addTaipeiCalendarYear(retentionBaseEpochMs);
            if (nowEpochMs < eligibleAtEpochMs) {
                retained.push({
                    strategyId,
                    reason: 'retention_period_active',
                    eligibleAtEpochMs,
                });
                continue;
            }

            const deleteJournal = database.prepare(`
                DELETE FROM event_journal WHERE entity_kind=? AND entity_id=?
            `);
            for (const [entityKind, entityId] of journalEntities) {
                deleteJournal.run(entityKind, entityId);
            }
            if (resolutionCaseIds.length > 0) {
                database
                    .prepare(`DELETE FROM relinquished_unknown_exposures WHERE resolution_case_id IN (${resolutionCaseIds.map(() => '?').join(',')})`)
                    .run(...resolutionCaseIds);
                database
                    .prepare(`DELETE FROM safety_blockers WHERE resolution_case_id IN (${resolutionCaseIds.map(() => '?').join(',')})`)
                    .run(...resolutionCaseIds);
            }
            database
                .prepare('DELETE FROM resolution_cases WHERE strategy_id=?')
                .run(strategyId);
            if (obligationIds.length > 0) {
                database
                    .prepare(`DELETE FROM exit_claims WHERE obligation_id IN (${obligationIds.map(() => '?').join(',')})`)
                    .run(...obligationIds);
            }
            if (intentIds.length > 0) {
                for (const intentId of intentIds) {
                    deleteRepositoryMeta(
                        database,
                        dispatchArbiterGrantMetaKey(intentId),
                    );
                }
                database
                    .prepare(`DELETE FROM broker_correlation_identifiers WHERE intent_id IN (${intentIds.map(() => '?').join(',')})`)
                    .run(...intentIds);
                database
                    .prepare(`DELETE FROM broker_correlations WHERE intent_id IN (${intentIds.map(() => '?').join(',')})`)
                    .run(...intentIds);
                database
                    .prepare(`DELETE FROM broker_orders WHERE intent_id IN (${intentIds.map(() => '?').join(',')})`)
                    .run(...intentIds);
                database
                    .prepare(`DELETE FROM intent_rearm_authorizations WHERE intent_id IN (${intentIds.map(() => '?').join(',')})`)
                    .run(...intentIds);
            }
            database
                .prepare('DELETE FROM entry_exposure_reservations WHERE strategy_id=?')
                .run(strategyId);
            database
                .prepare('DELETE FROM protection_obligations WHERE strategy_id=?')
                .run(strategyId);
            database
                .prepare('DELETE FROM pending_protection_commitments WHERE strategy_id=?')
                .run(strategyId);
            database
                .prepare('DELETE FROM observations WHERE strategy_id=?')
                .run(strategyId);
            database
                .prepare('DELETE FROM order_intents WHERE strategy_id=?')
                .run(strategyId);
            database
                .prepare('DELETE FROM activations WHERE strategy_id=?')
                .run(strategyId);
            database.prepare('DELETE FROM strategies WHERE strategy_id=?').run(strategyId);
            purgedStrategyIds.push(strategyId);
        }
        const externalExitClaimCandidates = database
            .prepare(`
                SELECT exit_claim_id, state, evidence_hash,
                       terminal_at_epoch_ms, updated_at_epoch_ms
                  FROM exit_claims
                 WHERE external_lineage=1 AND obligation_id IS NULL
                   AND state IN ('consumed','released')
                   AND terminal_at_epoch_ms IS NOT NULL
                 ORDER BY terminal_at_epoch_ms, exit_claim_id
                 LIMIT ?
            `)
            .all(batchLimit);
        const purgedExternalExitClaimIds = [];
        const retainedExternalExitClaims = [];
        const latestExternalClaimEvidence = database.prepare(`
            SELECT MAX(created_at_epoch_ms) AS latest
              FROM event_journal
             WHERE entity_kind='exit_claim' AND entity_id=?
        `);
        const deleteExternalClaimJournal = database.prepare(`
            DELETE FROM event_journal
             WHERE entity_kind='exit_claim' AND entity_id=?
        `);
        const deleteExternalClaim = database.prepare(`
            DELETE FROM exit_claims
             WHERE exit_claim_id=? AND external_lineage=1
               AND obligation_id IS NULL AND state IN ('consumed','released')
               AND terminal_at_epoch_ms IS NOT NULL
        `);
        for (const claim of externalExitClaimCandidates) {
            const latestJournalEpochMs = latestExternalClaimEvidence.get(
                claim.exit_claim_id,
            )?.latest;
            const retentionBaseEpochMs = Math.max(
                claim.terminal_at_epoch_ms,
                claim.updated_at_epoch_ms,
                latestJournalEpochMs ?? 0,
            );
            const eligibleAtEpochMs = addTaipeiCalendarYear(
                retentionBaseEpochMs,
            );
            if (nowEpochMs < eligibleAtEpochMs) {
                retainedExternalExitClaims.push({
                    exitClaimId: claim.exit_claim_id,
                    reason: 'retention_period_active',
                    eligibleAtEpochMs,
                });
                continue;
            }
            deleteExternalClaimJournal.run(claim.exit_claim_id);
            const deleted = deleteExternalClaim.run(claim.exit_claim_id);
            if (Number(deleted.changes) !== 1) {
                throw new Error(
                    'external exit claim purge lost its terminal predicate',
                );
            }
            purgedExternalExitClaimIds.push(claim.exit_claim_id);
        }
        return Object.freeze({
            purgedStrategyIds: Object.freeze(purgedStrategyIds),
            retained: Object.freeze(retained.map((entry) => Object.freeze(entry))),
            purgedExternalExitClaimIds: Object.freeze(
                purgedExternalExitClaimIds,
            ),
            retainedExternalExitClaims: Object.freeze(
                retainedExternalExitClaims.map((entry) => Object.freeze(entry)),
            ),
            calendarTimeZone: 'Asia/Taipei',
            policy: 'later-terminal-release-or-evidence-plus-one-calendar-year',
        });
    });
}

function status(database) {
    verifyRepository(database);
    const counts = {};
    for (const table of REQUIRED_SMART_ORDER_TABLES) {
        counts[table] = database.prepare(`SELECT COUNT(*) AS count FROM ${table}`).get()
            ?.count;
    }
    const eventJournalRows = Number(counts.event_journal);
    return {
        schemaId: SMART_ORDER_REPOSITORY_SCHEMA_ID,
        schemaVersion: SMART_ORDER_REPOSITORY_SCHEMA_VERSION,
        integrity: 'ok',
        journalMode: database.prepare('PRAGMA journal_mode').get()?.journal_mode,
        synchronous: database.prepare('PRAGMA synchronous').get()?.synchronous,
        foreignKeys: database.prepare('PRAGMA foreign_keys').get()?.foreign_keys,
        busyTimeoutMs: database.prepare('PRAGMA busy_timeout').get()?.timeout,
        trustedSchema: database.prepare('PRAGMA trusted_schema').get()?.trusted_schema,
        eventJournalMaxRows: configuredEventJournalMaxRows,
        eventJournalCapacityRemaining: Math.max(
            0,
            configuredEventJournalMaxRows - eventJournalRows,
        ),
        requestReplayMaxRows: configuredRequestReplayMaxRows,
        requestReplayCapacityRemaining: Math.max(
            0,
            configuredRequestReplayMaxRows - Number(counts.request_replays),
        ),
        strategyMaxRows: configuredStrategyMaxRows,
        draftStrategyMaxRows: configuredDraftStrategyMaxRows,
        tradingSenderAuthority:
            repositoryMetaValue(database, TRADING_SENDER_AUTHORITY_META_KEY) ??
            NO_TRADING_SENDER_AUTHORITY,
        legacyTradingTriggerAuthority: 'permanently_retired',
        killSwitch: killSwitchProjection(currentKillSwitchArbiter(database)),
        counts,
    };
}

function lifecycleProjection(database, { verify = true } = {}) {
    if (verify) verifyRepository(database);
    const raw = database
        .prepare(`
            SELECT
              (SELECT COUNT(*) FROM strategies
                WHERE state NOT IN ('completed','cancelled','expired'))
                AS non_terminal_strategies,
              (SELECT COUNT(*) FROM strategies
                WHERE state NOT IN ('completed','cancelled','expired','paused'))
                AS non_quiesced_strategies,
              (SELECT COUNT(*) FROM activations
                WHERE state NOT IN ('filled','cancelled','failed','missed'))
                AS non_terminal_activations,
              (SELECT COUNT(*) FROM order_intents
                WHERE state NOT IN ('terminal','cancelled_proven_unsent'))
                AS non_terminal_intents,
              (SELECT COUNT(*) FROM order_intents
                WHERE state IN ('dispatching','acknowledged','reconciling','unknown')
                   OR (state='prepared' AND adapter_authority_granted=1))
                AS side_effect_intents,
              (SELECT COUNT(*) FROM order_intents
                WHERE state='prepared' AND adapter_authority_granted=0)
                AS proven_unsent_prepared_intents,
              (SELECT COUNT(*) FROM broker_orders
                WHERE state NOT IN ('filled','cancelled','failed','inactive'))
                AS non_terminal_broker_orders,
              (SELECT COUNT(*) FROM pending_protection_commitments
                WHERE state NOT IN ('materialized','zero_fill_terminal',
                                    'released_pre_dispatch','released_manual'))
                AS non_terminal_commitments,
              (SELECT COUNT(*) FROM protection_obligations
                WHERE state NOT IN ('fulfilled','zero_fill_terminal','released_manual'))
                AS active_protection_obligations,
              (SELECT COUNT(*) FROM entry_exposure_reservations
                WHERE state NOT IN ('consumed','released'))
                AS active_entry_reservations,
              (SELECT COUNT(*) FROM exit_claims
                WHERE state NOT IN ('consumed','released'))
                AS active_exit_claims,
              (SELECT COUNT(*) FROM exit_claims
                WHERE state='unknown') AS unknown_exit_claims,
              (SELECT COUNT(*) FROM resolution_cases
                WHERE state!='resolved') AS open_resolution_cases,
              (SELECT COUNT(*) FROM safety_blockers
                WHERE state='open') AS open_safety_blockers,
              (SELECT COUNT(*) FROM order_intents
                WHERE adapter_authority_granted=1) +
              (SELECT COUNT(*) FROM broker_orders) +
              (SELECT COUNT(*) FROM broker_correlations)
                AS durable_side_effect_history,
              (SELECT COUNT(*) FROM pending_protection_commitments) +
              (SELECT COUNT(*) FROM protection_obligations)
                AS durable_obligation_history,
              (SELECT COALESCE(SUM(quantity_shares), 0)
                 FROM entry_exposure_reservations
                WHERE state NOT IN ('consumed','released'))
                AS reserved_entry_shares,
              (SELECT COALESCE(SUM(quantity_shares), 0)
                 FROM exit_claims
                WHERE state NOT IN ('consumed','released'))
                AS claimed_exit_shares,
              (SELECT COALESCE(SUM(
                    CASE
                      WHEN filled_shares > confirmed_exited_shares
                      THEN filled_shares - confirmed_exited_shares
                      ELSE 0
                    END
                 ), 0)
                 FROM protection_obligations
                WHERE state NOT IN ('fulfilled','zero_fill_terminal','released_manual'))
                AS maximum_unprotected_remainder_shares,
              (SELECT COUNT(*) FROM runtime_epochs
                WHERE state IN ('starting','observe_only','reconciling','ready',
                                'quiescing')) AS active_runtime_epochs,
              (SELECT state FROM runtime_epochs
                WHERE runtime_epoch_id=(SELECT value FROM repository_meta
                  WHERE key='current_runtime_epoch_id')) AS current_runtime_state,
              (SELECT reconciliation_evidence_hash FROM runtime_epochs
                WHERE runtime_epoch_id=(SELECT value FROM repository_meta
                  WHERE key='current_runtime_epoch_id'))
                AS current_reconciliation_evidence_hash
        `)
        .get();
    const numericKeys = [
        'non_terminal_strategies',
        'non_quiesced_strategies',
        'non_terminal_activations',
        'non_terminal_intents',
        'side_effect_intents',
        'proven_unsent_prepared_intents',
        'non_terminal_broker_orders',
        'non_terminal_commitments',
        'active_protection_obligations',
        'active_entry_reservations',
        'active_exit_claims',
        'unknown_exit_claims',
        'open_resolution_cases',
        'open_safety_blockers',
        'durable_side_effect_history',
        'durable_obligation_history',
        'reserved_entry_shares',
        'claimed_exit_shares',
        'maximum_unprotected_remainder_shares',
        'active_runtime_epochs',
    ];
    const counts = {};
    for (const key of numericKeys) {
        const value = Number(raw?.[key]);
        if (!Number.isSafeInteger(value) || value < 0) {
            throw new Error('lifecycle audit count is invalid');
        }
        counts[key] = value;
    }
    const currentRuntimeState =
        typeof raw?.current_runtime_state === 'string'
            ? raw.current_runtime_state
            : 'absent';
    const currentReconciliationComplete =
        typeof raw?.current_reconciliation_evidence_hash === 'string' &&
        /^sha256:[0-9a-f]{64}$/.test(
            raw.current_reconciliation_evidence_hash,
        ) &&
        lifecycleReconciliationCoversCurrentSideEffects(database);
    const sideEffectCount =
        counts.side_effect_intents +
        counts.non_terminal_broker_orders +
        counts.non_terminal_commitments +
        counts.active_protection_obligations +
        counts.active_entry_reservations +
        counts.active_exit_claims +
        counts.open_resolution_cases +
        counts.open_safety_blockers;
    const drainBlockerCount =
        counts.non_terminal_strategies +
        counts.non_terminal_activations +
        counts.non_terminal_intents +
        counts.non_terminal_broker_orders +
        counts.non_terminal_commitments +
        counts.active_protection_obligations +
        counts.active_entry_reservations +
        counts.active_exit_claims +
        counts.open_resolution_cases +
        counts.open_safety_blockers;
    const currentClaimsRequireReconciliation = counts.active_exit_claims > 0;
    const neverAuthorizedAndNoHistory =
        counts.durable_side_effect_history === 0 &&
        counts.durable_obligation_history === 0;
    const reconciliationAllowsDrain =
        (['ready', 'observe_only', 'quiescing'].includes(currentRuntimeState) &&
            currentReconciliationComplete) ||
        neverAuthorizedAndNoHistory;
    const reconciliationBlockerCount = reconciliationAllowsDrain ? 0 : 1;
    counts.reconciliation_blockers = reconciliationBlockerCount;
    const productionReadonlyBlockerCount =
        counts.non_quiesced_strategies +
        counts.non_terminal_activations +
        counts.non_terminal_intents +
        counts.non_terminal_broker_orders +
        counts.non_terminal_commitments +
        counts.active_protection_obligations +
        counts.active_entry_reservations +
        counts.active_exit_claims +
        counts.open_resolution_cases +
        counts.open_safety_blockers +
        reconciliationBlockerCount;
    const gracefulStopBlockerCount =
        drainBlockerCount + reconciliationBlockerCount;
    const rawDrainRecords = database
        .prepare(`
            SELECT kind, state, quantity_shares, quantity_state, disposition
              FROM (
                SELECT 1 sort_group, strategy_id sort_id, 'strategy' kind,
                       state, NULL quantity_shares,
                       'not_applicable' quantity_state,
                       'pause_or_cancel_strategy' disposition
                  FROM strategies
                 WHERE state NOT IN ('completed','cancelled','expired')
                UNION ALL
                SELECT 2, activation_id, 'activation', state, NULL,
                       'not_applicable',
                       'cancel_strategy_or_complete_activation'
                  FROM activations
                 WHERE state NOT IN ('filled','cancelled','failed','missed')
                UNION ALL
                SELECT 3, intent_id, 'prepared_intent', 'prepared', NULL,
                       'not_applicable',
                       'cancel_proven_unsent_intent_and_release'
                  FROM order_intents
                 WHERE state='prepared' AND adapter_authority_granted=0
                UNION ALL
                SELECT 4, intent_id, 'side_effect_intent',
                       CASE
                         WHEN state='prepared' THEN 'prepared_authority_granted'
                         ELSE state
                       END,
                       NULL, 'not_applicable',
                       'reconcile_intent_before_stop'
                  FROM order_intents
                 WHERE state IN ('dispatching','acknowledged','reconciling','unknown')
                    OR (state='prepared' AND adapter_authority_granted=1)
                UNION ALL
                SELECT 5, broker_order_id, 'broker_order', state,
                       remaining_shares, 'conservative_maximum',
                       'cancel_working_order_or_reconcile'
                  FROM broker_orders
                 WHERE state NOT IN ('filled','cancelled','failed','inactive')
                UNION ALL
                SELECT 6, commitment_id, 'protection_commitment',
                       CASE
                         WHEN state IN ('pending_entry_fill') THEN state
                         ELSE 'unknown'
                       END,
                       MAX(0, committed_shares - materialized_shares),
                       'conservative_maximum',
                       'prove_zero_fill_or_release_pre_dispatch'
                  FROM pending_protection_commitments
                 WHERE state NOT IN ('materialized','zero_fill_terminal',
                                     'released_pre_dispatch','released_manual')
                UNION ALL
                SELECT 7, obligation_id, 'protection_obligation',
                       CASE
                         WHEN state IN ('pending_entry_fill','monitoring') THEN state
                         ELSE 'unknown'
                       END,
                       MAX(0, filled_shares - confirmed_exited_shares),
                       CASE
                         WHEN EXISTS (
                           SELECT 1 FROM exit_claims AS active_claims
                            WHERE active_claims.obligation_id =
                                  protection_obligations.obligation_id
                              AND active_claims.state NOT IN ('consumed','released')
                         ) THEN 'conservative_maximum'
                         ELSE 'exact'
                       END,
                       'prove_zero_fill_confirmed_exit_or_break_glass'
                  FROM protection_obligations
                 WHERE state NOT IN ('fulfilled','zero_fill_terminal','released_manual')
                UNION ALL
                SELECT 8, reservation_id, 'entry_exposure_reservation', state,
                       quantity_shares, 'exact',
                       'release_proven_unsent_or_reconcile'
                  FROM entry_exposure_reservations
                 WHERE state NOT IN ('consumed','released')
                UNION ALL
                SELECT 9, exit_claim_id, 'exit_claim', state, quantity_shares,
                       'exact',
                       'reconcile_or_release_claim'
                  FROM exit_claims
                 WHERE state NOT IN ('consumed','released')
                UNION ALL
                SELECT 10, resolution_case_id, 'manual_resolution',
                       CASE WHEN state='resolved' THEN state ELSE 'open' END,
                       NULL, 'not_applicable',
                       'complete_reason_specific_resolution'
                  FROM resolution_cases
                 WHERE state != 'resolved'
                UNION ALL
                SELECT 11, blocker_id, 'safety_blocker', state, NULL,
                       'not_applicable',
                       'resolve_or_supersede_blocker'
                  FROM safety_blockers
                 WHERE state = 'open'
              )
             ORDER BY sort_group, sort_id
             LIMIT ?
        `)
        .all(
            SMART_ORDER_LIFECYCLE_DRAIN_RECORD_MAX_ITEMS -
                reconciliationBlockerCount +
                1,
        );
    const drainRecordsTruncated =
        rawDrainRecords.length >
        SMART_ORDER_LIFECYCLE_DRAIN_RECORD_MAX_ITEMS -
            reconciliationBlockerCount;
    const entityDrainRecords = rawDrainRecords
        .slice(
            0,
            SMART_ORDER_LIFECYCLE_DRAIN_RECORD_MAX_ITEMS -
                reconciliationBlockerCount,
        )
        .map((record, index) => {
            const quantityShares =
                record.quantity_shares === null
                    ? null
                    : Number(record.quantity_shares);
            if (
                typeof record.kind !== 'string' ||
                typeof record.state !== 'string' ||
                !['not_applicable', 'exact', 'conservative_maximum'].includes(
                    record.quantity_state,
                ) ||
                typeof record.disposition !== 'string' ||
                (record.quantity_state === 'not_applicable'
                    ? quantityShares !== null
                    : !Number.isSafeInteger(quantityShares) ||
                      quantityShares < 0)
            ) {
                throw new Error('lifecycle drain record is invalid');
            }
            return Object.freeze({
                ordinal: index + 1 + reconciliationBlockerCount,
                kind: record.kind,
                state: record.state,
                quantityShares,
                quantityState: record.quantity_state,
                disposition: record.disposition,
            });
        });
    const drainRecords = Object.freeze([
        ...(reconciliationBlockerCount === 0
            ? []
            : [
                  Object.freeze({
                      ordinal: 1,
                      kind: 'account_reconciliation',
                      state: 'missing_or_stale',
                      quantityShares: null,
                      quantityState: 'not_applicable',
                      disposition: 'complete_current_account_reconciliation',
                  }),
              ]),
        ...entityDrainRecords,
    ]);
    if (
        !drainRecordsTruncated &&
        drainRecords.length !== gracefulStopBlockerCount
    ) {
        throw new Error('lifecycle drain record count is inconsistent');
    }
    return Object.freeze({
        schemaVersion: SMART_ORDER_LIFECYCLE_AUDIT_SCHEMA_VERSION,
        currentRuntimeState,
        writeMaster: 'disabled',
        reconciliation:
            currentRuntimeState === 'ready' &&
            currentReconciliationComplete &&
            sideEffectCount === 0
                ? 'current_no_side_effects'
                : 'required_before_any_write_or_drain',
        counts: Object.freeze({ ...counts }),
        runtimeTrackedUnprotectedRemainder: Object.freeze({
            state: currentClaimsRequireReconciliation ? 'unknown' : 'known',
            shares: currentClaimsRequireReconciliation
                ? null
                : counts.maximum_unprotected_remainder_shares,
            conservativeMaximumShares:
                counts.maximum_unprotected_remainder_shares,
            currentAccountReconciliationRequired:
                currentClaimsRequireReconciliation,
        }),
        productionReadonlyDrainAllowed:
            counts.non_quiesced_strategies === 0 &&
            counts.non_terminal_activations === 0 &&
            counts.non_terminal_intents === 0 &&
            sideEffectCount === 0 &&
            reconciliationAllowsDrain,
        gracefulStopAllowed:
            drainBlockerCount === 0 && reconciliationAllowsDrain,
        uninstallAllowed:
            drainBlockerCount === 0 && reconciliationAllowsDrain,
        productionReadonlyBlockerCount,
        gracefulStopBlockerCount,
        uninstallBlockerCount: gracefulStopBlockerCount,
        blockerCount: gracefulStopBlockerCount,
        drainRecords,
        drainRecordsTruncated,
        accountIdentifiersExposed: false,
        entityIdentifiersExposed: false,
        strategyDefinitionsExposed: false,
    });
}

function lifecycleAudit(database, input) {
    if (
        input === undefined ||
        input === null ||
        typeof input !== 'object' ||
        Array.isArray(input) ||
        Object.keys(input).length !== 0
    ) {
        throw new TypeError('lifecycle audit input must be an empty object');
    }
    return lifecycleProjection(database);
}

