let database;
try {
    validatePrivateDatabaseLocation();
    loadAuthenticatedIdentityKey();
    const repositoryExpectation = readRepositoryExpectation();
    prepareRepositoryArtifact(repositoryExpectation);
    hardenDatabaseFiles();
    database = new DatabaseSync(databasePath);
    hardenDatabaseFiles();
    configureDatabase(database, { foreignKeys: false });
    migrateDatabase(database, {
        allowFreshInitialize: repositoryExpectation.repositoryExpected === false,
    });
    initializeAuthenticatedIdentityKeyBinding(database);
    configureDatabase(database);
    // Fresh repositories and every supported legacy migration create the
    // arbiter metadata inside the same schema transaction.  A current-schema
    // repository must already contain both keys; recreating them here would
    // turn deletion/tampering into an unsafe all-disabled reset.
    currentKillSwitchArbiter(database);
    seedTestExposureArbiterHeads(database);
    seedTestExternalSellVisibilityHeads(database);
    if (testOnlyMaxPageCount !== undefined) {
        if (process.env.VITEST !== 'true') {
            throw new Error('test-only SQLite fault injection is unavailable');
        }
        database.exec(
            `PRAGMA max_page_count=${safeInteger(
                testOnlyMaxPageCount,
                'testOnlyMaxPageCount',
                { minimum: 1 },
            )}`,
        );
    }
    verifyRepository(database);
    hardenDatabaseFiles();
    publishRepositoryExpected(repositoryExpectation);
    parentPort.postMessage({ type: 'ready' });
} catch (error) {
    try {
        database?.close();
    } catch {
        // The startup fault remains authoritative.
    }
    database = undefined;
    identityKeyBytes?.fill(0);
    parentPort.postMessage({
        type: 'startup-error',
        error: { name: error?.name ?? 'Error', message: error?.message ?? String(error) },
    });
}

async function handleRepositoryMessage(message) {
    if (!database) return;
    const startedAt = performance.now();
    const queueAgeMs = Math.max(
        0,
        startedAt -
            (typeof message.enqueuedAtMonotonicMs === 'number'
                ? message.enqueuedAtMonotonicMs
                : startedAt),
    );
    parentPort.postMessage({
        type: 'started',
        id: message.id,
        queueAgeMs,
    });
    try {
        if (
            READINESS_GATED_METHODS.has(message.method) &&
            (!Number.isFinite(queueAgeLimitMs) ||
                queueAgeLimitMs <= 0 ||
                queueAgeMs > queueAgeLimitMs)
        ) {
            const error = new Error(
                'repository queue age blocks readiness-gated operation',
            );
            error.name = 'RepositoryWatchdogError';
            throw error;
        }
        if (message.method === 'close') {
            database.close();
            database = undefined;
            identityKeyBytes?.fill(0);
            parentPort.postMessage({
                id: message.id,
                ok: true,
                result: { closed: true },
                queueAgeMs,
                workerDurationMs: performance.now() - startedAt,
            });
            return;
        }
        const handler = handlers[message.method];
        if (!handler) throw new TypeError(`unknown repository method: ${message.method}`);
        assertLifecycleMutationFenceAllows(
            database,
            message.method,
            message.payload ?? {},
        );
        if (
            message.method === 'createRepositoryBackup' &&
            configuredBlockingBackupDelayMs > 0
        ) {
            Atomics.wait(
                new Int32Array(new SharedArrayBuffer(Int32Array.BYTES_PER_ELEMENT)),
                0,
                0,
                configuredBlockingBackupDelayMs,
            );
        }
        const result = await handler(database, message.payload ?? {});
        hardenDatabaseFiles();
        parentPort.postMessage({
            id: message.id,
            ok: true,
            result,
            queueAgeMs,
            workerDurationMs: performance.now() - startedAt,
        });
    } catch (error) {
        const fatalRepositoryError = isFatalRepositoryError(error);
        if (fatalRepositoryError) {
            try {
                database?.close();
            } catch {
                // The first persistence failure remains authoritative.
            }
            database = undefined;
            identityKeyBytes?.fill(0);
        }
        parentPort.postMessage({
            id: message.id,
            ok: false,
            error: { name: error?.name ?? 'Error', message: error?.message ?? String(error) },
            fatalRepositoryError,
            queueAgeMs,
            workerDurationMs: performance.now() - startedAt,
        });
    }
}

let operationQueue = Promise.resolve();
parentPort.on('message', (message) => {
    operationQueue = operationQueue.then(
        () => handleRepositoryMessage(message),
        () => handleRepositoryMessage(message),
    );
});
